CREATE PROCEDURE [dbo].[sp_I_Shift_To_Go]
  (@ent_id int ,
   @start_time datetime ,
   @end_time datetime ,
   @shift_id int ,
   @break1_start datetime ,
   @break1_end datetime ,
   @break2_start datetime ,
   @break2_end datetime ,
   @break3_start datetime ,
   @break3_end datetime ,
   @time_zone_bias_value INT32 = NULL)
AS
-- ***********************************************************************************************************************
-- Module Name	      -
-- Description	      -
-- Author	      -
-- Date Created	      -	10/21/2002
-- Version	      - 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified  Modified_By      Changes
--10/10/2005	Raghu		3.1.0	HD# 5678, Part of DB Changes
--06/24/2008    Raghu       3.5     CR# 75765, Sidus 2 Broadway Task ID: (3130,3131,3133) Change shifts to use local time instead of GMT.
--11/11/2009	Eswar       4.0     HF 1432 - datetime changes.
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

/*SET @start_time = DATEADD(mi, -@time_zone_bias_value, @start_time)
SET @end_time = DATEADD(mi, -@time_zone_bias_value, @end_time)
SET @break1_start = DATEADD(mi, -@time_zone_bias_value, @break1_start)
SET @break1_end = DATEADD(mi, -@time_zone_bias_value, @break1_end)
SET @break2_start = DATEADD(mi, -@time_zone_bias_value, @break2_start)
SET @break2_end = DATEADD(mi, -@time_zone_bias_value, @break2_end)
SET @break3_start = DATEADD(mi, -@time_zone_bias_value, @break3_start)
SET @break3_end = DATEADD(mi, -@time_zone_bias_value, @break3_end)
*/
INSERT INTO shift_to_go
 (ent_id,
  start_time,
  end_time,
  shift_id,
  break1_start,
  break1_end,
  break2_start,
  break2_end,
  break3_start,
  break3_end)
VALUES
  (@ent_id,
   @start_time,
   @end_time,
   @shift_id,
   @break1_start,
   @break1_end,
   @break2_start,
   @break2_end,
   @break3_start,
   @break3_end)

CREATE PROCEDURE [dbo].[sp_U_Sample]
  (@sample_id int ,
   @sample_name nvarchar(254) ,
   @ent_id int,
   @item_id nvarchar(80) ,
   @wo_id nvarchar(80) ,
   @oper_id nvarchar(80) ,
   @seq_no int,
   @context_ent_id int,
   @context_item_id nvarchar(80),
   @item_category_id int,
   @process_id nvarchar(80),
   @context_oper_id nvarchar(80),
   @freq_id int,
   @plan_id int = NULL,
   @segment_requirement_id nvarchar(254) ,
   @segment_response_id nvarchar(254) ,
   @lot_no nvarchar(80) ,
   @sublot_no nvarchar(80) ,
   @requested_time_local datetime,
   @requested_time_tz INT32 = NULL,
   @expiry_time_local datetime,
   @expiry_time_tz INT32 = NULL,
   @warning_time_local datetime,
   @warning_time_tz INT32 = NULL,
   @pulled_by nvarchar(80),
   @pulled_time_local datetime,
   @pulled_time_tz INT32 = NULL,
   @final bit,
   @finalized_by nvarchar(80),
   @finalized_at_local datetime,
   @finalized_at_tz INT32 = NULL,
   @verified_by nvarchar(80),
   @sample_status int,
   @sample_result int,
   @spare1 nvarchar(80) ,
   @spare2 nvarchar(80) ,
   @spare3 nvarchar(80) ,
   @spare4 nvarchar(80) ,
   @priority int=NULL,
   @last_edit_comment nvarchar(254) ,
   @last_edit_at DATETIME,
   @time_zone_bias_value INT32 = NULL)
AS
-- ***********************************************************************************************************************
-- Module Name       -  Sp_U_Sample
-- Description       -  Update a sample record
-- Author         -  Sara Reynolds
-- Date Created         -  02/02/2011
-- Version        -
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified  Modified_By      Changes
----------------------------------------------------------------------------------------------------------------------------
-- 6/7/2011       Johnny Agsalog    Added priority column
-- *************************************************************************************************************************
SET NOCOUNT ON

DECLARE  @requested_time_utc TDATETIME,
       @expiry_time_utc TDATETIME,
       @pulled_time_utc TDATETIME,
       @finalized_at_utc TDATETIME,
         @warning_time_utc TDATETIME,
         @tz_temp    INT32

BEGIN
    EXEC sp_TZ_GetDateInfo NULL, @requested_time_utc OUTPUT, @requested_time_local OUTPUT, @time_zone_bias_value OUTPUT

   SET @requested_time_tz = dbo.fn_TZ_ValidateOffset(@requested_time_tz)
   SET @requested_time_local = dbo.fn_TZ_ValidateLocalDate(@requested_time_local, @requested_time_tz)

   SET @expiry_time_tz = dbo.fn_TZ_ValidateOffset(@expiry_time_tz)
   SET @expiry_time_local = dbo.fn_TZ_ValidateLocalDate(@expiry_time_local, @expiry_time_tz)

   SET @warning_time_tz = dbo.fn_TZ_ValidateOffset(@warning_time_tz)
   SET @warning_time_local = dbo.fn_TZ_ValidateLocalDate(@warning_time_local, @warning_time_tz)

   SET @pulled_time_tz = dbo.fn_TZ_ValidateOffset(@pulled_time_tz)
   SET @pulled_time_local = dbo.fn_TZ_ValidateLocalDate(@pulled_time_local, @pulled_time_tz)

   SET @finalized_at_tz = dbo.fn_TZ_ValidateOffset(@finalized_at_tz)
   SET @finalized_at_local = dbo.fn_TZ_ValidateLocalDate(@finalized_at_local, @finalized_at_tz)

   SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

   SET @tz_temp = -@requested_time_tz
   EXEC sp_S_GetUtcDate @requested_time_local, @tz_temp, @requested_time_utc OUTPUT

   SET @tz_temp = -@expiry_time_tz
   EXEC sp_S_GetUtcDate @expiry_time_local, @tz_temp, @expiry_time_utc OUTPUT

   SET @tz_temp = -@warning_time_tz
   EXEC sp_S_GetUtcDate @warning_time_local, @tz_temp, @warning_time_utc OUTPUT

   SET @tz_temp = -@pulled_time_tz
   EXEC sp_S_GetUtcDate @pulled_time_local, @tz_temp, @pulled_time_utc OUTPUT

   SET @tz_temp = -@finalized_at_tz
   EXEC sp_S_GetUtcDate @finalized_at_local, @tz_temp, @finalized_at_utc OUTPUT

    IF @final IS NULL SET @final = 0

   UPDATE sample
   SET sample_name = @sample_name,
     ent_id = @ent_id,
     item_id = @item_id,
     wo_id = @wo_id,
     oper_id = @oper_id,
     seq_no = @seq_no,
     context_ent_id = @context_ent_id,
     context_item_id = @context_item_id,
     item_category_id = @item_category_id,
     process_id = @process_id,
     context_oper_id = @context_oper_id,
     freq_id = @freq_id,
     plan_id = @plan_id,
     segment_requirement_id = @segment_requirement_id,
     segment_response_id = @segment_response_id,
     lot_no = @lot_no,
     sublot_no = @sublot_no,
     requested_time_utc = @requested_time_utc,
     requested_time_local = @requested_time_local,
     expiry_time_utc = @expiry_time_utc,
     expiry_time_local = @expiry_time_local,
     warning_time_utc = @warning_time_utc,
      warning_time_local = @warning_time_local,
      pulled_by = @pulled_by,
     pulled_time_utc = @pulled_time_utc,
     pulled_time_local = @pulled_time_local,
     final = @final,
     finalized_by = @finalized_by,
     finalized_at_utc = @finalized_at_utc,
     finalized_at_local = @finalized_at_local,
     verified_by = @verified_by,
     sample_status = @sample_status,
     sample_result = @sample_result,
     spare1 = @spare1,
     spare2 = @spare2,
     spare3 = @spare3,
     spare4 = @spare4,
     priority = @priority,
     last_edit_comment = @last_edit_comment
   WHERE    (sample_id = @sample_id)
      AND (last_edit_at = @last_edit_at)

END

