CREATE PROCEDURE [dbo].[sp_I_Shipment]
(
	@cust_id nvarchar(40) ,
	@po_id nvarchar(40) ,
	@so_line_no int ,
	--@ship_date datetime ,
	@ship_date_local datetime, -- Added 08/02/2007 AML
	@ship_via nvarchar(80) ,
	@ship_by nvarchar(40) ,
	@ship_from int ,
	@spare1 nvarchar(80) ,
	@spare2 nvarchar(80) ,
	@spare3 nvarchar(80) ,
	@spare4 nvarchar(80) ,
	@last_edit_comment nvarchar(254) ,
	@time_zone_bias_value INT32 = 0,
	@mod_id varchar(30) OUT
)

AS
-- ***********************************************************************************************************************
-- Module Name				-
-- Description				-
-- Author					-
-- Date Created				- 10/21/2002
-- Version					- 1.6.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By     Ver		Changes
-- 12/04/2002		Raghu			1.5.0	Mod Id Changes (Datetime to Money type)
-- 06/06/2003		Sheetal Jain	1.6.0	Oracle migration changes - SET @<variable> = (SELECT ...)
-- 10/11/2005		Raghu			3.1.0	HD# 5678, Part of DB Changes
-- 01/18/2007		KRF				3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 08/02/2007		AML				3.3.0	DB Changes
-- 10/24/2007		AML				3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--											dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @last_edit_by	NVARCHAR(40)
	,	@last_edit_at	DATETIME
-- Added 08/02/2007 AML
	,	@ship_date_utc	DATETIME
	,	@tz_temp		INT

SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)
SET @tz_temp = -@time_zone_bias_value
--

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

-- IF @ship_date IS null SET  @ship_date = @last_edit_at
--SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)
--IF @ship_date IS NOT NULL SET @ship_date = DATEADD(mi, -@time_zone_bias_value, @ship_date)

EXEC sp_S_GetUtcDate @ship_date_local, @tz_temp, @ship_date_utc OUTPUT	-- Added 08/02/2007 AML

INSERT INTO shipment
(
	cust_id,
	po_id,
	so_line_no,
	--ship_date,
	ship_date_utc,		-- Added 08/02/2007 AML
	ship_date_local,	-- Added 08/02/2007 AML
	ship_via,
	ship_by,
	ship_from,
	spare1,
	spare2,
	spare3,
	spare4,
	last_edit_comment,
	last_edit_by,
	last_edit_at
)
VALUES
(
	@cust_id,
	@po_id,
	@so_line_no,
	--@ship_date,
	@ship_date_utc,		-- Added 08/02/2007 AML
	@ship_date_local,	-- Added 08/02/2007 AML
	@ship_via,
	@ship_by,
	@ship_from,
	@spare1,
	@spare2,
	@spare3,
	@spare4,
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at
)

-- Return timestamp
--SET @mod_id = (SELECT CONVERT(varchar(30), CONVERT(DATETIME, mod_id), 13)
SELECT @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
FROM shipment
WHERE	cust_id = @cust_id AND
		po_id = @po_id AND
		so_line_no = @so_line_no AND
		--ship_date = @ship_date
		ship_date_local = @ship_date_local AND	-- Added 08/02/2007 AML
		ship_date_utc = @ship_date_utc			-- Added 08/02/2007 AML

CREATE PROCEDURE [dbo].[sp_I_Job_Bom]
  (@wo_id nvarchar(40) ,
   @oper_id nvarchar(40) ,
   @seq_no int ,
   @bom_pos int ,
   @item_id nvarchar(40) ,
   @reqd_grade_cd int ,
   @instruction nvarchar(2000) ,
   @qty_per_parent_item float ,
   @max_qty_per_parent_item float,
   @min_qty_per_parent_item float,
   @reqd_start_val float ,
   @reqd_start_val_is_pct bit ,
   @update_inv bit ,
   @backflush bit ,
   @def_reas_cd int ,
   @def_lot_no nvarchar(40) ,
   @def_sublot_no nvarchar(40) ,
   @def_storage_ent_id int ,
   @def_reject_ent_id int ,
   @scaling_factor float ,
   @must_consume_from_inv bit,
   @may_choose_alt_inv_loc bit,
   @may_create_new_lots bit,
   @must_consume_from_wip bit,
   @must_consume_before_prod bit,
   @constant_qty bit,
   @est_time float,
   @current_subst int,
   @qty_reqd float,
   @serial_no_source bit,
   @spare1 nvarchar(1000) ,
   @spare2 nvarchar(1000) ,
   @spare3 nvarchar(1000) ,
   @spare4 nvarchar(1000) ,
   @last_edit_comment nvarchar(254) ,
   @mod_id varchar(30) OUT)
AS
-- ***********************************************************************************************************************
-- Module Name	      -
-- Description	      -
-- Author	      -
-- Date Created	      - 10/21/2002
-- Version	      - 1.6.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Modified_By	Ver.	Changes
-- 10/21/2002	Tony	        1.5.0	Include constant_qty field
-- 12/04/2002	Raghu		1.5.0	Mod Id Changes (Datetime to Money type)
-- 06-06-2003	Sheetal Jain	1600	Oracle migration changes - SET @<variable> = (SELECT ...)
-- 01/13/2004	Sheetal Jain 	1.6.0.41	(HD #4284) Creating a Job (not from process) bom_pos zero not created
-- 09/19/2005	Raghu		3.1.0	Part of DB Changes
-- 01/12/2007	KRF		3.2.1	HD# 8314 & 9232, part of DB changes - added @def_sublot_no and @serial_no_source arguments
-- 01/18/2007	KRF		3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 10/24/2007	AML			3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--									dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET NOCOUNT ON
BEGIN
DECLARE  @last_edit_by	NVARCHAR(40)
	     ,@last_edit_at	DATETIME

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

 IF @reqd_start_val IS NULL SET @reqd_start_val = 0
 IF @reqd_start_val_is_pct IS NULL SET @reqd_start_val_is_pct = 0
 IF @update_inv IS NULL SET @update_inv = 0
 IF @backflush IS NULL SET @backflush = 0
 IF @must_consume_from_inv IS NULL SET @must_consume_from_inv = 0
 IF @may_choose_alt_inv_loc IS NULL SET @may_choose_alt_inv_loc = 1
 IF @may_create_new_lots IS NULL SET @may_create_new_lots = 1
 IF @constant_qty IS NULL SET @constant_qty = 0
 IF @serial_no_source IS NULL SET @serial_no_source = 0 -- Added 1/12/07 KRF

 INSERT INTO job_bom
 (wo_id,
  oper_id,
  seq_no,
  bom_pos,
  item_id,
  reqd_grade_cd,
  instruction,
  qty_per_parent_item,
  max_qty_per_parent_item,
  min_qty_per_parent_item,
  reqd_start_val,
  reqd_start_val_is_pct,
  update_inv,
  backflush,
  def_reas_cd,
  def_lot_no,
  def_sublot_no, -- Added 1/12/07 KRF
  def_storage_ent_id,
  def_reject_ent_id,
  scaling_factor,
  must_consume_from_inv,
  may_choose_alt_inv_loc,
  may_create_new_lots,
  must_consume_from_wip,
  must_consume_before_prod,
  constant_qty,
  est_time,
  current_subst,
  qty_reqd,
  serial_no_source, -- Added 1/12/07 KRF
  spare1,
  spare2,
  spare3,
  spare4,
  last_edit_comment,
  last_edit_by,
  last_edit_at)
VALUES
  (@wo_id,
   @oper_id,
   @seq_no,
   @bom_pos,
   @item_id,
   @reqd_grade_cd,
   @instruction,
   @qty_per_parent_item,
   @max_qty_per_parent_item,
   @min_qty_per_parent_item,
   @reqd_start_val,
   @reqd_start_val_is_pct,
   @update_inv,
   @backflush,
   @def_reas_cd,
   @def_lot_no,
   @def_sublot_no, -- Added 1/12/07 KRF
   @def_storage_ent_id,
   @def_reject_ent_id,
   @scaling_factor,
   @must_consume_from_inv,
   @may_choose_alt_inv_loc,
   @may_create_new_lots,
   @must_consume_from_wip,
   @must_consume_before_prod,
   @constant_qty,
   @est_time,
   @current_subst,
   @qty_reqd,
   @serial_no_source, -- Added 1/12/07 KRF
   @spare1,
   @spare2,
   @spare3,
   @spare4,
   @last_edit_comment,
   @last_edit_by,
   @last_edit_at)

-- Return timestamp
--SET @mod_id = (SELECT CONVERT(varchar(30), CONVERT(DATETIME, mod_id), 13)
SELECT @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
FROM job_bom
WHERE (wo_id = @wo_id AND
oper_id = @oper_id AND
seq_no = @seq_no AND
bom_pos = @bom_pos)
END

--===========================================================================================
-- Name:		[sp_U_ofi_SULowSignal]
-- Description:Storage Unit Low Level Signal Update

-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	 AJEET         	  2022-09-14		Intial Version
-- 0.01.01	 YG				  2024-02-09		Update Script Body Comment and Missing No Lock
-- 0.02.00	 YG				  2024-03-12		Added Good Consumption (Item Reason), Validation for non running job, Ensure qty_left has value for empty inventory  
-- 0.03.00	 YG			      2024-03-21		Update logic how to get latest consumption and disable scrap logic
--
-- Exec sp_U_ofi_SULowSignal '500BN001'
-- =============================================
CREATE PROCEDURE [dbo].[sp_U_ofi_SULowSignal_Backup08052024] 
	@SU_Name nvarchar(40)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- Declare variable
	DECLARE @storage_ent_id INT
			,@cons_lot_no NVARCHAR(40) = NULL
			,@cons_sublot_no NVARCHAR(40) = NULL
			,@cons_qty FLOAT = 0
			,@avl_qty FLOAT = 0
			--,@temp_qty FLOAT = 0
			,@consumed_qty FLOAT = 0
			,@job_pos INT = 0 
			,@bom_pos INT = 0
			,@date_time_UTC datetime =  GETUTCDATE()
			,@return_value int
			,@row_id INT32
			,@minID INT
			,@typeOfCons NVARCHAR(20) = 'FIFO'
			,@process_id NVARCHAR(30)
			,@process_type NVARCHAR(30)
			,@prod_info NVARCHAR(4000)
			,@prod_item_id NVARCHAR(40)
			,@prod_date_time_UTC datetime
			,@user_id NVARCHAR(40)=NULL
			,@wo_state INT 
	declare @ent_id int, @qty_left float, @su_level_threshold int, @plant_level_threshold int, @final_threshold int, @wo_id nvarchar(40),@Out int,@inv_item_id nvarchar(40)
	declare @item_id nvarchar(40),@target_sched_ent_id int , @cons_ent_id int, @oper_id nvarchar(40), @seq_no int
	DECLARE @Counter INT, @iterate int=1
	declare @TempInv table(ID INT IDENTITY(1, 1) primary key, ent_id int,item_id nvarchar(40), lot_no nvarchar(40), sub_lot_no nvarchar(40), qty float)
	declare @defaultUoMDesc NVARCHAR(20) = 'KG'
		   ,@defaultUoMId INT 

	-- Get User Id
	EXEC sp_S_DB_Status_GetAudTrailUsr @user_id OUTPUT, NULL

	Select @ent_id= ent_id from ent(nolock) where ent_name=@SU_Name
	print @ent_id

	-- Get Default UoM Desc
	SELECT @defaultUoMDesc=attr_value FROM ent_attr WITH (NOLOCK) WHERE ent_id = @ent_id AND attr_id = (SELECT attr_id 
																											FROM attr WITH (NOLOCK) 
																											WHERE attr_desc = 'DefaultStorageUoM' and attr_grp = 2)

	SET @defaultUoMDesc = ISNULL(@defaultUoMDesc,'KG')

	-- v0.02.00 Get Good Consumption (Item Reason)
	DECLARE @strGoodConsReas NVARCHAR(40) = 'Good Consumption',
			@intGoodConsReas INT = NULL
	SELECT @intGoodConsReas = reas_cd FROM item_reas WITH (NOLOCK) 
	WHERE reas_desc= @strGoodConsReas

	SET @intGoodConsReas = ISNULL(@intGoodConsReas, 1)

	-- Get Default UoM Id
	SELECT @defaultUoMId = uom_id FROM uom WITH(NOLOCK)
	WHERE description = @defaultUoMDesc

	-- Get current qty
	select @qty_left=SUM(qty_left),@inv_item_id=max(item_id) from item_inv(nolock) where ent_id=@ent_id
	print @qty_left

	-- Get plant and storage threshold
	select @su_level_threshold = CONVERT(INT,REPLACE(ea.attr_value, ',','')) from ent_attr(nolock) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
						join attr(nolock) a on ea.attr_id=a.attr_id
						where ea.ent_id=@ent_id and a.attr_desc='StorageUnitThreshold'
	print @su_level_threshold

	select @plant_level_threshold =  CONVERT(INT,REPLACE(ea.attr_value, ',','')) from ent_attr(nolock) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
						join attr(nolock) a on ea.attr_id=a.attr_id
						where ea.ent_id=(select top 1 ent_id from ent(nolock) where parent_ent_id is null order by ent_id )  
						and a.attr_desc='StorageUnitThreshold'

	-- get converted qty left
