/*
-- ===========================================================================================
-- Name:		[sp_s_ofi_lm_print_label]
-- Description: Print Label- Insert data into Label table
--
-- Usage:	Print Label- Insert data into Label table
-- ===========================================================================================
-- Version	Author		Date (yyyy-MM-dd)	Change description
-- 0.01.00	CK			2022-11-02			Initial version. 
-- ===========================================================================================*/
CREATE PROCEDURE [dbo].[sp_s_ofi_lm_print_label] 
	 
	 @wo_id NVARCHAR(100)
	,@oper_id NVARCHAR(100)
	,@seq_no INT
AS
BEGIN
	 
	SET NOCOUNT ON;
 
	Declare 
@job_req_qty INT ,
@item_prod_lot NVARCHAR(100),
@job_item_id NVARCHAR(100),
@item_prod_produce INT ,
@job_seq_no INT ,
@job_prod_qty INT ,
@ofi_printer_id NVARCHAR(100),
@job_wo_id NVARCHAR(100),
@item_prod_pallet_spare2  NVARCHAR(100),
@ofi_wo_ext_customer NVARCHAR(100),
@job_oper_id NVARCHAR(100),
@raw_layout_name NVARCHAR(100),
@layoutName nvarchar(100) = NULL
,@swShowKosher bit = 0;

select 
@job_req_qty =j.qty_reqd
,@item_prod_lot=ip.lot_no
,@job_item_id=j.item_id
,@item_prod_produce=ip.qty_prod
,@job_seq_no=j.seq_no
,@job_prod_qty=j.qty_prod
,@ofi_printer_id=owe.printer_id
,@job_wo_id=j.wo_id
,@item_prod_pallet_spare2=ip.spare2
,@ofi_wo_ext_customer=owe.ship_to_customer
,@job_oper_id =j.oper_id
,@raw_layout_name=owe.layout_name
from job j WITH(NOLOCK)
inner join item_prod ip WITH(NOLOCK) on ip.wo_id=j.wo_id and ip.oper_id=j.oper_id and ip.seq_no=j.seq_no and ip.item_id=j.item_id
inner join ofi_wo_ext owe WITH(NOLOCK) on owe.wo_id=j.wo_id and owe.wo_id=j.wo_id
WHERE j.wo_id=@wo_id AND j.oper_id=@oper_id AND j.seq_no=@seq_no

DECLARE @layoutTable TABLE ( row_id int identity(1,1) ,value nvarchar(50));

INSERT INTO @layoutTable
SELECT  value FROM STRING_SPLIT(@raw_layout_name, '-')

select  @layoutName=value from @layoutTable where row_id=1
select  @swShowKosher=value from @layoutTable where row_id=2
select  @layoutName as layout,@swShowKosher as showkosher
END

--===========================================================================================
-- Name:    SP_U_EI_Item
-- Description:  Updates the item
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Sk          2022-07-12      Initial version.
-- 0.01.01  Lk          2024-03-07      Updated the wip to obsolete 
-- 0.01.02  Lk          2024-03-07      added the logic for Classification Attribute
-- ===========================================================================================
CREATE   PROCEDURE [dbo].[SP_U_EI_MM] (@item_id       NVARCHAR(40),
                                      @item_desc     NVARCHAR(80),
                                      @uom_desc      NVARCHAR(40),
                                      @lifetime      INT,
                                      @lifetime_unit NVARCHAR(1),
                                      @item_status   NVARCHAR(40),
                                      @item_class_desc NVARCHAR(40),
                                      @spare1        NVARCHAR(200),
                                      @spare2        NVARCHAR(200),
                                      @spare3        NVARCHAR(200),
                                      @spare4        NVARCHAR(200))
AS
  BEGIN
	  IF (dbo.fn_s_ofi_plantcode()= @spare1)
	  BEGIN
			  DECLARE @obsolete       INT=0,
					  @uom_id         INT,
					  @rc             INT,
					  @error_msg      NVARCHAR(500),
					  @error_severity INT,
					  @error_state    INT,
					  @item_class_id  NVARCHAR(40),
					  @wip_item_id nvarchar(20)

			  IF @item_status = 'Deleted'
				BEGIN
					SET @obsolete=1
				END

			  SET @lifetime= CASE
							   WHEN @lifetime_unit = 'D' THEN @lifetime
							   WHEN @lifetime_unit = 'M' THEN @lifetime * 30
							   WHEN @lifetime_unit = 'Y' THEN @lifetime * 365
							   ELSE @lifetime
							 END



				  IF @obsolete=1
				  BEGIN
					  UPDATE item
					  SET obsolete=@obsolete
					  WHERE item_id=@item_id

					  select @wip_item_id=replace(@item_id,'10000','50000')---- 0.01.01
					  UPDATE item
					  SET obsolete=@obsolete
					  WHERE item_id=@wip_item_id

				  END

				  ELSE
				  BEGIN
						BEGIN try
							BEGIN TRANSACTION
							  IF NOT EXISTS (SELECT TOP 1 1
											 FROM   uom WITH (nolock)
											 WHERE  description = @uom_desc)
								BEGIN
									EXECUTE @rc = [dbo].[Sp_i_uom]
									  @description = @uom_desc,
									  @abbreviation = @uom_desc,
									  @last_edit_comment = N'ADDED BY EI',
									  @uom_id = @uom_id output,
									  @last_edit_at = NULL

									IF ( @rc <> 0 )
									  BEGIN
										  SET @error_msg = N'Error while creating UOM (' + @uom_desc
														   + ') in MES  - SP_U_EI_ITEM -  '
														   + CONVERT(NVARCHAR(16), @rc);

										  THROW 51009, @error_msg, 1
									  END
								END
							  ELSE
								BEGIN
									SELECT @uom_id = uom_id
									FROM   uom WITH (nolock)
									WHERE  description = @uom_desc
								END

							  IF NOT EXISTS (SELECT TOP 1 1
											 FROM   item_class WITH (nolock)
											 WHERE  item_class_desc = @item_class_desc)
								BEGIN
									EXECUTE @rc = [dbo].[Sp_i_item_class]
									  @item_class_id = @item_class_desc,
									  @item_class_desc = @item_class_desc,
									  @produced = 1,
									  @consumed = 1,
									  @obsolete = 0,
									  @purchased = 0,
									  @sold = 0,
									  @lot_no_format = NULL,
									  @last_lot_no = NULL,
									  @sublot_no_format = NULL,
									  @last_sublot_no = NULL,
									  @serial_no_lvl = -1,
									  @inv_unique_by_job = 0,
									  @spare1 = NULL,
									  @spare2 = NULL,
									  @spare3 = NULL,
									  @spare4 = NULL,
									  @last_edit_comment = N'ADDED BY EI',
									  @last_edit_at = NULL

									IF ( @rc <> 0 )
									  BEGIN
										  SET @error_msg = N'Error while creating item class ('
														   + @item_class_desc
														   + ') in MES  - SP_U_EI_ITEM -  '
														   + CONVERT(NVARCHAR(16), @rc);

										  THROW 51009, @error_msg, 1
									  END
								END

							  SELECT @item_class_id = item_class_id
							FROM   item_class WITH (nolock)
							WHERE  item_class_desc = @item_class_desc

							  UPDATE item
							  SET    item_desc = @item_desc,
									 uom_id = @uom_id,
									 item_class_id = @item_class_id,
									 lifetime = @lifetime,
									 obsolete = @obsolete
							  WHERE  item_id = @item_id
							  -- 0.01.02 below logic is written to update the item attribute for classification
							 SELECT @item_class_id = attr_id
							FROM   attr a WITH (nolock)
							WHERE  a.attr_desc = 'Classification'
								   AND a.attr_grp = 1
					
				   IF EXISTS (SELECT TOP 1 1
								 FROM   item_attr WITH (nolock)
								 WHERE  item_id = @item_id
										AND attr_id = @item_class_id)
						   BEGIN
							UPDATE item_attr
							SET    attr_value = @spare4
							WHERE  attr_id = @item_class_id
							  AND item_id = @item_id
				           END

							COMMIT TRANSACTION

						END try

						BEGIN catch
							IF @@TRANCOUNT > 0
							ROLLBACK TRANSACTION;

							SELECT @error_msg = Error_message(),
									@error_severity = Error_severity(),
									@error_state = Error_state();

							RAISERROR(@error_msg,@error_severity,@error_state)
						END catch
				  END
			END
  END

