CREATE  PROCEDURE [dbo].[sp_u_ofi_inv_reduceV1]
	-- Add the parameters for the stored procedure here
	@ent_name nvarchar(100),	
	@reduceqty float

AS
BEGIN
    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET nocount ON; 

    DECLARE @ent_id    INT,
            @item_id   NVARCHAR(80),
            @grade_cd  INT,
            @status_cd INT
    DECLARE @minID    INT,
            @maxID    INT,
            @lotno    NVARCHAR(50),
            @sublotno NVARCHAR(50),
            @consqty  FLOAT,
			@qty FLOAT,
			@incomingUoM NVARCHAR(100) = 'KG'

	DECLARE @auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			 @iRowId int,
			 @audit_trail INT = 1,
			 @grade_desc NVARCHAR(100),
			 @state_desc NVARCHAR(100),
			 @user_name NVARCHAR(100),
             @strModuleName nvarchar(80) = 'INV_AutoScrap',
             @strFunctionName nvarchar(80) = 'UI',
             @strActivityMsg nvarchar(200) = 'EDIT',
             @strCommentMsg nvarchar(200) = 'Silo Name :'+@ent_name+', Reduce Qty'+CAST(@reduceqty AS varchar)+' KG, created From [dbo].[sp_u_ofi_inv_reduce]'

    SELECT @ent_id = ent_id
    FROM   ent WITH(nolock)
    WHERE  ent_name = @ent_name

    IF @ent_id IS NOT NULL
      BEGIN
          --DECLARE @inv_list  table(id int identity(1,1) not null,lot nvarchar(50),sublot  nvarchar(50),qty float,cons_qty float,  consume_full int,grade_cd int,status_cd int,row_id int)
          SELECT @item_id = item_id
          FROM   item_inv WITH(nolock)
          WHERE  ent_id = @ent_id

          DECLARE @inv_list AS TABLE
            (
               id           INT,
               lot          NVARCHAR(40),
               sublot       NVARCHAR(40),
               qty          FLOAT,
               cons_qty     FLOAT,
               consume_full BIT,
               grade_cd     INT,
               status_cd    INT,
               row_id       INT
            )

		  SELECT @reduceqty = [dbo].[Fn_ofi_convertqtybyitemidanduom]
				(@item_id, @reduceqty, NULL, NULL, 'KG', u.abbreviation, NULL, NULL) -- value incomming always in KG
		  FROM item i WITH (NOLOCK)
		  INNER JOIN uom u WITH (NOLOCK) ON i.uom_id=u.uom_id
		  where item_id = @item_id

		  SET @reduceqty = ISNULL(@reduceqty,0.00)

          -- Insert statements for procedure here
          INSERT INTO @inv_list
          EXEC Sp_sa_ofi_item_inv_typeofcons
            @ent_id,
            @item_id,
            @reduceqty,
            'FIFO'

          --SELECT * FROM @inv_list
          SELECT @minID = Min(id),
                 @maxID = Max(id)
          FROM   @inv_list

          SELECT *
          FROM   @inv_list

          WHILE ( @minID <= @maxID )
            BEGIN
                --  select *from #inv_list where id=@minID
                SELECT @lotno = lot,
                       @sublotno = sublot,
					   @qty = qty,
                       @consqty = cons_qty,
                       @grade_cd = grade_cd,
                       @status_cd = status_cd,
					   @irowid = row_id
                FROM   @inv_list
                WHERE  id = @minID

                EXEC Sp_u_item_inv_reduce
                  @ent_id=@ent_id,
                  @item_id=@item_id,
                  @lot_no=@lotno,
                  @sublot_no=@sublotno,
                  @reduce_qty=@consqty,
                  @reduce_qty_erp=0,
                  @date_out=NULL,
                  @goods_shipped=0,
                  @item_grade_cd=@grade_cd,
                  @item_status_cd=@status_cd,
                  @item_reas_cd=NULL,
                  @must_consume_from_inv=1,
                  @must_cons_from_wip=0,
                  @checkgrade=1,
                  @wo_id=NULL,
                  @oper_id=NULL,
                  @seq_no=NULL,
                  @last_edit_at=NULL,
                  @transfer_comments='AUTO SCRAP',
                  @log_transfer=1,
                  @date_out_utc=NULL,
                  @time_zone_bias_value=NULL,
                  @row_id=NULL

				IF (@audit_trail = 1)
				BEGIN
					
					-- Insert entry in Audit Trial starts
					Select @grade_desc=item_grade_desc from item_grade with (nolock) where item_grade_cd=@grade_cd

					Select @state_desc=item_status_desc from item_state with (nolock) where item_status_cd=@status_cd

					Select @user_name = SUSER_NAME()
					
					DELETE @auditTrailParameters;
					SET @strCommentMsg  = 'Silo Name :'+@ent_name+', Prev Qty :'+ CAST(@qty AS varchar) +', Reduce Qty :'+CAST(@consqty AS varchar)+', created From [dbo].[sp_u_ofi_inv_reduce]'
					
					INSERT INTO @auditTrailParameters (row_id, field_name, field_value)	values 
							 (@iRowId,'@EntId',CONVERT(NVARCHAR(80),@ent_id)),
							(@iRowId,'@ItemId',CONVERT(NVARCHAR(80),@item_id))
							,(@iRowId,'@LotNo',CONVERT(NVARCHAR(80),@lotno))
							,(@iRowId,'@SublotNo',CONVERT(NVARCHAR(80),@sublotno))
							,(@iRowId,'@Qty',CONVERT(NVARCHAR(80),@qty-@consqty))
							,(@iRowId,'@GradeCd',CONVERT(NVARCHAR(80),@grade_cd))
							,(@iRowId,'@StateCd',CONVERT(NVARCHAR(80),@status_cd))
						

					 EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName,
											  @function_id = @strFunctionName,
											  @auditTrailParameters = @auditTrailParameters,
											  @user_id = @user_name,
											  @activity = @strActivityMsg,
											  @audit_category = 'Info',
											  @comments = @strCommentMsg
				 END

                SET @minID = @minID + 1;
            END
      END
END

