	@value6 nvarchar(80) ,
	@value7 nvarchar(80) ,
	@value8 nvarchar(80) ,
	@value9 nvarchar(80) ,
	@value10 nvarchar(80) ,
	@last_edit_comment nvarchar(254) ,
	@time_zone_bias_value INT32 = 0,
	@row_id int OUT
)
AS
--- ***********************************************************************************************************************
-- Module Name      - sp_I_Job_Event
-- Description      - Insert a row into the table
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
-- Notes            -
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Modified_By		Ver		Changes
-- 02/18/2003	Raghu			1.5.5	Get current date for event time, if event time is NULL
-- 10/14/2005	Raghu			3.1.0	HD# 5678, Part of DB Changes
-- 10/20/2005	Raghu			3.1.0	Language string ID added.
-- 01/12/2007	KRF				3.2.1	HD# 8314, part of DB changes - added @sublot_no argument
-- 01/18/2007	KRF				3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 07/26/2007	AML				3.3.0	DB Changes
-- 10/24/2007	AML				3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--										dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 02/14/2008	AML				3.4.0	L00075111: commented out code that set @event_time_local to @last_edit_at
-- 08/22/2009	Raghu		4.0		DB Changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @wo_id 			NVARCHAR(40)
	,	@oper_id 		NVARCHAR(40)
	,	@seq_no 		INT
	,	@last_edit_by	NVARCHAR(40)
	,	@last_edit_at	DATETIME
	,	@event_time_utc	DATETIME


SELECT @wo_id = cur_wo_id, @oper_id = cur_oper_id, @seq_no = cur_seq_no
FROM job_exec WITH (NOLOCK)
WHERE ent_id = @ent_id
     AND job_pos = @job_pos

IF (@wo_id IS NULL OR @wo_id = '')  OR (@oper_id IS NULL OR @oper_id = '') BEGIN
	--RAISERROR ('There is NO job running on this entity', 16, 1)
	RAISERROR ('There is currently NOT a job running on the specified entity.{3194}', 16, 1)
	RETURN -1
END

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)

DECLARE @tz_temp AS INT
SET @tz_temp = -@time_zone_bias_value

--SET @event_time_utc = DATEADD( mi, -@time_zone_bias_value, @event_time_local )
EXEC sp_TZ_GetDateInfo NULL, @event_time_utc OUTPUT, @event_time_local OUTPUT, @time_zone_bias_value OUTPUT

SELECT	@event_time_local = dbo.fn_StripMilliSecsFromDateTime( @event_time_local )
	,	@event_time_utc = dbo.fn_StripMilliSecsFromDateTime( @event_time_utc )


INSERT INTO job_event
(
