CREATE PROCEDURE [dbo].[sp_I_Cert_Type]
  (@cert_name nvarchar(40) ,
   @max_level int ,
   @duration int ,
   @audit bit,
   @signoff_notes nvarchar(254),
   @num_signoffs_reqd int,
   @reqd_exp_to_renew int ,
   @comments_reqd bit,
   @avail_to_oper bit ,
   @avail_to_oper_step bit ,
   @avail_to_prod_item bit ,
   @avail_to_cons_item bit ,
   @avail_to_attr bit ,
   @avail_to_grade_chg bit ,
   @avail_to_state_chg bit ,
   @avail_to_log_data bit ,
   @up_to_experimental bit ,
   @up_to_approved bit ,
   @up_to_certified bit ,
   @down_to_disabled bit ,
   @down_to_experimental bit ,
   @down_to_approved bit ,
   @spare1  nvarchar(1000)  ,
   @spare2  nvarchar(1000)  ,
   @spare3  nvarchar(1000)  ,
   @spare4  nvarchar(1000) ,
   @last_edit_comment nvarchar(254) ,
   @last_edit_at DATETIME OUT)
AS
--- ***********************************************************************************************************************
-- Module Name        - sp_I_Cert_Type
-- Description            - Insert a row into the table
-- Author	      -
-- Date Created         - 10/17/2002
-- Version                  - 1.5.0.0
--
-- Copyright (c) 2018 AVEVA Group plc and its subsidiaries. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
-- Notes                     -
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Change By	Ver.	Changes
-- 09/22/2005	Raghu		3.1.0	Part of DB Changes
-- 01/18/2007	KRF			3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 10/24/2007	AML			3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--									dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 11/01/2007	AML			3.4.0	DB Changes
-- 08/24/2018	Surya 		6.0		US#983758 (As SE, I want stateless APIs for certifications so I can include it in MES client)
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN
	IF @max_level IS NULL SET  @max_level = 1
	IF @duration IS NULL SET  @duration = 0

	SELECT	@audit = ISNULL( @audit, 0 )
		,	@comments_reqd = ISNULL( @comments_reqd, 0 )
		,	@avail_to_oper = ISNULL( @avail_to_oper, 0 )
		,	@avail_to_oper_step = ISNULL( @avail_to_oper_step, 0 )
		,	@avail_to_prod_item = ISNULL( @avail_to_prod_item, 0 )
		,	@avail_to_cons_item = ISNULL( @avail_to_cons_item, 0 )
		,	@avail_to_attr = ISNULL( @avail_to_attr, 0 )
		,	@avail_to_grade_chg = ISNULL( @avail_to_grade_chg, 0 )
		,	@avail_to_state_chg = ISNULL( @avail_to_state_chg, 0 )
		,	@avail_to_log_data = ISNULL( @avail_to_log_data, 0 )
		,	@up_to_experimental = ISNULL( @up_to_experimental, 0 )
		,	@up_to_approved = ISNULL( @up_to_approved, 0 )
		,	@up_to_certified = ISNULL( @up_to_certified, 0 )
		,	@down_to_disabled = ISNULL( @down_to_disabled, 0 )
		,	@down_to_experimental = ISNULL( @down_to_experimental, 0 )
		,	@down_to_approved = ISNULL( @down_to_approved, 0 )
		,	@reqd_exp_to_renew = ISNULL( @reqd_exp_to_renew, 0 )

	DECLARE  @last_edit_by	NVARCHAR(40)

	EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
	SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

	INSERT INTO cert_type
	(
		cert_name, max_level, duration, cert_audit, signoff_notes, num_signoffs_reqd, reqd_exp_to_renew, comments_reqd, avail_to_oper,
		avail_to_oper_step, avail_to_prod_item, avail_to_cons_item, avail_to_attr, avail_to_grade_chg, avail_to_state_chg, avail_to_log_data,
		up_to_experimental, up_to_approved, up_to_certified, down_to_disabled, down_to_experimental, down_to_approved, spare1, spare2,
		spare3, spare4, last_edit_comment, last_edit_by, last_edit_at
	)
	VALUES
	(
		@cert_name, @max_level, @duration, @audit, @signoff_notes, @num_signoffs_reqd, @reqd_exp_to_renew, @comments_reqd, @avail_to_oper,
		@avail_to_oper_step, @avail_to_prod_item, @avail_to_cons_item, @avail_to_attr, @avail_to_grade_chg, @avail_to_state_chg,
		@avail_to_log_data, @up_to_experimental, @up_to_approved, @up_to_certified, @down_to_disabled, @down_to_experimental, @down_to_approved, @spare1,
		@spare2, @spare3, @spare4, @last_edit_comment, @last_edit_by, @last_edit_at
	)

END

--===========================================================================================
-- Name:    SP_U_EI_Item_UOM_CONV
-- Description:  Updates the item uom conversion
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Sk          2022-07-14      Initial version.
-- ===========================================================================================
CREATE   PROCEDURE [dbo].[SP_U_EI_MM_UOM_CONV] (@item_id     NVARCHAR(40),
                                               @plant_code  NVARCHAR(40),
                                               @item_status NVARCHAR(40),
                                               @from_uom    NVARCHAR(40),
                                               @to_uom      NVARCHAR(40),
                                               @numerator   FLOAT,
                                               @denominator FLOAT)
AS
  BEGIN
      IF @item_status <> 'Deleted' and (dbo.fn_s_ofi_plantcode()= @plant_code)
        BEGIN
            DECLARE @rc             INT,
                    @error_msg      NVARCHAR(500),
                    @error_severity INT,
                    @error_state    INT,
                    @from_uom_id    INT,
                    @to_uom_id      INT,
                    @row_id         INT,
                    @last_edit_at   DATETIME,
                    @conv_factor    FLOAT,
					@attr_id		INT,
					@mod_id			NVARCHAR(100)

            SET @conv_factor=( @numerator / @denominator )

            SELECT @from_uom_id = uom_id
            FROM   uom WITH (nolock)
            WHERE  description = @from_uom

            SELECT @to_uom_id = uom_id
            FROM   uom WITH (nolock)
            WHERE  description = @to_uom

            BEGIN try
                BEGIN TRANSACTION

                IF @from_uom_id IS NULL
                  BEGIN
                      EXECUTE @rc = [dbo].[Sp_i_uom]
                        @description = @from_uom,
                        @abbreviation = @from_uom,
                        @last_edit_comment = N'ADDED BY EI',
                        @uom_id = @from_uom_id output,
                        @last_edit_at = NULL

                      IF ( @rc <> 0 )
                        BEGIN
                            SET @error_msg = N'Error while creating UOM (' +
                                             @from_uom
                                             + ') in MES  - SP_U_EI_ITEM_UOM_CONV -  '
                                             + CONVERT(NVARCHAR(16), @rc);

                            THROW 51009, @error_msg, 1
                        END
                  END

                IF @to_uom_id IS NULL
                  BEGIN
                      EXECUTE @rc = [dbo].[Sp_i_uom]
                        @description = @to_uom,
                        @abbreviation = @to_uom,
                        @last_edit_comment = N'ADDED BY EI',
                        @uom_id = @to_uom_id output,
                        @last_edit_at = NULL

                      IF ( @rc <> 0 )
                        BEGIN
                            SET @error_msg = N'Error while creating UOM (' +
                                             @to_uom
                                             + ') in MES  - SP_U_EI_ITEM_UOM_CONV -  '
                                             + CONVERT(NVARCHAR(16), @rc);

                            THROW 51009, @error_msg, 1
                        END
                  END

                IF NOT EXISTS (SELECT TOP 1 1
                               FROM   uom_conv WITH (nolock)
                               WHERE  from_uom_id = @from_uom_id
                                      AND to_uom_id = @to_uom_id
                                      AND item_id = @item_id)
                  BEGIN
                      IF NOT EXISTS (SELECT TOP 1 1
                                     FROM   uom_conv WITH (nolock)
                                     WHERE  from_uom_id = @from_uom_id
                                            AND to_uom_id = @to_uom_id
                                            AND item_id IS NULL)
                        BEGIN
                            EXEC @RC = [dbo].[Sp_i_uom_conv]
                              @from_uom_id = @from_uom_id,
                              @to_uom_id = @to_uom_id,
                              @item_id = NULL,
                              @factor = @conv_factor,
                              @offset = 0,
                              @spare1 = NULL,
                              @spare2 = NULL,
                              @spare3 = NULL,
                              @spare4 = NULL,
                              @last_edit_comment = NULL,
                              @last_edit_at = @last_edit_at output,
                              @row_id = @row_id output

                            IF ( @RC <> 0 )
                              BEGIN
                                  SET @error_msg = N'Error while creating UOM Conversion (' +
                                             @from_uom
											 + '-' + @to_uom + '-' + @item_id
                                             + ') in MES  - SP_U_EI_ITEM_UOM_CONV -  '
                                             + CONVERT(NVARCHAR(16), @rc);

								  THROW 51009, @error_msg, 1
                              END
                        END

                      EXEC @RC = [dbo].[Sp_i_uom_conv]
                        @from_uom_id = @from_uom_id,
                        @to_uom_id = @to_uom_id,
                        @item_id = @item_id,
                        @factor = @conv_factor,
                        @offset = 0,
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @last_edit_comment = NULL,
                        @last_edit_at = @last_edit_at output,
                        @row_id = @row_id output

                      IF ( @RC <> 0 )
                        BEGIN
                                  SET @error_msg = N'Error while creating UOM Conversion (' +
                                             @from_uom
											 + '-' + @to_uom + '-' + @item_id
                                             + ') in MES  - SP_U_EI_ITEM_UOM_CONV -  '
                                             + CONVERT(NVARCHAR(16), @rc);

								  THROW 51009, @error_msg, 1
                        END
                  END
                ELSE
                  BEGIN
                      UPDATE uom_conv
                      SET    factor = @conv_factor,
                             offset = 0,
                             spare1 = NULL,
                             spare2 = NULL,
                             spare3 = NULL,
                             spare4 = NULL,
                             last_edit_comment = NULL
                      WHERE  from_uom_id = @from_uom_id
                             AND to_uom_id = @to_uom_id
                             AND item_id = @item_id
                  END

                SET @conv_factor= 1 / @conv_factor

                IF NOT EXISTS (SELECT TOP 1 1
                               FROM   uom_conv WITH (nolock)
                               WHERE  from_uom_id = @to_uom_id
                                      AND to_uom_id = @from_uom_id
                                      AND item_id = @item_id)
                  BEGIN
                      IF NOT EXISTS (SELECT TOP 1 1
                                     FROM   uom_conv WITH (nolock)
                                     WHERE  from_uom_id = @to_uom_id
                                            AND to_uom_id = @from_uom_id
                                            AND item_id IS NULL)
                        BEGIN
                            EXEC @RC = [dbo].[Sp_i_uom_conv]
                              @from_uom_id = @to_uom_id,
                              @to_uom_id = @from_uom_id,
                              @item_id = NULL,
                              @factor = @conv_factor,
                              @offset = 0,
                              @spare1 = NULL,
                              @spare2 = NULL,
                              @spare3 = NULL,
                              @spare4 = NULL,
                              @last_edit_comment = NULL,
                              @last_edit_at = @last_edit_at output,
                              @row_id = @row_id output

                            IF ( @RC <> 0 )
                              BEGIN
                                  SET @error_msg = N'Error while creating UOM Conversion (' +
                                             @to_uom
											 + '-' + @from_uom + '-' + @item_id
                                             + ') in MES  - SP_U_EI_ITEM_UOM_CONV -  '
                                             + CONVERT(NVARCHAR(16), @rc);

								  THROW 51009, @error_msg, 1
                              END
                        END

                      EXEC @RC = [dbo].[Sp_i_uom_conv]
                        @from_uom_id = @to_uom_id,
                        @to_uom_id = @from_uom_id,
                        @item_id = @item_id,
                        @factor =@conv_factor,
                        @offset = 0,
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @last_edit_comment = NULL,
                        @last_edit_at = @last_edit_at output,
                        @row_id = @row_id output

                      IF ( @RC <> 0 )
                        BEGIN
							SET @error_msg = N'Error while creating UOM Conversion (' +
										@to_uom
										+ '-' + @from_uom + '-' + @item_id
										+ ') in MES  - SP_U_EI_ITEM_UOM_CONV -  '
										+ CONVERT(NVARCHAR(16), @rc);

							THROW 51009, @error_msg, 1
                        END
                  END
                ELSE
                  BEGIN
                      UPDATE uom_conv
                      SET    factor = @conv_factor,
                             offset = 0,
                             spare1 = NULL,
                             spare2 = NULL,
                             spare3 = NULL,
                             spare4 = NULL,
                             last_edit_comment = NULL
                      WHERE  from_uom_id = @to_uom_id
                             AND to_uom_id = @from_uom_id
                             AND item_id = @item_id
                  END

				IF @from_uom = 'BBG'
				BEGIN
					SELECT @attr_id = attr_id from attr with(nolock) where attr_desc = 'isBigBag'
					IF NOT EXISTS (SELECT 1 from item_attr with(nolock) where item_id = @item_id and attr_id = @attr_id)
					BEGIN
						EXEC @rc = sp_I_Item_Attr @item_id,@attr_id,'1','ADDED BY EI',NULL,@mod_id OUTPUT

						IF ( @rc <> 0 )
                        BEGIN
                            SET @error_msg = N'Error while creating isBigBag attribute (' +
                                             @item_id
                                             + ') in MES  - sp_I_Item_Attr -  '
                                             + CONVERT(NVARCHAR(16), @rc);

                            THROW 51009, @error_msg, 1
                        END
					END
				END

                COMMIT TRANSACTION
            END try

            BEGIN catch
                IF @@TRANCOUNT > 0
                  ROLLBACK TRANSACTION;

                SELECT @error_msg = Error_message(),
                       @error_severity = Error_severity(),
                       @error_state = Error_state();

                RAISERROR(@error_msg,@error_severity,@error_state)
            END catch
        END
  END

