CREATE PROCEDURE [dbo].[sp_I_Spc_Rule]
    (
      @rule_desc NVARCHAR(40) ,
      @use_for_ix BIT = 0 ,
      @use_for_mr BIT = 0 ,
      @use_for_xbar BIT = 0 ,
      @use_for_range BIT = 0 ,
      @use_for_sigma BIT = 0 ,
      @use_for_ma BIT = 0 ,
      @use_for_ewmaix BIT = 0 ,
      @use_for_run BIT = 0 ,
      @use_for_attr BIT = 0 ,
      @test1 INT ,
      @test2 INT ,
      @and_not_or BIT ,
      @level1 FLOAT ,
      @level2 FLOAT ,
      @num_points INT ,
      @of_points INT ,
      @priority INT , -- Added 1/16/07 KRF
      @obsolete BIT = 0 ,
      @last_edit_comment NVARCHAR(254) ,
      @time_zone_bias_value INT32 = 0 ,
      @last_edit_at DATETIME OUT ,
      @rule_id INT OUT
    )
AS -- ***********************************************************************************************************************
-- Module Name      - sp_I_Spc_Rule
-- Description      - Insert a row into the table
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
-- Notes            -
----------------------------------------------------------------------------------------------------------------------------
-- Change Date Change By   Ver.  Changes
-- 09/26/2005  Raghu    3.1.0 Part of DB Changes
-- 01/16/2007  KRF      3.2.1 HD# 9289, part of DB changes - added @priority argument, if null, setting it to
--             one more than the highest existing rule priority
-- 01/18/2007  KRF      3.2.1 HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 10/24/2007  AML         3.3.4 HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--                         dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 08/29/2011  JA        4.5   MES-QM changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
    SET NOCOUNT ON
    SET XACT_ABORT ON
    BEGIN

        DECLARE @last_edit_by NVARCHAR(40) ,
            @created_at TDATETIME

        EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
        SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime(GETUTCDATE())

        SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0) -- Added 1/18/07 KRF
        IF ( @time_zone_bias_value = 0 )
            SET @created_at = dbo.fn_TZ_GetLocalDate(NULL)
        ELSE
            SET @created_at = @last_edit_at

        IF ( @priority IS NULL )
            SELECT  @priority = MAX(priority) + 1
            FROM    spc_rule -- Added 1/16/07 KRF

        INSERT  INTO spc_rule
                ( rule_desc ,
                  use_for_ix ,
                  use_for_mr ,
