AS
--- ***********************************************************************************************************************
-- Module Name      - SP_I_JOB_EXEC
-- Description      - Insert a row into the table
-- Author	      -
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
-- Notes            -
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified      Modified_By      Changes
--01/23/2007	Raghu		3.2.0	Part of DB Changes
--07/13/2007  Raghu           3.3.1   HD# 9389, Add Post_exec_fc_counts to the job_exec table.
--11/02/2007	Raghu		3.4.0	Part of DB Changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN

	DECLARE @last_edit_by	STRING40
		,	@V_Client_Info	STRING40

	SELECT	@next_job_only = ABS(@next_job_only)  --Absolute
		,	@item_based_desc = ABS(@item_based_desc) --Absolute
		,	@autoload_job_specs = ABS(@autoload_job_specs)  --Absolute
		,	@incl_class_reas = ABS(@incl_class_reas)  --Absolute
		,	@must_complete_steps = ABS(@must_complete_steps)  --Absolute
		,	@must_prod_reqd_qty = ABS(@must_prod_reqd_qty) --Absolute
		,	@run_without_operator = ABS(@run_without_operator)
		,	@apply_post_exec_fc_counts = ISNULL(ABS(@apply_post_exec_fc_counts), 1)
		,	@suppress_start_qty_prompt = ISNULL(ABS(@suppress_start_qty_prompt), 0)
		,	@allow_zero_qty_split = ISNULL(ABS(@allow_zero_qty_split), 0)
		,	@auto_alloc_qty_to_running_job = ISNULL(ABS(@auto_alloc_qty_to_running_job), 0)
		,	@next_job_only = COALESCE(@next_job_only, 0)

	IF  @item_based_desc IS NULL BEGIN
		SET @item_based_desc = 0
	END
	IF  @autoload_job_specs IS NULL BEGIN
		SET @autoload_job_specs = 0
	END
	IF  @auto_seq_start_option IS NULL BEGIN
		SET @auto_seq_start_option = 0
	END
	IF  @auto_job_start_option IS NULL BEGIN
		SET @auto_job_start_option = 0
	END
	IF  @auto_job_end_option IS NULL BEGIN
		SET @auto_job_end_option = 0
	END
	IF  @incl_class_reas IS NULL BEGIN
		SET @incl_class_reas = 0
	END
	IF  @must_complete_steps IS NULL BEGIN
		SET @must_complete_steps = 1
	END
	IF  @must_prod_reqd_qty IS NULL BEGIN
		SET @must_prod_reqd_qty = 1
	END

	SELECT	@local_movable_cons_ent = ISNULL(ABS(@local_movable_cons_ent), 0)
		,	@local_movable_prod_ent = ISNULL(ABS(@local_movable_prod_ent), 0)
		,	@run_without_operator = ISNULL(ABS(@run_without_operator), 1)

	EXEC sp_s_db_status_getaudtrailusr @last_edit_by, @V_Client_Info

	SET @last_edit_at = GETUTCDATE()

	INSERT INTO job_exec (ent_id, job_pos, next_job_only, item_based_desc, job_end_confirm_msg, def_to_ent_id, def_reject_ent_id,
		   def_from_ent_id, def_prod_reas_cd, def_cons_reas_cd, def_lot_no, def_sublot_no, autoload_job_specs, auto_seq_start_option,
		   auto_job_start_option, auto_job_end_option, incl_class_reas, must_complete_steps, must_prod_reqd_qty,
		   local_movable_cons_ent, local_movable_prod_ent, run_without_operator, apply_post_exec_fc_counts,
           suppress_start_qty_prompt, allow_zero_qty_split, auto_alloc_qty_to_running_job,
		   cur_wo_id, cur_oper_id, cur_seq_no, cur_step_no, cur_step_start, spare1, spare2, spare3, spare4,
		   last_edit_comment, last_edit_by, last_edit_at)
	VALUES (@ent_id, @job_pos, @next_job_only, @item_based_desc, @job_end_confirm_msg, @def_to_ent_id, @def_reject_ent_id,
			@def_from_ent_id, @def_prod_reas_cd, @def_cons_reas_cd, @def_lot_no, @def_sublot_no, @autoload_job_specs, @auto_seq_start_option,
			@auto_job_start_option, @auto_job_end_option, @incl_class_reas, @must_complete_steps, @must_prod_reqd_qty, @local_movable_cons_ent,
			@local_movable_prod_ent, @run_without_operator, 1, @suppress_start_qty_prompt, @allow_zero_qty_split, @auto_alloc_qty_to_running_job,
			@cur_wo_id, @cur_oper_id, @cur_seq_no, @cur_step_no, @cur_step_start, @spare1, @spare2, @spare3, @spare4, @last_edit_comment,
			@last_edit_by, @last_edit_at)

END

