--/*********************************************************************************************************************************************************************
--Procedure:          [dbo].[[ufn_ofi_mes_aut_itemid] 
--Create Date:        2022-11-22
--Author:             Unnikrishnan Nair PG
--Description:        <To Convert MES item id to Automation related item id. >
--						The reason for this conversion is: 
--
/*The ABB OPC system in Koog is not really capable of handling many data types. So, beside the performance problems with String; noticed that only 32Bit integers are supported. 
This is an issue for the Item Id that comes from SAP; since they are 12 digit long and that exceed the capacity of the 32Bits Integer with ends around half of the 9 digit numbers. 

In order to overcome this:-

-	Item Ids will come and be created in MES via the Material Master message from SAP.
-	The item Ids in OFI (Koog and most likely all plants) follows the business rules of:
o	NN0987654321, where NN is a number to pre-identify the type of Materials; It can be 10 for Finish-Goods/Semi-Finish-Goods/ etc.; 90 for Wasted, and similar. 
o	The remaining numbers are just an incremental type.
-	
o	So, Keep the first two digits on the left of the item Id
o	Keep the first 6 digits on the right of the item Id
o	Concatenate both; as an Integer. 
o	The DCS Unique code would be something like NN654321; which is 8 digits and thereof could fit in a 32Bits Integer type.
-	From MES to DCS and Vice versa; the DCS Unique Code should be used.
-	MES would need to translated messages from DCS with this code into actual ItemID for the consumption and production messages coming from the interfaces.
*/

--Call by:            Common function; getting called from multiple SPs.                     
--Affected table(s):  
--                   
--Used By:            Functional Area:  
--
--	SELECT * FROM ufn_ofi_mes_aut_itemid ('2345690169841')
--**********************************************************************************************************************************************************************
--SUMMARY OF CHANGES
--Date(yyyy-mm-dd)    Author				Ver					Comments
------------------- ------------------- --------------------------------------------------------------------------------------------------------------------------------
--2022-11-22          PG					1.0					First version
--*********************************************************************************************************************************************************************/

CREATE FUNCTION [dbo].[ufn_ofi_mes_aut_itemid]
(    
      @item_id NVARCHAR(40),
	  @conversion_type int = 1		--	 conversion_type: 1 = MES item id to AUT item id.		2 = AUT item id to MES item id
)
	RETURNS @Output TABLE (
		  mes_item_id NVARCHAR(40), 
		  aut_item_id NVARCHAR(40), 
		  item_desc NVARCHAR(80), 
		  conv_type NVARCHAR(40)
		)
AS
BEGIN
    DECLARE @mes_item_id NVARCHAR(40) ;
	DECLARE @aut_item_id NVARCHAR(40) ;
	DECLARE @item_id_to_return nvarchar(20) = '' ;
	DECLARE @item_desc NVARCHAR(80) ;
	
	IF (@item_id IS NULL) SET @item_id = '' ;

	

	-- if only less than 8 char are in the item id, then nothing to do
	IF (LEN(@item_id) < 8) BEGIN
		INSERT INTO @Output (mes_item_id, aut_item_id, item_desc, conv_type)
		VALUES (@item_id, @item_id, @item_desc, @conversion_type) ;

		RETURN ;
	END ;

	--	 conversion_type: 1 = MES item id to AUT item id.
    IF (@conversion_type = 1) BEGIN
		SELECT @item_id_to_return = LEFT(@item_id, 2) + RIGHT(@item_id, 6) ;

		SELECT @item_desc = item_desc,
			@mes_item_id = @item_id,
			@aut_item_id = @item_id_to_return
		FROM item WITH (NOLOCK) 
		WHERE item_id = @item_id ;

	END ;
	--	 conversion_type: 2 = AUT item id to MES item id
	ELSE BEGIN
		SELECT @item_id_to_return = item_id 
		FROM item WITH (NOLOCK) 
		WHERE LEFT(item_id, 2) = LEFT(@item_id, 2) 
			AND  RIGHT(item_id, 6) = RIGHT(@item_id, 6) ;

		SELECT @item_desc = item_desc, 
			@aut_item_id = @item_id, 
			@mes_item_id = item_id  
		FROM item WITH (NOLOCK) WHERE item_id = @item_id_to_return ;
	END ;
	

    INSERT INTO @Output (mes_item_id, aut_item_id, item_desc, conv_type)
		VALUES (@mes_item_id, @aut_item_id, @item_desc, @conversion_type) ;

    RETURN ;
END

CREATE PROCEDURE [dbo].[sp_I_Job_Exec_CloneJob_BOM]
	@wo_id string40,
	@oper_id string40,
	@seq_no int,
	@new_wo_id string40,
	@new_oper_id string40,
	@new_seq_no int
AS
--- ***********************************************************************************************************************
-- Module Name	      - sp_I_Job_Exec_CloneJob_BOM
-- Description	      -
-- Author	      -
-- Date Created	      -
-- Version                  -
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Modified_By	Ver	Changes
-- 09/09/2002	Raghu		1.4	Removed Cont_id
-- 06/16/2004	Raghu		2.1.0		Included last_edit_by and last_edit_at fields in the insert statement.
-- 01/17/2005	Raghu		2.1.10	HD# 5302, Split job does not carry over the constant_qty
-- 05/18/2005	Raghu		2.1.11	HD# 5673, Cloning a job_bom does not write all the fields.
-- 01/12/2007	KRF		3.2.1	HD# 8314, part of DB changes - handle def_sublot_no field when cloning job_bom
-- 01/18/2007	KRF		3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 10/24/2007	AML			3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--									dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 08/30/2016   Malleswara  5.03    US#696147 Changes Merge CR#L00142243 - Clone the job_bom_subst records during the cloning of the job_bom
-- 09/21/2016   Malleswara  5.03    US#696147 Changes Merge CR#L00142243 - Adding 'with NOLOCK' hint to select statement.
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET NOCOUNT ON
DECLARE
  @JB_wo_id STRING40,
  @JB_oper_id STRING40,
  @JB_seq_no int,
  @JB_BOM_pos int,
  @JB_item_id STRING40,
  @JB_reqd_grade_cd int,
  @JB_instruction VARCHAR(2000),
  @JB_qty_per_parent_item float,
  @JB_max_qty_per_parent_item float,
  @JB_min_qty_per_parent_item float,
  @JB_reqd_start_val float,
  @JB_reqd_start_val_is_pct logical,
  @JB_update_inv logical,
  @JB_backflush logical,
  @JB_def_reas_cd int,
  @JB_def_lot_no STRING40,
  @JB_def_sublot_no STRING40, -- Added 1/12/07 KRF
  -- @JB_def_cont_id STRING40, Removed because containers not used 1/12/07 KRF
  @JB_def_storage_ent_id int,
  @JB_scaling_factor float,
  @JB_must_consume_from_inv logical,
  @JB_may_choose_alt_inv_loc logical,
  @JB_may_create_new_lots logical,
  @JB_must_consume_from_wip logical,
  @JB_must_consume_before_prod logical,
  @JB_constant_qty logical,
  @JB_est_time float,
  @JB_spare1 STRING80,
  @JB_spare2 STRING80,
  @JB_spare3 STRING80,
  @JB_spare4 STRING80,
  @last_edit_by	STRING40,
  @last_edit_at	DATETIME,
  @JB_mod_id timestamp
BEGIN
  EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
  SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

--6.	Clone JOB_BOM table row(s)* and then Clone JOB_BOM_STEP table row(s)*.
  DECLARE Job_bom_cursor CURSOR LOCAL
	FOR SELECT wo_id, oper_id, seq_no, bom_pos, item_id, reqd_grade_cd, instruction, qty_per_parent_item,
		max_qty_per_parent_item, min_qty_per_parent_item, reqd_start_val, reqd_start_val_is_pct,
		update_inv, backflush, def_reas_cd, def_lot_no, def_sublot_no, def_storage_ent_id, -- Added "def_sublot_no" 1/12/07 KRF
		scaling_factor, must_consume_from_inv, may_choose_alt_inv_loc, may_create_new_lots,
		must_consume_from_wip, must_consume_before_prod, constant_qty, est_time,
		spare1, spare2, spare3, spare4, mod_id FROM Job_BOM
	    WHERE  wo_id = @wo_id AND oper_id = @oper_id and seq_no = @seq_no
  OPEN  Job_bom_cursor
  FETCH NEXT FROM Job_bom_cursor
	INTO @JB_wo_id, @JB_oper_id, @JB_seq_no, @JB_BOM_pos,
		@JB_item_id, @JB_reqd_grade_cd, @JB_instruction, @JB_qty_per_parent_item, @JB_max_qty_per_parent_item,
		@JB_min_qty_per_parent_item, @JB_reqd_start_val, @JB_reqd_start_val_is_pct, @JB_update_inv, @JB_backflush,
		@JB_def_reas_cd, @JB_def_lot_no, @JB_def_sublot_no, @JB_def_storage_ent_id, @JB_scaling_factor, @JB_must_consume_from_inv, -- Added "@JB_def_sublot_no" 1/12/07 KRF
		@JB_may_choose_alt_inv_loc, @JB_may_create_new_lots, @JB_must_consume_from_wip, @JB_must_consume_before_prod,
		@JB_constant_qty, @JB_est_time, @JB_spare1, @JB_spare2, @JB_spare3, @JB_spare4, @JB_mod_id
  WHILE @@FETCH_STATUS = 0 BEGIN
	-- Added "def_sublot_no," and "@JB_def_sublot_no," in statement below 1/12/07 KRF
	INSERT INTO job_BOM  (wo_id, oper_id, seq_no, BOM_pos, item_id, reqd_grade_cd, instruction, qty_per_parent_item,
			max_qty_per_parent_item, min_qty_per_parent_item, reqd_start_val, reqd_start_val_is_pct,
			update_inv, backflush, def_reas_cd, def_lot_no, def_sublot_no, def_storage_ent_id, scaling_factor,
			must_consume_from_inv, may_choose_alt_inv_loc, may_create_new_lots, must_consume_from_wip,
			must_consume_before_prod, constant_qty, est_time, spare1, spare2, spare3, spare4,
			last_edit_by, last_edit_at)
		VALUES
			(@new_wo_id, @new_oper_id, @new_seq_no, @JB_BOM_pos, @JB_item_id, @JB_reqd_grade_cd,
			@JB_instruction, @JB_qty_per_parent_item, @JB_max_qty_per_parent_item, @JB_min_qty_per_parent_item,
			@JB_reqd_start_val, @JB_reqd_start_val_is_pct, @JB_update_inv, @JB_backflush, @JB_def_reas_cd, @JB_def_lot_no,
			@JB_def_sublot_no, @JB_def_storage_ent_id, @JB_scaling_factor, @JB_must_consume_from_inv, @JB_may_choose_alt_inv_loc,
			@JB_may_create_new_lots, @JB_must_consume_from_wip, @JB_must_consume_before_prod, @JB_constant_qty,
			@JB_est_time, @JB_spare1, @JB_spare2, @JB_spare3, @JB_spare4, @last_edit_by, @last_edit_at)
-- 		CLONE JOB_BOM_STEP ROWS
	EXECUTE sp_I_Job_Exec_CloneJobBOMStep @wo_id, @oper_id, @seq_no, @JB_BOM_pos, @new_wo_id, @new_oper_id, @new_seq_no, @JB_BOM_pos

	INSERT INTO job_bom_subst
		(wo_id,oper_id,seq_no,bom_pos,alt_no,pref,subst_level,item_id,reqd_grade_cd,instruction,qty_per_parent_item,max_qty_per_parent_item,
		 min_qty_per_parent_item,reqd_start_val,reqd_start_val_is_pct,update_inv,backflush,def_reas_cd,def_lot_no,def_sublot_no,def_storage_ent_id,
		 def_reject_ent_id,scaling_factor,must_consume_from_inv,may_choose_alt_inv_loc,may_create_new_lots,must_consume_from_wip,must_consume_before_prod,
		 constant_qty,est_time,spare1,spare2,spare3,spare4,last_edit_by,last_edit_at)
		SELECT @new_wo_id, @new_oper_id, @new_seq_no, @JB_BOM_pos,alt_no,pref,subst_level,item_id,reqd_grade_cd,instruction,qty_per_parent_item,max_qty_per_parent_item,
		 min_qty_per_parent_item,reqd_start_val,reqd_start_val_is_pct,update_inv,backflush,def_reas_cd,def_lot_no,def_sublot_no,def_storage_ent_id,
		 def_reject_ent_id,scaling_factor,must_consume_from_inv,may_choose_alt_inv_loc,may_create_new_lots,must_consume_from_wip,must_consume_before_prod,
		 constant_qty,est_time,spare1,spare2,spare3,spare4,@last_edit_by,@last_edit_at
		FROM job_bom_subst	WITH (NOLOCK)
		WHERE wo_id = @wo_id AND
		oper_id = @oper_id AND
		seq_no = @seq_no AND
		bom_pos = @JB_BOM_pos

  FETCH NEXT FROM Job_bom_cursor
	INTO @JB_wo_id, @JB_oper_id, @JB_seq_no, @JB_BOM_pos,
		@JB_item_id, @JB_reqd_grade_cd, @JB_instruction, @JB_qty_per_parent_item, @JB_max_qty_per_parent_item,
		@JB_min_qty_per_parent_item, @JB_reqd_start_val, @JB_reqd_start_val_is_pct, @JB_update_inv, @JB_backflush,
		@JB_def_reas_cd, @JB_def_lot_no, @JB_def_sublot_no, @JB_def_storage_ent_id, @JB_scaling_factor, @JB_must_consume_from_inv, -- Added "@JB_def_sublot_no" 1/12/07 KRF
		@JB_may_choose_alt_inv_loc, @JB_may_create_new_lots, @JB_must_consume_from_wip, @JB_must_consume_before_prod,
		@JB_constant_qty, @JB_est_time, @JB_spare1, @JB_spare2, @JB_spare3, @JB_spare4, @JB_mod_id
  END
  CLOSE Job_bom_cursor
  DEALLOCATE Job_bom_cursor
END

