CREATE PROCEDURE [dbo].[sp_i_job_exec_clonejob_noroute]
(
  @wo_id					STRING40_NULL = NULL,
  @oper_id					STRING40_NULL = NULL,
  @seq_no					INT32_NULL = NULL,
  @user_id					STRING40_NULL = NULL,
  @new_wo_id				STRING40_NULL = NULL,
  @new_oper_id				STRING40_NULL = NULL,
  @new_seq_no				INT32_NULL = NULL,
  @req_qty					TFLOAT_NULL = NULL,
  @start_qty				TFLOAT_NULL = NULL,
  @new_state_cd				INT32_NULL = NULL,
  @req_finish_time			TDATETIME_NULL = NULL,
  @target_ent_id			INT32_NULL = NULL,
  @status_notes				STRING254_NULL = NULL,
  @time_zone_bias_value		INT32_NULL = NULL
) AS
-- ***********************************************************************************************************************
-- Module Name          -
-- Description          -
-- Author          -
-- TDATETIME Created          -    10/21/2002
-- Version          - 2.0.0.33
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- TDATETIME_Modified  Modified_By   Ver   Changes
-- 12/20/02    Chandresh    1.5.0 Insert into Job was cloning qty_prod which must be 0 while a record is cloned. HD #698
-- 01/09/2003    Rohit        1.5.2 Added string Id reference to err messages.
-- 08/25/2003   Sheetal Jain    1.6.0 Added spc characteristics to be brought over for the job
-- 04/30/2004      Sheetal Jain    2033    Double the character variable lengths to support multibyte character
--05/16/2005    Raghu        2.1.21    HD# 5674, Clone Job BOM does not write the supplied state_cd
--                                    Also, CURSOR is removed. The query always contains primary key values and never
--                                    returns more than 1 row.
--12/28/2005    Raghu        3.1.6    HD# 5678, Part of DB Changes
--09/15/2006    Raghu        3.1.22    HD# 8676, Jobs window/cloning a wo or a job
--07/24/2007    Raghu       3.3.1   HD# 10081, Change shift_start with *_utc and *_local.
--09/19/2007    Raghu       3.3.1   The new job should use the required quantity if supplied; otherwise default to the existing value.
--01/21/2008	Raghu		3.4		L00073299; Entry of Production Rates is cumbersome,...
--03/05/2008	Raghu		3.4		L00075524; Load Test: Receiving a series of exceptions (similar to"Conversion failed when converting the nvarchar value 'u7-' to datatype int") when running a load test with a series of logon, add productions and logoffs.
--11/13/2009	Kishore		4.0		HF# 1432, Part of Date/Timezone Changes
--10/08/2012	  Arun          4.6      spc_char_job is removed from the database
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN

	SET NOCOUNT ON

	DECLARE	@req_finish_time_utc tdatetime,
	@StoO_error		INT32,
	@StoO_errmsg		STRING254,
	@row_count		INT32,
	@standard_time_to_do_this_job     TFLOAT,
	@lst_for_this_job_utc     TDATETIME,
	@lst_for_this_job_local  TDATETIME,
	@J_wo_id NVARCHAR(80),
	@J_oper_id NVARCHAR(80),
	@J_seq_no INT32,
	@J_job_desc NVARCHAR(80),
	@J_item_id NVARCHAR(80),
	@J_state_cd INT32,
	@J_job_priority INT32,
	@J_req_finish_time_utc TDATETIME,
	@J_req_finish_time_local TDATETIME,
	@J_init_sched_ent_id INT32,
	@J_target_sched_ent_id INT32,
	@J_run_ent_id INT32,
	@J_qty_reqd TFLOAT,
	@J_qty_prod TFLOAT,
	@J_qty_prod_erp TFLOAT,
	@J_qty_rejected TFLOAT,
	@J_qty_rejected_erp TFLOAT,
	@J_qty_at_start TFLOAT,
	@J_deviation_above TFLOAT,
	@J_deviation_below TFLOAT,
	@J_batch_size TFLOAT,
	@J_first_job LOGICAL,
	@J_final_job LOGICAL,
	@J_sched_pinned LOGICAL,
	@J_check_inv LOGICAL,
	@J_est_fixed_lab TFLOAT,

	@J_est_lab_rate TFLOAT,
	@J_est_setup_time TFLOAT,
	@J_est_teardown_time TFLOAT,
	@J_est_prod_rate TFLOAT,
	@J_prod_uom	INT32,
	@J_est_transfer_time TFLOAT,
	@J_sched_start_time_utc TDATETIME,
	@J_sched_start_time_local TDATETIME,
	@J_latest_start_time_utc TDATETIME,
	@J_latest_start_time_local TDATETIME,
	@J_sched_finish_time_utc TDATETIME,
	@J_sched_finish_time_local TDATETIME,
	@J_act_start_time_utc TDATETIME,
	@J_act_start_time_local TDATETIME,
	@J_act_finish_time_utc TDATETIME,
	@J_act_finish_time_local TDATETIME,
	@J_concurrent_link INT32,
	@J_job_cost TFLOAT,
	@J_parent_contingent_job LOGICAL,
	@J_child_contingent_job LOGICAL,
	@J_notes NVARCHAR(4000),
	@J_assoc_file NVARCHAR(508),
	@J_assoc_file_type NVARCHAR(40),
	@J_status_notes NVARCHAR(2000),
	@J_edited_by NVARCHAR(80),
	@J_edit_time TDATETIME,
	@J_display_seq INT32,
	@J_folder_ver_id NVARCHAR(80),
	@J_rework LOGICAL,
    @J_reworkCd   NVARCHAR(80),
    @J_reworkProcessId NVARCHAR(80),
	@JR_wo_id     NVARCHAR(80),
	@JR_oper_id     NVARCHAR(80),
	@JR_seq_no     INT32,
	@JR_input_oper_id     NVARCHAR(80),
	@JR_input_seq_no     INT32,
	@JR_input_percent     TFLOAT,
	@JR_mod_id     INT32,
	@last_edit_at TDATETIME,
	@last_edit_by    NVARCHAR(80),
	@V_Client_Info    NVARCHAR(40),
	@job_state_cd    INT32,
	@J_spare1             NVARCHAR(80),
	@J_spare2             NVARCHAR(80),
	@J_spare3             NVARCHAR(80),
	@J_spare4             NVARCHAR(80),
	@tz_temp INT32


	 SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

	  SET @tz_temp = -@time_zone_bias_value

	EXEC sp_S_GetUtcDate @req_finish_time, @tz_temp, @req_finish_time_utc OUTPUT
    EXEC sp_S_Db_Status_GetAudTrailUsr @last_edit_by OUTPUT, @V_Client_Info OUTPUT

	SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

    IF  ( @new_wo_id IS NULL) AND ( @new_oper_id IS NULL) AND ( @new_seq_no IS NULL) BEGIN
        RAISERROR( 'Atleast one of the new_wo_id,new_oper_id or new_seq_no must be specified{3273}', 16, 1 )
        RETURN
    END

    SELECT	@J_wo_id = wo_id, @J_oper_id = oper_id, @J_seq_no = seq_no, @J_job_desc = job_desc, @J_item_id = item_id, @J_state_cd = state_cd,
			@J_job_priority = job_priority, @J_req_finish_time_utc = req_finish_time_utc, @J_req_finish_time_local = req_finish_time_local,
			@J_init_sched_ent_id = init_sched_ent_id, @J_target_sched_ent_id = target_sched_ent_id,
			@J_run_ent_id = run_ent_id, @J_qty_reqd = qty_reqd, @J_qty_prod = qty_prod, @J_qty_prod_erp = qty_prod_erp,
			@J_qty_rejected = qty_rejected, @J_qty_rejected_erp = qty_rejected_erp, @J_qty_at_start = qty_at_start,
			@J_deviation_above = deviation_above, @J_deviation_below = deviation_below, @J_batch_size = batch_size, @J_first_job = first_job,
			@J_final_job = final_job, @J_sched_pinned = sched_pinned, @J_check_inv = check_inv, @J_est_fixed_lab = est_fixed_lab,
			@J_est_lab_rate = est_lab_rate, @J_est_setup_time = est_setup_time, @J_est_teardown_time = est_teardown_time,
			@J_est_prod_rate = est_prod_rate, @J_prod_uom = prod_uom, @J_est_transfer_time = est_transfer_time, @J_sched_start_time_utc = sched_start_time_utc,
			@J_sched_start_time_local = sched_start_time_local, @J_latest_start_time_utc = latest_start_time_utc,
			@J_latest_start_time_local = latest_start_time_local, @J_sched_finish_time_utc = sched_finish_time_utc,
			@J_sched_finish_time_local = sched_finish_time_local, @J_act_start_time_utc = act_start_time_utc,
			@J_act_start_time_local = act_start_time_local, @J_act_finish_time_utc = act_finish_time_utc,
			@J_act_finish_time_local = act_finish_time_local, @J_concurrent_link = concurrent_link, @J_job_cost = job_cost,
			@J_parent_contingent_job = parent_contingent_job, @J_child_contingent_job = child_contingent_job,
			@J_notes = notes, @J_assoc_file = assoc_file, @J_assoc_file_type = assoc_file_type, @J_status_notes = status_notes,
			@J_edited_by = edited_by, @J_edit_time = edit_time, @J_display_seq = display_seq, @J_folder_ver_id = folder_ver_id,
			@J_rework = rework, @J_reworkCd = rework_cd, @J_reworkProcessId = rework_process_id, @J_spare1 = spare1, @J_spare2 = spare2,
            @J_spare3 = spare3, @J_spare4 = spare4
    FROM JOB WITH (NOLOCK)
    WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no

	IF @J_wo_id IS NULL BEGIN
		--The Job to be cloned does not exist, so throw the error
		RAISERROR('The Job to be cloned does not exist{3275}', 16, 1)
		RETURN
	END

	SET @new_wo_id = ISNULL(@new_wo_id, @wo_id)
	SET @new_oper_id = ISNULL(@new_oper_id, @oper_id)

	IF  @new_seq_no IS NULL BEGIN
		IF  ( @new_wo_id = @wo_id) AND ( @new_oper_id = @oper_id) BEGIN
			SELECT @new_seq_no = MAX(seq_no) + 1 FROM JOB
			WHERE wo_id = @wo_id AND oper_id = @oper_id
		END ELSE BEGIN
			SET @new_seq_no = @seq_no
		END
	END

	--Check whether the new job is already exists, if exists throw the error
	SET @J_wo_id = NULL;

	SELECT @J_wo_id = wo_id FROM JOB WHERE wo_id = @new_wo_id AND oper_id = @new_oper_id AND seq_no = @new_seq_no

	IF ( @j_wo_id IS NOT NULL ) BEGIN
		--means the new job is already exists, so throw the error
		RAISERROR('The new Job is already exists{3274}', 16, 1)
		RETURN
	END

	IF (@new_state_cd IS NULL) BEGIN
		SET @job_state_cd = @J_state_cd
		IF NOT (@job_state_cd = 1 OR @job_state_cd = 2) BEGIN
		   SET @job_state_cd = 1
		END
	END
	ELSE BEGIN
		IF (@new_state_cd = 3)
			SET @job_state_cd = 2
		ELSE
			SET @job_state_cd = @new_state_cd
	END

	SELECT	@req_qty = ISNULL(@req_qty, @J_qty_reqd)
		,	@start_qty = ISNULL( @start_qty, @J_qty_at_start)
		,	@req_finish_time_utc = ISNULL( @req_finish_time_utc, @J_req_finish_time_utc)
		,	@req_finish_time = ISNULL( @req_finish_time, @J_req_finish_time_local)
		,	@target_ent_id = ISNULL( @target_ent_id, @J_target_sched_ent_id)
		,	@status_notes = ISNULL( @status_notes, 'Created by Job Clone')
		,	@J_edit_time = @last_edit_at

	--5.        calculate latest start time (JOB table) by using req_qty and req_finish_time

    SET @standard_time_to_do_this_job = @J_est_setup_time + @J_est_teardown_time + @J_est_transfer_time + (dbo.fn_CONVERTPRODRATETOHRSPERBATCH(@J_est_prod_rate, @J_prod_uom) * @start_qty)

    SET @lst_for_this_job_utc = @req_finish_time_utc + ((-ROUND(ROUND( CONVERT( INT, @standard_time_to_do_this_job ), 0), 0)) /24)
    SET @lst_for_this_job_local = DATEADD( mi, @time_zone_bias_value, @req_finish_time_utc )

    --4.        Clone JOB table row (everything but wo_id, seq_no, state_cd,  req_finish_time, run_ent_id,
    --qty_reqd, qty_prod, qty_prod_erp, qty_rejected, qty_rejected_erp, qty_at_start,
    --sched_pinned, sched_start_time, sched_finish_time, act_start_time,
    --act_finish_time, concurrent_link, status_notes, edited_by, edit_time
    INSERT INTO JOB
	(
		wo_id, oper_id, seq_no, job_desc, item_id, state_cd, job_priority, req_finish_time_utc, req_finish_time_local, init_sched_ent_id,
		target_sched_ent_id, run_ent_id, qty_reqd, qty_prod, qty_prod_erp, qty_rejected, qty_rejected_erp, qty_at_start,
        deviation_above, deviation_below, batch_size, first_job, final_job, sched_pinned, check_inv, est_fixed_lab, est_lab_rate,
		est_setup_time, est_teardown_time, est_prod_rate, prod_uom, est_transfer_time, sched_start_time_utc, sched_start_time_local, latest_start_time_utc,
		latest_start_time_local, sched_finish_time_utc, sched_finish_time_local, act_start_time_utc, act_start_time_local, act_finish_time_utc,
		act_finish_time_local , concurrent_link, job_cost, parent_contingent_job, child_contingent_job, notes, assoc_file, assoc_file_type,
		status_notes, edited_by, edit_time, display_seq, folder_ver_id, rework, rework_cd, rework_process_id, spare1, spare2, spare3, spare4
	)
    VALUES (@new_wo_id, @new_oper_id, @new_seq_no,
                @J_job_desc,@J_item_id, @job_state_cd, @J_job_priority,
                @req_finish_time_utc,    @req_finish_time, @J_init_sched_ent_id, @target_ent_id,
                NULL, @req_qty, 0, NULL,0, NULL,@start_qty, @J_deviation_above,
                @J_deviation_below,
                @J_batch_size, @J_first_job, @J_final_job,
                0, @J_check_inv, @J_est_fixed_lab, @J_est_lab_rate,
                @J_est_setup_time, @J_est_teardown_time,@J_est_prod_rate, @J_prod_uom,
                @J_est_transfer_time, NULL, NULL,
                @lst_for_this_job_utc, @lst_for_this_job_local, NULL, NULL,
                NULL,NULL, NULL, NULL, 0,@J_job_cost, @J_parent_contingent_job, @J_child_contingent_job,
                @status_notes,@J_assoc_file,
                @J_assoc_file_type, NULL,    @last_edit_by,@J_edit_time,
                @J_display_seq, @J_folder_ver_id,
                @J_rework, @J_reworkCd, @J_reworkProcessId, @J_spare1, @J_spare2, @J_spare3,
                @J_spare4)

	--8.    Clone*** JOB_STEP table row(s)*.
	EXEC sp_I_Job_Exec_CloneJob_Step @wo_id, @oper_id, @seq_no, @new_wo_id, @new_oper_id, @new_seq_no

	--6.    Clone JOB_BOM table row(s)* and then Clone JOB_BOM_STEP table row(s)*.
	EXEC sp_I_Job_Exec_CloneJob_Bom @wo_id, @oper_id, @seq_no, @new_wo_id,  @new_oper_id, @new_seq_no

	--7.    Clone*** JOB_SPEC table row(s)*.
	EXEC sp_I_Job_Exec_CloneJob_Spec @wo_id, @oper_id, @seq_no, @new_wo_id, @new_oper_id, @new_seq_no

	--10     Clone Attributes
	EXEC sp_I_Job_Exec_CloneJob_Attr @wo_id, @oper_id, @seq_no, @new_wo_id, @new_oper_id, @new_seq_no

	--Clone resource job link records.
	INSERT INTO res_job_link (res_id, wo_id, oper_id, seq_no, qty_reqd, last_edit_by, last_edit_at)
	SELECT res_id, @new_wo_id, @new_oper_id, @new_seq_no, ISNULL(@req_qty, qty_reqd), @last_edit_by, @last_edit_at
	FROM res_job_link WITH (NOLOCK)
	WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no

	--Clone data log group records (data_log_grp_job_link)
	INSERT INTO data_log_grp_job_link (grp_id, wo_id, oper_id, seq_no, last_edit_by, last_edit_at)
	SELECT grp_id, @new_wo_id, @new_oper_id, @new_seq_no, @last_edit_by, @last_edit_at
	FROM data_log_grp_job_link WITH (NOLOCK)
	WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no;

	--Clone job_bom_subst records.
	INSERT INTO job_bom_subst (wo_id, oper_id, seq_no, bom_pos, alt_no, pref, subst_level, item_id, reqd_grade_cd,
		instruction, qty_per_parent_item, max_qty_per_parent_item, min_qty_per_parent_item, reqd_start_val,
		reqd_start_val_is_pct, update_inv, backflush, def_reas_cd, def_lot_no, def_storage_ent_id, def_reject_ent_id,
		scaling_factor, must_consume_from_inv, may_choose_alt_inv_loc, may_create_new_lots, must_consume_from_wip,
		must_consume_before_prod, constant_qty, est_time, spare1, spare2, spare3, spare4,
		last_edit_by, last_edit_at)
	SELECT @new_wo_id, @new_oper_id, @new_seq_no,
		bom_pos, alt_no, pref, subst_level, item_id, reqd_grade_cd,
		instruction, qty_per_parent_item, max_qty_per_parent_item, min_qty_per_parent_item, reqd_start_val,
		reqd_start_val_is_pct, update_inv, backflush, def_reas_cd, def_lot_no, def_storage_ent_id, def_reject_ent_id,
		scaling_factor, must_consume_from_inv, may_choose_alt_inv_loc, may_create_new_lots, must_consume_from_wip,
		must_consume_before_prod, constant_qty, est_time, spare1, spare2, spare3, spare4,
		@last_edit_by, @last_edit_at
	FROM job_bom_subst WITH (NOLOCK)
	WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no;

	IF (@job_state_cd = 2) begin
		  EXEC SP_I_JOB_EXEC_CLONEJOB_CHKSTAT @new_wo_id, @new_oper_id, @new_seq_no
	END

END

