--===================================================================================================================
-- Name:		sp_I_ofi_AddMasterRecipe
-- Description:	The stored procedure will create new master recipe that called from the WF
--	
-- Usage:		AddMasterRecipe
-- ===================================================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-07-04			Initial version.
-- 0.02.00	YG				2022-10-24			Add flag for audit trail in the parameter
-- 0.03.00	AP				2023-05-03			Added the audit trail comment with@recipe_name and @recipe_version
-- ===================================================================================================================

CREATE Procedure [dbo].[sp_I_ofi_AddMasterRecipe_y2025m09d15]
	@recipe_name NVARCHAR(80) = NULL,
	@recipe_version FLOAT = NULL,
	@ent_id INT = NULL,
	@item_id NVARCHAR(40) = NULL,
	@recipe_active NVARCHAR(1) = 'N',
	@recipe_preferred NVARCHAR(1) = 'N',
	@note NVARCHAR(250) = NULL,
	@user_name NVARCHAR(100) = NULL,
	@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail

AS 
BEGIN
	DECLARE @strErrorMessage NVARCHAR(255),
			@iErrorValue INT = 0,
			@bRecipePrefered BIT,
			@iRecipeVersion INT,
			@strEntName NVARCHAR(80),
			@strMaterialName NVARCHAR(80),
			@nRecipeName NVARCHAR(80),
			@mod NVARCHAR(30),
			@iRecipeRowId INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MRM_MasterRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'add',
			@strCommentMsg NVARCHAR(200) ='Recipe:'+@recipe_name+' Version:'+ CAST(CAST(@recipe_version AS INT)AS varchar)+ ' created From [dbo].[sp_I_ofi_AddMasterRecipe]'
		
	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Convert recipe version (float) into (integer)	
	SET @iRecipeVersion = CAST(@recipe_version AS INT);

	-- Retrieve equipment name and material name
	SELECT @strEntName = ent_name 
	FROM ent WITH (NOLOCK) 
	WHERE ent_id = @ent_id

	SELECT @strMaterialName = item_desc 
	FROM item WITH (NOLOCK) 
	WHERE item_id = @item_id

	-- Interlock #1 validate recipe active and recipe preferred value are consistent
	IF (@recipe_preferred = 'Y' and @recipe_active = 'N')
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Recipe should be set in active if set as preferred recipe'
		RAISERROR ('@@MRWFErrorActiveandPreferredRecipeInconsistent@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- Interlock #2 check if any same recipe version for the selected item
	IF EXISTS(	SELECT TOP 1 1 
					FROM ofi_master_recipe WITH(NOLOCK)
				WHERE 
					item_id = @item_id 
					AND ent_id = @ent_id
					AND version = @recipe_version )
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Recipe version is already available in the system'
		RAISERROR ('@@MRWFErrorRecipeVersionAlreadyAvailable@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	IF (@iErrorValue >= 0)
	BEGIN
		-- if new recipe set as preferred
		-- then update into non preferred for other recipe 
		IF (@recipe_preferred = 'Y')
		BEGIN
			-- Validate if any current preferred recipe available then set into not preferred
			IF (EXISTS(	SELECT 1
						FROM ofi_master_recipe WITH (NOLOCK) 
						WHERE item_id = @item_id 
								AND ent_id = @ent_id
								AND preferred = 'Y'))
			BEGIN
				-- Get the current preferred recipe 
				SELECT @nRecipeName = recipe_name
				FROM ofi_master_recipe WITH (NOLOCK) 
				WHERE item_id = @item_id 
						AND ent_id = @ent_id
						AND preferred = 'Y'

				EXEC [dbo].[sp_U_ofi_UpdateRecipe] 
					@item_id = @item_id,
					@ent_id = @ent_id,
					@recipe_name = @nRecipeName,
					@recipe_preferred = 'N',
					@recipe_active = null,
					@audit_comments = 'Updated From [dbo].[sp_I_ofi_AddMasterRecipe]',
					@user_name = @user_name
			END
			
		END

		-- convert preferred recipe value into the value is match with bom_ver table requirement
		IF (@recipe_preferred = 'Y')
			SET @bRecipePrefered = 1
		ELSE 
			SET @bRecipePrefered = 0

		-- insert bom_ver as a requirement before writing to the bom_item table
		EXEC sp_I_Bom_Ver
		   @parent_item_id = @item_id,
		   @ver_id = @iRecipeVersion ,
		   @ver_date = NULL ,
		   @ver_date_tz = NULL ,
		   @ver_comments = @note,
		   @preferred_ver = @bRecipePrefered,
		   @disassembly = 0,
		   @start_eff  = NULL,
		   @start_eff_tz = NULL ,
		   @end_eff = NULL ,
		   @end_eff_tz =NULL ,
		   @last_edit_comment = @strCommentMsg ,
		   @time_zone_bias_value  = NULL ,
		   @mod_id = @mod

		-- insert record into the master recipe
		INSERT into [dbo].ofi_master_recipe (
			ent_id,
			item_id,
			recipe_name,
			version,
			preferred,
			is_active,
			notes,
			created_at_utc,
			created_at_local,
			created_by
		)values(
			@ent_id,
			@item_id,
			@recipe_name,
			@iRecipeVersion,
			@recipe_preferred,
			@recipe_active,
			@note,
			GETUTCDATE(),
			GETDATE(),
			@user_name
		)

		-- Get The RowId from ofi_master_recipe table
		SELECT @iRecipeRowId = @@IDENTITY

		IF (@audit_trail = 1)
		BEGIN
			-- Insert entry in Audit Trial starts
			DELETE @auditTrailParameters;
			INSERT INTO @auditTrailParameters
			(
				row_id, 
				field_name, 
				field_value
			) 
			VALUES 
			(
				@iRecipeRowId, 
				'@MaterialId', 
				@item_id
			),
			(
				@iRecipeRowId, 
				'@EquipmentId', 
				CAST(@ent_id AS NVARCHAR(40))
			),
			(
				@iRecipeRowId,
				'@Version',
				CAST(@iRecipeVersion AS NVARCHAR(40))
			),
			(
				@iRecipeRowId,
				'@RecipeName',
				@recipe_name
			),
			(
				@iRecipeRowId,
				'@Preferred',
				@recipe_preferred
			),
			(
				@iRecipeRowId,
				'@Active',
				@recipe_active
			),
			(
				@iRecipeRowId,
				'@Notes',
				@note
			)

			EXEC sp_I_ofi_AuditTrail 
				@module_id = @strModuleName,
				@function_id = @strFunctionName,
				@auditTrailParameters = @auditTrailParameters,
				@user_id = @user_name,
				@activity = @strActivityMsg,
				@audit_category = 'Info',
				@comments = @strCommentMsg,
				@keyField1   = @strEntName,
				@keyField2   = @strMaterialName

		END
	END

END

