--===========================================================================================
-- Name:    FN_S_ofi_dcsHU_to_SAPHU
-- Description:  generate SAP HU number based on DCS HU number
--
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  AML, XPM    2026-05-08         Initial function version based on SP_S_ofi_dcsHU_to_SAPHU.
-- ===========================================================================================
CREATE   FUNCTION [dbo].[fn_s_ofi_dcsHU_to_SAPHU]
(
	@HUNumber NVARCHAR(80) = NULL, -- DCS HU Number
	@wo_id VARCHAR(100),
	@oper_id VARCHAR(100),
	@seq_no INT
)
RETURNS NVARCHAR(20)
AS
BEGIN
	DECLARE @SAPNumber NVARCHAR(20),
			@plant_code INT,
			@line_no VARCHAR(10),
			@line_ent INT,
			@year_sap NVARCHAR(2),
			@job_year INT,
			@job_decade INT,
			@job_year_digit INT,
			@dcs_year_digit INT,
			@resolved_year INT;

	-- Get the line number
	SELECT DISTINCT @line_ent = e.parent_ent_id
	FROM job ip WITH(NOLOCK) 
		INNER JOIN ent e WITH(NOLOCK) 
			ON e.ent_id = ip.run_ent_id
		INNER JOIN ent_attr ea WITH(NOLOCK) 
			ON ea.ent_id = e.parent_ent_id
		INNER JOIN ent ee WITH(NOLOCK) 
			ON ee.ent_id = ea.ent_id
	WHERE ea.attr_value = 'Line'
	  AND ip.wo_id = @wo_id
	  AND ip.oper_id = @oper_id
	  AND ip.seq_no = @seq_no;

	SELECT @line_no = ea.attr_value
	FROM ent_attr ea WITH(NOLOCK) 
		INNER JOIN attr A WITH(NOLOCK) 
			ON A.attr_id = ea.attr_id
	WHERE A.attr_desc = 'LineCode' 
	  AND ea.ent_id = @line_ent;

	SET @line_no = CAST(RIGHT(@line_no, 1) AS VARCHAR(10));

	-- Get the plant code
	SELECT @plant_code = attr_value 
	FROM system_attr WITH(NOLOCK) 
	WHERE attr_desc = 'HUPlantCode';

	-- Get the job year
	SELECT TOP 1
		@job_year = YEAR(j.act_start_time_local)
	FROM job j WITH(NOLOCK)
	WHERE j.wo_id = @wo_id
	  AND j.oper_id = @oper_id
	  AND j.seq_no = @seq_no;

	-- Get the year digit from the HU number sent by DCS
	SET @dcs_year_digit = TRY_CONVERT(INT, SUBSTRING(@HUNumber, 2, 1));

	IF @job_year IS NULL OR @dcs_year_digit IS NULL
	BEGIN
		RETURN NULL;
	END;

	SET @job_decade = (@job_year / 10) * 10;
	SET @job_year_digit = @job_year % 10;

	IF @dcs_year_digit >= @job_year_digit
	BEGIN
		SET @resolved_year = @job_decade + @dcs_year_digit;
	END
	ELSE
	BEGIN
		SET @resolved_year = @job_decade + 10 + @dcs_year_digit;
	END;

	SET @year_sap = RIGHT(CAST(@resolved_year AS VARCHAR(4)), 2);

	-- Get the info from the HU number
	SET @SAPNumber = CONCAT(
		@plant_code,
		@line_no,
		LEFT(@HUNumber, 1),             
		@year_sap,                     
		SUBSTRING(@HUNumber, 3, 2),     
		SUBSTRING(@HUNumber, 5, 2),     
		RIGHT(@HUNumber, 3),            
		'0'                             
	);

	RETURN @SAPNumber;
END

