--===========================================================================================
-- Name:        sp_I_ofi_qm_AUT_ProcessSampleRequest
-- Description: Replaces AUT Sample Request WF logic.
--              Validates AUT sample request and creates the sample if validation succeeds.
--
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  AML, XPM    2026-05-14         Initial version following the WF logic.
-- 0.01.01  AML, XPM    2026-06-25         Added error codes (71, 72, 73) for better tracking.
-- 0.02.00  AML, XPM    2026-07-01          Fix for error handling.
-- 0.02.01	AML, XPM	2026-07-15		   Added CB parameters.
-- ===========================================================================================

CREATE   PROCEDURE [dbo].[sp_I_ofi_qm_AUT_ProcessSampleRequest]
(
    @ent_name NVARCHAR(40),
    @frequency NVARCHAR(40) = NULL,
    @wo_id NVARCHAR(40) = NULL,
    @plevel NVARCHAR(40) = NULL,
    @stage NVARCHAR(40) = NULL,
    @seq_no INT = NULL,
	@CBWoId NVARCHAR(40) = NULL, --V2.01
    @CBSeqNo INT = NULL,		 --V2.01
    @CBSublotNo INT = NULL,		 --V2.01
    @sample_id INT = 0 OUTPUT,
    @status_output INT = 1 OUTPUT,
    @message_output NVARCHAR(4000) = '' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ValidationResult TABLE
    (
        IsValid INT
    );

    SET @sample_id = 0;
    SET @status_output = 1;
    SET @message_output = '';

	DECLARE @ent_id INT, 
			@mes_oper_id NVARCHAR(40),
			@mes_wo_id NVARCHAR(40),
			@start INT, 
            @end INT;

	SELECT @ent_id = e.ent_id 
	FROM ent e WITH (NOLOCK)
	WHERE e.ent_name = @ent_name


	SELECT	 @mes_wo_id = w.wo_id
			,@mes_oper_id = output_operid
	FROM ufn_ofi_mes_aut_orderid(@wo_id, @seq_no, @ent_id) wa
	LEFT OUTER JOIN wo w WITH (NOLOCK) ON w.wo_id = wa.output_woid
 
    BEGIN TRY

        INSERT INTO @ValidationResult
        EXEC [dbo].[sp_S_ofi_qm_AUT_ValidateSampleRequest]
             @ent_id = @ent_id,
             @frequency = @frequency,
             @wo_id = @mes_wo_id,
             @autitem_id = NULL,-- autitemid is not currently used by the sample validation logic
             @oper_id = @mes_oper_id,
             @plevel = @plevel,
             @stage = @stage,
             @seq = @seq_no,
			 @CBWoId = @CBWoId,			--V2.01
			 @CBSeqNo = @CBSeqNo,		--V2.01
			 @CBSublotNo = @CBSublotNo;	--V2.01

    END TRY
    BEGIN CATCH

        SET @status_output = 71;
        SET @message_output = CONCAT(
            'AUT sample request validation failed. ',
            ERROR_MESSAGE()
        );

        SET @start  = LEN(@message_output) - CHARINDEX('{', REVERSE(@message_output)) + 1;

			-- Find the corresponding closing brace
		SET @end  = CHARINDEX('}', @message_output, @start);

			-- Remove the substring if both braces are found
		IF @start > 0 AND @end > 0
		BEGIN
			SET @message_output = STUFF(@message_output, @start, @end - @start + 1, '');
		END

		PRINT 'FIXING_MESSAGE:sample_id:'+TRY_CONVERT(NVARCHAR(10),@sample_id)+';status_output:'+TRY_CONVERT(NVARCHAR(10),@status_output)+';message_output:'+@message_output
			

        SELECT
            @status_output AS status_output,
            @message_output AS message_output,
            @sample_id AS sample_id;

        RETURN 0;

    END CATCH;

    IF NOT EXISTS (
        SELECT 1
        FROM @ValidationResult
        WHERE IsValid = 1
    )
    BEGIN
        SET @status_output = 72;
        SET @message_output = 'AUT sample request validation failed. No valid response was returned.';


        SET @start  = LEN(@message_output) - CHARINDEX('{', REVERSE(@message_output)) + 1;

			-- Find the corresponding closing brace
		SET @end  = CHARINDEX('}', @message_output, @start);

			-- Remove the substring if both braces are found
		IF @start > 0 AND @end > 0
		BEGIN
			SET @message_output = STUFF(@message_output, @start, @end - @start + 1, '');
		END

		PRINT 'FIXING_MESSAGE:sample_id:'+TRY_CONVERT(NVARCHAR(10),@sample_id)+';status_output:'+TRY_CONVERT(NVARCHAR(10),@status_output)+';message_output:'+@message_output
			

        SELECT
            @status_output AS status_output,
            @message_output AS message_output,
            @sample_id AS sample_id;

        RETURN 0;
    END;

    BEGIN TRY

        EXEC [dbo].[sp_I_ofi_qm_AUT_samplecreationrequest]
             @ent_id = @ent_id,
             @frequency = @frequency,
             @wo_id = @mes_wo_id,
             @autitem_id = NULL, -- autitemid is not currently used by the sample creation logic
             @oper_id = @mes_oper_id,
             @plevel = @plevel,
             @stage = @stage,
             @seq = @seq_no,
             @username = NULL, -- username is not currently used by the sample creation logic
             @sample_id = @sample_id OUTPUT,
			 @CBWoId = @CBWoId,			--V2.01
			 @CBSeqNo = @CBSeqNo,		--V2.01
			 @CBSublotNo = @CBSublotNo;	--V2.01

    END TRY
    BEGIN CATCH

        SET @status_output = 73;
        SET @message_output = CONCAT(
            'AUT sample creation failed. ',
            ERROR_MESSAGE()
        );

        SET @start  = LEN(@message_output) - CHARINDEX('{', REVERSE(@message_output)) + 1;

			-- Find the corresponding closing brace
		SET @end  = CHARINDEX('}', @message_output, @start);

			-- Remove the substring if both braces are found
		IF @start > 0 AND @end > 0
		BEGIN
			SET @message_output = STUFF(@message_output, @start, @end - @start + 1, '');
		END

		PRINT 'FIXING_MESSAGE:sample_id:'+TRY_CONVERT(NVARCHAR(10),@sample_id)+';status_output:'+TRY_CONVERT(NVARCHAR(10),@status_output)+';message_output:'+@message_output
			

        SELECT
            @status_output AS status_output,
            @message_output AS message_output,
            @sample_id AS sample_id;

        RETURN 0;

    END CATCH;

    SET @status_output = 5;
    SET @message_output = 'Success';

    SELECT
        @status_output AS status_output,
        @message_output AS message_output,
        @sample_id AS sample_id;

    RETURN 0;
END

