CREATE PROCEDURE [dbo].[SP_U_OFI_STQTY_DETAILS_GETBYKEY] (
    @ssu AS int,
    @dsu AS int,
    @aut_item_id AS int,
    @ent_id INT,
    @transQty FLOAT,
    @rowId INT=NULL,
    @from_site_name NVARCHAR(40) OUTPUT,
    @line_ent_name NVARCHAR(80) OUTPUT,
    @from_ent_id INT OUTPUT,
    @to_ent_id NVARCHAR(40) OUTPUT,
    @from_ent_name NVARCHAR(80) OUTPUT,
    @to_ent_name NVARCHAR(80)  OUTPUT,
    @item_id NVARCHAR(40) OUTPUT,
    @lot_no NVARCHAR(80) OUTPUT,
    @sublot_no NVARCHAR(80) OUTPUT,
    @from_grade_desc NVARCHAR(80) OUTPUT,
    @from_status_desc NVARCHAR(80) OUTPUT,
    @to_item_id NVARCHAR(40) OUTPUT,
    @to_item_grade NVARCHAR(80) OUTPUT,
    @blocked_state NVARCHAR(80)OUTPUT,
    @infomessage VARCHAR(MAX) OUTPUT,
    @submessage VARCHAR(MAX) OUTPUT,
    @ischk_message INT OUTPUT,
    @finaltransQty FLOAT OUTPUT,
    @reclassify INT OUTPUT,
    @trasnferUODMDesc NVARCHAR(100) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @default_grade NVARCHAR(30),
        @unq_item_id NVARCHAR(30),
        @mesItemId NVARCHAR(80),
        @auto_reclass_attr_value nvarchar(50) = 'false',
        @bfq_id int,
        @bfq_desc nvarchar(10),
        @attrOmarDesc VARCHAR(40) = 'auto_reclassify',
        @uniqIdAttrDesc VARCHAR(100) = 'unique_item_id',
        @defGradecAttr VARCHAR(100) = 'default_grade',
        @bfqAttr VARCHAR(40) = 'BlockForQuality',
        @attr_id_SUNumberInAUT INT,
        @srcQtyLeft FLOAT,
        @destQtyLeft FLOAT,
        @destMaxCapacity FLOAT,
        @transferType INT,
        @maxcapUomId INT,
        @itemUOMId INT,
        @convFactor FLOAT,
        @offset FLOAT,
        @targetQty FLOAT=0,
        @transferredQty FLOAT=0,
        @AUTdefUOM NVARCHAR(100),
        @factor float,
        @linebreak char(10) = '. ',
        @srcItemId NVARCHAR(80) = '';

    DECLARE @su_attr AS TABLE (
        attr_id int,
        attr_desc nvarchar(80),
        attr_value STRING1700_NULL
    )
    
    DECLARE @itemInvtemp AS TABLE (
        ent_id int,
        qty_left FLOAT,
        lot_no NVARCHAR(40),
        sublot_no NVARCHAR(40),
        item_id NVARCHAR(80),
        item_grade_desc NVARCHAR(80),
        item_status_desc NVARCHAR(80)
    )
        
    SET @ischk_message = 0
    SET @trasnferUODMDesc = NULL
    SET @finaltransQty = @transQty
    SET @infoMessage = ''
    
    SELECT @attr_id_SUNumberInAUT=attr_id
    FROM attr WITH (NOLOCK)
    WHERE attr_desc = 'SUNumberInAUT' AND attr_grp = 2
    
    --GET MES ITEM ID
    SELECT @item_id = item_id
    FROM item
        CROSS APPLY ufn_ofi_mes_aut_itemid(item.item_id, 1) AS autitem
    WHERE autitem.aut_item_id = CAST(@aut_item_id AS NVARCHAR)
    
    --GET ENTITY INFORMATION
    SELECT @line_ent_name = ent.ent_name, @from_site_name = ents.ent_name
    FROM ent WITH (NOLOCK)
        LEFT JOIN ent AS ents WITH (NOLOCK)
            ON ent.site = ents.ent_id
    WHERE ent.ent_id = @ent_id
    
    
    --GET MES SOURCE SILO ID
    SELECT
        @from_ent_id = ent.ent_id,
        @from_ent_name = ent.ent_name
    FROM ent WITH (NOLOCK)
        INNER JOIN [dbo].ent_attr AS ea WITH (NOLOCK)
            ON ea.ent_id = ent.ent_id
            AND ea.attr_id = @attr_id_SUNumberInAUT
            AND attr_value = CAST(@ssu AS VARCHAR(80))
        LEFT JOIN dbo.site WITH (NOLOCK)
            ON ent.ent_id=site.ent_id
    
    --SET MESSAGE SUBJECT
    SET @submessage = dbo.fn_s_ofi_getLangString(400026,NULL,NULL)
    
    --GET MES DESTINATION SILO ID
    SELECT
        @to_ent_id = ent.ent_id,
        @to_ent_name = ent.ent_name
    FROM ent WITH (NOLOCK)
        INNER JOIN [dbo].ent_attr AS ea WITH (NOLOCK)
            ON ea.ent_id=ent.ent_id
            AND ea.attr_id = @attr_id_SUNumberInAUT
            AND attr_value = CAST(@dsu AS VARCHAR(80))
    
    --VERIFY Item_id reveived from AUT is same
    SELECT @srcItemId = src_item_id
    FROM ofi_st_trans_selection WITH (NOLOCK)
    WHERE ent_id = @ent_id
        AND src_su_ent_id = @from_ent_id
        AND is_active = 1
        AND transfer_status_cd = 3
    
    IF(@item_id <> @srcItemId)
    BEGIN
        SET @ischk_message = 2 -- Added for rejecting message in Workflow
        SET @submessage = dbo.fn_s_ofi_getLangString(400027, NULL, NULL)
        SET @infoMessage = CONCAT(
            dbo.fn_s_ofi_getLangString(400023, NULL, NULL),
                @line_ent_name, ', ',
            dbo.fn_s_ofi_getLangString(400024, NULL, NULL),
                @item_id, dbo.fn_GetUOMDesc(@itemUOMId), ', ',
            dbo.fn_s_ofi_getLangString(400025, NULL, NULL),
                @srcItemId, ', ',
            dbo.fn_s_ofi_getLangString(400017, NULL, NULL),
                CAST(isnull(@transQty,0) AS VARCHAR (20)), dbo.fn_GetUOMDesc(@itemUOMId)
        )
    END
    
    --GET MAX CAPACITY FOR DESTINATION SILO
    SELECT
        @destMaxCapacity = ISNULL(max_capacity, 0),
        @maxcapUomId = uom_id
    FROM storage_exec WITH (NOLOCK)
    WHERE ent_id = @to_ent_id
    
    --GET INVENTORY IN TEMP TABLE
    INSERT INTO @itemInvtemp 
    SELECT
        ii.ent_id,
        ii.qty_left,
        lot_no,
        sublot_no,
        ii.item_id,
        item_grade_desc,
        item_status_desc 
    from item_inv AS ii WITH (NOLOCK)
        INNER JOIN item_grade ig WITH (NOLOCK)
            ON ii.grade_cd = ig.item_grade_cd
        INNER JOIN item_state ist WITH (NOLOCK)
            ON ii.status_cd = ist.item_status_cd
    WHERE ent_id IN (@from_ent_id, @to_ent_id)
    
    
    --GET SOURCE SILO INVENTORY
    SELECT @srcQtyLeft = ISNULL(SUM(qty_left), 0)
    FROM @itemInvtemp
    WHERE ent_id = @from_ent_id
        AND item_id = @item_id
    GROUP BY ent_id
    
    --GET DESTINATION SILO INVENTORY
    SELECT @destQtyLeft = ISNULL(SUM(qty_left), 0)
    FROM @itemInvtemp
    WHERE ent_id = @to_ent_id
        AND item_id = @item_id
    GROUP BY ent_id
    
    --QTY. CONVERSION RECEIVED FROM AUT 
    --Get UOM factor 
    DECLARE @UOM_factor table(factor float)
    
    INSERT @UOM_factor
    EXECUTE sp_S_ofi_uomconv_AUT @item_id, @from_ent_id, 'CONS'
    
    SELECT @factor = factor
    FROM @UOM_factor
    
    SET @finaltransQty = [dbo].[fn_ConvertQty](@finaltransQty, ISNULL(@factor, 1), ISNULL(@offset, 0)) 
    
    --ITEM UOM CONVERSION FOR MAX CAPACITY
    SELECT @itemUOMId = uom_id
    FROM item WITH (NOLOCK)
    WHERE item_id = @item_id
    
    --CHECK FOR OVER CONSUMPTION TRANSFER
    IF (@finaltransQty > ISNULL(@srcQtyLeft, 0) AND @ischk_message = 0)
    BEGIN
        SET @ischk_message = 1
        SET @finaltransQty = @srcQtyLeft
        SET @infoMessage = CONCAT(
            dbo.fn_s_ofi_getLangString(400013, NULL, NULL),
                @line_ent_name, ', ',
            dbo.fn_s_ofi_getLangString(400019, NULL, NULL),
                CAST(ISNULL(@finaltransQty,0) AS VARCHAR(20)), dbo.fn_GetUOMDesc(@itemUOMId), ', ',
            dbo.fn_s_ofi_getLangString(400017, NULL, NULL),
                CAST(ISNULL(@transQty, 0) AS VARCHAR(20)), dbo.fn_GetUOMDesc(@itemUOMId)
        )
    END 
    
    --CHECK QUANTITY TRANSFERRED WITH TARGET
    SELECT
        @targetQty = ISNULL(target_qty, 0),
        @transferredQty = ISNULL(qty_transferred, 0),
        @transferType = st_transfer_type 
    FROM ofi_st_trans_selection WITH (NOLOCK)
    WHERE ent_id = @ent_id
        AND src_su_ent_id = @from_ent_id
        AND dest_su_ent_id = @to_ent_id
        AND is_Active = 1
        AND st_transfer_type = 3
    
    IF (@transferType = 3 AND @ischk_message=0)--MANUAL TRANSFER
    BEGIN
        IF (@finaltransQty > @targetQty - @transferredQty)
        BEGIN
            SET @ischk_message = 1
            SET @infoMessage = CONCAT(
                dbo.fn_s_ofi_getLangString(400014, NULL, NULL),
                    @line_ent_name, ', ',
                dbo.fn_s_ofi_getLangString(400020, NULL, NULL),
                    CAST(ISNULL(@finaltransQty, 0) AS VARCHAR(20)), dbo.fn_GetUOMDesc(@itemUOMId), ', ',
                dbo.fn_s_ofi_getLangString(478, NULL, NULL), ' : ',
                    CAST(ISNULL(@targetQty, 0) AS VARCHAR(20)), dbo.fn_GetUOMDesc(@itemUOMId), ', ',
                dbo.fn_s_ofi_getLangString(400021, NULL, NULL),
                    CAST(ISNULL(@transferredQty, 0) AS VARCHAR(20)), dbo.fn_GetUOMDesc(@itemUOMId), '.'
            )
        END
    END
    
    
    --GET ATTR-VALUES IN TEMP TABLE 
    INSERT INTO @su_attr 
    SELECT
        A.attr_id,
        A.attr_desc,
        EA.attr_value
    FROM ent_attr AS ea WITH (NOLOCK)
        INNER JOIN attr AS a WITH (NOLOCK)
            ON ea.attr_id = a.attr_id    
    WHERE
        ea.ent_id = @to_ent_id
        AND a.attr_desc IN (@attrOmarDesc, @uniqIdAttrDesc, @defGradecAttr, @bfqAttr)

    --GET MES ITEM ID
    SELECT
        @item_id = item.item_id
    FROM item WITH (NOLOCK) 
        CROSS APPLY ufn_ofi_mes_aut_itemid(item.item_id, 1) AS autitem
    WHERE autitem.aut_item_id = CAST(@aut_item_id AS VARCHAR(40))
 
    --Get the Source Item inv details
    SELECT TOP 1 
        @lot_no = lot_no,
        @sublot_no = sublot_no,
        @from_grade_desc = item_grade_desc,
        @from_status_desc = item_status_desc
    FROM
        @itemInvtemp
    WHERE
        ent_id = @from_ent_id
        AND item_id = CAST(@item_id AS VARCHAR(40))

    --READ  AUTO RECLASSIFY CONFIGURATION
    SELECT @auto_reclass_attr_value = attr_value
    FROM @su_attr
    WHERE attr_desc = @attrOmarDesc 

    --READ UNIQUE ITEM ID CONFIGURATION
    SELECT @unq_item_id = attr_value
    FROM @su_attr
    WHERE attr_desc = @uniqIdAttrDesc

    --READ UNIQUE ITEM GRADE CONFIGURATION
    SELECT @default_grade = attr_value
    FROM @su_attr
    WHERE attr_desc = @defGradecAttr  

    --READ BLOCK FOR QUALITY STATE
    SELECT @bfqAttr = attr_value
    FROM @su_attr
    WHERE attr_desc = @bfq_desc  

    SELECT @blocked_state = ISNULL(@bfq_desc, 'notblocked')

    -- [1.4 - CR 00203562]
    -- Reclassify the item to the destination if source item has the AllowReclassInTransfer MES item attribute set
    DECLARE @AllowReclassInTransferAttrId AS int;
    SELECT @AllowReclassInTransferAttrId = [attr_id]
    FROM [attr] WITH (NOLOCK)
    WHERE [attr_desc] = 'AllowReclassInTransfer'
      AND [attr_grp] = 1 -- Item
    
    IF (SELECT attr_value FROM item_attr WHERE item_id = @item_id AND attr_id = @AllowReclassInTransferAttrId) = 1
    BEGIN
        DECLARE @DestSiloItemId AS nvarchar(40);
        DECLARE @DestSiloItemGradeId AS int;
        SELECT TOP 1
            @DestSiloItemId = item_id,
            @DestSiloItemGradeId = grade_cd
        FROM item_inv
        WHERE ent_id = @to_ent_id
        ORDER BY date_in_utc DESC;
        IF @DestSiloItemId IS NOT NULL
        BEGIN
            SELECT @trasnferUODMDesc = dbo.[fn_GetUOMDesc](uom_id)
            FROM item WITH (NOLOCK)
            WHERE item_id = @DestSiloItemId
            
            SELECT @to_item_grade = item_grade_desc
            FROM item_grade
            WHERE item_grade_cd = @DestSiloItemGradeId;
            
            SET @to_item_id = @DestSiloItemId
            SET @reclassify = 1;
        END
    END
    -- [/1.4 - CR 00203562]
    --SET TO ITEM ID AND GRADE BASED ON OMAR/AUTO RECLASSIFY CONFIGURATION
    ELSE IF (@auto_reclass_attr_value = 'true' AND @unq_item_id IS NOT NULL AND @default_grade IS NOT NULL)
    BEGIN
        SELECT @trasnferUODMDesc = dbo.[fn_GetUOMDesc](uom_id)
        FROM item WITH (NOLOCK)
        WHERE item_id = @unq_item_id
        SELECT
            @to_item_id = @unq_item_id,
            @to_item_grade = @default_grade,
            @reclassify = 1;
    END
    ELSE
    BEGIN
        SELECT
            @to_item_id = @item_id,
            @to_item_grade = @from_grade_desc,
            @trasnferUODMDesc = NULL;
    END
    
    SET @finaltransQty = ISNULL(@finalTransQty,0)
    SELECT
        @from_site_name    site_name,
        @line_ent_name     line_ent_name,
        @from_ent_id       from_ent_id,
        @to_ent_id         to_ent_id,
        @from_ent_name     from_ent_name,
