--  
-- Usage:    
-- ===========================================================================================  
-- Version Author   Date (yyyy-MM-dd)	Change description  
-- 0.01.00 TB       2023-04-13			Initial version.  
-- 0.02.00 AKM      2024-02-01			coding best practice
-- ===========================================================================================  
  
	CREATE PROCEDURE [dbo].[sp_s_ofi_SAVEMAXBLEND]
	(  
		@lot_no NVARCHAR(80)=NULL,
		@attr_value INT,
		@item_id NVARCHAR(40)
	
		

 
	)   
	AS

	BEGIN

	DECLARE 
	@attr_id INT,
	@mod_id varchar(30),
	@notes NOTES,
	@last_edit_comment nvarchar(254),
	@last_edit_by nvarchar(40) ,
	@last_edit_at datetime = NULL

	SET @attr_id= (select  attr_id from attr(nolock) where attr_desc ='MaxBlendRatio')
	If EXISTS(select attr_value from lot_attr(nolock) where attr_id=(select  attr_id from attr(nolock) where attr_desc ='MaxBlendRatio') AND lot_no =@lot_no)
	BEGIN

	UPDATE lot_attr
	SET attr_value = @attr_value 
	WHERE lot_no=@lot_no
	END
	ELSE
	BEGIN
	EXEC sp_I_Lot_Attr 
 
	@item_id,
	@lot_no,
	@attr_id,
	@attr_value,
	@notes,
	@last_edit_comment,
	@mod_id

	

	END
	END

