DECLARE @sample_time_utc	DATETIME
	,	@shift_start_utc	DATETIME
	,   @dbg_resp			INT32
	,	@tz_temp			INT32



SET @sample_time_tz = dbo.fn_TZ_ValidateOffset(@sample_time_tz)
SET @sample_time_local = dbo.fn_TZ_ValidateLocalDate(@sample_time_local, @sample_time_tz)
SET @shift_start_tz = dbo.fn_TZ_ValidateOffset(@shift_start_tz)
SET @shift_start_local = dbo.fn_TZ_ValidateLocalDate(@shift_start_local, @shift_start_tz)
SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)


-- TRACE
exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_U_Data_Log_16', @src_key='sp_U_Data_Log_16', @date_val1 = @sample_time_local, @numeric_val1 = @sample_time_tz, @date_val2 = @shift_start_local, @numeric_val2 = @shift_start_tz


SET @tz_temp = -@sample_time_tz
EXEC sp_S_GetUtcDate @sample_time_local,@tz_temp, @sample_time_utc OUTPUT

SET @tz_temp = -@shift_start_tz
EXEC sp_S_GetUtcDate @shift_start_local,@tz_temp, @shift_start_utc OUTPUT



UPDATE data_log_16
SET wo_id = @wo_id,
    oper_id = @oper_id,
    seq_no = @seq_no,
    step_no = @step_no,
    item_id = @item_id,
    lot_no = @lot_no,
    sublot_no = @sublot_no,
	shift_start_utc = @shift_start_utc,
	shift_start_local = @shift_start_local,
    shift_id = @shift_id,
    ent_id = @ent_id,
    genealogy_id = @genealogy_id,
    segment_requirement_id = @segment_requirement_id,
    segment_response_id = @segment_response_id,
    value1 = @value1,
    value2 = @value2,
    value3 = @value3,
    value4 = @value4,
    value5 = @value5,
    value6 = @value6,
    value7 = @value7,
    value8 = @value8,
    value9 = @value9,
    value10 = @value10,
    value11 = @value11,
    value12 = @value12,
    value13 = @value13,
    value14 = @value14,
    value15 = @value15,
    value16 = @value16,
    last_edit_comment = @last_edit_comment
WHERE row_id = @row_id
