--* Procedure definition
--in future the user priviliges check should be changed
--error messages also to be changed to language independent
CREATE  PROCEDURE [dbo].[sp_I_Job_Exec_SplitJob]
(
	@wo_id							STRING40,
	@oper_id						STRING40,
	@orig_seq_no					INT32,
	@user_id						STRING40,
	@split_qty						TFLOAT,
	@new_seq_no						INT32 OUTPUT,
	@split_start_qty				TFLOAT_NULL = NULL,
	@new_state_cd					INT32_NULL = NULL,
	@req_finish_time				TDATETIME_NULL = NULL ,
	@req_finish_time_utc			TDATETIME_NULL = NULL ,
	@target_ent_id					INT32_NULL = NULL ,
	@status_notes					STRING2000_NULL = NULL ,
	@ignore_zero_start_qty_check	LOGICAL = 0,
	@time_zone_bias_value			INT32 = 0
)

AS
-- ***********************************************************************************************************************
-- Module Name			- sp_I_Job_Exec_SplitJob
-- Description			-
-- Author				-
-- Date Created			- 10/21/2002
-- Version				- 3.1.0.12
--
-- Copyright (C) 2020 AVEVA Software, LLC. and its subsidiaries. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Ver		Changes
-- 01/09/2003		Rohit			1.5.2	Added string Id reference to err messages.
-- 08/25/2003		Sheetal Jain    1.6.0	Added spc characteristics to be brought over for the job
-- 10/14/2003		Sheetal Jain    1.6.28	(HD# 3688) Start qty changes
-- 11/07/2003		Sheetal Jain    1.6.31	(HD#3931) Job notes
-- 05/07/2004		Sheetal Jain	20033	Job_Cursor was not closed
-- 10/03/2005		Raghu			3.1.0	Part of DB Changes
-- 03/17/2006		SJ				31012	HD#7574 - (Oracle)Jobs Window - Error Splitting job
--											Only a maximum of 4000 characters can be copied from the notes field
-- 08/15/2007		AML				3.3.0	DB Changes
-- 01/21/2008		Raghu		3.4		L00073299; Entry of Production Rates is cumbersome,...
-- 02/23/2009		DonT		3.4		L00089175 (HF1275): Add an exclusive lock around splitjob
-- 03/07/2011		Ibrahim		4.1		CR L00110543/HF2382; Updated the input required finished time in the newly created job.
-- 10/08/2012	  	Arun            4.6             spc_char_job is removed from the database
--07/10/2014	Raghu		5.0	Userstory: 348566 - As Jack, I want to prohibit MES client from making changes to work orders assigned to lines that would make them incompatible with the line to which they were assigned so that I do not create a problem for the Web client (Part 2)
-- 12/19/2019	Srinivasa	6.2	US#1240917,CR#L00155614 to Merge L00155427(Added Spare fields to the INSERT statement when splitting job).
-- 05/12/2020	Eswar H		6.2	Added UTC input parameter (US 1302837).
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN

	SET NOCOUNT ON

	DECLARE	@priv_id					int,
			@priv_desc					varchar,
			@seq_no						int,
			@job_desc					nvarchar(80) ,
			@item_id					nvarchar(40) ,
			@state_cd					int,
			@job_priority				int ,
			@l_req_finish_time_local	datetime,
			@init_sched_ent_id			int ,
			@target_sched_ent_id		int ,
			@run_ent_id					int ,
			@qty_prod					float ,
			@qty_prod_erp				float ,
			@qty_rejected				float ,
			@qty_rejected_erp			float ,
			@qty_at_start				float ,
			@deviation_above			float ,
			@deviation_below			float ,
			@batch_size					float ,
			@first_job					bit ,
			@final_job					bit ,
			@sched_pinned				bit ,
			@check_inv					bit ,
			@est_fixed_lab				float ,
			@est_lab_rate				float ,
			@est_setup_time				float ,
			@est_teardown_time			float ,
			@est_prod_rate				float ,
			@prod_uom				int,
			@est_transfer_time			float ,
			@sched_start_time_utc		datetime ,
			@sched_start_time_local		datetime,
			@latest_start_time_utc		datetime ,
			@latest_start_time_local	datetime,
			@sched_finish_time_utc		datetime ,
			@sched_finish_time_local	datetime,
			@act_start_time_utc			datetime ,
			@act_start_time_local		datetime,
			@act_finish_time_utc		datetime ,
			@act_finish_time_local		datetime,
			@concurrent_link			int ,
			@job_cost					float ,
			@parent_contingent_job		bit,
			@child_contingent_job		bit,
			@assoc_file					nvarchar(254) ,
			@assoc_file_type			nvarchar(20) ,
			@edited_by					nvarchar(40) ,
			@edit_time					datetime ,
			@display_seq				int ,
			@data_log_grp_id			int ,
			@folder_ver_id				nvarchar(40),
			@rework						bit,
			@V_Integer					int,
			@V_Notes					nvarchar(4000),
			@req_finish_time_local		tdatetime,
			@lock_result 			int,
			@upstream_ent_name	NVARCHAR(80),
			@downstream_ent_name	NVARCHAR(80),
			@err_msg		NVARCHAR(MAX),
			@line_name		NVARCHAR(80),
			@spare1 nvarchar(80),
			@spare2 nvarchar(80),
			@spare3 nvarchar(80),
			@spare4 nvarchar(80)

	--Fix for the CR L00110543/HF2382
	SET @req_finish_time_local = @req_finish_time
	-- (HF1275) This exclusive lock will last until we release it at bottom of the SP. If we exit early via a RASIERROR,
	-- it will be released when the client Tx is committed or rolled back
	EXEC @lock_result = sp_getapplock @Resource = 'SJLock', @LockMode = 'Exclusive', @LockTimeout = '25000';
	IF @lock_result < 0
	BEGIN
		RAISERROR('Failed to get exclusive lock for splitjob - error code %d', 16, 1, @lock_result)
		SET @new_seq_no = -1
		RETURN -1
	END

	--check @user_id has the value
	--below checking @user_id is commented temporarily
	--IF @user_id IS NULL
	--BEGIN
	--	RAISERROR('A valid User Id is required', 16, 1)
	--	RETURN -1
	--END

	IF ( @ignore_zero_start_qty_check <> 1 ) BEGIN
		--check @split_qty has the value
		IF (@split_qty IS NULL OR @split_qty <= 0) BEGIN
			RAISERROR('A Split Quantity is required{3348}', 16, 1)
			RETURN -1
		END
	END

	/* Got rid of this cursor...looks like we stopped using the values in it a long time ago.  08/15/2007 AML
	--check the user privileges to split the jobs
	DECLARE priv_cursor CURSOR LOCAL FOR
		SELECT b.priv_id, c.priv_desc
		FROM user_grp_link a WITH (NOLOCK)
			INNER JOIN grp_priv_link b WITH (NOLOCK) ON a.grp_id = b.grp_id
			INNER JOIN priv c WITH (NOLOCK) ON b.priv_id = c.priv_id
		WHERE a.user_id = @user_id

	OPEN priv_cursor
	FETCH NEXT FROM priv_cursor INTO @priv_id, @priv_desc
	CLOSE priv_cursor
	DEALLOCATE priv_cursor
	--below checking privliges is commented temporarily
	--IF @priv_id IS NULL
	--BEGIN
	--	RAISERROR('This user does not have Priviliges to split Jobs', 16, 1)
	--	RETURN -1
	--END
	*/

	--if new sequence number is not given get the new sequence no
	IF ( @new_seq_no IS NULL ) BEGIN
		SELECT @seq_no = MAX(seq_no) + 1
		FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id

		--check the sequence no. this can be null only in the case of the work order
		-- or operation is deleted just before executing this procedure
		IF ( @seq_no IS NULL ) BEGIN
			RAISERROR('work order or operation not found{3349}', 16, 1)
			SET @new_seq_no = -1
			RETURN -1
		END

		SET @new_seq_no = @seq_no
	END
	ELSE BEGIN
		--Check whether the record is existed with the new_seq_no
		--Fix for CR L00100446/HF1751
		SELECT @seq_no = seq_no FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @new_seq_no

		IF NOT(@seq_no IS NULL) BEGIN
			RAISERROR('New Sequence No already exists{3350}', 16, 1)
			SET @new_seq_no = -1
			RETURN -1
		END
	END

	/* Got rid of this.  Total overkill.  08/15/2007 AML
	--get the values of original sequence  from the job table
	DECLARE job_cursor CURSOR LOCAL FOR
		SELECT	job_desc,item_id,state_cd,job_priority,req_finish_time,init_sched_ent_id,target_sched_ent_id,
				qty_at_start,deviation_above, deviation_below, batch_size, first_job, final_job, sched_pinned,
				check_inv, est_fixed_lab, est_lab_rate, est_setup_time, est_teardown_time, est_prod_rate,
				est_transfer_time, sched_start_time, latest_start_time, sched_finish_time, concurrent_link,
				job_cost, parent_contingent_job, child_contingent_job, assoc_file, assoc_file_type, edited_by,
				edit_time, display_seq, folder_ver_id, rework, notes
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @orig_seq_no

	OPEN job_cursor
	FETCH NEXT FROM job_cursor
	INTO @job_desc, @item_id, @state_cd, @job_priority, @l_req_finish_time, @init_sched_ent_id, @target_sched_ent_id,
		 @qty_at_start, @deviation_above, @deviation_below, @batch_size, @first_job, @final_job, @sched_pinned, @check_inv,
		 @est_fixed_lab, @est_lab_rate, @est_setup_time, @est_teardown_time, @est_prod_rate, @est_transfer_time, @sched_start_time,
		 @latest_start_time, @sched_finish_time, @concurrent_link, @job_cost, @parent_contingent_job, @child_contingent_job,
		 @assoc_file, @assoc_file_type, @edited_by, @edit_time, @display_seq, @folder_ver_id, @rework, @V_Notes

	IF ( @@FETCH_STATUS <> 0 ) BEGIN
		CLOSE job_cursor
		DEALLOCATE job_cursor

		RAISERROR('Job not found{3351}', 16, 1)

		SET @new_seq_no = -1
		RETURN -1
	END

	CLOSE job_cursor
	DEALLOCATE job_cursor
	*/

	--get the values of original sequence from the job table
	IF NOT EXISTS ( SELECT TOP 1 1 FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @orig_seq_no ) BEGIN
		RAISERROR('Job not found{3351}', 16, 1)
		SET @new_seq_no = -1
		RETURN -1
	END

	SELECT	@job_desc = job_desc, @item_id = item_id, @state_cd = state_cd, @job_priority = job_priority,
			@l_req_finish_time_local = req_finish_time_local,
			@init_sched_ent_id = init_sched_ent_id, @target_sched_ent_id = target_sched_ent_id,
			@qty_at_start = qty_at_start, @deviation_above = deviation_above, @deviation_below = deviation_below,
			@batch_size = batch_size, @first_job = first_job, @final_job = final_job, @sched_pinned = sched_pinned,
			@check_inv = check_inv, @est_fixed_lab = est_fixed_lab, @est_lab_rate = est_lab_rate, @est_setup_time = est_setup_time,
			@est_teardown_time = est_teardown_time, @est_prod_rate = est_prod_rate,
			@prod_uom = prod_uom, @est_transfer_time = est_transfer_time,
			@sched_start_time_utc = sched_start_time_utc, @sched_start_time_local = sched_start_time_local,
			@latest_start_time_utc = latest_start_time_utc, @latest_start_time_local = latest_start_time_local,
			@sched_finish_time_utc = sched_finish_time_utc, @sched_finish_time_local = sched_finish_time_local,
			@concurrent_link = concurrent_link, @job_cost = job_cost, @parent_contingent_job = parent_contingent_job,
			@child_contingent_job = child_contingent_job, @assoc_file = assoc_file, @assoc_file_type = assoc_file_type,
			@edited_by = edited_by, @edit_time = edit_time, @display_seq = display_seq, @folder_ver_id = folder_ver_id,
			@rework = rework, @V_Notes = notes, @spare1 = spare1, @spare2 = spare2, @spare3 = spare3, @spare4 = spare4
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @orig_seq_no

	--Check if there are quantities available to split
	IF EXISTS (
		SELECT 'X'
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id AND
			  oper_id = @oper_id AND
			  seq_no = @orig_seq_no AND
			  (ISNULL(qty_at_start,0)-(qty_prod+qty_rejected) < ISNULL(@split_start_qty,0) OR qty_reqd-(qty_prod+qty_rejected) < @split_qty)
	)
	BEGIN
		RAISERROR('There are not enough start or required quantities available to split{4155}', 16, 1)
		SET @new_seq_no = -1
		RETURN -1
	END

	--Check if the job-item can be fractionalized
	SELECT @V_Integer = i.num_decimals
	FROM job AS j WITH (NOLOCK)
		INNER JOIN item AS i WITH (NOLOCK) ON j.item_id = i.item_id
	WHERE j.wo_id = @wo_id AND j.oper_id = @oper_id AND j.seq_no = @orig_seq_no

	--If @split_start_qty is null calculate split start qty proportionately
	IF (@split_start_qty IS NULL) BEGIN
		SELECT @split_start_qty = qty_at_start*@split_qty/qty_reqd
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @orig_seq_no

		--If item can not be fractionalized
		IF @V_Integer = 0
		SET @split_start_qty = FLOOR(@split_start_qty)
	END

	--Error if split start or job quantities are less than 1 for item that cannot be fractionalized
	IF @V_Integer = 0 AND (@split_qty > FLOOR(@split_qty) OR @split_start_qty > FLOOR(@split_start_qty)) BEGIN
		RAISERROR('The split quantity and the split start quantity must be integer values for items that can not be fractionalized{4154}', 16, 1)
		SET @new_seq_no = -1
		RETURN -1
	END

	--set the default values
	SELECT	@qty_prod = 0, @qty_rejected = 0, @run_ent_id = NULL

	IF @first_job IS NULL SET @first_job = 0
	IF @final_job IS NULL SET @final_job = 0
	IF @status_notes IS NULL SET @status_notes = 'Created by Job Split'
	IF @new_state_cd IS NULL SET @new_state_cd = @state_cd

	IF ( @req_finish_time_local IS NULL ) BEGIN
		SET @req_finish_time_local = @l_req_finish_time_local
	END

	IF @target_ent_id IS NULL SET @target_ent_id = @target_sched_ent_id

	IF (@req_finish_time_utc IS NOT NULL)
		SET @req_finish_time_local = dbo.fn_TZ_GetLocalDateFromUtc(@target_ent_id, @req_finish_time_utc)
	ELSE BEGIN
		IF (@req_finish_time_local IS NOT NULL) SET @req_finish_time_utc = dbo.fn_TZ_GetUtcDateFromLocal(@target_ent_id, @req_finish_time_local, GETUTCDATE())
	END

	IF NOT (@new_state_cd IS NULL OR @new_state_cd = 1 OR @new_state_cd = 2 OR @new_state_cd = 5 OR @new_state_cd = 6) BEGIN
		IF @state_cd = 3 OR  @state_cd = 4 OR  @state_cd = 7 BEGIN
			SET @state_cd = 2   --set the status to 'Ready'
		END

		SET @new_state_cd = @state_cd
	END

	INSERT INTO job
	(
		wo_id, oper_id, seq_no, job_desc, item_id, state_cd, job_priority, req_finish_time_utc,
		req_finish_time_local, init_sched_ent_id, target_sched_ent_id, run_ent_id, qty_reqd, qty_prod,
		qty_prod_erp, qty_rejected, qty_rejected_erp, qty_at_start, batch_size, deviation_above,
		deviation_below, first_job, final_job, sched_pinned, check_inv, est_fixed_lab, est_lab_rate,
		est_setup_time, est_teardown_time, est_prod_rate, prod_uom, est_transfer_time, sched_start_time_utc,
		sched_start_time_local, latest_start_time_utc, latest_start_time_local, sched_finish_time_utc,
		sched_finish_time_local, act_start_time_utc, act_start_time_local, act_finish_time_utc,
		act_finish_time_local, concurrent_link, job_cost, notes, parent_contingent_job, child_contingent_job,
		assoc_file, assoc_file_type, status_notes, edited_by, edit_time, display_seq, folder_ver_id, rework,
		spare1, spare2, spare3, spare4
	)
	VALUES
	(
		@wo_id, @oper_id, @new_seq_no, @job_desc, @item_id, @new_state_cd, @job_priority, @req_finish_time_utc,
		@req_finish_time_local, @init_sched_ent_id, @target_ent_id, @run_ent_id, @split_qty, @qty_prod, @qty_prod_erp,
		@qty_rejected, @qty_rejected_erp, @split_start_qty, @batch_size, @deviation_above, @deviation_below, @first_job,
		@final_job, @sched_pinned, @check_inv, @est_fixed_lab, @est_lab_rate, @est_setup_time, @est_teardown_time,
		@est_prod_rate, @prod_uom, @est_transfer_time, @sched_start_time_utc, @sched_start_time_local, @latest_start_time_utc,
		@latest_start_time_local, @sched_finish_time_utc, @sched_finish_time_local, @act_start_time_utc, @act_start_time_local,
		@act_finish_time_utc, @act_finish_time_local, @concurrent_link, @job_cost, @V_Notes, @parent_contingent_job,
		@child_contingent_job, @assoc_file, @assoc_file_type, @status_notes, @edited_by, @edit_time, @display_seq, @folder_ver_id,
		@rework, @spare1, @spare2, @spare3, @spare4
	)

	-- update the notes
	UPDATE job SET notes = b.notes FROM (
		SELECT wo_id, oper_id, notes
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @orig_seq_no
	) AS b
	WHERE job.wo_id = b.wo_id AND job.oper_id = b.oper_id AND job.seq_no = @new_seq_no

	--	update the job.qty_reqd for the job from which new one has been split
	UPDATE job SET qty_reqd = qty_reqd - @split_qty, qty_at_start = qty_at_start - ISNULL(@split_start_qty,0)
	WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @orig_seq_no

	--.	Clone*** JOB_STEP table row(s)*.
	EXECUTE sp_I_Job_Exec_CloneJob_Step @wo_id, @oper_id, @orig_seq_no, @wo_id, @oper_id, @new_seq_no

	--.	Clone JOB_BOM table row(s)* and then Clone JOB_BOM_STEP table row(s)*.
	EXECUTE sp_I_Job_Exec_CloneJob_BOM @wo_id, @oper_id, @orig_seq_no, @wo_id, @oper_id, @new_seq_no

	--.	Clone*** JOB_SPEC table row(s)*.
	EXECUTE sp_I_Job_Exec_CloneJob_Spec @wo_id, @oper_id, @orig_seq_no, @wo_id, @oper_id, @new_seq_no

	--.	Clone JOB_ROUTE table rows.
	EXECUTE sp_I_Job_Exec_CloneJob_Route @wo_id, @oper_id, @orig_seq_no, @wo_id, @oper_id, @new_seq_no

	EXEC sp_U_Wo_ValJobRteWithLineRte @wo_id = @wo_id, @upstream_ent_name = @upstream_ent_name OUTPUT, @downstream_ent_name	= @downstream_ent_name OUTPUT

	IF (@upstream_ent_name IS NOT NULL OR @downstream_ent_name IS NOT NULL) BEGIN
		SELECT @line_name = l.line_name
		FROM line l WITH (NOLOCK)
		INNER JOIN wo wo WITH (NOLOCK) ON l.line_id = wo.target_sched_line_id
		WHERE wo.wo_id = @wo_id

		SET @err_msg = 'The work order: %1 is currently assigned to line: %2. The job cannot be split, because the sequence of entities (upstream entity: %3, downstream entity: %4) in the job route do not match with the sequence of entities in the line route.{7918},' + @wo_id + ',' + @line_name + ',' + @upstream_ent_name + ',' + @downstream_ent_name
		RAISERROR(@err_msg, 16, 1)
		RETURN
	END
	--     Clone Attributes
	EXECUTE sp_I_Job_Exec_CloneJob_Attr @wo_id, @oper_id, @orig_seq_no, @wo_id, @oper_id, @new_seq_no

	-- (HF1275) Release the exclusive lock we aquired above
	EXEC sp_releaseapplock @Resource = 'SJLock'

	RETURN @new_seq_no
END

