--===========================================================================================
-- Name:		[sp_D_ofi_DeleteMaterialMaster]
-- Description:	The stored procedure will delete record to the item table
--
-- Usage:		DeleteMaterialMaster
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-16			Initial version.
-- 0.02.00	YG				2022-10-24			Add flag for audit trail in the parameter
-- ===========================================================================================
CREATE Procedure [dbo].[sp_D_ofi_DeleteMaterialMaster]
	@item_id NVARCHAR(40) = NULL,
	@user_name NVARCHAR(40) = NULL,
	@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail
AS
BEGIN
	DECLARE	@iRowId INT,
			@strModuleName NVARCHAR(80) = 'MM_Item',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'delete',
			@dataRecord XML,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS;

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	SELECT @iRowId = row_id
	FROM item WITH(NOLOCK)
	WHERE item_id = @item_id

	-- retrieve datas and set into xml format
	SET @dataRecord = (
			SELECT i.item_id		as item_id,
				i.item_desc			as item_desc,
				i.item_class_id		as item_class_id,
				ic.item_class_desc	as item_class_desc,
				u.abbreviation		as uom_desc,
				u.uom_id			as uom_id,
				i.num_decimals		as num_decimals,
				ia.attr_value		as template_name,
				ISNULL(i.spare1,0)	as spare1,
				i.last_edit_comment as last_edit_comment
			FROM item i WITH (NOLOCK)
			INNER JOIN uom u WITH (NOLOCK) ON i.uom_id = u.uom_id
			INNER JOIN item_class ic WITH (NOLOCK) ON i.item_class_id = ic.item_class_id
			LEFT OUTER JOIN item_attr ia WITH (NOLOCK) ON i.item_id = ia.item_id AND ia.attr_id = (SELECT attr_id 
																								   FROM attr WHERE attr_desc = 'ItemGroup')
			WHERE 
				(i.item_id like '%' + @item_id + '%' OR @item_id IS NULL)
			FOR XML RAW('data')
	);

	EXEC sp_D_Item 
		@item_id = @item_id

	IF (@audit_trail = 1)
	BEGIN
		-- At least one record with the row_id is required for storing the deleted record in the audit_trail table.
		DELETE @auditTrailParameters
		INSERT INTO @auditTrailParameters (
			row_id
			,field_name
			,field_value
			)
		VALUES 
			(
			@iRowId
			,'@row_id'
			,NULL
			)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@xmlDeletedRow = @dataRecord,
			@deletedRowSourceTable = '[dbo].[item]',
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info'
	END
END

