	@uom_id_pick int ,
	@from_expiry_date datetime ,
	@from_expiry_date_tz INT32 = NULL,
	@trans_id int ,
	@spare1 nvarchar(80) ,
	@spare2 nvarchar(80) ,
	@spare3 nvarchar(80) ,
	@spare4 nvarchar(80) ,
	@last_edit_comment nvarchar(254) ,
	@time_zone_bias_value INT32 = NULL ,
	@last_edit_at datetime OUT,
	@row_id int OUT
)
AS
