-- PARTICULAR PURPOSE.
-- Notes            -
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Change By	Ver.	Changes
-- 09/22/2005	Raghu		3.1.0	Part of DB Changes
-- 01/16/2007	KRF			3.2.1	HD# 8314, part of DB changes - added @sublot_no & @from_sublot_no arguments.
--									Also HD# 8434 w.r.t. last_edit_at.
-- 07/31/2007	AML			3.3.0	DB Changes
-- 10/24/2007	AML			3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--									dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 11/16/2009	Ajay		4.0.0	HD#1432, Part of Date/TimeZone changes
---------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @last_edit_by			NVARCHAR(40)
	,	@date_of_shipment_utc	DATETIME
	,	@tz_temp				INT
	,	@dbg_resp				INT


SET @date_of_shipment_tz	= dbo.fn_TZ_ValidateOffset(@date_of_shipment_tz)
SET @date_of_shipment_local = dbo.fn_TZ_ValidateLocalDate(@date_of_shipment_local,@date_of_shipment_tz )
SET @expiry_date_tz			= dbo.fn_TZ_ValidateOffset(@expiry_date_tz)
SET @expiry_date			= dbo.fn_TZ_ValidateLocalDate(@expiry_date, @expiry_date_tz)
SET @from_expiry_date_tz	= dbo.fn_TZ_ValidateOffset(@from_expiry_date_tz)
SET @from_expiry_date		= dbo.fn_TZ_ValidateLocalDate(@from_expiry_date, @from_expiry_date_tz)
SET @time_zone_bias_value	= dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

-- TRACE
exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Transfer_List', @src_key='sp_I_Transfer_List', @date_val1 = @date_of_shipment_local, @numeric_val1 = @date_of_shipment_tz, @date_val2 = @expiry_date, @numeric_val2 = @expiry_date_tz



EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL

SET  @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

SET @tz_temp = - @date_of_shipment_tz

EXEC sp_S_GetUtcDate @date_of_shipment_local,  @tz_temp, @date_of_shipment_utc OUTPUT -- Added 07/31/2007

SET @expiry_date		=  DATEADD(mi, - @expiry_date_tz, @expiry_date)
SET @from_expiry_date	=  DATEADD(mi, - @from_expiry_date_tz, @from_expiry_date)

INSERT INTO transfer_list
(
	transfer_type,
	cust_id,
	order_id,
	line_no,
	--date_of_shipment,
	date_of_shipment_utc,	-- Added 07/31/2007
	date_of_shipment_local, -- Added 07/31/2007
	wo_id,
	oper_id,
	seq_no,
	bom_pos,
	to_ent_id,
	item_id,
	lot_no,
	sublot_no, -- Added 1/16/07 KRF
	grade_cd,
	status_cd,
	qty_to_store,
	uom_id_store,
	expiry_date,
	from_ent_id,
	from_item_id,
	from_lot_no,
	from_sublot_no, -- Added 1/16/07 KRF
	from_grade_cd,
	from_status_cd,
	qty_to_pick,
	uom_id_pick,
	from_expiry_date,
	trans_id,
	spare1,
	spare2,
	spare3,
	spare4,
	last_edit_comment,
	last_edit_by,
	last_edit_at
)
VALUES
(
	@transfer_type,
	@cust_id,
	@order_id,
	@line_no,
	--@date_of_shipment,
	@date_of_shipment_utc,		-- Added 07/31/2007
	@date_of_shipment_local,	-- Added 07/31/2007
	@wo_id,
	@oper_id,
	@seq_no,
	@bom_pos,
	@to_ent_id,
	@item_id,
	@lot_no,
	@sublot_no, -- Added 1/16/07 KRF
	@grade_cd,
	@status_cd,
	@qty_to_store,
	@uom_id_store,
	@expiry_date,
	@from_ent_id,
	@from_item_id,
	@from_lot_no,
	@from_sublot_no, -- Added 1/16/07 KRF
	@from_grade_cd,
	@from_status_cd,
	@qty_to_pick,
	@uom_id_pick,
	@from_expiry_date,
	@trans_id,
	@spare1,
	@spare2,
	@spare3,
	@spare4,
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at
)

SET @row_id = SCOPE_IDENTITY()

-- =============================================
-- Name:    SP_I_ofi_Item_Cons_AddCons
-- Description:  Add consumption
--
-- Usage:
-- ===========================================================================================
-- Version  Author	Date (yyyy-MM-dd)	Change description
-- 0.01.00  VJ		2022-10-17			Initial version.
-- 0.02.00  MP		2023-01-30			Added row_id input for [SP_SA_ofi_item_inv_typeOfCons]
-- 0.03.00	YG		2023-03-14			Added logic for consuming material has different grade with job bom
-- 0.04.00	YG		2023-04-28			Added logic for consuming material non bom
-- 0.05.00	DS		2023-08-28			#279, Added logic for liquor consumption based on ticket document
-- 0.06.00	DS		2023-10-13			#279_1, MOdified logic for liquor consumption if WIP material is already present in BOM pos=0
--											System is checking whether triggered item is part of the BOM or not and based on that we have checked 2 conditions, selected silos item is part of the BOM or not
--											#279_10 - Triggered item is BOM compenent or not
--											#279_11 - selected silo componenet is matching with BOM component or not
--											#279_13 - removed group @groupConsRows attribute from the liquor blending
-- 0.07.00	DS		2023-10-27			#279_14 - issue with getting inserted new rows in the item_cons table, fixed to restrict the insertion. used
-- 0.08.00	DS		2024-01-31			Added inline comments
-- 1.00.00	YG		2024-04-29			Added stopped WO also in the validation
-- 1.01.00	YG		2024-05-13			Added recorded timestamp
-- 1.02.00	MC		2025-01-07			Modified way to making decision about "reclassification" silo for bidirrectional silo - not only during first												consumption - always when prod item in running job is different than in dest silo
-- 1.03.00	JSC		2025-11-06			Added lot and sublot as input (optional)
-- 1.03.01	JSC		2025-11-06			Fix for the overflow
-- =============================================
-- EXEC SP_I_ofi_Item_Cons_AddCons '1003202202', 'Miller_02', 0, 100, 159,8, '1000101'
-- EXEC SP_I_ofi_Item_Cons_AddCons '123', 'BeanIntake', 0,100, 138,8, '1000101'
-- =============================================

CREATE   PROCEDURE [dbo].[SP_I_ofi_Item_Cons_AddCons]
	@wo_id NVARCHAR(40) ,
	@oper_id NVARCHAR(40) ,
	@seq_no INT ,
	@qty FLOAT ,
	@ent_id INT ,
	@aut_storage_id INT ,
	@item_id NVARCHAR(40) = NULL ,
	@actual_cons_time TDATETIME = NULL, -- V1.01.00 Added
	@target_fg_lot_no NVARCHAR(40) = NULL, --v1.03.00 Added
	@target_fg_sublot_no NVARCHAR(40) = NULL, --v1.03.00 Added
	@target_cons_reas_cd INT = -1 --v1.03.00 Added -- review type
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @storage_ent_id INT,
			@cons_lot_no NVARCHAR(40) = NULL,
			@cons_sublot_no NVARCHAR(40) = NULL,
			@cons_qty FLOAT = 0,
			@avl_qty FLOAT = 0,
			@consumed_qty FLOAT = 0,
			@job_pos INT = 0,
			@bom_pos INT = 0,
			@date_time_UTC TDATETIME = @actual_cons_time,
			@return_value INT,
			@row_id INT32,
			@minID INT,
			@typeOfCons NVARCHAR(20) = 'FIFO',
			@process_id NVARCHAR(30),
			@process_type NVARCHAR(30),
			@prod_info NVARCHAR(4000),
			@prod_item_id NVARCHAR(40),
			@prod_date_time_UTC DATETIME,
			@reqd_grade_cd INT,
			@reqd_status_cd INT,
			@grade_cd INT,
			@status_cd INT,
			@is_bom_item INT = 1, -- this supplied\trigger item from automation is a bom item or not
			@is_siloItem_bom_item INT = 1, -- is selected destination item a bom item or not
			@groupConsRows INT,
			@ConsBiDirectionalSilo INT,
			@IsBiDirectionalSiloExists INT = 0,
			@source_su_id INT,
			@jb_item_id NVARCHAR(80),
			@max_row_cnt INT,
			@row_cnt INT,
			@si_lot_no string40_null,
			@si_sublot_no string40_null,
			@si_grade_cd int32_null,
			@si_qty_left tfloat,
			@si_item_id string40_null,
			@si_status_cd INT,
			@target_reqd_grade_cd INT,
			@target_item_id NVARCHAR(80),
			@target_lot_no NVARCHAR(80),
			@user_id NVARCHAR(80), -- V1.01.00 Added
			@tz_bias INT = 120, -- V1.01.00 Added
			@cons_reas_cd INT,-- V1.01.00 Added
			@prod_reas_cd INT -- V1.01.00 Added
	
	--AP: 23-fEB-23, Getting sublot number
	DECLARE @SUBLOTTABLE TABLE
		(
			sublot_counter INT,
			sublot_no NVARCHAR(40)
		)

	DECLARE @silo_inv AS TABLE (row_id INT identity(1,1),item_id NVARCHAR(80),lot_no string40_null, sublot_no string40_null,grade_cd int32_null,status_cd int32_null, qty_left tfloat)
	-- Set TZ offset
	SELECT TOP 1 @tz_bias = ISNULL(offset,120)
	FROM tz_offset WITH (NOLOCK)
	WHERE @actual_cons_time BETWEEN start_utc AND end_utc
		AND region_id = 'W. Europe Standard Time'
	-- Get User Id -- V1.01.00 Added
	EXEC Sp_s_db_status_getaudtrailusr @user_id output,
										NULL
	--v1.02 MOD
	IF @target_cons_reas_cd > -1 AND @target_cons_reas_cd IS NOT NULL
	BEGIN
		SET @cons_reas_cd = @target_cons_reas_cd
	END
	ELSE
	BEGIN
		-- Get Consumption Reason -- V1.01.00 Added
		SELECT @cons_reas_cd = reas_cd
		FROM item_reas WITH (NOLOCK)
		WHERE reas_desc = 'Good Consumption'
	END
	-- v1.02 MOD
	-- get the configured default production reason
	SELECT @prod_reas_cd = e.def_prod_reas_cd
	FROM job_exec e WITH (NOLOCK)
	WHERE e.ent_id = @ent_id

	IF @prod_reas_cd IS NULL
	BEGIN
		-- Get Prod Reason -- V1.01.00 Added
		SELECT @prod_reas_cd = reas_cd
		FROM item_reas WITH (NOLOCK)
		WHERE reas_desc = 'Good Production'
	END
	--GETS Required Data
	SELECT @storage_ent_id = ent_id
	FROM ent_attr ea WITH (NOLOCK)
		INNER JOIN attr a WITH (NOLOCK) ON ea.attr_id = a.attr_id
											AND a.attr_desc = 'SUNumberInAUT'
											AND a.attr_grp = 2
											AND ea.attr_value = CAST(@aut_storage_id AS NVARCHAR(80))
	--fetching the bom position & grade details from job_bom
	SELECT 	@bom_pos=bom_pos,
			@reqd_grade_cd = reqd_grade_cd
	FROM job_bom WITH (NOLOCK)
	WHERE wo_id = @wo_id
		AND oper_id = @oper_id
		AND seq_no = @seq_no
		AND item_id = @item_id
	--fetching the bom position & grade details from job_bom for target material
	SELECT 	@target_reqd_grade_cd = reqd_grade_cd,
			@target_item_id = item_id,
			@target_lot_no = ISNULL(@target_fg_lot_no, def_lot_no)
	FROM job_bom WITH (NOLOCK)
	WHERE wo_id = @wo_id
		AND oper_id = @oper_id
		AND seq_no = @seq_no
		AND bom_pos = 0
	----fetching the type of cons configuration from silo
	SELECT @typeOfCons = attr_value
	FROM ent_attr WITH (NOLOCK)
	WHERE ent_id = @storage_ent_id
		AND attr_id = (	SELECT attr_id
						FROM attr WITH (NOLOCK)
						WHERE attr_desc = 'TypeOfCons')
						
	SELECT @process_id=process_id
	FROM wo WITH (NOLOCK)
	WHERE wo_id=@wo_id
	
	SELECT @process_type = attr_value
	FROM process_attr pa WITH (NOLOCK)
		INNER JOIN attr a WITH (NOLOCK) ON pa.attr_id=a.attr_id
	WHERE pa.process_id=@process_id
		AND a.attr_desc='ProcessType'
	--CHECK WO Running Or Completed
	IF (
		 (  SELECT state_cd
			FROM job WITH (NOLOCK)
			WHERE wo_id = @wo_id
				AND oper_id = @oper_id
				AND seq_no = @seq_no
			) = 3
		)
	BEGIN
		PRINT('Consumption Against Running WO')
		SELECT @job_pos = job_pos
		FROM job_exec WITH (NOLOCK)
		WHERE cur_wo_id = @wo_id
			AND cur_oper_id = @oper_id
			AND cur_seq_no = @seq_no
		IF object_id('tempdb..#invlist1') IS NOT NULL
		BEGIN
			DROP TABLE #invlist1
		END
		CREATE TABLE #invlist1
			(
				id INT PRIMARY KEY,
				lot NVARCHAR(40),
				sublot NVARCHAR(40),
				qty FLOAT,
				cons_qty FLOAT,
				consume_full BIT,
				grade_cd INT,
				status_cd INT,
				row_id INT
			)
		PRINT TRY_CONVERT(NVARCHAR(50),@STORAGE_ENT_ID) + ' as storage entity_id'
		PRINT TRY_CONVERT(NVARCHAR(50),@CONS_QTY) + ' as cons qty'
		
		-- inset in temp table
		INSERT INTO #invlist1
		EXEC SP_SA_ofi_item_inv_typeOfCons @storage_ent_id,
										@item_id,
										@qty,
										@typeOfCons

									
		-- v1.03.01 Check if we got already the sublot	
		IF @target_fg_sublot_no IS NULL OR @target_fg_sublot_no = '' OR TRY_CONVERT(BIGINT,@target_fg_sublot_no) < 0
		BEGIN 
			
			INSERT @sublotTable
			EXEC sp_S_ofi_Sublot @wo_id,
			@oper_id,
			@seq_no
			

			SELECT TOP 1 @target_fg_sublot_no = sublot_no
			FROM @sublotTable
		END

		-- get minId for while
		SELECT @minID = MIN(id)
		FROM #invlist1
		WHERE cons_qty >0
		WHILE (@minID IS NOT NULL )
		BEGIN -- BEGIN WHILE
			DELETE
			FROM @silo_inv --1.02.00: removing record from temp table


			SELECT @cons_qty = cons_qty,
				@cons_lot_no = lot,
				@cons_sublot_no= sublot,
				@grade_cd = grade_cd,
				@status_cd = status_cd
			FROM #invlist1
			WHERE id = @minID
			
			PRINT 'Consume From:' + CONVERT( NVARCHAR(40), @storage_ent_id) +' LOT:' + @cons_lot_no + ' SLOT:' + @cons_sublot_no + ' Qty:' + CONVERT( NVARCHAR(40), @cons_qty)
			IF EXISTS ( SELECT 1
						FROM job_bom WITH (NOLOCK)
						WHERE wo_id = @wo_id
							AND oper_id = @oper_id
							AND seq_no = @seq_no
							AND item_id = @item_id
							AND bom_pos>0 ) -- #0.06
			BEGIN
				SET @is_bom_item = 1
			END
			ELSE
			BEGIN
				SET @is_bom_item = 0
			END
			
			SET @groupConsRows=0
			
			SELECT @groupConsRows=attr_value
			FROM oper_attr oa WITH(NOLOCK)
				INNER JOIN attr a WITH(NOLOCK) ON oa.attr_id=a.attr_id
					AND a.attr_desc='GroupConsRows'
			WHERE oper_id=@oper_id
			
			--select @ConsBiDirectionalSilo=attr_value from oper_attr oa with(nolock)
			--inner join attr a with(nolock) on oa.attr_id=a.attr_id and a.attr_desc='ConsBiDirectionalSilo'
			--where oper_id=@oper_id
			-- checking the biDirectional silo
			
			SELECT  @IsBiDirectionalSiloExists = COUNT(*),
					@source_su_id = MAX(su_ent_id)
			FROM ofi_su_selection oss WITH(NOLOCK)
			WHERE oss.wo_id = @wo_id
				AND oss.oper_id = @oper_id
				AND oss.seq_no = @seq_no
				AND oss.dest_type = 2
				AND oss.su_ent_id IN ( 	SELECT oss.su_ent_id
										FROM ofi_su_selection oss WITH(NOLOCK)
											INNER JOIN ent WITH(NOLOCK) ON oss.su_ent_id = ent.ent_id
										WHERE oss.wo_id = @wo_id
											AND oss.oper_id = @oper_id
											AND oss.seq_no = @seq_no
											AND oss.dest_type = 1 )
			IF EXISTS ( SELECT 1
						FROM job_bom WITH (NOLOCK)
						WHERE wo_id = @wo_id
							AND oper_id = @oper_id
							AND seq_no = @seq_no
							AND bom_pos>0
							AND item_id = ( SELECT TOP 1 item_id
											FROM item_inv WITH(NOLOCK)
											WHERE ent_id = @source_su_id) 
					    ) -- #0.06
			BEGIN
				SET @is_siloItem_bom_item = 1
			END
			ELSE
			BEGIN
				SET @is_siloItem_bom_item = 0
			END
			--select @isFirstCons = count(*) from item_cons with(nolock) where wo_id = @wo_id and oper_id = @oper_id and seq_no = @seq_no
			IF @source_su_id IS NOT NULL AND @storage_ent_id=@source_su_id AND @IsBiDirectionalSiloExists = 1 -- 1.02.00 if requested silo is bidirectional silo
			BEGIN
				RAISERROR ('Requested consumed silo is bidirectinal silo', 16, 1)
				RETURN -1
			END
			IF (@grade_cd = @reqd_grade_cd AND @is_bom_item = 1) -- #279_10[trigger is item matching with BOM or not]
			BEGIN
				--IF (@isFirstCons=0 and @IsBiDirectionalSiloExists = 1) -- when bidirectional silo exists and first consumption
				IF (@IsBiDirectionalSiloExists = 1) -- 1.02.00 when bidirectional silo exists
				BEGIN
					--part 1
					SELECT @jb_item_id = jb_item_id
					FROM ofi_su_selection oss WITH(NOLOCK)
					WHERE oss.wo_id = @wo_id
						AND oss.oper_id = @oper_id
						AND oss.seq_no = @seq_no
						AND oss.dest_type = 1
						AND su_ent_id = @source_su_id
					--insert @silo_inv
					--select item_id,lot_no,sublot_no,grade_cd,status_cd,qty_left from item_inv with(nolock) where ent_id = @source_su_id
					--1.02.00: insert only that inventory which should to be reclasified
					INSERT @silo_inv
					SELECT item_id,
						lot_no,
						sublot_no,
						grade_cd,
						status_cd,
						qty_left
					FROM item_inv WITH(NOLOCK)
					WHERE ent_id = @source_su_id
						AND ( item_id<>@target_item_id
								OR grade_cd<>@target_reqd_grade_cd
								OR lot_no<>@target_lot_no )
					--loop here
					SELECT  @max_row_cnt=MAX(row_id),
							@row_cnt = MIN(row_id)
					FROM @silo_inv
					WHILE ((@row_cnt<=@max_row_cnt) AND @row_cnt<>0) -- this loop only execute in case of silo item is BOM item
					BEGIN
						SELECT  @si_item_id = item_id,
								@si_lot_no =lot_no,
								@si_sublot_no =sublot_no,
								@si_grade_cd =grade_cd,
								@si_qty_left =qty_left,
								@si_status_cd = status_cd
						FROM @silo_inv
						WHERE row_id = @row_cnt
						IF (@is_siloItem_bom_item = 1) -- #279_11 [silo item is matching with BOM or not]
						BEGIN
							-- consuming the silo items
							EXEC @return_value = [dbo].[sp_I_Item_Cons_AddCons] @session_id = NULL,
																				@event_time_local = NULL,
																				@user_id = @user_id, -- V1.01.00 Added
																				@ent_id = @ent_id,
																				@job_pos = @job_pos,
																				@bom_pos = @bom_pos,
																				@qty_cons = @si_qty_left,
																				@reas_cd = @cons_reas_cd,
																				@lot_no = @si_lot_no,
																				--	@fg_lot_no = @cons_lot_no,
																				@fg_lot_no = @target_lot_no, -- DS[18-Oct2023] uncommented fg_lot_number
																				@sublot_no = @si_sublot_no,
																				@fg_sublot_no = @target_fg_sublot_no,
																				@from_ent_id = @source_su_id,
																				@item_id = @si_item_id,
																				@ext_ref = NULL,
																				@apply_scaling_factor = NULL,
																				@genealogy_id = NULL,
																				@upstream_event_id = NULL,
																				@segment_requirement_id = NULL,
																				@segment_response_id = NULL,
																				@comments = NULL,
																				@spare1 = NULL,
																				@spare2 = NULL,
																				@spare3 = NULL,
																				@spare4 = NULL,
																				@created_at_utc = @date_time_UTC, -- V1.01.00 Updated
																				@row_id = @row_id OUTPUT
						END
						ELSE -- silo having the non bom material, need to consume in loop
						BEGIN
							EXEC @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect] @from_ent_id = @source_su_id,
																						@item_id = @si_item_id,
																						@lot_no = @si_lot_no,
																						@sublot_no = @si_sublot_no,
																						@qty_cons = @si_qty_left,
																						@reas_cd = @cons_reas_cd,
																						@grade_cd = @si_grade_cd,
																						@status_cd = @si_status_cd,
																						@user_id = @user_id -- V1.01.00 Added
																						,
																						@wo_id = @wo_id,
																						@oper_id = @oper_id,
																						@seq_no = @seq_no,
																						@shift_start_local = NULL
																						--,@fg_lot_no = NULL
																						,
																						@fg_lot_no = @target_lot_no -- DS[18-Oct2023] uncommented fg_lot_number
																						,
