	BEGIN
		-- v1.03.01 Check if we got already the sublot	
		IF @target_fg_sublot_no IS NULL OR @target_fg_sublot_no = '' OR TRY_CONVERT(BIGINT,@target_fg_sublot_no) < 0
		BEGIN 
			--AP: 23-fEB-23, Getting sublot number			
			INSERT @sublotTable
			EXEC sp_S_ofi_Sublot @wo_id,
			@oper_id,
			@seq_no
			
			SELECT TOP 1 @target_fg_sublot_no = sublot_no
			FROM @sublotTable
		END
			
		PRINT('Consumption Against Completed/Stopped WO') --v01.00.00 Added stopped Wo also
		SELECT @bom_pos=bom_pos,
			@reqd_grade_cd=reqd_grade_cd
		FROM job_bom WITH (NOLOCK)
		WHERE wo_id = @wo_id
			AND oper_id = @oper_id
			AND seq_no = @seq_no
			AND item_id = @item_id
			
		--type of cons
		SELECT @typeOfCons = attr_value
		FROM ent_attr WITH (NOLOCK)
		WHERE ent_id = @storage_ent_id
			AND attr_id =
			(   SELECT attr_id
				FROM attr WITH (NOLOCK)
				WHERE attr_desc = 'TypeOfCons')
		
		-- review temp table 2
		IF object_id('tempdb..#invlist2') IS NOT NULL
		BEGIN
			DROP TABLE #invlist2
		END
		CREATE TABLE #invlist2
			(
				id INT PRIMARY KEY,
				lot NVARCHAR(40),
				sublot NVARCHAR(40),
				qty FLOAT,
				cons_qty FLOAT,
				consume_full BIT,
				grade_cd INT,
				status_cd INT,
				row_id INT
			)
		PRINT @STORAGE_ENT_ID
		PRINT @CONS_QTY
		INSERT INTO #invlist2
		EXEC SP_SA_ofi_item_inv_typeOfCons @storage_ent_id,
											@item_id,
											@qty,
											@typeOfCons
		-- output ?
		SELECT *
		FROM #invlist2
		
		SELECT @minID = MIN(id)
		FROM #invlist2
		WHERE cons_qty >0
		WHILE ( @minID IS NOT NULL )
		BEGIN
			SELECT @cons_qty = cons_qty,
				@cons_lot_no = lot,
				@cons_sublot_no= sublot,
				@grade_cd = grade_cd,
				@status_cd = status_cd
			FROM #invlist2
			WHERE id = @minID

			PRINT 'Consume From:' + CONVERT ( NVARCHAR(40), @storage_ent_id ) +' LOT:' + @cons_lot_no + ' SLOT:' + @cons_sublot_no + ' Qty:' + CONVERT ( NVARCHAR(40), @cons_qty )
			IF EXISTS (	SELECT 1
