						WHERE wo_id = @wo_id
							AND oper_id = @oper_id
							AND seq_no = @seq_no
							AND item_id = @item_id
						)
			BEGIN
				SET @is_bom_item = 1
			END
			ELSE
			BEGIN
				SET @is_bom_item = 0
			END
		
