																			@reas_cd = @cons_reas_cd,
																			@lot_no = @cons_lot_no,
																			--@fg_lot_no = NULL,
																			@fg_lot_no = @target_lot_no, -- DS[18-Oct2023] uncommented fg_lot_number
																			@sublot_no = @cons_sublot_no,
																			@fg_sublot_no = @target_fg_sublot_no,
																			@from_ent_id = @storage_ent_id,
																			@ext_ref = NULL,
																			@genealogy_id = NULL,
																			@upstream_event_id = NULL,
																			@segment_requirement_id = NULL,
																			@segment_response_id = NULL,
																			@comments = NULL,
																			@spare1 = NULL,
																			@spare2 = NULL,
																			@spare3 = NULL,
																			@spare4 = NULL,
																			@created_at_utc = @date_time_UTC, -- V1.01.00 Updated
																			@row_id = @row_id OUTPUT,
																			@time_zone_bias_value = NULL
			END
			ELSE
			BEGIN
				EXEC @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect] 	@from_ent_id = @storage_ent_id,
																			@item_id = @item_id,
																			@lot_no = @cons_lot_no,
																			@sublot_no = @cons_sublot_no,
																			@qty_cons = @cons_qty,
																			@reas_cd = @cons_reas_cd,
																			@grade_cd = @grade_cd,
																			@status_cd = @status_cd,
																			@user_id = @user_id -- V1.01.00 Added
																			,
																			@wo_id = @wo_id,
																			@oper_id = @oper_id,
																			@seq_no = @seq_no,
																			@shift_start_local = NULL
																			--,@fg_lot_no = NULL
																			,
																			@fg_lot_no = @target_lot_no -- DS[18-Oct2023] uncommented fg_lot_number
																			,
																			@fg_sublot_no = @target_fg_sublot_no,
																			@item_scrapped = 0,
																			@ent_id = @ent_id,
																			@shift_id = NULL,
																			@qty_cons_erp = 0,
																			@ext_ref = NULL,
																			@transaction_type = 0,
																			@genealogy_id = NULL,
																			@upstream_event_id = NULL,
																			@segment_requirement_id = NULL,
																			@segment_response_id = NULL,
																			@comments = NULL,
																			@spare1 = NULL,
																			@spare2 = NULL,
																			@spare3 = NULL,
																			@spare4 = NULL,
																			@shift_start_utc = NULL,
																			@time_zone_bias_value = @tz_bias,
																			@row_id=@row_id OUTPUT
			END		
			PRINT @PROCESS_TYPE
			IF @process_type = 'Blocked'
			BEGIN -- blocked
				-- Get Prod Item id
				SELECT @prod_item_id = item_id
				FROM wo WITH (NOLOCK)
				WHERE wo_id = @wo_id
				
				PRINT 'PROD - BLOCKED - ' + @prod_item_id
				IF EXISTS 	(   SELECT 1
								FROM job_history WITH (NOLOCK)
								WHERE wo_id = @wo_id
							)
				BEGIN
					-- GET job start time
					SELECT TOP 1 @prod_date_time_UTC = job_start_utc
					FROM job_history WITH (NOLOCK)
					WHERE wo_id = @wo_id
					
					PRINT 'PROD - BLOCKED - ' + @prod_item_id + ' - ' + CONVERT( NVARCHAR(40), @prod_date_time_UTC )
					--Add Prod
					EXEC @return_value = [dbo].[sp_I_Item_Prod_AddProdPostExec] @session_id = NULL,
																				@user_id = @user_id, -- V1.01.00 Added
																				@ent_id = @ent_id,
																				@qty_prod = @cons_qty,
																				@wo_id = @wo_id,
																				@oper_id = @oper_id,
																				@seq_no = @seq_no,
																				@created_at_utc = @date_time_UTC, -- V1.01.00 Updated
																				@shift_start_local = NULL,
																				@hour_start_local = NULL,
																				@shift_id = NULL,
																				@item_id = @prod_item_id,
																				@reas_cd = @prod_reas_cd,
																				@lot_no = @cons_lot_no,
																				@rm_lot_no = NULL,
																				@sublot_no = @cons_sublot_no,
																				@rm_sublot_no = NULL,
																				@to_ent_id = NULL,
																				@processed = NULL,
																				@byproduct = NULL,
																				@ext_ref = NULL,
																				@move_status = NULL,
																				@genealogy_id = NULL,
																				@event_id = NULL,
																				@segment_requirement_id = NULL,
																				@segment_response_id = NULL,
																				@comments = NULL,
																				@spare1 = NULL,
																				@spare2 = NULL,
																				@spare3 = NULL,
																				@spare4 = NULL,
																				@time_zone_bias_value = @tz_bias,
																				@row_id = @row_id OUTPUT
				END -- job_history exististed
			END -- process type blocked
			
			SELECT @minID = MIN(id)
			FROM #invlist2
			WHERE id > @minID
				AND cons_qty >0
		END -- end of while
		DROP TABLE #invlist2
	END -- stopped jobs
END

--===========================================================================================
-- Name:		[sp_D_ofi_DeleteMaterialTemplate]
-- Description:	The stored procedure will delete record to the material template table
-- Usage:		DeleteMaterialTemplate
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-12			Initial version.
-- 0.02.00	YG				2022-10-24			Add flag for audit trail in the parameter
-- ===========================================================================================
CREATE Procedure [dbo].[sp_D_ofi_DeleteMaterialTemplate]
	@template_name NVARCHAR(40) = NULL,
	@attr_id INT = NULL,
	@user_name NVARCHAR(40) = NULL,
	@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail
AS
BEGIN
	DECLARE	@iRowId INT,
			@strModuleName NVARCHAR(80) = 'MM_Template',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'delete',
			@dataRecord XML,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS;

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	SELECT @iRowId = row_id
	FROM [dbo].[ofi_master_attr]
	WHERE item_group = @template_name 
		AND attr_id = @attr_id
		AND (process_id IS NULL AND oper_id IS NULL)

	-- retrieve datas and set into xml format
	SET @dataRecord = (
			SELECT 
				row_id,
				item_group,
				attr_id,
				def_value,
				created_at_utc,
				created_at_local,
				last_edit_at_local,
				last_edit_at_utc,
				@user_name AS last_edit_by
			FROM [dbo].ofi_master_attr WITH(NOLOCK) WHERE row_id = @iRowId
			FOR XML RAW('data')
			);

	DELETE [dbo].[ofi_master_attr]
	WHERE
		row_id = @iRowId

	IF (@audit_trail = 1)
	BEGIN
		-- At least one record with the row_id is required for storing the deleted record in the audit_trail table.
		DELETE @auditTrailParameters
		INSERT INTO @auditTrailParameters (
			row_id
			,field_name
			,field_value
			)
		VALUES 
			(
			@iRowId
			,'@row_id'
			,NULL
			)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@xmlDeletedRow = @dataRecord,
			@deletedRowSourceTable = '[dbo].[ofi_master_attr]',
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info'
	END
END

