/*
-- ===========================================================================================
-- Name:  [sp_S_ofi_WO_ValidateBeforeCreate]
-- Description: [CR 00188202] Validates data of the about-to-be-created WO, returning
--     a boolean value determining whether MDMCreateWoWorkflow can be safely executed.
-- Returns: (IsValid bit, Message nvarchar) - multiple messages are separated by '; ' 
--     - If valid: (1, NULL)
--     - If valid with warnings: (1, '...')
--     - If invalid: (0, '...')
--
-- Usage: Invoked when clicking the "Create" button in MDMCreateWoForm, before executing
--     MDMCreateWoWorkflow.
-- ===========================================================================================
-- Version  Author  Date (yyyy-MM-dd)   Change description
-- 0.01.00  MH      2025-09-15          Initial version.
-- ===========================================================================================
*/
-- MH: Take all the parameters in case validation requests are expanded.
CREATE PROCEDURE [dbo].[sp_S_ofi_WO_ValidateBeforeCreate] (
    @wo_id AS nvarchar(40),
    @process_id AS nvarchar(40),
    @item_id AS nvarchar(40),
    @req_qty AS float,
    @lot_no AS nvarchar(40),
    @release_date AS datetime,
    @due_date AS datetime,
    @customer AS nvarchar(80),
    @user_id AS nvarchar(40)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IsValid AS bit = 1;
    DECLARE @ErrorMessages AS TABLE (Message nvarchar(255))

    -- MH: Check if the item ID has a preferred recipe to avoid setting update_inv to 0 when creating the WO.
    IF NOT EXISTS(SELECT 1 FROM bom_ver WHERE parent_item_id = @item_id AND preferred_ver = 1)
    BEGIN
        SET @IsValid = 0;
        
        -- 'Item ID does not have a preferred recipe/BOM'
        INSERT INTO @ErrorMessages (Message) VALUES ([dbo].fn_s_ofi_getLangString(500044, NULL, NULL));
    END

    -- Validation finished - return the results.
    SET NOCOUNT OFF;
    SELECT
        @IsValid AS IsValid,
        STRING_AGG(Message, '; ') AS Message
    FROM @ErrorMessages 
END

