-- 05/16/2003	Raghu				(HD# 2570) Disallow insertion of a step having a seq_no less than or equal to any existing step in job_step_data for this job.
-- 06-06-2003	SJ			1.6.0	Oracle migration changes - (TOP 1 ...)
-- 09/21/2005	Raghu		3.1.0	Part of DB Changes
-- 01/15/2007	KRF			3.2.1	HD# 9222, part of DB changes - added @reqd_rep argument
-- 01/18/2007	KRF			3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 02/02/2007	KRF			3.2.1	HD# 9410, part of DB changes - removed script_id argument
-- 06/14/2007   AML			3.2.2   HD# 9222, 9473, Default reqd_rep to 0; if not supplied.
-- 10/24/2007	AML			3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--									dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 10/31/2007	AML			3.4.0	DB Changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN

	SET NOCOUNT ON

	DECLARE @step_grp_seq	INT
		,	@last_edit_by	NVARCHAR(40)

	EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
	SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

	SELECT @step_grp_seq = step_grp_seq FROM job_step_grp WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND step_grp_id = @step_grp_id

	IF EXISTS (SELECT 'X' FROM job_step_data jsd WITH (NOLOCK), job_step js WITH (NOLOCK), job_step_grp jsg WITH (NOLOCK)
			WHERE jsd.wo_id = js.wo_id AND jsd.oper_id = js.oper_id AND jsd.seq_no = js.seq_no AND jsd.step_no = js.step_no
			  AND js.wo_id = jsg.wo_id AND js.oper_id = jsg.oper_id AND js.seq_no = jsg.seq_no AND js.step_grp_id = jsg.step_grp_id
			  AND jsd.wo_id = @wo_id AND jsd.oper_id = @oper_id AND jsd.seq_no = @seq_no
			  AND (jsg.step_grp_seq > @step_grp_seq  OR (jsg.step_grp_seq = @step_grp_seq AND jsg.step_grp_id > @step_grp_id))) BEGIN
		RAISERROR ('Steps with the lower step seq_no or step_no on this step group are already started{3892}', 16, 1)
		RETURN -1
	END
	ELSE BEGIN
		IF EXISTS (SELECT 'X' FROM job_step_data jsd WITH (NOLOCK), job_step js WITH (NOLOCK), job_step_grp jsg WITH (NOLOCK)
				WHERE jsd.wo_id = js.wo_id AND jsd.oper_id = js.oper_id AND jsd.seq_no = js.seq_no AND jsd.step_no = js.step_no
				  AND js.wo_id = jsg.wo_id AND js.oper_id = jsg.oper_id AND js.seq_no = jsg.seq_no AND js.step_grp_id = jsg.step_grp_id
				  AND jsd.wo_id = @wo_id AND jsd.oper_id = @oper_id AND jsd.seq_no = @seq_no
				  AND (jsg.step_grp_seq > @step_grp_seq  OR (jsg.step_grp_seq = @step_grp_seq AND jsg.step_grp_id >= @step_grp_id))
				  AND (js.step_seq > @step_seq  OR (js.step_seq = @step_seq AND js.step_no >= @step_no))) BEGIN
			RAISERROR ('Steps with the lower step seq_no or step_no on this step group  step group are already started{3892}', 16, 1)
			RETURN -1
		END
	END

	/*
	IF @action_type IS null SET  @action_type = 0
	IF @complete_cond IS null SET @complete_cond = 3
	IF @allow_bypass IS null SET  @allow_bypass = 0
	IF @enter_data IS null SET  @enter_data = 0
	IF @reqd_rep IS null SET  @reqd_rep = 0  -- Added 1/15/07 KRF
	*/

	SELECT	@action_type = ISNULL( @action_type, 0 )
		,	@complete_cond = ISNULL( @complete_cond, 3 )
		,	@allow_bypass = ISNULL( @allow_bypass, 0 )
		,	@enter_data = ISNULL( @enter_data, 0 )
		,	@reqd_rep = ISNULL( @reqd_rep, 0 )
		,	@limit_warning = ISNULL( @limit_warning, 0 )

	INSERT INTO job_step
	(
		wo_id, oper_id, seq_no, step_no, step_name, step_seq, step_desc, action_type, std_time, complete_cond, allow_bypass, enter_data,
		step_grp_id, spc_char, form_name, data_log_grp_id, reqd_rep, control_type, high_limit, low_limit, limit_warning, spare1, spare2,
		spare3, spare4, spare5, spare6, last_edit_comment, last_edit_by, last_edit_at
	)
	VALUES
	(
		@wo_id, @oper_id, @seq_no, @step_no, @step_name, @step_seq, @step_desc, @action_type, @std_time, @complete_cond, @allow_bypass,
		@enter_data, @step_grp_id, @spc_char, @form_name, @data_log_grp_id, @reqd_rep, @control_type, @high_limit, @low_limit, @limit_warning,
		@spare1, @spare2, @spare3, @spare4, @spare5, @spare6, @last_edit_comment, @last_edit_by, @last_edit_at
	)

END

