--* Return timestamp
--SET @mod_id = (SELECT CONVERT(varchar(30), CONVERT(DATETIME, mod_id), 13)
SELECT @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
FROM user_name
WHERE (user_id = @user_id)

-- ===========================================================================================
-- Name:		sp_S_ofi_st_trans_queue
-- Description:	Get stock transfer details for selected line with current status and details

-- Usage:		Stock Transfer UI
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	Veervar Joshi	2024-01-04			Initial version.
-- 0.01.01	Veervar Joshi	2024-03-20			Updating @row_id as optional parameter
-- ===========================================================================================
CREATE PROCEDURE [dbo].[sp_S_ofi_st_trans_queue] 
	 @ent_id INT,
	@row_id INT=NULL,
	@entName VARCHAR(40) OUTPUT,
	@srcSU INT OUTPUT,
	@destSU INT OUTPUT,
	@transType VARCHAR(20) OUTPUT,
	@itemId NVARCHAR(40) OUTPUT,
	@qty FLOAT OUTPUT,
	@autItemId NVARCHAR(40) OUTPUT,
	@mesSrcSU NVARCHAR(40) OUTPUT,
	@mesDestSU NVARCHAR(40) OUTPUT


AS
BEGIN
	
	SET NOCOUNT ON ;

	DECLARE @attr_id_SUNumberInAUT INT

	SELECT @attr_id_SUNumberInAUT=attr_id FROM attr WITH (NOLOCK)  WHERE attr_desc = 'SUNumberInAUT' AND attr_grp = 2

  --GET FINAL DATA SET
  SELECT
  @entName=entl.ent_name,
  @srcSU=ea.attr_value,
  @qty=target_qty,
  @destSU=ean.attr_value,
  @transType=st_transfer_type,  
  @autItemId=autitem.aut_item_id,
  @itemId=item.item_id
  FROM  ofi_st_trans_selection sts  
  INNER JOIN item ON sts.src_item_id=ITEM.item_id
  INNER JOIN ent ON sts.src_su_ent_id=ent.ent_id
  INNER JOIN ent entl ON sts.ent_id=entl.ent_id
  INNER JOIN ent entN ON sts.dest_su_ent_id=entN.ent_id  
  CROSS APPLY ufn_ofi_mes_aut_itemid(item.item_id ,1) autitem
  INNER JOIN [dbo].ent_attr ea WITH (NOLOCK) ON sts.src_su_ent_id=ea.ent_id 													  
													   AND ea.attr_id = @attr_id_SUNumberInAUT
 LEFT JOIN [dbo].ent_attr ean WITH (NOLOCK) ON sts.dest_su_ent_id=ean.ent_id 													  
													   AND ean.attr_id = @attr_id_SUNumberInAUT
   WHERE  sts.ent_id=@ent_id and sts.is_active=1
  

 END

