-- Author:		Thommy Djupenstrom
-- Create date: 2017-03-14
-- Description:	SP is used to execute the custom functions
-- Change History
-- Version		Date		Change By		Change Description
-- 1.0			2017-03-14	TDJ				Initial Revision
-- 1.1			2017-11-15	WL				Change made to include @commandreply as result
-- =============================================
CREATE PROCEDURE [dbo].[SP_S_MDM_Sched_Execute_Custom_Functions]
(
@I_SPNAME NVARCHAR(250),
@I_SessionId int,
@I_Location nvarchar(50) = NULL,
@I_User_Name  nvarchar(50) = NULL,
@I_SelEvent nvarchar(50) = NULL,
@I_EQLoaded nvarchar(MAX) = NULL,
@I_CommandParam nvarchar(max) = NULL,
@I_commandreply nvarchar(max) = 'success' output 
)
AS
BEGIN
set nocount on
declare  @ent_name NVARCHAR(50)
DECLARE @SQLString nvarchar(max);  
DECLARE @ParmDefinition nvarchar(500); 
Declare @UseSelect bit
Declare @UseLoaded bit
Declare @commandreply nvarchar(max) 
Declare @CommandParam nvarchar(max)
select @UseSelect=UseSelect, @UseLoaded=UseLoaded from [SDB].[dbo].[Scheduler_Custom_Functions] where StoredProcedure=@I_SPNAME


	
	SET @SQLString = N'exec ' + @I_SPNAME + ' @SessionId, @user_name'		
	SET @ParmDefinition = N'@SessionId int, @user_name  nvarchar(50)';
	if(@UseSelect=1)
	BEGIN
		set @ParmDefinition=@ParmDefinition+N',@I_SelEvent nvarchar(50)'
		set @SQLString=@SQLString+N',@I_SelEvent'
	END
	if(@UseSelect=1)
	BEGIN
		set @ParmDefinition=@ParmDefinition+N',@I_EQLoaded nvarchar(MAX)'
		set @SQLString=@SQLString+N',@I_EQLoaded'
	END


	set @ParmDefinition=@ParmDefinition+N',@I_CommandParam nvarchar(MAX)'
		set @SQLString=@SQLString+N',@I_CommandParam'


	set @ParmDefinition=@ParmDefinition+N', @commandreply nvarchar(max) OUTPUT'
	set @SQLString=@SQLString+N', @commandreply OUTPUT'
	 


	if (@UseSelect = 0 and @UseLoaded= 0)
		EXECUTE sp_executesql @SQLString, @ParmDefinition,  
                     @SessionId = @I_SessionId, @user_name = @I_User_Name,@I_CommandParam= @I_CommandParam, @commandreply = @I_commandreply output;

	if (@UseSelect = 1 and @UseLoaded= 0)
		EXECUTE sp_executesql @SQLString, @ParmDefinition,  
                     @SessionId = @I_SessionId, @user_name = @I_User_Name,@I_SelEvent=@I_SelEvent,@I_CommandParam= @I_CommandParam, @commandreply = @I_commandreply output ;
	
	if (@UseSelect = 0 and @UseLoaded= 1)
		EXECUTE sp_executesql @SQLString, @ParmDefinition,  
                     @SessionId = @I_SessionId, @user_name = @I_User_Name,@I_EQLoaded=@I_EQLoaded,@I_CommandParam= @I_CommandParam, @commandreply = @I_commandreply output;

	if (@UseSelect = 1 and @UseLoaded= 1)
		EXECUTE sp_executesql @SQLString, @ParmDefinition,  
                     @SessionId = @I_SessionId, @user_name = @I_User_Name,@I_SelEvent=@I_SelEvent,@I_EQLoaded=@I_EQLoaded,@I_CommandParam= @I_CommandParam, @commandreply = @I_commandreply output ;

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	

	select @I_commandreply as message
END


