-- Description:Storage Unit Low Level Signal Update

-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	 AJEET         	  2022-09-14		Intial Version
-- 0.01.01	 YG				  2024-02-09		Update Script Body Comment and Missing No Lock
-- 0.02.00	 YG				  2024-03-12		Added Good Consumption (Item Reason), Validation for non running job, Ensure qty_left has value for empty inventory  
-- 0.03.00	 YG			      2024-03-21		Update logic how to get latest consumption and disable scrap logic
--
-- Exec sp_U_ofi_SULowSignal '500BN001'
-- =============================================
CREATE PROCEDURE [dbo].[sp_U_ofi_SULowSignal_Backup240324] 
	@SU_Name nvarchar(40)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- Declare variable
	DECLARE @storage_ent_id INT
			,@cons_lot_no NVARCHAR(40) = NULL
			,@cons_sublot_no NVARCHAR(40) = NULL
			,@cons_qty FLOAT = 0
			,@avl_qty FLOAT = 0
			--,@temp_qty FLOAT = 0
			,@consumed_qty FLOAT = 0
			,@job_pos INT = 0 
			,@bom_pos INT = 0
			,@job_state INT -- 0.03.00 Added
			,@date_time_UTC datetime =  GETUTCDATE()
			,@return_value int
			,@row_id INT32
			,@minID INT
			,@typeOfCons NVARCHAR(20) = 'FIFO'
			,@process_id NVARCHAR(30)
			,@process_type NVARCHAR(30)
			,@prod_info NVARCHAR(4000)
			,@prod_item_id NVARCHAR(40)
			,@prod_date_time_UTC datetime
			,@user_id NVARCHAR(40)=NULL
			,@wo_state INT 
	declare @ent_id int, @qty_left float, @su_level_threshold int, @plant_level_threshold int, @final_threshold int, @wo_id nvarchar(40),@Out int,@inv_item_id nvarchar(40)
	declare @item_id nvarchar(40),@target_sched_ent_id int , @cons_ent_id int, @oper_id nvarchar(40), @seq_no int
	DECLARE @Counter INT, @iterate int=1
	declare @TempInv table(ID INT IDENTITY(1, 1) primary key, ent_id int,item_id nvarchar(40), lot_no nvarchar(40), sub_lot_no nvarchar(40), qty float)
	declare @defaultUoMDesc NVARCHAR(20) = 'KG'
		   ,@defaultUoMId INT 

	-- Get User Id
	EXEC sp_S_DB_Status_GetAudTrailUsr @user_id OUTPUT, NULL

	Select @ent_id= ent_id from ent(nolock) where ent_name=@SU_Name
	print @ent_id

	-- Get Default UoM Desc
	SELECT @defaultUoMDesc=attr_value FROM ent_attr WITH (NOLOCK) WHERE ent_id = @ent_id AND attr_id = (SELECT attr_id 
																											FROM attr WITH (NOLOCK) 
																											WHERE attr_desc = 'DefaultStorageUoM' and attr_grp = 2)

	SET @defaultUoMDesc = ISNULL(@defaultUoMDesc,'KG')

	-- v0.02.00 Get Good Consumption (Item Reason)
	DECLARE @strGoodConsReas NVARCHAR(40) = 'Good Consumption',
			@intGoodConsReas INT = NULL
	SELECT @intGoodConsReas = reas_cd FROM item_reas WITH (NOLOCK) 
	WHERE reas_desc= @strGoodConsReas

	SET @intGoodConsReas = ISNULL(@intGoodConsReas, 1)

	-- Get Default UoM Id
	SELECT @defaultUoMId = uom_id FROM uom WITH(NOLOCK)
	WHERE description = @defaultUoMDesc

	-- Get current qty
	select @qty_left=SUM(qty_left),@inv_item_id=max(item_id) from item_inv(nolock) where ent_id=@ent_id
	print @qty_left

	-- Get plant and storage threshold
	select @su_level_threshold = CONVERT(INT,REPLACE(ea.attr_value, ',','')) from ent_attr(nolock) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
						join attr(nolock) a on ea.attr_id=a.attr_id
						where ea.ent_id=@ent_id and a.attr_desc='StorageUnitThreshold'
	print @su_level_threshold

	select @plant_level_threshold =  CONVERT(INT,REPLACE(ea.attr_value, ',','')) from ent_attr(nolock) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
						join attr(nolock) a on ea.attr_id=a.attr_id
						where ea.ent_id=(select top 1 ent_id from ent(nolock) where parent_ent_id is null order by ent_id )  
						and a.attr_desc='StorageUnitThreshold'

	-- get converted qty left
	select @qty_left= dbo.[fn_ofi_ConvertQtyByItemIdAndUom](@inv_item_id,@qty_left,uom_id,@defaultUoMId,NULL,NULL,NULL,NULL)  
	from item with (nolock) where item_id=@inv_item_id
	 
	-- If the Silo level threshold is missing then take the plan level threshold
	if(@su_level_threshold = 0)
	begin
		set @final_threshold = @plant_level_threshold
	end
	else
	begin
		set @final_threshold = @su_level_threshold
	end
	
	-- v0.02.00 Ensure qty has value even no inventory
	SET @qty_left = ISNULL(@qty_left,0.00)

	-- if silo qty less than the thresshold
	 if(@qty_left < @final_threshold and @qty_left > 0) -- v0.02.00 Add validation qty must more than 0
	 BEGIN
	 
		--select @wo_id= j.wo_id,@item_id=su.jb_item_id, @target_sched_ent_id=j.target_sched_ent_id, @job_pos=je.job_pos,
		--@oper_id=j.oper_id,@seq_no=j.seq_no
		--from ofi_su_selection(nolock) su
		--join job(nolock) j on j.wo_id=su.wo_id 
		--inner join job_exec(nolock) je on j.wo_id=je.cur_wo_id and j.oper_id=je.cur_oper_id and j.seq_no=je.cur_seq_no
		--where su_ent_id=@ent_id and dest_type=1 and j.state_cd=3

		--- Added by Mahesh 07042023 -- 0.03.00 Disabled
		--SELECT TOP 1  @wo_id=j.wo_id,@item_id=ic.item_id, @target_sched_ent_id=j.target_sched_ent_id, @job_pos=je.job_pos,
		--			  @oper_id=j.oper_id,@seq_no=j.seq_no
		--from item_cons (nolock) ic
		--join job(nolock) j on j.wo_id=ic.wo_id 
		--inner join job_exec(nolock) je on j.wo_id=je.cur_wo_id and j.oper_id=je.cur_oper_id and j.seq_no=je.cur_seq_no
		--where from_ent_id=@ent_id and j.state_cd=3 order  by ic.last_edit_at desc

		-- 0.03.00 Added
		SELECT TOP 1  @wo_id=j.wo_id,@item_id=ic.item_id, @target_sched_ent_id=j.target_sched_ent_id, @job_pos=je.job_pos,
					  @oper_id=j.oper_id,@seq_no=j.seq_no, @job_state = j.state_cd
		from item_cons (nolock) ic
		join job (nolock) j on j.wo_id=ic.wo_id and j.oper_id=ic.oper_id and j.seq_no=ic.seq_no
		left outer join job_exec(nolock) je on j.wo_id=je.cur_wo_id and j.oper_id=je.cur_oper_id and j.seq_no=je.cur_seq_no
		where from_ent_id=@ent_id 
		order  by ic.last_edit_at desc
		
		-- check the running job on silo and assign qty_left to it
		-- if(@wo_id is not null) -- 0.03.00 Disabled
		if(@wo_id is not null and @job_state = 3) -- 0.03.00 Added
		BEGIN
		    Print 'WoId is running'
			--UPDATE item_cons set qty_cons =qty_cons+@qty_left where row_id =(select top 1 row_id from item_cons where wo_id=@wo_id and item_id =@item_id order by row_id desc )
		
			/*select top 1 @cons_ent_id=ent_id, @bom_pos=jb.bom_pos			
			from item_inv(nolock) icqw
			inner join job_bom(nolock) jb on ic.item_id=jb.item_id  
			where jb.wo_id=@wo_id and jb.oper_id=@oper_id and jb.seq_no=@seq_no and ic.item_id =@item_id 
			order by ic.row_id desc */

			select top 1 @cons_ent_id=@ent_id, @bom_pos=jb.bom_pos            
            from job_bom(nolock) jb
            where jb.wo_id=@wo_id and jb.oper_id=@oper_id and jb.seq_no=@seq_no and jb.item_id =@item_id ;

			insert into @TempInv(ent_id,item_id , lot_no , sub_lot_no,qty)
			select iv.ent_id, iv.item_id,iv.lot_no, iv.sublot_no,qty_left--dbo.[fn_ofi_ConvertQtyByItemIdAndUom](iv.item_id,iv.qty_left,uom_id,@defaultUoMId,NULL,NULL,NULL,NULL)			
			from item_inv(nolock) iv
			where ent_id=@ent_id and iv.item_id in (select item_id from job_bom(nolock) jb where jb.wo_id=@wo_id and jb.oper_id=@oper_id and jb.seq_no=@seq_no )

			SET @Counter=(select count(1) from @TempInv)
			
			WHILE ( @iterate <= @Counter)
			BEGIN
				select @cons_lot_no=lot_no, @cons_sublot_no=sub_lot_no,@qty_left=qty, @item_id=item_id from @TempInv where ID=@iterate

				
				EXEC	@return_value = [dbo].[sp_I_Item_Cons_AddCons]
					@session_id = NULL,
					@event_time_local = NULL,
					@user_id = @user_id,
					@ent_id = @target_sched_ent_id,
					@job_pos = @job_pos,
					@bom_pos = @bom_pos,
					@qty_cons = @qty_left,
					@reas_cd = @intGoodConsReas, -- updated v0.02.00 
					@lot_no = @cons_lot_no,
					@fg_lot_no = NULL,
					@sublot_no = @cons_sublot_no,
					@fg_sublot_no =NULL,
					@from_ent_id = @ent_id,
					@item_id = @item_id,
					@ext_ref = NULL,
					@apply_scaling_factor = NULL,
					@genealogy_id = NULL,
					@upstream_event_id = NULL,
					@segment_requirement_id = NULL,
					@segment_response_id = NULL,
					@comments = 'Trigger with Low Signal-Consumed on running Job',
					@spare1 = NULL,
					@spare2 = NULL,
					@spare3 = NULL,
					@spare4 = NULL,
					@created_at_utc = @date_time_UTC,
					@row_id = @row_id OUTPUT
				
				SET @iterate  = @iterate  + 1
			END

		
		END
		
		if(@wo_id IS not NULL and @job_state in (4,5)) -- 0.03.00 Added
		--if(@wo_id IS NULL) -- 0.03.00 Disabled
		BEGIN
			Print 'WoId is not running'
			--select top 1 @wo_id= j.wo_id from  job(nolock) j  where  j.state_cd=4 order by act_finish_time_utc desc
			--MP20072023
			SELECT TOP 1  @wo_id=j.wo_id,@cons_ent_id=target_sched_ent_id, @oper_id=ic.oper_id, @seq_no=ic.seq_no, @bom_pos=jb.bom_pos,@item_id=ic.item_id,
						  @oper_id=j.oper_id,@seq_no=j.seq_no
			from item_cons (nolock) ic
			join job(nolock) j on j.wo_id=ic.wo_id and j.oper_id = ic.oper_id and j.seq_no = ic.seq_no -- v0.02.00 Added checking on the oper_id and seq_no
			inner join job_bom(nolock) jb on ic.item_id=jb.item_id and ic.wo_id=jb.wo_id and ic.oper_id=jb.oper_id and ic.seq_no=jb.seq_no
			--inner join job_exec(nolock) je on j.wo_id=je.cur_wo_id and j.oper_id=je.cur_oper_id and j.seq_no=je.cur_seq_no
			where from_ent_id=@ent_id and j.state_cd in (4,5) order by ic.last_edit_at desc -- v0.02.00 Take order for completed and suspended / stopped job
			
			--select top 1 @cons_ent_id=ent_id, @oper_id=ic.oper_id, @seq_no=ic.seq_no, @bom_pos=jb.bom_pos,@item_id=ic.item_id		
			--from item_cons(nolock) ic 
			--inner join job_bom(nolock) jb on ic.item_id=jb.item_id and ic.wo_id=jb.wo_id and ic.oper_id=jb.oper_id and ic.seq_no=jb.seq_no
			--where ic.wo_id=@wo_id and ic.item_id =@item_id 
			--order by ic.row_id desc 
		
			select @wo_state = state_cd from wo with (nolock) where wo_id = @wo_id

			-- v0.02.00 Validate order state
			if (@wo_state = 3) -- 3 = Closed
			begin
				set @Out = 2
				select @Out as [Out], @ent_id as EntId, @wo_id as WoId
				return
			end 
			
			insert into @TempInv(ent_id,item_id , lot_no , sub_lot_no,qty)
			select iv.ent_id, iv.item_id,iv.lot_no, iv.sublot_no,qty_left--dbo.[fn_ofi_ConvertQtyByItemIdAndUom](iv.item_id,iv.qty_left,uom_id,@defaultUoMId,NULL,NULL,NULL,NULL)			
			from item_inv(nolock) iv
			where ent_id=@ent_id and iv.item_id in (select item_id from job_bom(nolock) jb where jb.wo_id=@wo_id and jb.oper_id=@oper_id and jb.seq_no=@seq_no )

			
			SET @Counter=(select count(1) from @TempInv)
			WHILE ( @iterate <= @Counter)
			BEGIN
				select @cons_lot_no=lot_no, @cons_sublot_no=sub_lot_no,@qty_left=qty,@item_id=item_id  from @TempInv where ID=@iterate
				
				EXEC	@return_value = [dbo].[sp_I_Item_Cons_AddConsPostExec]
					@session_id = NULL,
					@user_id = @user_id,
					@ent_id = @cons_ent_id,
					@bom_pos = @bom_pos,
					@qty_cons =@qty_left,
					@wo_id = @wo_id,
					@oper_id = @oper_id,
					@seq_no = @seq_no,
					@shift_start_local = NULL,
					@shift_id = NULL,
					@item_id = @item_id,
					@reas_cd =  @intGoodConsReas, -- updated v0.02.00
					@lot_no = @cons_lot_no,
					@fg_lot_no = NULL,
					@sublot_no = @cons_sublot_no,
					@fg_sublot_no = NULL,
					@from_ent_id = @ent_id,
					@ext_ref = NULL,
					@genealogy_id = NULL,
					@upstream_event_id = NULL,
					@segment_requirement_id = NULL,
					@segment_response_id = NULL,
					@comments = 'Trigger with Low Signal-Consumed with last consumed job ',
					@spare1 = NULL,
					@spare2 = NULL,
					@spare3 = NULL,
					@spare4 = NULL,
					@created_at_utc = NULL,
					@row_id = @row_id OUTPUT,
					@time_zone_bias_value = NULL

					
				SET @iterate  = @iterate  + 1
			END

		END

		delete from @TempInv

		/* -- 0.03.00 Disabled
		insert into @TempInv(ent_id,item_id , lot_no , sub_lot_no,qty)
		select iv.ent_id, iv.item_id,iv.lot_no, iv.sublot_no,qty_left--dbo.[fn_ofi_ConvertQtyByItemIdAndUom](iv.item_id,iv.qty_left,uom_id,@defaultUoMId,NULL,NULL,NULL,NULL)		
		from item_inv(nolock) iv
		where ent_id=@ent_id 

		if exists (select 1 from @TempInv)
		BEGIN
			select 1
			EXEC	@return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
					@from_ent_id = @ent_id,
					@item_id = null,
					@lot_no = NULL,
					@sublot_no = NULL,
					@qty_cons = NULL,
					@reas_cd = 2, -- need to change the code upon creation of new scrap reason code
					@grade_cd = NULL,
					@status_cd = NULL,
					@user_id = @user_id,
					@wo_id = NULL,
					@oper_id = NULL,
					@seq_no = NULL,
					@shift_start_local = NULL,
					@fg_lot_no = NULL,
					@fg_sublot_no = NULL,
					@item_scrapped = 1,
					@ent_id = NULL,
					@shift_id = NULL,
					@qty_cons_erp = NULL,
					@ext_ref = NULL,
					@transaction_type = NULL,
					@genealogy_id = NULL,
					@upstream_event_id = NULL,
					@segment_requirement_id = NULL,
					@segment_response_id = NULL,
					@comments = 'Trigger with Low Signal, Scrap because of not part of BOM',
					@spare1 = NULL,
					@spare2 = NULL,
					@spare3 = NULL,
					@spare4 = NULL,
					@shift_start_utc = NULL,
					@time_zone_bias_value = NULL,
					@row_id = @row_id OUTPUT
		END
		*/
			--UPDATE item_inv Set qty_left = 0 where item_id =@item_id and ent_id=@ent_id
				
		set @Out=0
	 end
	 ELSE if (@qty_left = 0.00) --v0.02.00 Add checking if qty is 0
	 BEGIN 
		set @Out = 3
		print @Out
	 END
	 ELSE
	 BEGIN
		set @Out =1
		print @Out
	 END
	 select @Out as [Out], @ent_id as EntId, @wo_id as WoId
END

