CREATE PROCEDURE [dbo].[sp_U_Std_Oper_Step]
  (@oper_id nvarchar(40) ,
   @step_no int ,
   @step_seq int ,
   @step_name nvarchar(40) ,
   @step_desc nvarchar(1700) ,
   @action_type int ,
   @std_time float ,
   @complete_cond int ,
   @allow_bypass bit ,
   @enter_data bit ,
   @step_grp_id int ,
   @spc_char nvarchar(40) ,
   @form_name nvarchar(254) ,
   @data_log_grp_id int ,
   @reqd_rep_pct float ,
   @control_type int ,
   @high_limit float ,
   @low_limit float ,
   @limit_warning bit ,
   @spare1 nvarchar(80) ,
   @spare2 nvarchar(80) ,
   @spare3 nvarchar(80) ,
