   @spare5 nvarchar(80) ,
   @spare6 nvarchar(80) ,
   @last_edit_comment nvarchar(254) ,
   @last_edit_at datetime )
AS
--- ***********************************************************************************************************************
-- Module Name      - sp_U_Std_Oper_Step
-- Description      - Update an existing row in the table
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
-- Notes            - SP requires that all table fields be included
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified      Modified_By      Changes
--09/19/2005	Raghu		3.1.0	Part of DB Changes
--01/24/2007	Raghu		3.2.0	Part of DB Changes
--10/31/2007	AML			3.4.0	DB changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
UPDATE std_oper_step
SET step_seq = @step_seq,
	step_name = @step_name,
    step_desc = @step_desc,
    action_type = @action_type,
    std_time = @std_time,
    complete_cond = @complete_cond,
    allow_bypass = @allow_bypass,
    enter_data = @enter_data,
    step_grp_id = @step_grp_id,
    spc_char = @spc_char,
    form_name = @form_name,
    data_log_grp_id = @data_log_grp_id,
    reqd_rep_pct = @reqd_rep_pct,
	control_type = @control_type,
	high_limit = @high_limit,
	low_limit = @low_limit,
	limit_warning = @limit_warning,
    spare1 = @spare1,
    spare2 = @spare2,
    spare3 = @spare3,
    spare4 = @spare4,
    spare5 = @spare5,
    spare6 = @spare6,
    last_edit_comment = @last_edit_comment
WHERE 	(oper_id = @oper_id AND
        step_no = @step_no AND
    last_edit_at = @last_edit_at)

