-- 0.01.02	YG				2024-02-22			Added logic if ent_id is not provided
----------------------------------------------------------------------------------------------

CREATE PROCEDURE [dbo].[sp_I_ofi_AddJobMessageLogs]
     @wo_id nvarchar(40)  = NULL,
     @oper_id        nvarchar(40)  = NULL,
	 @seq_no          int          = NULL,
     @type           nvarchar(100) = NULL,
     @description    nvarchar(250) = NULL,
     @logged_at      datetime       = NULL,
	 @status		 INT = 0,
	 @ent_id		INT = NULL --V 0.01.01
AS
BEGIN
     SET NOCOUNT ON;

	 DECLARE @target_sched_ent INT,
			@run_ent_id INT

	 SET @status = ISNULL(@status,0);

	 -- if ent_id is not provided
	 if (@ent_id is null or @ent_id = '')
	 BEGIN
		
		SELECT @target_sched_ent = target_sched_ent_id , @run_ent_id = run_ent_id
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id and Oper_id = @oper_id AND seq_no = @seq_no

		SET @ent_id = ISNULL(@run_ent_id,@target_sched_ent)
	 END

    INSERT INTO [dbo].[ofi_Job_Message_log] VALUES (@wo_id,@oper_id,@seq_no,@type,@description,GETUTCDATE(),@status,@ent_id)
END

