--===========================================================================================
-- Name:		sp_I_ofi_AddMaterialMaster
-- Description:	The stored procedure will create new material master that called from the WF
--	
-- Usage:		AddMaterialMaster
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-15			Initial version.
-- 0.02.00	YG				2022-10-24			Add flag for audit trail in the parameter
-- 0.03.00  YG				2022-12-16			Bug Fixed #489 : Item attribute is not getting set through template
-- ===========================================================================================
CREATE Procedure [dbo].[sp_I_ofi_AddMaterialMaster]
 (	@item_id NVARCHAR(40) = NULL,
	@item_desc NVARCHAR(80) = NULL,
	@item_class_id NVARCHAR(40)= NULL,
	@uom_id INT= NULL,
	@num_decimals INT= NULL,
	@template_name NVARCHAR(40)= NULL,
	@user_name NVARCHAR(40)= NULL,
	@audit_trail BIT = 1, -- 1=Save to audit trail 0=Not Save to Audit Trail
	@row_id INT OUT	)
AS
BEGIN
	DECLARE @return_value INT,
			@last_edit_at DATETIME,
			@mod_id NVARCHAR(30),
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MM_Item',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'add',
			@strCommentMsg NVARCHAR(200) = 'Created From [dbo].[sp_I_ofi_AddMaterialMaster]',
			@csrItemGroup NVARCHAR(40),
			@csrAttrId INT,
			@csrDefValue NVARCHAR(100)

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Insert material in the item table
	EXEC @return_value = [dbo].[sp_I_Item]
		@item_id = @item_id,
		@item_desc = @item_desc,
		@item_class_id = @item_class_id,
		@uom_id = @uom_id,
		@num_decimals = @num_decimals,
		@template = 0,
		@lifetime = 730, -- Set maximum To Be Update
		@unit_cost = NULL,
		@obsolete = 0,
		@purchased = 0,
		@sold = 0,
		@must_complete_steps = 0,
		@must_prod_reqd_qty = 0,
		@min_grade = NULL,
		@min_state = NULL,
		@min_inv_level = NULL,
		@reorder_amt = NULL,
		@auto_reorder = 0,
		@lot_no_format = NULL,
		@last_lot_no = NULL,
		@max_lot_size = NULL,
		@sublot_no_format = NULL,
		@last_sublot_no = NULL,
		@serial_no_lvl = -1,
		@max_sublot_size = NULL,
		@max_order_size = NULL,
		@min_trace_inv = NULL,
		@inv_unique_by_job = NULL,
		@notes = NULL,
		@spare1 = NULL,
		@spare2 = NULL,
		@spare3 = NULL,
		@spare4 = NULL,
		@last_edit_comment = 'ADDED BY MES UI',
		@last_edit_at = @last_edit_at OUTPUT

	SET @row_id = @@IDENTITY

	DECLARE @masterAttrTable TABLE (
		attr_id INT,
		def_value NVARCHAR(100),
		item_group NVARCHAR(100)
	)

	INSERT @masterAttrTable
	SELECT attr_id, 
		def_value, 
		item_group 
	FROM ofi_master_attr WITH (NOLOCK)
	WHERE 
		item_group = @template_name

	-- Set cursor to insert attribute  
	DECLARE cursor_attr CURSOR
	FOR SELECT 
			attr_id,def_value, item_group 
		FROM 
			@masterAttrTable
		WHERE 
			item_group = @template_name

	OPEN cursor_attr;

	FETCH NEXT FROM cursor_attr INTO 
		@csrAttrId, @csrDefValue, @csrItemGroup

	WHILE @@FETCH_STATUS = 0
	BEGIN
		-- Insert Item Attribute in the item_attr table
		EXEC sp_I_Item_Attr 
			@item_id = @item_id, 
			@attr_id = @csrAttrId, 
			@attr_value = @csrDefValue, 
			@notes = NULL, 
			@last_edit_comment = 'ADDED BY MES UI', 
			@mod_id = @mod_id OUTPUT
		
		FETCH NEXT FROM cursor_attr INTO 
					@csrAttrId, @csrDefValue, @csrItemGroup
	END

	CLOSE cursor_attr;

	DEALLOCATE cursor_attr;

	IF (@audit_trail = 1)
	BEGIN
		-- Insert entry in Audit Trial starts
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES 
		(
			@row_id, 
			'@ItemId', 
			@item_id
		),
		(
			@row_id, 
			'@ItemDesc', 
			@item_desc
		),
		(
			@row_id, 
			'@ItemClassId', 
			@item_class_id
		),
		(
			@row_id,
			'@UoM',
			CAST(@uom_id AS NVARCHAR(40))
		),
		(
			@row_id,
			'@NumDecimals',
			CAST(@num_decimals AS NVARCHAR(40))
		),
		(
			@row_id,
			'@TemplateName',
			CAST(@template_name AS NVARCHAR(40))
		)
	
		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg
	END
END

