--===========================================================================================
-- Name:		[sp_I_ofi_AddMaterialTemplate]
-- Description:	The stored procedure will insert record to the material template table
-- Usage:		AddMaterialTemplate
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-12			Initial version.
-- 0.02.00	YG				2022-10-24			Add flag for audit trail in the parameter
-- ===========================================================================================
CREATE Procedure [dbo].[sp_I_ofi_AddMaterialTemplate]
	@template_name NVARCHAR(40) = NULL,
	@attr_id INT = NULL,
	@default_value NVARCHAR(50) = NULL,
	@user_name NVARCHAR(40) = NULL,
	@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail
AS
BEGIN
	DECLARE	@iRowId INT,
			@strAttrDesc NVARCHAR(80),
			@iDataType INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MM_Template',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'add',
			@strCommentMsg NVARCHAR(200) = 'Created From [dbo].[sp_I_ofi_AddMaterialTemplate]'

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Get Attribute Description 
	SELECT @strAttrDesc = attr_desc,
		@iDataType = data_type
	FROM attr WITH (NOLOCK)
	WHERE attr_id = @attr_id
		AND attr_grp = 1 -- Item attr group

	INSERT ofi_master_attr 
	(
		item_group,
		attr_id,
		def_value,
		created_at_local,
		created_at_utc,
		last_edit_by
	)
	values
	(
		@template_name,
		@attr_id,
		@default_value,
		GETDATE(),
		GETUTCDATE(),
		@user_name
	)

	SET @iRowId = @@IDENTITY

	IF (@audit_trail = 1)
	BEGIN
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES 
		(
			@iRowId, 
			'@ItemGroup', 
			@template_name
		),
		(
			@iRowId, 
			'@AttrId', 
			CAST(@attr_id AS NVARCHAR(40))
		),
		(
			@iRowId, 
			'@DefValue', 
			@default_value
		)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg,
			@keyField1 = @strAttrDesc,
			@keyField2 = @iDataType
	END
END

