CREATE FUNCTION dbo.fn_S_ofi_GetParentWithAttrValue(
    @input_ent_id INT,
    @input_attr_value VARCHAR(255)
)
RETURNS INT
AS
BEGIN
    DECLARE @parent_id INT;
    DECLARE @found_parent_id INT = NULL;

    -- Recursive Common Table Expression (CTE) to traverse the hierarchy
    WITH ParentHierarchy AS (
        SELECT ent_id, parent_ent_id
        FROM ent WITH (NOLOCK) 
        WHERE ent_id = @input_ent_id
        UNION ALL
        SELECT e.ent_id, e.parent_ent_id
        FROM ent e WITH (NOLOCK) 
        INNER JOIN ParentHierarchy ph ON e.ent_id = ph.parent_ent_id
    )
    SELECT TOP 1 @found_parent_id = ph.parent_ent_id
    FROM ParentHierarchy ph
    INNER JOIN ent_attr a WITH (NOLOCK) ON ph.parent_ent_id = a.ent_id
    WHERE a.attr_value = @input_attr_value;

    RETURN @found_parent_id;
END;

--===========================================================================================
-- Name:        [sp_D_ofi_lm_print_tables_maintenance]
-- Description: Cleaning SP to delete old records 
-- ===========================================================================================
-- Version  Author		Date (yyyy-MM-dd)   Change description
-- 0.01.00  AML, XPM	2026-06-23          Initial version.
-- ===========================================================================================
CREATE   PROCEDURE [dbo].[sp_D_ofi_lm_print_tables_maintenance]
AS 
BEGIN
    SET NOCOUNT ON;
    SET DEADLOCK_PRIORITY LOW;

    DECLARE @cutoff DATETIME = DATEADD(MONTH, -2, GETDATE());
    DECLARE @batchSize INT = 5000;

    WHILE 1 = 1
    BEGIN
        DELETE TOP (@batchSize) d
        FROM [dbo].[ofi_lm_print_label_details] d
        INNER JOIN [dbo].[ofi_lm_print_label_header] h
            ON d.[label_id] = h.[label_id]
        WHERE h.created_at < @cutoff;

        IF @@ROWCOUNT = 0 
            BREAK;

        WAITFOR DELAY '00:00:00.200';
    END;

    WHILE 1 = 1
    BEGIN
        DELETE TOP (@batchSize)
        FROM [dbo].[ofi_lm_print_label_header]
        WHERE created_at < @cutoff;

        IF @@ROWCOUNT = 0 
            BREAK;

        WAITFOR DELAY '00:00:00.200';
    END;

END

