	@last_edit_comment nvarchar(254),
	@time_zone_bias_value INT32 = NULL ,
	@mod_id varchar(30) OUT
)

AS
-- ***********************************************************************************************************************
-- Module Name			-
-- Description			-
-- Author				-
-- Date Created			- 10/21/2002
-- Version				- 6.2.0
--
-- Copyright (c) 2020 AVEVA Group plc - All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Change By	Ver.	Changes
-- 12/04/2002	Raghu		1.5.0	Mod Id Changes (Datetime to Money type)
-- 04/01/2003	Raghu		1.6.0	Included 'state_cd' input param - part of DB 1.6 change
-- 06/06/2003	SJ			1601	Oracle migration changes - SET @<variable> = (SELECT ...)
-- 10/14/2005	Raghu		3.1.0	HD# 5678, Part of DB Changes
-- 01/11/2005	Raghu		3.1.7	HD# 7209, Adjust reqd_finish_time accordingly
-- 07/11/2006	Raghu		3.1.19	HD# 8434, Strip the milli-seconds by converting the datetime value to a character
--									type and then convert it back to a datetime datatype
-- 01/24/2007	KRF			3.2.1	HD# 8424, 9248, & 9224, part of DB changes - added @bom_ver_id, @spec_ver_id,
--									@may_override_route, and @spare1-4 arguments
-- 07/25/2007	AML			3.3.0	DB Changes; Replaced parameters @release_time and @req_finish_time with @release_time_local
--									and @req_finish_time_local.  Added @release_time_local, @release_time_utc, @req_finish_time_local,
--									and @req_finish_time_utc to insert statement.
-- 10/24/2007	AML			3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--									dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 10/31/2007	AML			3.4.0	DB Changes
-- 07/17/2009   SLR         4.0.0   DB Changes
-- 08/22/2009	Raghu		4.0.0	DB Changes
-- 11/16/2009	Ajay		4.0.0	HD#1432, Part of Date/TimeZone changes
-- 07/17/2014	Arun		5.0	    UserStory#367594,CR L00132269:Merged the HF L00132187, Handle tz offset correctly for release time and required time utc
-- 02/04/2020   Jim O'Hearn 6.2.0   Removed ntext type in favor of NOTES; see US 1232760
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE	@last_edit_by			NVARCHAR(40)
	,	@last_edit_at			DATETIME
	,	@release_time_utc		DATETIME
	,	@req_finish_time_utc	DATETIME
	,	@dbg_resp				INT
	,	@tz_temp 		        INT32



SET @release_time_tz = dbo.fn_TZ_ValidateOffset(@release_time_tz)
SET @release_time_local = dbo.fn_TZ_ValidateLocalDate(@release_time_local, @release_time_tz)
SET @req_finish_time_tz = dbo.fn_TZ_ValidateOffset(@req_finish_time_tz)
SET @req_finish_time_local = dbo.fn_TZ_ValidateLocalDate(@req_finish_time_local, @req_finish_time_tz)
SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

-- TRACE
exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Wo_t', @src_key='sp_I_Wo_t', @date_val1 = @release_time_local, @numeric_val1 = @release_time_tz, @date_val2 = @req_finish_time_local, @numeric_val2 = @req_finish_time_tz

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL

SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )



SELECT	@not_deletable = ISNULL( @not_deletable, 0 )
	,	@disassembly = ISNULL( @disassembly, 0 )
	,	@may_override_route = ISNULL( @may_override_route, 0 )
	,	@override_serialization = ISNULL( @override_serialization, 0 )
	,	@state_cd = COALESCE(@state_cd, 0)

-- HF L00132187
SET @tz_temp = -@release_time_tz
EXEC sp_S_GetUtcDate @release_time_local, @tz_temp, @release_time_utc OUTPUT
SET @tz_temp = -@req_finish_time_tz
EXEC sp_S_GetUtcDate @req_finish_time_local, @tz_temp, @req_finish_time_utc OUTPUT

INSERT INTO wo
(
	wo_id,
	wo_desc,
	process_id,
	bom_ver_id, -- Added 1/24/07 KRF
