	--release_time, -- 07/25/2007 AML
	release_time_utc,
	release_time_local,
	--req_finish_time, -- 07/25/2007 AML
	req_finish_time_utc,
	req_finish_time_local,
	state_cd,
	wo_priority,
	cust_info,
	mo_id,
	production_schedule_id,
	notes,
	not_deletable,
	disassembly,
	may_override_route, -- Added 1/24/07 KRF
	override_serialization,
    input_wo_id, -- Added 7/17/09 SLR
    input_oper_id, -- Added 7/17/09 SLR
    input_seq_no, -- Added 7/17/09 SLR
	spare1, -- Added 1/24/07 KRF
	spare2, -- Added 1/24/07 KRF
	spare3, -- Added 1/24/07 KRF
	spare4, -- Added 1/24/07 KRF
	last_edit_comment,
	last_edit_by,
	last_edit_at
)
VALUES
(
	@wo_id,
	@wo_desc,
	@process_id,
	@bom_ver_id, -- Added 1/24/07 KRF
	@spec_ver_id, -- Added 1/24/07 KRF
	@item_id,
	@req_qty,
	--@release_time, -- 07/25/2007 AML
	@release_time_utc,
	@release_time_local,
	--@req_finish_time, -- 07/25/2007 AML
	@req_finish_time_utc,
	@req_finish_time_local,
	@state_cd,
	@wo_priority,
	@cust_info,
	@mo_id,
	@production_schedule_id,
	@notes,
	@not_deletable,
	@disassembly,
	@may_override_route, -- Added 1/24/07 KRF
	@override_serialization,
        @input_wo_id,  -- Added 7/17/09 SLR
        @input_oper_id, -- Added 7/17/09 SLR
        @input_seq_no,  -- Added 7/17/09 SLR
	@spare1, -- Added 1/24/07 KRF
	@spare2, -- Added 1/24/07 KRF
	@spare3, -- Added 1/24/07 KRF
	@spare4, -- Added 1/24/07 KRF
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at
)

-- Return timestamp
--SET @mod_id = (select CONVERT(varchar(30), CONVERT(DATETIME, mod_id), 13)
SELECT @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
from wo
WHERE (wo_id = @wo_id)

