   @item_id NVARCHAR (40)  
  
  
   DECLARE @latest_sample_id INT  
 --fetch latest sample item and order details      
SELECT @item_id =item_id,  
    @wo_id =wo_id,  
    @oper_id =oper_id,  
    @seq_no =seq_no  
FROM sample(nolock)   
WHERE sample_id =@sample_id  

	-- Check if already sample exists for the WO and current step. If No then insert else update.
	if not exists(select 1 from ofi_cb_sample_results(nolock) where wo_id =@wo_id and oper_id=@oper_id and seq_no =@seq_no and item_id = @item_id  and is_manual=@is_manual and correction_step=@corr_step)  
	begin  
		   INSERT INTO ofi_cb_sample_results  
			(  
		  wo_id,  
		  oper_id,  
		  seq_no,  
			 item_id,  
			 fat,  
			 moist_per,  
			 pH,  
			 l,  
		  c,  
		  h,  
		  spare1,  
			 last_edit_by,  
			 last_edit_date,  
		  is_manual,
		  l_base,
		  c_base,
		  h_base,
		  moist_water,
		  phCorrectionType1,
		  phCorrectionValue1,
		  phCorrectionType2,
		  phCorrectionValue2,
		  phCorrectionType3,
		  phCorrectionValue3,
		  phCorrectionType4,
		  phCorrectionValue4,
		  reqd_qty,
		  correction_step)  
		   VALUES  
			 (  
		   @wo_id,  
		   @oper_id,  
		   @seq_no,  
		   @item_id,  
		   @measured_fat,  
		   @measured_moisture_per,  
		   @measured_ph,  
		   @measured_l,  
		   @measured_c,  
		   @measured_h,  
		   @spare1,  
		   @userName,  
		   @last_edit_date,  
		   @is_manual ,
		   @l_base,
		   @c_base,
		   @h_base,
		   @moist_water,
		   @phCorrectionType1,
		   @phCorrectionValue1,
		   @phCorrectionType2,
		   @phCorrectionValue2,
		   @phCorrectionType3,
		   @phCorrectionValue3,
		   @phCorrectionType4,
		   @phCorrectionValue4,
		   @reqd_qty,
		   @corr_step
			 )  
	END  

	 else
	 begin
		 Update ofi_cb_sample_results
		 set
		  fat= @measured_fat,  
			 moist_per=@measured_moisture_per,  
			 pH=@measured_ph,  
			 l=@measured_l,  
		  c=@measured_c,  
		  h=@measured_h,
			 last_edit_by=@userName,  
			 last_edit_date=@last_edit_date,  
		  is_manual=@is_manual,
		  l_base=@l_base,
		  c_base=@c_base,
		  h_base=@h_base,
		  moist_water=@moist_water,
		  phCorrectionType1=@phCorrectionType1,
		  phCorrectionValue1=@phCorrectionValue1,
		  phCorrectionType2=@phCorrectionType2,
		  phCorrectionValue2=@phCorrectionValue2,
		  phCorrectionType3=@phCorrectionType3,
		  phCorrectionValue3=@phCorrectionValue3,
		  phCorrectionType4=@phCorrectionType4,
		  phCorrectionValue4=@phCorrectionValue4,
		  reqd_qty=@reqd_qty,
		  spare1=@spare1

		 where wo_id =@wo_id and oper_id=@oper_id and seq_no =@seq_no and item_id = @item_id  and is_manual=@is_manual   and correction_step=@corr_step

	 end


END

CREATE PROCEDURE [dbo].[sp_U_Ent]
  (@ent_id int ,
   @ent_name nvarchar(80) ,
