   @can_run_jobs_from_galaxy bit,
   @can_capture_util_from_galaxy bit,
   @can_track_oee_from_galaxy bit,
   @can_store_from_galaxy bit,
   @entity_from_galaxy bit,
   @cur_shift_id int ,
   --@cur_shift_start_time datetime , -- 07/25/2007 AML
   @cur_shift_start_time_local datetime,
   @cur_shift_start_time_tz INT32 = NULL,
   @last_domain_change datetime ,
   @last_domain_change_tz INT32 = NULL,
