   @equipment_type INT32,
   @spare1 nvarchar(1000) ,
   @spare2 nvarchar(1000) ,
   @spare3 nvarchar(1000) ,
   @spare4 nvarchar(1000),
   @last_edit_comment nvarchar(254) ,
   @last_edit_at DATETIME ,
   @time_zone_bias_value INT32 = NULL)
AS
-- ***********************************************************************************************************************
-- Module Name	      -
-- Description	      -
-- Author	      -
-- Date Created	      -	10/21/2002
-- Version	      - 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Ver.		Changes
-- 09/15/2005	Raghu			3.1.0		Part of DB Changes
-- 07/25/2007	AML				3.3.0		DB Changes; Changed @cur_shift_start_time to @cur_shift_start_time_local in
--												parameter list.  Removed @cur_shift_start_time from update statement, added
--												@cur_shift_start_time_local and @cur_shift_start_time_utc.
--11/16/2009	Ajay			4.0.0		HD#1432, Part of Date/TimeZone changes
--02/25/2013	RaghuG			4.6			Added def_std_oper_id and equipment_type to support line management.
--03/18/2016	Lorin			5.3			UserStory 605966 - As the SE Product Owner, I want to ensure that the can_do_dnc capability in the Ent table is alway set to false----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET NOCOUNT ON

DECLARE @cur_shift_start_time_utc   DATETIME
	,	@tz_temp_shift_start		INT32
	,	@dbg_resp					INT32

SET @cur_shift_start_time_tz	= dbo.fn_TZ_ValidateOffset(@cur_shift_start_time_tz)
SET @cur_shift_start_time_local	= dbo.fn_TZ_ValidateLocalDate(@cur_shift_start_time_local, @cur_shift_start_time_tz)
SET @last_domain_change_tz		= dbo.fn_TZ_ValidateOffset(@last_domain_change_tz)
SET @last_domain_change			= dbo.fn_TZ_ValidateLocalDate(@last_domain_change, @last_domain_change_tz)
SET @time_zone_bias_value		= dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)


-- TRACE
exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_U_Ent', @src_key='sp_U_Ent', @date_val1 = @cur_shift_start_time_local, @numeric_val1 = @cur_shift_start_time_tz, @date_val2 = @last_domain_change, @numeric_val2 = @last_domain_change_tz


SET @tz_temp_shift_start   = -@cur_shift_start_time_tz


EXEC sp_S_GetUtcDate @cur_shift_start_time_local, @tz_temp_shift_start, @cur_shift_start_time_utc OUTPUT

IF (@last_domain_change IS  NOT NULL) SET @last_domain_change =  DATEADD(mi, -@last_domain_change_tz, @last_domain_change)

SET @last_domain_change = dbo.fn_StripMilliSecsFromDateTime( @last_domain_change )

UPDATE ent
SET ent_name = @ent_name,
    description = @description,
    parent_ent_id = @parent_ent_id,
--    site = @site,
    hourly_cost = @hourly_cost,
    can_sched_jobs = @can_sched_jobs,
    can_run_jobs = @can_run_jobs,
    can_capture_util = @can_capture_util,
    can_capture_labor = @can_capture_labor,
    can_do_dnc = 0,
    can_track_oee = @can_track_oee,
    can_sched_shifts = @can_sched_shifts,
    can_store = @can_store,
    can_log_data = @can_log_data,
    can_ship = @can_ship,
    can_receive = @can_receive,
    can_copy_folders = @can_copy_folders,
	can_capture_qm_data = @can_capture_qm_data,
	can_sched_jobs_from_galaxy = @can_sched_jobs_from_galaxy,
	can_run_jobs_from_galaxy = @can_run_jobs_from_galaxy,
	can_capture_util_from_galaxy = @can_capture_util_from_galaxy,
	can_track_oee_from_galaxy = @can_track_oee_from_galaxy,
	can_store_from_galaxy = @can_store_from_galaxy,
	entity_from_galaxy = @entity_from_galaxy,
    cur_shift_id = @cur_shift_id,
    --cur_shift_start_time = @cur_shift_start_time, -- 07/25/2007 AML
	cur_shift_start_time_utc = @cur_shift_start_time_utc,
	cur_shift_start_time_local = @cur_shift_start_time_local,
    last_domain_change = @last_domain_change,
    tree_icon = @tree_icon,
    flow_diag_img = @flow_diag_img,
    identical_job_execs = @identical_job_execs,
    show_in_dsp_tree = @show_in_dsp_tree,
    ent_class = @ent_class,
    def_std_oper_id = @def_std_oper_id,
    equipment_type = @equipment_type,
    spare1= @spare1,
    spare2= @spare2,
    spare3= @spare3,
    spare4= @spare4,
    last_edit_comment = @last_edit_comment
WHERE 	(ent_id = @ent_id AND
        last_edit_at = @last_edit_at)

