CREATE PROCEDURE [dbo].[sp_I_Labor_Usage]
(
	@log_id int OUT,
	--@labor_start datetime ,
	@labor_start_local datetime, -- Added 08/01/2007 AML
    @labor_start_tz INT32 = NULL ,
	@user_id nvarchar(40) ,
	@ent_id int ,
	@wo_id nvarchar(40) ,
	@oper_id nvarchar(40) ,
	@seq_no int ,
	@step_no int ,
	@item_id nvarchar(40) ,
	@lot_no nvarchar(40) ,
	@sublot_no nvarchar(40) , -- Added 1/15/07 KRF
	@lab_cd nvarchar(40) ,
	@dept_id nvarchar(40) ,
	@shift_id int ,
	--@shift_start datetime ,
	@shift_start_local datetime, -- Added 08/01/2007 AML
    @shift_start_tz INT32 = NULL ,
	@pct_to_apply float ,
	@active bit ,
	@duration int ,
	@comments nvarchar(254) ,
	@raw_reas_cd nvarchar(40) , -- Added 1/15/07 KRF
	@last_edit_comment nvarchar(254) ,
	@time_zone_bias_value INT32 = NULL,
	@mod_id varchar(30) OUT
)

AS
--- ***********************************************************************************************************************
-- Module Name					- sp_I_Labor_Usage
-- Description					-
-- Author						-
-- Date Created					-
-- Version						- 1.6.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Ver		Changes
-- 09/10/2002		Raghu			1.4		Changed @@identity to scope_identity
-- 12/04/2002		Raghu			1.5.0	Mod Id Changes (Datetime to Money type)
-- 06-06-2003		Sheetal Jain    1.6.0	Oracle migration changes - SET @<variable> = (SELECT ...)
-- 06/15/2004		Raghu			2.1.0	Included last_edit_by and last_edit_at fields in the insert statement
-- 10/11/2005		Raghu			3.1.0	HD# 5678, Part of DB Changes
-- 01/15/2007		KRF				3.2.1	HD# 8314 & 8605 - Added @sublot_no and @raw_reas_cd arguments
-- 01/18/2007		KRF				3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 07/01/2007		AML				3.3.0	DB Changes
-- 10/24/2007		AML				3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--											dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 11/11/2009       Eswar           4.0		HF 1432 - datetime changes.
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @last_edit_by		NVARCHAR(40)
	,	@last_edit_at		DATETIME
	--	Added 08/01/2007 AML
	,	@labor_start_utc	DATETIME
	,	@shift_start_utc	DATETIME
	,	@tz_temp			INT
	,	@dbg_resp			INT
	--

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

-- IF @labor_start IS NULL SET  @labor_start = @last_edit_at
IF @active IS NULL SET @active = 0
IF @pct_to_apply IS NULL SET @pct_to_apply = 1

-- Added 08/01/2007 AML

SET @labor_start_tz = dbo.fn_TZ_ValidateOffset(@labor_start_tz)
SET @labor_start_local = dbo.fn_TZ_ValidateLocalDate(@labor_start_local, @labor_start_tz)

SET @shift_start_tz = dbo.fn_TZ_ValidateOffset(@shift_start_tz)
SET @shift_start_local = dbo.fn_TZ_ValidateLocalDate(@shift_start_local, @shift_start_tz)

SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

SET @tz_temp = -@labor_start_tz
EXEC sp_S_GetUtcDate @labor_start_local, @tz_temp, @labor_start_utc OUTPUT
SET @tz_temp = -@shift_start_tz
EXEC sp_S_GetUtcDate @shift_start_local, @tz_temp, @shift_start_utc OUTPUT

-- TRACE
EXEC @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Labor_Usage', @src_key='on_entry', @date_val1 = @labor_start_local, @numeric_val1 = @labor_start_tz,
	@date_val2 = @shift_start_local, @numeric_val2 = @shift_start_tz
if ( @dbg_resp = 1 ) RETURN

--

INSERT INTO labor_usage
