--===========================================================================================
-- Name:		sp_I_ofi_CloneMasterRecipe
-- Description:	The stored procedure will clone an item in master recipe that called from the WF
--	
-- Usage:		CloneMasterRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-07-18			Initial version.
-- 0.02.00	YG				2024-01-24			Update based on best practice audit
-- ===========================================================================================

CREATE Procedure [dbo].[sp_I_ofi_CloneMasterRecipe]
	@source_recipe_name NVARCHAR(80) = NULL,
	@recipe_name NVARCHAR(80) = NULL,
	@recipe_version FLOAT = NULL,
	@ent_id INT = NULL,
	@item_id NVARCHAR(40) = NULL,
	@recipe_active NVARCHAR(1) = 'N',
	@recipe_preferred NVARCHAR(1) = 'N',
	@note NVARCHAR(250) = NULL,
	@user_name NVARCHAR(100) = NULL

AS
BEGIN
	DECLARE @iErrorValue INT = 0,
			@iRecipeVersion INT,
			@strSourceItemId NVARCHAR(40),
			@strSourceRecipeVersion NVARCHAR(40),
			@strEntName NVARCHAR(80),
			@strMaterialName NVARCHAR(80),
			@nRecipeName NVARCHAR(80),
			@iRecipeRowId INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MRM_MasterRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'add',
			@strCommentMsg NVARCHAR(200) = 'Created From [dbo].[sp_I_ofi_CloneMasterRecipe]',
			@mod_id NVARCHAR(30)

	SET @iRecipeVersion =CAST(@recipe_version AS INT);

	-- Retrieve equipment name and material name
	SELECT @strEntName = ent_name 
	FROM ent WITH (NOLOCK) 
	WHERE ent_id = @ent_id

	SELECT @strMaterialName = item_desc 
	FROM item WITH (NOLOCK) 
	WHERE item_id = @item_id

	-- Interlock #1 validate recipe active and recipe preferred value are consistent
	IF (@recipe_preferred = 'Y' and @recipe_active = 'N')
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Recipe should be set in active if set as preferred recipe'
		RAISERROR ('@@MRWFErrorActiveandPreferredRecipeInconsistent@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN -1
	END

	-- Interlock #2 check if any same recipe version for the selected item and ent
	IF EXISTS(	SELECT TOP 1 1 
					FROM ofi_master_recipe WITH(NOLOCK)
				WHERE 
					item_id = @item_id 
					AND ent_id = @ent_id
					AND version = @recipe_version )
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Recipe version is already available in the system'
		RAISERROR ('@@MRWFErrorRecipeVersionAlreadyAvailable@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN -1
	END

	IF (@iErrorValue >= 0) 
	BEGIN
		-- update preferred for other recipe 
		IF (@recipe_preferred = 'Y')
		BEGIN
			-- Validate if any current preferred recipe available then set into not preferred
			IF (EXISTS(	SELECT 1
						FROM ofi_master_recipe WITH (NOLOCK) 
						WHERE item_id = @item_id 
								AND ent_id = @ent_id
								AND preferred = 'Y'))
			BEGIN
				-- Get the current preferred recipe 
				SELECT @nRecipeName = recipe_name
				FROM ofi_master_recipe WITH (NOLOCK) 
				WHERE item_id = @item_id 
						AND ent_id = @ent_id
						AND preferred = 'Y'

				EXEC [dbo].[sp_U_ofi_UpdateRecipe] 
					@item_id = @item_id,
					@ent_id = @ent_id,
					@recipe_name = @nRecipeName,
					@recipe_preferred = 'N',
					@recipe_active = null,
					@audit_comments = 'Updated From [dbo].[sp_I_ofi_CloneMasterRecipe]',
					@user_name = @user_name
			END
		END

		-- Insert New Master Recipe
		INSERT into [dbo].ofi_master_recipe (
			ent_id,
			item_id,
			recipe_name,
			version,
			preferred,
			is_active,
			notes,
			created_at_utc,
			created_at_local,
			created_by
		)values(
			@ent_id,
			@item_id,
			@recipe_name,
			@iRecipeVersion,
			@recipe_preferred,
			@recipe_active,
			@note,
			GETUTCDATE(),
			GETDATE(),
			@user_name
		)

		
		-- Get The RowId from ofi_master_recipe table
		SELECT @iRecipeRowId = @@IDENTITY
		
		-- Retrieve data from the source master recipe
		SELECT @strSourceItemId = item_id, 
			@strSourceRecipeVersion = version
		FROM ofi_master_recipe WITH (NOLOCK)
		WHERE recipe_name = @source_recipe_name

		-- Insert New Bom Item
		EXEC sp_I_Bom_Ver_Clone 
			@strSourceItemId,
			@strSourceRecipeVersion,
			@item_id,
			@recipe_version,
			null,
			null,
			@mod_id

		-- Insert New Param
		INSERT INTO [dbo].ofi_master_recipe_parameter (process_id, oper_id, step_no, recipe_name, item_id, spec_id, spec_value, min_value, max_value, product_dependent, comments, last_edit_at_utc, last_edit_at_local, last_edit_by )
		SELECT process_id, oper_id, step_no, @recipe_name, @item_id, spec_id, spec_value, min_value, max_value, product_dependent, null, GETUTCDATE(), GETDATE(), @user_name 
		FROM ofi_master_recipe_parameter WITH (NOLOCK) WHERE recipe_name = @source_recipe_name AND item_id = @strSourceItemId

		-- Insert entry in Audit Trial starts
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES 
		(
			@iRecipeRowId, 
			'@MaterialId', 
			@item_id
		),
		(
			@iRecipeRowId, 
			'@EquipmentId', 
			CAST(@ent_id AS NVARCHAR(40))
		),
		(
			@iRecipeRowId,
			'@Version',
			CAST(@iRecipeVersion AS NVARCHAR(40))
		),
		(
			@iRecipeRowId,
			'@RecipeName',
			@recipe_name
		),
		(
			@iRecipeRowId,
			'@Preferred',
			@recipe_preferred
		),
		(
			@iRecipeRowId,
			'@Active',
			@recipe_active
		),
		(
			@iRecipeRowId,
			'@Notes',
			@note
		)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
		    @user_id = @user_name,
		    @activity = @strActivityMsg,
		    @audit_category = 'Info',
		    @comments = @strCommentMsg,
		    @keyField1   = @strEntName,
			@keyField2   = @strMaterialName,
			@keyField3   = @source_recipe_name

	END
	
END

