CREATE PROCEDURE [dbo].[sp_I_Wo_File]
(
	@wo_id nvarchar(40) ,
	@file_path nvarchar(254) ,
	@file_desc nvarchar(40) ,
	@last_modified datetime ,
	@file_size int ,
	@author nvarchar(40),
	-- Added 07/31/2007 AML
	@spare1 nvarchar(80),
	@spare2 nvarchar(80),
	@spare3 nvarchar(80),
	@spare4 nvarchar(80),
	--
	@last_edit_comment nvarchar(254) ,
	@time_zone_bias_value INT32 = 0,
	@mod_id varchar(30) OUT
)

AS
-- ***********************************************************************************************************************
-- Module Name				-
-- Description				-
-- Author					-
-- Date Created				- 10/21/2002
-- Version					- 1.6.0.0
--
-- Copyright (c) 2018 AVEVA Group plc and its subsidiaries. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Ver		Changes
-- 12/04/2002		Raghu			1.5.0	Mod Id Changes (Datetime to Money type)
-- 06/06/2003		Sheetal Jain    1.6.0	Oracle migration changes - SET @<variable> = (SELECT ...)
-- 10/11/2005		Raghu			3.1.0	HD# 5678, Part of DB Changes
-- 07/31/2007		AML				3.3.0	DB Changes
-- 10/24/2007		AML				3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--											dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 10/01/2018	Raghu		6.1	UserStory:1084805 - As Terry, I want the upgrade to modify the document / file stored procedures so that my existing configuration is still valid (Part 1)
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @last_edit_by	NVARCHAR(40)
	,	@last_edit_at	DATETIME
	,@ftle		DATETIME
	,@file_type	NVARCHAR(254)

SET @file_type = dbo.fn_GetFileExtn(@file_path)
EXEC sp_I_File_Type @file_ext=@file_type, @file_desc=@file_desc, @edit_level=NULL, @view_level=NULL, @print_level=NULL
	, @edit_args=NULL, @view_args=NULL, @print_args=NULL, @ignore_if_exists=1
	, @last_edit_comment=NULL, @last_edit_at=@ftle OUTPUT

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)
IF @last_modified IS NOT NULL SET @last_modified = DATEADD(mi, -@time_zone_bias_value, @last_modified)

INSERT INTO wo_file
(
	wo_id,
	file_path,
	file_desc,
	file_type,
	last_modified,
	file_size,
	author,
--	Added 07/31/2007 AML
	spare1,
	spare2,
	spare3,
	spare4,
--
	last_edit_comment,
	last_edit_by,
	last_edit_at
)
VALUES
(
	@wo_id,
	@file_path,
	@file_desc,
	@file_type,
	@last_modified,
	@file_size,
	@author,
--	Added 07/31/2007 AML
	@spare1,
	@spare2,
	@spare3,
	@spare4,
--
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at
)

-- Return timestamp
--SET @mod_id = (select CONVERT(varchar(30), CONVERT(DATETIME, mod_id), 13)
SELECT @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
from wo_file WITH (NOLOCK)
WHERE (wo_id = @wo_id AND
file_path = @file_path)

CREATE PROCEDURE [dbo].[sp_U_Transfer_List]
(
	@row_id int ,
	@transfer_type int ,
	@cust_id nvarchar(40) ,
	@order_id nvarchar(40) ,
	@line_no int ,
	--@date_of_shipment datetime ,
	@date_of_shipment_local datetime, -- Added 07/31/2007 AML
	@date_of_shipment_tz INT32 = NULL ,
	@wo_id nvarchar(40) ,
	@oper_id nvarchar(40) ,
	@seq_no int ,
	@bom_pos int,
	@to_ent_id int ,
	@item_id nvarchar(40) ,
	@lot_no nvarchar(40) ,
	@sublot_no nvarchar(40),
	@grade_cd int ,
	@status_cd int ,
	@qty_to_store float ,
	@uom_id_store int ,
	@expiry_date datetime ,
	@expiry_date_tz INT32 = NULL ,
	@from_ent_id int ,
	@from_item_id nvarchar(40) ,
	@from_lot_no nvarchar(40) ,
	@from_sublot_no nvarchar(40),
	@from_grade_cd int ,
	@from_status_cd int ,
	@qty_to_pick float ,
	@uom_id_pick int ,
	@from_expiry_date datetime ,
	@from_expiry_date_tz INT32 = NULL ,
	@trans_id int ,
	@spare1 nvarchar(80) ,
	@spare2 nvarchar(80) ,
	@spare3 nvarchar(80) ,
	@spare4 nvarchar(80) ,
	@last_edit_comment nvarchar(254) ,
	@last_edit_at datetime,
	@time_zone_bias_value INT32 = NULL
)

AS
--- ***********************************************************************************************************************
-- Module Name      - sp_U_Transfer_List
-- Description      - Update an existing row in the table
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
-- Notes            - SP requires that all table fields be included
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified    Modified_By		Version     Changes
-- 09/22/2005		Raghu			3.1.0		Part of DB Changes
-- 01/30/2007		Raghu			3.2.0		Part of DB Changes
-- 07/31/2007		AML				3.3.0		DB Changes
-- 11/17/2009		Eswar			4.0			HF 1432 - Part of Date/Time changes.
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @dbg_resp INT32

SET @date_of_shipment_tz = dbo.fn_TZ_ValidateOffset(@date_of_shipment_tz)
SET @date_of_shipment_local = dbo.fn_TZ_ValidateLocalDate(@date_of_shipment_local, @date_of_shipment_tz)

SET @expiry_date_tz = dbo.fn_TZ_ValidateOffset(@expiry_date_tz)
SET @expiry_date = dbo.fn_TZ_ValidateLocalDate(@expiry_date, @expiry_date_tz)

SET @from_expiry_date_tz = dbo.fn_TZ_ValidateOffset(@from_expiry_date_tz)
SET @from_expiry_date = dbo.fn_TZ_ValidateLocalDate(@from_expiry_date, @from_expiry_date_tz)

SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

-- TRACE
EXEC @dbg_resp = sp_DBG_LogTrace @src_sp='sp_U_Transfer_List', @src_key='on_entry', @date_val1 = @date_of_shipment_local, @numeric_val1 = @date_of_shipment_tz,
				 @date_val2 = @expiry_date, @numeric_val2 = @expiry_date_tz,
				 @date_val3 = @from_expiry_date, @numeric_val3 = @from_expiry_date_tz

DECLARE @date_of_shipment_utc	DATETIME
	,	@tz_temp				INT

SET @tz_temp = -@date_of_shipment_tz
EXEC sp_S_GetUtcDate @date_of_shipment_local, @tz_temp, @date_of_shipment_utc OUTPUT

UPDATE transfer_list
SET	transfer_type = @transfer_type,
	cust_id = @cust_id,
	order_id = @order_id,
	line_no = @line_no,
	--date_of_shipment = DATEADD(mi, -@time_zone_bias_value, @date_of_shipment),
	date_of_shipment_utc = @date_of_shipment_utc,		-- Added 07/31/2007 AML
	date_of_shipment_local = @date_of_shipment_local,	-- Added 07/31/2007 AML
	wo_id = @wo_id,
	oper_id = @oper_id,
	seq_no = @seq_no,
	bom_pos = @bom_pos,
	to_ent_id = @to_ent_id,
	item_id = @item_id,
	lot_no = @lot_no,
	sublot_no = @sublot_no,
	grade_cd = @grade_cd,
	status_cd = @status_cd,
	qty_to_store = @qty_to_store,
	uom_id_store = @uom_id_store,
	expiry_date = DATEADD(mi, -@expiry_date_tz, @expiry_date),
	from_ent_id = @from_ent_id,
	from_item_id = @from_item_id,
	from_lot_no = @from_lot_no,
	from_sublot_no = @from_sublot_no,
	from_grade_cd = @from_grade_cd,
	from_status_cd = @from_status_cd,
	qty_to_pick = @qty_to_pick,
	uom_id_pick = @uom_id_pick,
	from_expiry_date = DATEADD(mi, -@from_expiry_date_tz, @from_expiry_date),
	trans_id = @trans_id,
	spare1 = @spare1,
	spare2 = @spare2,
	spare3 = @spare3,
	spare4 = @spare4,
	last_edit_comment = @last_edit_comment
WHERE 	(row_id = @row_id
	AND last_edit_at = @last_edit_at)

