-- 11/09/2009	    Kishore		    4.0			HF# 1432, Part of Date/Timezone Changes
-- 12/22/2011		Ravi Teja		4.0 SP2		CR L00110628 The apply_post_exec_fc_counts, suppress_start_qty_prompt,
--												allow_zero_qty_split and auto_alloc_qty_to_running_job fields are included from job_exec
--												table so that these fields should be copied to the new entity.
-- 01/24/2012		Asgar			4.5			Modified the code to update the shift end time (local and utc)
-- 05/03/2012		Ibrahim			4.5			Modifieid the code to validate entities having can_capture_qm_data capability
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN

	SET NOCOUNT ON
	SET XACT_ABORT ON

	DECLARE @cur_ent_id      			INT32,
  			@cur_description 			STRING80_NULL,
  			@cur_parent_ent_id 			INT32_NULL,
  			@cur_site 					INT32_NULL,
  			@cur_hourly_cost 			TFLOAT_NULL,
  			@cur_can_sched_jobs 		LOGICAL,
  			@cur_can_run_jobs 			LOGICAL,
  			@cur_can_capture_util 		LOGICAL,
  			@cur_can_capture_labor 		LOGICAL,
  			@cur_can_do_dnc 			LOGICAL,
  			@cur_can_track_oee 			LOGICAL,
  			@cur_can_sched_shifts 		LOGICAL,
  			@cur_can_store 				LOGICAL,
  			@cur_can_log_data 			LOGICAL,
  			@cur_can_ship				LOGICAL,
  			@cur_can_receive 			LOGICAL,
  			@cur_can_copy_folders 		LOGICAL,

  			@l_cur_shift_id 			INT32,

  			@l_cur_shift_start_time_utc		TDATETIME_NULL,
