			@cur_shift_end_time_local		TDATETIME_NULL,
			@cur_shift_end_time_utc			TDATETIME_NULL,

  			@cur_last_domain_change 	TDATETIME_NULL,
  			@cur_tree_icon 				STRING254_NULL,
  			@cur_flow_diag_img 			STRING254_NULL,
  			@cur_identical_job_execs 	INT32,
  			@cur_show_in_dsp_tree 		LOGICAL,
  			@last_edit_by 				STRING40,
			@spare1						STRING1700,
			@spare2						STRING1700,
			@spare3						STRING1700,
			@spare4						STRING1700,
			@V_Order					INT32,
			@V_Ent_Name					STRING80_NULL,
			@cur_shift_start_time_utc	TDATETIME,
			@tz_temp					INT32,
			@identical_job_execs		INT32,
			@disable_util_exec			INT32,
			@disable_dnc_exec			INT32,
			@disable_oper_exec			INT32,
			@disable_stor_exec			INT32,
			@disable_quality			INT32,
			@tot_util_used				INT32,
			@tot_dnc_used				INT32,
			@tot_oper_used				INT32,
			@tot_stor_used				INT32,
			@tot_quality_used			INT32,
			@util_reqd					INT32,
			@dnc_reqd					INT32,
			@oper_reqd					INT32,
			@stor_reqd					INT32,
			@quality_reqd				INT32,
			@flow_diag_img				STRING254_NULL,
			@dbg_resp					INT32,
			@cur_can_capture_qm_data	LOGICAL,
			@cur_ent_class				LOGICAL


	  SET @cur_shift_start_time_tz = dbo.fn_TZ_ValidateOffset(@cur_shift_start_time_tz)
	  SET @cur_shift_start_time_local = dbo.fn_TZ_ValidateLocalDate(@cur_shift_start_time_local, @cur_shift_start_time_tz)
      SET @last_domain_change_tz = dbo.fn_TZ_ValidateOffset(@last_domain_change_tz)
      SET @last_domain_change = dbo.fn_TZ_ValidateLocalDate(@last_domain_change, @last_domain_change_tz)

      SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

      -- TRACE
		exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Ent_Clone', @src_key='on_entry', @date_val1 = @cur_shift_start_time_local, @numeric_val1 = @cur_shift_start_time_tz,
					@date_val2 = @last_domain_change, @numeric_val2 = @last_domain_change_tz

	SELECT @max_util_allowed = COALESCE(@max_util_allowed, 0)
		,@max_dnc_allowed = COALESCE(@max_dnc_allowed, 0)
		,@max_oper_allowed = COALESCE(@max_oper_allowed, 0)
		,@max_storage_allowed = COALESCE(@max_storage_allowed, 0)
		,@max_quality_allowed = COALESCE(@max_quality_allowed, 0)
		,@disable_util_exec = 1
		,@disable_dnc_exec = 1
		,@disable_oper_exec	= 1
		,@disable_stor_exec = 1
		,@disable_quality = 1

	SET @tz_temp = -@cur_shift_start_time_tz
	EXEC sp_S_GetUtcDate @cur_shift_start_time_local, @tz_temp, @cur_shift_start_time_utc OUTPUT

	DECLARE @tt_ent_ids_2 TABLE( ent_id INT, child_level INT, description INT, ent_name INT )

	--check for the required field ent_name
	IF @ent_name IS NULL BEGIN
		RAISERROR ('The %1 should not be Null{3339},Entity Name', 16, 1)
		RETURN -1
	END

	EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL

	SET	@last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

	INSERT INTO @tt_ent_ids_2 VALUES(@existing_ent_id, @parent_ent_id, 0, 0)

	DECLARE cur_entlist CURSOR LOCAL FOR
		SELECT ent_id, description FROM @tt_ent_ids_2 WHERE ent_name = 0

	WHILE (1=1) BEGIN
		OPEN cur_entlist
		FETCH cur_entlist INTO @cur_ent_id, @V_Order
		IF @@FETCH_STATUS <> 0 BREAK

		WHILE (1=1) BEGIN
			--select all the child entities for this entity
			INSERT INTO @tt_ent_ids_2
			SELECT child_ent_id, @cur_ent_id, @V_Order + 1, 0
			FROM ent_link WITH (NOLOCK) WHERE parent_ent_id  = @cur_ent_id


			UPDATE @tt_ent_ids_2 SET ent_name = 1 WHERE ent_id = @cur_ent_id

			--get the next entity
			FETCH cur_entlist INTO @cur_ent_id, @V_Order
			IF @@FETCH_STATUS <> 0 BREAK
		END
		CLOSE cur_entlist
	END
	DEALLOCATE cur_entlist

	IF NOT EXISTS (SELECT TOP 1 1 FROM @tt_ent_ids_2) BEGIN
		RAISERROR('The specified %1 does not exist in the database{3566},source entity', 16, 1)
		RETURN -1
	END

	  --Get the no. of utilization and dnc_execs currently used.
	  SELECT @tot_util_used = SUM(CASE WHEN can_capture_util = 1 THEN 1 ELSE 0 END)
		,@tot_dnc_used = SUM(CASE WHEN can_do_dnc = 1 THEN 1 ELSE 0 END)
		,@tot_oper_used = SUM(CASE WHEN can_sched_jobs = 1 OR can_run_jobs = 1 THEN 1 ELSE 0 END)
		,@tot_stor_used = SUM(CASE WHEN can_store = 1 THEN 1 ELSE 0 END)
		,@tot_quality_used = SUM(CASE WHEN can_capture_qm_data = 1 THEN 1 ELSE 0 END)
	  FROM ent WITH (NOLOCK)
	  WHERE can_capture_util = 1 OR can_do_dnc = 1 OR can_sched_jobs = 1 OR can_run_jobs = 1 OR can_store = 1 OR can_capture_qm_data = 1

	  --Verify whether we have sufficient utilization and dnc seats reqd.
	  SELECT @util_reqd = SUM(CASE WHEN e.can_capture_util = 1 THEN 1 ELSE 0 END)
		,@dnc_reqd = SUM(CASE WHEN e.can_do_dnc = 1 THEN 1 ELSE 0 END)
		,@oper_reqd = SUM(CASE WHEN e.can_sched_jobs = 1 OR e.can_run_jobs = 1 THEN 1 ELSE 0 END)
		,@stor_reqd = SUM(CASE WHEN e.can_store = 1 THEN 1 ELSE 0 END)
		,@quality_reqd = SUM(CASE WHEN e.can_capture_qm_data = 1 THEN 1 ELSE 0 END)
	  FROM ent e WITH (NOLOCK)
	  INNER JOIN (SELECT DISTINCT ent_id FROM @tt_ent_ids_2) te ON e.ent_id = te.ent_id
	  WHERE e.can_capture_util = 1 OR e.can_do_dnc = 1 OR e.can_sched_jobs = 1 OR e.can_run_jobs = 1 OR e.can_store = 1 OR e.can_capture_qm_data = 1

	  IF ((@tot_util_used + @util_reqd) <= @max_util_allowed)
		SET @disable_util_exec = 0

	  IF ((@tot_dnc_used + @dnc_reqd) <= @max_dnc_allowed)
		SET @disable_dnc_exec = 0

	  IF ((@tot_oper_used + @oper_reqd) <= @max_oper_allowed)
		SET @disable_oper_exec = 0

	  IF ((@tot_stor_used + @stor_reqd) <= @max_storage_allowed)
		SET @disable_stor_exec = 0

	  IF ((@tot_quality_used + @quality_reqd) <= @max_quality_allowed)
		SET @disable_quality = 0

	DECLARE cur_all_ents CURSOR LOCAL FOR SELECT ent_id, child_level, description FROM @tt_ent_ids_2 ORDER BY description
	OPEN cur_all_ents
	WHILE (1 = 1) BEGIN
		FETCH cur_all_ents INTO @existing_ent_id, @parent_ent_id, @V_Order
		IF @@FETCH_STATUS <> 0 BREAK

		SET @V_Ent_Name = '-1'

		SELECT	@V_Ent_Name = ent_name, @cur_description = description, @cur_parent_ent_id = parent_ent_id, @cur_site = site,
				@cur_hourly_cost = hourly_cost, @cur_can_sched_jobs = can_sched_jobs, @cur_can_run_jobs = can_run_jobs,
				@cur_can_capture_util = can_capture_util, @cur_can_capture_labor = can_capture_labor, @cur_can_do_dnc = can_do_dnc,
				@cur_can_track_oee = can_track_oee, @cur_can_sched_shifts = can_sched_shifts, @cur_can_store = can_store,
				@cur_can_log_data = can_log_data, @cur_can_ship = can_ship, @cur_can_receive = can_receive,
				@cur_can_copy_folders = can_copy_folders, @cur_can_capture_qm_data =can_capture_qm_data,@l_cur_shift_id = cur_shift_id, @l_cur_shift_start_time_utc = cur_shift_start_time_utc,
				@l_cur_shift_start_time_local = cur_shift_start_time_local, @l_cur_shift_end_time_utc = cur_shift_end_time_utc,
				@l_cur_shift_end_time_local = cur_shift_end_time_local, @cur_last_domain_change = last_domain_change,
				@cur_tree_icon = tree_icon, @cur_flow_diag_img = flow_diag_img, @cur_identical_job_execs = identical_job_execs,
				@cur_show_in_dsp_tree = show_in_dsp_tree,@cur_ent_class = ent_class, @spare1 = spare1, @spare2 = spare2, @spare3 = spare3, @spare4 = spare4
		FROM ent WITH (NOLOCK)
		WHERE ent_id = @existing_ent_id

		IF @V_Ent_Name = '-1' BEGIN
			RAISERROR('The specified %1 does not exist in the database{3566},source entity', 16, 1)
			RETURN -1
		END

		SET @site = COALESCE(@site, @cur_site)
		IF (@V_Order = 0) BEGIN
			--if input parameters are NULL then assign the values from field values of existing_ent_id record
			SELECT @description = COALESCE(@description, @cur_description)
				,@site = COALESCE(@site, @cur_site)
				,@hourly_cost = COALESCE(@hourly_cost, @cur_hourly_cost)
				,@can_sched_jobs = COALESCE(@can_sched_jobs, @cur_can_sched_jobs)
				,@can_run_jobs = COALESCE(@can_run_jobs, @cur_can_run_jobs)
				,@can_capture_util = COALESCE(@can_capture_util, @cur_can_capture_util)
				,@can_capture_labor = COALESCE(@can_capture_labor, @cur_can_capture_labor)
				,@can_do_dnc = COALESCE(@can_do_dnc, @cur_can_do_dnc)
				,@can_track_oee = COALESCE(@can_track_oee, @cur_can_track_oee)
				,@can_sched_shifts = COALESCE(@can_sched_shifts, @cur_can_sched_shifts)
				,@can_store = COALESCE(@can_store, @cur_can_store)
				,@can_log_data = COALESCE(@can_log_data, @cur_can_log_data)
				,@can_ship = COALESCE(@can_ship, @cur_can_ship)
				,@can_receive = COALESCE(@can_receive, @cur_can_receive)
				,@can_copy_folders = COALESCE(@can_copy_folders, @cur_can_copy_folders)
				,@can_capture_qm_data =COALESCE(@can_capture_qm_data, @cur_can_capture_qm_data)
				,@show_in_dsp_tree = COALESCE(@show_in_dsp_tree, @cur_show_in_dsp_tree)
				,@cur_shift_id = COALESCE(@cur_shift_id, @l_cur_shift_id)
				,@cur_shift_start_time_local = COALESCE(@cur_shift_start_time_local, @l_cur_shift_start_time_local)
				,@cur_shift_start_time_utc = COALESCE(@cur_shift_start_time_utc, @l_cur_shift_start_time_utc)
				,@cur_shift_end_time_local = COALESCE(@cur_shift_end_time_local, @l_cur_shift_end_time_local)
				,@cur_shift_end_time_utc = COALESCE(@cur_shift_end_time_utc, @l_cur_shift_end_time_utc)
				,@ent_class = COALESCE(@ent_class, @cur_ent_class)

			IF (@last_domain_change IS NULL)
				SET @last_domain_change = COALESCE(@last_domain_change, @cur_last_domain_change)
			ELSE
				SET @last_domain_change = DATEADD(MI, -@last_domain_change_tz, @last_domain_change)


			SELECT @tree_icon = COALESCE(@tree_icon, @cur_tree_icon)
				,@flow_diag_img = COALESCE(@flow_diag_img, @cur_flow_diag_img)
				,@identical_job_execs = COALESCE(@identical_job_execs, @cur_identical_job_execs)
				,@show_in_dsp_tree = COALESCE(@show_in_dsp_tree, @cur_show_in_dsp_tree)

			IF ( @parent_ent_id IS NOT NULL) BEGIN
				SELECT @cur_shift_start_time_local = NULL, @cur_shift_start_time_utc = NULL,
				@cur_shift_end_time_local = NULL, @cur_shift_end_time_utc = NULL

				SELECT @site = e.site, @cur_shift_start_time_local = e.cur_shift_start_time_local
					,@cur_shift_start_time_utc = e.cur_shift_start_time_utc,
					@cur_shift_end_time_local = e.cur_shift_end_time_local, @cur_shift_end_time_utc = e.cur_shift_end_time_utc

				FROM ent e WITH (NOLOCK)
				WHERE e.ent_id = @parent_ent_id
			END

			--- get entity local UTC value from shift local value or current time. If site is NULL, it will create client local outputs
			/*EXEC Sp_TZ_GetDateInfo @site, @cur_shift_start_time_utc OUTPUT, @cur_shift_start_time_local OUTPUT,  @cur_shift_start_time_tz OUTPUT
			SET @cur_shift_start_time_local = dbo.fn_StripMilliSecsFromDateTime( @cur_shift_start_time_local )
			SET @cur_shift_start_time_utc = dbo.fn_StripMilliSecsFromDateTime( @cur_shift_start_time_utc )*/

			INSERT INTO ent
			(
				ent_name, description, parent_ent_id, site, hourly_cost, can_sched_jobs, can_run_jobs,
				can_capture_util, can_capture_labor, can_do_dnc, can_track_oee, can_sched_shifts, can_store,
				can_log_data, can_ship, can_receive, can_copy_folders,can_capture_qm_data,cur_shift_id, cur_shift_start_time_utc,
				cur_shift_start_time_local, cur_shift_end_time_utc,	cur_shift_end_time_local,last_domain_change, tree_icon, flow_diag_img, identical_job_execs,
				show_in_dsp_tree, ent_class,last_edit_comment, last_edit_by, last_edit_at
			)
			VALUES
			(
				@ent_name, @description, @parent_ent_id, @site, @hourly_cost, @can_sched_jobs, @can_run_jobs,
				@can_capture_util, @can_capture_labor, @can_do_dnc, @can_track_oee, @can_sched_shifts, @can_store,
				@can_log_data, @can_ship, @can_receive, @can_copy_folders, @can_capture_qm_data,@cur_shift_id, @cur_shift_start_time_utc,
				@cur_shift_start_time_local, @cur_shift_end_time_utc,
				@cur_shift_end_time_local,@last_domain_change, @tree_icon, @cur_flow_diag_img, @cur_identical_job_execs,
				@show_in_dsp_tree, @ent_class,@last_edit_comment, @last_edit_by, @last_edit_at
			)

			SET @cur_ent_id = SCOPE_IDENTITY()

			--Log this shift event in the shift history table.
			INSERT INTO shift_history (ent_id, shift_start_utc, shift_start_local, shift_id)
			VALUES (@cur_ent_id, @cur_shift_start_time_utc, @cur_shift_start_time_local, @cur_shift_id)

		END
		ELSE BEGIN
			--Only for the entity passed use all the parameters passed
			IF @V_Order = 1 	--get the parent from new ent_name
				SELECT @parent_ent_id = ent_id FROM ent WHERE ent_name = @ent_name
			ELSE
				--get the parent from old ent_name+'(Clone)'
				SELECT @parent_ent_id = ent_id FROM ent
				WHERE ent_name = (SELECT ent_name+'(Clone)' FROM ent WHERE ent_id = @parent_ent_id)

			SET @cur_ent_id = NULL

			IF EXISTS (SELECT TOP 1 1 FROM ent WHERE ent_name = @V_Ent_Name + '(Clone)') BEGIN
				SELECT @cur_ent_id = ent_id
				FROM ent
				WHERE ent_name = @V_Ent_Name + '(Clone)'

				IF (@cur_ent_id IS NOT NULL)
					INSERT INTO ent_link (parent_ent_id, child_ent_id, last_edit_comment, last_edit_by, last_edit_at)
					VALUES (@parent_ent_id, @cur_ent_id, @last_edit_comment, @last_edit_by, @last_edit_at)
				SET @cur_ent_id = NULL
			END
			ELSE BEGIN
				SELECT @hourly_cost = @cur_hourly_cost
					,@can_sched_jobs = @cur_can_sched_jobs
					,@can_run_jobs = @cur_can_run_jobs
					,@can_capture_util = @cur_can_capture_util
					,@can_capture_labor = @cur_can_capture_labor
					,@can_do_dnc = @cur_can_do_dnc
					,@can_track_oee = 0
					,@can_sched_shifts = @cur_can_sched_shifts
					,@can_store = @cur_can_store
					,@can_log_data = @cur_can_log_data
					,@can_ship = @cur_can_ship
					,@can_receive = @cur_can_receive
					,@can_copy_folders = @cur_can_copy_folders
					,@can_capture_qm_data =@cur_can_capture_qm_data
					,@last_domain_change = @cur_last_domain_change
					,@tree_icon = COALESCE(@tree_icon, @cur_tree_icon)
					,@flow_diag_img = @cur_flow_diag_img
					,@identical_job_execs = @cur_identical_job_execs
					,@show_in_dsp_tree = @cur_show_in_dsp_tree
					,@ent_class = @cur_ent_class

					IF (@disable_util_exec = 1) SET @can_capture_util = 0
					IF (@disable_dnc_exec = 1) SET @can_do_dnc = 0
					IF (@disable_oper_exec = 1) SELECT @can_run_jobs = 0, @can_sched_jobs = 0
					IF (@disable_stor_exec = 1) SET @can_store = 0
					IF (@disable_quality = 1) SET @can_capture_qm_data = 0

					SELECT @cur_shift_start_time_local = NULL, @cur_shift_start_time_utc = NULL

					SELECT @site = e.site, @cur_shift_start_time_local = e.cur_shift_start_time_local
						,@cur_shift_start_time_utc = e.cur_shift_start_time_utc
					FROM ent e WITH (NOLOCK)
					WHERE e.ent_id = @parent_ent_id


					--- get entity local UTC value from shift local value or current time. If site is NULL, it will create client local outputs
					/*EXEC Sp_TZ_GetDateInfo @site, @cur_shift_start_time_utc OUTPUT, @cur_shift_start_time_local OUTPUT,  @cur_shift_start_time_tz OUTPUT
					SET @cur_shift_start_time_local = dbo.fn_StripMilliSecsFromDateTime( @cur_shift_start_time_local )
					SET @cur_shift_start_time_utc = dbo.fn_StripMilliSecsFromDateTime( @cur_shift_start_time_utc )*/

					INSERT INTO ent
					(
						ent_name, description, parent_ent_id, site, hourly_cost, can_sched_jobs, can_run_jobs,
						can_capture_util, can_capture_labor, can_do_dnc, can_track_oee, can_sched_shifts, can_store,
						can_log_data, can_ship, can_receive, can_copy_folders, can_capture_qm_data,cur_shift_id, cur_shift_start_time_utc,
						cur_shift_start_time_local, last_domain_change, tree_icon, flow_diag_img, identical_job_execs,
						show_in_dsp_tree, ent_class,last_edit_comment, last_edit_by, last_edit_at
					)
					VALUES
					(
						@V_Ent_Name+'(Clone)', @cur_description, @parent_ent_id, @site, @hourly_cost, @can_sched_jobs, @can_run_jobs,
						@can_capture_util, @can_capture_labor, @can_do_dnc, @can_track_oee, @can_sched_shifts, @can_store,
						@can_log_data, @can_ship, @can_receive, @can_copy_folders,@can_capture_qm_data, @l_cur_shift_id, @l_cur_shift_start_time_utc,
						@l_cur_shift_start_time_local, @last_domain_change, @tree_icon, @flow_diag_img, @identical_job_execs,
						@show_in_dsp_tree, @ent_class,@last_edit_comment, @last_edit_by, @last_edit_at
					)

					SET @cur_ent_id = SCOPE_IDENTITY()

					--Log this shift event in the shift history table.
					INSERT INTO shift_history (ent_id, shift_start_utc, shift_start_local, shift_id)
					VALUES (@cur_ent_id, @cur_shift_start_time_utc, @cur_shift_start_time_local, @cur_shift_id)

			END
		END

		IF NOT ( @cur_ent_id IS NULL ) BEGIN
			--clone the row in to Ent_Attr Table
			INSERT INTO ent_attr (ent_id, attr_id, attr_value, notes, last_edit_comment, last_edit_by, last_edit_at)
			SELECT @cur_ent_id, attr_id, attr_value, notes, @last_edit_comment, @last_edit_by, @last_edit_at
			FROM ent_attr WITH (NOLOCK)
			WHERE ent_id = @existing_ent_id

			--clone the row in to Shift_sched
			IF @can_sched_shifts = 1 BEGIN
				INSERT INTO Shift_sched
				(
					ent_id, start_day, shift_id, start_time, end_time, break1_start,
					break1_end,break2_start,break2_end,break3_start,break3_end,
					last_edit_comment, last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, start_day, shift_id, start_time, end_time, break1_start,
						break1_end, break2_start, break2_end, break3_start, break3_end,
						@last_edit_comment, @last_edit_by, @last_edit_at
				FROM Shift_sched WITH (NOLOCK)
				WHERE ent_id  = @existing_ent_id
			END

			--clone the row into shift_exc
			IF @can_sched_shifts = 1 BEGIN
				INSERT INTO shift_exc ( ent_id, start_time, end_time, shift_id, additive, last_edit_comment, last_edit_by, last_edit_at )
				SELECT @cur_ent_id, start_time, end_time, shift_id, additive, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM shift_exc WITH (NOLOCK)
				WHERE ent_id  = @existing_ent_id
			END

			-- clone rows into grp_ent_link table for all defined groups (default access = 0)
			INSERT INTO grp_ent_link ( grp_id, ent_id, accss, last_edit_comment, last_edit_by, last_edit_at )
			SELECT grp_id, @cur_ent_id , 0, @last_edit_comment, @last_edit_by, @last_edit_at
			FROM grp_name WITH (NOLOCK)

			-- if parent_ent_id <> NULL then add row in ent_link table for this entity
			IF NOT (@parent_ent_id IS NULL) BEGIN
				INSERT INTO ent_link (parent_ent_id, child_ent_id, last_edit_comment, last_edit_by, last_edit_at)
				VALUES (@parent_ent_id, @cur_ent_id, @last_edit_comment, @last_edit_by, @last_edit_at)
			END

			--clone the row into Dir table
			INSERT INTO Dir ( ent_id, seq_no, directory, last_edit_comment, last_edit_by, last_edit_at )
			SELECT @cur_ent_id, seq_no, directory, @last_edit_comment, @last_edit_by, @last_edit_at
			FROM dir WITH (NOLOCK) WHERE ent_id  = @existing_ent_id

			--clone the row into job_exec
			-- 10/26/2002	TC	Include all job_pos rows when cloning rows in job_exec
			IF @can_run_jobs = 1 BEGIN
				INSERT INTO job_exec
				(
					ent_id, job_pos, next_job_only, item_based_desc, job_end_confirm_msg, def_to_ent_id, def_reject_ent_id,
					def_from_ent_id, def_prod_reas_cd, def_cons_reas_cd, def_lot_no, def_sublot_no, autoload_job_specs,
					auto_seq_start_option, auto_job_start_option, auto_job_end_option, incl_class_reas, must_complete_steps,
					must_prod_reqd_qty, local_movable_cons_ent, local_movable_prod_ent, run_without_operator, apply_post_exec_fc_counts,
					suppress_start_qty_prompt, allow_zero_qty_split,auto_alloc_qty_to_running_job, cur_wo_id, cur_oper_id, cur_seq_no,
					cur_step_no, cur_step_start, spare1, spare2, spare3, spare4, last_edit_comment, last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, job_pos, next_job_only, item_based_desc, job_end_confirm_msg, def_to_ent_id, def_reject_ent_id,
						def_from_ent_id, def_prod_reas_cd, def_cons_reas_cd, def_lot_no, def_sublot_no, autoload_job_specs,
						auto_seq_start_option, auto_job_start_option, auto_job_end_option, incl_class_reas, must_complete_steps,
						must_prod_reqd_qty, local_movable_cons_ent, local_movable_prod_ent, run_without_operator, apply_post_exec_fc_counts,
						suppress_start_qty_prompt, allow_zero_qty_split,auto_alloc_qty_to_running_job, NULL, NULL, NULL, NULL,
						cur_step_start, spare1, spare2, spare3, spare4, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM job_exec WITH (NOLOCK)

				WHERE ent_id = @existing_ent_id
			END

			--clone the row into job_sched_exec
			IF @can_sched_jobs = 1 BEGIN
				INSERT INTO job_sched_exec
				(
					ent_id, oper_type, queue_time, sort_order, filtr, spare1, spare2, spare3, spare4,
					last_edit_comment, last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, oper_type, queue_time, sort_order, filtr, NULL, NULL, NULL, NULL,
						@last_edit_comment, @last_edit_by, @last_edit_at
				FROM job_sched_exec WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id
			END

			--clone the row into oee_exec
			IF @can_track_oee = 1 BEGIN
				INSERT INTO oee_exec
				(
					ent_id, job_ent_id, util_ent_id, target_perf, current_perf, target_qual, current_qual,
					def_prod_rate, target_oee, current_oee, basis, last_edit_comment, last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, job_ent_id, util_ent_id, target_perf, NULL, target_qual, NULL, def_prod_rate,
						target_oee, NULL, 0, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM oee_exec WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id
			END

			--clone the row into item_reas_grp_ent_link
			INSERT INTO item_reas_grp_ent_link ( reas_grp_id, ent_id, last_edit_comment, last_edit_by, last_edit_at )
			SELECT reas_grp_id,@cur_ent_id, @last_edit_comment, @last_edit_by, @last_edit_at
			FROM item_reas_grp_ent_link WITH (NOLOCK)
			WHERE ent_id = @existing_ent_id

			--clone the row into storage_exec
			IF @can_store = 1 BEGIN
				INSERT INTO storage_exec
				(
					ent_id, type, status, max_capacity, uom_id, tare, tare_uom_id, auto_del_zero_inv,
					allow_neg_qty, scannable_id, allow_multiple_items, allow_multiple_lots, movable,
					storage_ent_id, allow_dirty_state, log_state_transitions, indistinguishable_lots, unlisted,
					spare_int1, spare_int2, spare_int3, spare_int4, spare1, spare2, spare3, spare4, last_edit_comment,
					last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, type, status ,max_capacity, uom_id, tare, tare_uom_id, auto_del_zero_inv,
						allow_neg_qty,	scannable_id, allow_multiple_items, allow_multiple_lots, movable, storage_ent_id,
						allow_dirty_state, log_state_transitions, indistinguishable_lots, unlisted, spare_INT1, spare_INT2,
						spare_INT3, spare_INT4, spare1, spare2, spare3, spare4, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM storage_exec WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id
			END

			--clone the row into util_exec
			IF @can_capture_util = 1 BEGIN
				INSERT INTO util_exec
				(
					ent_id, cur_state_cd, cur_reas_cd, cur_reas_start_utc, cur_reas_start_local, cur_raw_reas_cd, reas_reqd,
					cur_log_id, target_util, current_util, jobstart_reas_cd, jobend_reas_cd, unkn_stop_reas_cd, break_start_reas_cd,
					break_end_reas_cd, inherit_from_parent, spare1, spare2, spare3, spare4, last_edit_comment, last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, NULL, NULL, NULL, NULL, NULL, reas_reqd, NULL, target_util, NULL, jobstart_reas_cd, jobend_reas_cd,
						unkn_stop_reas_cd, break_start_reas_cd, break_end_reas_cd, inherit_from_parent, spare1, spare2, spare3,
						spare4, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM util_exec WITH (NOLOCK)
				WHERE ent_id  = @existing_ent_id

				--clone the rows INTo util_raw_reas
				INSERT INTO util_raw_reas ( ent_id, raw_reas_cd, def_reas_cd, prompt, last_edit_comment, last_edit_by, last_edit_at )
				SELECT @cur_ent_id, raw_reas_cd, def_reas_cd, prompt, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM util_raw_reas WITH (NOLOCK)
				WHERE ent_id  = @existing_ent_id

				--clone the rows into util_reas_link
				INSERT INTO util_reas_link ( ent_id, raw_reas_cd, reas_cd, last_edit_comment, last_edit_by, last_edit_at )
				SELECT @cur_ent_id, raw_reas_cd, reas_cd, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM util_reas_link WITH ( NOLOCK)
				WHERE ent_id  = @existing_ent_id
			END

			--clone the row into labor_exec
			IF @can_capture_labor = 1 BEGIN
				INSERT INTO labor_exec
				(
					ent_id, def_lab_cd, def_dept_id, multiple_operators, def_raw_reas_cd, lab_cd_reqd, spare1,
					spare2, spare3, spare4,	last_edit_comment, last_edit_by, last_edit_at
				)
				SELECT	@cur_ent_id, def_lab_cd, def_dept_id, multiple_operators, def_raw_reas_cd, lab_cd_reqd,
						NULL, NULL, NULL, NULL, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM labor_exec WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id

				--clone the rows into labor_raw_reas
				INSERT INTO labor_raw_reas ( ent_id, raw_reas_cd, prompt, def_lab_cd, last_edit_comment, last_edit_by, last_edit_at )
				SELECT @cur_ent_id, raw_reas_cd, prompt, def_lab_cd, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM labor_raw_reas WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id

				--clone the rows into labor_reas_link
				INSERT INTO labor_reas_link ( ent_id, raw_reas_cd, lab_cd, last_edit_comment, last_edit_by, last_edit_at )
				SELECT @cur_ent_id, raw_reas_cd, lab_cd, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM labor_reas_link WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id

				--clone the rows into labor_dept_ent_link
				INSERT INTO labor_dept_ent_link ( ent_id, dept_id, last_edit_comment, last_edit_by, last_edit_at )
				SELECT @cur_ent_id, dept_id, @last_edit_comment, @last_edit_by, @last_edit_at
				FROM labor_dept_ent_link WITH (NOLOCK)
				WHERE ent_id = @existing_ent_id
			END

			-- set the added ent_id to return parameter
			IF @ent_id IS NULL BEGIN
				SET @ent_id =  @cur_ent_id
			END
		END  --End of NOT(@cur_ent_id IS NULL)
	END  --End of cur_all_ents
END

--===========================================================================================
-- Name:    [sp_U_ofi_SULowSignal]
-- Description:Storage Unit Low Level Signal Update
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)	Change description
-- 0.01.00  AJEET       2022-09-14			Intial Version
-- 0.01.01  YG          2024-02-09			Update Script Body Comment and Missing No Lock
-- 0.02.00  YG          2024-03-12			Added Good Consumption (Item Reason), Validation for non running job, Ensure qty_left has value for empty inventory  
-- 0.03.00  YG          2024-03-21			Update logic how to get latest consumption and disable scrap logic
-- 0.04.00  YG          2024-05-10			Major Update
-- 0.05.00  MC          2025-07-25			Adding fg_lot/sublot to item consumted because of low level in silo
-- 0.06.00  MC          2025-10-20			Adding removing zero-invenotry as only after low level signal invenotry can by removed from the silo
-- 0.07.00  MH          2025-11-20			[CR 00223357] Implement force scrapping for butter silos if ForceScrapOnLowLevel is set
-- 0.08.00	MC			2025-11-05			Try link only by lot_no if there is no connection by sublot_no
--
-- Exec sp_U_ofi_SULowSignal '500BN003'
-- =============================================
CREATE   PROCEDURE [dbo].[sp_U_ofi_SULowSignal] @SU_Name NVARCHAR(40)
AS
BEGIN
    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET nocount ON;

    -- Declare variable
    DECLARE
        @storage_ent_id INT,
        @cons_lot_no NVARCHAR(40) = NULL,
        @cons_sublot_no NVARCHAR(40) = NULL,
        @cons_qty FLOAT = 0,
        @avl_qty FLOAT = 0,
        @consumed_qty FLOAT = 0,
        @job_pos INT = 0,
        @bom_pos INT = 0,
        @date_time_UTC DATETIME = GETUTCDATE(),
        @return_value INT,
        @row_id INT32,
        @minID INT,
        @typeOfCons NVARCHAR(20) = 'FIFO',
        @process_id NVARCHAR(30),
        @process_type NVARCHAR(30),
        @prod_info NVARCHAR(4000),
        @prod_item_id NVARCHAR(40),
        @prod_date_time_UTC DATETIME,
        @user_id NVARCHAR(40) = NULL,
        @wo_state INT,
        @ent_id INT,
        @qty_left FLOAT,
        @su_level_threshold INT,
        @plant_level_threshold INT,
        @final_threshold INT,
        @wo_id NVARCHAR(40),
        @Out INT,
        @inv_item_id NVARCHAR(40),
        @item_id NVARCHAR(40),
        @target_sched_ent_id INT,
        @cons_ent_id INT,
        @oper_id NVARCHAR(40),
        @seq_no INT,
        @Counter INT,
        @iterate INT = 1,
        @last_consumed_date DATETIME,
        @lot_no NVARCHAR(40) = NULL,
        @sublot_no NVARCHAR(40) = NULL,
        @job_state INT,
        @grade_cd INT,
        @status_cd INT,
        @uom_desc NVARCHAR(40),
        @isOrderClosed INT = 0,
		--0.08.00 New variables
		@comment				NVARCHAR(200),
		@qty_cons_erp			FLOAT,
		@reas_code			INT,
		@item_scrapped		BIT

    -- Declare Audit Trail
    DECLARE
        @auditTrailParameters ofi_AUDITTRAILPARAMETERS,
        @iRowId int,
        @audit_trail INT = 1,
        @grade_desc NVARCHAR(100),
        @state_desc NVARCHAR(100),
        @user_name NVARCHAR(100),
        @strModuleName nvarchar(80) = 'INV_LowLevelAdjustment',
        @strFunctionName nvarchar(80) = 'UI',
        @strActivityMsg nvarchar(200) = 'ADD',
        @strCommentMsg nvarchar(200)

    DECLARE @TempInv TABLE (
        id         INT IDENTITY (1, 1) PRIMARY KEY,
        ent_id     INT,
        item_id    NVARCHAR(40),
        lot_no     NVARCHAR(40),
        sub_lot_no NVARCHAR(40),
        qty        FLOAT,
        row_id     INT
    )

    DECLARE
        @defaultUoMDesc NVARCHAR(20) = 'KG',
        @defaultUoMId   INT

    --00.05.00
    DECLARE @fg_sublot_no nvarchar(40)
    DECLARE @fg_lot_no nvarchar(40)

    -- Get User Id
    EXEC Sp_s_db_status_getaudtrailusr @user_id output, NULL
    SET @user_name = @user_id

    -- Get Ent Id from SP Parameter
    SELECT @ent_id = ent_id
    FROM ent (nolock)
    WHERE ent_name = @SU_Name

    -- Get Default UoM Desc
    SELECT @defaultUoMDesc = attr_value
    FROM ent_attr WITH (NOLOCK)
    WHERE ent_id = @ent_id
        AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) WHERE attr_desc = 'DefaultStorageUoM' AND attr_grp = 2)

    SET @defaultUoMDesc = Isnull(@defaultUoMDesc, 'KG')

    -- v0.02.00 Get Good Consumption (Item Reason)
    DECLARE
        @strGoodConsReas NVARCHAR(40) = 'Good Consumption',
        @intGoodConsReas INT = NULL

    SELECT @intGoodConsReas = ISNULL(reas_cd, 1)
    FROM item_reas WITH (NOLOCK)
    WHERE reas_desc = @strGoodConsReas

	-- 0.08.00 Get Close order Consumption (Item Reason)
	DECLARE @strCloseOrderConsReas NVARCHAR(40) = 'Closed order',
			@intCloseOrderConsReas INT = NULL
	DECLARE @strSpendInvOnLastJob	NVARCHAR(40) = 'SpendInvOnLastJob',
			@intSpendInvOnLastJob	INT

	SELECT @intCloseOrderConsReas = Isnull(reas_cd,1)
	FROM   item_reas WITH (NOLOCK)
	WHERE  reas_desc = @strCloseOrderConsReas

	SELECT @intSpendInvOnLastJob = attr_id
	FROM   attr WITH (NOLOCK)
	WHERE  attr_desc = @strSpendInvOnLastJob
	-- 0.08.00 End

    -- Get Default UoM Id
    SELECT @defaultUoMId = uom_id
    FROM uom WITH (NOLOCK)
    WHERE description = @defaultUoMDesc

    -- Get Current Qty on the Silo
    SELECT
        @qty_left = SUM(qty_left),
        @inv_item_id = MAX(item_id)
    FROM item_inv (NOLOCK)
    WHERE ent_id = @ent_id

    -- PRINT @qty_left

    -- Get Plant or Storage threshold
    SELECT @su_level_threshold = CONVERT(INT, REPLACE(ea.attr_value, ',', ''))
    FROM ent_attr (NOLOCK) ea
        -- v0.02.00 refine the logic when taking value from nvarchar attr value
        JOIN attr (NOLOCK) a
            ON ea.attr_id = a.attr_id
    WHERE ea.ent_id = @ent_id
        AND a.attr_desc = 'StorageUnitThreshold'

    -- PRINT @su_level_threshold

    SELECT @plant_level_threshold = CONVERT(INT, REPLACE(ea.attr_value, ',', ''))
    FROM ent_attr (NOLOCK) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
        JOIN attr (NOLOCK) a
            ON ea.attr_id = a.attr_id
    WHERE ea.ent_id = (SELECT TOP 1 ent_id FROM ent (NOLOCK) WHERE parent_ent_id IS NULL ORDER BY ent_id)
        AND a.attr_desc = 'StorageUnitThreshold'

    -- Convert Qty into Default UoM
    SELECT @qty_left = dbo.[Fn_ofi_convertqtybyitemidanduom](
        @inv_item_id, @qty_left, uom_id, @defaultUoMId, NULL, NULL, NULL, NULL)
    FROM item WITH (NOLOCK)
    WHERE item_id = @inv_item_id

    -- If the Silo level threshold is missing then take the plan level threshold
    IF ( @su_level_threshold = 0 )
    BEGIN
        SET @final_threshold = @plant_level_threshold
    END
    ELSE
    BEGIN
        SET @final_threshold = @su_level_threshold
    END

    -- v0.02.00 Ensure qty has value even no inventory
    SET @qty_left = Isnull(@qty_left, 0.00)

    -- if silo qty less than the thresshold
    IF (@qty_left < @final_threshold AND @qty_left > 0) -- v0.02.00 Add validation qty must more than 0
    BEGIN        
        -- Get last consumed order
        SELECT TOP 1
            @item_id = iv.item_id,
            @lot_no = iv.lot_no,
            @sublot_no = iv.sublot_no,
            @fg_lot_no = ic_max.fg_lot_no,       --00.05.00 select fg_lot/sublot_no from last consumed order
            @fg_sublot_no = ic_max.fg_sublot_no, --00.05.00
            @last_consumed_date = ic_max.max_id,
            @wo_id = ic_max.wo_id,
            @oper_id = ic_max.oper_id,
            @seq_no = ic_max.seq_no,
            @job_state = j.state_cd,
            @target_sched_ent_id = j.target_sched_ent_id,
            @job_pos = je.job_pos,
            @bom_pos = jb.bom_pos
        FROM item_inv iv WITH (NOLOCK)
            LEFT JOIN (
                SELECT
                    item_id,
                    lot_no,
                    sublot_no,
                    fg_lot_no,    --00.05.00
                    fg_sublot_no, --00.05.00
                    from_ent_id,
                    wo_id,
                    oper_id,
                    seq_no,
                    MAX(last_edit_at) AS max_id
                FROM item_cons WITH (NOLOCK)
                GROUP BY
                    item_id,
                    lot_no,
                    sublot_no,
                    fg_lot_no,    --00.05.00
                    fg_sublot_no, --00.05.00
                    from_ent_id,
                    wo_id,
                    oper_id,
                    seq_no
            ) AS ic_max
                ON iv.item_id = ic_max.item_id
                AND iv.lot_no = ic_max.lot_no
                AND iv.sublot_no = ic_max.sublot_no
                AND iv.ent_id= ic_max.from_ent_id
            LEFT JOIN job_exec je WITH (NOLOCK)
                ON ic_max.wo_id = je.cur_wo_id
                AND ic_max.oper_id = je.cur_oper_id
                AND ic_max.seq_no = je.cur_seq_no
            LEFT JOIN job j WITH (NOLOCK)
                ON ic_max.wo_id = j.wo_id
                AND ic_max.oper_id = j.oper_id
                AND ic_max.seq_no = j.seq_no
            LEFT JOIN job_bom jb WITH (NOLOCK)
                ON ic_max.wo_id = jb.wo_id
                AND ic_max.oper_id = jb.oper_id
                AND ic_max.seq_no = jb.seq_no
                AND iv.item_id = jb.item_id
                AND jb.bom_pos > 0
        WHERE iv.ent_id = @ent_id
        ORDER BY max_id DESC

		--0.08.00
		--If there is no connection for sublot_no between invenotry and item_cons table
		--try connect only by lot_no
		IF @wo_id IS NULL
		BEGIN
			SELECT TOP 1
			@fg_lot_no = ic_max.fg_lot_no,
			@fg_sublot_no = ic_max.fg_sublot_no,
			@last_consumed_date = ic_max.max_id,
			@wo_id = ic_max.wo_id,
			@oper_id = ic_max.oper_id,
			@seq_no = ic_max.seq_no,
			@job_state = j.state_cd,
			@target_sched_ent_id = j.target_sched_ent_id,
			@job_pos = je.job_pos,
			@bom_pos = jb.bom_pos
			FROM 
				item_inv iv WITH (NOLOCK)
			LEFT JOIN 
				(SELECT 
					 item_id, 
					 lot_no, 
					 sublot_no,
					 fg_lot_no,
					 fg_sublot_no,
					 from_ent_id,
					 wo_id,
					 oper_id,
					 seq_no,
					 MAX(last_edit_at) AS max_id
				 FROM 
					 item_cons WITH (NOLOCK)
				 GROUP BY 
					 item_id, 
					 lot_no, 
					 sublot_no,
					 fg_lot_no,
					 fg_sublot_no,
					 from_ent_id,
					 wo_id,oper_id,seq_no) AS ic_max
			ON 
				iv.item_id = ic_max.item_id 
				AND iv.lot_no = ic_max.lot_no 
				--AND iv.sublot_no = ic_max.sublot_no
				AND iv.ent_id= ic_max.from_ent_id
			LEFT JOIN job_exec je WITH (NOLOCK) ON ic_max.wo_id = je.cur_wo_id
							  AND ic_max.oper_id = je.cur_oper_id
							  AND ic_max.seq_no = je.cur_seq_no
			LEFT JOIN job j WITH (NOLOCK) ON ic_max.wo_id = j.wo_id
							  AND ic_max.oper_id = j.oper_id
							  AND ic_max.seq_no = j.seq_no
			LEFT JOIN job_bom jb WITH (NOLOCK) ON ic_max.wo_id = jb.wo_id
							  AND ic_max.oper_id = jb.oper_id
							  AND ic_max.seq_no = jb.seq_no
							  AND iv.item_id = jb.item_id
							  AND jb.bom_pos > 0
			WHERE iv.ent_id = @ent_id
			ORDER BY max_id DESC

			--If there is no connection for lot_no between invenotry and item_cons table
			--try connect only by item_id and inventory id
			IF @wo_id IS NULL
			BEGIN
				--risky action for some silos - this is why only authorized ones can be spend just on last cons job
				IF ISNULL((SELECT attr_value FROM ent_attr	WHERE attr_id = @intSpendInvOnLastJob AND ent_id = @ent_id),0)=1
				BEGIN
					SELECT TOP 1
					@fg_lot_no = ic_max.fg_lot_no,
					@fg_sublot_no = ic_max.fg_sublot_no,
					@last_consumed_date = ic_max.max_id,
					@wo_id = ic_max.wo_id,
					@oper_id = ic_max.oper_id,
					@seq_no = ic_max.seq_no,
					@job_state = j.state_cd,
					@target_sched_ent_id = j.target_sched_ent_id,
					@job_pos = je.job_pos,
					@bom_pos = jb.bom_pos
					FROM 
						item_inv iv WITH (NOLOCK)
					LEFT JOIN 
						(SELECT 
							 item_id, 
							 lot_no, 
							 sublot_no,
							 fg_lot_no,
							 fg_sublot_no,
							 from_ent_id,
							 wo_id,
							 oper_id,
							 seq_no,
							 MAX(last_edit_at) AS max_id
						 FROM 
							 item_cons WITH (NOLOCK)
						 GROUP BY 
							 item_id, 
							 lot_no, 
							 sublot_no,
							 fg_lot_no,
							 fg_sublot_no,
							 from_ent_id,
							 wo_id,oper_id,seq_no) AS ic_max
					ON 
						iv.item_id = ic_max.item_id 
						--AND iv.lot_no = ic_max.lot_no 
						--AND iv.sublot_no = ic_max.sublot_no
						AND iv.ent_id= ic_max.from_ent_id
					LEFT JOIN job_exec je WITH (NOLOCK) ON ic_max.wo_id = je.cur_wo_id
									  AND ic_max.oper_id = je.cur_oper_id
									  AND ic_max.seq_no = je.cur_seq_no
					LEFT JOIN job j WITH (NOLOCK) ON ic_max.wo_id = j.wo_id
									  AND ic_max.oper_id = j.oper_id
									  AND ic_max.seq_no = j.seq_no
					LEFT JOIN job_bom jb WITH (NOLOCK) ON ic_max.wo_id = jb.wo_id
									  AND ic_max.oper_id = jb.oper_id
									  AND ic_max.seq_no = jb.seq_no
									  AND iv.item_id = jb.item_id
									  AND jb.bom_pos > 0
					WHERE iv.ent_id = @ent_id
					ORDER BY max_id DESC

					IF @wo_id IS NOT NULL SET @comment = ' linked by item_id'
				END
			END
			ELSE SET @comment = ' linked by lot_no'
		END
		--0.08.00 End

        -- Ensure order selected is not closed
        SELECT @wo_state = state_cd
        FROM   wo WITH (nolock)
        WHERE  wo_id = @wo_id

        IF ( @wo_state = 3 ) -- 3 = Closed
        BEGIN
            SET @isOrderClosed = 1
        END
		
        -- [0.07.00]
        -- Force scrap if the silo has the ForceScrapOnLowLevel attribute set
        DECLARE @ForceScrapOnLowLevelId AS int;
        SELECT @ForceScrapOnLowLevelId = attr_id
        FROM attr
        WHERE attr_desc = 'ForceScrapOnLowLevel'
            AND attr_grp = 2 -- Entity
            
        DECLARE @ForceScrapOnLowLevel AS bit;
        SELECT @ForceScrapOnLowLevel = IIF(attr_value = '1', 1, 0)
        FROM ent_attr
        WHERE ent_id = @ent_id
            AND attr_id = @ForceScrapOnLowLevelId;
        
        IF (@ForceScrapOnLowLevel = 1)
        BEGIN
            PRINT 'Force scrap due to ForceScrapOnLowLevel attribute'

            INSERT INTO @TempInv (
                ent_id,
                item_id,
                lot_no,
                sub_lot_no,
                qty,
                row_id
            )
            SELECT
                iv.ent_id,
                iv.item_id,
                iv.lot_no,
                iv.sublot_no,
                qty_left,
                row_id
            FROM item_inv (NOLOCK) iv
            WHERE ent_id = @ent_id

            IF EXISTS (SELECT 1 FROM @TempInv)
            BEGIN
                SET @Counter = (SELECT Count(1) FROM @TempInv)

                WHILE (@iterate <= @Counter)
                BEGIN
                    SELECT
                        @cons_lot_no = at.lot_no,
                        @cons_sublot_no = at.sub_lot_no,
                        @qty_left = at.qty,
                        @item_id = at.item_id,
                        @grade_cd = iv.grade_cd,
                        @status_cd = iv.status_cd,
                        @uom_desc = u.abbreviation
                    FROM @TempInv at
                        LEFT JOIN item_inv iv WITH (NOLOCK)
                            ON at.row_id = iv.row_id
                        LEFT JOIN uom u WITH (NOLOCK)
                            ON iv.uom_id = u.uom_id
                    WHERE id = @iterate

                    EXEC @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
                        @from_ent_id = @ent_id,
                        @item_id = @item_id,
                        @lot_no = @cons_lot_no,
                        @sublot_no = @cons_sublot_no,
                        @qty_cons = @qty_left,
                        @reas_cd = @intGoodConsReas,
                        @grade_cd = @grade_cd,
                        @status_cd = @status_cd,
                        @user_id = @user_id,
                        @wo_id = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @oper_id = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @seq_no = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @shift_start_local = NULL,
                        @fg_lot_no = @fg_lot_no, --0.05.00
                        @fg_sublot_no = @fg_sublot_no, --0.05.00
                        @item_scrapped = 1,
                        @ent_id = @target_sched_ent_id, --0.05.00
                        @shift_id = NULL,
                        @qty_cons_erp = NULL,
                        @ext_ref = NULL,
                        @transaction_type = NULL,
                        @genealogy_id = NULL,
                        @upstream_event_id = NULL,
                        @segment_requirement_id = NULL,
                        @segment_response_id = NULL,
                        @comments = 'Trigger with Low Signal, Scrap due to ForceScrapOnLowLevel attribute',
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @shift_start_utc = NULL,
                        @time_zone_bias_value = NULL,
                        @row_id = @row_id OUTPUT

                    --00.06.00
                    DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                    IF (@audit_trail = 1)
                    BEGIN
                        DELETE @auditTrailParameters;
                        SET @strCommentMsg = 'Scrap due to ForceScrapOnLowLevel attribute - Silo Name :' + @SU_Name
                            + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                        INSERT INTO @auditTrailParameters
                            (row_id, field_name, field_value)
                        VALUES
                            (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                            (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                            (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                            (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                            (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                            (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                            (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                        EXEC sp_I_ofi_AuditTrail
                             @module_id = @strModuleName,
                             @function_id = @strFunctionName,
                             @auditTrailParameters = @auditTrailParameters,
                             @user_id = @user_name,
                             @activity = @strActivityMsg,
                             @audit_category = 'Info',
                             @comments = @strCommentMsg
                    END

                    SET @iterate = @iterate + 1
                END
            END

            SET @Out = 0

            SELECT
                @Out AS [Out],
                @ent_id AS EntId,
                @wo_id AS WoId
            RETURN
        END
        -- [/0.07.00]

        -- check the running job on silo and assign qty_left to it
        IF (@wo_id IS NOT NULL AND @job_state = 3 AND @isOrderClosed = 0)
            BEGIN
                PRINT 'WoId is running'
                -- Get bom pos from selected order
                SELECT TOP 1 @bom_pos = jb.bom_pos
                FROM job_bom (NOLOCK) jb
                WHERE jb.wo_id = @wo_id
                    AND jb.oper_id = @oper_id
                    AND jb.seq_no = @seq_no
                    AND jb.item_id = @item_id;

                INSERT INTO @TempInv (
                    ent_id,
                    item_id,
                    lot_no,
                    sub_lot_no,
                    qty,
                    row_id
                )
                SELECT
                    iv.ent_id,
                    iv.item_id,
                    iv.lot_no,
                    iv.sublot_no,
                    qty_left,
                    row_id
                FROM item_inv (NOLOCK) iv
                WHERE ent_id = @ent_id
                    AND iv.item_id IN (
                        SELECT item_id
                        FROM job_bom (NOLOCK) jb
                        WHERE jb.wo_id = @wo_id AND jb.oper_id = @oper_id AND jb.seq_no = @seq_no
                    )

                SET @Counter = (SELECT Count(1) FROM @TempInv)

                IF EXISTS (SELECT 1 FROM @TempInv)
                BEGIN
                    WHILE (@iterate <= @Counter)
                    BEGIN
                        SELECT 
                            @cons_lot_no = at.lot_no,
                            @cons_sublot_no = at.sub_lot_no,
                            @qty_left = at.qty,
                            @item_id = at.item_id,
                            @grade_cd = iv.grade_cd,
                            @status_cd = iv.status_cd,
                            @uom_desc = u.abbreviation
                        FROM @TempInv at
                            LEFT JOIN item_inv iv WITH (NOLOCK)
                                ON at.row_id = iv.row_id
                            LEFT JOIN uom u WITH (NOLOCK)
                                ON iv.uom_id = u.uom_id
                        WHERE id = @iterate

						--0.08.00 create comment
						SET @comment = 'Trigger with Low Signal-Consumed on running Job' + ISNULL(@comment,'')

                        EXEC @return_value = [dbo].[Sp_i_item_cons_addcons]
                            @session_id = NULL,
                            @event_time_local = NULL,
                            @user_id = @user_id,
                            @ent_id = @target_sched_ent_id,
                            @job_pos = @job_pos,
                            @bom_pos = @bom_pos,
                            @qty_cons = @qty_left,
                            @reas_cd = @intGoodConsReas,
                            @lot_no = @cons_lot_no,
                            @fg_lot_no = @fg_lot_no, --00.05.00
                            @sublot_no = @cons_sublot_no,
                            @fg_sublot_no = @fg_sublot_no, --00.05.00
                            @from_ent_id = @ent_id,
                            @item_id = @item_id,
                            @ext_ref = NULL,
                            @apply_scaling_factor = NULL,
                            @genealogy_id = NULL,
                            @upstream_event_id = NULL,
                            @segment_requirement_id = NULL,
                            @segment_response_id = NULL,
                            @comments =@comment, --0.08.00 use variable
                            @spare1 = NULL,
                            @spare2 = NULL,
                            @spare3 = NULL,
                            @spare4 = NULL,
                            @created_at_utc = @date_time_UTC,
                            @row_id = @row_id OUTPUT

                        --00.06.00
                        DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                        IF (@audit_trail = 1)
                        BEGIN
                            print 'Audit'
                            DELETE @auditTrailParameters;
                            SET @strCommentMsg = 'Consumed on running Job - Order No : ' + @wo_id
                                + ', Operation : ' + @oper_id
                                + ', Seq No : ' + CAST(@seq_no AS varchar)
                                + ', Silo Name :' + @SU_Name
                                + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                            INSERT INTO @auditTrailParameters
                                (row_id, field_name, field_value)
                            VALUES
                                (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                                (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                                (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                                (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                                (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                                (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                                (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                            EXEC sp_I_ofi_AuditTrail
                                 @module_id = @strModuleName,
                                 @function_id = @strFunctionName,
                                 @auditTrailParameters = @auditTrailParameters,
                                 @user_id = @user_name,
                                 @activity = @strActivityMsg,
                                 @audit_category = 'Info',
                                 @comments = @strCommentMsg
                        END

                        SET @iterate = @iterate + 1
                    END
                END

                DELETE FROM @TempInv

                SET @Out = 0

                SELECT
                    @Out AS [Out],
                    @ent_id AS EntId,
                    @wo_id  AS WoId
                RETURN
            END

        IF (@wo_id IS NOT NULL AND @job_state IN (4,5) AND @isOrderClosed = 0)
        BEGIN
            PRINT 'WoId is stopped/completed'

            INSERT INTO @TempInv (
                ent_id,
                item_id,
                lot_no,
                sub_lot_no,
                qty,
                row_id
            )
            SELECT
                iv.ent_id,
                iv.item_id,
                iv.lot_no,
                iv.sublot_no,
                qty_left,
                row_id
            FROM item_inv (NOLOCK) iv
            WHERE ent_id = @ent_id
                AND iv.item_id IN (
                    SELECT item_id
                    FROM job_bom (NOLOCK) jb
                    WHERE jb.wo_id = @wo_id AND jb.oper_id = @oper_id AND jb.seq_no = @seq_no
                )

            SET @Counter = (SELECT Count(1) FROM @TempInv)

            IF EXISTS (SELECT 1 FROM @TempInv)
            BEGIN
                WHILE (@iterate <= @Counter)
                BEGIN
                    SELECT
                        @cons_lot_no = at.lot_no,
                        @cons_sublot_no = at.sub_lot_no,
                        @qty_left = at.qty,
                        @item_id = at.item_id,
                        @grade_cd = iv.grade_cd,
                        @status_cd = iv.status_cd,
                        @uom_desc = u.abbreviation
                    FROM @TempInv at
                        LEFT JOIN item_inv iv WITH (NOLOCK)
                            ON at.row_id = iv.row_id
                        LEFT JOIN uom u WITH (NOLOCK)
                            ON iv.uom_id = u.uom_id
                    WHERE id = @iterate

					--0.08.00 create comment
					SET @comment = 'Trigger with Low Signal-Consumed with last consumed job' + ISNULL(@comment,'')

                    EXEC @return_value = [dbo].[Sp_i_item_cons_addconspostexec]
                        @session_id = NULL,
                        @user_id = @user_id,
                        @ent_id = @target_sched_ent_id,
                        @bom_pos = @bom_pos,
                        @qty_cons = @qty_left,
                        @wo_id = @wo_id,
                        @oper_id = @oper_id,
                        @seq_no = @seq_no,
                        @shift_start_local = NULL,
                        @shift_id = NULL,
                        @item_id = @item_id,
                        @reas_cd = @intGoodConsReas,
                        @lot_no = @cons_lot_no,
                        @fg_lot_no = @fg_lot_no,    --00.05.00
                        @sublot_no = @cons_sublot_no,
                        @fg_sublot_no = @fg_sublot_no,    --00.05.00
                        @from_ent_id = @ent_id,
                        @ext_ref = NULL,
                        @genealogy_id = NULL,
                        @upstream_event_id = NULL,
                        @segment_requirement_id = NULL,
                        @segment_response_id = NULL,
                        @comments = @comment, --0.08.00 use variable
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @created_at_utc = @date_time_UTC,
                        @row_id = @row_id output,
                        @time_zone_bias_value = NULL

                    --00.06.00
                    DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                    IF (@audit_trail = 1)
                    BEGIN
                        DELETE @auditTrailParameters;
                        SET @strCommentMsg = 'Consumed with last consumed job - Order No : ' + @wo_id
                            + ', Operation : ' + @oper_id
                            + ', Seq No : ' + CAST(@seq_no AS varchar)
                            + ', Silo Name :' + @SU_Name
                            + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                        INSERT INTO @auditTrailParameters
                            (row_id, field_name, field_value)
                        VALUES
                            (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                            (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                            (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                            (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                            (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                            (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                            (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                        EXEC sp_I_ofi_AuditTrail
                             @module_id = @strModuleName,
                             @function_id = @strFunctionName,
                             @auditTrailParameters = @auditTrailParameters,
                             @user_id = @user_name,
                             @activity = @strActivityMsg,
                             @audit_category = 'Info',
                             @comments = @strCommentMsg
                    END

                    SET @iterate = @iterate + 1
                END
            END

            DELETE FROM @TempInv

            SET @Out = 0

            SELECT
                @Out AS [Out],
                @ent_id AS EntId,
                @wo_id  AS WoId
            RETURN
        END

        IF (@wo_id IS NULL OR @isOrderClosed = 1)
        BEGIN
            PRINT 'No order is founded / order closed'

            INSERT INTO @TempInv (
                ent_id,
                item_id,
                lot_no,
                sub_lot_no,
                qty,
                row_id
            )
            SELECT
                iv.ent_id,
                iv.item_id,
                iv.lot_no,
                iv.sublot_no,
                qty_left,
                row_id
            FROM item_inv (NOLOCK) iv
            WHERE ent_id = @ent_id

            IF EXISTS (SELECT 1 FROM @TempInv)
            BEGIN
                SET @Counter = (SELECT Count(1) FROM @TempInv)

                WHILE (@iterate <= @Counter)
                BEGIN
                    SELECT
                        @cons_lot_no = at.lot_no,
                        @cons_sublot_no = at.sub_lot_no,
                        @qty_left = at.qty,
                        @item_id = at.item_id,
                        @grade_cd = iv.grade_cd,
                        @status_cd = iv.status_cd,
                        @uom_desc = u.abbreviation
                    FROM @TempInv at
                        LEFT JOIN item_inv iv WITH (NOLOCK)
                            ON at.row_id = iv.row_id
                        LEFT JOIN uom u WITH (NOLOCK)
                            ON iv.uom_id = u.uom_id
                    WHERE id = @iterate

					--0.08.00 set specific values
					IF @isOrderClosed = 1
					BEGIN
						SET @comment = 'Trigger with Low Signal-Consumed on closed Job'
						SET @reas_code = ISNULL(@intCloseOrderConsReas,@intGoodConsReas)
						SET @item_scrapped = 0
						SET @strCommentMsg = 'Consumed with closed job - Silo Name :'+@SU_Name+', Reduced Qty :'+CAST(@qty_left AS varchar)+' '+@uom_desc
					END
					ELSE
					BEGIN
						SET @comment = 'Trigger with Low Signal, Scrap because of no order is found'
						SET @reas_code = @intGoodConsReas
						SET @item_scrapped = 1
						SET @strCommentMsg = 'Scrap because of no order is founded - Silo Name :'+@SU_Name+', Reduced Qty :'+CAST(@qty_left AS varchar)+' '+@uom_desc
					END

                    EXEC @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
                        @from_ent_id = @ent_id,
                        @item_id = @item_id,
                        @lot_no = @cons_lot_no,
                        @sublot_no = @cons_sublot_no,
                        @qty_cons = @qty_left,
                        @reas_cd = @reas_code, --0.08.00
                        @grade_cd = @grade_cd,
                        @status_cd = @status_cd,
                        @user_id = @user_id,
                        @wo_id = @wo_id,		--0.08.00
						@oper_id = @oper_id,	--0.08.00
						@seq_no = @seq_no,		--0.08.00
                        @shift_start_local = NULL,
                       @fg_lot_no = @fg_lot_no,	--0.05.00
						@fg_sublot_no = @fg_sublot_no,	--0.05.00
						@item_scrapped = @item_scrapped, --0.08.00
						@ent_id = @target_sched_ent_id, --0.05.00
                        @shift_id = NULL,
                        @qty_cons_erp = NULL,
                        @ext_ref = NULL,
                        @transaction_type = NULL,
                        @genealogy_id = NULL,
                        @upstream_event_id = NULL,
                        @segment_requirement_id = NULL,
                        @segment_response_id = NULL,
                        @comments = @comment, --0.08.00
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @shift_start_utc = NULL,
                        @time_zone_bias_value = NULL,
                        @row_id = @row_id OUTPUT

                    --00.06.00
                    DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                    IF (@audit_trail = 1)
                    BEGIN
                        DELETE @auditTrailParameters;
                        SET @strCommentMsg = 'Scrap because of no order is founded Or order closed - Silo Name :' + @SU_Name
                            + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                        INSERT INTO @auditTrailParameters
                            (row_id, field_name, field_value)
                        VALUES
                            (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                            (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                            (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                            (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                            (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                            (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                            (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                        EXEC sp_I_ofi_AuditTrail
                             @module_id = @strModuleName,
                             @function_id = @strFunctionName,
                             @auditTrailParameters = @auditTrailParameters,
                             @user_id = @user_name,
                             @activity = @strActivityMsg,
                             @audit_category = 'Info',
                             @comments = @strCommentMsg
                    END

                    SET @iterate = @iterate + 1
                END
            END

            SET @Out = 0

            SELECT
                @Out AS [Out],
                @ent_id AS EntId,
                @wo_id  AS WoId
            RETURN
        END

        SET @Out = 0
    END
    ELSE IF (@qty_left = 0.00) --v0.02.00 Add checking if qty is 0
    BEGIN
        --00.06.00
        DELETE FROM item_inv WHERE ent_id = @ent_id AND qty_left <= 0
        PRINT 'Qty is Zero'
        SET @Out = 3
        PRINT @Out
    END
    ELSE
    BEGIN
        PRINT 'Qty More Than Threshold'
        SET @Out = 1
        PRINT @Out
    END

    SELECT @Out    AS [Out],
           @ent_id AS EntId,
           @wo_id  AS WoId
END

-- Procedure definition
CREATE PROCEDURE [dbo].[sp_I_Line]
  (@line_name nvarchar(80),
   @line_class bit = 0,
   @origin_line_class_id int32,
   @labor_load int32,
   @max_wo int32 = 1,
   @prod_ent_id int32 = null,
   @prod_uom int32 = 0,
   @batch_size tfloat = 1,
   @std_item_id string40 = null,
   @bottleneck_ent_id int32 = null,
   @target_util tfloat = null,
   @target_qual tfloat = null,
   @target_perf tfloat = null,
   @target_oee tfloat = null,
   @spare1 nvarchar(2000),
   @spare2 nvarchar(2000),
   @spare3 nvarchar(2000),
   @spare4 nvarchar(2000),
   @last_edit_comment nvarchar(254),
   @last_edit_at DATETIME OUT,
   @line_id int OUT)
AS
-- ***********************************************************************************************************************
-- Module Name	      - SP_I_Line
-- Description	      - inserts a production line record
-- Author	          - Sara Reynolds
-- Date Created	      -	02/25/2013
-- Version	          - 4.6.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Change Date	Change By	Ver.	Changes
-- 05/17/2013	Raghu		4.6	UserStory:178630 - configure normalized production rates
-- 08/14/2014	Raghu		4.6	UserStory: 226242 - As Bruce, I want to indicate that a specific line position "IS" the bottleneck.
-- 12/03/2014	JimO		5.1 UserStory: 419435 - As Lenka, I want the standard access methods on the line table to be capable
--													of storing and retrieving KPI targets
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET NOCOUNT ON
BEGIN
DECLARE  @last_edit_by	NVARCHAR(40)

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

 IF @line_class IS null SET @line_class = 0
 IF @max_wo IS null SET @max_wo = 1
 SELECT @prod_uom = COALESCE(@prod_uom, 0), @batch_size = COALESCE(@batch_size, 1)

 INSERT INTO line
 (line_name,
  line_class,
  origin_line_class_id,
  labor_load,
  max_wo,
  prod_ent_id,
  prod_uom,
  batch_size,
  std_item_id,
  bottleneck_ent_id,
  target_util,
  target_qual,
  target_perf,
  target_oee,
  spare1,
  spare2,
  spare3,
  spare4,
  last_edit_comment,
  last_edit_by,
  last_edit_at)
VALUES
  (@line_name,
   @line_class,
   @origin_line_class_id,
   @labor_load,
   @max_wo,
   @prod_ent_id,
   @prod_uom,
   @batch_size,
   @std_item_id,
   @bottleneck_ent_id,
   @target_util,
   @target_qual,
   @target_perf,
   @target_oee,
   @spare1,
   @spare2,
   @spare3,
   @spare4,
   @last_edit_comment,
   @last_edit_by,
   @last_edit_at)

-- Auto Identifer table - return the id of the record created
SELECT @line_id = SCOPE_IDENTITY()


-- add row in grp_line_link table for all defined lines (default access = 0) if this is not a line class
IF @line_class = 0 BEGIN
	INSERT INTO grp_line_link (grp_id, line_id, accss, last_edit_comment, last_edit_by, last_edit_at)
	SELECT grp_id, @line_id, 0, @last_edit_comment, @last_edit_by, @last_edit_at FROM grp_name
END

END

--===========================================================================================
-- Name:    SP_U_EI_MM_WIP_ITEM
-- Description:  Inserts the WIP item
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  KN          2023-01-12      Initial version.
-- 0.01.01  kn			2023-07-20		Update logic to handle WIP items
-- 0.01.02	KN			2023-07-25		Added logic to handle WIP creation for FG items
-- 0.01.03	LK			2024-02-27		Modified the else logic for spare2
-- 0.01.04	LK			2024-03-01		Updated logic to add item attribute
-- 0.01.05	LK			2024-06-19		Updated logic to delete existing attribute, added condition to delete only those which are coming from sap
-- 0.01.06	MC			2025-10-08		Updated logic for Cake Blend WIP description to align with Insert version
-- ===========================================================================================

CREATE   PROCEDURE [dbo].[SP_U_EI_MM_WIP_ITEM] (@item_id NVARCHAR(40),@item_class NVARCHAR(80),@item_group NVARCHAR(80)) AS
BEGIN
	DECLARE @item_desc VARCHAR(MAX), @is_wip BIT,@wip_item_id VARCHAR(50), @wip_name VARCHAR(MAX), @spare2 VARCHAR(MAX), @wip_class VARCHAR(MAX), @wip_desc VARCHAR(MAX), 
	@wip_item_grp VARCHAR(MAX), @rc INT, @attr_id INT,@mod_id VARCHAR(40), @uom_id INT, @lifetime INT, @obsolete BIT, @num_decimals INT,
	@error_msg  NVARCHAR(500), @error_severity INT, @error_state    INT,@item_class_id VARCHAR(100),
	@item_classification   NVARCHAR(80),                                           
    @plant_code            NVARCHAR(40),                                           
    @legacy_code           NVARCHAR(40),
    @item_status           NVARCHAR(40),  
	@material_state        NVARCHAR(40),
	@production_supervisor NVARCHAR(40),
	@itemgrpattrid int,
	@prodsuperattrid int,
	@plantcodeattrid int,
	@languagekeyattrid int,
	@legacykeyattrid int,
	@automationidattrid int

	IF EXISTS (SELECT 1 FROM item WHERE item_id = @item_id)
	BEGIN

		--DO THE ENTIRE LOGIC ONLY FOR SFG ITEMS OR FOR ITEMS WITH ITEM GROUP EITHER AS COCOA LIQUOR OR CAKE
		
		IF -- 0.01.06 modify condition as there is no WIP for CAKE items
		((UPPER(@item_class) = UPPER('Semifinished Goods') OR UPPER(@item_class) = UPPER('Finshed Goods')) AND (UPPER(@item_group) = UPPER('Cocoa Liquor')))
		OR
		/*UPPER(@item_group) = UPPER('Cocoa Cake') OR*/
		(UPPER(@item_class) = UPPER('Semifinished Goods') AND (UPPER(@item_group) = UPPER('Cocoa Low Fat Powder') OR UPPER(@item_group) = UPPER('Cocoa Highfat Powder')))
		BEGIN		
			SELECT @item_desc = item_desc,@item_class_id = item_class_id FROM item with(nolock) WHERE item_id = @Item_id

			PRINT @item_class

			SET @spare2 = NULL
			SELECT @spare2 = spare2 FROM item_class with(nolock) WHERE item_class_id = @item_class or item_class_desc = @item_class

			SELECT @uom_id = uom_id,@lifetime = lifetime,@obsolete = obsolete,@num_decimals = num_decimals FROM item with(nolock) WHERE item_id = @item_id

			--CREATE A NEW WIP ITEM ID BASED ON THE INCOMING ITEM ID. THE REST OF THE ITEM DETAILS CAN BE REUSED

			IF @spare2 IS NULL
				SET @wip_item_id = CONCAT('50', substring(@Item_id, 3, len(@Item_id)))
			ELSE
				SET @wip_item_id = CONCAT(@spare2, substring(@Item_id, 3, len(@Item_id))) -- 0.01.03

			SELECT @wip_class = item_class_id FROM item_class with(nolock) WHERE item_class_desc = 'Intermediate Materials'
			
			SET @wip_desc = 'WIP '

			DECLARE @attr_desc varchar(100) = NULL

			SELECT @attr_desc = attr_value from item_attr with(nolock) where item_id = @Item_id and attr_id = (Select attr_id from attr where attr_desc = 'ItemGroup')

			/*KN 25Jul23 Added below logic to handle WIP creation for FG process*/
			-- 0.01.06 moved wip_item_group selecting
			IF @item_class_id = 'FG'
			BEGIN
				IF @attr_desc LIKE '%liquor%'
				BEGIN
					SET @wip_desc = @wip_desc + '(LIQUOR BLEND) '
					SET @wip_item_grp = 'LIQUOR' --must be the same as liquor item group as is substitute for them
				END
				--ELSE IF @attr_desc LIKE '%butter%' SET @wip_desc = @wip_desc + '(BUTTER BLEND) '	-- 0.01.06 modify condition as there is no WIP for BUTTER items
				--ELSE IF @attr_desc LIKE '%cake%' SET @wip_desc = @wip_desc + '(CAKE BLEND) '		-- 0.01.06 modify condition as there is no WIP for CAKE items
			END
			ELSE IF @item_class_id = 'SFG'
			BEGIN
				IF @attr_desc LIKE '%powder%'
				BEGIN
					SET @wip_desc = @wip_desc + '(CAKE BLEND) '
					SET @wip_item_grp = 'CAKE BLEND'
				END
				ELSE IF @attr_desc LIKE '%liquor%'
				BEGIN
					SET @wip_desc = @wip_desc + '(NIBS) '
					SET @wip_item_grp = 'NIBS'
				END
			END
			--0.01.06
			/*
			ELSE IF @attr_desc LIKE '%powder%'
				SET @wip_desc = @wip_desc + '(CAKE) '
			ELSE
				SET @wip_desc = @wip_desc + '(NIBS) '
			*/
			SET @wip_desc = @wip_desc +   @item_desc
			SET @wip_name = @wip_desc
			print @wip_desc
			BEGIN TRY
			BEGIN TRANSACTION

			--UPDATE THE NEW WIP ITEM

				EXECUTE @rc = [dbo].[Sp_u_item]
						@item_id = @wip_item_id,
						@item_desc =@wip_desc,
						@item_class_id = @wip_class,
						@uom_id = @uom_id,
						@template = 0,
						@lifetime = @lifetime,
						@unit_cost = NULL,
						@obsolete = @obsolete,
						@purchased = 0,
						@sold = 0,
						@num_decimals = @num_decimals,
						@must_complete_steps = 0,
						@must_prod_reqd_qty = 0,
						@min_grade = NULL,
						@min_state = NULL,
						@min_inv_level = NULL,
						@reorder_amt = NULL,
						@auto_reorder = 0,
						@lot_no_format = NULL,
						@last_lot_no = NULL,
						@max_lot_size = NULL,
						@sublot_no_format = NULL,
						@last_sublot_no = NULL,
						@serial_no_lvl = -1,
						@max_sublot_size = NULL,
						@max_order_size = NULL,
						@min_trace_inv = NULL,
						@inv_unique_by_job = 0,
						@notes = NULL,
						@spare1 = 1,
						@spare2 = NULL,
						@spare3 = NULL,
						@spare4 = NULL,
						@last_edit_comment = N'UPDATED BY EI',
						@last_edit_at = NULL

						--added update if product sp didnt work
						UPDATE item
							  SET    item_desc = @wip_desc,
									 uom_id = @uom_id,
									 item_class_id = @wip_class,
									 lifetime = @lifetime,
									 obsolete = @obsolete
							  WHERE  item_id = @wip_item_id
				-- FOR THE WIP ITEM, UPDATE ITEM GROUP ATTRIBUTE BASED ON WHAT ITEM GROUP IT BELONGS TO

				SELECT @attr_id = attr_id FROM attr WHERE attr_desc= 'ItemGroup' AND attr_grp = 1

				/*-- 0.01.04 - moved to wip_desc section
				IF @attr_desc LIKE '%powder%'
					SET @wip_item_grp = 'CAKE BLEND'
				ELSE
					BEGIN
						IF @item_class_id = 'FG' SET @wip_item_grp = 'Liquor' ELSE SET @wip_item_grp = 'NIBS'
					END
				*/

				SELECT @mod_id= CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id))) from item_attr where item_id =@wip_item_id and attr_id = @attr_id

				/*EXEC @rc = [dbo].[Sp_u_item_attr]
							@item_id = @wip_item_id,
							@attr_id = @attr_id,
							@attr_value = @wip_item_grp,
							@notes = 'UPDATED BY EI',
							@last_edit_comment = NULL,
							@mod_id = @mod_id*/
							-- 0.01.04
				DECLARE
					@mainitemattr TABLE 
					(
					attr_desc nvarchar(40),
					attr_value  nvarchar(40)
					)
					insert into @mainitemattr
					select a.attr_desc,ia.attr_value from item_attr ia with(nolock) inner join attr a with(nolock)
					on ia.attr_id=a.attr_id
					where item_id=@item_id order by a.attr_desc asc

					select @item_classification=attr_value from @mainitemattr where attr_desc='Classification'
					select @plant_code=attr_value from @mainitemattr where attr_desc='PlantCode'
					select @legacy_code=attr_value from @mainitemattr where attr_desc='LegacyCode'
					select @material_state=attr_value from @mainitemattr where attr_desc='MaterialType'
					select @production_supervisor=attr_value from @mainitemattr where attr_desc='ProductionSupervisor'
								
					select @itemgrpattrid =attr_id from attr with(nolock) where attr_desc='ItemGroup'
					select @languagekeyattrid =attr_id from attr with(nolock) where attr_desc='languagekey'
					select @plantcodeattrid =attr_id from attr with(nolock) where attr_desc='PlantCode'
					select @legacykeyattrid =attr_id from attr with(nolock) where attr_desc='LegacyCode'
					select @automationidattrid =attr_id from attr with(nolock) where attr_desc='AutomationItemId'
					select @prodsuperattrid=attr_id from attr with(nolock) where attr_desc='ProductionSupervisor'
																							
					delete from item_attr where item_id=@wip_item_id and attr_id in(@itemgrpattrid ,@prodsuperattrid,@plantcodeattrid ,@languagekeyattrid ,	@legacykeyattrid ,@automationidattrid )-- 0.01.05

					Exec [dbo].[SP_I_EI_MM_Attr] 
					@item_id  = @wip_item_id,
                                @item_group= @wip_item_grp,
                                @item_classification =@item_classification,
                                @language_key='EN',
                                @plant_code   =@plant_code,
                                @production_supervisor=@production_supervisor,
                                @legacy_code  =@legacy_code,
                                @item_status ='ACTIVE',
								@material_state  =@material_state,
								@production_method=null
				COMMIT;
			END TRY
			BEGIN CATCH
				  IF @@TRANCOUNT > 0
					ROLLBACK TRANSACTION;

				  SELECT @error_msg = Error_message(),@error_severity = Error_severity(),@error_state = Error_state();
				  RAISERROR(@error_msg,@error_severity,@error_state)
			END CATCH

		END		
	END
END

