(@src_ent_name			STRING80,
@src_site_name			STRING80,
@ent_name 					STRING80,
@description 				STRING80_NULL = NULL ,
@parent_ent_id 				INT32_NULL = NULL,
@site 						INT32_NULL = NULL,
