     -- TRACE
		exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Ent_CloneByName', @src_key='on_entry', @date_val1 = @cur_shift_start_time_local, @numeric_val1 = @cur_shift_start_time_tz,
					@date_val2 = @last_domain_change, @numeric_val2 = @last_domain_change_tz


	EXEC sp_I_Ent_Clone @ent_id OUTPUT, @src_ent_id, @ent_name, @description, @parent_ent_id, @site, @hourly_cost
			, @can_sched_jobs, @can_run_jobs, @can_capture_util, @can_capture_labor, @can_do_dnc, @can_track_oee
