CREATE PROCEDURE [dbo].[sp_i_ofi_create_sample]
@ent_name nvarchar(40),
@qm_spec_name nvarchar(40),
@item_id nvarchar(40),
@wo_id nvarchar(40),
@oper_id nvarchar(40),
@seq_no INT
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	
DECLARE	@return_value int,
		@sample_id INT,
		@def_lot_no nvarchar(40)

EXEC	@return_value = [dbo].[sp_U_Sample_GenerateASample]
		@ent_name = @ent_name,
		@site_name = NULL,
		@qm_spec_name = @qm_spec_name,
		@ver_id = NULL,
		@sample_name = NULL,
		@item_id = @item_id,
		@wo_id = @wo_id,
		@oper_id = NULL,
		@seq_no = NULL,
		@plan_name = NULL,
		@requested_time_local = NULL,
		@requested_time_utc = NULL,
		@expiry_time = NULL,
		@warning_time = NULL,
		@time_zone_bias_value = NULL,
		@sample_id = @sample_id OUTPUT

		SELECT @def_lot_no=def_lot_no 
		from job_bom with (nolock) 
		where wo_id=@wo_id and oper_id=@oper_id and seq_no=@seq_no and bom_pos=0 

		UPDATE sample SET lot_no=@def_lot_no, spare4='MES' where sample_id=@sample_id

		
END

