CREATE PROCEDURE [dbo].[sp_I_Ent_File]
(
	@ent_id int ,
	@file_path nvarchar(254) ,
	@file_desc nvarchar(40) ,
	@last_modified datetime ,
	@file_size int ,
	@author nvarchar(40) ,
