VALUES
(
	@ent_id,
	@file_path,
	@file_desc,
	@file_type,
	@last_modified,
	@file_size,
	@author,
	-- Added 07/31/2007 AML
	@spare1,
	@spare2,
	@spare3,
	@spare4,
	--
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at
)
END

--===========================================================================================
-- Name:     	sp_I_ofi_Job_Bom
-- Description:	The stored procedure will insert job bom
--	
-- Usage:		Insert Job Bom
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	SSB				2022-09-30			Initial version.
-- 0.01.01  SM				2022-12-16			Update job_bom table set may_choose_alt_inv_loc=1 when bom_pos>0
-- 0.01.02	DS				2023-01-08			update intermediate material if operation is producing WIP/ Delete by products which are part of the SAP bom but produced in other operation or not part of the recipe.
-- 0.01.03	DS				2023-01-28			Modified for setting the def lot  
-- ===========================================================================================
Create   PROCEDURE [dbo].[sp_I_ofi_InsertRecipeBOM_backup_04_22]
	-- Add the parameters for the stored procedure here
   @wo_id nvarchar(40) ,
   @oper_id nvarchar(40) ,
   @seq_no int ,
   @parent_item_id nvarchar(50),
   @ver_id INT ,
   @last_edit_comment nvarchar(254) 
 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
declare 
   @bom_pos int ,
   @item_id nvarchar(40) ,
   @reqd_grade_cd int ,
   @instruction nvarchar(2000) ,
   @qty_per_parent_item float,
   @max_qty_per_parent_item float,
   @min_qty_per_parent_item float,
   @reqd_start_val float ,
   @reqd_start_val_is_pct bit ,
   @update_inv bit ,
   @backflush bit ,
   @def_reas_cd int ,
   @def_lot_no nvarchar(40) ,
   @def_sublot_no nvarchar(40) ,
   @def_storage_ent_id int ,
   @def_reject_ent_id int ,
   @scaling_factor float ,
   @must_consume_from_inv bit,
   @may_choose_alt_inv_loc bit,
   @may_create_new_lots bit,
   @must_consume_from_wip bit,
   @must_consume_before_prod bit,
   @constant_qty bit,
   @est_time float,
   @current_subst int,
   @qty_reqd float,
   @serial_no_source bit,
   @spare1 nvarchar(1000) ,
   @spare2 nvarchar(1000) ,
   @spare3 nvarchar(1000) ,
   @spare4 nvarchar(1000) ,
	@cnt int=1,
	@mod_id varchar(36)=null,
	@row_cnt int,
	@iswip int
	,@job_reqd_qty  float
	,@defaultLotNo nvarchar(10)
	,@recipe_name nvarchar(80)
	,@req_track_no nvarchar(40) = NULL --for checking grade from SAP
	,@target_sched_ent_id int
	,@def_reas_desc_ent nvarchar(40)
	,@def_reas_cd_ent int
	, @uom_desc nvarchar(20)

if OBJECT_ID('tempdb..#temptable') Is Not Null
BEGIN
	DROP TABLE #temptable
END

if OBJECT_ID('tempdb..#jobBOMtemp') Is Not Null
BEGIN
	DROP TABLE #jobBOMtemp
END



SELECT ROW_NUMBER() OVER ( order by row_id)as rows,* INTO #temptable FROM  bom_item with(nolock) where parent_item_id=@parent_item_id and ver_id=@ver_id and bom_pos <>0 and isnull(spare2,0)<>'InActive'

select @recipe_name= recipe_name from ofi_master_recipe with(nolock) where item_id = @parent_item_id and version = @ver_id;

select @row_cnt=COUNT(0) from  #temptable

SELECT ROW_NUMBER() OVER ( order by row_id)as rows,* INTO #jobBOMtemp FROM  job_bom with(nolock) where wo_id=@wo_id and seq_no = @seq_no -- seq number becasue cake blender having multiple jobs -- and ver_id=@ver_id and bom_pos <>0 

select top 1 @job_reqd_qty = qty_reqd,@target_sched_ent_id = target_sched_ent_id  from job with(nolock) where wo_id = @wo_id and oper_id = @oper_id and seq_no = @seq_no
	-- before inserting deleting the job_bom
	if(@row_cnt<>0)
	begin
		delete from job_bom where wo_id = @wo_id and oper_id = @oper_id and seq_no = @seq_no and bom_pos<>0
	end

while(@row_cnt<>0)
BEGIN 
	select @bom_pos=bom_pos,@item_id=item_id,@qty_per_parent_item=qty_per_parent_item,@max_qty_per_parent_item=max_qty_per_parent_item,@min_qty_per_parent_item=min_qty_per_parent_item,@update_inv=update_inv,
	@backflush=backflush,@scaling_factor=scaling_factor,@must_consume_from_inv=must_consume_from_inv,@may_choose_alt_inv_loc=may_choose_alt_inv_loc,@may_create_new_lots=may_create_new_lots,
	@must_consume_from_wip=must_consume_from_wip,@must_consume_before_prod=must_consume_before_prod,@constant_qty=constant_qty,@reqd_grade_cd=reqd_grade_cd,@instruction=instruction,@def_reas_cd=def_reas_cd,
	@def_lot_no=def_lot_no,@def_sublot_no=def_sublot_no,@def_storage_ent_id=def_storage_ent_id,@def_reject_ent_id=def_reject_ent_id,@est_time=est_time,@serial_no_source=serial_no_source,@spare1=spare1,
	@spare2=spare2,@spare3=@spare3,@spare4=spare4
	from #temptable where rows=@cnt


	-- if exists(select * from job_bom with(nolock) where wo_id =@wo_id and oper_id =@oper_id and seq_no = @seq_no and bom_pos=@bom_pos )
	-- DS commented above line if already exists ,it is not deleting
	  -- begin
	   
			--EXEC  [dbo].[sp_D_Job_Bom]  @wo_id,@oper_id,@seq_no,@bom_pos,@mod_id
	  -- end 
	  --Comments of the below condtion on 16-DEC-2022 for bug 452 to enable storage location 
	  if (@bom_pos >0)
	  begin
	   set @may_choose_alt_inv_loc = 1
	  end
	  --code end 

	  
	-- setting the qty_reqd values
	 --set @qty_reqd = round(@qty_per_parent_item*@job_reqd_qty,4);
	 
		select @uom_desc = uom.description from item with(nolock) inner join uom with(nolock) on uom.uom_id  = item.uom_id and  item_id = @item_id
		set @qty_reqd = round((case when (@qty_per_parent_item < 0.001) AND @uom_desc = 'KG' then 0 else @qty_per_parent_item end) *@job_reqd_qty,4);
		set @qty_per_parent_item = case when (@qty_per_parent_item < 0.001) AND @uom_desc = 'KG' then 0 else @qty_per_parent_item end 
	
	
	declare @p36 varchar(30)
	set @p36=NULL
	
	if(@qty_per_parent_item  <=  0.00001) set @qty_per_parent_item = 0
	if(@max_qty_per_parent_item  <=  0.00001) set @max_qty_per_parent_item = 0
	if(@min_qty_per_parent_item  <=  0.00001) set @min_qty_per_parent_item = 0

	exec SP_I_JOB_BOM @wo_id=@wo_id,@oper_id=@oper_id,@seq_no=@seq_no,@bom_pos=@bom_pos,@item_id=@item_id,@reqd_grade_cd=@reqd_grade_cd,@instruction=@instruction,
	@qty_per_parent_item=@qty_per_parent_item,@max_qty_per_parent_item=@max_qty_per_parent_item,
	@min_qty_per_parent_item=@min_qty_per_parent_item,@reqd_start_val=NULL,@reqd_start_val_is_pct=NULL,
	@update_inv=@update_inv,@backflush=@backflush,@def_reas_cd=@def_reas_cd,@def_lot_no=@def_lot_no,@def_sublot_no=@def_sublot_no,@def_storage_ent_id=@def_storage_ent_id,
	@def_reject_ent_id=@def_reject_ent_id,@scaling_factor=@scaling_factor,@must_consume_from_inv=@must_consume_from_inv,@may_choose_alt_inv_loc=@may_choose_alt_inv_loc,@may_create_new_lots=@may_create_new_lots,
	@must_consume_from_wip=@must_consume_from_wip,@must_consume_before_prod=@must_consume_before_prod,@constant_qty=@constant_qty,@est_time=@est_time,@current_subst=NULL,
	@qty_reqd=@qty_reqd,
	@serial_no_source=@serial_no_source,@spare1=@spare1,@spare2=@spare2,@spare3=@spare3,@spare4=@spare4,@last_edit_comment=@last_edit_comment,@mod_id=@p36 output
	--select @p36

	delete from #temptable where rows=@cnt
	select @row_cnt=COUNT(0) from  #temptable
	set @cnt=@cnt+1
	print @row_cnt
END

-- update intermediate material if operation is producing WIP
select @iswip = attr_value from oper_attr with(nolock) where  oper_id = @oper_id and attr_id in(select attr_id from attr with(nolock) where attr_desc = 'produce_wip')

--select top 1 @job_reqd_qty = qty_reqd,@target_sched_ent_id = target_sched_ent_id  from job with(nolock) where wo_id = @wo_id and oper_id = @oper_id and seq_no = @seq_no
	if(@iswip=1)
		begin
			update job_bom set item_id = @parent_item_id,qty_reqd =@job_reqd_qty,spare1 = @recipe_name where wo_id =@wo_id and oper_id =@oper_id and seq_no = @seq_no and bom_pos=0
		end
	else -- this part is to update reqd_qty to the job_bom position 0
		begin
			update job_bom set qty_reqd =@job_reqd_qty,spare1 = @recipe_name  where wo_id =@wo_id and oper_id =@oper_id and seq_no = @seq_no and bom_pos=0
		end
	-- Delete by products which are part of the SAP bom but produced in other operation or not part of the recipe.

	if exists(select item_id FROM  bom_item with(nolock) where parent_item_id=@parent_item_id and ver_id=@ver_id)
		begin
			delete FROM  job_bom where wo_id =@wo_id and oper_id =@oper_id and seq_no = @seq_no and item_id not in(select item_id FROM  bom_item where parent_item_id=@parent_item_id and ver_id=@ver_id )
		end

		------- updating the required qty in the job_bom 
		update job_bom set qty_reqd = Round((jb.qty_per_parent_item * job.qty_reqd), item.num_decimals)
		--def_lot_no = case when (select spare1 from wo with(nolock) where wo_id = jb.wo_id) is null then jb.wo_id else jb1.def_lot_no end 
		 from job_bom jb with(nolock)  inner join job with(nolock) on jb.wo_id = job.wo_id and jb.oper_id = job.oper_id and jb.seq_no = job.seq_no
		 inner join #jobBOMtemp jb1 on  jb.wo_id = jb1.wo_id and jb.oper_id = jb1.oper_id and jb1.seq_no = job.seq_no and jb1.item_id = jb.item_id
		inner join item with(nolock) on jb.item_id = item.item_id
		where jb.wo_id = @wo_id and jb.oper_id = @oper_id and jb.seq_no = @seq_no 

		--updating the def_lot number /** excluting opertion id **/

		update job_bom set 
		def_lot_no = case when (select spare1 from wo with(nolock) where wo_id = jb.wo_id) is null then jb.wo_id else jb1.def_lot_no end 
		 from job_bom jb with(nolock)  inner join job with(nolock) on jb.wo_id = job.wo_id and jb.oper_id = job.oper_id and jb.seq_no = job.seq_no
		inner join #jobBOMtemp jb1 on  jb.wo_id = jb1.wo_id and jb1.seq_no = job.seq_no and jb1.item_id = jb.item_id  --and jb.oper_id = jb1.oper_id 
