								/* Action items
									1. we need to get a list of all the possible values for req_track_no from SAP and create a reas_code for it
									2. fetch the required reas_cd for it.
									3. update  job_bom.def_Reas_cd where bom_pos=0
								*/
							else
								==> (do nothing)  
					else
						//this means it is production order
					    if (check if the ent_attr def_Reas_cd set for the assigned ent (job.target_Sched_ent_id)) yes==>
					    	then ==> update job_bom set def_Reas_cd=ent_attr.value(reas_Desc) where the bom_pos=0
						else
							==> (do nothing)
					end if
				*/
				--if exists(select 1 from ofi_wo_ext with(nolock) where wo_id =@wo_id and module = 'PO')
				--BEGIN
					declare @attr_id int,@it_grp nvarchar(80)
					select @attr_id=attr_id  from attr with(nolock) where attr_desc='itemgroup'

					select @req_track_no =  req_track_no,@it_grp=ia.attr_value from ofi_wo_ext oe with(nolock)
					inner join item_attr ia on ia.item_id=oe.item_id and ia.attr_id=@attr_id
					where wo_id =@wo_id-- req_track_no is  item grade
					if(@req_track_no is not null)
					begin -- @req_track_no has to configure as grade and reason description
							-- reas_grp_id - production reasons
						select  @def_reas_cd_ent = reas_cd from item_reas with(nolock) 
						where reas_grp_id = 0 and  item_grade_cd = (select  item_grade_cd from item_grade 
						where item_grade_desc=@it_grp+' - '+@req_track_no )
						and item_status_cd = (select item_status_cd from item_state with(nolock) where item_status_desc ='UNRESTRICTED' ) 
						update job_bom set def_reas_cd = @def_reas_cd_ent  where wo_id =@wo_id and oper_id =@oper_id
						and seq_no = @seq_no and bom_pos=0
						
					end
					else
					begin
						 select @def_reas_desc_ent = attr_value from ent_attr with(nolock) 
						 where ent_id = @target_sched_ent_id and attr_id =  (select attr_id from attr with(nolock) 
						 where attr_desc = 'def_reas_cd' )
						 
						 if(@def_reas_desc_ent is not null) -- configured grade and reas_desc is same
						 begin

						 --  select top 1 @reqd_grade_cd = item_grade_cd from item_grade with(nolock) where item_grade_desc = @def_reas_desc_ent -- this is item_grade which we are mapping in the entity level
					
						 --  select  @def_reas_cd_ent = reas_cd from item_reas with(nolock) where reas_grp_id = 0 and  reas_desc = @def_reas_desc_ent and item_status_cd = (select item_status_cd from item_state with(nolock) where item_status_desc ='UNRESTRICTED' ) 
							--
