--===========================================================================================
-- Name:		sp_I_ofi_ImportParamRecipe
-- Description:	The stored procedure will import parameter from the spec table 
--	
-- Usage:		ImportParamRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-05			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- 0.03		SN				2022-12-14			Devops bug # 300, 303
-- 0.04.00	YG				2022-12-20			Added Display Seq
-- 0.05.00  YG				2023-05-04			Added Spare2 as the gropu id
--											    Delete old data which has no spare2
-- 0.07.00	AP				2023-05-03			Added the audit trail comment with @recipe_name 
-- 0.08.00	YG				2024-01-24			Update based on best practice audit
-- ===========================================================================================
CREATE Procedure [dbo].[sp_I_ofi_ImportParamRecipe]
		@recipe_name NVARCHAR(80) = NULL,
		@item_id NVARCHAR(40) = NULL,
		@parameter_group NVARCHAR(80) = NULL,
		@user_name NVARCHAR(40) = NULL,
		@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail
AS
BEGIN
	DECLARE	@iRowId INT,
			@SpecId NVARCHAR(80),
			@grp_id NVARCHAR(80),
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MRM_ParamRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'add',
			@strCommentMsg NVARCHAR(200) = 'Recipe:'+@recipe_name+' created From [dbo].[sp_I_ofi_ImportParamRecipe]',-- 0.07.00
			--0.03
			@minValue FLOAT,
			@maxValue FLOAT,
			@targetValue FLOAT,
			@displaySeq INT
	
	--debugger 
	--SELECT @recipe_name=N'BreakingWinnowing_S-500000041590-10',@item_id=N'500000041590',@parameter_group=N'BnW-SNIB',@user_name=N'Yoga Sapta Satriawan',@audit_trail=1
	
	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	IF EXISTS(SELECT * FROM ofi_master_recipe_parameter WITH (NOLOCK) WHERE spare2 is NULL and recipe_name = @recipe_name and item_id = @item_id)
	BEGIN
		-- Delete old data which has no spare2
		-- spare2 will be fill with the spec group
		DELETE FROM ofi_master_recipe_parameter WHERE spare2 is NULL and recipe_name = @recipe_name and item_id = @item_id
	END

	-- Set cursor to insert parameter recipe 
	DECLARE cursor_spec CURSOR
	FOR SELECT 
			spec_id, grp_id, spare1, spare2, spare3, display_seq --0.03 --0.05 add targetvalue
		FROM 
			spec WITH (NOLOCK)
		WHERE 
			grp_id = @parameter_group
		ORDER BY display_seq ASC

	OPEN cursor_spec;

	FETCH NEXT FROM cursor_spec INTO 
		@SpecId, @grp_id ,@minValue, @maxValue, @targetValue, @displaySeq --0.05 add targetvalue

	WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @targetValue = ISNULL(@targetValue,0.00);
			PRINT @targetValue
			-- Insert or update parameter recipe
			-- If parameter recipe is already available then will 
			EXEC [dbo].[sp_IU_ofi_AddParamRecipe] 
				@recipe_name = @recipe_name,
				@item_id = @item_id,
				@spec_id  = @SpecId,
				--@spec_value  = 0.00, -- Set default value as 0.00 commented on v 0.05 since will take value from spare3 global param
				--@min_value  = 0.00,  -- Set default value as 0.00 commented to get the min and max value from the global param
				--@max_value  = 0.00,  -- Set default value as 0.00
				@spec_group = @grp_id,
				@spec_value = @targetValue, -- 0.05 to get the spec value from the global param
				@min_value  = @minValue,  -- 0.03 to get the min value from the global param
				@max_value  = @maxValue,  -- 0.03 to get the max value from the global param
				@product_dependent  = 'N', -- Set default value as N
				@comments  = NULL,
				@display_seq = @displaySeq,
				@user_name  = @user_name,
				@row_id = @iRowId OUTPUT
			
			-- Insert entry in Audit Trial starts
			-- Validation: only items are new may create the audit trail
			
			IF NOT(@iRowId IS NULL)
			BEGIN
				IF (@audit_trail = 1)
				BEGIN
					-- Save audit trail 
					DELETE @auditTrailParameters;
					INSERT INTO @auditTrailParameters
					(
						row_id, 
						field_name, 
						field_value
					) 
					VALUES 
					(
						@iRowId, 
						'@SpecId', 
						@SpecId
					),
					(
						@iRowId, 
						'@SpecValue', 
						CAST(@targetValue as nvarchar(100))
					),
					(
						@iRowId, 
						'@MinValue', 
						CAST(@maxValue as nvarchar(100))
					),
					(
						@iRowId,
						'@MaxValue',
						CAST(@minValue as nvarchar(100))
					),
					(
						@iRowId,
						'@ProductDependent',
						'N'
					),
					(
						@iRowId,
						'@Notes',
						NULL
					)

					EXEC sp_I_ofi_AuditTrail 
						@module_id = @strModuleName,
						@function_id = @strFunctionName,
						@auditTrailParameters = @auditTrailParameters,
						@user_id = @user_name,
						@activity = @strActivityMsg,
						@audit_category = 'Info',
						@comments = @strCommentMsg,
						@keyField1 = @recipe_name,
						@keyField2 = @parameter_group
				END
				
			END
			
			FETCH NEXT FROM cursor_spec INTO 
				@SpecId, @grp_id, @minValue, @maxValue, @targetValue, @displaySeq --0.05 add targetvalue
		END;

	CLOSE cursor_spec;

	DEALLOCATE cursor_spec;
END

--===========================================================================================
-- Name:    SP_I_EI_Item
-- Description:  Inserts the item
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Sk          2022-07-12      Initial version.
-- 0.01.00  lk          2024-03-14      Added logic to insert classification value
-- ===========================================================================================
CREATE   PROCEDURE [dbo].[SP_I_EI_MM] (@item_id       NVARCHAR(40),
                                      @item_desc     NVARCHAR(80),
                                      @uom_desc      NVARCHAR(40),
                                      @lifetime      INT,
                                      @lifetime_unit NVARCHAR(1),
                                      @item_status   NVARCHAR(40),
                                      @item_class_desc NVARCHAR(40),
                                      @spare1        NVARCHAR(200),
                                      @spare2        NVARCHAR(200),
                                      @spare3        NVARCHAR(200),
                                      @spare4        NVARCHAR(200))
AS
  BEGIN
 
	  IF (dbo.fn_s_ofi_plantcode()= @spare1)
	  BEGIN
			  DECLARE @num_decimals   INT=7,
					  @obsolete       INT=0,
					  @rc             INT,
					  @uom_id         INT,
					  @error_msg      NVARCHAR(500),
					  @error_severity INT,
					  @error_state    INT,
					  @item_class_id NVARCHAR(40),
					  @mod_id         VARCHAR(30),
					  @attr_id2       INT=NULL

			  IF @item_status = 'Deleted'
				BEGIN
					SET @obsolete=1
				END

			  SET @lifetime= CASE
							   WHEN @lifetime_unit = 'D' THEN @lifetime
							   WHEN @lifetime_unit = 'M' THEN @lifetime * 30
							   WHEN @lifetime_unit = 'Y' THEN @lifetime * 365
							   ELSE @lifetime
							 END

			  BEGIN try
				  BEGIN TRANSACTION
				  
				  IF NOT EXISTS (SELECT TOP 1 1
								 FROM   uom WITH (nolock)
								 WHERE  description = @uom_desc)
					BEGIN
						EXECUTE @rc = [dbo].[Sp_i_uom]
						  @description = @uom_desc,
						  @abbreviation = @uom_desc,
						  @last_edit_comment = N'ADDED BY EI',
						  @uom_id = @uom_id output,
						  @last_edit_at = NULL

						IF ( @rc <> 0 )
						  BEGIN
							  SET @error_msg = N'Error while creating UOM (' + @uom_desc
											   + ') in MES  - SP_I_EI_ITEM -  '
											   + CONVERT(NVARCHAR(16), @rc);

							  THROW 51009, @error_msg, 1
						  END
					END
				  ELSE
					BEGIN
						SELECT @uom_id = uom_id
						FROM   uom WITH (nolock)
						WHERE  description = @uom_desc
					END

				  IF NOT EXISTS (SELECT TOP 1 1
								 FROM   item_class WITH (nolock)
								 WHERE  item_class_desc = @item_class_desc)
					BEGIN
						EXECUTE @rc = [dbo].[Sp_i_item_class]
						  @item_class_id = @item_class_desc,
						  @item_class_desc = @item_class_desc,
						  @produced = 1,
						  @consumed = 1,
						  @obsolete = 0,
						  @purchased = 0,
						  @sold = 0,
						  @lot_no_format = NULL,
						  @last_lot_no = NULL,
						  @sublot_no_format = NULL,
						  @last_sublot_no = NULL,
						  @serial_no_lvl = -1,
						  @inv_unique_by_job = 0,
						  @spare1 = NULL,
						  @spare2 = NULL,
						  @spare3 = NULL,
						  @spare4 = NULL,
						  @last_edit_comment = N'ADDED BY EI',
						  @last_edit_at = NULL

						IF ( @rc <> 0 )
						  BEGIN
							  SET @error_msg = N'Error while creating item class ('
											   + @item_class_desc
											   + ') in MES  - SP_I_EI_ITEM -  '
											   + CONVERT(NVARCHAR(16), @rc);

							  THROW 51009, @error_msg, 1
						  END
					END


				SELECT @item_class_id = item_class_id
				FROM   item_class WITH (nolock)
				WHERE  item_class_desc = @item_class_desc

				
				  EXECUTE @rc = [dbo].[Sp_i_item]
					@item_id = @item_id,
					@item_desc =@item_desc,
					@item_class_id = @item_class_id,
					@uom_id = @uom_id,
					@template = 0,
					@lifetime = @lifetime,
					@unit_cost = NULL,
					@obsolete = @obsolete,
					@purchased = 0,
					@sold = 0,
					@num_decimals = @num_decimals,
					@must_complete_steps = 0,
					@must_prod_reqd_qty = 0,
					@min_grade = NULL,
					@min_state = NULL,
					@min_inv_level = NULL,
					@reorder_amt = NULL,
					@auto_reorder = 0,
					@lot_no_format = NULL,
					@last_lot_no = NULL,
					@max_lot_size = NULL,
					@sublot_no_format = NULL,
					@last_sublot_no = NULL,
					@serial_no_lvl = -1,
					@max_sublot_size = NULL,
					@max_order_size = NULL,
					@min_trace_inv = NULL,
					@inv_unique_by_job = 0,
					@notes = NULL,
					@spare1 = 1,
					@spare2 = NULL,
					@spare3 = NULL,
					@spare4 = NULL,
					@last_edit_comment = N'ADDED BY EI',
					@last_edit_at = NULL
					
				  IF ( @rc <> 0 )
					BEGIN
						SET @error_msg = N'Error while creating item (' + @item_id
										 + ') in MES  - SP_I_EI_ITEM -  '
										 + CONVERT(NVARCHAR(16), @rc);
									
						THROW 51009, @error_msg, 1
					END

					 SELECT @attr_id2 = attr_id
					 FROM   attr a WITH (nolock)
					 WHERE  a.attr_desc = 'Classification'
                     AND a.attr_grp = 1
					 IF NOT EXISTS (SELECT TOP 1 1
                               FROM   item_attr WITH (nolock)
                               WHERE  item_id = @item_id
                                      AND attr_id = @attr_id2)
                  BEGIN
				  
                      EXEC @rc = [dbo].[Sp_i_item_attr]
                        @item_id = @item_id,
                        @attr_id = @attr_id2,
                        @attr_value = @spare4,
                        @notes = 'ADDED BY EI',
                        @last_edit_comment = NULL,
                        @mod_id = @mod_id output

                      IF ( @rc <> 0 )
                        BEGIN
                            SET @error_msg =
                            N'Error while creating item attribute ('
                            + @item_id
                            + ') in MES  - SP_I_EI_ITEM_ATTR -  '
                            + CONVERT(NVARCHAR(16), @rc);

                            THROW 51009, @error_msg, 1
                        END
                  END
					
				  COMMIT TRANSACTION
			  END try

			  BEGIN catch
				  IF @@TRANCOUNT > 0
					ROLLBACK TRANSACTION;

				  SELECT @error_msg = Error_message(),
						 @error_severity = Error_severity(),
						 @error_state = Error_state();

				  RAISERROR(@error_msg,@error_severity,@error_state)
			  END catch
		END
  END

--===========================================================================================
-- Name:		sp_U_ofi_EditBoMRecipe
-- Description:	The stored procedure will update the bom component that called from the WF
--	
-- Usage:		EditBoMRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-01			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- 0.03.00	YG				2022-12-20			Bug Fix : Skip checking the maximum ratio if new material added is non Main Material
-- 0.04.00	SM				2022-12-23			Bug Fix : If the quantity is zero then remove the record to avoid division by zero in the sp sp_BI_to_Job_BOM
-- 0.05.00  YG				2023-01-25			Added one attribute to skip sum recipe validation and considering uom when saving to the bom_item table
-- 0.06.00	AP				2023-05-03			Added the audit trail comment with @item_id and @recipe_version 
-- 0.07.00  YG				2024-02-09			Get Default UoM from Plant Level UoM
-- 0.08.00	YG				2024-03-21			Save audit trail qty based on percentage
-- 0.09.00	DS				2024-04-16			modified this sp and updated the grade cd in where clause to updating the BOM_ITem
-- 0.10.00  OT				2025-04-22			adding def_reas_cd to bom_item based on grade selected to component during recipe configuration 
-- ===========================================================================================

CREATE   Procedure [dbo].[sp_U_ofi_EditBoMRecipe] 
		@parent_item_id NVARCHAR(40) = NULL,
		@recipe_version INT = NULL,
		@item_id NVARCHAR(40) = NULL ,
		@qty nvarchar(10) = NULL,
		@max_qty nvarchar(10) = NULL,
		@min_qty nvarchar(10) = NULL,
		@grade_cd INT = NULL,
		@notes NVARCHAR(250) = NULL,
		@user_name NVARCHAR(100) = NULL,
		
	    @recipe_name NVARCHAR(40)= NULL,
		@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail

AS
BEGIN
	DECLARE @iBomPos INT,
			@Mod NVARCHAR(30),
			@iErrorValue INT,
			@fQty DECIMAL(16,8), 
			@fMinQty DECIMAL(16,8), 
			@fMaxQty DECIMAL(16,8),
			@fCurrentTtlQty DECIMAL(16,8),
			@iRecipeUsed INT = 0,
			@strRecipeVersion NVARCHAR(10),
			@iRowId INT,
			@strActive NVARCHAR(20),
		    @strByProduct NVARCHAR(10), 
			@strModuleName NVARCHAR(80) = 'MRM_BoMRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update',
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strCommentMsg NVARCHAR(200) = 'Item id:'+@item_id+' for version:'+CAST(@recipe_version AS varchar)+' recipe_name:'+@recipe_name+' updated From [dbo].[sp_U_ofi_EditBoMRecipe]',-- 0.06.00	
			@bIsMainMaterial INT = 0,
			@iIgnoreSumRecipeValue INT = 0,
			@strDefaultUoM NVARCHAR(10) = 'KG',
			@strItemUoM NVARCHAR(10),
			@defReasCd int

	-- v0.07.00 Get Default UoM from plant level
	Declare @Plant_Ent_Id Integer

	SELECT @Plant_Ent_Id = ent_id 
	FROM ent WITH (NOLOCK) 
	WHERE ent_id = (SELECT ent_id 
					FROM ent_attr WITH (NOLOCK) 
					WHERE attr_id = (SELECT attr_id 
									FROM attr WITH (NOLOCK) 
									WHERE attr_desc = 'EntityType' and attr_grp = 2) and attr_value = 'Site')

	SELECT @strDefaultUoM=attr_value FROM ent_attr WITH (NOLOCK) WHERE ent_id = @Plant_Ent_Id AND attr_id = (SELECT attr_id 
																											FROM attr WITH (NOLOCK) 
																											WHERE attr_desc = 'DefaultStorageUoM' and attr_grp = 2)

	
	-- Set default value if no value entered
	 IF (@audit_trail is NULL or @audit_trail = '')
	 BEGIN 
		SET @audit_trail = 1;
	 END

	-- Prepare the values
	SET @fQty = ROUND(@qty, 7)
	SET @fMinQty = ROUND(@min_qty, 7)
	SET @fMaxQty = ROUND(@max_qty, 7)

	----DS1234
	--select  FORMAT(@fMinQty, '0.########') 

	SET @strRecipeVersion = CONVERT(NVARCHAR(10), @recipe_version)

	-- Get information about requirement to ignore the 100% validation  
	 SELECT @iIgnoreSumRecipeValue = attr_value FROM ent_attr WITH (NOLOCK) 
	 WHERE ent_id = (SELECT ent_id FROM ofi_master_recipe WITH (NOLOCK) 
					 WHERE item_id = @parent_item_id and version = @recipe_version) 
		 AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) 
						WHERE attr_desc = 'IgnoreSumRecipeComponent')
						
	 SET @iIgnoreSumRecipeValue = ISNULL(@iIgnoreSumRecipeValue,0); 

	-- Interlock #1 - Check Mandatory Parameter 
	IF (@parent_item_id IS NULL OR @recipe_version IS NULL OR @item_id IS NULL)
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Parameters are not completed'
		RAISERROR ('@@MRBWFErrorParameterNotCompleted@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- Interlock #2 - Validate the maximum, and minimum quantity will be made sure it is Min <= Qty <= Max. 
	IF (NOT(@fQty >= @fMinQty AND @fQty <= @fMaxQty) AND NOT(@fQty = 0.0000))
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'the maximum, and minimum quantity are not valid'
		RAISERROR ('@@MRBWFErrorQtyNotValid@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- convert percentage qty into ration qty
	--SET @fQty = ROUND((@fQty / 100), 5)
	--SET @fMinQty = ROUND((@fMinQty / 100), 5)
	--SET @fMaxQty = ROUND((@fMaxQty / 100), 5)

	SET @fQty =    @fQty/100
	SET @fMinQty = @fMinQty/100
	SET @fMaxQty = @fMaxQty/100

	--DS1234
	--select  FORMAT(@fMinQty, '0.########') 

	
	SET @fQty = CASE WHEN @fQty = 0.00000 THEN 0.00001 ELSE @fQty END;
	SET @fMinQty = CASE WHEN @fMinQty = 0.00000 THEN 0.00001 ELSE @fMinQty END;
	SET @fMaxQty = CASE WHEN @fMaxQty = 0.00000 THEN 0.00002 ELSE @fMaxQty END;

	-- Interlock #3 Total BoM should not more than 1.00 / 100 %
	-- Assumed all item with bom_pos > 0 can be calculated
	SELECT
          @fCurrentTtlQty = ROUND(SUM(dbo.[fn_ofi_ConvertQtyByItemIdAndUom](bi.item_id,qty_per_parent_item,NULL,NULL,NULL,NULL,u.description,@strDefaultUoM)), 5)
     FROM bom_item bi WITH (NOLOCK)
	 INNER JOIN item i WITH (NOLOCK) ON bi.item_id = i.item_id
	 INNER JOIN uom u WITH (NOLOCK) ON i.uom_id = u.uom_id 
	 LEFT OUTER JOIN item_attr ia ON bi.item_id = ia.item_id and attr_id = (SELECT attr_id FROM attr WITH(NOLOCK) WHERE attr_desc = 'MaterialType' 
																													AND attr_grp = 1 )
     WHERE parent_item_id = @parent_item_id
		 AND attr_value = 'FERT'
		 AND ver_id = @recipe_version
		 AND bom_pos > 0
		 AND bi.item_id <> @item_id
		 AND (bi.spare2 = 'Active'
		 OR bi.spare2 IS NULL)

	SET @fCurrentTtlQty = ISNULL(@fCurrentTtlQty,NULL);

	-- Check Material is a Main Material
	SELECT @bIsMainMaterial = 1 FROM item_attr 
	WHERE item_id = @item_id 
		AND attr_id = (SELECT attr_id 
						FROM attr WITH(NOLOCK) 
						WHERE attr_desc = 'MaterialType' 
						AND attr_grp = 1)
		AND attr_value = 'FERT'

	IF (round((@fCurrentTtlQty + @fQty),3) > 1.0000 AND @bIsMainMaterial = 1 AND @iIgnoreSumRecipeValue=0) 
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Total BoM more than 1.00'
		RAISERROR ('@@MRBWFErrorTotalBoMQtyTooMuch@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- Retrieve data are needed for next execution
	--0.09.00  , Added Clause--> reqd_grade_cd = @grade_cd
	SELECT @iBomPos = bom_pos,
		@iRowId = row_id,
		@Mod = CONVERT(varchar(30), CONVERT(DECIMAL(19,4), CONVERT(MONEY, mod_id))),
		@strActive = spare2,
		@strByProduct = spare1
	FROM bom_item WITH (NOLOCK)
	WHERE parent_item_id = @parent_item_id
		AND ver_id = @recipe_version
		AND item_id = @item_id and reqd_grade_cd = @grade_cd AND spare2 = 'Active'

		
		-- 0.04.00  BS
		IF (@fQty = 0)
		BEGIN
			EXEC sp_D_Bom_Item @parent_item_id,@strRecipeVersion,@iBomPos,@Mod
		END
		ELSE
		BEGIN
		

		-- 0.04.00  BE
	SELECT @strItemUoM = description 
	FROM uom WITH (NOLOCK)
	WHERE uom_id = (SELECT uom_id FROM item WITH (NOLOCK) 
					WHERE item_id = @item_id)

		
	SELECT @fQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	SELECT @fMinQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fMinQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	SELECT @fMaxQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fMaxQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)

	-- Adding def_reas_cd based on recipe (grade in recipe) 
	-- 0.10.00
	IF @iBomPos < 0
	BEGIN
	SELECT TOP (1) @defReasCd = reas_cd FROM item_reas (NOLOCK) WHERE item_grade_cd = @grade_cd
	and reas_grp_id = (SELECT reas_grp_id FROM item_reas_grp (NOLOCK) WHERE reas_grp_type = 1)
	END
	
	--DS1234
	--select  FORMAT(@fMinQty, '0.########') 

	EXEC sp_U_Bom_Item 
		@parent_item_id = @parent_item_id,
		@ver_id = @strRecipeVersion,
		@bom_pos = @iBomPos, 
		@item_id = @item_id, 
		@reqd_grade_cd = @grade_cd, 
		@instruction = NULL,
		@qty_per_parent_item = @fQty,
		@max_qty_per_parent_item = @fMaxQty,
		@min_qty_per_parent_item = @fMinQty,
		@update_inv = 1 ,
		@backflush = 0,
		@def_reas_cd = @defReasCd,
		@def_lot_no = NULL,
		@def_sublot_no = NULL,
		@def_storage_ent_id = NULL,
		@def_reject_ent_id = NULL,
		@scaling_factor = 1,
		@must_consume_from_inv= 0,
		@may_choose_alt_inv_loc = 0,
		@may_create_new_lots = 1,
		@must_consume_from_wip = 0,
		@must_consume_before_prod = 0,
		@constant_qty = 0,
		@est_time = 0,
		@serial_no_source=0,
		@spare1=@strByProduct,
		@spare2=@strActive,
		@spare3=NULL,
		@spare4=NULL,
		@last_edit_comment=@notes,
		@mod_id= @Mod

		END;-- 0.04.00 

	-- Save the log
	IF (@audit_trail = 1)
	BEGIN
		-- Insert entry in Audit Trial starts
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES 
		(
			@iRowId, 
			'@ParentItemId', 
			@parent_item_id
		),
		(
			@iRowId, 
			'@Version', 
			CAST(@recipe_version AS NVARCHAR(40))
		),
		(
			@iRowId, 
			'@ItemId', 
			@item_id
		),
		(
			@iRowId,
			'@Qty',
			--CAST(@fQty AS NVARCHAR(40))
			CAST(CAST(ROUND(@qty,2) AS DECIMAL(18,2)) AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@MinQty',
			 CAST(CAST(ROUND(@min_qty,2) AS DECIMAL(18,2)) AS NVARCHAR(40))
			--CAST(@fMinQty AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@MaxQty',
			CAST(CAST(ROUND(@max_qty,2) AS DECIMAL(18,2)) AS NVARCHAR(40))
			--CAST(@fMaxQty AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@GradeCd',
			CAST(@grade_cd AS NVARCHAR(10))
		),
		(
			@iRowId,
			'@Notes',
			@notes
		),
		(
			@iRowId,
			'@Active',
			@strActive
		)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg
	END
END

--===========================================================================================
-- Name:		sp_U_ofi_EditBoMRecipe
-- Description:	The stored procedure will update the bom component that called from the WF
--	
-- Usage:		EditBoMRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-01			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- 0.03.00	YG				2022-12-20			Bug Fix : Skip checking the maximum ratio if new material added is non Main Material
-- 0.04.00	SM				2022-12-23			Bug Fix : If the quantity is zero then remove the record to avoid division by zero in the sp sp_BI_to_Job_BOM
-- 0.05.00  YG				2023-01-25			Added one attribute to skip sum recipe validation and considering uom when saving to the bom_item table
-- 0.06.00	AP				2023-05-03			Added the audit trail comment with @item_id and @recipe_version 
-- 0.07.00  YG				2024-02-09			Get Default UoM from Plant Level UoM
-- 0.08.00	YG				2024-03-21			Save audit trail qty based on percentage
-- 0.09.00	DS				2024-04-16			modified this sp and updated the grade cd in where clause to updating the BOM_ITem
-- ===========================================================================================

Create   Procedure [dbo].[sp_U_ofi_EditBoMRecipe_backup_04_22] 
		@parent_item_id NVARCHAR(40) = NULL,
		@recipe_version INT = NULL,
		@item_id NVARCHAR(40) = NULL ,
		@qty nvarchar(10) = NULL,
		@max_qty nvarchar(10) = NULL,
		@min_qty nvarchar(10) = NULL,
		@grade_cd INT = NULL,
		@notes NVARCHAR(250) = NULL,
		@user_name NVARCHAR(100) = NULL,
	
	    @recipe_name NVARCHAR(40)= NULL,
		@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail

AS
BEGIN
	DECLARE @iBomPos INT,
			@Mod NVARCHAR(30),
			@iErrorValue INT,
			@fQty DECIMAL(16,8), 
			@fMinQty DECIMAL(16,8), 
			@fMaxQty DECIMAL(16,8),
			@fCurrentTtlQty DECIMAL(16,8),
			@iRecipeUsed INT = 0,
			@strRecipeVersion NVARCHAR(10),
			@iRowId INT,
			@strActive NVARCHAR(20),
		    @strByProduct NVARCHAR(10), 
			@strModuleName NVARCHAR(80) = 'MRM_BoMRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update',
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strCommentMsg NVARCHAR(200) = 'Item id:'+@item_id+' for version:'+CAST(@recipe_version AS varchar)+' recipe_name:'+@recipe_name+' updated From [dbo].[sp_U_ofi_EditBoMRecipe]',-- 0.06.00	
			@bIsMainMaterial INT = 0,
			@iIgnoreSumRecipeValue INT = 0,
			@strDefaultUoM NVARCHAR(10) = 'KG',
			@strItemUoM NVARCHAR(10)

	-- v0.07.00 Get Default UoM from plant level
	Declare @Plant_Ent_Id Integer

	SELECT @Plant_Ent_Id = ent_id 
	FROM ent WITH (NOLOCK) 
	WHERE ent_id = (SELECT ent_id 
					FROM ent_attr WITH (NOLOCK) 
					WHERE attr_id = (SELECT attr_id 
									FROM attr WITH (NOLOCK) 
									WHERE attr_desc = 'EntityType' and attr_grp = 2) and attr_value = 'Site')

	SELECT @strDefaultUoM=attr_value FROM ent_attr WITH (NOLOCK) WHERE ent_id = @Plant_Ent_Id AND attr_id = (SELECT attr_id 
																											FROM attr WITH (NOLOCK) 
																											WHERE attr_desc = 'DefaultStorageUoM' and attr_grp = 2)

	-- Set default value if no value entered
	 IF (@audit_trail is NULL or @audit_trail = '')
	 BEGIN 
		SET @audit_trail = 1;
	 END

	-- Prepare the values
	SET @fQty = ROUND(@qty, 7)
	SET @fMinQty = ROUND(@min_qty, 7)
	SET @fMaxQty = ROUND(@max_qty, 7)

	----DS1234
	--select  FORMAT(@fMinQty, '0.########') 

	SET @strRecipeVersion = CONVERT(NVARCHAR(10), @recipe_version)

	-- Get information about requirement to ignore the 100% validation  
	 SELECT @iIgnoreSumRecipeValue = attr_value FROM ent_attr WITH (NOLOCK) 
	 WHERE ent_id = (SELECT ent_id FROM ofi_master_recipe WITH (NOLOCK) 
					 WHERE item_id = @parent_item_id and version = @recipe_version) 
		 AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) 
						WHERE attr_desc = 'IgnoreSumRecipeComponent')
						
	 SET @iIgnoreSumRecipeValue = ISNULL(@iIgnoreSumRecipeValue,0); 

	-- Interlock #1 - Check Mandatory Parameter 
	IF (@parent_item_id IS NULL OR @recipe_version IS NULL OR @item_id IS NULL)
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Parameters are not completed'
		RAISERROR ('@@MRBWFErrorParameterNotCompleted@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- Interlock #2 - Validate the maximum, and minimum quantity will be made sure it is Min <= Qty <= Max. 
	IF (NOT(@fQty >= @fMinQty AND @fQty <= @fMaxQty) AND NOT(@fQty = 0.0000))
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'the maximum, and minimum quantity are not valid'
		RAISERROR ('@@MRBWFErrorQtyNotValid@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- convert percentage qty into ration qty
	--SET @fQty = ROUND((@fQty / 100), 5)
	--SET @fMinQty = ROUND((@fMinQty / 100), 5)
	--SET @fMaxQty = ROUND((@fMaxQty / 100), 5)

	SET @fQty =    @fQty/100
	SET @fMinQty = @fMinQty/100
	SET @fMaxQty = @fMaxQty/100

	--DS1234
	--select  FORMAT(@fMinQty, '0.########') 

	
	SET @fQty = CASE WHEN @fQty = 0.00000 THEN 0.00001 ELSE @fQty END;
	SET @fMinQty = CASE WHEN @fMinQty = 0.00000 THEN 0.00001 ELSE @fMinQty END;
	SET @fMaxQty = CASE WHEN @fMaxQty = 0.00000 THEN 0.00002 ELSE @fMaxQty END;

	-- Interlock #3 Total BoM should not more than 1.00 / 100 %
	-- Assumed all item with bom_pos > 0 can be calculated
	SELECT
          @fCurrentTtlQty = ROUND(SUM(dbo.[fn_ofi_ConvertQtyByItemIdAndUom](bi.item_id,qty_per_parent_item,NULL,NULL,NULL,NULL,u.description,@strDefaultUoM)), 5)
     FROM bom_item bi WITH (NOLOCK)
	 INNER JOIN item i WITH (NOLOCK) ON bi.item_id = i.item_id
	 INNER JOIN uom u WITH (NOLOCK) ON i.uom_id = u.uom_id 
	 LEFT OUTER JOIN item_attr ia ON bi.item_id = ia.item_id and attr_id = (SELECT attr_id FROM attr WITH(NOLOCK) WHERE attr_desc = 'MaterialType' 
																													AND attr_grp = 1 )
     WHERE parent_item_id = @parent_item_id
		 AND attr_value = 'FERT'
		 AND ver_id = @recipe_version
		 AND bom_pos > 0
		 AND bi.item_id <> @item_id
		 AND (bi.spare2 = 'Active'
		 OR bi.spare2 IS NULL)

	SET @fCurrentTtlQty = ISNULL(@fCurrentTtlQty,NULL);

	-- Check Material is a Main Material
	SELECT @bIsMainMaterial = 1 FROM item_attr 
	WHERE item_id = @item_id 
		AND attr_id = (SELECT attr_id 
						FROM attr WITH(NOLOCK) 
						WHERE attr_desc = 'MaterialType' 
						AND attr_grp = 1)
		AND attr_value = 'FERT'

	IF (round((@fCurrentTtlQty + @fQty),3) > 1.0000 AND @bIsMainMaterial = 1 AND @iIgnoreSumRecipeValue=0) 
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Total BoM more than 1.00'
		RAISERROR ('@@MRBWFErrorTotalBoMQtyTooMuch@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- Retrieve data are needed for next execution
	--0.09.00  , Added Clause--> reqd_grade_cd = @grade_cd
	SELECT @iBomPos = bom_pos,
		@iRowId = row_id,
		@Mod = CONVERT(varchar(30), CONVERT(DECIMAL(19,4), CONVERT(MONEY, mod_id))),
		@strActive = spare2,
		@strByProduct = spare1
	FROM bom_item WITH (NOLOCK)
	WHERE parent_item_id = @parent_item_id
		AND ver_id = @recipe_version
		AND item_id = @item_id and reqd_grade_cd = @grade_cd AND spare2 = 'Active'

		
		-- 0.04.00  BS
		IF (@fQty = 0)
		BEGIN
			EXEC sp_D_Bom_Item @parent_item_id,@strRecipeVersion,@iBomPos,@Mod
		END
		ELSE
		BEGIN
		

		-- 0.04.00  BE
	SELECT @strItemUoM = description 
	FROM uom WITH (NOLOCK)
	WHERE uom_id = (SELECT uom_id FROM item WITH (NOLOCK) 
					WHERE item_id = @item_id)

		
	SELECT @fQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	SELECT @fMinQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fMinQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	SELECT @fMaxQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fMaxQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	
	--DS1234
	--select  FORMAT(@fMinQty, '0.########') 

	EXEC sp_U_Bom_Item 
		@parent_item_id = @parent_item_id,
		@ver_id = @strRecipeVersion,
		@bom_pos = @iBomPos, 
		@item_id = @item_id, 
		@reqd_grade_cd = @grade_cd, 
		@instruction = NULL,
		@qty_per_parent_item = @fQty,
		@max_qty_per_parent_item = @fMaxQty,
		@min_qty_per_parent_item = @fMinQty,
		@update_inv = 1 ,
		@backflush = 0,
		@def_reas_cd = NULL,
		@def_lot_no = NULL,
		@def_sublot_no = NULL,
		@def_storage_ent_id = NULL,
		@def_reject_ent_id = NULL,
		@scaling_factor = 1,
		@must_consume_from_inv= 0,
		@may_choose_alt_inv_loc = 0,
		@may_create_new_lots = 1,
		@must_consume_from_wip = 0,
		@must_consume_before_prod = 0,
		@constant_qty = 0,
		@est_time = 0,
		@serial_no_source=0,
		@spare1=@strByProduct,
		@spare2=@strActive,
		@spare3=NULL,
		@spare4=NULL,
		@last_edit_comment=@notes,
		@mod_id= @Mod

		END;-- 0.04.00 

	-- Save the log
	IF (@audit_trail = 1)
	BEGIN
		-- Insert entry in Audit Trial starts
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES 
		(
			@iRowId, 
			'@ParentItemId', 
			@parent_item_id
		),
		(
			@iRowId, 
			'@Version', 
			CAST(@recipe_version AS NVARCHAR(40))
		),
		(
			@iRowId, 
			'@ItemId', 
			@item_id
		),
		(
			@iRowId,
			'@Qty',
			--CAST(@fQty AS NVARCHAR(40))
			CAST(CAST(ROUND(@qty,2) AS DECIMAL(18,2)) AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@MinQty',
			 CAST(CAST(ROUND(@min_qty,2) AS DECIMAL(18,2)) AS NVARCHAR(40))
			--CAST(@fMinQty AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@MaxQty',
			CAST(CAST(ROUND(@max_qty,2) AS DECIMAL(18,2)) AS NVARCHAR(40))
			--CAST(@fMaxQty AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@GradeCd',
			CAST(@grade_cd AS NVARCHAR(10))
		),
		(
			@iRowId,
			'@Notes',
			@notes
		),
		(
			@iRowId,
			'@Active',
			@strActive
		)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg
	END
END

--===========================================================================================
-- Name:    sp_I_InsertJobStepDataForRecipe
-- Description:  The stored procedure will insert jobsteps for recipe
--  
-- Usage:    
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  SS        2022-12-09      This SP is for the inserting/updating the job step data. It is being used in the setup UI
-- ===========================================================================================
CREATE PROCEDURE [dbo].[sp_I_ofi_InsertJobStepDataForRecipe]
  -- Add the parameters for the stored procedure here
  @wo_id   NVARCHAR(50),
  @oper_id NVARCHAR(50),
  @seq_no  INT,
  @step_name nvarchar(50),
  @step_data nvarchar(max) 
AS
  BEGIN
      -- SET NOCOUNT ON added to prevent extra result sets from
      -- interfering with SELECT statements.
      SET nocount ON;

      -- Insert statements for procedure here
      
	  declare @stepno int
	  declare @time datetime=GETDATE()
	  DECLARE	@return_value int,
		@last_edit_at datetime,
		@row_id int
		--@step_data1 STRING254_NULL = NULL


      IF @step_name='Set Source'
        BEGIN
            SELECT @stepno=step_no
            FROM   job_step
            WHERE  wo_id = @wo_id
                   AND oper_id = @oper_id
                   AND seq_no = @seq_no
                   AND step_name = 'Set Source'
       
		if exists(select 1 from job_step_data with(nolock) where wo_id = @wo_id and  oper_id = @oper_id AND seq_no = @seq_no and step_no = @stepno )
			delete  job_step_data where wo_id = @wo_id and  oper_id = @oper_id AND seq_no = @seq_no and step_no = @stepno 
             
				if(@step_data is null)
				begin
						select  @step_data = STRING_AGG( ent.ent_name,',') 
							from ofi_su_selection oss with(nolock)
							inner join ent with(nolock)  on ent.ent_id =oss.su_ent_id
							where wo_id = @wo_id and dest_type = 1     
				end

				EXEC	@return_value = [dbo].[sp_I_Job_Step_Data]
						@wo_id =@wo_id,
						@oper_id =@oper_id,
						@seq_no = @seq_no,
						@step_no = @stepno,
						@lot_no = NULL,
