--===========================================================================================
-- Name:		sp_U_ofi_EditMasterRecipe
-- Description:	The stored procedure will update master recipe that called from the WF
--	
-- Usage:		EditMasterRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-07-15			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- 0.03.00  YG				2022-12-16			Resolve Issue : Able to set recipe active and preferred if no material available
-- 0.04.00  YG				2023-01-25			Added one attribute to skip sum recipe validation
-- 0.05.00	AP				2023-05-03			Added the audit trail comment with@recipe_name and @recipe_version
-- 0.06.00  AML, XPM		2026-05-20			CR617: Check if the recipe has been already used
-- 0.07.00	AML, XPM		2026-06-29			CR648: Setting a recipe as not preferred is now allowed in any case
-- ===========================================================================================

CREATE Procedure [dbo].[sp_U_ofi_EditMasterRecipe]
	@recipe_name NVARCHAR(80) = NULL,
	@item_id NVARCHAR(40) = NULL,
	@recipe_active NVARCHAR(1) = 'N',
	@recipe_preferred NVARCHAR(1) = 'N',
	@note NVARCHAR(250) = NULL,
	@user_name NVARCHAR(100) = NULL,
	@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail

AS 
BEGIN
	DECLARE @iErrorValue INT = 0,
			@strCurrentRecipePreferred NVARCHAR(1),
			@strCurrentRecipeActive NVARCHAR(1),
			@strAlreadyUsed NVARCHAR(1), -- CR617
			@bRecipePrefered BIT,
			@iRecipeId INT,
			@iRecipeVersion INT,
			@iEntId INT,
			@fTotalBoM FLOAT,
			@nRecipeName NVARCHAR(80),
			@mod NVARCHAR(30),
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MRM_MasterRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update',
			@strCommentMsg NVARCHAR(200) = 'updated From [dbo].[sp_U_ofi_EditMasterRecipe]',
			@iIgnoreSumRecipeValue INT = 0

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Get information about requirement to ignore the 100% validation  
	 SELECT @iIgnoreSumRecipeValue = attr_value FROM ent_attr WITH (NOLOCK) 
	 WHERE ent_id = (SELECT ent_id FROM ofi_master_recipe WITH (NOLOCK) 
					 WHERE item_id = @item_id and recipe_name = @recipe_name) 
		 AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) 
						WHERE attr_desc = 'IgnoreSumRecipeComponent')
						
	 SET @iIgnoreSumRecipeValue = ISNULL(@iIgnoreSumRecipeValue,0); 

	-- Retrieve datas used on update execution
	SELECT TOP 1 @iRecipeId = row_id, 
				@iRecipeVersion = version,
				@iEntId = ent_id,
				@strCurrentRecipePreferred = preferred,
				@strCurrentRecipeActive = is_active,
				@strAlreadyUsed = ISNULL(already_used, 'N') -- CR617
	FROM [dbo].ofi_master_recipe WITH (NOLOCK)
	WHERE recipe_name = @recipe_name
	SET @strCommentMsg ='Recipe:'+@recipe_name+' Version:'+ CAST(CAST(@iRecipeVersion AS INT)AS varchar)+' '+ @strCommentMsg-- 0.05.00
	-- Retrieve Total BoM Qty
	EXEC sp_S_ofi_GetTtlBoMQty 
		@parent_item_id = @item_id, 
		@version = @iRecipeVersion, 
		@material_type = 'FERT', 
		@total_bom_qty = @fTotalBoM OUTPUT

	-- v0.03.00 Fix Issue : Able to edit recipe if no material available
	SET @fTotalBoM = ISNULL(@fTotalBoM,0.00);


	-- Interlock #1 validate if recipe preferred value change to 'N'
	-- CR648 
	/*IF (@strCurrentRecipePreferred = 'Y' and @recipe_preferred = 'N') 
	BEGIN
		-- CR617
		IF (@strAlreadyUsed = 'Y')
		BEGIN
			SET @iErrorValue = -1;

			-- Set Error Message 'Recipe only allowed to change from not prefered into preferred. Reverse not allowed'
			RAISERROR ('@@MRWFErrorPreferredRecipeCantSetToInactive@@', -- Message text.  
				   16, -- Severity.  
				   1 -- State.  
				   );

			RETURN -1
		END
	END
	*/
	-- Interlock #2 validate recipe active and recipe preferred value are consistent
	IF (@recipe_preferred = 'Y' and @recipe_active = 'N')
	BEGIN
		SET @iErrorValue = -1;

		-- Set Error Message 'Recipe should be set in active if set as preferred recipe'
		RAISERROR ('@@MRWFErrorActiveandPreferredRecipeInconsistent@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN -1
	END

	IF (NOT(ROUND(@fTotalBoM,1) >= 100.0 AND ROUND(@fTotalBoM,2) <= 100.01) AND @iIgnoreSumRecipeValue=0) 
	BEGIN 
		IF (@strCurrentRecipeActive = 'N' and @recipe_active = 'Y')
		BEGIN
			SET @iErrorValue = -1;

			-- Set Error Message 'Recipe cannot be set into active because bom is not completed'
			RAISERROR ('@@MRWFErrorBoMRecipeNotCompleted@@', -- Message text.  
				   16, -- Severity.  
				   1 -- State.  
				   );
			   
			RETURN -1
		END
	END

	IF (@iErrorValue >= 0)
	BEGIN
		-- update other master recipe as not preferred  
		IF (@recipe_preferred = 'Y')
		BEGIN
			-- Validate if any current preferred recipe available then set into not preferred
			IF (EXISTS(	SELECT 1
						FROM ofi_master_recipe WITH (NOLOCK) 
						WHERE item_id = @item_id 
								AND ent_id = @iEntId
								AND preferred = 'Y'))
			BEGIN
				-- Get the current preferred recipe 
				SELECT @nRecipeName = recipe_name
				FROM ofi_master_recipe WITH (NOLOCK) 
				WHERE item_id = @item_id 
						AND ent_id = @iEntId
						AND preferred = 'Y'

				EXEC [dbo].[sp_U_ofi_UpdateRecipe] 
					@item_id = @item_id,
					@ent_id = @iEntId,
					@recipe_name = @nRecipeName,
					@recipe_preferred = 'N',
					@recipe_active = null,
					@audit_comments = 'Updated From [dbo].[sp_U_ofi_EditMasterRecipe]',
					@user_name = @user_name
			END

			SET @bRecipePrefered = 1 
		END
		ELSE 
		BEGIN
			SET @bRecipePrefered = 0
		END

		-- Update the master recipe table
		UPDATE [dbo].ofi_master_recipe
		SET 
			is_active = @recipe_active,
			preferred = @recipe_preferred,
			notes = @note,
			last_edit_at_utc = GETUTCDATE(),
			last_edit_at_local = GETDATE(),
			last_edit_by = @user_name
		WHERE 
			row_id = @iRecipeId

		-- Get Mod_ID
		SELECT @mod = CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
		FROM bom_ver WITH (NOLOCK)
		WHERE parent_item_id = @item_id AND ver_id = @iRecipeVersion

		-- Update the bom ver
		EXEC sp_U_Bom_Ver
			@parent_item_id = @item_id ,
			@ver_id = @iRecipeVersion,
			@ver_date = NULL ,
			@ver_date_tz =NULL ,
			@ver_comments = @note,
			@preferred_ver = @bRecipePrefered,
			@disassembly = 0,
			@start_eff = NULL,
			@start_eff_tz= NULL,
			@end_eff = NULL ,
			@end_eff_tz = NULL ,
			@last_edit_comment = 'Updated From MasterRecipeManagement-EditMasterRecipe Form' ,
			@mod_id = @mod ,
			@time_zone_bias_value= NULL

		IF (@audit_trail = 1)
		BEGIN
			-- Insert entry in Audit Trial starts
			DELETE @auditTrailParameters;
			INSERT INTO @auditTrailParameters
			(
				row_id, 
				field_name, 
				field_value
			) 
			VALUES
			(
				@iRecipeId,
				'@RecipeName',
				@recipe_name
			),
			(
				@iRecipeId,
				'@Preferred',
				@recipe_preferred
			),
			(
				@iRecipeId,
				'@Active',
				@recipe_active
			),
			(
				@iRecipeId,
				'@Notes',
				@note
			)

			EXEC sp_I_ofi_AuditTrail 
				@module_id = @strModuleName,
				@function_id = @strFunctionName,
				@auditTrailParameters = @auditTrailParameters,
				@user_id = @user_name,
				@activity = @strActivityMsg,
				@audit_category = 'Info',
				@comments = @strCommentMsg
		END

	END

END

