-- 0.01.01  kn			2023-07-20		Update logic to handle WIP items
-- 0.01.02	KN			2023-07-25		Added logic to handle WIP creation for FG items
-- 0.01.03	LK			2024-02-27		Modified the else logic for spare2
-- 0.01.04	MC			2025-10-08		Updated logic for Cake Blend WIP description to align with Update version
-- ===========================================================================================

CREATE   PROCEDURE [dbo].[SP_I_EI_MM_WIP_ITEM] (@item_id NVARCHAR(40),@item_class NVARCHAR(80),@item_group NVARCHAR(80)) AS
BEGIN
	DECLARE @item_desc VARCHAR(MAX), @is_wip BIT,@wip_item_id VARCHAR(MAX), @wip_name VARCHAR(MAX), @spare2 VARCHAR(MAX), @wip_class VARCHAR(MAX), @wip_desc VARCHAR(MAX), 
	@wip_item_grp VARCHAR(MAX), @rc INT, @attr_id INT,@mod_id VARCHAR(40), @uom_id INT, @lifetime INT, @obsolete BIT, @num_decimals INT,
	@error_msg  NVARCHAR(500), @error_severity INT, @error_state    INT,@item_class_id VARCHAR(100),
	@item_classification   NVARCHAR(80),                                           
    @plant_code            NVARCHAR(40),                                           
    @legacy_code           NVARCHAR(40),
    @item_status           NVARCHAR(40),  
	@material_state        NVARCHAR(40),
	@production_supervisor NVARCHAR(40)

	IF EXISTS (SELECT 1 FROM item WHERE item_id = @item_id)
	BEGIN

		--DO THE ENTIRE LOGIC ONLY FOR SFG ITEMS OR FOR ITEMS WITH ITEM GROUP EITHER AS COCOA LIQUOR OR CAKE
		
		IF -- 0.01.06 modify condition as there is no WIP for CAKE items
		((UPPER(@item_class) = UPPER('Semifinished Goods') OR UPPER(@item_class) = UPPER('Finshed Goods')) AND (UPPER(@item_group) = UPPER('Cocoa Liquor')))
		OR
		/*UPPER(@item_group) = UPPER('Cocoa Cake') OR*/
		(UPPER(@item_class) = UPPER('Semifinished Goods') AND (UPPER(@item_group) = UPPER('Cocoa Low Fat Powder') OR UPPER(@item_group) = UPPER('Cocoa Highfat Powder')))
		BEGIN		
			SELECT @item_desc = item_desc,@item_class_id = item_class_id FROM item with(nolock) WHERE item_id = @Item_id

			SET @spare2 = NULL
			SELECT @spare2 = spare2 FROM item_class with(nolock) WHERE item_class_id = @item_class or item_class_desc = @item_class

			SELECT @uom_id = uom_id,@lifetime = lifetime,@obsolete = obsolete,@num_decimals = num_decimals FROM item with(nolock) WHERE item_id = @item_id

			--CREATE A NEW WIP ITEM ID BASED ON THE INCOMING ITEM ID. THE REST OF THE ITEM DETAILS CAN BE REUSED

			IF @spare2 IS NULL
				SET @wip_item_id = CONCAT('50', substring(@Item_id, 3, len(@Item_id)))
			ELSE
				SET @wip_item_id = CONCAT(@spare2, substring(@Item_id, 3, len(@Item_id))) -- 0.01.03

			SELECT @wip_class = item_class_id FROM item_class WHERE item_class_desc = 'Intermediate Materials'

			SET @wip_desc = 'WIP '

			DECLARE @attr_desc varchar(100) = NULL

			SELECT @attr_desc = attr_value from item_attr with(nolock) where item_id = @Item_id and attr_id = (Select attr_id from attr where attr_desc = 'ItemGroup')		

			/*KN 25Jul23 Added below logic to handle WIP creation for FG process*/
			-- 0.01.04 moved wip_item_group selecting
			IF @item_class_id = 'FG'
				BEGIN
					IF @attr_desc LIKE '%liquor%'
					BEGIN
						SET @wip_desc = @wip_desc + '(LIQUOR BLEND) '
						SET @wip_item_grp = 'LIQUOR' --must be the same as liquor item group as is substitute for them
					END
					--ELSE IF @attr_desc LIKE '%butter%' SET @wip_desc = @wip_desc + '(BUTTER BLEND) ' -- 0.01.06 modify condition as there is no WIP for BUTTER items
				END
			ELSE IF @item_class_id = 'SFG'
			BEGIN
				IF @attr_desc LIKE '%powder%'
				BEGIN
					SET @wip_desc = @wip_desc + '(CAKE BLEND) '
					SET @wip_item_grp = 'CAKE BLEND'
				END
				ELSE IF @attr_desc LIKE '%liquor%'
				BEGIN
					SET @wip_desc = @wip_desc + '(NIBS) '
					SET @wip_item_grp = 'NIBS'
				END
						
			END
           
			SET @wip_desc = @wip_desc +   @item_desc
			SET @wip_name = @wip_desc

			BEGIN TRY
			BEGIN TRANSACTION

			--CREATE THE NEW WIP ITEM

				EXECUTE @rc = [dbo].[Sp_i_item]
						@item_id = @wip_item_id,
						@item_desc =@wip_desc,
						@item_class_id = @wip_class,
						@uom_id = @uom_id,
						@template = 0,
						@lifetime = @lifetime,
						@unit_cost = NULL,
						@obsolete = @obsolete,
						@purchased = 0,
						@sold = 0,
						@num_decimals = @num_decimals,
						@must_complete_steps = 0,
						@must_prod_reqd_qty = 0,
						@min_grade = NULL,
						@min_state = NULL,
						@min_inv_level = NULL,
						@reorder_amt = NULL,
						@auto_reorder = 0,
						@lot_no_format = NULL,
						@last_lot_no = NULL,
						@max_lot_size = NULL,
						@sublot_no_format = NULL,
						@last_sublot_no = NULL,
						@serial_no_lvl = -1,
						@max_sublot_size = NULL,
						@max_order_size = NULL,
						@min_trace_inv = NULL,
						@inv_unique_by_job = 0,
						@notes = NULL,
						@spare1 = 1,
						@spare2 = NULL,
						@spare3 = NULL,
						@spare4 = @item_id,
						@last_edit_comment = N'ADDED BY EI',
						@last_edit_at = NULL


				-- FOR THE NEWLY CREATED WIP ITEM, ADD ITEM GROUP ATTRIBUTE BASED ON WHAT ITEM GROUP IT BELONGS TO

				SELECT @attr_id = attr_id FROM attr WHERE attr_desc= 'ItemGroup' AND attr_grp = 1

				/*-- 0.01.04 - moved to wip_desc section
				IF @attr_desc LIKE '%powder%'
				   BEGIN
					SET @wip_item_grp = 'CAKE BLEND'
					END
				ELSE
					BEGIN
						IF @item_class_id = 'FG' 
						BEGIN
							SET @wip_item_grp = 'Liquor' 
						END						
						ELSE
						BEGIN
							SET @wip_item_grp = 'NIBS'
						END
					END
				*/
print @wip_item_grp
			/*	EXEC @rc = [dbo].[Sp_i_item_attr]
							@item_id = @wip_item_id,
							@attr_id = @attr_id,
							@attr_value = @wip_item_grp,
							@notes = 'ADDED BY EI',
							@last_edit_comment = NULL,
							@mod_id = @mod_id output*/

							select @item_classification,@plant_code,@legacy_code,@item_status,@material_state from item_attr ia with(nolock) inner join attr a with(nolock)
							on ia.attr_id=a.attr_id
							where item_id=@item_id

							DECLARE
							  @mainitemattr TABLE 
							  (
							   attr_desc nvarchar(40),
							   attr_value  nvarchar(40)
							  )
							 insert into @mainitemattr
								select a.attr_desc,ia.attr_value from item_attr ia with(nolock) inner join attr a with(nolock)
								on ia.attr_id=a.attr_id
								where item_id=@item_id order by a.attr_desc asc

								select @item_classification=attr_value from @mainitemattr where attr_desc='Classification'
								select @plant_code=attr_value from @mainitemattr where attr_desc='PlantCode'
								select @legacy_code=attr_value from @mainitemattr where attr_desc='LegacyCode'
								select @material_state=attr_value from @mainitemattr where attr_desc='MaterialType'
								select @production_supervisor=attr_value from @mainitemattr where attr_desc='ProductionSupervisor'
								
								

							  Exec [dbo].[SP_I_EI_MM_Attr] 
							  @item_id  = @wip_item_id,
                                           @item_group= @wip_item_grp,
                                           @item_classification =@item_classification,
                                           @language_key='EN',
                                           @plant_code   =@plant_code,
                                           @production_supervisor=@production_supervisor,
                                           @legacy_code  =@legacy_code,
                                           @item_status ='ACTIVE',
										   @material_state  =@material_state,
										   @production_method=null
				COMMIT

			END TRY
			BEGIN CATCH
				  IF @@TRANCOUNT > 0
					ROLLBACK TRANSACTION;

				  SELECT @error_msg = Error_message(),@error_severity = Error_severity(),@error_state = Error_state();
				  RAISERROR(@error_msg,@error_severity,@error_state)
			END CATCH

		END		
	END
END

-- =============================================
-- Name:    SP_I_ofi_Item_Cons_AddCons 
-- Description:  Add consumption
--
-- Usage:  
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  VJ            2022-10-17      Initial version.
-- 0.02.00  MP			  2023-01-30	  Added row_id input for [SP_SA_ofi_item_inv_typeOfCons]
-- 0.03.00	YG			  2023-03-14	  Added logic for consuming material has different grade with job bom
-- 0.04.00	YG			  2023-04-28	  Added logic for consuming material non bom
-- 0.05.00	DS			  2023-08-28	  #279, Added logic for liquor consumption based on ticket document
-- 0.06.00	DS			  2023-10-13	  #279_1, MOdified logic for liquor consumption if WIP material is already present in BOM pos=0
--										  System is checking whether triggered item is part of the BOM or not and based on that we have checked 2 conditions, selected silos item is part of the BOM or not
--										  #279_10 - Triggered item is BOM compenent or not
--										  #279_11 - selected silo componenet is matching with BOM component or not
--										  #279_13 - removed group @groupConsRows attribute from the liquor blending
-- 0.07.00	DS			  2023-10-27	  #279_14 - issue with getting inserted new rows in the item_cons table, fixed to restrict the insertion. used 
-- 0.08.00	DS			  2024-01-31	  Added inline comments 
-- 1.00.00	YG			  2024-04-29	  Added stopped WO also in the validation
-- 1.01.00	YG			  2024-05-13	  Added recorded timestamp
-- =============================================
-- EXEC SP_I_ofi_Item_Cons_AddCons '1003202202', 'Miller_02', 0, 100, 159,8, '1000101'
-- EXEC SP_I_ofi_Item_Cons_AddCons '123', 'BeanIntake', 0,100, 138,8, '1000101'
-- =============================================
CREATE PROCEDURE [dbo].[SP_I_ofi_Item_Cons_AddCons]
	 @wo_id NVARCHAR(40) 
	,@oper_id NVARCHAR(40) 
	,@seq_no INT 
	,@qty FLOAT 
	,@ent_id INT 
	,@aut_storage_id INT 
	,@item_id  NVARCHAR(40) = NULL 
	,@actual_cons_time TDATETIME = NULL -- V1.01.00 Added
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @storage_ent_id INT
			,@cons_lot_no NVARCHAR(40) = NULL
			,@cons_sublot_no NVARCHAR(40) = NULL
			,@cons_qty FLOAT = 0
			,@avl_qty FLOAT = 0
			--,@temp_qty FLOAT = 0
			,@consumed_qty FLOAT = 0
			,@job_pos INT = 0
			,@bom_pos INT = 0
			,@date_time_UTC TDATETIME =  @actual_cons_time--GETUTCDATE()
			,@return_value int
			,@row_id INT32
			,@minID INT
			,@typeOfCons NVARCHAR(20) = 'FIFO'
			,@process_id NVARCHAR(30)
			,@process_type NVARCHAR(30)
			,@prod_info NVARCHAR(4000)
			,@prod_item_id NVARCHAR(40)
			,@prod_date_time_UTC datetime
			,@reqd_grade_cd int
			,@reqd_status_cd int
			,@grade_cd int
			,@status_cd int
			,@is_bom_item int = 1 -- this supplied\trigger item from automation is a bom item or not
			,@is_siloItem_bom_item int = 1 -- is selected destination item a bom item or not 

			,@groupConsRows int
			,@ConsBiDirectionalSilo int
			,@IsBiDirectionalSiloExists int = 0
			,@isFirstCons int
			,@source_su_id int
			,@jb_item_id nvarchar(80)
			,@max_row_cnt int
			,@row_cnt int
			,@si_lot_no string40_null
			,@si_sublot_no string40_null
			,@si_grade_cd int32_null
			,@si_qty_left tfloat
			,@si_item_id string40_null
			,@si_status_cd int

			,@target_reqd_grade_cd int
			,@target_item_id nvarchar(80)
			,@target_lot_no nvarchar(80)
			,@user_id nvarchar(80) -- V1.01.00 Added
			,@tz_bias INT = 120 -- V1.01.00 Added
			,@cons_reas_cd INT -- V1.01.00 Added
			,@prod_reas_cd INT -- V1.01.00 Added
			--,@

			declare @silo_inv as table (row_id int identity(1,1),item_id nvarchar(80),lot_no string40_null, sublot_no string40_null,grade_cd int32_null,status_cd int32_null, qty_left tfloat)

	-- Set TZ offset 
	SELECT TOP 1 @tz_bias = ISNULL(offset,120) FROM tz_offset WITH (NOLOCK)
	WHERE @actual_cons_time BETWEEN start_utc AND end_utc
	AND region_id = 'W. Europe Standard Time'

	-- Get User Id -- V1.01.00 Added
	EXEC Sp_s_db_status_getaudtrailusr
		@user_id output, NULL
		
	-- Get Consumption Reason -- V1.01.00 Added
	SELECT @cons_reas_cd = reas_cd 
	FROM item_reas WITH (NOLOCK) 
	WHERE reas_desc = 'Good Consumption'
	
	-- Get Prod Reason -- V1.01.00 Added
	SELECT @prod_reas_cd = reas_cd 
	FROM item_reas WITH (NOLOCK) 
	WHERE reas_desc = 'Good Production'

	--GETS Required Data
	SELECT @storage_ent_id = ent_id
	FROM ent_attr ea WITH (NOLOCK)
	INNER JOIN attr a WITH (NOLOCK) ON ea.attr_id = a.attr_id
		AND a.attr_desc = 'SUNumberInAUT'
		AND a.attr_grp = 2
		AND ea.attr_value = Cast(@aut_storage_id AS NVARCHAR)

		--fetching the bom position & grade details from job_bom
	SELECT @bom_pos=bom_pos,@reqd_grade_cd = reqd_grade_cd FROM job_bom WITH (NOLOCK) WHERE  wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND item_id = @item_id
	
		--fetching the bom position & grade details from job_bom for target material
	SELECT @target_reqd_grade_cd = reqd_grade_cd,@target_item_id = item_id,@target_lot_no = def_lot_no FROM job_bom WITH (NOLOCK) WHERE  wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND bom_pos = 0

		----fetching the type of cons configuration from silo
	SELECT @typeOfCons = attr_value FROM ent_attr WITH (NOLOCK) WHERE ent_id = @storage_ent_id AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) WHERE attr_desc = 'TypeOfCons')

	select @process_id=process_id from wo with (nolock) where wo_id=@wo_id
	select @process_type = attr_value  from process_attr pa with (nolock)
	inner join attr a with (nolock) on pa.attr_id=a.attr_id
	where pa.process_id=@process_id and a.attr_desc='ProcessType'

	--CHECK WO Running Or Completed
	IF((SELECT state_cd FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no)=3)
	BEGIN
	PRINT('Consumption Against Running WO')
	SELECT @job_pos=job_pos FROM job_exec WITH (NOLOCK) WHERE cur_wo_id = @wo_id AND cur_oper_id = @oper_id AND cur_seq_no = @seq_no

	IF object_id('tempdb..#invlist1') is not null DROP TABLE #invlist1
	CREATE TABLE #invlist1(id INT  PRIMARY KEY, lot NVARCHAR(40) ,sublot NVARCHAR(40), qty FLOAT, cons_qty FLOAT,  consume_full BIT ,grade_cd INT, status_cd INT, row_id int)

	PRINT @storage_ent_id
	PRINT @cons_qty
	INSERT INTO #invlist1
	EXEC SP_SA_ofi_item_inv_typeOfCons @storage_ent_id, @item_id, @qty, @typeOfCons

	--AP: 23-fEB-23, Getting sublot number
		DECLARE @sublotTable TABLE (
	    sublot_counter INT,
		sublot_no NVARCHAR(40)
	)

	INSERT @sublotTable
	EXEC sp_S_ofi_Sublot @wo_id, @oper_id, @seq_no
	Declare @fg_Sublot_no nvarchar(40)
	select top 1 @fg_Sublot_no = sublot_no from @sublotTable

	--SELECT * FROM #invlist1
	SELECT @minID = MIN(id) FROM #invlist1 WHERE cons_qty >0
	WHILE (@minID IS NOT NULL )
	BEGIN
		SELECT @cons_qty = cons_qty, @cons_lot_no = lot, @cons_sublot_no= sublot, @grade_cd = grade_cd, @status_cd = status_cd FROM #invlist1 WHERE id = @minID
		PRINT 'Consume From:' + Convert( NVARCHAR(40) , @storage_ent_id) +' LOT:' +  @cons_lot_no + ' SLOT:' +  @cons_sublot_no + ' Qty:' + Convert( NVARCHAR(40) ,  @cons_qty)

		IF EXISTS(SELECT 1 FROM job_bom WITH (NOLOCK) where  wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND item_id = @item_id and bom_pos>0) -- #0.06
			SET @is_bom_item = 1
		ELSE
		BEGIN
			SET @is_bom_item = 0
		END

		
		SET @groupConsRows=0
		select @groupConsRows=attr_value from oper_attr oa with(nolock) 
		inner join attr a with(nolock) on oa.attr_id=a.attr_id and a.attr_desc='GroupConsRows'
		where oper_id=@oper_id

		--select @ConsBiDirectionalSilo=attr_value from oper_attr oa with(nolock) 
		--inner join attr a with(nolock) on oa.attr_id=a.attr_id and a.attr_desc='ConsBiDirectionalSilo'
		--where oper_id=@oper_id

		-- checking the biDirectional silo
		select @IsBiDirectionalSiloExists = count(*),@source_su_id = max(su_ent_id) from ofi_su_selection oss with(nolock) where oss.wo_id = @wo_id and oss.oper_id = @oper_id 
		and oss.seq_no = @seq_no and oss.dest_type = 2 
		and oss.su_ent_id in( 
		select oss.su_ent_id from ofi_su_selection oss with(nolock)
				inner join ent with(nolock) on oss.su_ent_id = ent.ent_id
				where oss.wo_id = @wo_id and oss.oper_id = @oper_id and oss.seq_no = @seq_no and oss.dest_type = 1 )
		
		
		IF EXISTS(SELECT 1 FROM job_bom WITH (NOLOCK) where  wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND bom_pos>0 and
			item_id = (select top 1 item_id from item_inv with(nolock) where ent_id = @source_su_id) ) -- #0.06
			SET @is_siloItem_bom_item = 1
		ELSE
		BEGIN
			SET @is_siloItem_bom_item = 0
		END

		select @isFirstCons = count(*) from item_cons with(nolock) where wo_id = @wo_id and oper_id = @oper_id and seq_no = @seq_no

		IF (@grade_cd = @reqd_grade_cd and @is_bom_item = 1) -- #279_10[trigger is item matching with BOM or not]
		BEGIN
			
				IF (@isFirstCons=0 and @IsBiDirectionalSiloExists = 1) -- when bidirectional silo exists and first consumption
				BEGIN

					--part 1
					select @jb_item_id = jb_item_id from ofi_su_selection oss with(nolock)
					where oss.wo_id = @wo_id and oss.oper_id = @oper_id and oss.seq_no = @seq_no and oss.dest_type = 1 and su_ent_id = @source_su_id
					
					insert @silo_inv 
					select item_id,lot_no,sublot_no,grade_cd,status_cd ,qty_left from item_inv with(nolock) where ent_id = @source_su_id
					
					--loop here
					select @max_row_cnt=max(row_id),@row_cnt = min(row_id) from  @silo_inv
					WHILE ((@row_cnt<=@max_row_cnt) and @row_cnt<>0)  -- this loop only execute in case of silo item is BOM item
						BEGIN

						select	@si_item_id = item_id,@si_lot_no =lot_no ,@si_sublot_no =sublot_no
								,@si_grade_cd =grade_cd ,@si_qty_left =qty_left,@si_status_cd = status_cd from @silo_inv where row_id = @row_cnt

						if(@is_siloItem_bom_item =1) -- #279_11 [silo item is matching with BOM or not] 
						begin
								
					-- consuming the silo items
								EXEC	@return_value = [dbo].[sp_I_Item_Cons_AddCons]
										@session_id = NULL,
										@event_time_local = NULL,
										@user_id = @user_id, -- V1.01.00 Added
										@ent_id = @ent_id,
										@job_pos = @job_pos,
										@bom_pos = @bom_pos,
										@qty_cons = @si_qty_left,
										@reas_cd = @cons_reas_cd,
										@lot_no = @si_lot_no,
									--	@fg_lot_no = @cons_lot_no,
										@fg_lot_no = @target_lot_no,  -- DS[18-Oct2023] uncommented fg_lot_number
										@sublot_no = @si_sublot_no,
										@fg_sublot_no = @fg_Sublot_no,
										@from_ent_id = @source_su_id,
										@item_id = @si_item_id,
										@ext_ref = NULL,
										@apply_scaling_factor = NULL,
										@genealogy_id = NULL,
										@upstream_event_id = NULL,
										@segment_requirement_id = NULL,
										@segment_response_id = NULL,
										@comments = NULL,
										@spare1 = NULL,
										@spare2 = NULL,
										@spare3 = NULL,
										@spare4 = NULL,
										@created_at_utc = @date_time_UTC, -- V1.01.00 Updated
										@row_id = @row_id OUTPUT

							end
							else  -- silo having the non bom material , need to consume in loop
							begin
									 EXEC	@return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
												@from_ent_id = @source_su_id
												,@item_id = @si_item_id
												,@lot_no = @si_lot_no
												,@sublot_no = @si_sublot_no
												,@qty_cons = @si_qty_left
												,@reas_cd =	@cons_reas_cd
												,@grade_cd = @si_grade_cd
												,@status_cd = @si_status_cd
												,@user_id = @user_id -- V1.01.00 Added
												,@wo_id = @wo_id
												,@oper_id = @oper_id
												,@seq_no = @seq_no
												,@shift_start_local = NULL
												--,@fg_lot_no = NULL
												,@fg_lot_no = @target_lot_no  -- DS[18-Oct2023] uncommented fg_lot_number
												,@fg_sublot_no = @fg_Sublot_no
												,@item_scrapped = 0
												,@ent_id = @ent_id
												,@shift_id = NULL
												,@qty_cons_erp = 0
												,@ext_ref = NULL
												,@transaction_type = 0
												,@genealogy_id = NULL
												,@upstream_event_id = NULL
												,@segment_requirement_id = NULL
												,@segment_response_id = NULL
												,@comments = NULL
												,@spare1 = NULL
												,@spare2 = NULL
												,@spare3 = NULL
												,@spare4 = NULL
												,@shift_start_utc = NULL
												,@time_zone_bias_value = NULL
												,@row_id=@row_id OUTPUT
							end

							-- producing the same amount in wip material here
								exec SP_I_OFI_ITEM_PROD_ADDPROD @session_id=-18, 
									 @event_time_local=NULL, 
									 @user_id=@user_id, 
									 @ent_id=@ent_id,  -- V1.01.00 Added
									 @job_pos=@job_pos, 
									 @qty_prod=@si_qty_left, 
									 @reas_cd=@target_reqd_grade_cd, 
									 @lot_no=@target_lot_no, 
									 @sublot_no=@fg_Sublot_no, 
									 @to_ent_id=@source_su_id,   -- this will the the bidirectional silo
									 @item_id=@target_item_id, 
									 @byproduct_bom_pos=0, 
									 @ext_ref=NULL, 
									 @apply_scaling_factor=NULL, 
									 @genealogy_id=NULL, 
									 @event_id=NULL, 
									 @segment_requirement_id=NULL, 
									 @segment_response_id=NULL, 
									 @comments=NULL, 
									 @spare1=NULL, 
									 @spare2=NULL, 
									 @spare3=NULL, 
									 @spare4=NULL, 
									 @check_privs=NULL, 
									 @created_at_utc=@date_time_UTC,   -- V1.01.00 Updated
									 @time_zone_bias_value=@tz_bias, 
									 @row_id = @row_id OUTPUT  , 
									 @prod_info = @prod_info output

						set @row_cnt = @row_cnt+1
					END

					--part-2
					-- again execute the same sp for recording the consumption from other silo
								EXEC	@return_value = [dbo].[sp_I_Item_Cons_AddCons]
																@session_id = NULL,
																@event_time_local = NULL,
																@user_id = @user_id, -- V1.01.00 Added
																@ent_id = @ent_id,
																@job_pos = @job_pos,
																@bom_pos = @bom_pos,
																@qty_cons = @cons_qty,
