--===========================================================================================
-- Name:		sp_U_ofi_EditMaterialMaster
-- Description:	The stored procedure will update material master that called from the WF
--				Only material created by MES can be updated
--	
-- Usage:		EditMaterialMaster
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-15			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- 0.03.00	YG				2022-12-16			Bug Fix #492 UOM is not saving into db while edit item 
-- ===========================================================================================
CREATE Procedure [dbo].[sp_U_ofi_EditMaterialMaster]
 (	@item_id NVARCHAR(40) = NULL,
	@item_desc NVARCHAR(80) = NULL,
	@item_class_id NVARCHAR(40)= NULL,
	@uom_id INT= NULL,
	@num_decimals INT= NULL,
	@template_name NVARCHAR(40)= NULL,
	@user_name NVARCHAR(40)= NULL,
	@audit_trail BIT = 1, -- 1=Save to audit trail 0=Not Save to Audit Trail
	@row_id INT OUT	)
AS
BEGIN
	DECLARE @return_value INT,
			@last_edit_at DATETIME,
			@iItemGroupAttrId INT,
			@strItemGroupAttrDesc NVARCHAR(80) = 'ItemGroup',
			@mod_id NVARCHAR(30),
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MM_Item',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update',
			@strCommentMsg NVARCHAR(200) = 'Created From [dbo].[sp_U_ofi_EditMaterialMaster]',
			@csrItemGroup NVARCHAR(40),
			@csrAttrId INT,
			@csrDefValue NVARCHAR(100)

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Get attribute id for ItemGroup
	SELECT @iItemGroupAttrId = attr_id
	FROM attr WITH (NOLOCK)
	WHERE attr_desc = @strItemGroupAttrDesc
		AND attr_grp = 1

	-- Get row id for the material
	SELECT @row_id = row_id 
	FROM item WITH (NOLOCK)
	WHERE item_id = @item_id

	-- Update material in the item table
	UPDATE item SET
		item_desc = @item_desc,
		item_class_id = @item_class_id,
		uom_id = @uom_id,
		num_decimals = @num_decimals,
		last_edit_comment = 'UPDATED BY MES UI',
		last_edit_at = GETUTCDATE()
	WHERE 
		item_id = @item_id

	-- Get Mod_ID
	SELECT @mod_id = CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
	FROM item_attr WITH (NOLOCK)
	WHERE item_id = @item_id AND attr_id = @iItemGroupAttrId


	IF ((SELECT attr_value FROM item_attr WITH (NOLOCK)
		WHERE item_id = @item_id AND attr_id = @iItemGroupAttrId) <> @template_name)
	BEGIN
		-- Delete the item attribute and reinserting
		DELETE item_attr WHERE item_id = @item_id

		DECLARE @masterAttrTable TABLE (
			attr_id INT,
			def_value NVARCHAR(100),
			item_group NVARCHAR(100)
		)

		INSERT @masterAttrTable
		SELECT attr_id, 
			def_value, 
			item_group 
		FROM ofi_master_attr WITH (NOLOCK)
		WHERE 
			item_group = @template_name

		-- Set cursor to insert attribute  
		DECLARE cursor_attr CURSOR
		FOR SELECT 
				attr_id,def_value, item_group 
			FROM 
				@masterAttrTable
			WHERE 
				item_group = @template_name

		OPEN cursor_attr;

		FETCH NEXT FROM cursor_attr INTO 
			@csrAttrId, @csrDefValue, @csrItemGroup

		WHILE @@FETCH_STATUS = 0
		BEGIN
			-- Insert Item Attribute in the item_attr table
			EXEC sp_I_Item_Attr 
				@item_id = @item_id, 
				@attr_id = @csrAttrId, 
				@attr_value = @csrDefValue, 
				@notes = NULL, 
				@last_edit_comment = 'UPDATED BY MES UI', 
				@mod_id = @mod_id OUTPUT
		
			FETCH NEXT FROM cursor_attr INTO 
						@csrAttrId, @csrDefValue, @csrItemGroup
		END

		CLOSE cursor_attr;

		DEALLOCATE cursor_attr;
	END

	IF (@audit_trail = 1)
	BEGIN
		-- Insert entry in Audit Trial starts
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES 
		(
			@row_id, 
			'@ItemId', 
			@item_id
		),
		(
			@row_id, 
			'@ItemDesc', 
			@item_desc
		),
		(
			@row_id, 
			'@ItemClassId', 
			@item_class_id
		),
		(
			@row_id,
			'@UoM',
			CAST(@uom_id AS NVARCHAR(40))
		),
		(
			@row_id,
			'@NumDecimals',
			CAST(@num_decimals AS NVARCHAR(40))
		),
		(
			@row_id,
			'@TemplateName',
			CAST(@template_name AS NVARCHAR(40))
		)
	
		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg
	END
END

