CREATE   PROCEDURE [dbo].[SP_I_EI_OBD] (@DocNoRefDoc VARCHAR(40),@delivery VARCHAR(40),@delivery_type VARCHAR(40),@plant_gds_date VARCHAR(40),@plant_gds_time VARCHAR(40),
@load_date VARCHAR(40),@load_time VARCHAR(40),@trans_date VARCHAR(40),@trans_time VARCHAR(40),@delivery_date VARCHAR(40),@delivery_time VARCHAR(40),@delivery_no VARCHAR(40),@delivery_item VARCHAR(40),@pick_date VARCHAR(40),
@pick_time VARCHAR(40),@ship_to_party VARCHAR(40),@batch VARCHAR(40),@ship_point VARCHAR(40),@item_id VARCHAR(40),@item_group VARCHAR(40),@plant_code VARCHAR(40),
@storage_location VARCHAR(40),@delivery_qty VARCHAR(40),@base_uom VARCHAR(40),@item_no_ref VARCHAR(40))
AS
BEGIN

DECLARE  @ErrorMessage  NVARCHAR(MAX),@ErrorSeverity INT,@ErrorState INT, @ErrMsg VARCHAR(MAX);
DECLARE @wo_id VARCHAR(MAX)

SET @wo_id = @DocNoRefDoc

BEGIN TRY

/*Begin Validations*/
BEGIN
	SET @ErrMsg = '';

		IF NOT EXISTS (SELECT 1 FROM WO with(nolock) WHERE wo_id = @wo_id)
			SET @ErrMsg = @ErrMsg + '[Invalid WO]'
		ELSE IF NOT EXISTS(SELECT TOP 1 1 FROM ofi_wo_ext with(nolock) WHERE wo_id = @wo_id AND item_id = @item_id)
			SET @ErrMsg = @ErrMsg + '[Invalid Item]'	


		IF(dbo.fn_S_ofi_PlantCode()<>@plant_code)
			SET @ErrMsg = @ErrMsg + '[Invalid plant code] ' + @plant_code

		--IF EXISTS(SELECT 1 FROM ofi_wo_ext WHERE wo_id = @wo_id and status = 0)
		--	SET @ErrMsg = @ErrMsg + '[Invalid WO status. Must be 1 or NULL]'

	IF LEN(@ErrMsg) > 2 RAISERROR(@ErrMsg, 17, 1);
END
/*End Validations*/

END TRY

BEGIN CATCH
SELECT 
        @ErrorMessage = ERROR_MESSAGE(), 
        @ErrorSeverity = ERROR_SEVERITY(), 
        @ErrorState = ERROR_STATE();

    -- return the error inside the CATCH block
    RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);	
END CATCH
END

--===========================================================================================
-- Name:		[sp_U_ofi_EditMaterialTemplate]
-- Description:	The stored procedure will update record to the material template table
-- Usage:		EditMaterialTemplate
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-12			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- ===========================================================================================
CREATE Procedure [dbo].[sp_U_ofi_EditMaterialTemplate]
	@template_name NVARCHAR(40) = NULL,
	@attr_id INT = NULL,
	@default_value NVARCHAR(50) = NULL,
	@user_name NVARCHAR(40) = NULL,
	@audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail
AS
BEGIN
	DECLARE	@iRowId INT,
			@strAttrDesc NVARCHAR(80),
			@iDataType INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MM_Template',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update',
			@strCommentMsg NVARCHAR(200) = 'Created From [dbo].[sp_U_ofi_EditMaterialTemplate]'

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Retrive attribute name and attribute type
	SELECT @strAttrDesc = attr_desc,
		@iDataType = data_type
	FROM attr WITH (NOLOCK)
	WHERE attr_id = @attr_id
		AND attr_grp = 1

	SELECT @iRowId = row_id
	FROM [dbo].[ofi_master_attr]
	WHERE item_group = @template_name 
		AND attr_id = @attr_id
		AND (process_id IS NULL AND oper_id IS NULL)

	UPDATE [dbo].[ofi_master_attr]
	SET 
		def_value = @default_value,
		last_edit_at_local = GETDATE(),
		last_edit_at_utc = GETUTCDATE(),
		last_edit_by = @user_name
	WHERE
		row_id = @iRowId
		AND (process_id IS NULL AND oper_id IS NULL)

	IF (@audit_trail = 1)
	BEGIN
		-- Save to the audit trail log
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES
		(
			@iRowId, 
			'@DefValue', 
			@default_value
		)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg,
			@keyField1 = @strAttrDesc,
			@keyField2 = @iDataType
	END
END

