--===========================================================================================
-- Name:		sp_U_ofi_EditParamRecipe
-- Description:	The stored procedure will update parameter recipe that called from the WF
--	
-- Usage:		EditParamRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-08-04			Initial version.
-- 0.02.00	YG				2022-10-25			Add flag for audit trail in the parameter
-- 0.03.00	AP				2023-05-03			Added the audit trail comment with @recipe_name 
-- ===========================================================================================
CREATE Procedure [dbo].[sp_U_ofi_EditParamRecipe]
		@recipe_name NVARCHAR(80) = NULL,
		@spec_id NVARCHAR(40) = NULL,
		@spec_value FLOAT = NULL,
		@min_value FLOAT = NULL,
		@max_value FLOAT = NULL,
		@product_dependent NVARCHAR(1) = NULL,
		@comments NVARCHAR(250) = NULL,
		@user_name NVARCHAR(40) = NULL,
		@audit_trail BIT = 1, -- 1=Save to audit trail 0=Not Save to Audit Trail
		@iRowId INT = NULL OUT
AS
BEGIN 
	SET NOCOUNT ON
	SET XACT_ABORT ON

	-- Declaration Variable
	DECLARE @item_id NVARCHAR(40) = NULL,
			@fSpecValue FLOAT,
			@fMinValue FLOAT,
			@fMaxValue FLOAT,
			@fMinEquipment FLOAT,
			@fMaxEquipment FLOAT,
			@iErrorValue INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MRM_ParamRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update',
			@strCommentMsg NVARCHAR(200) = 'Recipe:'+@recipe_name+' updated From [dbo].[sp_U_ofi_EditParamRecipe]'-- 0.03.00

	-- Set default value if no value entered
	IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
		SET @audit_trail = 1;
	END

	-- Prepare the values
	SET @fSpecValue = ROUND(@spec_value, 2)
	SET @fMinValue = ROUND(@min_value, 2)
	SET @fMaxValue = ROUND(@max_value, 2)

	-- Get the master data value defined for the equipment
	SELECT @fMinEquipment = spare1,
		   @fMaxEquipment = spare2
	FROM spec WITH (NOLOCK)
	WHERE spec_id = @spec_id

	-- Interlock #1 Mandatory Parameter should be available and provided by the form
	IF (@recipe_name IS NULL OR @spec_id IS NULL)
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'Parameters are not completed'
		RAISERROR ('@@MRPWFErrorParameterNotCompleted@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );

		RETURN @iErrorValue
	END

	-- Interlock #2 Validate whether Value is more than entity specification
	IF ((@fMaxValue > @fMaxEquipment) OR (@fMinValue < @fMinEquipment))
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message  'Value is more than entity specification'
		RAISERROR ('@@MRPWFErrorQtyOutofEquipSpec@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );

		RETURN @iErrorValue
	END

	-- Interlock #3 - Validate the maximum, and minimum quantity will be made sure it is Min <= Qty <= Max. 
	IF (NOT(@fSpecValue >= @fMinValue AND @fSpecValue <= @fMaxValue))
	BEGIN
		SET @iErrorValue = -1

		-- Set Error Message 'the maximum, and minimum quantity are not valid'
		RAISERROR ('@@MRPWFErrorQtyNotValid@@', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN @iErrorValue
	END

	-- Get Row Id
	SELECT @iRowId = omrp.row_id,
		   @item_id = omr.item_id
	FROM ofi_master_recipe_parameter omrp WITH (NOLOCK)
	INNER JOIN ofi_master_recipe omr WITH (NOLOCK) ON omrp.recipe_name = omr.recipe_name 
	WHERE omrp.recipe_name = @recipe_name
		AND omrp.spec_id = @spec_id

	-- Update the master recipe parameter
	UPDATE ofi_master_recipe_parameter
	SET spec_value=@fSpecValue,
		min_value=@fMinValue,
		max_value=@fMaxValue,
		product_dependent=@product_dependent,
		comments=@comments,
		last_edit_at_local=GETDATE(),
		last_edit_at_utc=GETUTCDATE(),
		last_edit_by=@user_name
	WHERE row_id = @iRowId

	IF (@audit_trail = 1)
	BEGIN
		-- Insert entry in Audit Trial starts
		DELETE @auditTrailParameters;
		INSERT INTO @auditTrailParameters
		(
			row_id, 
			field_name, 
			field_value
		) 
		VALUES
		(
			@iRowId, 
			'@SpecId', 
			@spec_id
		),
		(
			@iRowId,
			'@SpecValue',
			CAST(@fSpecValue AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@MinValue',
			CAST(@fMinValue AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@MaxValue',
			CAST(@fMaxValue AS NVARCHAR(40))
		),
		(
			@iRowId,
			'@ProductDependent',
			@product_dependent
		),
		(
			@iRowId,
			'@Notes',
			@comments
		)

		EXEC sp_I_ofi_AuditTrail 
			@module_id = @strModuleName,
			@function_id = @strFunctionName,
			@auditTrailParameters = @auditTrailParameters,
			@user_id = @user_name,
			@activity = @strActivityMsg,
			@audit_category = 'Info',
			@comments = @strCommentMsg,
			@keyField1   = @recipe_name,
			@keyField2   = @item_id
	END

	SELECT @iRowId
END

CREATE   PROCEDURE [dbo].[sp_I_Ofi_Item_Process_Link]
(@item_id    NVARCHAR(40),
@process_id NVARCHAR(40),
@item_pref  INT,
@status     INT,
@last_edit_comment nvarchar(254) ,
@mod_id     VARCHAR(30) OUT
)
AS
--- ***********************************************************************************************************************
-- Module Name	      - SP_I_OFI_ITEM_PROCESS_LINK
-- Description	      - Insert into bom item table
-- Author	      -	Lavkesh
-- Date Created	      - 04/26/2002
-- Version	      - 1.6.0.36
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified  Modified_By   Version		Changes

----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE
  @V_Ver_Id			STRING40,
  @V_Oper			STRING40,
  @V_Qty_Per_Parent_Item	TFLOAT,
  @V_Count			INT,
  @V_Status			CHAR(1),
  @V_Reqd_Start_Pct		TFLOAT_NULL,
  @V_StepNo			INT32,
  @last_edit_by			NVARCHAR(40),
  @last_edit_at			DATETIME,
  @def_reas_cd			INT32,
  @def_storage_ent_id		INT32,
  @def_reject_ent_id		INT32,
  @update_inv			LOGICAL,
  @backflush			LOGICAL,
  @def_lot_no			STRING80,
  @def_sublot_no		STRING80, -- added 1/10/07 KRF
  @must_consume_from_inv	LOGICAL,
  @may_choose_alt_inv_loc	LOGICAL,
  @may_create_new_lots		LOGICAL,
  @must_consume_from_wip	LOGICAL,
  @must_consume_before_prod	LOGICAL,
  @constant_qty			LOGICAL,
  @has_anc_or_desc			LOGICAL,
  @error_msg				NVARCHAR(500)

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

BEGIN

  -- Check to see if the item belongs to any BOMs where the ancestor or descendants of the item are being made by the
  -- process.  If there are any, raise an error.
	;
	WITH
	bom_ancestor AS (
		SELECT parent_item_id FROM bom_item WITH(NOLOCK) WHERE item_id = @item_id AND bom_pos <> 0

		UNION ALL

		SELECT bi.parent_item_id FROM bom_item bi WITH(NOLOCK)
		JOIN bom_ancestor ba ON bi.item_id = ba.parent_item_id AND bom_pos <> 0
		WHERE item_id = @item_id
	),

	bom_descendant AS (
		SELECT item_id FROM bom_item WITH(NOLOCK) WHERE parent_item_id = @item_id AND bom_pos <> 0

		UNION ALL

		SELECT bi.item_id FROM bom_item bi WITH(NOLOCK)
		JOIN bom_descendant bd ON bi.parent_item_id = bd.item_id AND bi.bom_pos <> 0

	)

	SELECT TOP 1 @has_anc_or_desc = 1
	FROM item_process_link ipl WITH(NOLOCK)
	LEFT JOIN bom_ancestor ba ON ipl.item_id = ba.parent_item_id
	LEFT JOIN bom_descendant bd ON bd.item_id = ipl.item_id
	WHERE ipl.process_id = @process_id AND (ba.parent_item_id IS NOT NULL OR bd.item_id IS NOT NULL)

	IF @has_anc_or_desc = 1 BEGIN
		SET @error_msg = 'The item (%1) cannot be made by the process (%2) as the item belongs to at least one BOM where an ancestor or descendant of the item is being made by the process.<7988>,' + @item_id + ',' + @process_id
		RAISERROR(@error_msg, 16, 1)
		RETURN
	END



  IF @item_pref IS NULL OR @item_pref = 0
    SET @item_pref = 1

--  IF @status is NULL
--    SET @status = 2
  --Get the status from the process
  SELECT @status = process_status FROM process WITH (NOLOCK) WHERE process_id = @process_id

  INSERT INTO item_process_link (item_id, process_id, item_pref,status, last_edit_comment, last_edit_by, last_edit_at)
	VALUES(@item_id, @process_id, @item_pref,@status, @last_edit_comment, @last_edit_by, @last_edit_at)

	SELECT @V_Oper = oper_id FROM oper WITH (NOLOCK) WHERE process_id = @process_id AND final_oper = 1
	IF @V_Oper IS NOT NULL
		EXEC sp_U_BOM_Item_Oper_Link_ChPrIt @process_id=@process_id, @oper_id=@V_Oper, @old_item_id=null, @old_ver_id=null, @new_item_id=@item_id, @new_ver_id=null

  -- Return timestamp
  SELECT @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id))) FROM item_process_link with(nolock)
                   WHERE (item_id = @item_id AND process_id = @process_id)
END

