						   [packing_print_line7],
						   [packing_print_line8],
						   [packing_print_line9],
						   [packing_print_line10],
						   [packing_print_line11],
						   [packing_print_line12],
						   [packing_print_line13],
						   [prodn_method],-- (KN 13-Mar-23 - Added this column extra as requested by SAP)
						   [material_state],-- (KN 13-Mar-23 - Added this column extra as requested by SAP)
						   [order_type],-- (KN 13-Mar-23 - Added this column extra as requested by SAP)
						   [comments],
						   [status],
						   [spare1],
