--===========================================================================================
-- Name:    SP_I_EI_PRO_Create_BOM
-- Description:  Updates BOM to the existing work order if SAP recipe to be used
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Sk          2022-07-27        Initial version.
-- 0.01.01  MC			2024-03-28		  Do not modify BOM for job in status > 2 (after running)
-- ===========================================================================================
CREATE   PROCEDURE [dbo].[SP_I_EI_PRO_Create_BOM] (@module        NVARCHAR(40),
                                                @plant_code    NVARCHAR(40),
                                                @wo_id         NVARCHAR(40),
                                                @erp_wo_status NVARCHAR(40),
                                                @item_id       NVARCHAR(40),
                                                @spare1        NVARCHAR(200),
                                                @spare2        NVARCHAR(200),
                                                @spare3        NVARCHAR(200),
                                                @spare4        NVARCHAR(200))
AS
  BEGIN
      IF @erp_wo_status = 'ACTIVE'
         AND EXISTS(SELECT TOP 1 1 FROM wo WITH (nolock) WHERE  wo_id = @wo_id)
         AND EXISTS(SELECT TOP 1 1 FROM ofi_wo_ext WITH (nolock) WHERE  wo_id = @wo_id AND ( status = 1 OR status IS NULL ))
         AND EXISTS(SELECT TOP 1 1 FROM item_attr ia WITH (nolock)
                    INNER JOIN item i WITH (nolock) ON i.item_id = ia.item_id AND i.item_id = @item_id
                    INNER JOIN attr a WITH (nolock) ON a.attr_id = ia.attr_id AND a.attr_desc = 'RecipeToUse' AND a.attr_grp = 1 AND ia.attr_value = 'ERP')
        BEGIN
            DECLARE @rc                  INT,
                    @error_msg           NVARCHAR(500),
                    @error_severity      INT,
                    @error_state         INT,
                    @cur_jobs            CURSOR,
                    @cur_bom_item        CURSOR,
                    @oper_id             NVARCHAR(40),
                    @seq_no              INT,
                    @job_qty             FLOAT,
                    @bom_pos             INT,
                    @bom_item_id         NVARCHAR(40),
                    @bom_qty             FLOAT,
                    @backflush           BIT,
                    @def_lot_no          NVARCHAR(40),
                    @mod_id              VARCHAR(30),
                    @qty_per_parent_item FLOAT

            BEGIN try
                BEGIN TRANSACTION

				DECLARE @process_id VARCHAR(100)
				SELECT @process_id = process_id FROM wo WITH(nolock) WHERE wo_id = @wo_id

                SET @cur_jobs=CURSOR
                FOR SELECT oper_id,
                           seq_no,
                           qty_reqd
                    FROM   job WITH (nolock)
                    WHERE  wo_id = @wo_id
                           AND final_job = 1
						   AND state_cd<=1 --0.01.01 verification of job status
                SET @cur_bom_item= CURSOR
                FOR SELECT TOP 50 bom_pos,
                                  item_id,
                                  qty,
                                  backflush,
                                  def_lot_no
                    FROM   ofi_wo_item_ext WITH (nolock)
                    WHERE  wo_id = @wo_id AND parent_item_id IS NOT NULL
                    ORDER  BY bom_pos ASC

                OPEN @cur_jobs

                FETCH next FROM @cur_jobs INTO @oper_id, @seq_no, @job_qty

                WHILE @@FETCH_STATUS = 0
                  BEGIN
					
                      OPEN @cur_bom_item

                      FETCH next FROM @cur_bom_item INTO @bom_pos, @bom_item_id,
                      @bom_qty,
                      @backflush, @def_lot_no

                      WHILE @@FETCH_STATUS = 0
                        BEGIN
                            IF (NOT EXISTS (SELECT TOP 1 1
                                           FROM   job_bom WITH (nolock)
                                           WHERE  wo_id = @wo_id
                                                  AND oper_id = @oper_id
                                                  AND seq_no = @seq_no
                                                  AND bom_pos = 0)) 
									AND @bom_pos = 0				--(KN 03May23 - Added condition to ensure only item from bom_pos 0 of ofi_wo_item_ext gets picked here)
									
							BEGIN
								EXECUTE @rc= [dbo].[Sp_i_job_bom]
								@wo_id=@wo_id,
								@oper_id=@oper_id,
								@seq_no=@seq_no,
								@bom_pos=0,
								@item_id=@item_id,
								@reqd_grade_cd=NULL,
								@instruction=NULL,
								@qty_per_parent_item=1,
								@max_qty_per_parent_item=NULL,
								@min_qty_per_parent_item=NULL,
								@reqd_start_val=NULL,
								@reqd_start_val_is_pct=NULL,
								@update_inv=1,
								@backflush=0,
								@def_reas_cd=NULL,
								@def_lot_no=NULL,
								@def_sublot_no=NULL,
								@def_storage_ent_id=NULL,
								@def_reject_ent_id=NULL,
								@scaling_factor=NULL,
								@must_consume_from_inv=NULL,
								@may_choose_alt_inv_loc=NULL,
								@may_create_new_lots=NULL,
								@must_consume_from_wip=0,
								@must_consume_before_prod=0,
								@constant_qty=NULL,
								@est_time=NULL,
								@current_subst=NULL,
								@qty_reqd=NULL,
								@serial_no_source=NULL,
								@spare1=NULL,
								@spare2=NULL,
								@spare3=NULL,
								@spare4=NULL,
								@last_edit_comment=N'ADDED BY EI',
								@mod_id=@mod_id output

								IF ( @rc <> 0 )
								BEGIN
									SET @error_msg = N'Error while creating bom item for bom position zero  (' + @item_id+ ') in MES  - SP_I_EI_PRO_Create_BOM -  '+ CONVERT(NVARCHAR(16), @rc);
									THROW 51009, @error_msg, 1
								END
							END


							ELSE IF NOT EXISTS (SELECT TOP 1 1
                                           FROM   job_bom WITH (nolock)
                                           WHERE  wo_id = @wo_id
                                                  AND oper_id = @oper_id
                                                  AND seq_no = @seq_no
                                                  AND bom_pos = @bom_pos) 
							BEGIN

							SET @qty_per_parent_item=( @bom_qty / @job_qty )

                            EXECUTE @rc= [dbo].[Sp_i_job_bom]
                              @wo_id=@wo_id,
                              @oper_id=@oper_id,
                              @seq_no=@seq_no,
                              @bom_pos=@bom_pos,
                              @item_id=@bom_item_id,
                              @reqd_grade_cd=NULL,
                              @instruction=NULL,
                              @qty_per_parent_item=@qty_per_parent_item,
                              @max_qty_per_parent_item=NULL,
                              @min_qty_per_parent_item=NULL,
                              @reqd_start_val=NULL,
                              @reqd_start_val_is_pct=NULL,
                              @update_inv=NULL,
                              @backflush=0,
                              @def_reas_cd=NULL,
                              @def_lot_no=@def_lot_no,
                              @def_sublot_no=NULL,
                              @def_storage_ent_id=NULL,
                              @def_reject_ent_id=NULL,
                              @scaling_factor=NULL,
                              @must_consume_from_inv=NULL,
                              @may_choose_alt_inv_loc=NULL,
                              @may_create_new_lots=NULL,
                              @must_consume_from_wip=0,
                              @must_consume_before_prod=0,
                              @constant_qty=NULL,
                              @est_time=NULL,
                              @current_subst=NULL,
                              @qty_reqd=NULL,
                              @serial_no_source=NULL,
                              @spare1=NULL,
                              @spare2=NULL,
                              @spare3=NULL,
                              @spare4=NULL,
                              @last_edit_comment=N'ADDED BY EI',
                              @mod_id=@mod_id output

                            IF ( @rc <> 0 )
							BEGIN
								SET @error_msg = N'Error while creating bom item for bom position zero  (' + @bom_item_id+ ') in MES  - SP_I_EI_PRO_Create_BOM -  '+ CONVERT(NVARCHAR(16), @rc);
								THROW 51009, @error_msg, 1
							END

							--KN (06June23 - Added logic to set the update_inv flag only for the bom items of the process which doesn't have the attribute SkipInventoryForConsumables set
							--and the item doesn't have backflush indicator)

							IF NOT EXISTS(Select 1 from process_attr WITH(NOLOCK) where process_id = @process_id and attr_id = (SELECT attr_id from attr with(nolock) where attr_desc = 'SkipInventoryForConsumables'))
							BEGIN
								IF @backflush IS NULL or @backflush = 0
								BEGIN
									UPDATE job_bom SET update_inv=1 WHERE item_id = @bom_item_id and oper_id = @oper_id and seq_no = @seq_no and wo_id = @wo_id and bom_pos = @bom_pos
								END

							END

							END

                            FETCH next FROM @cur_bom_item INTO @bom_pos,
                            @bom_item_id,
                            @bom_qty,
                            @backflush, @def_lot_no
                        END

                      CLOSE @cur_bom_item

                      FETCH next FROM @cur_jobs INTO @oper_id, @seq_no, @job_qty
                  END

                CLOSE @cur_jobs

                DEALLOCATE @cur_bom_item

                DEALLOCATE @cur_jobs

				SET @def_lot_no=NULL

				SELECT @def_lot_no = lot_no
				FROM   ofi_wo_ext WITH (nolock)
				WHERE  wo_id = @wo_id 

				UPDATE job_bom
				SET def_lot_no=@def_lot_no
				WHERE wo_id=@wo_id and bom_pos=0





                COMMIT TRANSACTION
            END try

            BEGIN catch
                IF @@TRANCOUNT > 0
                  ROLLBACK TRANSACTION;

                SELECT @error_msg = Error_message(),
                       @error_severity = Error_severity(),
                       @error_state = Error_state();

                RAISERROR(@error_msg,@error_severity,@error_state)
            END catch
        END
  END

