CREATE PROCEDURE [dbo].[sp_U_ofi_InsertJobNotes]
	-- Add the parameters for the stored procedure here
	@wo_id nvarchar(30),
	@seq_no int,
	@oper_id nvarchar(50),
	@notes nvarchar(MAX)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	--update job set notes=@notes where wo_id=@wo_id and seq_no=@seq_no and oper_id=@oper_id
	declare @aId int
	select @aId=attr_id from attr with(nolock) where attr_desc='job_label_details'

DECLARE	@return_value int,
		@mod_id varchar(30)

		if exists(select * from job_attr  with(nolock) where wo_id=@wo_id and oper_id=@oper_id and seq_no=@seq_no and attr_id=@aId)
		BEGIN
			update job_attr
			set notes=@notes
			where
			wo_id=@wo_id and oper_id=@oper_id and seq_no=@seq_no and attr_id=@aId

		END
		else
		BEGIN


		EXEC	
		@return_value = [dbo].[sp_I_Job_Attr]
			@wo_id = @wo_id,
			@oper_id = @oper_id,
			@seq_no = @seq_no,
			@attr_id =@aId,
			@attr_value = NULL,
			@notes = @notes,
			@last_edit_comment = NULL,
			@mod_id = @mod_id OUTPUT

			SELECT	@mod_id as N'@mod_id'

			SELECT	'Return Value' = @return_value


			END
END

--===========================================================================================
-- Name:    SP_I_EI_PRO_Create_Wo
-- Description:  Inserts the work order details if not exist
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Sk          2022-07-26          Initial version.
-- 0.02.00  KN			2023-03-13		    Added additional logic to determine the process order type based on additional fields
-- 0.02.00  AML, XPM    2026-05-14          Updated how get the @to_uom_id to convert correctly the qtys
-- 0.03.00	AML, XPM	2026-07-14			Updated to skip item_process_link in Rework cases.			
-- ===========================================================================================
-- exec [dbo].[SP_I_EI_PRO_Create_Wo] 'Spare1', 'Spare2', '2000098287', 'ACTIVE', 'Spare1', 'Spare2', 'Spare3', 'Spare4'
CREATE   PROCEDURE [dbo].[SP_I_EI_PRO_Create_Wo] (@module        NVARCHAR(40),
                                               @plant_code    NVARCHAR(40),
                                               @wo_id         NVARCHAR(40),
                                               @erp_wo_status NVARCHAR(40),
                                               @spare1        NVARCHAR(200),
                                               @spare2        NVARCHAR(200),
                                               @spare3        NVARCHAR(200),
                                               @spare4        NVARCHAR(200))
AS
  BEGIN
      IF @erp_wo_status = 'ACTIVE'
         AND NOT EXISTS(SELECT TOP 1 1
                        FROM   wo WITH (nolock)
                        WHERE  wo_id = @wo_id)
         AND EXISTS(SELECT TOP 1 1
                    FROM   ofi_wo_ext WITH (nolock)
                    WHERE  wo_id = @wo_id
                           AND ( status = 1
                                  OR status IS NULL ))
        BEGIN
            DECLARE @rc               INT,
                    @error_msg        NVARCHAR(500),
                    @error_severity   INT,
                    @error_state      INT,
                    @item_pref        INT,
                    @event_time_utc   DATETIME,
                    @event_time_local DATETIME,
                    @created_by       NVARCHAR(40),
                    @process_id       NVARCHAR(40) = NULL,
                    @item_id          NVARCHAR(40),
                    @qty              FLOAT,
                    @wo_desc          NVARCHAR(80),
                    @user_id          NVARCHAR(80),
                    @prod_supervisor  NVARCHAR(40),
                    @req_finish_time  DATETIME,
					@sched_start_time DATETIME,
					@req_finish_time_local DATETIME,
					@sched_start_time_local DATETIME,
					@from_uom_id INT,
					@to_uom_id INT,
					@conv_factor FLOAT,
					@mod_id     VARCHAR(30),
                    @status     INT = 2,	--- -1 = Disabled, 1 = Experimental, 2 = Approved, 3 = Certified
                    @last_edit_comment  nvarchar(254) = 'ADDED BY EI' ;

SET XACT_ABORT ON
SET NoCount ON

            --BEGIN try
                BEGIN TRANSACTION

                SET @event_time_utc = dbo.Fn_stripmillisecsfromdatetime(Getutcdate())
                SET @event_time_local =dbo.Fn_tz_getlocaldatefromutc(NULL,@event_time_utc)

                IF @created_by IS NULL
                  BEGIN
                      SELECT @created_by = attr_value
                      FROM   system_attr sa WITH (nolock)
                      WHERE  sa.attr_id = 199
                  END

                SELECT @item_id = item_id,
                       @qty = wo_qty,
                       @wo_desc = wo_desc,
                       --@prod_supervisor = product_group,
					   @req_finish_time = dbo.Fn_s_ofi_converterpdatestring(req_finish_date, req_finish_time),
					   @sched_start_time=dbo.Fn_s_ofi_converterpdatestring(sched_start_date, sched_start_time),
					   @req_finish_time_local = dbo.Fn_s_ofi_converterpdatestring(req_finish_date,req_finish_time),
					   @sched_start_time_local=dbo.Fn_s_ofi_converterpdatestring(sched_start_date, sched_start_time)
				FROM   ofi_wo_ext WITH (nolock)
				WHERE  wo_id = @wo_id


				/** (KN 13-Mar-23) Added the below logic to determine the process order type based on product group, production method, material state and order type **/

				DECLARE @product_group VARCHAR(100),@prodn_method VARCHAR(100),@material_state VARCHAR(100),@order_type VARCHAR(100)

				SELECT @product_group = product_group,@prodn_method = prodn_method,@material_state = material_state,@order_type = order_type 
				from ofi_wo_ext where wo_id = @wo_id

				Print 'Product group ' + isnull(@product_group,'') + ' / Production Method ' + isnull(@prodn_method,'') 
				+ ' / Material state ' + isnull(@material_state,0) + ' / Order typer ' + isnull(@order_type,'')

				
				SET @process_id = NULL

				SELECT @process_id = dbo.Fn_s_ofi_get_processByCriteria(@wo_id,@product_group,@prodn_method,@material_state,@order_type)
				PRINT 'Process found by Criteria - ' +  isnULL(@process_id,'')

				IF @process_id IS NULL
				BEGIN
					Select @prod_supervisor = attr_value from item_attr with (nolock) where item_id = @item_id 
					and attr_id = (Select attr_id from attr with (nolock) where attr_desc = 'ProductionSupervisor' and attr_grp = 1)

					SELECT @process_id = dbo.Fn_s_ofi_processbyprodsupervisor(@prod_supervisor)
					PRINT 'Process found by Supervisor - ' +  isnULL(@process_id,'')
				END
				ELSE
					BEGIN
						UPDATE ofi_wo_ext set Comments = 'Process by Criteria - ' + @process_id WHERE wo_id = @wo_id
						SET @last_edit_comment = 'EI - Process added by Criteria'
					END

				/** (KN 13-Mar-23) End of the logic **/

		IF @process_id IS NOT NULL Print @prod_supervisor + ' - (' + @process_id + ')'

		PRINT 'Linking process ' + @process_id + ' with the item ' + @item_id
		
		DECLARE @clean_attr_id INT,
				@clean_item_process_link INT = 0;

		SELECT @clean_attr_id = a.attr_id 
		FROM attr a WITH(NOLOCK)
		WHERE a.attr_desc = 'CleanItemProcessLink' AND a.attr_grp = 8 -- V3.00

		SELECT @clean_item_process_link = attr_value 
		FROM process_attr WITH(NOLOCK)
		WHERE attr_id = @clean_attr_id AND process_id = @process_id


		IF @clean_item_process_link = 1 AND  @process_id IS NOT NULL
		BEGIN 

			EXECUTE [dbo].[sp_D_Item_Process_Link] 
						   @item_id = NULL
						  ,@process_id = @process_id
						  ,@mod_id = NULL

		END
		IF NOT EXISTS(SELECT TOP 1 1
				FROM   item_process_link WITH (nolock)
				WHERE  process_id = @process_id
						AND item_id = @item_id) 
		BEGIN


				IF LEN(ISNULL(@process_id,'')) > 0
					BEGIN

						SELECT @item_pref = Max(item_pref)
						FROM   item_process_link WITH (nolock)
						WHERE  process_id = @process_id 

						SET @item_pref=Isnull(@item_pref, 0) + 1

						EXEC sp_I_Item_Process_Link 
						@item_id,
						@process_id,
						@item_pref,
						@status,
						@last_edit_comment, 
						@mod_id OUTPUT ;

						PRINT 'Item_Process_link established'
					END
				ELSE
					BEGIN
						SET @error_msg = 'Unable to find process to link with item ' + @item_id
						RAISERROR(@error_msg,15,10)
					END
		END
		


		EXEC sp_S_DB_Status_GetAudTrailUsr @user_id OUTPUT, NULL

        --SET @user_id=dbo.Fn_s_ofi_serviceaccount()

		SELECT @to_uom_id = u.uom_id
			FROM   item i WITH (nolock)
				   INNER JOIN uom u WITH (nolock)
						   ON u.uom_id = i.uom_id
							  AND i.item_id = @item_id


		SELECT TOP 1  @from_uom_id = u.uom_id
		FROM uom u WITH (nolock)
			INNER JOIN ent_attr ea WITH(NOLOCK) ON u.description = ea.attr_value
			JOIN attr a WITH(NOLOCK) ON ea.attr_id = a.attr_id 
			JOIN site s WITH(NOLOCK) ON ea.ent_id = s.ent_id
		WHERE a.attr_desc = 'SAPPROUOM'


		IF @from_uom_id IS NULL
		BEGIN 
			SELECT @from_uom_id = u.uom_id
			FROM   ofi_wo_ext owe WITH (nolock)
				INNER JOIN uom u WITH (nolock)
						ON u.description = owe.uom_desc
							AND owe.wo_id = @wo_id
		END 


		IF @from_uom_id <> @to_uom_id
		BEGIN

			SELECT TOP 1 @conv_factor=factor
			FROM   uom_conv WITH (nolock)
			WHERE  from_uom_id = @from_uom_id
				   AND to_uom_id = @to_uom_id
				   AND ( @item_id IS NULL
						  OR @item_id = item_id )
			ORDER  BY item_id DESC

			SET @qty = @qty * @conv_factor

		END


		PRINT 'About to run job_exec_cwofp_stack'
		Print 'Quantity ' + cast(@qty as varchar)

        EXECUTE @rc = [dbo].[Sp_i_job_exec_cwofp_stack]
        @wo_id = @wo_id,
        @process_id = @process_id,
        @item_id = @item_id,
        @req_qty = @qty,
        @user_id = @user_id,
        @start_qty = @qty,
        @init_wo_state = 0,
        @wo_desc = @wo_desc,
        @release_time = @event_time_local,
        @release_time_tz = NULL,
        @req_finish_time = @req_finish_time,
        @req_finish_time_tz = NULL,
        @wo_priority = 50,
        @cust_info = NULL,
        @mo_id = NULL,
        @production_schedule_id = NULL,
        @notes = NULL,
        @bom_ver_id = NULL,
        @for_first_op = NULL,
        @spec_ver_id = NULL,
        @may_override_route = NULL,
        @parent_wo_id = NULL,
        @parent_oper_id = NULL,
        @parent_seq_no = NULL,
        @target_sched_line_id = NULL,
        @queue_seq_no = NULL,
        @check_privs = 1,
        @time_zone_bias_value = 0
		print 'Exit proc'
		
        IF ( @rc <> 0 )
			BEGIN
			SET @error_msg =N'Error while creating the work order ('+ @wo_id + ') in MES  - SP_I_EI_PRO_Create_Wo -  ' + CONVERT(NVARCHAR(16), @rc);
			THROW 51009, @error_msg, 1
        END
		ELSE
			DELETE from job_bom where wo_id = @wo_id and bom_pos <> 0	--(KN 2May23 - Delete the job_bom entries created by Sp_i_job_exec_cwofp_stack based on Recipe)

		
		print 'before update'
		UPDATE job
		--SET    sched_start_time_utc = @sched_start_time
		SET    sched_start_time_local = @sched_start_time_local --(KN 27-Jan-23 - Updated this to local as SAP sends their time only in local time)
		WHERE  wo_id = @wo_id
        --AND first_job = 1		--(KN 27-Jan-23 - Updated this as part of the same discussion and advised)

		UPDATE job_bom
		SET update_inv=1
		WHERE wo_id=@wo_id and bom_pos=0

		--Updating the spare1 of wo, to identify that it is a ERP work order
		UPDATE wo
		SET spare1=1
		WHERE wo_id=@wo_id

		DECLARE @oper_id VARCHAR(100),@seq_no INT,@init_ent_id INT,@attr_id INT

		SELECT @oper_id = oper_id,@init_ent_id = init_sched_ent_id,@seq_no = seq_no FROM JOB WHERE wo_id = @wo_id AND first_job = 1 -- @init_sched_ent_id in job will always be an Area 
		print 'after update' 
		EXEC @rc = [dbo].[sp_I_ofi_AutoAssignJob]
		@wo_id = @wo_id,
		@oper_id = @oper_id,
		@seq_no = @seq_no,
		@init_ent_id = @init_ent_id

	


		/* KN 18Apr23 Disabled as requested to possibly prevent auto release.
		Update job set state_cd = 1 WHERE wo_id = @wo_id AND first_job = 1 and seq_no = @seq_no -- KN 25/01/23 - Prevent job state from going to Running by default
		*/

		IF ( @rc <> 0 )
		BEGIN
		SET @error_msg = N'Error while auto assign job (' + @wo_id + ') in MES  - SP_I_EI_PRO_Create_Wo -  ' + CONVERT(NVARCHAR(16), @rc);
		END

        COMMIT TRANSACTION
        --END try

        --BEGIN catch
        --    IF @@TRANCOUNT > 0
        --        ROLLBACK TRANSACTION;

        --    SELECT @error_msg = Error_message(),
        --            @error_severity = Error_severity(),
        --            @error_state = Error_state();

        --    RAISERROR(@error_msg,@error_severity,@error_state)
        --END catch
        END
  END

