   @util_ent_id,
   @target_perf,
   @current_perf,
   @target_qual,
   @current_qual,
   @def_prod_rate,
   @prod_uom,
   @target_oee,
   @current_oee,
   @basis,
   @last_edit_comment,
   @last_edit_by,
   @last_edit_at)

