*/

CREATE   PROCEDURE [dbo].[sp_U_ofi_lm_MesMapping]
    @title NVARCHAR(100),
    @column_name NVARCHAR(100),
    @table_name NVARCHAR(100),
	@filter_id NVARCHAR(40),
    @return_code INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM [dbo].[ofi_lm_mes_info_mapping] WHERE [title] = @title)
    BEGIN
        THROW 50002, 'TitleDoesNotExist', 1;
    END

    BEGIN TRY
        UPDATE [dbo].[ofi_lm_mes_info_mapping]
        SET [column_name] = @column_name,
            [table_name] = @table_name,
			[filter_id] = @filter_id,
            [creation_date] = GETUTCDATE()
        WHERE [title] = @title;

    END TRY
    BEGIN CATCH
        THROW; 
    END CATCH

END;

