CREATE   PROCEDURE[dbo].[SP_I_EI_PUO_Add_Details] (@po_doc_no NVARCHAR(40),@po_doc_type NVARCHAR(40),@sup_plant_stock_trans_ordr NVARCHAR(40),
@sales_person NVARCHAR(40),@your_ref NVARCHAR(40),@our_ref NVARCHAR(40),@purchase_group NVARCHAR(40),@collective_no NVARCHAR(40),
@item_no_po_doc NVARCHAR(40),@material_no NVARCHAR(40),@material_desc NVARCHAR(40),@purchase_order_qty NVARCHAR(40),@purchase_order_UOM NVARCHAR(10),
@material_group NVARCHAR(40),@plant_code NVARCHAR(40),@req_track_no NVARCHAR(40),@po_item NVARCHAR(40),@batch NVARCHAR(40),@delivery_date NVARCHAR(40),
@spare1 NVARCHAR(200),@spare2 NVARCHAR(200),@spare3 NVARCHAR(200),@spare4 NVARCHAR(200),@spare5 NVARCHAR(200)) AS
BEGIN
	SET NOCOUNT ON
		  DECLARE @event_time_utc   DATETIME,
				  @event_time_local DATETIME,
				  @created_by       NVARCHAR(40),
				  @rc               INT,
