--===========================================================================================
-- Name:    SP_I_EI_PUO_Create_BOM
-- Description:  Updates BOM to the existing work order if SAP recipe to be used
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Sk          2022-07-27        Initial version.
-- 0.01.01	KN			2023-08-09			Added logic to set Update_inv flag for consumables
-- 0.01.02	MC			2025-03-30		  Do not modify BOM for job in status > 2 (after running)
-- ===========================================================================================
CREATE   PROCEDURE [dbo].[SP_I_EI_PUO_Create_BOM] (@module        NVARCHAR(40),
                                                @plant_code    NVARCHAR(40),
                                                @wo_id         NVARCHAR(40),
                                                @item_id       NVARCHAR(40),
                                                @spare1        NVARCHAR(200),
                                                @spare2        NVARCHAR(200),
                                                @spare3        NVARCHAR(200),
                                                @spare4        NVARCHAR(200))
AS
        BEGIN
            DECLARE @rc                  INT,
                    @error_msg           NVARCHAR(500),
                    @error_severity      INT,
                    @error_state         INT,
                    @cur_jobs            CURSOR,
                    @cur_bom_item        CURSOR,
                    @oper_id             NVARCHAR(40),
                    @seq_no              INT,
                    @job_qty             FLOAT,
                    @bom_pos             INT,
                    @bom_item_id         NVARCHAR(40),
                    @bom_qty             FLOAT,
                    @backflush           BIT,
					@cur_lot_no          NVARCHAR(40),
                    @def_lot_no          NVARCHAR(40),
                    @mod_id              VARCHAR(30),
                    @qty_per_parent_item FLOAT,
					@by_product			 BIT,
					@co_product			 BIT

            BEGIN try
                BEGIN TRANSACTION

				DECLARE @process_id VARCHAR(100)
				SELECT @process_id = process_id FROM wo WITH(nolock) WHERE wo_id = @wo_id

				IF NOT EXISTS(SELECT 1 FROM item WHERE item_id = @item_id)
				BEGIN
					SET @error_msg = N'Item (' + @item_id+ ') does not exist in MES  - SP_I_EI_PRO_Create_BOM';
					THROW 51009, @error_msg, 1
				END


                SET @cur_jobs=CURSOR
                FOR SELECT oper_id,
                           seq_no,
                           qty_reqd
                    FROM   job WITH (nolock)
                    WHERE  wo_id = @wo_id
                           AND final_job = 1
						   AND state_cd<=1 --0.01.02 verification of job status
                SET @cur_bom_item= CURSOR
                FOR SELECT TOP 50 bom_pos,
                                  item_id,
                                  qty,
                                  backflush,
                                  def_lot_no,
								  by_product,
								  co_product
                    FROM   ofi_wo_item_ext WITH (nolock)
                    WHERE  wo_id = @wo_id
                    ORDER  BY bom_pos ASC

                OPEN @cur_jobs

                FETCH next FROM @cur_jobs INTO @oper_id, @seq_no, @job_qty

                WHILE @@FETCH_STATUS = 0
                  BEGIN
                      OPEN @cur_bom_item

                      FETCH next FROM @cur_bom_item INTO @bom_pos, @bom_item_id,
                      @bom_qty,
                      @backflush, @cur_lot_no,@by_product,@co_product

                      WHILE @@FETCH_STATUS = 0
                        BEGIN
                            IF NOT EXISTS (SELECT TOP 1 1
                                           FROM   job_bom WITH (nolock)
                                           WHERE  wo_id = @wo_id
                                                  AND oper_id = @oper_id
                                                  AND seq_no = @seq_no
                                                  AND bom_pos = 0)
                  BEGIN
					  print 'lk'
					  EXECUTE @rc= [dbo].[Sp_i_job_bom]
                        @wo_id=@wo_id,
                        @oper_id=@oper_id,
                        @seq_no=@seq_no,
                        @bom_pos=0,
                        @item_id=@item_id,
                        @reqd_grade_cd=NULL,
                        @instruction=NULL,
                        @qty_per_parent_item=1,
                        @max_qty_per_parent_item=NULL,
                        @min_qty_per_parent_item=NULL,
                        @reqd_start_val=NULL,
                        @reqd_start_val_is_pct=NULL,
                        @update_inv=1,
                        @backflush=0,
                        @def_reas_cd=NULL,
                        @def_lot_no=NULL,
                        @def_sublot_no=NULL,
                        @def_storage_ent_id=NULL,
                        @def_reject_ent_id=NULL,
                        @scaling_factor=NULL,
                        @must_consume_from_inv=NULL,
                        @may_choose_alt_inv_loc=NULL,
                        @may_create_new_lots=NULL,
                        @must_consume_from_wip=0,
                        @must_consume_before_prod=0,
                        @constant_qty=NULL,
                        @est_time=NULL,
                        @current_subst=NULL,
                        @qty_reqd=NULL,
                        @serial_no_source=NULL,
                        @spare1=NULL,
                        @spare2=@bom_qty,
                        @spare3=NULL,
                        @spare4=NULL,
                        @last_edit_comment=N'ADDED BY EI',
                        @mod_id=@mod_id output

                      IF ( @rc <> 0 )
                        BEGIN
                            SET @error_msg = N'Error while creating bom item for bom position zero  (' + @item_id+ ') in MES  - SP_I_EI_PRO_Create_BOM -  '+ CONVERT(NVARCHAR(16), @rc);
						    THROW 51009, @error_msg, 1
                        END
                  END

							SET @qty_per_parent_item=( IIF(@bom_qty < 0, @bom_qty * -1,@bom_qty) / @job_qty )
															
								IF @co_product = 1
									SET @spare4 = 1
								ELSE
								IF @by_product = 1
									SET @spare4 = 0
								ELSE
									SET @spare4 = NULL
							
							 IF NOT EXISTS (SELECT TOP 1 1
                                           FROM   job_bom WITH (nolock)
                                           WHERE  wo_id = @wo_id
                                                  AND oper_id = @oper_id
                                                  AND seq_no = @seq_no
                                                  AND bom_pos = @bom_pos)
							BEGIN
                            EXECUTE @rc= [dbo].[Sp_i_job_bom]
                              @wo_id=@wo_id,
                              @oper_id=@oper_id,
                              @seq_no=@seq_no,
                              @bom_pos=@bom_pos,
                              @item_id=@bom_item_id,
                              @reqd_grade_cd=NULL,
                              @instruction=NULL,
                              @qty_per_parent_item=@qty_per_parent_item,
                              @max_qty_per_parent_item=NULL,
                              @min_qty_per_parent_item=NULL,
                              @reqd_start_val=NULL,
                              @reqd_start_val_is_pct=NULL,
                              @update_inv=NULL,
                              @backflush=@backflush,
                              @def_reas_cd=NULL,
                              @def_lot_no=@cur_lot_no,
                              @def_sublot_no=NULL,
                              @def_storage_ent_id=NULL,
                              @def_reject_ent_id=NULL,
                              @scaling_factor=NULL,
                              @must_consume_from_inv=NULL,
                              @may_choose_alt_inv_loc=NULL,
                              @may_create_new_lots=NULL,
                              @must_consume_from_wip=0,
                              @must_consume_before_prod=0,
                              @constant_qty=NULL,
                              @est_time=NULL,
                              @current_subst=NULL,
                              @qty_reqd=NULL,
                              @serial_no_source=NULL,
                              @spare1=NULL,
                              @spare2=@bom_qty,
                              @spare3=NULL,
                              @spare4=@spare4,
                              @last_edit_comment=N'ADDED BY EI',
                              @mod_id=@mod_id output

                        IF ( @rc <> 0 )
                        BEGIN
                            SET @error_msg = N'Error while creating bom item for bom position zero  (' + @bom_item_id+ ') in MES  - SP_I_EI_PRO_Create_BOM -  '+ CONVERT(NVARCHAR(16), @rc);
						    THROW 51009, @error_msg, 1
                        END

													--KN (06June23 - Added logic to set the update_inv flag only for the bom items of the process which doesn't have the attribute SkipInventoryForConsumables set
							--and the item doesn't have backflush indicator)

							IF NOT EXISTS(Select 1 from process_attr WITH(NOLOCK) where process_id = @process_id and attr_id = (SELECT attr_id from attr where attr_desc = 'SkipInventoryForConsumables'))
							BEGIN
								IF @backflush IS NULL or @backflush = 0
								BEGIN
									UPDATE job_bom SET update_inv=1 WHERE item_id = @bom_item_id and oper_id = @oper_id and seq_no = @seq_no and wo_id = @wo_id and bom_pos = @bom_pos
								END

							END

						END

                            FETCH next FROM @cur_bom_item INTO @bom_pos, @bom_item_id,
                      @bom_qty,
                      @backflush, @cur_lot_no,@by_product,@co_product
                        END

                      CLOSE @cur_bom_item

                      FETCH next FROM @cur_jobs INTO @oper_id, @seq_no, @job_qty
                  END

                CLOSE @cur_jobs

                DEALLOCATE @cur_bom_item

                DEALLOCATE @cur_jobs

				SET @def_lot_no=NULL

				SELECT @def_lot_no = lot_no
				FROM   ofi_wo_ext WITH (nolock)
				WHERE  wo_id = @wo_id 

				UPDATE job_bom
				SET def_lot_no=@def_lot_no
				WHERE wo_id=@wo_id and bom_pos=0

                COMMIT TRANSACTION
            END try

            BEGIN catch
                IF @@TRANCOUNT > 0
                  ROLLBACK TRANSACTION;

                SELECT @error_msg = Error_message(),
                       @error_severity = Error_severity(),
                       @error_state = Error_state();

                RAISERROR(@error_msg,@error_severity,@error_state)
            END catch
        END

/*
-- ===========================================================================================
-- Name:  [sp_U_ofi_bcons_SetDumpingTarget]
-- Description: Used to (re)set the isDumpingTarget job attribute in the currently running job
--              for the given WO. Also returns running job data to prepare data for the
--              UpdateJob_ofi workflow, which initiates communication with DCS.
--
-- Usage: Invoked from Work Tasks (MES UI); RequestBinsCons/StopBinsCons workflow
-- ===========================================================================================
-- Version Author  	Date (yyyy-MM-dd) 	Change description
-- 0.01.00 MH   	2025-10-15   		Initial version
-- ===========================================================================================*/
CREATE   PROCEDURE [dbo].[sp_U_ofi_bcons_SetDumpingTarget]
    @WoId nvarchar(80),
    @Value bit
AS BEGIN
    SET NOCOUNT ON
    SET XACT_ABORT ON

    BEGIN TRANSACTION

        -- Validate parameters
        IF @WoId IS NULL
            THROW 50000, '@WoId is NULL.', 0

        IF @Value IS NULL
            THROW 50000, '@Value is NULL.', 1
        
        -- Find isDumpingTarget attribute ID
        DECLARE @DumpingTargetAttrId AS INT;
        SELECT @DumpingTargetAttrId = attr_id
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE
            [attr_desc] = 'isDumpingTarget'
            AND [attr_grp] = 5; -- Job

        IF @DumpingTargetAttrId IS NULL
            THROW 50000, 'Could not find ''isDumpingTarget'' MES job attribute.', 2

        -- Find running job status ID
        DECLARE @RunningJobState AS INT;
        SELECT @RunningJobState = state_cd
        FROM [MESDB].[dbo].[job_state] WITH (NOLOCK)
        WHERE [state_desc] = 'RUNNING';

        IF @RunningJobState IS NULL
            THROW 50000, 'Could not find running job state ID.', 3

        -- Find running job data for WO
        DECLARE @OperId AS nvarchar(80);
        DECLARE @SeqNo AS int;
        DECLARE @JobRow AS int;
        SELECT
            @OperId = oper_id,
            @SeqNo = seq_no,
            @JobRow = row_id
        FROM [MESDB].[dbo].[job] WITH (NOLOCK)
        WHERE
            [wo_id] = @WoId
            AND state_cd = @RunningJobState;

        IF @OperId IS NULL OR @SeqNo IS NULL
            THROW 50000, 'The WO does not have a running job.', 4

        -- Create or update the job attribute
        DECLARE @EditComment AS nvarchar(128) = 'Start/Stop Bin Consumption Workflow';
        
        DECLARE @DumpingTargetAttrRow AS int
        SELECT @DumpingTargetAttrRow = [row_id]
        FROM [MESDB].[dbo].[job_attr] WITH (NOLOCK)
        WHERE
            [wo_id] = @WoId
            AND [oper_id] = @OperId
            AND [seq_no] = @SeqNo
            AND [attr_id] = @DumpingTargetAttrId
        
        DECLARE @ModId AS varchar(30);
        IF @DumpingTargetAttrRow IS NULL
            EXEC [dbo].[sp_I_Job_Attr]
                @wo_id = @WoId,
                @oper_id = @OperId,
                @seq_no = @SeqNo,
                @attr_id = @DumpingTargetAttrId,
                @attr_value = @Value,
                @notes = NULL,
                @last_edit_comment = @EditComment,
                @mod_id = @ModId OUTPUT;
        ELSE
            -- MH: Direct UPDATE is simpler.
            UPDATE [MESDB].[dbo].[job_attr]
            SET
                attr_value = @Value,
                last_edit_comment = @EditComment
                -- The UPDATE trigger handles last_edit_by and last_edit_at
            WHERE row_id = @DumpingTargetAttrRow;

        -- Return running job data for the WF; the Request/StopBinsCons workflows only have the WO ID 
        SET NOCOUNT OFF
        SELECT
            @WoId as wo_id,
            @OperId as oper_id,
            @SeqNo as seq_no,
            @JobRow as row_id

    COMMIT TRANSACTION
END

/*
-- ===========================================================================================
-- Name:  [sp_I_ofi_aut_int_buff_InsertPRODData]
-- Description: Used to insert PROD interface data into the buffer table
--
-- Usage: For AUT interface to insert the values from IDE PROD object 
-- ===========================================================================================
-- Version Author  	Date (yyyy-MM-dd) 	Change description
-- 0.01.00 JSC   	2025-04-15   		CR512: Initial version.
-- 0.01.01 JSC		2025-05-27			Added the row_id_output as output
-- ===========================================================================================*/
-- Updated PROD Data Proc with correct data types
CREATE      PROCEDURE [dbo].[sp_I_ofi_aut_int_buff_InsertPRODData]
    @wo_id NVARCHAR(40),
    @seq_no INT,
    @sublot_no INT,
    @qty FLOAT,
    @storage_unit NVARCHAR(40),
    @item_id NVARCHAR(80),
    @alibi_number NVARCHAR(40) = NULL,
    @recorded_timestamp DATETIME,
	@current_timestamp DATETIME,
    @object_name NVARCHAR(80),
    @interface_type NVARCHAR(15) = 'PROD',
	@return_code INT = 0 OUTPUT
	,@row_id_output INT = -1 OUTPUT
AS
BEGIN

	DECLARE @object_name_local NVARCHAR(80)
		,   @interface_type_local NVARCHAR(15)
		,	@current_timestamp_local DATETIME

	SET @object_name_local = @object_name
	SET @interface_type_local = @interface_type
	SET @current_timestamp_local = @current_timestamp

    DECLARE @Data_local NVARCHAR(4000) = (
        SELECT
            @wo_id AS wo_id,
            @seq_no AS seq_no,
            @sublot_no AS sublot_no,
            @qty AS qty,
            @storage_unit AS storage_unit,
            @item_id AS item_id,
            @alibi_number AS alibi_number,
			@recorded_timestamp AS recorded_timestamp
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    EXEC dbo.sp_I_ofi_aut_int_buff 
        @Data = @Data_local,
        @object_name = @object_name_local,
        @interface_type = @interface_type_local,
        @current_timestamp = @current_timestamp_local,
        @Error = @return_code OUTPUT,
		@id = @row_id_output OUTPUT;


	SET @return_code = COALESCE(@return_code,999999)
	SET @row_id_output = COALESCE(@row_id_output,-1)

    RETURN @return_code
END;

--===========================================================================================
-- Name:    SP_I_EI_PUO_Create_Wo
-- Description:  Creates work order for the given PUO
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)	Change description
-- 0.01.00  Karthik     2022-09-08			Initial version.
-- 0.01.01	Karthik		2022-09-13			Added logic to obtain data from item_transfer
-- 0.01.02	Lavkesh		2024-02-18			Added logic to insert WO Attribute for Auto Release 
-- 0.01.03	Lavkesh		2024-04-18			Added logic to check plant code 
-- ===========================================================================================


CREATE             PROCEDURE [dbo].[SP_I_EI_PUO_Create_Wo] (@module        NVARCHAR(40),
                                               @plant_code    NVARCHAR(40),
                                               @wo_id         NVARCHAR(40),
                                               @spare1        NVARCHAR(200),
                                               @spare2        NVARCHAR(200),
                                               @spare3        NVARCHAR(200),
                                               @spare4        NVARCHAR(200))
AS
BEGIN

SET NOCOUNT ON
            DECLARE @rc               INT,
                    @error_msg        NVARCHAR(500),
                    @error_severity   INT,
                    @error_state      INT,
                    @item_pref        INT,
                    @event_time_utc   DATETIME,
                    @event_time_local DATETIME,
                    @created_by       NVARCHAR(40),
                    @process_id       NVARCHAR(40),
                    @item_id          NVARCHAR(40),
                    @qty              FLOAT,
                    @wo_desc          NVARCHAR(80),
                    @user_id          NVARCHAR(80),
                    @prod_supervisor  NVARCHAR(40),
                    @req_finish_time  DATETIME,
					@sched_start_time DATETIME,
					@from_uom_id INT,
					@to_uom_id INT,
					@conv_factor FLOAT,
					@material_grp	 VARCHAR(100),
					@req_finish_time_local DATETIME,
					@sched_start_time_local DATETIME,
					@attr_id_Auto_Release int,
					@mod_id         VARCHAR(30)

            BEGIN try
                BEGIN TRANSACTION
				IF (dbo.fn_s_ofi_plantcode()= @plant_code)-- 0.01.03
				BEGIN
                SET @event_time_utc = dbo.Fn_stripmillisecsfromdatetime(Getutcdate())
                SET @event_time_local =dbo.Fn_tz_getlocaldatefromutc(NULL,@event_time_utc)

                IF @created_by IS NULL
                  BEGIN
                      SELECT @created_by = attr_value
                      FROM   system_attr sa WITH (nolock)
                      WHERE  sa.attr_id = 199
                  END


                SELECT @item_id = item_id,
                       @qty = wo_qty,
                       @wo_desc = wo_desc,
					   @req_finish_time = dbo.Fn_s_ofi_converterpdatestring(req_finish_date, req_finish_time),
					   @sched_start_time=dbo.Fn_s_ofi_converterpdatestring(sched_start_date, sched_start_time),
					   @req_finish_time_local = dbo.Fn_s_ofi_converterpdatestring(req_finish_date,req_finish_time),
					   @sched_start_time_local=dbo.Fn_s_ofi_converterpdatestring(sched_start_date, sched_start_time)
				FROM   ofi_wo_ext WITH (nolock)
				WHERE  wo_id = @wo_id

				PRINT 'Item ID - ' + ISNULL(@item_id,'')


				--Select @prod_supervisor = attr_value from item_attr with (nolock) where item_id = @item_id 
				--and attr_id = (Select attr_id from attr with (nolock) where attr_desc = 'ProductionSupervisor' and attr_grp = 1)

				Select @material_grp = product_group from ofi_wo_ext where wo_id = @wo_id
				Select @process_id = process_id from process_attr with (nolock) where attr_value = @material_grp
				If @material_grp = 8004
				Begin
					Set @process_id = 'Additive Bulk Intake-1'
				End


        --SELECT @process_id = dbo.Fn_s_ofi_processbyprodsupervisor(@prod_supervisor)

		PRINT 'Process ID - ' + iSNULL(@process_id,'') + ' / Item ID - ' + iSNULL(@item_id,'')

        IF NOT EXISTS(SELECT TOP 1 1
               FROM   item_process_link WITH (nolock)
               WHERE  process_id = @process_id
                      AND item_id = @item_id)
        BEGIN
        SELECT @item_pref = Max(item_pref)
        FROM   item_process_link WITH (nolock)
        WHERE  process_id = @process_id

        SET @item_pref=Isnull(@item_pref, 0) + 1

        INSERT INTO item_process_link
                   (item_id,
                    process_id,
                    item_pref,
                    [status],
                    last_edit_comment,
                    last_edit_by,
                    last_edit_at)
        VALUES      (@item_id,
                    @process_id,
                    @item_pref,
                    2,
                    N'ADDED BY EI',
                    @created_by,
                    @event_time_utc)
        END


  EXEC sp_S_DB_Status_GetAudTrailUsr @user_id OUTPUT, NULL


		SELECT @to_uom_id = u.uom_id
			FROM   item i WITH (nolock)
				   INNER JOIN uom u WITH (nolock)
						   ON u.uom_id = i.uom_id
							  AND i.item_id = @item_id

		SELECT @from_uom_id = u.uom_id
		FROM   ofi_wo_ext owe WITH (nolock)
				INNER JOIN uom u WITH (nolock)
						ON u.description = owe.uom_desc
							AND owe.wo_id = @wo_id

		IF @from_uom_id <> @to_uom_id
		BEGIN

			SELECT TOP 1 @conv_factor=factor
			FROM   uom_conv WITH (nolock)
			WHERE  from_uom_id = @from_uom_id
				   AND to_uom_id = @to_uom_id
				   AND ( @item_id IS NULL
						  OR @item_id = item_id )
			ORDER  BY item_id DESC

			SET @qty=@qty * @conv_factor

		END

		IF @qty is NULL SET @qty = 0

		PRINT 'About to execute Job exec cwofp'

        EXECUTE @rc = [dbo].[Sp_i_job_exec_cwofp_stack]
        @wo_id = @wo_id,
        @process_id = @process_id,
        @item_id = @item_id,
        @req_qty = @qty,
        @user_id = @user_id,
        @start_qty = @qty,
        @init_wo_state = 0,
        @wo_desc = @wo_desc,
        @release_time = @event_time_local,
        @release_time_tz = NULL,
        @req_finish_time = @req_finish_time,
        @req_finish_time_tz = NULL,
        @wo_priority = 50,
        @cust_info = NULL,
        @mo_id = NULL,
        @production_schedule_id = NULL,
        @notes = NULL,
        @bom_ver_id = NULL,
        @for_first_op = NULL,
        @spec_ver_id = NULL,
        @may_override_route = NULL,
        @parent_wo_id = NULL,
        @parent_oper_id = NULL,
        @parent_seq_no = NULL,
        @target_sched_line_id = NULL,
        @queue_seq_no = NULL,
        @check_privs = 1,
        @time_zone_bias_value = 0

		PRINT 'JOB executed'

        IF ( @rc <> 0 )
        BEGIN
        SET @error_msg =N'Error while creating the work order ('+ @wo_id + ') in MES  - SP_I_EI_PUO_Create_Wo -  ' + CONVERT(NVARCHAR(16), @rc);
        THROW 51009, @error_msg, 1
        END
		-- 0.01.02
		 SELECT @attr_id_Auto_Release = attr_id
                      FROM   attr a WITH (nolock)
                      WHERE  a.attr_desc = 'NewOrderCheck'
                             AND a.attr_grp = 6
		if Not Exists(select 1 from wo_attr with(nolock) where attr_id=@attr_id_Auto_Release and wo_id=@wo_id)  -- 0.01.02 
		BEGIN
					  EXEC @rc = [dbo].[Sp_i_wo_attr]
                        @wo_id = @wo_id,
                        @attr_id = @attr_id_Auto_Release,
                        @attr_value = 'True',
                        @notes = 'ADDED BY EI',
                        @last_edit_comment = NULL,
                        @mod_id = @mod_id output
         END

		UPDATE job
		--SET    sched_start_time_utc = @sched_start_time
		SET    sched_start_time_local = @sched_start_time_local --(KN 27-Jan-23 - Updated this to local as SAP sends their time only in local time)
		WHERE  wo_id = @wo_id
        --AND first_job = 1		--(KN 27-Jan-23 - Updated this as part of the same discussion and advised)

		UPDATE job_bom
		SET update_inv=1
		WHERE wo_id=@wo_id and bom_pos=0

		--Updating the spare1 of wo, to identify that it is a ERP work order
		UPDATE wo
		SET spare1=1
		WHERE wo_id=@wo_id


	
		DECLARE @oper_id VARCHAR(100),@seq_no INT,@init_ent_id INT

		DECLARE auto_cur CURSOR FOR
			SELECT oper_id,init_sched_ent_id,seq_no FROM JOB WHERE wo_id = @wo_id and seq_no = 0

		Open auto_cur
		Fetch next from auto_cur into @oper_id,@init_ent_id,@seq_no

		WHILE @@FETCH_STATUS = 0								-- For each of that job (operation)
		BEGIN

		--SELECT @oper_id = oper_id,@init_ent_id = init_sched_ent_id,@seq_no = seq_no FROM JOB WHERE wo_id = @wo_id AND first_job = 1 -- @init_sched_ent_id in job will always be an Area 

		EXEC @rc = [dbo].[sp_I_ofi_AutoAssignJob] @wo_id = @wo_id,@oper_id = @oper_id,@seq_no = @seq_no,@init_ent_id = @init_ent_id

		Update job set state_cd = 1 WHERE wo_id = @wo_id AND oper_id = @oper_id and seq_no = @seq_no -- KN 25/01/23 - Prevent job state from going to Running by default

		IF ( @rc <> 0 )
			SET @error_msg = N'Error while auto assign job (' + @wo_id + ') in MES  - SP_I_EI_PUO_Create_Wo -  ' + CONVERT(NVARCHAR(16), @rc);

		Fetch next from auto_cur into @oper_id,@init_ent_id,@seq_no
		END

		Close auto_cur
		Deallocate auto_cur


		END
		COMMIT TRANSACTION

        END try

            BEGIN catch
                IF @@TRANCOUNT > 0
                  ROLLBACK TRANSACTION;

                SELECT @error_msg = Error_message(),
                       @error_severity = Error_severity(),
                       @error_state = Error_state();

                RAISERROR(@error_msg,@error_severity,@error_state)
            END catch
END

