-- exec [sp_U_ofi_Item_Inv_Move] (item)

CREATE PROCEDURE [dbo].[sp_U_ofi_Item_Inv_Move] (
	  @from_row_id INT32
	, @from_last_edit_at TDATETIME = NULL
	, @item_id STRING40
	, @lot_no STRING40
	, @sublot_no STRING40
	, @to_sublot_no STRING40
	, @to_lot_no STRING40
	, @to_status_cd INT32 = NULL		--	 v0.5 updated this parameter as NULLable
	, @to_uom INT32_NULL = NULL
	, @to_expiry_date TDATETIME_NULL = NULL
	, @to_grade_cd INT32 = NULL			--	 v0.5 updated this parameter as NULLable
	, @to_seq_no INT32_NULL = NULL
	, @log_transfer INT32
	, @transfer_option INT32
	, @transfer_comments STRING254
	, @from_wo_id STRING40_NULL = NULL
	, @to_item_id STRING40 = NULL
	, @to_wo_id STRING40_NULL = NULL
	, @from_ent_id INT32 = NULL
	, @transfer_qty STRING40_NULL = NULL
	
	, @transfer_qty_erp TFLOAT = NULL
	, @in_to_ent_id INT32 = NULL
	, @in_to_item_id STRING40 = NULL
	, @in_to_lot_no STRING40 = NULL
	, @in_to_sublot_no STRING40 = NULL
	, @in_to_grade_cd INT32 = NULL
	, @to_expiry_date_utc TDATETIME_NULL = NULL
	, @to_oper_id STRING40_NULL = NULL
	, @from_oper_id STRING40_NULL = NULL
	, @from_seq_no INT32_NULL = NULL
	, @in_to_status_cd INT32 = NULL
	, @in_to_uom_id STRING40 = NULL
	, @in_to_expiry_date TDATETIME = NULL
	, @in_to_expiry_date_tz INT32 = NULL
	, @in_to_wo_id STRING80 = NULL
	, @in_to_oper_id STRING80 = NULL
	, @in_to_seq_no INT32 = NULL
	, @in_transfer_option INT32 = NULL
	, @in_move_inv_to_dwnstrm_job INT32 = NULL
	, @in_transfer_comments STRING254 = NULL
	, @in_log_transfer INT32 = 1
	, @bulk_move_reclassify LOGICAL = 0
	, @time_zone_bias_value INT32 = NULL
	--, @resultset int output
	 --, @resultcode nvarchar(250) output
	 )
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @transfer_qty1 float=null;
	select @transfer_qty1=convert(float,@transfer_qty)
	------------------------Audit Log----------------------
	--set @item_id=null
	IF OBJECT_ID(N'tempdb..#LocalCustomer') IS NOT NULL
	BEGIN
	DROP TABLE #LocalCustomer
	END
	
	DECLARE @iteminv as TABLE (
	
	[ent_id] [dbo].[STRING40] NOT NULL,
	[item_id] [dbo].[STRING40]  NULL,
	[grade_cd] [dbo].[int32]  NULL,
	[status_cd] [dbo].[int32]  NULL,
	[qty] [dbo].[STRING40] NOT NULL)


	insert into @iteminv values(@in_to_ent_id,@in_to_item_id,@in_to_grade_cd,@in_to_status_cd,@transfer_qty1)


	declare @curItemId nvarchar(50),@curStatuscd int ,@curGradecd int
	select @curItemId=item_id,@curStatuscd=status_cd,@curGradecd=grade_cd from item_inv with(nolock) where ent_id=@in_to_ent_id

	IF @item_id=@to_Item_id
	BEGIN
	IF ISNULL(@transfer_comments,'') <> 'RECLASS'
		BEGIN
		set @item_id=NULL
		set @to_item_id=NULL
		set @in_to_item_id=null
		END
	END
	--IF @item_id=@in_to_item_id
	--set @in_to_item_id=null
	--set @item_id=null

	

	DECLARE @from_ent_name STRING80,
			  @inv_unique_by_job LOGICAL,
			  @row_id int,
			  @to_ent_id INT32,
			  @to_ent_name STRING80,
			  @err_msg nvarchar(2000),
			  @can_store INT32,
			  @from_ent_indistinct INT32,
			  @to_ent_indistinct INT32,
			  @dbg_resp INT32,
			  @capacity float,
			  @last_edit_at datetime,
			  @tare_uom_id STRING40,
			  @tare STRING40,
			  @auto_del_zero_inv bit,
			  @allow_neg_qty bit,
			  @scannable_id nvarchar(40),
			  @allow_multiple_items bit,
			  @allow_multiple_lots bit,
			  @movable bit,
			  @storage_ent_id int,
			  @allow_dirty_state bit,
			  @log_state_transitions bit,
			  @indistinguishable_lots bit,
			  @unlisted bit,
			  @spare_int1 int,
			  @spare_int2 int,
			  @spare_int3 int,
			  @spare_int4 int,
			  @spare1 nvarchar(1000),
			  @spare2 nvarchar(1000),
			  @spare3 nvarchar(1000),
			  @spare4 nvarchar(1000),
			  @last_edit_comment nvarchar(254),
			  @status int,
			  @uom_id int,
			  --Added missing parameter into update inventory transfer quantity sp
			  @in_to_expiry_date_utc TDATETIME = GETUTCDATE();

	  -- v0.5 BS
	  DECLARE @i_min int ;
	  DECLARE @i_max int ;
	  DECLARE @tbl_item_inv_loc AS TABLE (
		id int IDENTITY (1, 1),
		row_id int,
		item_id nvarchar(80),
		lot_no nvarchar(40),
		sublot_no nvarchar(40),
		qty_left float,
		qty_left_erp float,
		uom_id int,
		grade_cd int,
		status_cd int
	  ) ;

	  DECLARE @local_grade_cd int;
	  DECLARE @local_status_cd int;
	  DECLARE @local_item_id nvarchar(40) ;
	  -- v0.5 BE
	  DECLARE @local_comments nvarchar(500);

	  SET @in_to_expiry_date_tz = dbo.fn_TZ_ValidateOffset(@in_to_expiry_date_tz)
	  SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)
	  SET @bulk_move_reclassify = COALESCE(@bulk_move_reclassify, 0)


	  -- TRACE
	  BEGIN TRY
	 
	 IF(@item_id is not null)
	BEGIN
	set @local_comments=@transfer_comments;
	END
	ELSE
	BEGIN
	set @local_comments = NULL;
	END

			SELECT
			  @capacity = max_capacity,
			  @last_edit_at = last_edit_at,
			  @status = status,
			  @uom_id = uom_id,
			  @tare_uom_id = tare_uom_id,
			  @tare = tare,
			  @auto_del_zero_inv = auto_del_zero_inv,
			  @allow_neg_qty = allow_neg_qty,
			  @scannable_id = scannable_id,
			  @allow_multiple_items = allow_multiple_items,
			  @allow_multiple_lots = allow_multiple_lots,
			  @movable = movable,
			  @storage_ent_id = storage_ent_id,
			  @allow_dirty_state = allow_dirty_state,
			  @log_state_transitions = log_state_transitions,
			  @indistinguishable_lots = indistinguishable_lots,
			  @unlisted = unlisted,
			  @spare_int1 = spare_int1,
			  @spare_int2 = spare_int2,
			  @spare_int3 = spare_int3,
			  @spare_int4 = spare_int4,
			  @spare1 = spare1,
			  @spare2 = spare2,
			  @spare3 = spare3,
			  @spare4 = spare4,
			  @last_edit_comment = last_edit_comment
			FROM dbo.storage_exec WITH (NOLOCK)
			WHERE ent_id = @from_ent_id ;

			 
			EXEC sp_U_Storage_Exec @ent_id = @from_ent_id,
								   @type = NULL,
								   @max_capacity = 0,		--@capacity,
								   @status = @status,
								   @uom_id = @in_to_uom_id,
								   @tare_uom_id = @tare_uom_id,
								   @tare = @tare,
								   @auto_del_zero_inv = @auto_del_zero_inv,
								   @allow_neg_qty = @allow_neg_qty,
								   @scannable_id = @scannable_id,
								   @allow_multiple_items = @allow_multiple_items,
								   @allow_multiple_lots = @allow_multiple_lots,
								   @movable = @movable,
								   @storage_ent_id = @storage_ent_id,
								   @allow_dirty_state = @allow_dirty_state,
								   @log_state_transitions = @log_state_transitions,
								   @indistinguishable_lots = @indistinguishable_lots,
								   @unlisted = @unlisted,
								   @spare_int1 = @spare_int1,
								   @spare_int2 = @spare_int2,
								   @spare_int3 = @spare_int3,
								   @spare_int4 = @spare_int4,
								   @spare1 = @spare1,
								   @spare2 = @spare2,
								   @spare3 = @spare3,
								   @spare4 = @spare4,
								   @last_edit_comment = @last_edit_comment,
								   @last_edit_at = @last_edit_at ;



		IF (@bulk_move_reclassify = 1)
		BEGIN

		  IF (@from_ent_id IS NULL)
		  BEGIN
			SET @err_msg = 'The %1 should not be null{3339},from entity ID'
			RAISERROR (@err_msg, 16, 1)
			RETURN
		  END

		  IF NOT EXISTS (SELECT TOP 1
			  1
			FROM ent WITH (NOLOCK)
			WHERE ent_id = @from_ent_id)
		  BEGIN
			SET @err_msg = 'The specified %%1 does not exist in the database.{3566},' + 'entity ID :' + CONVERT(nvarchar(20), @from_ent_id)
			RAISERROR (@err_msg, 16, 1)
			RETURN
		  END

		  /*
  			-- v0.5 BS
  			DECLARE item_inv_loc CURSOR FAST_FORWARD FOR
  			SELECT ii.row_id, ii.qty_left, ii.qty_left_erp,ii.sublot_no
  			FROM item_inv ii WITH (NOLOCK)
  			WHERE ii.ent_id = @from_ent_id
  			 --AND (ii.item_id = @item_id OR @item_id IS NULL) -- Restrict to the item, if supplied
  			--  AND (ii.lot_no = @lot_no OR @lot_no IS NULL) -- Restrict to the lot, if supplied
  			--  AND (ii.sublot_no = @sublot_no OR @sublot_no IS NULL) -- Restrict to the sublot, if supplied
  			OPEN item_inv_loc
  			WHILE (1=1) BEGIN				--0.4
  				FETCH NEXT FROM item_inv_loc INTO @row_id, @transfer_qty, @transfer_qty_erp,@in_to_sublot_no  
  				IF (@@FETCH_STATUS <> 0) BREAK
  
  				EXEC sp_U_Item_Inv_Move @from_row_id=@row_id, @in_to_item_id=@to_item_id, @in_to_grade_cd=@to_grade_cd, @in_to_status_cd=@to_status_cd,
  				@transfer_qty=@transfer_qty, @transfer_qty_erp=@transfer_qty_erp,@in_to_sublot_no=@in_to_sublot_no
  				--, @from_last_edit_at=NULL, 
  				--@from_ent_id=@from_ent_id, 
  				--	, @in_to_ent_id=@to_ent_id, @in_to_lot_no=@to_lot_no, @in_to_sublot_no=@to_sublot_no
  				--	 @in_to_uom_id=@to_uom, @in_to_expiry_date=@to_expiry_date
  				--	, @in_to_expiry_date_tz=0
  					--, @in_to_expiry_date_utc=@to_expiry_date_utc
  					--, @in_to_wo_id=@to_wo_id, @in_to_oper_id=@to_oper_id, @in_to_seq_no=@to_seq_no, @in_transfer_option=@transfer_option, @in_move_inv_to_dwnstrm_job=NULL
  					, @in_transfer_comments=@transfer_comments--, @in_log_transfer=@log_transfer, @time_zone_bias_value=NULL
  				
  				
  				
  				
  				--	UPDATE item_inv
  				--SET grade_cd = @in_to_grade_cd,
  				--	status_cd = @in_to_status_cd,
  				--	expiry_date = @in_to_expiry_date,
  				--	wo_id = @in_to_wo_id,
  				--	oper_id = @in_to_oper_id,
  				--	seq_no = @in_to_seq_no
  				--WHERE item_id = @in_to_item_id
  				--	AND ent_id = @in_to_ent_id
  			END
  			-- v0.5 BE */


		  -- v0.5 BS
		  INSERT INTO @tbl_item_inv_loc (row_id, item_id, lot_no, sublot_no, qty_left, qty_left_erp, uom_id, grade_cd, status_cd)
			SELECT
			  ii.row_id,
			  ii.item_id,
			  ii.lot_no,
			  ii.sublot_no,
			  ii.qty_left,
			  ii.qty_left_erp,
			  ii.uom_id,
			  ii.grade_cd,
			  ii.status_cd
			FROM item_inv ii WITH (NOLOCK)
			WHERE ii.ent_id = @from_ent_id;

		  SELECT
			@i_min = MIN(id),
			@i_max = MAX(id)
		  FROM @tbl_item_inv_loc;

		  WHILE (@i_min <= @i_Max)
		  BEGIN
			-- if @to_item_id is NULL -> dont change existing item id
			-- if @to_grade_cd is NULL -> dont change existing grade code
			-- if @to_status_cd is NULL -> dont change existing status code

			SELECT
			  @row_id = row_id,
			  @local_item_id =
						   CASE
							 WHEN @to_item_id IS NULL THEN item_id
							 ELSE @to_item_id
						   END,
			  @in_to_lot_no = lot_no,
