/*
-- ===========================================================================================
-- Name:  [sp_S_ofi_bcons_CheckDumpingTarget]
-- Description: Used to compare the isDumpingTarget job attribute to the isDumping job attribute
--              in the currently running job for the given WO. Also returns running job data.
--
-- Usage: Invoked from Work Tasks (MES UI); Post_Start/StopBinCons_NewInterface JS functions
--        in ofi.ProductionExecution 
-- ===========================================================================================
-- Version Author  	Date (yyyy-MM-dd) 	Change description
-- 0.01.00 MH   	2025-10-16   		Initial version
-- ===========================================================================================*/
CREATE   PROCEDURE [dbo].[sp_S_ofi_bcons_CheckDumpingTarget]
    @WoId nvarchar(80)
AS BEGIN
    SET NOCOUNT ON
    SET XACT_ABORT ON

    BEGIN TRANSACTION

        -- Validate parameters
        IF @WoId IS NULL
            THROW 50000, '@WoId is NULL.', 0
        
        -- Find isDumpingTarget and isDumping attribute IDs
        DECLARE @DumpingTargetAttrId AS INT;
        SELECT TOP 1 @DumpingTargetAttrId = attr_id
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE
            [attr_desc] = 'isDumpingTarget'
            AND [attr_grp] = 5; -- Job

        IF @DumpingTargetAttrId IS NULL
            THROW 50000, 'Could not find ''isDumpingTarget'' MES job attribute.', 1
        
        DECLARE @DumpingAttrId AS INT;
        SELECT TOP 1 @DumpingAttrId = attr_id
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE
            [attr_desc] = 'isDumping'
            AND [attr_grp] = 5; -- Job

        IF @DumpingAttrId IS NULL
            THROW 50000, 'Could not find ''isDumping'' MES job attribute.', 2

        -- Find running job status ID
        DECLARE @RunningJobState AS INT;
        SELECT TOP 1 @RunningJobState = state_cd
        FROM [MESDB].[dbo].[job_state] WITH (NOLOCK)
        WHERE [state_desc] = 'RUNNING';

        IF @RunningJobState IS NULL
            THROW 50000, 'Could not find running job state ID.', 3

        -- Find running job data for WO
        DECLARE @OperId AS nvarchar(80);
        DECLARE @SeqNo AS int;
        DECLARE @JobRow AS int;
        SELECT TOP 1
            @OperId = oper_id,
            @SeqNo = seq_no,
            @JobRow = row_id
        FROM [MESDB].[dbo].[job] WITH (NOLOCK)
        WHERE
            [wo_id] = @WoId
            AND state_cd = @RunningJobState;

        -- Select attribute values
        DECLARE @DumpingTargetValue AS int;
        DECLARE @DumpingValue AS int;

        IF @OperId IS NULL OR @SeqNo IS NULL OR @JobRow IS NULL
        BEGIN
            -- There is no running job(?) - send NULLs instead
            SET @OperId = NULL;
            SET @SeqNo = NULL;
            SET @JobRow = NULL;
            SET @DumpingTargetValue = NULL;
            SET @DumpingValue = NULL;
            GOTO ReturnResultSet;
        END

        SELECT @DumpingTargetValue = [attr_value]
        FROM [MESDB].[dbo].[job_attr]
        WHERE
            [wo_id] = @WoId
            AND [oper_id] = @OperId
            AND [seq_no] = @SeqNo
            AND [attr_id] = @DumpingTargetAttrId;

        SELECT @DumpingValue = [attr_value]
        FROM [MESDB].[dbo].[job_attr]
        WHERE
            [wo_id] = @WoId
            AND [oper_id] = @OperId
            AND [seq_no] = @SeqNo
            AND [attr_id] = @DumpingAttrId;
        
    ReturnResultSet:
        -- Return running job data for the JS functions; the scripts only have the WO ID
        SET NOCOUNT OFF
        SELECT
            @WoId as wo_id,
            @OperId as oper_id,
            @SeqNo as seq_no,
            @JobRow as row_id,
            @DumpingTargetValue AS target_value,
            @DumpingValue AS actual_value

    COMMIT TRANSACTION
END

--===========================================================================================
-- Name:        sp_S_OFI_CB_correction
-- Description: select measured value of FAT,MOist,Ph, LCH for current correction step
--
-- Usage:       From which object this script is called.
-- ===========================================================================================
-- Version      Author                  Date (yyyy-MM-dd)       Change description
-- 0.01.00      AKM                       2022-12-22            Initial version.
-- ===========================================================================================



CREATE PROCEDURE [dbo].[sp_S_OFI_CB_correction] 
 @wo_id NVARCHAR (40),
   @oper_id	NVARCHAR (40),
   @seq_no INT,
   @is_manual int,
   @spare1 nvarchar(40),-- correlation id  
   @corr_step int
AS

BEGIN
	 select top 1 fat,moist_per as moist,pH, l, c, h, moist_water as water
	 from ofi_cb_sample_results(nolock) 
	 where wo_id=@wo_id and oper_id =@oper_id and seq_no=@seq_no and (is_manual is null OR  is_manual=@is_manual ) 
	 and spare1=@spare1	and correction_step = @corr_step
END

