      			--The source entity and the target entity are different. Verify whether the source entity and the destination entity are configured as indistinguishable lots.
      			SELECT @from_ent_indistinct = 0, @to_ent_indistinct = 0
      
      			--Get the indistinguishable_lots capability for the source entity.
      			SELECT @from_ent_indistinct = indistinguishable_lots FROM storage_exec WITH (NOLOCK)
      			WHERE ent_id = @from_ent_id
      
      			--Get the indistinguishable_lots capability for the destination entity.
      			SELECT @to_ent_indistinct = indistinguishable_lots FROM storage_exec WITH (NOLOCK)
      			WHERE ent_id = @to_ent_id
      
      			--Verify if both the source and the destination entities are configured as indishtinguishable lots
      			--If yes, then prorate the quantity in the source inventory location
      			--and transfer the prorated quantity to the destination location.
      			IF (@from_ent_indistinct = 1 AND @to_ent_indistinct = 1) BEGIN
      				EXEC sp_U_Item_Inv_ApplyIndistLots  @from_row_id, NULL, NULL, NULL, NULL,NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
      													NULL, @to_ent_id, NULL, @in_to_grade_cd, @in_to_status_cd, @from_ent_id, @transfer_qty,
      													@transfer_qty_erp, NULL, NULL, NULL, NULL, NULL, NULL, NULL,NULL, NULL, NULL, NULL,
      													@in_to_oper_id, @in_to_seq_no, @time_zone_bias_value, 1, @in_to_uom_id, @in_to_expiry_date, @in_to_expiry_date_tz,
      													@in_transfer_option, @in_transfer_comments
      			END
      			-- Fix for CR L00096446/HF-1602
      			-- ELSE IF (@from_ent_indistinct <> @to_ent_indistinct) BEGIN
      			ELSE IF (@from_ent_indistinct = 1 AND @to_ent_indistinct = 0) BEGIN
      				--One of the entity here is configured as  indistinguishable lots and the other is not configured as indistinguishable lots.
      				--Do not allow inventory transfers if both does not have the same configuration, throw an error.
      				--SET @err_msg = 'The item(s) cannot be transferred to the destination entity, because the source entitity''s:%1 setup for indistinguishable lots is different than the destination entity''s:%2 setup.{5009},' + @from_ent_name + ',' + @to_ent_name
      				SET @err_msg = 'The item(s) cannot be transferred to the destination entity, because lots or items stored in/on the source entity (%1) are indistinguishable whereas lots/items stored in/on the destination entity (%2) are distinguishable.{5009},' + @from_ent_name + ',' + @to_ent_name
      				RAISERROR(@err_msg, 16, 1)
      				RETURN
      			END
      			ELSE
      				--The source and the destination entities are not configured as indistinguishable lots,
      				--delegate to this 'sp_U_Item_Inv_TransferQty' stored procedure which does the inventory transfer.
      				EXEC sp_U_Item_Inv_TransferQty	@from_row_id, @from_last_edit_at, @transfer_qty, @transfer_qty_erp, @in_to_ent_id,
      												@in_to_item_id, @in_to_lot_no, @in_to_sublot_no, @in_to_grade_cd, @in_to_status_cd,
      												@in_to_uom_id, @in_to_expiry_date,@in_to_expiry_date_tz,@in_to_expiry_date_utc, @in_to_wo_id, @in_to_oper_id, @in_to_seq_no,
      												@in_transfer_option, @in_move_inv_to_dwnstrm_job, @in_transfer_comments, @in_log_transfer,
      												@time_zone_bias_value
      		END
      		ELSE	-- The source and the destination entity are same.
      			--just delegate to this 'sp_U_Item_Inv_TransferQty' stored procedure which does the inventory transfer.
      				EXEC sp_U_Item_Inv_TransferQty  @from_row_id, @from_last_edit_at, @transfer_qty, @transfer_qty_erp, @in_to_ent_id,
      												@in_to_item_id, @in_to_lot_no, @in_to_sublot_no, @in_to_grade_cd, @in_to_status_cd,
      												@in_to_uom_id, @in_to_expiry_date,@in_to_expiry_date_tz,@in_to_expiry_date_utc, @in_to_wo_id, @in_to_oper_id, @in_to_seq_no,
      												@in_transfer_option, @in_move_inv_to_dwnstrm_job, @in_transfer_comments, @in_log_transfer,
      												@time_zone_bias_value
      
      			--Updating same location with multiple lots
      				UPDATE item_inv
      				SET grade_cd = @in_to_grade_cd,
      					status_cd = @in_to_status_cd,
      					expiry_date = @in_to_expiry_date,
      					wo_id = @in_to_wo_id,
      					oper_id = @in_to_oper_id,
      					seq_no = @in_to_seq_no
      				WHERE item_id = @in_to_item_id
      					AND ent_id = @in_to_ent_id*/

		  --0.1 Deleting Record when the qty_left is 0 after reclassification


      DELETE FROM item_inv
      WHERE qty_left = 0
        AND ent_id = @in_to_ent_id ;




		-- v0.5 BS
		--CLOSE item_inv_loc
		--DEALLOCATE item_inv_loc
		-- v0.5 BE
    END ;
		EXEC sp_U_Storage_Exec @ent_id = @from_ent_id,
							   @type = NULL,
							   @max_capacity = @capacity,
							   @status = @status,
							   @uom_id = @in_to_uom_id,
							   @tare_uom_id = @tare_uom_id,
							   @tare = @tare,
							   @auto_del_zero_inv = @auto_del_zero_inv,
							   @allow_neg_qty = @allow_neg_qty,
							   @scannable_id = @scannable_id,
							   @allow_multiple_items = @allow_multiple_items,
							   @allow_multiple_lots = @allow_multiple_lots,
							   @movable = @movable,
							   @storage_ent_id = @storage_ent_id,
							   @allow_dirty_state = @allow_dirty_state,
							   @log_state_transitions = @log_state_transitions,
							   @indistinguishable_lots = @indistinguishable_lots,
							   @unlisted = @unlisted,
							   @spare_int1 = @spare_int1,
							   @spare_int2 = @spare_int2,
							   @spare_int3 = @spare_int3,
							   @spare_int4 = @spare_int4,
							   @spare1 = @spare1,
							   @spare2 = @spare2,
							   @spare3 = @spare3,
							   @spare4 = @spare4,
							   @last_edit_comment = @last_edit_comment,
							   @last_edit_at = @last_edit_at ;



	END TRY 

	  BEGIN CATCH
		EXEC sp_U_Storage_Exec @ent_id = @from_ent_id,
							   @type = NULL,
							   @max_capacity = @capacity,
							   @status = @status,
							   @uom_id = @in_to_uom_id,
							   @tare_uom_id = @tare_uom_id,
							   @tare = @tare,
							   @auto_del_zero_inv = @auto_del_zero_inv,
							   @allow_neg_qty = @allow_neg_qty,
							   @scannable_id = @scannable_id,
							   @allow_multiple_items = @allow_multiple_items,
							   @allow_multiple_lots = @allow_multiple_lots,
							   @movable = @movable,
							   @storage_ent_id = @storage_ent_id,
							   @allow_dirty_state = @allow_dirty_state,
							   @log_state_transitions = @log_state_transitions,
							   @indistinguishable_lots = @indistinguishable_lots,
							   @unlisted = @unlisted,
							   @spare_int1 = @spare_int1,
							   @spare_int2 = @spare_int2,
							   @spare_int3 = @spare_int3,
							   @spare_int4 = @spare_int4,
							   @spare1 = @spare1,
							   @spare2 = @spare2,
							   @spare3 = @spare3,
							   @spare4 = @spare4,
							   @last_edit_comment = @last_edit_comment,
							   @last_edit_at = @last_edit_at ;


	  END CATCH 
	  -------------Audit Trail------------------
	  BEGIN TRY
	  BEGIN
	   --Print 'Lavkesh'
		 DECLARE @auditTrailParameters ofi_AUDITTRAILPARAMETERS
		  ,@strModuleName nvarchar(80) = 'INV_SUOVERVIEW'
             ,@strFunctionName nvarchar(80) = 'UI'
             ,@strActivityMsg nvarchar(200) = 'EDIT'
			 ,@strCommentMsg nvarchar(200) = 'Reclassified the Inventory'
			 ,@iRowId  int
			 ,@step_name nvarchar(40) = 'Reclassify'
			 ,@keyField1             NVARCHAR(80)              = NULL
			 ,@keyField2             NVARCHAR(80)              = NULL
			 ,@keyField3             NVARCHAR(80)              = NULL
			 ,@keyField4             NVARCHAR(80)              = NULL
			 ,@keyField5             NVARCHAR(80)              = NULL
			-- select @from_row_id as lkDate
			 declare @rowid int,@itemid nvarchar(50),@grade_cd int,@statuscd int,@entid int,@qty nvarchar(50),@last_edit_by nvarchar(50)
			 select @itemid=item_id,@grade_cd=grade_cd,@statuscd=status_cd,@entid=ent_id,@qty=qty from @iteminv 

			 select @rowid=row_id,@last_edit_by=last_edit_by from item_inv with(nolock) 
			 where item_id=@itemid and ent_id= @entid
			-- SELECT @last_edit_by = user_desc from user_name with(nolock) where user_id=@last_edit_by

		 DELETE from @auditTrailParameters
		 INSERT INTO @auditTrailParameters(row_id, field_name, field_value)values(@rowid,'@ent_id',@entid)
		 INSERT INTO @auditTrailParameters(row_id, field_name, field_value)values(@rowid,'@item_id',@itemid)
		 INSERT INTO @auditTrailParameters(row_id, field_name, field_value)values(@rowid,'@grade_cd',@grade_cd)
		 INSERT INTO @auditTrailParameters(row_id, field_name, field_value)values(@rowid,'@state_cd',@statuscd)
		 INSERT INTO @auditTrailParameters(row_id, field_name, field_value)values(@rowid,'@qty_left',@qty)
		-- select @strFunctionName as fun,@strModuleName as module,@strActivityMsg as cmt

		-- select *from @auditTrailParameters
		 EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName
											,@function_id = @strFunctionName
											,@auditTrailParameters = @auditTrailParameters
											,@keyField1 = NULL
											,@keyField2 = NULL
											,@keyField3 = NULL
											,@keyField4 = NULL
											,@keyField5 = NULL
											,@user_id = @last_edit_by
											,@activity = @strActivityMsg
											,@audit_category = 'Info'
											,@comments = @strCommentMsg

		END
	  END TRY
	  BEGIN CATCH
		--print 'Error on audit'
		--set @resultset =0; set @resultcode=ERROR_MESSAGE();
		--select @resultcode
	  END CATCH;

END ;

CREATE PROCEDURE [dbo].[sp_I_Oper_Ent_Link]
  (@process_id nvarchar(40) ,
   @oper_id nvarchar(40) ,
   @ent_id int ,
   @est_fixed_lab float ,
   @est_lab_rate float ,
   @est_setup_time float ,
   @est_teardown_time float ,
   @est_prod_rate float ,
   @prod_uom int,
