			@value9  FLOAT,
			@value10 FLOAT,
			@value11 FLOAT,
			@value12 FLOAT,
			@value13 FLOAT,
			@value14 FLOAT,
			@value15 FLOAT,
			@value16 FLOAT,
			@value17 FLOAT,
			@value18 FLOAT,
			@value19 FLOAT,
			@value20 FLOAT,
			@value21 FLOAT,
			@value22 FLOAT,
			@value23 FLOAT,
			@value24 FLOAT,
			@value25 FLOAT,
			@value26 FLOAT,
			@value27 FLOAT,
			@value28 FLOAT,
			@value29 FLOAT,
			@value30 FLOAT,
			@value31 FLOAT,
			@measured_fat FLOAT,
			@measured_ph FLOAT,
			@measured_moisture FLOAT,
			--@wo_id nvarchar(40),
			--@oper_id nvarchar(40),
			--@seq_no int,
			--@item_id nvarchar(40),
			@actual_wt float,
			@target_wt float,
			@base_dosing nvarchar(max),
			@allowed_comp nvarchar(max),
			@min_dosing_qty_kg float,
			@additives nvarchar(max),
			@rcpLCH nvarchar(max),
			@rcp_moist float, 
			@rcp_fat float, 
			@rcp_fat_min float,
			@rcp_fat_max float, 
			@rcp_ph float, 
			@rcp_minimize_x nvarchar(10), 
			@rcp_ph_deviation float, 
			@rcpWLCH nvarchar(100),
			@rcpXLCH nvarchar(100),
			@cakeComponents nvarchar(max),
			@X_TRISTIMULUS nvarchar(max), 
			@Y_TRISTIMULUS nvarchar(max),
			@Z_TRISTIMULUS nvarchar(max),
			@x_normalize nvarchar(50),
			@y_normalize nvarchar(50),
			@z_normalize nvarchar(50),
			@sat_thresold nvarchar(50),
			@prev_dosing_step int,
			@qty_prod float
		
	DECLARE @temp_cons TABLE(	itemid nvarchar(40), 
								qty_con float
							)

	-- v0.2 FIX hardcoded attr_id
	DECLARE @item_group_attr_id INT
	SELECT @item_group_attr_id = a.attr_id
	FROM attr a WITH (NOLOCK)
	WHERE a.attr_desc = 'ItemGroup'
		AND a.attr_grp = 1 -- 1 is item


	INSERT INTO @result
	SELECT  c.spare1 AS char_name -- v0.02.02 FIX for interfacing with LIMS
			--c.char_name,
			,sck.mean
	FROM sample_char_link sck WITH (NOLOCK)				 
		INNER JOIN characteristic c WITH (NOLOCK)
				ON sck.char_id = c.char_id 
	WHERE sck.sample_id = @sample_id

	SELECT @value1 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL400'
	
	SELECT @value2 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL410'

	SELECT @value3 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL420'

	SELECT @value4 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL430'

	SELECT @value5 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL440'

	SELECT @value6 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL450'

	SELECT @value7 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL460'

	SELECT @value8 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL470'

	SELECT @value9 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL480'

	SELECT @value10 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL490'

	SELECT @value11 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL500'

	SELECT @value12 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL510'

	SELECT @value13 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL520'

	SELECT @value14 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL530'

	SELECT @value15 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL540'

	SELECT @value16 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL550'

	SELECT @value17 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL560'

	SELECT @value18 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL570'

	SELECT @value19 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL580'

