	WHERE  char_name = 'CLIWREFL660'

	SELECT @value28 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL670'

	SELECT @value29 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL680'

	SELECT @value30 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL690'

	SELECT @value31 = mean
	FROM   @result
	WHERE  char_name = 'CLIWREFL700' 

	SELECT @measured_fat = mean
	FROM   @result
	WHERE  char_name = 'FAT' 

	SELECT @measured_moisture = mean
