			  '"640":' + TRY_CONVERT(NVARCHAR(40),CLIWREFL640) + ',' +
			  '"650":' + TRY_CONVERT(NVARCHAR(40),CLIWREFL650) + ',' +
			  '"660":' + TRY_CONVERT(NVARCHAR(40),CLIWREFL660) + ',' +
			  '"670":' + TRY_CONVERT(NVARCHAR(40),CLIWREFL670) + ',' +
