			  '"690":' + TRY_CONVERT(NVARCHAR(40),CLIWREFL690) + ',' +
			  '"700":' + TRY_CONVERT(NVARCHAR(40),CLIWREFL700) + '}}'
				 -- v02.01 modified to SAP BOM
				FROM ofi_wo_item_ext jb WITH (NOLOCK) -- v2.01 MOD: --job_bom jb WITH (NOLOCK)
					--inner join item_inv	 iv on j.item_id=iv.item_id	
