															AND ia.attr_id = @item_group_attr_id
					INNER JOIN cakeblend.cake_masterdata cc WITH (NOLOCK) ON jb.item_id = cc.item_id -- MOD v0.02.04 new table
					WHERE jb.wo_id = @wo_id 
						--AND jb.oper_id = @oper_id 
						--AND jb.seq_no = @seq_no
						AND jb.bom_pos > 0
				FOR XML PATH('')
			 ), 1, 1, '') +']'

		
	SELECT 	@rcpLCH = '['+convert(nvarchar(40),l_target) +','+convert(nvarchar(40),c_target)+','+convert(nvarchar(40),h_target)+']',
			@rcp_moist = TRY_CONVERT(NVARCHAR(40),moisture_target),
