/*
-- ===========================================================================================
-- Name:  [sp_U_ofi_aut_int_buff_GetNextRow]
-- Description: Used to get the next row from the interface buffer table
--
-- Usage: For AUT interface to get the next unprocessed the record. Exec from parent SPs.
-- ===========================================================================================
-- Version	Author  Date (yyyy-MM-dd) 	Change description
-- 0.01.00	JSC   	2025-04-15   		CR512: Initial version.
-- 0.01.01	JSC		2025-05-22			CR512: Change mod date to UTC
-- 0.01.02	JSC		2025-10-06			Avoid Page LOCKS on updates
-- ===========================================================================================*/
-- Optimized GetNextRow with index-aligned ORDER BY
-- Get and Update Procedure
CREATE        PROCEDURE [dbo].[sp_U_ofi_aut_int_buff_GetNextRow]
    @InterfaceType NVARCHAR(15),
    @ObjectName NVARCHAR(80),
    @ID INT = -1 OUTPUT,
    @Data NVARCHAR(4000) = NULL OUTPUT,
    @ErrorCode INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT OFF;
   
    SET @Data = NULL;
    SET @ErrorCode = 0;

    DECLARE @TranCounter INT = @@TRANCOUNT;
	DECLARE @TranName NVARCHAR(32) =  CAST(RIGHT(OBJECT_NAME(@@PROCID),28) AS NVARCHAR(28));
    DECLARE @SavePointName NVARCHAR(32) = CAST(RIGHT(OBJECT_NAME(@@PROCID),28) AS NVARCHAR(28)) + N'_' + CAST(@@NESTLEVEL AS NVARCHAR(3));

    BEGIN TRY
        IF @TranCounter = 0
            BEGIN TRANSACTION @TranName;
        ELSE
            SAVE TRANSACTION @SavePointName;

        ;WITH NextRow AS (
            SELECT TOP (1) Id, [Data] 
            FROM dbo.ofi_aut_interface_buffer WITH (UPDLOCK, READPAST)
            WHERE [Status] = 0
              AND ObjectName = @ObjectName
              AND InterfaceType = @InterfaceType
            ORDER BY CurrentTimestamp ASC
        )
        UPDATE b WITH (ROWLOCK) -- MOD v1.03
        SET @ID = b.[Id],
            @Data = b.[Data],
            b.[Status] = 1,
            b.Comment = 'Processing',
            b.StatusTimestamp = GETUTCDATE() -- MOD
        FROM dbo.ofi_aut_interface_buffer b
        INNER JOIN NextRow nr ON b.Id = nr.Id;

        IF @TranCounter = 0
            COMMIT TRANSACTION @TranName;

		RETURN;
    END TRY
    BEGIN CATCH
        SET @ErrorCode = ERROR_NUMBER();
		SET @ID = -1;


		DECLARE @error INT, @message VARCHAR(4000), @xstate INT;
        SELECT @error = ERROR_NUMBER(), @message = ERROR_MESSAGE(), @xstate = XACT_STATE();
				PRINT 'errror ' + CAST(@error as varchar(32))
		PRINT 'message ' + @message
		PRINT 'xstate' + CAST (@xstate as varchar(32))
				PRINT 'TranNAme: ' + @TranName
		PRINT 'SavePointName: ' + @SavePointName
		PRINT 'TranCounter ' + CAST(@TranCounter as varchar(32))
        IF @xstate = -1
            ROLLBACK TRANSACTION @TranName;
        IF @xstate = 1 and @TranCounter = 0
            ROLLBACK TRANSACTION @TranName
        IF @xstate = 1 and @TranCounter > 0
            ROLLBACK TRANSACTION @SavePointName;
    END CATCH
END;

--===========================================================================================
-- Name:    [sp_U_ofi_SULowSignal]
-- Description:Storage Unit Low Level Signal Update
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  AJEET       2022-09-14		Intial Version
-- 0.01.01  YG          2024-02-09		Update Script Body Comment and Missing No Lock
-- 0.02.00  YG          2024-03-12		Added Good Consumption (Item Reason), Validation for non running job, Ensure qty_left has value for empty inventory  
-- 0.03.00  YG          2024-03-21		Update logic how to get latest consumption and disable scrap logic
-- 0.04.00  YG			2024-05-10		Major Update
-- 0.05.00	MC			2025-07-25		Adding fg_lot/sublot to item consumted because of low level in silo
--
-- Exec sp_U_ofi_SULowSignal '500BN003'
-- =============================================
CREATE   PROCEDURE [dbo].[sp_U_ofi_SULowSignal__BAK251020] @SU_Name NVARCHAR(40)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET nocount ON;

	-- Declare variable
	DECLARE @storage_ent_id        INT,
		  @cons_lot_no           NVARCHAR(40) = NULL,
		  @cons_sublot_no        NVARCHAR(40) = NULL,
		  @cons_qty              FLOAT = 0,
		  @avl_qty               FLOAT = 0,
		  @consumed_qty          FLOAT = 0,
		  @job_pos               INT = 0,
		  @bom_pos               INT = 0,
		  @date_time_UTC         DATETIME = Getutcdate(),
		  @return_value          INT,
		  @row_id                INT32,
		  @minID                 INT,
		  @typeOfCons            NVARCHAR(20) = 'FIFO',
		  @process_id            NVARCHAR(30),
		  @process_type          NVARCHAR(30),
		  @prod_info             NVARCHAR(4000),
		  @prod_item_id          NVARCHAR(40),
		  @prod_date_time_UTC    DATETIME,
		  @user_id               NVARCHAR(40) = NULL,
		  @wo_state              INT,
		  @ent_id                INT,
		  @qty_left              FLOAT,
		  @su_level_threshold    INT,
		  @plant_level_threshold INT,
		  @final_threshold       INT,
		  @wo_id                 NVARCHAR(40),
		  @Out                   INT,
		  @inv_item_id           NVARCHAR(40),
		  @item_id               NVARCHAR(40),
		  @target_sched_ent_id   INT,
		  @cons_ent_id           INT,
		  @oper_id               NVARCHAR(40),
		  @seq_no                INT,
		  @Counter               INT,
		  @iterate               INT = 1,
		  @last_consumed_date	 DATETIME,
		  @lot_no				 NVARCHAR(40) = NULL,
		  @sublot_no			 NVARCHAR(40) = NULL,
		  @job_state			 INT,
		  @grade_cd				 INT,
		  @status_cd 			 INT,
		  @uom_desc				 NVARCHAR(40),
		  @isOrderClosed		 INT = 0

	-- Declare Audit Trail
	DECLARE @auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			 @iRowId int,
			 @audit_trail INT = 1,
			 @grade_desc NVARCHAR(100),
			 @state_desc NVARCHAR(100),
			 @user_name NVARCHAR(100),
             @strModuleName nvarchar(80) = 'INV_LowLevelAdjustment',
             @strFunctionName nvarchar(80) = 'UI',
             @strActivityMsg nvarchar(200) = 'ADD',
             @strCommentMsg nvarchar(200) 
		  
	DECLARE @TempInv TABLE
		(
		   id         INT IDENTITY(1, 1) PRIMARY KEY,
		   ent_id     INT,
		   item_id    NVARCHAR(40),
		   lot_no     NVARCHAR(40),
		   sub_lot_no NVARCHAR(40),
		   qty        FLOAT,
		   row_id		INT
		)
	
	DECLARE @defaultUoMDesc NVARCHAR(20) = 'KG',
		  @defaultUoMId   INT

	--00.05.00
	Declare @fg_sublot_no nvarchar(40)
	Declare @fg_lot_no nvarchar(40)

	-- Get User Id
	EXEC Sp_s_db_status_getaudtrailusr
		@user_id output, NULL

	SET @user_name = @user_id

	-- Get Ent Id from SP Parameter
	SELECT @ent_id = ent_id
	FROM   ent (nolock)
	WHERE  ent_name = @SU_Name

	-- Get Default UoM Desc
	SELECT @defaultUoMDesc = attr_value
	FROM   ent_attr WITH (nolock)
	WHERE  ent_id = @ent_id
		 AND attr_id = (SELECT attr_id
						FROM   attr WITH (nolock)
						WHERE  attr_desc = 'DefaultStorageUoM'
							   AND attr_grp = 2)

	SET @defaultUoMDesc = Isnull(@defaultUoMDesc, 'KG')

	-- v0.02.00 Get Good Consumption (Item Reason)
	DECLARE @strGoodConsReas NVARCHAR(40) = 'Good Consumption',
			@intGoodConsReas INT = NULL

	SELECT @intGoodConsReas = reas_cd
	FROM   item_reas WITH (nolock)
	WHERE  reas_desc = @strGoodConsReas

	SET @intGoodConsReas = Isnull(@intGoodConsReas, 1)

	-- Get Default UoM Id
	SELECT @defaultUoMId = uom_id
	FROM   uom WITH (nolock)
	WHERE  description = @defaultUoMDesc

	-- Get Current Qty on the Silo
	SELECT @qty_left = Sum(qty_left),
		 @inv_item_id = Max(item_id)
	FROM   item_inv (nolock)
	WHERE  ent_id = @ent_id

	-- PRINT @qty_left

	-- Get Plant or Storage threshold
	SELECT @su_level_threshold = CONVERT(INT, Replace(ea.attr_value, ',', ''))
	FROM   ent_attr (nolock) ea
		 -- v0.02.00 refine the logic when taking value from nvarchar attr value
		 JOIN attr (nolock) a
		   ON ea.attr_id = a.attr_id
	WHERE  ea.ent_id = @ent_id
		 AND a.attr_desc = 'StorageUnitThreshold'

	-- PRINT @su_level_threshold

	SELECT @plant_level_threshold = CONVERT(INT, Replace(ea.attr_value, ',',''))
	FROM   ent_attr (nolock) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
		 JOIN attr (nolock) a
		   ON ea.attr_id = a.attr_id
	WHERE  ea.ent_id = (SELECT TOP 1 ent_id
					  FROM   ent (nolock)
					  WHERE  parent_ent_id IS NULL
					  ORDER  BY ent_id)
		 AND a.attr_desc = 'StorageUnitThreshold'

	-- Convert Qty into Default UoM
	SELECT @qty_left = dbo.[Fn_ofi_convertqtybyitemidanduom](@inv_item_id,
					 @qty_left,
							uom_id,
										@defaultUoMId, NULL, NULL, NULL,
					 NULL)
	FROM   item WITH (nolock)
	WHERE  item_id = @inv_item_id

	-- If the Silo level threshold is missing then take the plan level threshold
	IF ( @su_level_threshold = 0 )
	BEGIN
		SET @final_threshold = @plant_level_threshold
	END
	ELSE
	BEGIN
		SET @final_threshold = @su_level_threshold
	END

	-- v0.02.00 Ensure qty has value even no inventory
	SET @qty_left = Isnull(@qty_left, 0.00)

	-- if silo qty less than the thresshold
	IF ( @qty_left < @final_threshold AND @qty_left > 0 ) -- v0.02.00 Add validation qty must more than 0
	BEGIN
		-- Get last consumed order
		SELECT TOP 1 @item_id = iv.item_id, 
			@lot_no = iv.lot_no, 
			@sublot_no = iv.sublot_no, 
			@fg_lot_no = ic_max.fg_lot_no,			--00.05.00 select fg_lot/sublot_no from last consumed order
			@fg_sublot_no = ic_max.fg_sublot_no,	--00.05.00
			@last_consumed_date = ic_max.max_id,
			@wo_id = ic_max.wo_id,
			@oper_id = ic_max.oper_id,
			@seq_no = ic_max.seq_no,
			@job_state = j.state_cd,
			@target_sched_ent_id = j.target_sched_ent_id,
			@job_pos = je.job_pos,
			@bom_pos = jb.bom_pos
		FROM 
			item_inv iv WITH (NOLOCK)
		LEFT JOIN 
			(SELECT 
				 item_id, 
				 lot_no, 
				 sublot_no,
				 fg_lot_no,		--00.05.00
				 fg_sublot_no,	--00.05.00
				 from_ent_id,
				 wo_id,
				 oper_id,
				 seq_no,
				 MAX(last_edit_at) AS max_id
			 FROM 
				 item_cons WITH (NOLOCK)
			 GROUP BY 
				 item_id, 
				 lot_no, 
				 sublot_no,
				 fg_lot_no,		--00.05.00
				 fg_sublot_no,	--00.05.00
				 from_ent_id,
				 wo_id,oper_id,seq_no) AS ic_max
		ON 
			iv.item_id = ic_max.item_id 
			AND iv.lot_no = ic_max.lot_no 
			AND iv.sublot_no = ic_max.sublot_no
			AND iv.ent_id= ic_max.from_ent_id
		LEFT JOIN job_exec je WITH (NOLOCK) ON ic_max.wo_id = je.cur_wo_id
						  AND ic_max.oper_id = je.cur_oper_id
						  AND ic_max.seq_no = je.cur_seq_no
		LEFT JOIN job j WITH (NOLOCK) ON ic_max.wo_id = j.wo_id
						  AND ic_max.oper_id = j.oper_id
						  AND ic_max.seq_no = j.seq_no
		LEFT JOIN job_bom jb WITH (NOLOCK) ON ic_max.wo_id = jb.wo_id
						  AND ic_max.oper_id = jb.oper_id
						  AND ic_max.seq_no = jb.seq_no
						  AND iv.item_id = jb.item_id
						  AND jb.bom_pos > 0
		WHERE iv.ent_id = @ent_id
		ORDER BY max_id DESC

		-- Ensure order selected is not closed
		SELECT @wo_state = state_cd
		FROM   wo WITH (nolock)
		WHERE  wo_id = @wo_id

		IF ( @wo_state = 3 ) -- 3 = Closed
		BEGIN
			/*
			SET @Out = 2

			SELECT @Out    AS [Out],
				   @ent_id AS EntId,
				   @wo_id  AS WoId

			RETURN 
			*/
			SET @isOrderClosed = 1
		END
			
		-- check the running job on silo and assign qty_left to it
		IF ( @wo_id IS NOT NULL AND @job_state = 3 AND @isOrderClosed = 0) 
		BEGIN
			PRINT 'WoId is running'
			-- Get bom pos from selected order 
			SELECT TOP 1 @bom_pos = jb.bom_pos
			FROM   job_bom (nolock) jb
			WHERE  jb.wo_id = @wo_id
				 AND jb.oper_id = @oper_id
				 AND jb.seq_no = @seq_no
				 AND jb.item_id = @item_id;

			INSERT INTO @TempInv
					  (ent_id,
					   item_id,
					   lot_no,
					   sub_lot_no,
					   qty,
					   row_id)
			SELECT iv.ent_id,
				 iv.item_id,
				 iv.lot_no,
				 iv.sublot_no,
				 qty_left,
				 row_id
			FROM   item_inv (nolock) iv
			WHERE  ent_id = @ent_id
							AND iv.item_id IN (SELECT item_id
												FROM   job_bom (nolock) jb
												WHERE  jb.wo_id = @wo_id
													   AND jb.oper_id = @oper_id
													   AND jb.seq_no = @seq_no)

			SET @Counter = (SELECT Count(1) FROM @TempInv)
			
			IF EXISTS (select 1 from @TempInv)
			BEGIN
				WHILE ( @iterate <= @Counter )
				BEGIN
					SELECT @cons_lot_no = at.lot_no,
						   @cons_sublot_no = at.sub_lot_no,
						   @qty_left = at.qty,
						   @item_id = at.item_id,
						   @grade_cd = iv.grade_cd,
						   @status_cd = iv.status_cd,
						   @uom_desc = u.abbreviation
					FROM   @TempInv at
					LEFT JOIN item_inv iv WITH(NOLOCK) ON at.row_id = iv.row_id
					LEFT JOIN uom u WITH(NOLOCK) ON iv.uom_id = u.uom_id
					WHERE  id = @iterate

					EXEC @return_value = [dbo].[Sp_i_item_cons_addcons]
					  @session_id = NULL,
					  @event_time_local = NULL,
					  @user_id = @user_id,
					  @ent_id = @target_sched_ent_id,
					  @job_pos = @job_pos,
					  @bom_pos = @bom_pos,
					  @qty_cons = @qty_left,
					  @reas_cd = @intGoodConsReas,
					  @lot_no = @cons_lot_no,
					  @fg_lot_no = @fg_lot_no,	--00.05.00
					  @sublot_no = @cons_sublot_no,
					  @fg_sublot_no = @fg_sublot_no,	--00.05.00
					  @from_ent_id = @ent_id,
					  @item_id = @item_id,
					  @ext_ref = NULL,
					  @apply_scaling_factor = NULL,
					  @genealogy_id = NULL,
					  @upstream_event_id = NULL,
					  @segment_requirement_id = NULL,
					  @segment_response_id = NULL,
					  @comments ='Trigger with Low Signal-Consumed on running Job',
					  @spare1 = NULL,
					  @spare2 = NULL,
					  @spare3 = NULL,
					  @spare4 = NULL,
					  @created_at_utc = @date_time_UTC,
					  @row_id = @row_id output

					IF (@audit_trail = 1)
					BEGIN
						print 'Audit'
						DELETE @auditTrailParameters;
						SET @strCommentMsg  = 'Consumed on running Job - Order No : '+@wo_id+', Operation : '+@oper_id+', Seq No : '+CAST(@seq_no AS varchar)+', Silo Name :'+@SU_Name+', Reduced Qty :'+CAST(@qty_left AS varchar)+' '+@uom_desc
						
						INSERT INTO @auditTrailParameters (row_id, field_name, field_value)	values 
								 (@row_id,'@EntId',CONVERT(NVARCHAR(80),@ent_id)),
								(@row_id,'@ItemId',CONVERT(NVARCHAR(80),@item_id))
								,(@row_id,'@LotNo',CONVERT(NVARCHAR(80),@cons_lot_no))
								,(@row_id,'@SublotNo',CONVERT(NVARCHAR(80),@cons_sublot_no))
								,(@row_id,'@ReducedQty',CONVERT(NVARCHAR(80),@qty_left))
								,(@row_id,'@GradeCd',CONVERT(NVARCHAR(80),@grade_cd))
								,(@row_id,'@StateCd',CONVERT(NVARCHAR(80),@status_cd))
							
						 EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName,
												  @function_id = @strFunctionName,
												  @auditTrailParameters = @auditTrailParameters,
												  @user_id = @user_name,
												  @activity = @strActivityMsg,
												  @audit_category = 'Info',
												  @comments = @strCommentMsg
					 END

					SET @iterate = @iterate + 1
				END
			END

			DELETE FROM @TempInv
			
			SET @Out = 0
				
			SELECT @Out    AS [Out],
				   @ent_id AS EntId,
				   @wo_id  AS WoId
			RETURN
		END

		IF ( @wo_id IS NOT NULL AND @job_state IN (4,5) AND @isOrderClosed = 0) 
		BEGIN
			PRINT 'WoId is stopped/completed'
			
			INSERT INTO @TempInv
					  (ent_id,
					   item_id,
					   lot_no,
					   sub_lot_no,
					   qty,
					   row_id)
			SELECT iv.ent_id,
				 iv.item_id,
				 iv.lot_no,
				 iv.sublot_no,
				 qty_left,
				 row_id
			FROM   item_inv (nolock) iv
			WHERE  ent_id = @ent_id
				 AND iv.item_id IN (SELECT item_id
									FROM   job_bom (nolock) jb
									WHERE  jb.wo_id = @wo_id
										   AND jb.oper_id = @oper_id
										   AND jb.seq_no = @seq_no)

			SET @Counter = (SELECT Count(1) FROM   @TempInv)

			IF EXISTS (select 1 from @TempInv)
			BEGIN
				WHILE ( @iterate <= @Counter )
				BEGIN
					SELECT @cons_lot_no = at.lot_no,
						   @cons_sublot_no = at.sub_lot_no,
						   @qty_left = at.qty,
						   @item_id = at.item_id,
						   @grade_cd = iv.grade_cd,
						   @status_cd = iv.status_cd,
						   @uom_desc = u.abbreviation
					FROM   @TempInv at
					LEFT JOIN item_inv iv WITH(NOLOCK) ON at.row_id = iv.row_id
					LEFT JOIN uom u WITH(NOLOCK) ON iv.uom_id = u.uom_id
					WHERE  id = @iterate

					EXEC @return_value = [dbo].[Sp_i_item_cons_addconspostexec]
						@session_id = NULL,
						@user_id = @user_id,
						@ent_id = @target_sched_ent_id,
						@bom_pos = @bom_pos,
						@qty_cons = @qty_left,
						@wo_id = @wo_id,
						@oper_id = @oper_id,
						@seq_no = @seq_no,
						@shift_start_local = NULL,
						@shift_id = NULL,
						@item_id = @item_id,
						@reas_cd = @intGoodConsReas,
						@lot_no = @cons_lot_no,
						@fg_lot_no = @fg_lot_no,	--00.05.00
						@sublot_no = @cons_sublot_no,
						@fg_sublot_no = @fg_sublot_no,	--00.05.00
						@from_ent_id = @ent_id,
						@ext_ref = NULL,
						@genealogy_id = NULL,
						@upstream_event_id = NULL,
						@segment_requirement_id = NULL,
						@segment_response_id = NULL,
						@comments = 'Trigger with Low Signal-Consumed with last consumed job ',
						@spare1 = NULL,
						@spare2 = NULL,
						@spare3 = NULL,
						@spare4 = NULL,
						@created_at_utc = @date_time_UTC,
						@row_id = @row_id output,
						@time_zone_bias_value = NULL

					IF (@audit_trail = 1)
					BEGIN
						DELETE @auditTrailParameters;
						SET @strCommentMsg  = 'Consumed with last consumed job - Order No : '+@wo_id+', Operation : '+@oper_id+', Seq No : '+CAST(@seq_no AS varchar)+', Silo Name :'+@SU_Name+', Reduced Qty :'+CAST(@qty_left AS varchar)+' '+@uom_desc
						
						INSERT INTO @auditTrailParameters (row_id, field_name, field_value)	values 
								 (@row_id,'@EntId',CONVERT(NVARCHAR(80),@ent_id)),
								(@row_id,'@ItemId',CONVERT(NVARCHAR(80),@item_id))
								,(@row_id,'@LotNo',CONVERT(NVARCHAR(80),@cons_lot_no))
								,(@row_id,'@SublotNo',CONVERT(NVARCHAR(80),@cons_sublot_no))
								,(@row_id,'@ReducedQty',CONVERT(NVARCHAR(80),@qty_left))
								,(@row_id,'@GradeCd',CONVERT(NVARCHAR(80),@grade_cd))
								,(@row_id,'@StateCd',CONVERT(NVARCHAR(80),@status_cd))
							
						 EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName,
												  @function_id = @strFunctionName,
												  @auditTrailParameters = @auditTrailParameters,
												  @user_id = @user_name,
												  @activity = @strActivityMsg,
												  @audit_category = 'Info',
												  @comments = @strCommentMsg
					 END

					SET @iterate = @iterate + 1
				END	
			END

			DELETE FROM @TempInv
			
			SET @Out = 0
				
			SELECT @Out    AS [Out],
				   @ent_id AS EntId,
				   @wo_id  AS WoId
			RETURN
		END

		IF ( @wo_id IS NULL OR @isOrderClosed = 1)
		BEGIN
			PRINT 'No order is founded / order closed'

			INSERT INTO @TempInv
				(ent_id,
				 item_id,
				 lot_no,
				 sub_lot_no,
				 qty,
				 row_id)
			SELECT iv.ent_id,
				   iv.item_id,
				   iv.lot_no,
				   iv.sublot_no,
				   qty_left ,
				   row_id
			FROM   item_inv(nolock) iv
			WHERE  ent_id = @ent_id 

			IF EXISTS (select 1 from @TempInv)
			BEGIN
				SET @Counter = (SELECT Count(1) FROM   @TempInv)

				WHILE ( @iterate <= @Counter )
				BEGIN
					SELECT @cons_lot_no = at.lot_no,
						   @cons_sublot_no = at.sub_lot_no,
						   @qty_left = at.qty,
						   @item_id = at.item_id,
						   @grade_cd = iv.grade_cd,
						   @status_cd = iv.status_cd,
						   @uom_desc = u.abbreviation
					FROM   @TempInv at
					LEFT JOIN item_inv iv WITH(NOLOCK) ON at.row_id = iv.row_id
					LEFT JOIN uom u WITH(NOLOCK) ON iv.uom_id = u.uom_id
					WHERE  id = @iterate
			
					EXEC  @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
						@from_ent_id = @ent_id,
						@item_id = @item_id,
						@lot_no = @cons_lot_no,
						@sublot_no = @cons_sublot_no,
						@qty_cons = @qty_left,
						@reas_cd = @intGoodConsReas, 
						@grade_cd = @grade_cd,
						@status_cd = @status_cd,
						@user_id = @user_id,
						@wo_id = NULL,		--0.05.00 - to be implemented after CR00186839 implementing
						@oper_id = NULL,	--0.05.00 - to be implemented after CR00186839 implementing
						@seq_no = NULL,		--0.05.00 - to be implemented after CR00186839 implementing
						@shift_start_local = NULL,
						@fg_lot_no = @fg_lot_no,	--0.05.00
						@fg_sublot_no = @fg_sublot_no,	--0.05.00
						@item_scrapped = 1,
						@ent_id = @target_sched_ent_id, --0.05.00
						@shift_id = NULL,
						@qty_cons_erp = NULL,
						@ext_ref = NULL,
						@transaction_type = NULL,
						@genealogy_id = NULL,
						@upstream_event_id = NULL,
						@segment_requirement_id = NULL,
						@segment_response_id = NULL,
						@comments = 'Trigger with Low Signal, Scrap because of no order is founded Or order closed',
						@spare1 = NULL,
						@spare2 = NULL,
						@spare3 = NULL,
						@spare4 = NULL,
						@shift_start_utc = NULL,
						@time_zone_bias_value = NULL,
						@row_id = @row_id OUTPUT
			
					IF (@audit_trail = 1)
					BEGIN
						DELETE @auditTrailParameters;
						SET @strCommentMsg  = 'Scrap because of no order is founded Or order closed - Silo Name :'+@SU_Name+', Reduced Qty :'+CAST(@qty_left AS varchar)+' '+@uom_desc
						
						INSERT INTO @auditTrailParameters (row_id, field_name, field_value)	values 
								 (@row_id,'@EntId',CONVERT(NVARCHAR(80),@ent_id)),
								(@row_id,'@ItemId',CONVERT(NVARCHAR(80),@item_id))
								,(@row_id,'@LotNo',CONVERT(NVARCHAR(80),@cons_lot_no))
								,(@row_id,'@SublotNo',CONVERT(NVARCHAR(80),@cons_sublot_no))
								,(@row_id,'@ReducedQty',CONVERT(NVARCHAR(80),@qty_left))
								,(@row_id,'@GradeCd',CONVERT(NVARCHAR(80),@grade_cd))
								,(@row_id,'@StateCd',CONVERT(NVARCHAR(80),@status_cd))
							
						 EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName,
												  @function_id = @strFunctionName,
												  @auditTrailParameters = @auditTrailParameters,
												  @user_id = @user_name,
												  @activity = @strActivityMsg,
												  @audit_category = 'Info',
												  @comments = @strCommentMsg
					 END
			
					SET @iterate = @iterate + 1
				END
			END
			
			SET @Out = 0
				
			SELECT @Out    AS [Out],
				   @ent_id AS EntId,
				   @wo_id  AS WoId
			RETURN
		END
		
		SET @Out = 0
	END
	ELSE IF ( @qty_left = 0.00 ) --v0.02.00 Add checking if qty is 0
	BEGIN
		Print 'Qty is Zero'
		SET @Out = 3
		PRINT @Out
	END
	ELSE
	BEGIN
		Print 'Qty More Than Threshold'
		SET @Out = 1
		PRINT @Out
	END

	SELECT @Out    AS [Out],
		   @ent_id AS EntId,
		   @wo_id  AS WoId
END

