-- Description: Prpare Request payload to pass to Window service to calculate Cake blender prediction
--
-- Usage:       From which object this script is called.
-- ===========================================================================================
-- Version      Author                  Date (yyyy-MM-dd)       Change description
-- 0.01.00      AKM                       2022-12-08            Initial version.
-- 0.01.00		Shuvam					  2023-04-13			Extended this SP to prepare complete JSON to pass to Window service
-- 0.02.00		JSC						2025-09-23				CakeBlender FATs - Modified to pickup the latest sample with results (review status)
-- ===========================================================================================

CREATE PROCEDURE [dbo].[sp_S_OFI_CB_Prep_MQTT_Msg_Payload_bck20251023] 
	--@sample_id nvarchar(40) =1014
	@wo_id NVARCHAR(40) = null,
	@oper_id NVARCHAR(40) = null,
	@seq_no INT = null,
	@item_id	NVARCHAR(40) = null

AS

BEGIN

	DECLARE @sample_id nvarchar(40)
	
	SELECT TOP 1 @sample_id = s.sample_id
	FROM   [dbo].[sample] s WITH (NOLOCK)
	WHERE  s.wo_id = @wo_id
		   AND s.oper_id = @oper_id
		   AND s.seq_no = @seq_no
		   AND s.item_id = @item_id
		   AND s.sample_status in (6, 7) -- Complete or complete late (avoid failed requests)
	ORDER BY s.last_edit_at DESC 

	DECLARE @run_ent_id INT
	
	SELECT @run_ent_id = j.run_ent_id
	FROM job j WITH (NOLOCK)
	WHERE j.wo_id = @wo_id
		AND j.oper_id = @oper_id
		AND j.seq_no = @seq_no

	DECLARE @result TABLE (	char_name NVARCHAR(40),
							mean      FLOAT
						)

	DECLARE @value1  FLOAT,
			@value2  FLOAT,
			@value3  FLOAT,
			@value4  FLOAT,
			@value5  FLOAT,
			@value6  FLOAT,
			@value7  FLOAT,
			@value8  FLOAT,
			@value9  FLOAT,
			@value10 FLOAT,
			@value11 FLOAT,
			@value12 FLOAT,
			@value13 FLOAT,
			@value14 FLOAT,
			@value15 FLOAT,
			@value16 FLOAT,
			@value17 FLOAT,
			@value18 FLOAT,
			@value19 FLOAT,
			@value20 FLOAT,
			@value21 FLOAT,
			@value22 FLOAT,
			@value23 FLOAT,
			@value24 FLOAT,
			@value25 FLOAT,
			@value26 FLOAT,
			@value27 FLOAT,
			@value28 FLOAT,
			@value29 FLOAT,
			@value30 FLOAT,
			@value31 FLOAT,
			@measured_fat FLOAT,
			@measured_ph FLOAT,
			@measured_moisture FLOAT,
			--@wo_id nvarchar(40),
			--@oper_id nvarchar(40),
			--@seq_no int,
			--@item_id nvarchar(40),
			@actual_wt float,
			@target_wt float,
			@base_dosing nvarchar(max),
			@allowed_comp nvarchar(max),
			@min_dosing_qty_kg float,
			@additives nvarchar(max),
			@rcpLCH nvarchar(max),
			@rcp_moist float, 
			@rcp_fat float, 
			@rcp_fat_min float,
			@rcp_fat_max float, 
			@rcp_ph float, 
			@rcp_minimize_x nvarchar(10), 
			@rcp_ph_deviation float, 
			@rcpWLCH nvarchar(100),
			@rcpXLCH nvarchar(100),
			@cakeComponents nvarchar(max),
			@X_TRISTIMULUS nvarchar(max), 
			@Y_TRISTIMULUS nvarchar(max),
			@Z_TRISTIMULUS nvarchar(max),
			@x_normalize nvarchar(50),
			@y_normalize nvarchar(50),
			@z_normalize nvarchar(50),
			@sat_thresold nvarchar(50),
			@prev_dosing_step int,
			@qty_prod float
		
	DECLARE @temp_cons TABLE(	itemid nvarchar(40), 
								qty_con float
							)

	-- v0.02 REMOVED as it is irrelevant
	-- SELECT  @wo_id=wo_id,
			-- @oper_id=oper_id, 
