	FROM   @result
	WHERE  char_name = 'Moisture' 

	SELECT @measured_ph = mean
	FROM   @result
	WHERE  char_name = 'Ph'


	SELECT @min_dosing_qty_kg = ea.attr_value 
	FROM attr a WITH (NOLOCK)
		JOIN ent_attr ea WITH (NOLOCK) ON a.attr_id = ea.attr_id
	WHERE a.attr_desc = 'Min_Dosing_Qty_Kg'
		AND ea.ent_id = @run_ent_id

	IF @min_dosing_qty_kg IS NULL
	BEGIN
		SELECT TOP 1 @min_dosing_qty_kg = ea.attr_value 
		FROM attr a WITH (NOLOCK)
			JOIN ent_attr ea WITH (NOLOCK) ON a.attr_id = ea.attr_id
		WHERE a.attr_desc = 'Min_Dosing_Qty_Kg'
		ORDER by ea.ent_id ASC
	END
	
	SELECT @allowed_comp ='['+ STUFF((
			 SELECT Distinct  ',' + '"' + iv.item_id + '"' 
				FROM job_bom j
					INNER JOIN item_inv(nolock)	 iv on j.item_id=iv.item_id	
					INNER JOIN item_attr(nolock) ia on iv.item_id = ia.item_id and ia.attr_value <>'additives' and attr_id=13
