					AND iv.qty_left > 0
				FOR XML PATH('')
			 ), 1, 1, '')+']'
 

	INSERT INTO @temp_cons
	SELECT 	jb.item_id,
			SUM(jb.qty_cons) 
	FROM item_cons jb WITH (NOLOCK)
	WHERE jb.wo_id = @wo_id 
		AND jb.oper_id = @oper_id 
		AND jb.seq_no = @seq_no
	GROUP BY jb.item_id


	SELECT @qty_prod = sum(jb.qty_prod) 
	FROM item_prod jb WITH (NOLOCK)
	WHERE jb.wo_id = @wo_id 
		AND jb.oper_id = @oper_id 
		AND jb.seq_no = @seq_no

	-- v0.2 FIX hardcoded attr_id
	DECLARE @item_group_attr_id INT
	SELECT @item_group_attr_id = a.attr_id
	FROM attr a WITH (NOLOCK)
	WHERE a.attr_desc = 'ItemGroup'
		AND a.attr_grp = 1 -- 1 is item

	SELECT  @base_dosing ='{'+ STUFF((
			SELECT DISTINCT ',' + '"'+ jb.item_id +'"'+ ':' +TRY_CONVERT(nvarchar(40),ic.qty_con/@qty_prod)--/100)-- remove this comment after recipe gets fix
			FROM job_bom jb WITH (NOLOCK)
				INNER JOIN @temp_cons ic ON jb.item_id = ic.itemid-- and jb.oper_id = ic.oper_id and jb.seq_no = ic.seq_no
				INNER JOIN item_attr ia WITH (NOLOCK) ON jb.item_id = ia.item_id 
														AND ia.attr_value <> 'additives'  
														AND ia.attr_id = @item_group_attr_id --and jb.dosing_step = 1 (
			WHERE jb.wo_id = @wo_id 
				AND jb.oper_id = @oper_id 
				AND jb.seq_no = @seq_no 
				AND jb.bom_pos > 0
		   
			FOR XML PATH('')
			 ), 1, 1, '') +'}'



