		SELECT @additives ='{'+ STUFF((
					SELECT DISTINCT ',' + '"'+ component +'"'+ ':' +'[' +TRY_CONVERT(nvarchar(40),pH_Factor) + ',' + TRY_CONVERT(nvarchar(40),bagWeight)+',' + TRY_CONVERT(nvarchar(40),Concentration)+']'
					FROM cakeblend.Additives WITH (NOLOCK)
					FOR XML PATH('')
				 ), 1, 1, '') +'}'
	END
	ELSE
	BEGIN
		SELECT @additives ='{}'
	END


	SELECT @X_TRISTIMULUS = '[ '+ STUFF((
			 SELECT   ','  + TRY_CONVERT(nvarchar(40),x_values) 
				FROM ofi_x_calculation WITH (NOLOCK) ORDER BY x_char ASC
			
				FOR XML PATH('')
			 ), 1, 1, '')+' ]'

	SELECT @Y_TRISTIMULUS = '[ '+ STUFF((
			 SELECT   ','  + TRY_CONVERT(nvarchar(40),y_values) 
				FROM ofi_y_calculation WITH (NOLOCK) ORDER BY y_char ASC
			
				FOR XML PATH('')
			 ), 1, 1, '')+' ]'

	SELECT @Z_TRISTIMULUS = '[ '+ STUFF((
			 SELECT   ','  + TRY_CONVERT(nvarchar(40),z_values) 
				FROM ofi_z_calculation WITH (NOLOCK) ORDER BY z_char ASC
			
				FOR XML PATH('')
			 ), 1, 1, '')+' ]'
 
	SELECT @x_normalize = const_value 
	FROM cakeblend.Constants WITH (NOLOCK) 
	WHERE const_name = 'X_NORMALIZE'
	
	SELECT @y_normalize = const_value 
	FROM cakeblend.Constants WITH (NOLOCK)
	WHERE const_name = 'Y_NORMALIZE'
	
	SELECT @z_normalize = const_value 
	FROM cakeblend.Constants WITH (NOLOCK) 
	WHERE const_name = 'Z_NORMALIZE'
	
	SELECT @sat_thresold = const_value 
	FROM cakeblend.Constants WITH (NOLOCK) 
	WHERE const_name = 'SAT_THRESHOLD'

	SELECT @cakeComponents = 	
	  '['+ STUFF((
			 SELECT DISTINCT ',' +'{' + '"'+ 'Name' +'"'+ ':' + '"' +COMPONENT +'"' + ','
			 + '"' + 'Fat' +'"'+ ':' +convert(nvarchar(40),FAT) + ','
			 + '"' + 'PigmentDensity' +'"'+ ':'  +convert(nvarchar(40),PIGMENT_DENSITY)  + ','
			 + '"' + 'Ph' +'"'+ ':' +convert(nvarchar(40),PH) + ','
			 + '"' + 'XComponent' +'"'+ ':' + case when X_COMPONENT = 1 then 'true' else 'false' end + ','
			 + '"' + 'AllowedInCorrection' +'"'+ ':'  + 'true'  + ','
			 + '"'+'Reflections'+'"'+':' + '{' +
			  '"400":' + CLIWREFL400 + ',' +
			  '"410":' + CLIWREFL410 + ',' +
			  '"420":' + CLIWREFL420 + ',' +
			  '"430":' + CLIWREFL430 + ',' +
			  '"440":' + CLIWREFL440 + ',' +
			  '"450":' + CLIWREFL450 + ',' +
			  '"460":' + CLIWREFL460 + ',' +
			  '"470":' + CLIWREFL470 + ',' +
			  '"480":' + CLIWREFL480 + ',' +
			  '"490":' + CLIWREFL490 + ',' +
			  '"500":' + CLIWREFL500 + ',' +
			  '"510":' + CLIWREFL510 + ',' +
			  '"520":' + CLIWREFL520 + ',' +
			  '"530":' + CLIWREFL530 + ',' +
			  '"540":' + CLIWREFL540 + ',' +
			  '"550":' + CLIWREFL550 + ',' +
			  '"560":' + CLIWREFL560 + ',' +
			  '"570":' + CLIWREFL570 + ',' +
			  '"580":' + CLIWREFL580 + ',' +
			  '"590":' + CLIWREFL590 + ',' +
			  '"600":' + CLIWREFL600 + ',' +
			  '"610":' + CLIWREFL610 + ',' +
			  '"620":' + CLIWREFL620 + ',' +
			  '"630":' + CLIWREFL630 + ',' +
			  '"640":' + CLIWREFL640 + ',' +
			  '"650":' + CLIWREFL650 + ',' +
			  '"660":' + CLIWREFL660 + ',' +
			  '"670":' + CLIWREFL670 + ',' +
			  '"680":' + CLIWREFL680 + ',' +
			  '"690":' + CLIWREFL690 + ',' +
			  '"700":' + CLIWREFL700 + '}}'

				FROM job_bom jb WITH (NOLOCK)
					--inner join item_inv	 iv on j.item_id=iv.item_id	
					INNER JOIN item_attr ia WITH (NOLOCK) ON jb.item_id = ia.item_id
															AND ia.attr_value <> 'additives'
															AND ia.attr_id = @item_group_attr_id
					INNER JOIN cakeblend.cakeComponents cc WITH (NOLOCK) ON jb.item_id = cc.COMPONENT
					WHERE jb.wo_id = @wo_id 
						AND jb.oper_id = @oper_id 
						AND jb.seq_no = @seq_no
						AND jb.bom_pos > 0
				FOR XML PATH('')
			 ), 1, 1, '') +']'

		
	SELECT 	@rcpLCH = '['+convert(nvarchar(40),L) +','+convert(nvarchar(40),C)+','+convert(nvarchar(40),H)+']',
			@rcp_moist = MOISTURE,
			@rcp_fat = FAT,
			@rcp_fat_min = FAT_MIN,
			@rcp_fat_max = FAT_MAX,
			@rcp_ph = PH,
			@rcp_ph_deviation = PH_DIVIATION,
			@rcpWLCH = '['+convert(nvarchar(40),WL) +','+convert(nvarchar(40),WC)+','+convert(nvarchar(40),WH)+']', 
			@rcp_minimize_x = CASE 	WHEN MINIMIZE_X = 1 
										THEN 'true' 
									ELSE 'false' 
							  END,
			@rcpXLCH = '['+convert(nvarchar(40),MINIMIZE_X_L) +','+convert(nvarchar(40),MINIMIZE_X_C)+','+convert(nvarchar(40),MINIMIZE_X_H)+']'
	FROM cakeblend.cakeRecipeMasterData WITH (NOLOCK) 
	WHERE CAKEBLEND_ITEM = @item_id
		
	SELECT 
	
		@value1   as  'Ref400',
		@value2   as  'Ref410',
		@value3   as  'Ref420',
		@value4   as  'Ref430',
		@value5   as  'Ref440',
		@value6   as  'Ref450',
		@value7   as  'Ref460',
		@value8   as  'Ref470',
		@value9   as  'Ref480',
		@value10  as  'Ref490',
		@value11  as  'Ref500',
		@value12  as  'Ref510',
		@value13  as  'Ref520',
		@value14  as  'Ref530',
		@value15  as  'Ref540',
		@value16  as  'Ref550',
		@value17  as  'Ref560',
		@value18  as  'Ref570',
		@value19  as  'Ref580',
		@value20  as  'Ref590',
		@value21  as  'Ref600',
		@value22  as  'Ref610',
		@value23  as  'Ref620',
		@value24  as  'Ref630',
