		@value29  as  'Ref680',
		@value30  as  'Ref690',
		@value31  as  'Ref700',
		@measured_fat as fat,
		@measured_ph as ph,
		@measured_moisture as moist,
		--@actual_wt as actual_wt,
		--@target_wt as target_wt,
		@allowed_comp as allowed_comp,
		@base_dosing as base_dose,
		@wo_id as job_id,
