CREATE PROCEDURE [dbo].[sp_U_Folder_File]
(
	@item_id nvarchar(40) ,
	@oper_id nvarchar(40) ,
	@ent_id int ,
	@ver_id nvarchar(40) ,
	@file_path nvarchar(254) ,
	@file_desc nvarchar(40) ,
	@file_type nvarchar(254) ,
	@last_modified datetime ,
	@file_size int ,
	@author nvarchar(40) ,
	@spare1 nvarchar(80),
	@spare2 nvarchar(80),
	@spare3 nvarchar(80),
	@spare4 nvarchar(80),
	@last_edit_comment nvarchar(254),
	@mod_id varchar(30) ,
	@time_zone_bias_value INT32 = 0
)

AS
-- ***********************************************************************************************************************
-- Module Name				-
-- Description				-
-- Author					-
-- Date Created				- 10/21/2002
-- Version					- 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Version     Changes
-- 10/11/2005		Raghu			3.1.0		HD# 5678, Part of DB Changes
-- 07/31/2007		AML				3.3.0		DB Changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)

UPDATE folder_file
SET file_desc = @file_desc,
    file_type = @file_type,
    last_modified = DATEADD(mi, -@time_zone_bias_value, @last_modified),
    file_size = @file_size,
    author = @author,
	spare1 = @spare1,
	spare2 = @spare2,
	spare3 = @spare3,
	spare4 = @spare4,
    last_edit_comment = @last_edit_comment
WHERE 	(item_id = @item_id AND
        oper_id = @oper_id AND
        ent_id = @ent_id AND
        ver_id = @ver_id AND
        file_path = @file_path AND
        CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id))) = @mod_id)

