--===========================================================================================
-- Name:     	sp_I_ofi_AddBoMRecipe
-- Description:	The stored procedure will create new bom component that called from the WF
--	
-- Usage:		AddBoMRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-07-28			Initial version.
-- 0.02.00	YG				2022-09-11			Accomodate byproduct as a reference when set the set bom_pos
-- 0.03.00	YG				2022-10-24			Add flag for audit trail in the parameter
-- 0.04.00	YG				2022-12-20			Bug Fix : Skip checking the maximum ratio if new material added is non Main Material
-- 0.05.00	YG				2022-12-23			if Qty = 0.00 Then set parent item id into 0.0001
-- 0.06.00  YG				2023-01-11			Bug Fix #705 : Can't add main material once non main material already added with qty 100 %
-- 0.07.00  YG				2023-01-25			Added one attribute to skip sum recipe validation and considering uom when saving to the bom_item table
-- 0.08.00	AP				2023-05-03			Added the audit trail comment with @item_id and @recipe_version 
-- 0.09.00	YG				2024-03-21			Save audit trail qty based on percentage
-- 0.09.10	SSB				2024-03-25			Added check item exists condition with grade check
-- ===========================================================================================

CREATE PROCEDURE [dbo].[sp_I_ofi_AddBoMRecipe_backup]
     @parent_item_id nvarchar(40)  = NULL,
     @recipe_version int           = NULL,     @item_id        nvarchar(40)  = NULL,
     @grade_cd       int           = NULL,
     @qty            float         = NULL,
     @min_qty        float         = NULL,
     @max_qty        float         = NULL,
     @notes          nvarchar(250) = NULL,
     @byproduct      nvarchar(40)  = 'N',
     @user_name      nvarchar(80)  = NULL,
	 @audit_trail BIT = 1 -- 1=Save to audit trail 0=Not Save to Audit Trail
AS
BEGIN
     SET NOCOUNT ON;

     DECLARE @mod_id nvarchar(30),
             @iErrorValue int,
             @fQty DECIMAL(16,8),
             @fMinQty DECIMAL(16,8),
             @fMaxQty DECIMAL(16,8),
             @fCurrentTtlQty DECIMAL(16,8),
             @iRowId int,
             @iBomPos int,
             @auditTrailParameters ofi_AUDITTRAILPARAMETERS,
             @strModuleName nvarchar(80) = 'MRM_BoMRecipe',
             @strFunctionName nvarchar(80) = 'UI',
             @strActivityMsg nvarchar(200) = 'add',
             @strCommentMsg nvarchar(200) = 'Item id:'+@item_id+' for version:'+CAST(@recipe_version AS varchar)+' created From [dbo].[sp_I_ofi_AddBoMRecipe]',-- 0.08.00
			 @bIsMainMaterial INT = 0,
			 @iIgnoreSumRecipeValue INT = 0,
			 @strItemUoM nvarchar(40), 
			 @strDefaultUoM nvarchar(40) = 'KG' 

	 -- Set default value if no value entered
	 IF (@audit_trail is NULL or @audit_trail = '')
	 BEGIN 
		SET @audit_trail = 1;
	 END

	 -- Get information about requirement to ignore the 100% validation  
	 SELECT @iIgnoreSumRecipeValue = attr_value FROM ent_attr WITH (NOLOCK) 
	 WHERE ent_id = (SELECT ent_id FROM ofi_master_recipe WITH (NOLOCK) 
					 WHERE item_id = @parent_item_id and version = @recipe_version) 
		 AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) 
						WHERE attr_desc = 'IgnoreSumRecipeComponent')
						
	 SET @iIgnoreSumRecipeValue = ISNULL(@iIgnoreSumRecipeValue,0); 

     -- Prepare the values
     SET @fQty = ROUND(@qty, 4)
     SET @fMinQty = ROUND(@min_qty, 4)
     SET @fMaxQty = ROUND(@max_qty, 4)

     -- Interlock #1 - Check Mandatory Parameter 
     IF (@parent_item_id IS NULL
          OR @recipe_version IS NULL
          OR @item_id IS NULL) BEGIN
          SET @iErrorValue = -1

          -- Set Error Message 'Parameters are not completed'
          RAISERROR ('@@MRBWFErrorParameterNotCompleted@@', -- Message text.  
          16, -- Severity.  
          1 -- State.  
          );

          RETURN -1
     END

     -- Interlock #2 - Validate the maximum, and minimum quantity will be made sure it is Min <= Qty <= Max. 
     IF (NOT (@fQty >= @fMinQty
          AND @fQty <= @fMaxQty)
          AND NOT (@fQty = 0.0000)) BEGIN
          SET @iErrorValue = -1

          -- Set Error Message 'the maximum, and minimum quantity are not valid'
          RAISERROR ('@@MRBWFErrorQtyNotValid@@', -- Message text.  
          16, -- Severity.  
          1 -- State.  
          );

          RETURN -1
     END

     -- BS v 0.02.00 Validate bom_item as byproduct then sets the bom_item < 0 
     IF (@byproduct = 'Y') BEGIN
          -- Set bom_pos based on last minimum bom_pos currently available
          SELECT
               @iBomPos = MIN(bom_pos) - 1
          FROM bom_item WITH (NOLOCK)
          WHERE parent_item_id = @parent_item_id
          AND ver_id = @recipe_version
     END
     ELSE
     BEGIN
          -- Set bom_pos based on last maximum bom_pos currently available
          SELECT
               @iBomPos = MAX(bom_pos) + 1
          FROM bom_item WITH (NOLOCK)
          WHERE parent_item_id = @parent_item_id
          AND ver_id = @recipe_version
     END
     -- BE v 0.02.00 

     -- Interlock #3 - Validate the bom_pos is existed in the current table 
     IF EXISTS (SELECT
                    1
               FROM bom_item WITH (NOLOCK)
               WHERE parent_item_id = @parent_item_id
                    AND ver_id = @recipe_version
                    AND bom_pos = @iBomPos) BEGIN
          SET @iErrorValue = -1

          -- Set Error Message 'bom pos is currently available'
          RAISERROR ('@@MRBWFErrorBoMPosExisted@@', -- Message text.  
          16, -- Severity.  
          1 -- State.  
          );

          RETURN -1
     END

     -- convert percentage qty into ration qty
     SET @fQty = ROUND((@fQty / 100), 5)
     SET @fMinQty = ROUND((@fMinQty / 100), 5)
     SET @fMaxQty = ROUND((@fMaxQty / 100), 5)

	 -- if zero is entered, The value will be automatically set to 0.00001 %
     --IF (@fQty = 0.0000) BEGIN
	    --  SET @fQty = 0.00001
     --     SET @fMinQty = 0.00001
     --     SET @fMaxQty = 0.00002
     --END
	 SET @fQty = CASE WHEN @fQty = 0.00000 THEN 0.00001 ELSE @fQty END;
	 SET @fMinQty = CASE WHEN @fMinQty = 0.00000 THEN 0.00001 ELSE @fMinQty END;
	 SET @fMaxQty = CASE WHEN @fMaxQty = 0.00000 THEN 0.00002 ELSE @fMaxQty END;

     -- Interlock #4 Total BoM should not more than 1.00 / 100 %
     -- Assumed all item with bom_pos > 0 can be calculated
     SELECT
          @fCurrentTtlQty = ROUND(SUM(dbo.[fn_ofi_ConvertQtyByItemIdAndUom](bi.item_id,qty_per_parent_item,NULL,NULL,NULL,NULL,u.description,@strDefaultUoM)), 5)
     FROM bom_item bi WITH (NOLOCK)
	 INNER JOIN item i WITH (NOLOCK) ON bi.item_id = i.item_id
	 INNER JOIN uom u WITH (NOLOCK) ON i.uom_id = u.uom_id 
	 LEFT OUTER JOIN item_attr ia ON bi.item_id = ia.item_id and attr_id = (SELECT attr_id FROM attr WITH(NOLOCK) WHERE attr_desc = 'MaterialType' 
																													AND attr_grp = 1 )
     WHERE parent_item_id = @parent_item_id
		 AND attr_value = 'FERT'
		 AND ver_id = @recipe_version
		 AND bom_pos > 0
		 AND (bi.spare2 = 'Active'
		 OR bi.spare2 IS NULL)

	SET @fCurrentTtlQty = ISNULL(@fCurrentTtlQty,0.00);

	SELECT @bIsMainMaterial = 1 
	FROM item_attr WITH (NOLOCK)
	WHERE item_id = @item_id 
		AND attr_id = (SELECT attr_id 
						FROM attr WITH(NOLOCK) 
						WHERE attr_desc = 'MaterialType' 
						AND attr_grp = 1)
		AND attr_value = 'FERT'

     IF (Round((@fCurrentTtlQty + @fQty),3) > 1.0000 AND @bIsMainMaterial = 1 AND @iIgnoreSumRecipeValue = 0) 
	 BEGIN
          SET @iErrorValue = -1

          -- Set Error Message 'Total BoM more than 1.00'
          RAISERROR ('@@MRBWFErrorTotalBoMQtyTooMuch@@', -- Message text.  
          16, -- Severity.  
          1 -- State.  
          );

          RETURN -1
     END

	 SELECT @strItemUoM = description 
	 FROM uom WITH (NOLOCK)
	 WHERE uom_id = (SELECT uom_id FROM item WITH (NOLOCK) 
					WHERE item_id = @item_id)

	 SELECT @fQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	 SELECT @fMinQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fMinQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	 SELECT @fMaxQty = dbo.fn_ofi_ConvertQtyByItemIdAndUom(@item_id,@fMaxQty,NULL,NULL,NULL,NULL,@strDefaultUoM,@strItemUoM)
	
	--if exists check then raise error --V0.09.10
	if exists (select 1 from bom_item where parent_item_id =@parent_item_id and ver_id=@recipe_version and item_id=@item_id and reqd_grade_cd =@grade_cd)
	BEGIN
		SET @iErrorValue = -1

          -- Set Error Message 'Total BoM more than 1.00'
          RAISERROR ('@@ofiMRMItemExist@@', -- Message text.  
          16, -- Severity.  
          1 -- State.  
          );
	END
	ELSE 
	BEGIN

     EXEC sp_I_Bom_Item @parent_item_id = @parent_item_id,
                        @ver_id = @recipe_version,
                        @bom_pos = @iBomPos,
                        @item_id = @item_id,
                        @reqd_grade_cd = @grade_cd,
                        @instruction = NULL,
                        @qty_per_parent_item = @fQty,
                        @max_qty_per_parent_item = @fMaxQty,
                        @min_qty_per_parent_item = @fMinQty,
                        @update_inv = 1,
                        @backflush = 0,
                        @def_reas_cd = NULL,
                        @def_lot_no = NULL,
                        @def_sublot_no = NULL,
                        @def_storage_ent_id = NULL,
                        @def_reject_ent_id = NULL,
                        @scaling_factor = 1,
                        @must_consume_from_inv = NULL,
                        @may_choose_alt_inv_loc = NULL,
                        @may_create_new_lots = 1,
                        @must_consume_from_wip = 0,
                        @must_consume_before_prod = 0,
                        @constant_qty = NULL,
                        @est_time = 0,
                        @serial_no_source = 0,
                        @spare1 = @byproduct, -- Save byproduct in the spare columns
                        @spare2 = 'Active',
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @last_edit_comment = @notes,
                        @mod_id = @mod_id OUTPUT

     SET @iRowId = @@IDENTITY

	 IF (@audit_trail = 1)
	 BEGIN
		 -- Insert entry in Audit Trial starts
		 DELETE @auditTrailParameters;
		 INSERT INTO @auditTrailParameters (row_id,
			  field_name,
			  field_value)
		 VALUES
			  (@iRowId,
			   '@ParentItemId',
			   @parent_item_id),
			  (@iRowId,
			   '@Version',
			   CAST(@recipe_version AS nvarchar(40))),
			  (@iRowId,
			   '@ItemId',
			   @item_id),
			  (@iRowId,
			   '@Qty',
			   CAST(@qty AS nvarchar(40))),
			  (@iRowId,
			   '@MinQty',
			   CAST(@min_qty AS nvarchar(40))),
			  (@iRowId,
			   '@MaxQty',
			   CAST(@max_qty AS nvarchar(40))),
			  (@iRowId,
			   '@GradeCd',
			   CAST(@grade_cd AS nvarchar(10))),
			  (@iRowId,
			   '@Notes',
			   @notes),
			  (@iRowId,
			   '@Active',
			   'Active' -- Set Default as Active
			  )

		 EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName,
								  @function_id = @strFunctionName,
								  @auditTrailParameters = @auditTrailParameters,
								  @user_id = @user_name,
								  @activity = @strActivityMsg,
								  @audit_category = 'Info',
								  @comments = @strCommentMsg
	 END
	 END
END

/*
-- ===========================================================================================
-- Name:  [sp_U_ofi_aut_int_buff_GetNextRow]
-- Description: Used to get the next row from the interface buffer table
--
-- Usage: For AUT interface to get the next unprocessed the record. Exec from parent SPs.
-- ===========================================================================================
-- Version Author  	Date (yyyy-MM-dd) 	Change description
-- 0.01.00 JSC   	2025-04-15   		CR512: Initial version.
-- ===========================================================================================*/
-- Optimized GetNextRow with index-aligned ORDER BY
-- Get and Update Procedure
CREATE      PROCEDURE [dbo].[sp_U_ofi_aut_int_buff_GetNextRow_back_05_22_2025]
    @InterfaceType NVARCHAR(15),
    @ObjectName NVARCHAR(80),
    @ID INT = -1 OUTPUT,
    @Data NVARCHAR(4000) = NULL OUTPUT,
    @ErrorCode INT = 0 OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
   
    SET @Data = NULL;
    SET @ErrorCode = 0;

    DECLARE @TranCounter INT = @@TRANCOUNT;
	DECLARE @TranName NVARCHAR(32) =  CAST(OBJECT_NAME(@@PROCID) AS NVARCHAR(28));
    DECLARE @SavePointName NVARCHAR(32) = CAST(OBJECT_NAME(@@PROCID) AS NVARCHAR(28)) + N'_' + CAST(@@NESTLEVEL AS NVARCHAR(3));

    BEGIN TRY
        IF @TranCounter = 0
            BEGIN TRANSACTION @TranName;
        ELSE
            SAVE TRANSACTION @SavePointName;

        ;WITH NextRow AS (
            SELECT TOP (1) Id, [Data] 
            FROM dbo.ofi_aut_interface_buffer WITH (UPDLOCK, READPAST)
            WHERE [Status] = 0
              AND ObjectName = @ObjectName
              AND InterfaceType = @InterfaceType
            ORDER BY CurrentTimestamp ASC
        )
        UPDATE b
        SET @ID = b.[Id],
            @Data = b.[Data],
            b.[Status] = 1,
            b.Comment = 'Processing',
            b.StatusTimestamp = GETDATE()
        FROM dbo.ofi_aut_interface_buffer b
        INNER JOIN NextRow nr ON b.Id = nr.Id;

        IF @TranCounter = 0
            COMMIT TRANSACTION @TranName;

		RETURN;
    END TRY
    BEGIN CATCH
        SET @ErrorCode = ERROR_NUMBER();
		SET @ID = -1;


		DECLARE @error INT, @message VARCHAR(4000), @xstate INT;
        SELECT @error = ERROR_NUMBER(), @message = ERROR_MESSAGE(), @xstate = XACT_STATE();
        IF @xstate = -1
            ROLLBACK TRANSACTION @TranName;
        IF @xstate = 1 and @TranCounter = 0
            ROLLBACK TRANSACTION @TranName
        IF @xstate = 1 and @TranCounter > 0
            ROLLBACK TRANSACTION @SavePointName;
    END CATCH
END;

