--===========================================================================================
-- Name      : sp_u_ofi_SyncInventory
--
-- Description  : Synchronizes MES inventory for a storage unit based on the current
--          DCS level.
--
--          This procedure consolidates the logic previously implemented by:
--          - sp_s_ofi_GetInvV1
--          - sp_u_ofi_inv_reduceV1
--
--          The procedure:
--          1. Retrieves the current MES inventory.
--          2. Retrieves the conversion factor between the DCS UoM and
--             the default MES storage UoM.
--          3. Converts the DCS level to the MES storage UoM.
--          4. Checks the configured floating quantity threshold.
--          5. Checks the minimum remaining inventory threshold.
--          6. If required, reduces MES inventory using FIFO consumption.
--          7. Creates the corresponding audit trail.
--
--          The DCS level is expected to be provided in the UoM configured
--          by @DCS_UoM.
--
-- Parameters:
--  @ent_name         Storage Unit entity name
--  @DCS_Level         Current DCS level
--  @DCS_UoM         DCS level UoM
--  @DCSFloatingQtyThreshold  Allowed difference between MES and DCS inventory
--  @InvQtyThreshold       Minimum inventory that must remain in MES
--
-- Return:
--  result_code
--    0 = No reduction required
--    1 = Inventory reduced
--    2 = Reduction blocked by inventory threshold
--    3 = Storage unit / inventory not found
--
-- Output:
--  ent_name
--  mes_qty
--  factor
--  dcs_qty
--  reduce_qty
--  target_qty
--  result_code
--
--===========================================================================================
-- Version  Author      Date      Change Description
-- 0.01.00  AML, XPM    2026-09-28    Initial version
--===========================================================================================

CREATE   PROCEDURE [dbo].[sp_u_ofi_SyncInventory]
  @ent_name          NVARCHAR(100),
  @DCS_Level         FLOAT,
  @DCS_UoM         NVARCHAR(100),
  @DCSFloatingQtyThreshold   FLOAT,
  @InvQtyThreshold       FLOAT
AS
BEGIN

  SET NOCOUNT ON;

  --=======================================================================================
  -- Variables
  --=======================================================================================

  DECLARE
    @ent_id        INT,
    @item_id      NVARCHAR(80),
    @defaultstorageuom  NVARCHAR(100),
    @qty        FLOAT,
    @factor        FLOAT,
    @CurrentMESQty    FLOAT,
    @CurrentDCSQty    FLOAT,
    @NewMESQty      FLOAT,
    @QtyResult      FLOAT,
    @minID        INT,
    @maxID        INT,
    @lotno        NVARCHAR(50),
    @sublotno      NVARCHAR(50),
    @qty_inv      FLOAT,
    @consqty      FLOAT,
    @grade_cd      INT,
    @status_cd      INT,
    @iRowId      INT,
    @result_code    INT;


  --=======================================================================================
  -- Default values
  --=======================================================================================

  SET @qty = 0.0;
  SET @factor = 1.0;
  SET @CurrentMESQty = 0.0;
  SET @CurrentDCSQty = 0.0;
  SET @NewMESQty = 0.0;
  SET @QtyResult = 0.0;
  SET @result_code = 0;



  SELECT
    @defaultstorageuom = ISNULL(attr_value, 'KG')
  FROM dbo.ent_attr WITH (NOLOCK)
  WHERE ent_id = (
    SELECT TOP 1 ent_id
    FROM dbo.ent WITH (NOLOCK)
    WHERE parent_ent_id IS NULL
  )
  AND attr_id = (
    SELECT TOP 1 attr_id
    FROM dbo.attr WITH (NOLOCK)
    WHERE attr_desc = 'DefaultStorageUOM'
    AND attr_grp = 2
  );



  SELECT TOP 1
    @ent_id = ent_id
  FROM dbo.ent WITH (NOLOCK)
  WHERE ent_name = @ent_name;


  IF @ent_id IS NULL
  BEGIN

    SET @result_code = 3;

    SELECT
      @ent_name AS ent_name,
      0.0 AS mes_qty,
      1.0 AS factor,
      0.0 AS dcs_qty,
      0.0 AS reduce_qty,
      0.0 AS target_qty,
      @result_code AS result_code;

    RETURN;

  END;




  SELECT
    @qty = SUM(
      [dbo].[Fn_ofi_convertqtybyitemidanduom]
      (
        iv.item_id,
        iv.qty_left,
        NULL,
        NULL,
        u.description,
        @defaultstorageuom,
        NULL,
        NULL
      )
    )
  FROM dbo.item_inv iv WITH (NOLOCK)
  INNER JOIN dbo.ent e WITH (NOLOCK)
    ON iv.ent_id = e.ent_id
  INNER JOIN dbo.item i WITH (NOLOCK)
    ON iv.item_id = i.item_id
  INNER JOIN dbo.uom u WITH (NOLOCK)
    ON i.uom_id = u.uom_id
  WHERE e.ent_name = @ent_name;


  SET @CurrentMESQty = ISNULL(@qty, 0.0);



  SELECT TOP 1
    @factor = factor
  FROM dbo.uom_conv WITH (NOLOCK)
  WHERE from_uom_id = (
    SELECT TOP 1 uom_id
    FROM dbo.uom WITH (NOLOCK)
    WHERE abbreviation = @DCS_UoM
  )
  AND to_uom_id = (
    SELECT TOP 1 uom_id
    FROM dbo.uom WITH (NOLOCK)
    WHERE abbreviation = @defaultstorageuom
  );


  SET @factor = ISNULL(@factor, 1.0);



  SET @CurrentDCSQty = @DCS_Level * @factor;


  --=======================================================================================
  -- Check whether inventory needs to be reduced
  -- Equivalent to:
  --
  -- CurrentMESQty > CurrentDCSQty + DCSFloatingQtyThreshold
  --=======================================================================================

  IF @CurrentMESQty <= @CurrentDCSQty + @DCSFloatingQtyThreshold
  BEGIN

    SET @result_code = 0;

    SELECT
      @ent_name AS ent_name,
      @CurrentMESQty AS mes_qty,
      @factor AS factor,
      @CurrentDCSQty AS dcs_qty,
      0.0 AS reduce_qty,
      @CurrentMESQty AS target_qty,
      @result_code AS result_code;

    RETURN;

  END;


  --=======================================================================================
  -- Calculate reduction
  --=======================================================================================

  SET @NewMESQty = @CurrentMESQty - @CurrentDCSQty;

  SET @QtyResult = @CurrentMESQty - @NewMESQty;


  --=======================================================================================
  -- Check minimum inventory threshold
  -- Equivalent to:
  --
  -- IF QtyResult > InvQtyThreshold
  --=======================================================================================

  IF @QtyResult <= @InvQtyThreshold
  BEGIN

    SET @result_code = 2;

    SELECT
      @ent_name AS ent_name,
      @CurrentMESQty AS mes_qty,
      @factor AS factor,
      @CurrentDCSQty AS dcs_qty,
      @NewMESQty AS reduce_qty,
      @QtyResult AS target_qty,
      @result_code AS result_code;

    RETURN;

  END;


  --=======================================================================================
  -- Get item used by the storage unit
  -- Same logic as sp_u_ofi_inv_reduceV1
  --=======================================================================================

  SELECT TOP 1
    @item_id = item_id
  FROM dbo.item_inv WITH (NOLOCK)
  WHERE ent_id = @ent_id;


  IF @item_id IS NULL
  BEGIN

    SET @result_code = 3;

    SELECT
      @ent_name AS ent_name,
      @CurrentMESQty AS mes_qty,
      @factor AS factor,
      @CurrentDCSQty AS dcs_qty,
      0.0 AS reduce_qty,
      @CurrentMESQty AS target_qty,
      @result_code AS result_code;

    RETURN;

  END;


  --=======================================================================================
  -- Convert reduction quantity from MES storage UoM to item UoM
  -- Same logic as sp_u_ofi_inv_reduceV1
  --=======================================================================================

  SELECT
    @NewMESQty =
      [dbo].[Fn_ofi_convertqtybyitemidanduom]
      (
        @item_id,
        @NewMESQty,
        NULL,
        NULL,
        'KG',
        u.abbreviation,
        NULL,
        NULL
      )
  FROM dbo.item i WITH (NOLOCK)
  INNER JOIN dbo.uom u WITH (NOLOCK)
    ON i.uom_id = u.uom_id
  WHERE i.item_id = @item_id;


  SET @NewMESQty = ISNULL(@NewMESQty, 0.0);


  --=======================================================================================
  -- Build FIFO consumption list
  --=======================================================================================

  DECLARE @inv_list TABLE
  (
    id        INT,
    lot        NVARCHAR(40),
    sublot      NVARCHAR(40),
    qty        FLOAT,
    cons_qty    FLOAT,
    consume_full  BIT,
    grade_cd    INT,
    status_cd    INT,
    row_id      INT
  );


  INSERT INTO @inv_list
  EXEC dbo.Sp_sa_ofi_item_inv_typeofcons
    @ent_id,
    @item_id,
    @NewMESQty,
    'FIFO';


  --=======================================================================================
  -- Get FIFO range
  --=======================================================================================

  SELECT
    @minID = MIN(id),
    @maxID = MAX(id)
  FROM @inv_list;


  --=======================================================================================
  -- Reduce inventory
  --=======================================================================================

  WHILE @minID <= @maxID
  BEGIN

    SELECT
      @lotno = lot,
      @sublotno = sublot,
      @qty_inv = qty,
      @consqty = cons_qty,
      @grade_cd = grade_cd,
      @status_cd = status_cd,
      @iRowId = row_id
    FROM @inv_list
    WHERE id = @minID;


    EXEC dbo.Sp_u_item_inv_reduce
      @ent_id = @ent_id,
      @item_id = @item_id,
      @lot_no = @lotno,
      @sublot_no = @sublotno,
      @reduce_qty = @consqty,
      @reduce_qty_erp = 0,
      @date_out = NULL,
      @goods_shipped = 0,
      @item_grade_cd = @grade_cd,
      @item_status_cd = @status_cd,
      @item_reas_cd = NULL,
      @must_consume_from_inv = 1,
      @must_cons_from_wip = 0,
      @checkgrade = 1,
      @wo_id = NULL,
      @oper_id = NULL,
      @seq_no = NULL,
      @last_edit_at = NULL,
      @transfer_comments = 'AUTO SCRAP',
      @log_transfer = 1,
      @date_out_utc = NULL,
      @time_zone_bias_value = NULL,
      @row_id = NULL;


    --===================================================================================
    -- Audit trail
    --===================================================================================

    DECLARE @auditTrailParameters ofi_AUDITTRAILPARAMETERS;

    DECLARE
      @grade_desc    NVARCHAR(100),
      @state_desc    NVARCHAR(100),
      @user_name    NVARCHAR(100),
      @strModuleName  NVARCHAR(80) = 'INV_AutoScrap',
      @strFunctionName  NVARCHAR(80) = 'UI',
      @strActivityMsg  NVARCHAR(200) = 'EDIT',
      @strCommentMsg  NVARCHAR(200);


    SELECT
      @grade_desc = item_grade_desc
    FROM dbo.item_grade WITH (NOLOCK)
    WHERE item_grade_cd = @grade_cd;


    SELECT
      @state_desc = item_status_desc
    FROM dbo.item_state WITH (NOLOCK)
    WHERE item_status_cd = @status_cd;


    SELECT
      @user_name = SUSER_NAME();


    SET @strCommentMsg =
      'Silo Name :' + @ent_name +
      ', Prev Qty :' + CAST(@qty_inv AS VARCHAR) +
      ', Reduce Qty :' + CAST(@consqty AS VARCHAR) +
      ', created From [dbo].[sp_u_ofi_SyncInventory]';


    DELETE FROM @auditTrailParameters;


    INSERT INTO @auditTrailParameters
    (
      row_id,
      field_name,
      field_value
    )
    VALUES
      (
        @iRowId,
        '@EntId',
        CONVERT(NVARCHAR(80), @ent_id)
      ),
      (
        @iRowId,
        '@ItemId',
        CONVERT(NVARCHAR(80), @item_id)
      ),
      (
        @iRowId,
        '@LotNo',
        CONVERT(NVARCHAR(80), @lotno)
      ),
      (
        @iRowId,
        '@SublotNo',
        CONVERT(NVARCHAR(80), @sublotno)
      ),
      (
        @iRowId,
        '@Qty',
        CONVERT(NVARCHAR(80), @qty_inv - @consqty)
      ),
      (
        @iRowId,
        '@GradeCd',
        CONVERT(NVARCHAR(80), @grade_cd)
      ),
      (
        @iRowId,
        '@StateCd',
        CONVERT(NVARCHAR(80), @status_cd)
      );


    EXEC dbo.sp_I_ofi_AuditTrail
      @module_id = @strModuleName,
      @function_id = @strFunctionName,
      @auditTrailParameters = @auditTrailParameters,
      @user_id = @user_name,
      @activity = @strActivityMsg,
      @audit_category = 'Info',
      @comments = @strCommentMsg;


    SET @minID = @minID + 1;

  END;


  --=======================================================================================
  -- Successful reduction
  --=======================================================================================

  SET @result_code = 1;


  SELECT
    @ent_name AS ent_name,
    @CurrentMESQty AS mes_qty,
    @factor AS factor,
    @CurrentDCSQty AS dcs_qty,
    @NewMESQty AS reduce_qty,
    @QtyResult AS target_qty,
    @result_code AS result_code;

END

--===========================================================================================
-- Name:    SP_S_ofi_GenerateHUNumber
-- Description:  generate hu number based on automation requested handshake
--
-- Usage:  Always gets called from the ArchestrA scripts under $AUT_Interfaces instances
-- =======================================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  sv            2022-09-15      Initial version.
-- 0.01.01  sv            2023-04-22      Update the pallet production during bag production.
-- 0.02.00  AML, XPM      2026-03-11      Generate HU number in job_attr instead of wo_attr.
-- 0.03.00  AML, XPM      2026-03-12      Added the whole PalletCounter logic to generate the Nested HUs
-- 0.04.00  AML, XPM      2026-03-17      Updated the process_id logic
-- 0.04.01  AML, XPM      2026-03-23      Updated the serial numbers for each HU Type
-- 0.05.00  AML, XPM	  2026-06-03	  Added a condition to prevent skipping serial numbers
-- =======================================================================================================
CREATE PROCEDURE [dbo].[SP_S_ofi_GenerateHUNumber] (
	@HU_Type INT = NULL,
	@hu_number NVARCHAR(40)= NULL,
	@wo_id VARCHAR(100),
	@oper_id VARCHAR(100),
	@seq_no INT,
	@PalletCounter INT = NULL)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @process_id AS VARCHAR(100),
		@plant_code AS INT,
		@line_no VARCHAR(10),
		@curr_datetime DATETIME,
		@exist_datetime DATETIME,
		@attr_id INT,
		@nested_serialno_attr_id INT,
		@serial_no INT,
		@nested_serial_no INT,
		--@ent_id INT,
		@year VARCHAR(10),
		@month VARCHAR(10),
		@day VARCHAR(10),
		@new_serialno VARCHAR(10),
		@new_nested_serialno VARCHAR(10),
		@nested_hu_attr_id INT,
		@reject_hu_attr_id INT,
		@good_hu_attr_id INT,
		@line_ent_id INT,
		@parenthu_no VARCHAR(10),
		@parent_ent_id INT,
		@SAPNumber NVARCHAR(20),
		@DCSNumber NVARCHAR(20),
		@fnumber AS INT,
		@year_dcs VARCHAR(10)
	DECLARE @hunumber_g AS VARCHAR(20),
		@hunumber_r AS VARCHAR(20),
		@hunumber_f AS VARCHAR(20),
		@hunumber BIGINT = 0,
		@result AS INT = 0

	SET @fnumber = 0

	--set @HU_Type=2
	SELECT @oper_id = oper_id
	FROM job WITH (NOLOCK)
	WHERE wo_id = @wo_id
		AND seq_no = @seq_no

	--To Get the HU serial number which is used three digit sequence 001 and increment each request and reseting every day

	

	--To get the line ent_id using the wo_id, oper_id and seq_no
	SELECT @parent_ent_id = e.parent_ent_id
	FROM ent e WITH (NOLOCK)
	INNER JOIN job j WITH (NOLOCK) ON j.run_ent_id = e.ent_id
	WHERE wo_id = @wo_id
		AND oper_id = @oper_id
		AND seq_no = @seq_no

	--This Line code used to get the linecode assigned for this running entity id to generage the HU number against this line good or reject HU

	SELECT @line_no = ea.attr_value
	FROM ent_attr ea WITH (NOLOCK)
	INNER JOIN attr a WITH (NOLOCK) ON a.attr_id = ea.attr_id
	WHERE a.attr_desc = 'LineCode'
		AND ent_id = @parent_ent_id

	--This ParentHU Group code used to get the ParentHU group code assigned for this running entity id to assign for the Parent HU to uniquely identify the ParentHU group especially reject HU
	SELECT @parenthu_no = ea.attr_value
	FROM ent_attr ea WITH (NOLOCK)
	INNER JOIN attr a WITH (NOLOCK) ON a.attr_id = ea.attr_id
	WHERE a.attr_desc = 'ParentHUGroup'
		AND ent_id = @parent_ent_id --ParentHUGroup

	-- To store the plant code in the system attibute to generate the HU Number

	SELECT @plant_code = attr_value
	FROM system_attr WITH (NOLOCK)
	WHERE attr_desc = 'HUPlantCode'

	SET @year = CAST(right(year(getDate()), 2) AS VARCHAR(10))
	SET @year_dcs = CAST(right(year(getDate()), 1) AS VARCHAR(10))
	SET @day = CAST(FORMAT(getdate(), 'dd') AS VARCHAR(2)) 
	SET @month = CAST(FORMAT(getdate(), 'MM') AS VARCHAR(2))
	SET @curr_datetime = CONVERT(DATE, GETDATE())

	-- Get the HUSerialNo attr

	SELECT @attr_id = attr_id
	FROM attr WITH (NOLOCK)
	WHERE attr_desc = 'HUSerialNo'

	SELECT @serial_no = CAST(attr_value AS INT),
		   @exist_datetime = last_edit_at
	FROM ent_attr WITH (NOLOCK)
	WHERE ent_id = @parent_ent_id AND attr_id = @attr_id



	IF (@HU_Type IN (1,2))
	BEGIN

		IF (CONVERT(DATE, @curr_datetime) <> CONVERT(DATE, ISNULL(@exist_datetime, '1900-01-01')))
		BEGIN
			SET @serial_no = 1
		END
		ELSE
		BEGIN
			SET @serial_no = @serial_no + 1
		END

		SET @new_serialno = REPLICATE('0', 3 - LEN(@serial_no)) + CAST(@serial_no AS VARCHAR(10))
	END

	IF @HU_Type = 1
	BEGIN
		SELECT @good_hu_attr_id = attr_id
		FROM attr a WITH (NOLOCK)
		WHERE a.attr_desc = 'GoodHU'

		-- set @hunumber = CONCAT(@plant_code,@line_no,@year,@month,@day,@new_serialno,0) --11032211020010
		SET @DCSNumber = CONCAT (
				1,
				@year_dcs,
				@month,
				@day,
				@new_serialno)

		PRINT '@good_hu_attr_id'
		PRINT @good_hu_attr_id

		IF EXISTS (SELECT attr_id
					FROM job_attr WITH (NOLOCK)
					WHERE wo_id = @wo_id
					AND oper_id = @oper_id
					AND seq_no = @seq_no
					AND attr_id = @good_hu_attr_id)
		BEGIN
			SET @SAPNumber = CONCAT (
					@plant_code,
					@line_no,
					@HU_Type,
					@year,
					@month,
					@day,
					@new_serialno,
					0
					)

			--set @DCSNumber = CONCAT(@plant_code,@line_no,@HU_Type,@year,@month,@day,@new_serialno,0)
			PRINT 'goodhunumber'
			PRINT @SAPNumber

			UPDATE job_attr
			SET attr_value = @SAPNumber --SET attr_value = @hunumber  --SET attr_value = @new_serialno
			WHERE wo_id = @wo_id
				AND oper_id = @oper_id
				AND seq_no = @seq_no
				AND attr_id = @good_hu_attr_id
		END
		ELSE
		BEGIN
			SET @SAPNumber = CONCAT (
					@plant_code,
					@line_no,
					@HU_Type,
					@year,
					@month,
					@day,
					@new_serialno,
					0
					)

			--set @DCSNumber =CONCAT(@HU_Type,@year,@month,@day,@new_serialno,0)
			PRINT 'goodhunumber'
			PRINT @SAPNumber

			EXEC [dbo].[sp_I_Job_Attr] @wo_id = @wo_id,
				@oper_id = @oper_id,
				@seq_no = @seq_no,
				@attr_id = @good_hu_attr_id,
				@attr_value = @SAPNumber, --@attr_value = @hunumber -- @attr_value =@new_serialno,
				@notes = NULL,
				@last_edit_comment = NULL,
				@mod_id = NULL
		END

		--UPDATE wo_attr SET attr_value = @hunumber WHERE wo_id = @wo_id AND attr_id = @good_hu_attr_id
		--set @hunumber = CONCAT(@hunumber,@new_serialno)
		PRINT @new_serialno
		PRINT @hunumber
	END
	ELSE IF @HU_Type = 2
	BEGIN
		SELECT @reject_hu_attr_id = attr_id
		FROM attr a WITH (NOLOCK)
		WHERE a.attr_desc = 'RejectHU'

		--set @hunumber_r = CONCAT(@plant_code,@line_no,@year,@month,@day,@new_serialno,1) --11032211020010
		SET @DCSNumber = CONCAT (
				2,
				@year_dcs,
				@month,
				@day,
				@new_serialno
				)
		SET @hunumber_f = CONCAT (
				@plant_code,
				@line_no,
				@year,
				@month,
				@day,
				@new_serialno,
				'F'
				)

		IF EXISTS (
				SELECT attr_id
				FROM job_attr WITH (NOLOCK)
				WHERE wo_id = @wo_id
					AND oper_id = @oper_id
					AND seq_no = @seq_no
					AND attr_id = @reject_hu_attr_id
				)
		BEGIN
			SET @SAPNumber = CONCAT (
					@plant_code,
					@line_no,
					@HU_Type,
					@year,
					@month,
					@day,
					@new_serialno,
					0
					)

			--set @DCSNumber =CONCAT(@plant_code,@line_no,@HU_Type,@year,@month,@day,@new_serialno,0)
			PRINT 'rejecthunumber'
			PRINT @SAPNumber

			UPDATE job_attr
			SET attr_value = @SAPNumber --SET attr_value = @hunumber_r  --SET attr_value = @new_serialno
			WHERE wo_id = @wo_id
				AND oper_id = @oper_id
				AND seq_no = @seq_no
				AND attr_id = @reject_hu_attr_id
		END
		ELSE
		BEGIN
			SET @SAPNumber = CONCAT (
					@plant_code,
					@line_no,
					@HU_Type,
					@year,
					@month,
					@day,
					@new_serialno,
					0
					)

			--set @DCSNumber =CONCAT(@plant_code,@line_no,@HU_Type,@year,@month,@day,@new_serialno,0)
			PRINT 'rejecthunumber'
			PRINT @SAPNumber

			EXEC [dbo].[sp_I_Job_Attr] @wo_id = @wo_id,
				@oper_id = @oper_id,
				@seq_no = @seq_no,
				@attr_id = @reject_hu_attr_id,
				@attr_value = @SAPNumber, --@attr_value = @hunumber_r, --@attr_value = @new_serialno,
				@notes = NULL,
				@last_edit_comment = NULL,
				@mod_id = NULL
		END
				--UPDATE wo_attr SET attr_value = @hunumber_r WHERE wo_id = @wo_id AND attr_id = @reject_hu_attr_id
				--set  @hunumber = 1103 --11032211020010
	END
	ELSE IF @HU_Type = 3
	BEGIN
		-- Get the NestedHU attr
		SELECT @nested_serialno_attr_id = attr_id
		FROM attr WITH (NOLOCK)
		WHERE attr_desc = 'NestedHUSerialNo'

		SELECT @process_id = p.process_id 
		FROM oper o with(nolock) 
		inner join process p with(nolock) 
		on p.process_id=o.process_id 
		where o.oper_id=@oper_id


		SELECT @nested_serial_no = attr_value,
			@exist_datetime = last_edit_at
		FROM process_attr WITH (NOLOCK)
		WHERE attr_id = @nested_serialno_attr_id and process_id=@process_id 



		IF (CONVERT(DATE, @curr_datetime) <> CONVERT(DATE, ISNULL(@exist_datetime, '1900-01-01')))
			SET @nested_serial_no = 1
		ELSE
			SET @nested_serial_no = ISNULL(@nested_serial_no, 0) + 1
		SET @new_nested_serialno = REPLICATE('0', 3 - LEN(@nested_serial_no)) + CAST(@nested_serial_no AS VARCHAR(10))


		SELECT TOP 1 @line_ent_id = e.parent_ent_id
		FROM item_prod ip WITH (NOLOCK)
		INNER JOIN ent e WITH (NOLOCK) ON e.ent_id = ip.ent_id
		WHERE ip.wo_id = @wo_id
			AND ip.oper_id = @oper_id
			AND ip.seq_no = @seq_no
		ORDER BY ip.last_edit_at DESC

		SELECT @nested_hu_attr_id = attr_id
		FROM attr a WITH (NOLOCK)
		WHERE a.attr_desc = 'NestedHU'
			AND a.attr_grp = 2 --and ent
			--set @line_no=CAST(right(@line_no,1) as varchar(10))

		

		PRINT 'printingout'
		PRINT @plant_code
		PRINT @line_no
		PRINT @year

		----IF NOT EXISTS (
		----		SELECT *
		----		FROM ent_attr ea
		----		WHERE ea.ent_id IN (
		----				SELECT ea.ent_id
		----				FROM ent_attr ea WITH (NOLOCK)
		----				INNER JOIN attr a WITH (NOLOCK) ON a.attr_id = ea.attr_id
		----				WHERE a.attr_desc = 'ParentHUGroup'
		----					AND ea.attr_value = @parenthu_no
		----				)
		----			AND ea.attr_id = @nested_hu_attr_id
				----)
		

		SELECT @hunumber_f = nested_hu 
		FROM ofi_nested_hu_pallet_counter
		WHERE pallet_counter = @PalletCounter

		IF @hunumber_f IS NULL 
		BEGIN
			SET @year = RIGHT(CAST((YEAR(GETDATE()) / 10) AS VARCHAR) + SUBSTRING(@hu_number, 2, 1), 2);
			SET @month = SUBSTRING(@hu_number, 3, 2);     
			SET @day = SUBSTRING(@hu_number, 5, 2);
			SET @hunumber_f = CONCAT (
					@plant_code,
					@parenthu_no,
					2,
					@year,
					@month,
					@day,
					@new_nested_serialno,
					0
					)
			
			EXEC [dbo].[sp_U_Ent_Attr] @ent_id = @parent_ent_id,
				@attr_id = @nested_hu_attr_id,
				@attr_value = @hunumber_f,
				@notes = NULL,
				@last_edit_comment = NULL,
				@last_edit_at = NULL

		    EXEC [dbo].[sp_i_ofi_nested_hu_pallet_counter] @pallet_counter = @PalletCounter,
				@nested_hu = @hunumber_f
			
		END
		ELSE
		BEGIN
			SET @fnumber = 1
		END
	END
	ELSE
		SET @result = - 1

	IF @fnumber <> 1 AND @HU_Type = 3
	BEGIN
		EXEC [dbo].[sp_U_ofi_process_attr_value] 
			@attr_id = @nested_serialno_attr_id,
			@attr_value = @nested_serial_no,
			@process_id = @process_id
	END
	IF @HU_Type IN (1,2)
	BEGIN
		EXEC [dbo].[sp_U_Ent_Attr] @ent_id = @parent_ent_id,
				@attr_id = @attr_id,
				@attr_value = @serial_no,
				@notes = NULL,
				@last_edit_comment = NULL,
				@last_edit_at = @exist_datetime; 
	END

	SELECT @SAPNumber AS hunumber,
		@DCSNumber AS dcs_number,
		@hunumber_r AS rework_hunumber,
		@hunumber_f AS flush_hunumber,
		@result AS result


END

/*--===========================================================================================
-- Name:		[sp_I_ofi_Util_Audit_Trail]
-- Description:	The stored procedure will insert the data in for audit trail repot using 
--				sp_I_ofi_AuditTrail 
--
-- Usage:Audit Trail report 
-- ===========================================================================================
-- Version	Author						Date (yyyy-MM-dd)	Change description
-- 0.01.00	AP				2023-11-14			Initial version.

-- ===========================================================================================*/

CREATE      Procedure [dbo].[sp_I_ofi_Util_Audit_Trail]
	@state_cd INT,	
	@ent_id INT = NULL,	
	@user_name NVARCHAR(100) = NULL,
	@strActivity NVARCHAR(100) = NULL,
	@log_id INT

AS 
BEGIN
	DECLARE @strErrorMessage NVARCHAR(255),
			@iErrorValue INT = 0,
			@bRecipePrefered BIT,
			@iRecipeVersion INT,
			@strEntName NVARCHAR(80),
			@strMaterialName NVARCHAR(80),
			@nRecipeName NVARCHAR(80),
			@mod NVARCHAR(30),
			@iRecipeRowId INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS	,
	@strModuleName  NVARCHAR(30),
	@strFunctionName NVARCHAR(30),
	@strActivityMsg  NVARCHAR(30),
	@strCommentMsg NVARCHAR(150),
	@reas_cd INT,
	@reas_pending NVARCHAR(40),
	@raw_reas_cd NVARCHAR(40),
	@last_edit_comment NVARCHAR(80),
	@last_edit_by NVARCHAR(40),
	@comments NVARCHAR(40),
	@reas_desc NVARCHAR(40),
	@state_desc NVARCHAR(40),
	@util_state_cd INT,
	@ent_desc NVARCHAR(40)
	
	set @strModuleName='Utilization'
	set @strFunctionName='UI'
	set @strActivityMsg=@strActivity
	

	SELECT @iRecipeRowId = @log_id
	select @reas_pending=(case when uh.reas_pending=0 then 'Assigned' else 'Pending' end),@reas_cd=reas_cd,@raw_reas_cd=raw_reas_cd,@util_state_cd=state_cd,@last_edit_comment=last_edit_comment,@last_edit_by=last_edit_by,@comments=comments from util_history uh with(nolock) where log_id=@log_id
	select @reas_desc=reas_desc from util_reas with(nolock) where  reas_cd=@reas_cd
select @state_desc=state_desc from util_state with(nolock)  where state_cd=@util_state_cd
select @ent_desc=e.description from ent e with(nolock)  where e.ent_id=@ent_id

set @strCommentMsg ='Util Event :ent_name-' + @ent_desc+ ',state_cd-' + CAST(@state_cd AS NVARCHAR(40))
	-- Insert entry in Audit Trial starts
			DELETE @auditTrailParameters;
			INSERT INTO @auditTrailParameters
			(
				row_id, 
				field_name, 
				field_value
			) 
			VALUES 
			(
				@iRecipeRowId, 
				'@ent_Id', 
				(CAST(@ent_id AS NVARCHAR(40))+ '-' +@ent_desc)
				--CAST(@ent_id AS NVARCHAR(40))
			),
			(
				@iRecipeRowId,
				'@state_cd',
				(CAST(@util_state_cd AS NVARCHAR(40))+ '-' +@state_desc)
			),
			(
				@iRecipeRowId,
				'@reas_cd',
				(CAST(@reas_cd AS NVARCHAR(40)) + '-' +@reas_desc)
			),
			(
				@iRecipeRowId,
				'@reas_pending',
				@reas_pending
			),
			(
				@iRecipeRowId,
				'@raw_reas_cd',
				@raw_reas_cd 
			),
			(
				@iRecipeRowId,
				'@last_edit_comment',
				@last_edit_comment     
			),
			(
				@iRecipeRowId,
				'@last_edit_by',
				@last_edit_by 
			),
			(
				@iRecipeRowId,
				'@comments',
				@comments 
			)


			EXEC sp_I_ofi_AuditTrail 
				@module_id = @strModuleName,
				@function_id = @strFunctionName,
				@auditTrailParameters = @auditTrailParameters,
				@user_id = @user_name,
				@activity = @strActivityMsg,
				@audit_category = 'Info',
				@comments = @strCommentMsg,
				@keyField1   = @strEntName,
				@keyField2   = @strMaterialName

END

/**********************************************************************************
Stored Procedure:		sp_S_MDM_Sched_Job_EventLog
Author:					Wilwin Lewis
Created:				04.10.2017

Description:			Insert Scheduler Release Event into Job_Event Table
Called by:				User Interface


Revision		Date			Who				    What
========		====			===				    ====
0.1				04.10.2017		OS					First version
0.2				14.10.2017		WL					Add value1=3 for delete

**********************************************************************************/
--==================================================================================
CREATE PROCEDURE [dbo].[sp_S_MDM_Sched_Job_EventLog]
	-- Add the parameters for the stored procedure here
	@wo_id nvarchar(40),
	@oper_id nvarchar(40),
	@seq_no nvarchar(40),
	@ent_id int,
	@segmentEntId int,
	@item_id nvarchar(40),
	@event_type nvarchar(40) = 'jobScheduledChanged',
	@quantity  int,
	@last_edit_by nvarchar(40) 
	

AS
BEGIN
	SET NOCOUNT ON;




		DECLARE @RC int
		--DECLARE @ent_id int
		DECLARE @event_time_local datetime = getdate()
		DECLARE @event_time_utc datetime = getutcdate() 
		--DECLARE @job_pos int = 1
		DECLARE @step_no int = null
		--DECLARE @event_type nvarchar(40) = 'jobScheduledChanged'
		DECLARE @bom_pos int = null
		DECLARE @lot_no nvarchar(40) = null
		DECLARE @sublot_no nvarchar(40) = null
		--DECLARE @item_id nvarchar(40)
		DECLARE @cert_name nvarchar(40) = null
		DECLARE @done_by_user_id nvarchar(40) = @last_edit_by
		DECLARE @checked_by_user_id nvarchar(40) = @last_edit_by
		DECLARE @source_row_id int = null
		DECLARE @spec_id nvarchar(40) = null
		DECLARE @genealogy_id [dbo].[STRING254_NULL] = null
		DECLARE @segment_requirement_id [dbo].[STRING80_NULL] = null
		DECLARE @segment_response_id [dbo].[STRING80_NULL] = null
		DECLARE @subsegment_id [dbo].[STRING80_NULL] = null
		--DECLARE @quantity [dbo].[INT32] = null
		DECLARE @comments nvarchar(254) = null
		DECLARE @value1 nvarchar(80) = case when @quantity > 0 then  1 else 3 end -- Set the value1 to 3 on delete event
		DECLARE @value2 nvarchar(80) = null
		DECLARE @value3 nvarchar(80) = null
		DECLARE @value4 nvarchar(80) = null
		DECLARE @value5 nvarchar(80) = null
		DECLARE @value6 nvarchar(80) = null
		DECLARE @value7 nvarchar(80) = null
		DECLARE @value8 nvarchar(80) = null
		DECLARE @value9 nvarchar(80) = null
		DECLARE @value10 nvarchar(80) = @ent_id
		DECLARE @last_edit_at datetime = getdate()
		DECLARE @last_edit_comment nvarchar(254) = 'ScheduledJobChange'
		DECLARE @time_zone_bias_value [dbo].[INT32]
		DECLARE @row_id int

		-- Set all previous event records to 2 and insert a new event
		update job_event set value1 = 2 where event_type = 'jobScheduledChanged' and wo_id = @wo_id and oper_id = @oper_id and seq_no = @seq_no 
		-- TODO: Set parameter values here.

		INSERT INTO job_event
			(
