/*
-- ===========================================================================================
-- Name:  [sp_U_ofi_bcons_StartBinConsumption]
-- Description: Used to set the bin consumption MES attributes for a given line entity and process
--
-- Usage: Invoked from Work Tasks (MES UI); RequestBinsCons workflow
-- ===========================================================================================
-- Version Author  	Date (yyyy-MM-dd) 	Change description
-- 0.01.00 MH   	2025-06-05   		Initial version
-- 0.02.00 MH   	2025-06-10   		Move process parameters to entity parameters
-- ===========================================================================================*/
CREATE   PROCEDURE [dbo].[sp_U_ofi_bcons_StartBinConsumption]
    @EntityName nvarchar(80),
    @CollectionStartTime datetime,
    @CollectionEndTime datetime,
    @CollectionArea int
AS BEGIN
    SET NOCOUNT ON
    SET XACT_ABORT ON

    BEGIN TRANSACTION

        -- Validate parameters
        IF @EntityName IS NULL
            THROW 50000, '@EntityName is NULL.', 0

        IF @CollectionStartTime IS NULL
            THROW 50000, '@CollectionStartTime is NULL.', 1

        IF @CollectionEndTime IS NULL
            THROW 50000, '@CollectionEndTime is NULL.', 2

        IF @CollectionArea IS NULL
            THROW 50000, '@CollectionArea is NULL.', 3

        -- Find parent entity ID
        DECLARE @LineEntityId AS int

        SELECT @LineEntityId = [parent_ent_id]
        FROM [MESDB].[dbo].[ent] WITH (NOLOCK)
        WHERE [ent_name] = @EntityName

        IF @LineEntityId IS NULL
            THROW 50000, '@EntityName does not exist in the database, or does not have a parent entity assigned.', 4

        -- Select attribute IDs based on their names
        DECLARE
            @CollectionStartTimeAttributeId int,
            @CollectionEndTimeAttributeId int,
            @CollectionAreaAttributeId int,
            @CollectionWeighingAttributeId int

        SELECT @CollectionStartTimeAttributeId = [attr_id]
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE [attr_desc] = 'ActiveBinCollectionStartTime'
          AND [attr_grp] = 2 -- Entity

        IF @CollectionStartTimeAttributeId IS NULL
            THROW 50000, 'Could not find ''ActiveBinCollectionStartTime'' MES entity attribute.', 5

        SELECT @CollectionEndTimeAttributeId = [attr_id]
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE [attr_desc] = 'ActiveBinCollectionEndTime'
          AND [attr_grp] = 2 -- Entity

        IF @CollectionEndTimeAttributeId IS NULL
            THROW 50000, 'Could not find ''ActiveBinCollectionEndTime'' MES entity attribute.', 6

        SELECT @CollectionAreaAttributeId = [attr_id]
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE [attr_desc] = 'ActiveBinCollectionArea'
          AND [attr_grp] = 2 -- Entity

        IF @CollectionAreaAttributeId IS NULL
            THROW 50000, 'Could not find ''ActiveBinCollectionArea'' MES entity attribute.', 7

        SELECT @CollectionWeighingAttributeId = [attr_id]
        FROM [MESDB].[dbo].[attr] WITH (NOLOCK)
        WHERE [attr_desc] = 'ActiveBinCollectionWeighing'
          AND [attr_grp] = 2 -- Entity

        IF @CollectionWeighingAttributeId IS NULL
            THROW 50000, 'Could not find ''ActiveBinCollectionWeighing'' MES entity attribute.', 8

        -- Insert or update attributes
        DECLARE @EditComment AS nvarchar(128) = 'RequestBinsCons Workflow - Start Bin Consumption';

        -- MH: For some reason the entity update procedures require the last edited timestamp?
        DECLARE @EditTimestamp AS datetime

        SELECT @EditTimestamp = [last_edit_at]
        FROM [MESDB].[dbo].[ent_attr] WITH (NOLOCK)
        WHERE [ent_id] = @LineEntityId
          AND [attr_id] = @CollectionStartTimeAttributeId

        IF @EditTimestamp IS NOT NULL
            EXEC [MESDB].[dbo].[sp_U_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionStartTimeAttributeId,
                 @attr_value = @CollectionStartTime,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = @EditTimestamp
        ELSE
            EXEC [MESDB].[dbo].[sp_I_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionStartTimeAttributeId,
                 @attr_value = @CollectionStartTime,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = NULL

        SELECT @EditTimestamp = [last_edit_at]
        FROM [MESDB].[dbo].[ent_attr] WITH (NOLOCK)
        WHERE [ent_id] = @LineEntityId
          AND [attr_id] = @CollectionEndTimeAttributeId

        IF @EditTimestamp IS NOT NULL
            EXEC [MESDB].[dbo].[sp_U_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionEndTimeAttributeId,
                 @attr_value = @CollectionEndTime,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = @EditTimestamp
        ELSE
            EXEC [MESDB].[dbo].[sp_I_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionEndTimeAttributeId,
                 @attr_value = @CollectionEndTime,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = NULL

        SELECT @EditTimestamp = [last_edit_at]
        FROM [MESDB].[dbo].[ent_attr] WITH (NOLOCK)
        WHERE [ent_id] = @LineEntityId
          AND [attr_id] = @CollectionAreaAttributeId
        
        IF @EditTimestamp IS NOT NULL
            EXEC [MESDB].[dbo].[sp_U_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionAreaAttributeId,
                 @attr_value = @CollectionArea,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = @EditTimestamp
        ELSE
            EXEC [MESDB].[dbo].[sp_U_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionAreaAttributeId,
                 @attr_value = @CollectionArea,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = NULL

        SELECT @EditTimestamp = [last_edit_at]
        FROM [MESDB].[dbo].[ent_attr] WITH (NOLOCK)
        WHERE [ent_id] = @LineEntityId
          AND [attr_id] = @CollectionWeighingAttributeId

        IF @EditTimestamp IS NOT NULL
            EXEC [MESDB].[dbo].[sp_U_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionWeighingAttributeId,
                 @attr_value = 1,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = @EditTimestamp
        ELSE
            EXEC [MESDB].[dbo].[sp_U_Ent_Attr]
                 @ent_id = @LineEntityId,
                 @attr_id = @CollectionWeighingAttributeId,
                 @attr_value = 1,
                 @notes = NULL,
                 @last_edit_comment = @EditComment,
                 @last_edit_at = NULL
    COMMIT TRANSACTION
END

