/*--===========================================================================================
-- Name:		SP_U_OFI_BinDump]
-- Description:	to update IsDumping job attribute with known operid
-- 
-- Usage:		
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	MC				2025-06-05			Initial version
--===========================================================================================*/
-- *************************************************************************************************************************
CREATE PROCEDURE [dbo].[SP_U_OFI_BinDump_operid]
	-- Add the parameters for the stored procedure here
	@wo_id nvarchar(10),
	@oper_id nvarchar(40),
	@isActiveDump int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here

	declare
	@seq_no int,
	@mod_id varchar(30),
	@attr_id int

	
	select @seq_no=seq_no from job (NOLOCK) where oper_id=@oper_id and wo_id=@wo_id
	select @attr_id= ja.attr_id from job_attr ja (NOLOCK)
	inner join attr a (NOLOCK) on ja.attr_id=a.attr_id
	where a.attr_desc='isDumping'
	
		if not exists(select 1  from job j (nolock)
		inner join job_attr ja (nolock) on ja.wo_id=j.wo_id and ja.oper_id=j.oper_id and ja.seq_no=j.seq_no
		inner join attr a (nolock) on a.attr_id=ja.attr_id
		where j.wo_id=@wo_id and a.attr_desc='isDumping')
		BEGIN
			
			EXEC [dbo].[sp_I_Job_Attr]
			@wo_id =@wo_id,
			@oper_id =@oper_id,
			@seq_no = @seq_no,
			@attr_id = @attr_id,
			@attr_value = @isActiveDump,
			@notes = NULL,
			@last_edit_comment = NULL,
			@mod_id = @mod_id OUTPUT

			SELECT	@mod_id as N'@mod_id'
		END
		ELSE
		BEGIN
			select @mod_id=CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id))) from job_attr (NOLOCK) where wo_id=@wo_id and oper_id=@oper_id and seq_no=@seq_no and attr_id =@attr_id
			--update job_attr set attr_value =@isActiveDump where mod_id=@mod_id --wo_id=@wo_id and seq_no=@seq_no and attr_id=@attr_id
			EXEC [dbo].[sp_U_Job_Attr]
				@wo_id = @wo_id,
				@oper_id = @oper_id,
				@seq_no = @seq_no,
				@attr_id = @attr_id,
				@attr_value = @isActiveDump,
				@notes = NULL,
				@last_edit_comment = NULL,
				@mod_id = @mod_id
		END

END

