--===========================================================================================
-- Name:    sp_s_ei_close_purch_order_with_transit_loss
-- Description:  Returns closed purchase order
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)	Change description
-- 0.01.00  Karthik     2022-01-26			Initial version.
-- 0.02.00  Lavkesh     2024-02-18			Added logic to handle trainsit gain.
-- 0.03.00  Lavkesh     2024-03-06			Removed logic to handle trainsit gain based on the discussion with SAP
-- 0.04.00  DS			2024-03-17			Added logic to add the sublot number, added sp sp_S_ofi_Sublot to get the sublot
-- 1.00.00	JSC			2026-03-27			CR585 - Refactor and prevent TECO prior Transit Loss report
-- ===========================================================================================

CREATE   PROCEDURE [dbo].[sp_s_ei_close_purch_order_with_transit_loss]
AS
BEGIN
	--WO State 0 = Released, 1 = Started, 2 = Completed, 3 = Closed
	DECLARE @wo_id             VARCHAR(40),
			@pend_trans_cnt    INT,
			@gr_msgs_cnt       INT,
			@attr_id           INT,
			@item_id           NVARCHAR(40),
			@lot_no            NVARCHAR(40)
	DECLARE @error_msg         NVARCHAR(500),
			@error_severity    INT,
			@error_state       INT,
			@mod_id            VARCHAR(30),
			@item_no_puo_doc   NVARCHAR(40)
	DECLARE @obd_qty           DECIMAL(18,3),
			@qty_prod          DECIMAL(18,3),
			@qty_prod_erp      DECIMAL(18,3),
			@user              VARCHAR(4000),
			@diff_qty          DECIMAL(18,3),
			@ent_id            INT,
			@job_pos           INT,
			@seq_no            INT,
			@oper_id           VARCHAR(500),
			@row_id            INT,
			@reas_cd           INT,
			@shift_start_local DATETIME,
			@created_at_utc    DATETIME
	DECLARE @sublot AS TABLE ( sublot_counter NVARCHAR(40), sublot_no NVARCHAR(40) )
	DECLARE @lsublot_no NVARCHAR(40)
	SET NOCOUNT ON
	BEGIN TRY
		SET @wo_id = NULL;

		SELECT @attr_id = attr_id
		FROM attr WITH(NOLOCK)
		WHERE attr_desc = 'ReportedToSAP'
			AND attr_grp = 6; -- v1.00 ADDED --1=Items, 2=Entities, 3=Lots, 4=Item Classes, 5=Jobs, 6=WO, 7=Operations, 8=Processes, 9=Sublots, 10=Samples, 11=Results, 12=Lines, 13=Shifts
		
		SELECT TOP 1 @wo_id    = ip.wo_id,
			@qty_prod          = SUM(qty_prod) ,
			@qty_prod_erp      = SUM(qty_prod_erp) ,
			@obd_qty           = wo_qty,
			@ent_id            = MAX(ip.ent_id),
			@seq_no            = MAX(seq_no),
			@item_no_puo_doc   = MAX(item_no_puo_doc),
			@oper_id           = MAX(ip.oper_id),
			@shift_start_local = MAX(ip.shift_start_local),
			@created_at_utc    = MAX(ip.created_at_utc),
			@item_id           = ip.item_id,
			@lot_no            = ip.lot_no
		FROM item_prod ip WITH(NOLOCK)
			INNER JOIN ofi_wo_ext wo_ext WITH (NOLOCK) ON ip.wo_id = wo_ext.wo_id AND wo_ext.module = 'PO' -- v1.00 Added
			--INNER JOIN
			--	(   SELECT wo_id,
			--			wo_qty,
			--			item_no_puo_doc
			--		FROM ofi_wo_ext WITH (NOLOCK)
			--		WHERE module = 'PO') wo_ext ON ip.wo_id = wo_ext.wo_id
			INNER JOIN wo WITH (NOLOCK) ON wo_ext.wo_id = wo.wo_id AND wo.state_cd >= 3  -- v1.00 Added
			--INNER JOIN
			--	(   SELECT *
			--		FROM wo WITH(NOLOCK)
			--		WHERE state_cd >=3) wo ON wo_ext.wo_id = wo.wo_id
			LEFT OUTER JOIN wo_attr wa WITH (NOLOCK) ON wo.wo_id = wa.wo_id AND wa.attr_id = @attr_id
				--AND NOT EXISTS
				--(   SELECT attr_value
				--	FROM wo_attr WITH(NOLOCK)
				--	WHERE attr_id = @attr_id
				--		AND wo_id = wo.wo_id )
				--left join wo_attr wa on wa.wo_id = wo.wo_id and wa.attr_id = @attr_id
				--where wa.attr_id is null	-- Reported to SAP attribute shouldn't exist for this work order
		WHERE ISNULL(wa.attr_value,'0') = '0'
		GROUP BY ip.wo_id,
				wo_qty,
				ip.item_id,
				ip.lot_no
		HAVING TRY_CONVERT(NVARCHAR(50),SUM(qty_prod)) = TRY_CONVERT(NVARCHAR(50),SUM(qty_prod_erp)) --v1.00 Added fix for when MES considered equal quantities to be different floats

		-- if we find 1 wo, then check if OBD are OK and COMPLETED
		IF @wo_id IS NOT NULL
		BEGIN
			PRINT 'Inside wo_id'
			IF @obd_qty > @qty_prod -- Does transit loss exists ?  Then record it.-- 0.02.00
			BEGIN
				BEGIN TRANSACTION;
					
					SELECT @user = CURRENT_USER
					
					-- v1.00: Added: Update the job information to the latest job that produced anything
					SELECT TOP 1  @oper_id = oper_id
								 ,@seq_no = seq_no
					FROM item_prod i WITH (NOLOCK)
					WHERE i.wo_id = @wo_id
					ORDER BY i.last_edit_at DESC

					-- 0.03.00  DS	, added the logic for sublot number
					INSERT INTO @sublot
					EXECUTE [dbo].[sp_S_ofi_Sublot] @wo_id ,
													@oper_id ,
													@seq_no

					-- Select into variable
					SELECT TOP 1 @lsublot_no = CONCAT(sublot_no,'R')
					FROM @sublot

					SET @diff_qty = @obd_qty - @qty_prod
					
					SELECT @reas_cd = reas_cd
					FROM item_reas WITH (NOLOCK)
					WHERE reas_desc = 'Transit Loss'
				
					SET @diff_qty = ABS(@diff_qty)

					SELECT TOP 1 @created_at_utc = DATEADD(SECOND,-1,job_end_utc)
					FROM job_history WITH (NOLOCK)
					WHERE wo_id     = @wo_id
						AND seq_no  = @seq_no
						AND oper_id = @oper_id
					ORDER BY job_end_utc DESC

					--PRINT CAST(@created_at_utc AS VARCHAR) + ' ' + CAST(@oper_id AS VARCHAR) + ' ' + CAST(@seq_no AS VARCHAR) + ' ' + @wo_id

					EXEC sp_I_Item_Prod_AddProdPostExec @session_id             = -1,
														@user_id                = @user,
														@ent_id                 = @ent_id,
														@qty_prod               = @diff_qty,
														@wo_id                  = @wo_id,
														@oper_id                = @oper_id,
														@seq_no                 = @seq_no,
														@created_at_utc         = @created_at_utc,
														@shift_start_local      = @shift_start_local,
														@hour_start_local       = NULL,
														@shift_id               = NULL,
														@item_id                = @item_id,
														@reas_cd                = @reas_cd,
														@lot_no                 = @lot_no,
														@rm_lot_no              = NULL,
														@sublot_no              = @lsublot_no,
														@rm_sublot_no           = NULL,
														@to_ent_id              = 758, -- hardcoded to wAste area?
														@processed              = 0,
														@byproduct              = 0,
														@ext_ref                = NULL,
														@move_status            = 0,
														@genealogy_id           = NULL,
														@event_id               = NULL,
														@segment_requirement_id = NULL,
														@segment_response_id    = NULL,
														@comments               = 'Purchase order close with transit loss',
														@spare1                 = '',
														@spare2                 = '',
														@spare3                 = '',
														@spare4                 = '',
														@time_zone_bias_value   = NULL,
														@row_id                 = @row_id OUT
					
					--Begin change(KN 13Apr23 - Delete the inventory created by sp_I_Item_Prod_AddProdPostExec)
					DECLARE @inv_row_id INT					
					SELECT TOP 1 @inv_row_id = row_id
					FROM item_inv WITH (NOLOCK)
					WHERE wo_id = @wo_id
						AND oper_id = @oper_id
						AND seq_no = @seq_no
					ORDER BY last_edit_at DESC

					SET @inv_row_id = COALESCE(@row_id,@inv_row_id) -- modified to get the one inserted above

					--PRINT @INV_ROW_ID
					IF ISNULL(@inv_row_id,-1) <> -1
					BEGIN
						PRINT 'inventory exist'
						EXEC sp_D_Item_Inv @inv_row_id
					END
				--End change
				COMMIT TRANSACTION
				--SET  @wo_id = NULL
			END
			-- v1.00 Modified so it doesn't go here when createing a transit loss
			ELSE 
			BEGIN 
				BEGIN TRANSACTION;

					SELECT @pend_trans_cnt = COUNT(*)
					FROM item_prod WITH (NOLOCK)
					WHERE wo_id      = @wo_id
						AND qty_prod > qty_prod_erp

					SELECT @attr_id  = attr_id
					FROM attr WITH (NOLOCK)
					WHERE attr_desc = 'GR_Against_OBD_Messages_Count'
						AND attr_grp = 6;  -- v1.00 ADDED

					SELECT @gr_msgs_cnt = attr_value
					FROM wo_attr WITH (NOLOCK)
					WHERE wo_id     = @wo_id
						AND attr_id = @attr_id

					SELECT @attr_id = attr_id
					FROM attr WITH(NOLOCK)
					WHERE attr_desc = 'ReportedToSAP'
						AND attr_grp = 6; -- v1.00 ADDED --1=Items, 2=Entities, 3=Lots, 4=Item Classes, 5=Jobs, 6=WO, 7=Operations, 8=Processes, 9=Sublots, 10=Samples, 11=Results, 12=Lines, 13=Shifts
		

					SELECT wo_id                                           PurchaseOrder_Doc_Number,
						@item_no_puo_doc                                   ItemNumberofPurchasing_Document,
						'CLOSE'                                            Status,
						ISNULL(@pend_trans_cnt,0) + ISNULL(@gr_msgs_cnt,0) Number_of_GRMessages,
						FORMAT(CAST(last_edit_at AS DATE),'yyyyMMdd')      Closing_Date,
						FORMAT(CAST(last_edit_at AS DATETIME),'hhmmss')    Closing_Time,
						FORMAT(CAST(GETDATE() AS DATE),'yyyyMMdd')         File_Generation_Date,
						FORMAT(CAST(GETDATE() AS DATETIME),'hhmmss')       File_Generation_Time,
						''                                                 Document,
						''                                                 MESSAGE
					FROM wo WITH (NOLOCK)
					WHERE wo_id = @wo_id

					--PRINT @ATTR_ID
					
					IF NOT EXISTS ( SELECT 1
									FROM wo_attr WITH (NOLOCK)
									WHERE wo_id     = @wo_id
										AND attr_id = @attr_id)
					BEGIN
						PRINT 'no exist'
						EXEC dbo.sp_I_Wo_Attr @wo_id,
												@attr_id,
												'1',
												'',
												'CLOSED BY EI',
												@mod_id OUT --Add wo_attr to indicate the wo is closed and sent to SAP (Stops being picked up in the future by the same SP)
						PRINT 'Close'
					END
					ELSE
					BEGIN
						UPDATE wo_attr
						SET attr_value = '1'
						WHERE wo_id = @wo_id
							AND attr_id = @attr_id
					END
				--Update item_prod set qty_prod_erp = qty_prod,spare4= '1' where wo_id = @wo_id ---TBC with Sudhakar
				COMMIT TRANSACTION
			END
		END
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
			ROLLBACK TRANSACTION;

		SELECT @error_msg   = Error_message(),
			@error_severity = Error_severity(),
			@error_state    = Error_state();

		RAISERROR(@error_msg,@error_severity,@error_state)
	END CATCH
END

--===========================================================================================  
-- Name:  [sp_U_ofi_SAVEMAXBLEND]  
-- Description: The stored procedure will save the result of the Max Blend Ratio 
--  
-- Usage: In the inventory scree
-- ===========================================================================================  
-- Version	Author  Date (yyyy-MM-dd)	Change description  
-- 0.01.00	TB      2023-04-13			Initial version.  
-- 0.01.01  DS		2024-02-09			Updated header comments & nolock
-- 0.01.01  DS		2024-03-07			Changed the attribute value as decimal 
-- 0.02.00	YG		2024-03-21			Edit Last Edit By
-- ===========================================================================================  
  
  CREATE PROCEDURE [dbo].[sp_U_ofi_SAVEMAXBLEND]
	(  
		@lot_no NVARCHAR(80)=NULL,
		--@attr_value FLOAT,
		--@attr_value decimal(4,3),
		@attr_value NVARCHAR(80),
		@item_id NVARCHAR(40),
	    @audit_trail BIT = 1,
		@user_name Nvarchar (40),
		@iRowId INT = NULL OUT
	)   
	AS

	BEGIN

	DECLARE 
	@attr_id INT,
	@mod_id varchar(30),
	@notes NOTES,
	@last_edit_comment nvarchar(254),
	@last_edit_by nvarchar(40),--= @user_name,
	@last_edit_at datetime = NULL,
	@item_desc NVARCHAR(100)=NULL,
	@auditTrailParameters ofi_AUDITTRAILPARAMETERS,

	
    @strModuleName NVARCHAR(80) = 'INV_EditBlendRatio',
    @strFunctionName NVARCHAR(80) = 'UI',
	@strActivityMsg NVARCHAR(200) = 'update',
	@strCommentMsg NVARCHAR(200) = 'Item id:'+@item_id+' lot_no:'+@lot_no+ ' updated From [dbo].[sp_U_ofi_SAVEMAXBLEND]'
	
   IF (@audit_trail is NULL or @audit_trail = '')
	BEGIN 
	SET @audit_trail = 1;
   END


	SELECT @iRowId = ii.row_id , @last_edit_by =ii.last_edit_by 
	FROM lot_attr ii WITH (NOLOCK)
	WHERE ii.lot_no=@lot_no

	SET @attr_id= (select  attr_id from attr WITH (NOLOCK) where attr_desc ='MaxBlendRatio')
	select @iRowId as row_id ,@user_name as UserName , @attr_id as MaxBlenAttrId
	
	If EXISTS(select attr_value from lot_attr WITH (NOLOCK) where attr_id=(select  attr_id from attr WITH (NOLOCK) where attr_desc ='MaxBlendRatio') AND lot_no =@lot_no)
		BEGIN

		UPDATE lot_attr
		SET attr_value = @attr_value 
		WHERE lot_no=@lot_no and row_id=@iRowId
		 IF (@audit_trail = 1)
				BEGIN
		
					INSERT INTO @auditTrailParameters
					(
						row_id, 
						field_name, 
						field_value
					) 
					VALUES 
					 (
						@iRowId, 
					   'row_id', 
						CAST(@iRowId  AS NVARCHAR(40))
					),
		 
					(
						@iRowId, 
						'item_id', 
						@item_id
					),
					(
						@iRowId, 
						'lot_no', 
						 @lot_no
					),
		
					(
						@iRowId,
						'attr_value',
						 CAST(@attr_value AS NVARCHAR(40))
					),
					(
						@iRowId,
						'last_edit_by', 

						@user_name 
					)
	
					EXEC sp_I_ofi_AuditTrail 
						@module_id = @strModuleName,
						@function_id = @strFunctionName,
						@auditTrailParameters = @auditTrailParameters,
						@user_id = @user_name,
						@activity = @strActivityMsg,
						@audit_category = 'Info',
						@comments = @strCommentMsg,
						@keyField1   = @item_desc, 
						@keyField2   = @lot_no,
						@keyField3 =@item_id

					 END

		END
	ELSE
		BEGIN
					EXEC sp_I_Lot_Attr 
						@item_id,
						@lot_no,
						@attr_id,
						@attr_value,
						@notes,
						@last_edit_comment,
						@mod_id
		END
   
	END

CREATE PROCEDURE [dbo].[sp_I_Qm_Spec]
(@qm_spec_name STRING40,
@qm_spec_desc STRING80_NULL,
@edit_level INT32 = 1,
@ver_id STRING40,
@start_eff_local datetime,
@end_eff_local datetime,
@start_eff_utc datetime = null,
@end_eff_utc datetime = null,
@ent_id INT32_NULL,
@item_id STRING40_NULL,
@item_category_id INT32_NULL,
@process_id STRING40_NULL,
@oper_id STRING40_NULL,
@category_id INT32 = 0,
@plan_id INT32,
@num_pts_per_page INT32 = NULL,
@display_seq INT32 = 1,
