) AS
-- ***********************************************************************************************************************
-- Module Name       - sp_I_Qm_Spec
-- Description       - Insert a row into the table qm_spec
-- Author
-- Date Created         -  10/26/2010
-- Version            - 4.5
--
-- Copyright (c) 2020 AVEVA Group plc. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified  Modified_By   Ver    Changes
-- 03/25/2011    Ibrahim      4.2      Added a condition to check whether sample plan id is null.
-- 07/28/2011     Johnny               Added num_pts_per_page column
-- 04/13/2020     Sara          6.2    Added display_seq column
-- 05/07/2020	Raghu		6.2	UserStory:1302835 - As Bruce, I want the QMSpec Web APIs to pass Date/Times in UTC so that the user doesn't need to convert to entity local time
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
BEGIN
SET NOCOUNT ON
DECLARE  @last_edit_by  NVARCHAR(40)

--Validate Sample Plan Id.
IF ( @plan_id IS NULL ) BEGIN
   RAISERROR('Sample Plan Id cannot be null.<7232>', 16, 1)
   RETURN -1
END

IF (@start_eff_utc IS NOT NULL) SET @start_eff_local = dbo.fn_TZ_GetLocalDateFromUtc(@ent_id, @start_eff_utc)
ELSE BEGIN
	IF (@start_eff_local IS NOT NULL) SET @start_eff_utc = dbo.fn_TZ_GetUtcDateFromLocal(@ent_id, @start_eff_local, GETUTCDATE())
	IF (@start_eff_local IS NOT NULL) SET @start_eff_utc = dbo.fn_TZ_GetUtcDateFromLocal(@ent_id, @start_eff_local, GETUTCDATE())
	ELSE BEGIN
		SET @start_eff_utc = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )
		SET @start_eff_local = dbo.fn_TZ_GetLocalDateFromUtc(@ent_id, @start_eff_utc)
	END
END

IF (@end_eff_utc IS NOT NULL) SET @end_eff_local = dbo.fn_TZ_GetLocalDateFromUtc(@ent_id, @end_eff_utc)
ELSE BEGIN
	IF (@end_eff_local IS NOT NULL) SET @end_eff_utc = dbo.fn_TZ_GetUtcDateFromLocal(@ent_id, @end_eff_local, GETUTCDATE())
END

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

	IF @edit_level IS NULL SET @edit_level = 1
	IF @category_id IS NULL SET @category_id = 0
	IF @display_seq IS NULL SET @display_seq = 1


INSERT INTO qm_spec
(
qm_spec_name,
qm_spec_desc,
edit_level,
ver_id,
start_eff_utc,
start_eff_local,
end_eff_utc,
end_eff_local,
ent_id,
item_id,
item_category_id,
process_id,
oper_id,
category_id,
plan_id,
num_pts_per_page,
display_seq,
spare1,
spare2,
spare3,
spare4,
last_edit_comment,
last_edit_by,
last_edit_at)


VALUES
(
@qm_spec_name,
@qm_spec_desc,
@edit_level,
@ver_id,
@start_eff_utc,
@start_eff_local,
@end_eff_utc,
@end_eff_local,
@ent_id,
@item_id,
@item_category_id,
@process_id,
@oper_id,
@category_id,
@plan_id,
@num_pts_per_page,
@display_seq,
@spare1,
@spare2,
@spare3,
@spare4,
@last_edit_comment,
@last_edit_by,
@last_edit_at
)
END
select @qm_spec_id = SCOPE_IDENTITY()

