--Get Date for @created_at_local
SET @created_at_local = NULL
EXEC sp_TZ_GetDateInfo NULL,@created_at_utc,@created_at_local OUTPUT
-- TRACE
EXEC @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Item_Cons', @src_key='GetDateInfo', @date_val1 = @created_at_local,@date_val2 = @created_at_utc


EXEC sp_S_GetUtcDate @shift_start_local, @tz_temp, @shift_start_utc OUTPUT -- Added 07/30/2007


IF @item_scrapped IS null SET  @item_scrapped = 0
IF @qty_cons_erp IS null SET @qty_cons_erp = 0
