	ent_id,
	shift_id,
	grade_cd,
	status_cd,
	from_ent_id,
	qty_cons,
	qty_cons_erp,
	ext_ref,
	transaction_type,
	genealogy_id,
	upstream_event_id,
	segment_requirement_id,
	segment_response_id,
	comments, -- Added 07/20/2009 RWB
	spare1,
	spare2,
	spare3,
	spare4,
	last_edit_comment,
	last_edit_by,
	last_edit_at,
	--created_at
	created_at_utc,	-- Added 07/30/2007 AML
	created_at_local	-- Added 07/30/2007 AML
)
VALUES
(
	@wo_id,
	@oper_id,
	@seq_no,
	--@shift_start,
	@shift_start_utc,	-- Added 07/30/2007 AML
	@shift_start_local,	-- Added 07/30/2007 AML
	@item_id,
	@lot_no,
	@fg_lot_no,
	@sublot_no,
	@fg_sublot_no,
	@reas_cd,
	@user_id,
	@item_scrapped,
	@ent_id,
	@shift_id,
	@grade_cd,
	@status_cd,
	@from_ent_id,
	@qty_cons,
	@qty_cons_erp,
	@ext_ref,
	@transaction_type,
	@genealogy_id,
	@upstream_event_id,
	@segment_requirement_id,
	@segment_response_id,
	@comments, -- Added 07/20/2009 RWB
	@spare1,
	@spare2,
	@spare3,
	@spare4,
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at,
	--@created_at
	@created_at_utc,	-- Added 07/30/2007 AML
	@created_at_local	-- Added 07/30/2007 AML
)

SET @row_id = SCOPE_IDENTITY()

--===========================================================================================
-- Name:		sp_I_ofi_qm_AUT_samplecreationrequest
-- Description: This SP will create sample in MES
-- Usage:		Manual Sample request UI
