CREATE   PROCEDURE [dbo].[sp_I_ofi_qm_AUT_samplecreationrequest]
	@ent_id INT ,
	@frequency STRING80 = NULL ,
	@wo_id STRING80 = NULL ,
	@autitem_id STRING80 = NULL ,
	@oper_id STRING80 = NULL ,
	@plevel STRING80 = NULL ,
	@stage STRING80 = NULL ,
	@seq INT =NULL ,
	@username STRING80 = NULL ,
	@sample_id INT32 = 0 OUTPUT,
	@CBWoId NVARCHAR(40) = NULL,
    @CBSeqNo INT = NULL,
    @CBSublotNo INT = NULL

AS
BEGIN
	DECLARE @return_value INT ,
			@def_lot_no NVARCHAR(40) ,
			@item_id NVARCHAR(40) ,
			@mesitem_id NVARCHAR(40) ,
			@qmspec_name NVARCHAR(40) ,
			@qmspec_id INT ,
			@frequency_id INT ,
			@ent_name NVARCHAR(80) ,
			@sampleplan_id NVARCHAR(80) ,
			@plan_name NVARCHAR(80) ,
			@customerId NVARCHAR(80) ,
			@errormessage NVARCHAR(MAX) ,
			@infoCheck INT = 0 ,
			@aut_deflevel NVARCHAR(40) ,
			@aut_defstage NVARCHAR(40) ,
			@attr_id INT ,
			@attrLottypedesc NVARCHAR(80) = 'LotTypeForSample' ,
			@sublot_no NVARCHAR(40),--- BatchMaker or Sublot			
			@attr_value NVARCHAR(80) ,
			@smpCount INT = 0 ,
			@line_id INT ,
			@sent_to_lims INT ,
			@pslevel NVARCHAR(40) ,
			@pstage NVARCHAR(40) ,
			@wo_cust NVARCHAR(80) ,
			@sample_status INT ,
			@freq_id INT ,
			@plan_id INT ,
			@lot_no NVARCHAR(80) ,
			@lims_sublotno NVARCHAR(80);
	DECLARE @tblSublot AS TABLE (sublot_no NVARCHAR(80));
	DECLARE @tblvalidPlans AS TABLE ( row_num INT ,item_id NVARCHAR(40) ,plan_id INT ,qm_spec_id INT ,freq_id INT ,customer NVARCHAR(80) ,plevel NVARCHAR(40) ,stage NVARCHAR(40) );
	DECLARE @tblvalidcustPlans AS TABLE ( qm_spec_id INT ,plan_id INT );
	--GET MES ITEM ID
	SELECT @mesitem_id = item_id
	FROM item WITH (NOLOCK)
		CROSS APPLY ufn_ofi_mes_aut_itemid(item.item_id, 1) autitem
	WHERE autitem.aut_item_id = CAST(@autitem_id AS NVARCHAR);
	--GET FREQUNECY ID FROM AUT FREQUENCY TYPE
	SELECT @frequency_id = freq_id
	FROM sample_freq WITH (NOLOCK)
	WHERE freq_name = @frequency; --	 LIKE '%' + @frequency + '%'
	--GET ENTITY NAME
	SELECT @ent_name = ent_name
	FROM ent WITH (NOLOCK)
	WHERE ent_id = @ent_id;
	--GET CUSTOMER INFO FOR WO
	IF @wo_id IS NOT NULL
		AND @wo_id <> ''
	BEGIN
		SELECT @customerId = wxt.ship_to_customer
		FROM wo WITH (NOLOCK)
			INNER JOIN ofi_wo_ext wxt WITH (NOLOCK) ON wo.wo_id = wxt.wo_id
		WHERE wo.wo_id = @wo_id
	END
	--GET  ITEM ID	
	IF (@CBWoId IS NOT NULL AND @CBSeqNo >= 0 AND @CBSublotNo > 0)
	BEGIN
		SELECT TOP 1 @item_id = item_id,
					 @oper_id = COALESCE(@oper_id, oper_id), 
					 @seq = COALESCE(@seq, seq_no) 
		FROM job WITH (NOLOCK)
		WHERE wo_id = @wo_id
			AND (oper_id = @oper_id OR @oper_id IS NULL)
			AND (seq_no = @seq OR @seq IS NULL)
	END
	ELSE
	BEGIN
		SELECT TOP 1 @item_id = j.item_id,
					 @oper_id = COALESCE(@oper_id,j.oper_id), -- MOD v1.02 added coalesce for variable
					 @seq =  COALESCE(@seq,j.seq_no) -- MOD v1.02 added coalesce for variable
		FROM item_prod i WITH (NOLOCK)
			INNER JOIN job j WITH (NOLOCK) ON j.wo_id = i.wo_id 
											AND j.oper_id = i.oper_id 
											AND j.seq_no = i.seq_no 
											AND j.item_id = i.item_id
		WHERE i.wo_id = @wo_id
			AND i.ent_id = @ent_id
			AND (i.oper_id = @oper_id OR @oper_id IS NULL) -- MOD v1.02 Added
			AND (i.seq_no = @seq OR @seq IS NULL) -- MOD v1.02 Added
		ORDER BY i.last_edit_at DESC
	END
	--get item id from production if job is not running on entity
	IF @item_id IS NULL	-- v2.03 
		OR @item_id =''
	BEGIN
		SELECT TOP 1 
			@item_id = i.item_id,
			@wo_id = i.wo_id,
			@oper_id = i.oper_id,
			@seq = i.seq_no
		FROM item_prod i WITH (NOLOCK)
			INNER JOIN job j WITH (NOLOCK) ON j.wo_id = i.wo_id 
												AND j.oper_id = i.oper_id 
												AND j.seq_no = i.seq_no 
												AND j.item_id = i.item_id
		WHERE i.ent_id= @ent_id
		ORDER BY last_edit_at DESC
		--SET @oper_id = NULL
		--SET @wo_id = NULL
		--SET @seq = NULL
	END
	INSERT INTO @tblvalidPlans
	SELECT ROW_NUMBER() OVER (   ORDER BY item_id ) AS row_id ,
		*
	FROM fn_S_ofi_QM_getPreferredSamplePlan(@item_id, @frequency_id, @customerId, @plevel, @stage)
	SELECT @smpCount = COUNT(1)
	FROM @tblvalidPlans
	PRINT @smpCount
	DECLARE @loopcnt INT = 1
	IF (@smpCount > 0)
	BEGIN
		WHILE (@loopcnt <= @smpCount) --LOOP THROUGH EACH UN-PROCESSED SAMPLE
		BEGIN
			PRINT @loopcnt
			SELECT @plevel = plevel ,
				@stage = stage ,
				@item_id = tvp.item_id ,
				@freq_id = freq_id ,
				@qmspec_id = tvp.qm_spec_id ,
				@plan_id = tvp.plan_id ,
				@qmspec_name = qs.qm_spec_name ,
				@plan_name = sp.plan_name
			FROM @tblvalidPlans tvp
				INNER JOIN [qm_spec] qs WITH (NOLOCK) ON qs.qm_spec_id = tvp.qm_spec_id
				INNER JOIN sample_plan sp WITH (NOLOCK) ON sp.plan_id = tvp.plan_id
			WHERE row_num = @loopcnt
			--GET ENTITY NAME
			SELECT @ent_name = ent_name
			FROM ent WITH (NOLOCK)
			WHERE ent_id = @ent_id
			PRINT @QMSPEC_NAME
			EXEC @return_value = [dbo].[sp_U_ofi_QM_Sample_GenerateASample] @ent_name = @ent_name ,
							   @site_name = NULL ,
							   @qm_spec_name = @qmspec_name ,
							   @ver_id = NULL ,
							   @sample_name = NULL ,
							   @item_id = @item_id ,
							   @wo_id = @wo_id ,
							   @oper_id = @oper_id ,
							   @seq_no = @seq ,
							   @plan_name = @plan_name ,
							   @requested_time_local = NULL ,
							   @requested_time_utc = NULL ,
							   @expiry_time = NULL ,
							   @warning_time = NULL ,
							   @time_zone_bias_value = NULL ,
							   @sample_id = @sample_id OUTPUT
			--GET @LotTypeForSample VALUE FOR LINE ID
			SELECT @attr_value = ea.attr_value
			FROM ent_attr ea WITH (NOLOCK)
				INNER JOIN attr a WITH (NOLOCK) ON ea.attr_id = a.attr_id
			WHERE ea.ent_id = @ent_id
				AND a.attr_desc = @attrLottypedesc
			DECLARE @lotno NVARCHAR(80)
			--UPDATE LOT DETAILS FOR CREATED SAMPLE
			IF (@attr_value = 'BatchMaker') -- GET ALL LOT NO. FOR WO
			BEGIN
				-- v2.01
				IF (@CBWoId IS NOT NULL AND @CBSeqNo >= 0 AND @CBSublotNo > 0)
				BEGIN
					-- Usamos la función que ya existe para generar el sublote y lote
					SELECT @sublot_no = out_sublot_no,  
						   @lotno = out_lot_no
					FROM [dbo].[ufn_S_ofi_GenerateSublot](@CBWoId, 'CakeBlendng', @CBSeqNo, @CBSublotNo);
				END
				ELSE
				BEGIN
					SELECT TOP 1 @sublot_no = TRIM(i.last_edit_comment) -- Batch Maker number for Cake Packing
					FROM item_prod i WITH (NOLOCK)
						INNER JOIN job j WITH (NOLOCK) ON j.wo_id = i.wo_id 
											AND j.oper_id = i.oper_id 
											AND j.seq_no = i.seq_no 
											AND j.item_id = i.item_id
					WHERE i.wo_id = @wo_id
						AND i.oper_id = @oper_id
						AND i.seq_no = @seq -- Add v1.02
					ORDER BY last_edit_at DESC
				
					SELECT 	@lotno = lot_no
							-- @sublot_no = sublot_no v0.02 Not needed anymore
					FROM item_prod WITH (NOLOCK)
					WHERE sublot_no = @sublot_no -- v0.02
				END
			END
			ELSE -- GET ALL SUBLOT NO. FOR WO
			BEGIN
				SELECT TOP 1 	@lotno = lot_no,
								@sublot_no = sublot_no
				FROM item_prod i WITH (NOLOCK)
					INNER JOIN job j WITH (NOLOCK) ON j.wo_id = i.wo_id 
											AND j.oper_id = i.oper_id 
											AND j.seq_no = i.seq_no 
											AND j.item_id = i.item_id
				WHERE i.wo_id = @wo_id
					AND i.oper_id = @oper_id
					AND i.seq_no = @seq -- Add v1.02
				ORDER BY last_edit_at DESC
			END
			--IF THERE IS NO PRODUCTION THEN SELECT DEFAULT LOT
			IF @sublot_no IS NULL
				OR @sublot_no=''
			BEGIN
				SELECT @lotno= def_lot_no
				FROM job_bom WITH (NOLOCK)
				WHERE wo_id = @wo_id
					AND oper_id = @oper_id
					AND seq_no = @seq -- Add v1.02
					AND def_lot_no IS NOT NULL
				SET @sublot_no = NULL
			END
			UPDATE sample
			SET
				sublot_no = @sublot_no ,
				lot_no = @lotno ,
				spare4 = 'AUT' ,
				spare3 = 0
			WHERE sample_id = @sample_id
			SET @loopcnt = @loopcnt + 1;
		END --LOOP ENDS HERE
	END
	ELSE --RASIE ERROR FOR VALID SAMPLE PLAN NOT FOUND
	BEGIN
		SET @errormessage = ''
		SET @infoCheck = 2
		SET @errormessage = CONCAT ( dbo.fn_s_ofi_getLangString(500009, NULL, NULL),',
		 ' ,dbo.fn_s_ofi_getLangString(7760, NULL, NULL),':', @ent_name,',
		 ', dbo.fn_s_ofi_getLangString(1113, NULL, NULL),': ',@wo_id,',
		  ', dbo.fn_s_ofi_getLangString(63, NULL, NULL),': ',@item_id,',
		  ', dbo.fn_s_ofi_getLangString(714, NULL, NULL),': ', @oper_id,', 
		 ', dbo.fn_s_ofi_getLangString(7108, NULL, NULL),': ',@frequency,',
		  ', dbo.fn_s_ofi_getLangString(303, NULL, NULL),': ', @plevel,', 
		 ',dbo.fn_s_ofi_getLangString(500012, NULL, NULL),': ',@Stage )
		RAISERROR ( @errormessage ,16 ,1 )
		RETURN - 1
	END
END

