CREATE PROCEDURE [dbo].[sp_U_Oper_Prod_Rule]
  (@process_id nvarchar(40) ,
   @oper_id nvarchar(40) ,
   @ent_id int ,
   @outcome_no int ,
   @basis int ,
   @attr_id int ,
   @standard_value nvarchar(80) ,
   @relational_op int ,
   @sp_name nvarchar(40) ,
   @next_oper_id nvarchar(40) ,
   @next_ent_id int ,
   @is_default bit ,
   @spare1 nvarchar(1000) ,
   @spare2 nvarchar(1000) ,
   @spare3 nvarchar(1000) ,
   @spare4 nvarchar(1000) ,
   @last_edit_comment nvarchar(254) ,
   @last_edit_at datetime )
AS
--- ***********************************************************************************************************************
-- Module Name      - sp_U_Oper_Prod_Rule
-- Description      - Update an existing row in the table
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
-- Notes            - SP requires that all table fields be included
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified      Modified_By      Changes
--09/21/2005	Raghu		3.1.0	Part of DB Changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
UPDATE oper_prod_rule
SET basis = @basis,
    attr_id = @attr_id,
    standard_value = @standard_value,
    relational_op = @relational_op,
    sp_name = @sp_name,
    next_oper_id = @next_oper_id,
    next_ent_id = @next_ent_id,
    is_default = @is_default,
    spare1 = @spare1,
    spare2 = @spare2,
    spare3 = @spare3,
    spare4 = @spare4,
    last_edit_comment = @last_edit_comment
WHERE 	(process_id = @process_id AND
        oper_id = @oper_id AND
        ent_id = @ent_id AND
        outcome_no = @outcome_no AND
	last_edit_at = @last_edit_at)

 
