CREATE   PROCEDURE [dbo].[sp_I_ofi_EI_sampleresponse] (
	@sample_response NVARCHAR(1700)
	,@mes_sample_id INT OUTPUT
	)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	SET NOCOUNT ON;
 
	DECLARE @msg NVARCHAR(254) = '';
	DECLARE @msg_output NVARCHAR(500) = '';
	DECLARE @MESSampleRequestID NVARCHAR(40);
	DECLARE @LIMSSampleID NVARCHAR(40);
	DECLARE @CreateDate DATETIME;
	DECLARE @SamplePointID NVARCHAR(40);
	DECLARE @LocationLabel NVARCHAR(40);
	DECLARE @LocationPath NVARCHAR(40);
	DECLARE @Recurrence NVARCHAR(40);
	DECLARE @LIMS_initiated_request logical = 0;
	DECLARE @ent_id INT;
	DECLARE @plan_id INT;
	DECLARE @can_capture_qm_data LOGICAL;
	DECLARE @can_capture_util LOGICAL;
	DECLARE @spare3 NVARCHAR(80);
	DECLARE @customer NVARCHAR(80);
	DECLARE @sample_id INT32 = 0;
	DECLARE @lineName STRING80 = NULL;
	DECLARE @item_id STRING40 = NULL;
	DECLARE @level STRING80 = NULL;
	DECLARE @stage STRING80 = NULL;
 
	-- json body like as shown below:-
	/*
	sample01:-
 
	{
	  "MESSampleRequestID": "",
	  "LIMSSampleID": "S-230819-00012",
	  "CreateDate": "2023-08-19T13:41:36", 
	  "SamplePointID": "SP-00009",
	  "LocationLabel": "Line 1",
	  "LocationPath": "Wormer/Plant 2/Line 1",
	  "SchedulePlan": "TIME_8_W(MTWTF--)"
	}

	sample02:-
	{
	  "MESSampleRequestID": "125448744",
	  "LIMSSampleID": "S-230819-00012",
	  "CreateDate": "2023-08-19T13:41:36",
	  "SamplePointID": "",
	  "LocationLabel": "",
	  "LocationPath": "",
	  "SchedulePlan": ""
	}
	*/
	SELECT @MESSampleRequestID = JSON_VALUE(@sample_response, '$.MESSampleRequestID')
		,@LIMSSampleID = JSON_VALUE(@sample_response, '$.LIMSSampleID')
		,@CreateDate = JSON_VALUE(@sample_response, '$.CreateDate')
		,@SamplePointID = JSON_VALUE(@sample_response, '$.SamplePointID')
		,@LocationLabel = JSON_VALUE(@sample_response, '$.LocationLabel')
		,@LocationPath = JSON_VALUE(@sample_response, '$.LocationPath')
		,@Recurrence = JSON_VALUE(@sample_response, '$.Recurrence');
 
	IF (ISNULL(@LIMSSampleID, '') = '') 
	BEGIN
		--string_id 500008 = 'LIMS Sample id field is mandatory; it cannot be blank.'
		SELECT  @msg = dbo.fn_s_ofi_getLangString(500008, NULL, NULL) ;
		SET @msg_output = '{"code": 400,"status": "Error","error": "Error","message": "' + @msg + '"}';
 
		RAISERROR (
				@msg
				,16
				,1
				);
 
		Return -1 ;
	END ;
 
	IF EXISTS(SELECT 1 FROM sample WITH (NOLOCK) WHERE spare1 = @LIMSSampleID) 
	BEGIN
		--string_id 500007 = 'Duplicate LIMS Sample id: The given LIMS is already associated with another MES Sample'
		SELECT  @msg = dbo.fn_s_ofi_getLangString(500007, NULL, NULL) ;
		SET @msg_output = '{"code": 400,"status": "Error","error": "Error","message": "' + @msg + '"}';
 
		RAISERROR (
				@msg
				,16
				,1
				);
 
		Return -1 ;
	END ;
	-- check MES sample request id exist or not
	IF (@MESSampleRequestID = '')
		SET @LIMS_initiated_request = 1;
 
	-- If LIMS initiated request, this sample is not in MES system; so we have to first create the sample in MES. 
	IF (@LIMS_initiated_request = 1)
	BEGIN
		SELECT @ent_id = parent_ent_id
		FROM ent WITH (NOLOCK)
		WHERE parent_ent_id IN (select ent_id from ent where ent_name = @LocationLabel)
 
		--Retrieve the can_capture_* properties for utilization and qm_data
		SELECT @can_capture_util = can_capture_util
			,@can_capture_qm_data = can_capture_qm_data
		FROM ent WITH (NOLOCK)
		WHERE ent_id = @ent_id;
 
		--Verify whether the supplied entity can capture QM data, if not set it.
		IF (@can_capture_qm_data = 0)
		BEGIN
			UPDATE ent
			SET can_capture_qm_data = 1
			WHERE ent_id = @ent_id;
		END;
 
		-- get MES sample plan id
		SELECT @plan_id = sp.plan_id
			,@spare3 = sp.spare3
		FROM sample_plan sp WITH (NOLOCK)
		INNER JOIN qm_spec qm WITH (NOLOCK) ON qm.plan_id = sp.plan_id
			AND qm.ent_id = 271 --For test
		WHERE sp.spare1 = @SamplePointID
			AND CHARINDEX(@Recurrence, sp.spare3) > 0;
 
		IF (@plan_id IS NULL)
		BEGIN
			-- string_id 500004 = 'The given Sample Point is not exist in MES DB/ not associated with the given line.  Sample Point: '
			SELECT  @msg = CONCAT (dbo.fn_s_ofi_getLangString(500004, NULL, NULL), @SamplePointID, ', Line: ', @LocationLabel) ;
			SET @msg_output = '{"code": 500,"status": "Error","error": "Error","message": "' + @msg + '"}';
 
			RAISERROR (
					@msg
					,16
					,1
					);
 
			Return -1 ;
		END;
 
		SELECT @customer = [1]
		FROM ufn_ofi_SplitStringAsTableColumns(@spare3, '|');
 
		-- call the SP sp_I_ofi_qm_samplecreationrequest to create sample in MES
		EXEC sp_I_ofi_qm_samplecreationrequest
			@ent_id = @ent_id
			,@sampleplan_id = @plan_id
			,@sample_id = @sample_id OUTPUT ;		
	END;
	ELSE
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM sample WITH (NOLOCK)
				WHERE sample_id = @MESSampleRequestID
				)
		BEGIN
			-- string_id 500005 = 'The given MES Sample Point is not exist in MES DB.  Sample Point: '
			SELECT  @msg = CONCAT (dbo.fn_s_ofi_getLangString(500005, NULL, NULL), @SamplePointID) ;
			SET @msg_output = '{"code": 400,"status": "Error","error": "Error","message": "' + @msg + '"}';
 
			RAISERROR (
					@msg
					,16
					,1
					);
 
			Return -1 ;
		END;
	END;
 
	SET @sample_id = CAST(ISNULL(@MESSampleRequestID, -1) AS INT);
 
	IF EXISTS(SELECT 1 FROM sample WITH (NOLOCK) WHERE sample_id = @sample_id AND spare1 = @LIMSSampleID) 
	BEGIN
		--string_id 500007 = 'Duplicate LIMS Sample id: The given LIMS is already associated with another MES Sample'
		SELECT  @msg = CONCAT (dbo.fn_s_ofi_getLangString(500007, NULL, NULL), @MESSampleRequestID) ;
		SET @msg_output = '{"code": 400,"status": "Error","error": "Error","message": "' + @msg + '"}';
 
		RAISERROR (
				@msg
				,16
				,1
				);
 
		Return -1 ;
	END ;
 
	--v1.00 for those samples with only not monitored
	DECLARE @max_severity_cd INT
	SELECT DISTINCT @max_severity_cd = MAX(scc.severity_cd)
	FROM  sample_char_link sc WITH (NOLOCK)
		INNER JOIN qm_spec_char_link scc WITH (NOLOCK) ON scc.qm_spec_id = sc.qm_spec_id AND scc.char_id = sc.char_id
	WHERE sc.sample_id = @sample_Id

	-- update LIMS sample id in MES against the MES sample id
	-- v1.00 Added update on status and result for those samples where no result is expected. max severity is < 2 (not used or not monitored)
	UPDATE sample
	SET 
		 spare1 = @LIMSSampleID
		,spare4 = CASE WHEN spare4 IS NULL THEN  'LIMS' ELSE spare4 END		
		-- sample creation source.  values are: MES/LIMS/UI
		,spare3 = 1			-- this sample is created in MES system in response to LIMS; means this sample is already in LIMS system, so no need to send to LIMS
		,sample_status = CASE 
								WHEN @max_severity_cd < 2
									THEN 6 -- SAMPLE IS COMPLETED
								ELSE [sample_status] -- KEEP value
						 END
		,sample_result =  CASE 
								WHEN @max_severity_cd < 2
									THEN 2 -- RESULTS ARE GOOD
								ELSE [sample_status] -- KEEP value
						 END
	WHERE SAMPLE_ID = @sample_id;
END

