--===========================================================================================
-- Name: sp_U_ofi_st_RegisterTrasnferQty
-- Description: The stored procedure will transfer inventory from source to destination
-- 
-- Usage: Stock Transfer Workflow
-- ===========================================================================================
-- Version  Author          Date (yyyy-MM-dd)    Change description
-- 0.01.00  Veervar Joshi   2024-01-11           Initial version.
-- 0.01.01  LK              2024-01-25           Called stored procedure sp_u_ofi_st_audittrail to record audit trail
-- 0.01.02  Veervar         2024-01-31           Unique SU check added
-- 0.01.03  MC              2025-02-25           Select inventory from silo only if transfer_qty > 0
-- 0.01.04  MH              2025-11-05           [CR 00203562] Fix audit trail issue causing the transaction to become uncommittable; Reformatting + cleanup
-- ===========================================================================================-

CREATE PROCEDURE [dbo].[sp_U_ofi_st_RegisterTransferQty](
    @from_ent_name STRING80,
    @from_site_name STRING80,
    @to_ent_name STRING80,
    @to_site_name STRING80,
    @item_id STRING40,
    @to_item_id STRING40 = NULL,
    @lot_no STRING40,
    @to_lot_no STRING40,
    @sublot_no STRING40,
    @to_sublot_no STRING40,
    @from_grade_desc STRING80,
    @to_grade_desc STRING80,
    @from_status_desc STRING80,
    @to_status_desc STRING80,
    @transfer_qty TFLOAT,
    @transfer_qty_erp TFLOAT,
    @transfer_uom_desc STRING80 = NULL,
    @transfer_option INT32,
    @transfer_comments STRING254,
    @log_transfer INT32,
    @time_zone_bias_value int = 0,
    @autoreclassify INT=0,
    @username STRING80,
    @ent_id INT
)
AS
---------------------------------------------------------------------------------------------------------------------------
BEGIN
    SET NOCOUNT ON
    SET XACT_ABORT ON
    DECLARE
        @from_ent_id INT32,
        @to_ent_id INT32,
        @from_grade_cd INT32,
        @to_grade_cd INT32,
        @from_status_cd INT32,
        @to_status_cd INT32,
        @qty_uom_id INT32,
        @err_msg NVARCHAR(2000),
        @minID INT,
        @Plot_no STRING40,
        @pto_lot_no STRING40,
        @psublot_no STRING40,
        @pto_sublot_no STRING40,
        @pfrom_grade_desc STRING80,
        @pto_grade_desc STRING80,
        @pfrom_status_desc STRING80,
        @pto_status_desc STRING80,
        @ptransfer_qty TFLOAT,
        @typeOfCons NVARCHAR(20) = 'FIFO',
        @edit_at TDATETIME = GETDATE(),
        @edit_comment nvarchar(100) = NULL,
        @error_code nvarchar(max) = NULL,
        @errormessage NVARCHAR(MAX),
        @lock_for_input nvarchar(50) = 'false',
        @blk_for_quality_id int = 0,
        @blk_for_quality nvarchar(50) = NULL,
        @def_grd_attr_value nvarchar(50) = NULL,
        @unq_item_attr_value nvarchar(50) = NULL,
        @auto_reclass_attr_value nvarchar(50) = 'false'

    DECLARE @su_attr AS TABLE (
        attr_id    int,
        attr_desc  nvarchar(80),
        attr_value STRING1700_NULL
    )

    SELECT
        @from_ent_id = dbo.fn_GetEntityID(@from_ent_name, @from_site_name),
        @to_ent_id = dbo.fn_GetEntityID(@to_ent_name, @to_site_name)

    --GET TYPE OF CONSUMPTION
    SELECT @typeOfCons = attr_value
    FROM ent_attr WITH (NOLOCK)
    WHERE ent_id = @from_ent_id
        AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) WHERE attr_desc = 'TypeOfCons')

    --CREATE TEMP TABLE
    IF OBJECT_ID('tempdb..#invlist1') IS NOT NULL
        DROP TABLE #invlist1
    
    CREATE TABLE #invlist1 (
        id           INT PRIMARY KEY,
        lot          NVARCHAR(40),
        sublot       NVARCHAR(40),
        qty          FLOAT,
        cons_qty     FLOAT,
        consume_full BIT,
        grade_cd     INT,
        status_cd    INT,
        row_id       int
    )

    -- VARIABLE DECLARATION
    DECLARE
        @currTransferredQty FLOAT=0,
        @newTrasnferredQty FLOAT =0,
        @target_qty float=0,
        @lineid int,
        @trowId int,
        @status int,
        @itemUOMId INT,
        @lineName NVARCHAR(80)
    SELECT
        @trowId = row_id,
        @currTransferredQty = ISNULL(qty_transferred, 0),
        @target_qty = target_qty,
        @lineid = ent_id,
        @status = transfer_status_cd
    FROM ofi_st_trans_selection
    WHERE ent_id = @ent_id
        AND is_active = 1

    --ITEM UOM CONVERSION FOR MAX CAPACITY
    SELECT @itemUOMId = uom_id
    FROM item
    WHERE item_id = @item_id

    --GET LINE NAME
    SELECT @lineName = ISNULL(description, ent_name)
    FROM ent
    WHERE ent_id = @lineid

    -- [0.01.04 - CR 00203562]
    -- Trigger SAP inventory reclassification WEI location
    -- MH: The location checks for the string "RECLASS" in the "comments" field to determine whether this is a reclassification. 
    IF @autoreclassify = 1
    BEGIN
        SET @transfer_comments = IIF(
            ISNULL(@transfer_comments, '') = '',
            'RECLASS',
            @transfer_comments + '; RECLASS')
    END
    -- [/0.01.04 - CR 00203562]

    --GET LIST OF LOTS TO TRANSFER BY TYPE OF CONSUMPTION
    IF @transfer_qty > 0 --0.01.03 - If transfer qty is 0 there is nothing to transfer
    BEGIN
        INSERT INTO #invlist1
            EXEC SP_SA_ofi_item_inv_typeOfCons @from_ent_id, @item_id, @transfer_qty, @typeOfCons
    END

    SELECT @minID = MIN(id)
    FROM #invlist1
    WHERE cons_qty > 0

    BEGIN TRY
        --LOOP THROUGH EACH LOT FOR TRANSFER
        WHILE (@minID IS NOT NULL)
        BEGIN
            SELECT
                @ptransfer_qty = cons_qty,
                @Plot_no = lot,
                @psublot_no = sublot,
                @from_grade_cd = grade_cd,
                @from_status_cd = status_cd
            FROM #invlist1
            WHERE id = @minID

            EXEC [sp_U_II_TransAndUpdInvByName]
                 @from_site_name = @from_site_name,
                 @to_site_name = @to_site_name,
                 @from_ent_name = @from_ent_name,
                 @to_ent_name = @to_ent_name,
                 @item_id = @item_id,
                 @to_item_id = @to_item_id,
                 @lot_no = @Plot_no,
                 @to_lot_no = @Plot_no,
                 @sublot_no = @psublot_no,
                 @to_sublot_no = @psublot_no,
                 @from_grade_desc = @from_grade_desc,
                 @to_grade_desc = @to_grade_desc,
                 @from_status_desc = @from_status_desc,
                 @to_status_desc = @to_status_desc,
                 @transfer_qty = @ptransfer_qty,
                 @transfer_qty_erp = @transfer_qty_erp,
                 @transfer_option = @transfer_option,
                 @transfer_comments = @transfer_comments,
                 @log_transfer = @log_transfer,
                 @transfer_uom_desc = @transfer_uom_desc

            SELECT @minID = MIN(id)
            FROM #invlist1
            WHERE id > @minID AND cons_qty > 0

        END
    END TRY
    BEGIN CATCH
        SET @errormessage = ERROR_MESSAGE()
        IF @errormessage LIKE '%{3205}%'
        BEGIN
            SET @errormessage = ''
            SET @errormessage = CONCAT(
                dbo.fn_s_ofi_getLangString(400018, NULL, NULL), @lineName, ', ',
                dbo.fn_s_ofi_getLangString(338, 1001, NULL), ' ', @from_ent_name, ', ',
                dbo.fn_s_ofi_getLangString(4259, NULL, NULL), ' : ', @to_ent_name, ', ',
                dbo.fn_s_ofi_getLangString(400017, NULL, NULL), @transfer_qty,
                dbo.fn_GetUOMDesc(@itemUOMId), '.# ')
        END
        RAISERROR(@errormessage, 16, 1)
        RETURN
    END CATCH

    --UPDATE TRANFERRED QUANTITY
    SET @newTrasnferredQty = @currTransferredQty + @transfer_qty
    
    UPDATE ofi_st_trans_selection
    SET qty_transferred = @newTrasnferredQty,
        last_edit_at_local = GETDATE(),
        last_edit_at_utc = GETUTCDATE(),
        last_edit_by = @username
    WHERE ent_id = @ent_id
        AND is_active = 1

    --check for unique item
    INSERT INTO @su_attr
    SELECT
        A.attr_id,
        A.attr_desc,
        EA.attr_value
    FROM ent_attr EA WITH (NOLOCK)
        INNER JOIN attr A WITH (NOLOCK)
            ON A.attr_id = EA.attr_id
    WHERE EA.ent_id = @to_ent_id
        AND A.attr_desc IN ('LockForInput', 'BlockForQuality', 'default_grade', 'unique_item_id', 'auto_reclassify')

    -- get all attribute values into variables
    --check lock for input       
    SELECT @lock_for_input = SA.attr_value
    FROM @su_attr SA
    WHERE SA.attr_desc = 'LockForInput'

    -- get blockforQuality value        
    SELECT
        @blk_for_quality_id = SA.attr_id,
        @blk_for_quality = SA.attr_value
    FROM @su_attr SA
    WHERE SA.attr_desc = 'BlockForQuality'

    -- get default grade value         
    SELECT @def_grd_attr_value = SA.attr_value
    FROM @su_attr SA
    WHERE SA.attr_desc = 'default_grade'

    -- get unique item value         
    SELECT @unq_item_attr_value = SA.attr_value
    FROM @su_attr SA
    WHERE SA.attr_desc = 'unique_item_id'

    IF (@autoreclassify = 0)
    BEGIN
        --BLOCK DESTINATION SILO IF UNIQUE ITEM NOT MATCHING
        IF (
            @def_grd_attr_value IS NOT NULL
            AND @unq_item_attr_value IS NOT NULL
            AND (@item_id <> @unq_item_attr_value OR @from_grade_desc <> @def_grd_attr_value)
        )
        BEGIN
            IF EXISTS (SELECT 1 FROM @su_attr SA WHERE SA.attr_desc = 'BlockForQuality')
            BEGIN
                SELECT @edit_comment = dbo.fn_ofi_lm_getLangString('300004', NULL, 10);
                SELECT @edit_at = ea.last_edit_at
                FROM ent_attr ea WITH (NOLOCK)
                WHERE ea.attr_id = @blk_for_quality_id
                    AND ea.ent_id = @to_ent_id

                EXEC [dbo].[sp_U_Ent_Attr]
                     @to_ent_id, 
                     @blk_for_quality_id,
                     1,
                     @error_code,
                     @edit_comment,
                     @edit_at
            END
            ELSE
            BEGIN
                EXEC [dbo].[Sp_i_ent_attr]
                     @ent_id = @to_ent_id,
                     @attr_id = @blk_for_quality_id,
                     @attr_value = 1,
                     @notes = @error_code,
                     @last_edit_comment = @edit_comment,
                     @last_edit_at = @edit_at OUTPUT
            END
        END
    END


    --RECORD AUDIT TRAIL
    IF (@autoreclassify = 1)
    BEGIN
        -------------Audit Trail------------------
        BEGIN TRY
        BEGIN
            DECLARE
                @auditTrailParameters ofi_AUDITTRAILPARAMETERS,
                @strModuleName nvarchar(80) = 'STOCK TRANSFER',
                @strFunctionName nvarchar(80) = 'Register Quantity WF',
                @strActivityMsg nvarchar(200) = 'EDIT',
                @strCommentMsg nvarchar(200) = 'Reclassified the Inventory'

            -- [0.01.04 - CR 00203562]
            -- Fix NULL @grade_cd and @statuscd variables
            -- MH: The variables were being read from but never written to, causing them to have the default value of NULL
            --     The redundant insertion to a temporary table which included NOT NULL columns caused the transaction to
            --     become uncommittable. The unused table has been removed, and the missing assignments have been added.
            DECLARE
                @itemid nvarchar(50) = @to_item_id,
                @grade_cd int,
                @statuscd int,
                @entid int = @to_ent_id,
                @qty nvarchar(50) = @transfer_qty,
                @rowid int,
                @last_edit_by nvarchar(50)

            SELECT TOP 1 @grade_cd = item_grade_cd
            FROM item_grade
            WHERE item_grade_desc = @to_grade_desc

            SELECT TOP 1 @statuscd = item_status_cd
            FROM item_state
            WHERE item_status_desc = @to_status_desc
            -- [/0.01.04 - CR 00203562]

            SELECT
                @rowid = row_id,
                @last_edit_by = last_edit_by
            FROM item_inv WITH (NOLOCK)
            WHERE item_id = @itemid
                AND ent_id = @entid

            DELETE FROM @auditTrailParameters
            -- MH: Cannot join these into one INSERT. It will attempt to cast the parameters into
            --     the same type as the first value and throw an error when it overflows.
            INSERT INTO @auditTrailParameters(row_id, field_name, field_value)
            VALUES (@rowid, '@ent_id', @entid)
            INSERT INTO @auditTrailParameters(row_id, field_name, field_value)
            VALUES (@rowid, '@item_id', @itemid)
            INSERT INTO @auditTrailParameters(row_id, field_name, field_value)
            VALUES (@rowid, '@grade_cd', @grade_cd)
            INSERT INTO @auditTrailParameters(row_id, field_name, field_value)
            VALUES (@rowid, '@state_cd', @statuscd)
            INSERT INTO @auditTrailParameters(row_id, field_name, field_value)
            VALUES (@rowid, '@qty_left', @qty)

            EXEC sp_I_ofi_AuditTrail @module_id = @strModuleName,
                @function_id = @strFunctionName,
                @auditTrailParameters = @auditTrailParameters,
                @keyField1 = NULL,
                @keyField2 = NULL,
                @keyField3 = NULL,
                @keyField4 = NULL,
                @keyField5 = NULL,
                @user_id = @last_edit_by,
                @activity = @strActivityMsg,
                @audit_category = 'Info',
                @comments = @strCommentMsg

        END
        END TRY
        BEGIN CATCH
            -- [0.01.04 - CR 00203562]
            -- Rethrow the error if the transaction becomes uncommittable instead of always silencing it to improve error debugging
            -- MH: Even if the error is caught, the transaction may become uncommittable. As there is no way to make an uncommittable
            --     transaction committable again, the most we can do is to rethrow the error to aid in debugging.
            --     Attempting to commit an uncommittable transaction will result in an error and roll it back anyway.
            IF XACT_STATE() = -1
                THROW
            -- [/0.01.04 - CR 00203562]
        END CATCH;
    END
END

