--===========================================================================================
-- Name:    SP_S_ofi_dcsHU_to_SAPHU
-- Description:  generate sap hu number based on dcs hu number

-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  AML, XPM    2026-03-11         Initial Version
-- 0.02.00  AML, XPM    2026-05-08         Updated how we get the first digit of the year.
-- ===========================================================================================
CREATE PROCEDURE [dbo].[sp_s_ofi_dcsHU_to_SAPHU] 
	@HUNumber NVARCHAR(80) = NULL, -- DCS HU Number
	@wo_id VARCHAR(100),
	@oper_id VARCHAR(100),
	@seq_no INT,
	@SAPNumber NVARCHAR(20) OUTPUT
AS 
BEGIN
	SET NOCOUNT ON;

	DECLARE @plant_code AS INT,
			@line_no VARCHAR(10),
			@line_ent INT,
			@year_sap NVARCHAR(2),
			@job_year INT,
			@job_decade INT,
			@job_year_digit INT,
			@dcs_year_digit INT,
			@resolved_year INT;

	-- Get the line number
	SELECT DISTINCT @line_ent = e.parent_ent_id
	FROM job ip WITH(NOLOCK) 
		INNER JOIN ent e WITH(NOLOCK) 
			ON e.ent_id = ip.run_ent_id
		INNER JOIN ent_attr ea WITH(NOLOCK) 
			ON ea.ent_id = e.parent_ent_id
		INNER JOIN ent ee WITH(NOLOCK) 
			ON ee.ent_id = ea.ent_id
	WHERE ea.attr_value = 'Line'
	  AND ip.wo_id = @wo_id
	  AND ip.oper_id = @oper_id
	  AND seq_no = @seq_no;

	SELECT @line_no = ea.attr_value
	FROM ent_attr ea WITH(NOLOCK) 
		INNER JOIN attr A WITH(NOLOCK) 
			ON A.attr_id = ea.attr_id
	WHERE A.attr_desc = 'LineCode' 
	  AND ea.ent_id = @line_ent;

	SET @line_no = CAST(RIGHT(@line_no, 1) AS VARCHAR(10));

	-- Get the plant code
	SELECT @plant_code = attr_value 
	FROM system_attr WITH(NOLOCK) 
	WHERE attr_desc = 'HUPlantCode';

	-- Get the job year
	SELECT TOP 1
		@job_year = YEAR(j.act_start_time_local)
	FROM job j WITH(NOLOCK)
	WHERE j.wo_id = @wo_id
	  AND j.oper_id = @oper_id
	  AND j.seq_no = @seq_no;

	-- Get the year digit from the HU number sent by DCS
	SET @dcs_year_digit = TRY_CONVERT(INT, SUBSTRING(@HUNumber, 2, 1));

	SET @job_decade = (@job_year / 10) * 10;
	SET @job_year_digit = @job_year % 10;

	IF @dcs_year_digit >= @job_year_digit
	BEGIN
		SET @resolved_year = @job_decade + @dcs_year_digit;
	END
	ELSE
	BEGIN
		SET @resolved_year = @job_decade + 10 + @dcs_year_digit;
	END;

	SET @year_sap = RIGHT(CAST(@resolved_year AS VARCHAR(4)), 2);

	-- Get the info from the HU number
	SET @SAPNumber = CONCAT(
		@plant_code,
		@line_no,
		LEFT(@HUNumber, 1),             
		@year_sap,                     
		SUBSTRING(@HUNumber, 3, 2),     
		SUBSTRING(@HUNumber, 5, 2),     
		RIGHT(@HUNumber, 3),            
		'0'                             
	);

	SELECT 
		@SAPNumber AS SAPHUNumber;
END

-- *******************************************************************************************************************************************************************
-- Name				: sp_I_ofi_EI_samplefreq
-- Description		: To create sample frequency.
--
-- Author			: Unnikrishnan Nair P G (GDC)
-- Creation date	: 2024-02-12
--
-- Usage			: Using IN LIMS interface EI location MES_LIMS_SamplePlan_IN
--	DECLARE @freq_id INT32; EXEC sp_I_ofi_EI_samplefreq 'TIME_12_H', '10022554', '1011325', 'Full', 'PhysChem', 'Color Test', 'Color', 'Lovibond', 1, @freq_id OUTPUT ; SELECT @freq_id ;
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Version			Authour				Date (yyyy-MM-dd)		Change Description
-- 00.01			PG					2024-02-12				Initial draft
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- *******************************************************************************************************************************************************************
CREATE PROCEDURE [dbo].[sp_I_ofi_EI_samplefreq] (
	@SourceLabel NVARCHAR(80)
	,@ProductID NVARCHAR(40)
	,@Customer NVARCHAR(40)
	,@LEVEL NVARCHAR(20)
	,@Stage NVARCHAR(20)
	,@TestMethod NVARCHAR(40)
	,@ParameterListID NVARCHAR(40)
	,@Variant NVARCHAR(40)
	,@enabled_freq LOGICAL = 1
	,@samplePlanType INT = 0 -- 0. LabVantage Product Variant (material and process based sample plan) --1. LabVantage Sample Point Schedule Plans (time and location based sample plan)
	,@freq_id INT32 OUTPUT
	)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	SET NOCOUNT ON;

	DECLARE @msg NVARCHAR(254) = '';
	DECLARE @msg_output NVARCHAR(500) = '';

	DECLARE @new_freq_name nvarchar(80) ;
	DECLARE @filter_by_spare1 LOGICAL = 0;
	DECLARE @filter_by_spare2 LOGICAL = 0;
	DECLARE @filter_by_spare3 LOGICAL = 0;
	DECLARE @filter_by_spare4 LOGICAL = 0;
	DECLARE @freq_name STRING40 = @SourceLabel;
	DECLARE @freq_desc STRING80_NULL = @SourceLabel;
	-- @freq_type: 0 = shift, 1 (default) = calendar time, 2 = run time, 3 = production, 4 and up = data change event (see DB documentation for details), 8 = job start,  19 = manual, 20 = job end, 6 = lot number change, 
	DECLARE @freq_type INT32 = 1;
	DECLARE @interval TFLOAT_NULL;
	-- @interval_unit: 0 = seconds, 1 = minutes, 2 = hours, 3 = day, 4 = weeks
	DECLARE @interval_unit INT32_NULL;
	DECLARE @prod_reset_option INT32_NULL;
	DECLARE @start_delay INT32_NULL = NULL;
	DECLARE @offset_start INT32_NULL;
	DECLARE @offset_start_unit INT32_NULL;
	DECLARE @offset_end INT32_NULL;
	DECLARE @offset_end_unit INT32_NULL;
	DECLARE @samples_per_shift INT32_NULL;
	DECLARE @multiplier INT32 = 1;
	DECLARE @enabled LOGICAL = @enabled_freq;
	DECLARE @expiry_time INT32_NULL;
	DECLARE @expiry_unit INT32_NULL;
	DECLARE @warning_time INT32 = 5;
	DECLARE @warning_unit INT32 = 1;
	DECLARE @spare1 STRING80_NULL = @LEVEL;
	DECLARE @spare2 STRING80_NULL = @Stage;
	DECLARE @spare3 STRING80_NULL = @Variant + '|' + @TestMethod;-- combination of variant and test method
	DECLARE @spare4 STRING80_NULL = @ProductID + '|' + ISNULL(@Customer, '') + '|' + @ParameterListID;-- combination of product id, customer and parameterlistid
	DECLARE @last_edit_comment STRING254_NULL = 'inserted through script';
	DECLARE @last_edit_at TDATETIME = GETDATE();
	DECLARE @frequency_part1 NVARCHAR(20);
	DECLARE @frequency_part2 NVARCHAR(20);
	DECLARE @frequency_part3 NVARCHAR(20);
	DECLARE @frequency_format_is_valid bit = 1 ;

	SET @freq_id = -1 ; --default value (invalid frequency)

	-- Sourcelabel, ie. frequency format:
	/*
	TIME_dd_H/M/S/D/W (MTWTFSS)
	Where:
	TIME_: fixed label
	dd: numeric value
	H: hour
	M: minute
	S: second
	D: day
	W: weeks
	(MTWTFSS) will be work with W
	 - “week” field only
	 - skipped days are respresented by “-”
	Examples:
	 - TIME_30_M -> frequency every 30 minutes.
	 - TIME_12_W (MTWTFSS) -> weekly 12 noon on Monday, Tuesday, Wednesday, Thursday, Friday, Saturday and Sunday
	 - TIME_14_W (M--T-SS) -> weekly 2 pm on Monday, Thursday, Saturday and Sunday (note the separator – as a placeholder)
	NOTE: LabVantage does not support interval in Seconds.


	JOB_START
	JOB_END
	LOT_CHANGE

	VOLUME_dd_MT/KG/BAG/PAL
	Where:
	dd : numeric value
	MT: Metric Ton
	KG: kg  
	LB: lb (Pound)
	BAG: bag
	PAL: Pallet
	Example: VOLUME_100_KG -> frequency every 100 kg.

	*/
	SELECT @frequency_part1 = [1]
		,@frequency_part2 = [2]
		,@frequency_part3 = [3]
	FROM ufn_ofi_SplitStringAsTableColumns(@SourceLabel, '_');

	-- @SourceLabel can be -> 'TIME' or 'VOLUME' or 'Job_Start'/'Job_End' or 'Lot_Change'
	IF (@SourceLabel = 'JOB_START') BEGIN
		SELECT @interval = NULL
			,@interval_unit = NULL
			,@freq_type = 8;
	END ;
	ELSE IF (@SourceLabel = 'JOB_END') BEGIN
		SELECT @interval = NULL
			,@interval_unit = NULL
			,@freq_type = 20;
	END ;
	ELSE IF (@SourceLabel = 'LOT_CHANGE') BEGIN
		SELECT @interval = NULL
			,@interval_unit = NULL
			,@freq_type = 6;
	END ;
	ELSE IF (@frequency_part1 = 'VOLUME') BEGIN		
		-- @interval_unit: MT = Metric Ton, KG = Kg, LB = Pound, BAG = bag, PAL = Pallet
		SELECT @interval = CONVERT(INT, @frequency_part2);

		SELECT @interval_unit = 5
			,@freq_type = 3
			,@prod_reset_option = 1 ;	-- ie. when the job changes
	END ;
	ELSE IF (@frequency_part1 = 'TIME') BEGIN		
		-- @interval_unit: 0 = seconds, 1 = minutes, 2 = hours, 3 = day, 4 = weeks
		SELECT @interval = CONVERT(INT, @frequency_part2);

		SELECT @interval_unit = CASE 
				WHEN @frequency_part3 = 'S'
					THEN 0
				WHEN @frequency_part3 = 'M'
					THEN 1
				WHEN @frequency_part3 = 'H'
					THEN 2
				WHEN @frequency_part3 = 'D'
					THEN 3
				WHEN @frequency_part3 = 'W'
					THEN 4
				ELSE -- can be combination (MTWTFSS) with W.  To achieve this, need to create SQL Server job scheduler; in this scenario, the trigger is always happening from LIMS side, so in MES, no need to do anything.
					5
				END;

		IF (@interval_unit = 5)
		BEGIN
			-- create SQL Server job schedulder using the sp sp_add_schedule; and reset @interval_unit = NULL, and set freq_type is manual
			EXEC sp_I_ofi_EI_add_schedule @frequency_part2
				,@frequency_part3;

			SELECT @interval = NULL
				,@interval_unit = NULL
				,@freq_type = 19;
		END;
	END;
	ELSE BEGIN
		SET @frequency_format_is_valid = 0 ;
	END ;

	IF (@frequency_format_is_valid = 0) BEGIN
		-- string_id 500003 = 'The given frequency is not valid.  Frequency id: '
		SELECT  @msg = CONCAT (dbo.fn_s_ofi_getLangString(500003, NULL, NULL), @SourceLabel) ;
		SET @msg_output = '{"code": 500,"status": "Error","error": "Error","message": "' + @msg + '"}';

		RAISERROR (
				@msg
				,16
				,1
				);

		Return -1 ;
	END ;

	SET @new_freq_name = @SourceLabel ;
	IF (@samplePlanType = 1)
	BEGIN
		SET @new_freq_name = 'L_' + @SourceLabel ;
	END;

	IF NOT EXISTS (
			SELECT 1
			FROM sample_freq WITH (NOLOCK)
			WHERE FREQ_NAME = @new_freq_name -- @SourceLabel
			)
	BEGIN
		EXEC sp_I_Sample_freq @freq_name = @new_freq_name -- @SourceLabel
			,@freq_desc = @new_freq_name --@SourceLabel
			,@freq_type = @freq_type
			,@interval = @interval
			,@interval_unit = @interval_unit
			,@prod_reset_option = @prod_reset_option
			--,@start_delay = NULL
			,@offset_start = NULL
			,@offset_start_unit = NULL
			,@offset_end = NULL
			,@offset_end_unit = NULL
			,@samples_per_shift = NULL
			,@multiplier = @multiplier
			,@enabled = @enabled
			,@expiry_time = NULL
			,@expiry_unit = NULL
			,@warning_time = @warning_time
			,@warning_unit = @warning_unit
			,@spare1 = @spare1
			,@spare2 = @spare2
			,@spare3 = @spare3
			,@spare4 = @spare4
			,@last_edit_comment = @last_edit_comment
			,@last_edit_at = @last_edit_at OUTPUT
			,@freq_id = @freq_id OUTPUT;
	END;
	ELSE
	BEGIN
		SELECT @last_edit_at = last_edit_at
			,@freq_id = freq_id
		FROM sample_freq WITH (NOLOCK)
		WHERE FREQ_NAME = @new_freq_name ; -- @SourceLabel ;
	END;
END

