	DECLARE @std_deviation TFLOAT_NULL;
	DECLARE @cl_xbar TFLOAT_NULL;
	DECLARE @lcl_xbar TFLOAT_NULL;
	DECLARE @ucl_xbar TFLOAT_NULL;
	DECLARE @cl_range TFLOAT_NULL;
	DECLARE @lcl_range TFLOAT_NULL;
	DECLARE @ucl_range TFLOAT_NULL;
	DECLARE @cl_sigma TFLOAT_NULL;
	DECLARE @lcl_sigma TFLOAT_NULL;
	DECLARE @ucl_sigma TFLOAT_NULL;
	DECLARE @cl_ix TFLOAT_NULL;
	DECLARE @lcl_ix TFLOAT_NULL;
	DECLARE @ucl_ix TFLOAT_NULL;
	DECLARE @cl_imr TFLOAT_NULL;
	DECLARE @lcl_imr TFLOAT_NULL;
	DECLARE @ucl_imr TFLOAT_NULL;
	DECLARE @cl_ma TFLOAT_NULL;
	DECLARE @lcl_ma TFLOAT_NULL;
	DECLARE @ucl_ma TFLOAT_NULL;
	DECLARE @cl_mr TFLOAT_NULL;
	DECLARE @lcl_mr TFLOAT_NULL;
	DECLARE @ucl_mr TFLOAT_NULL;
	DECLARE @cl_ms TFLOAT_NULL;
	DECLARE @lcl_ms TFLOAT_NULL;
	DECLARE @ucl_ms TFLOAT_NULL;
	DECLARE @cl_p TFLOAT_NULL;
	DECLARE @lcl_p TFLOAT_NULL;
	DECLARE @ucl_p TFLOAT_NULL;
	DECLARE @cl_np TFLOAT_NULL;
	DECLARE @lcl_np TFLOAT_NULL;
	DECLARE @ucl_np TFLOAT_NULL;
	DECLARE @cl_c TFLOAT_NULL;
	DECLARE @lcl_c TFLOAT_NULL;
	DECLARE @ucl_c TFLOAT_NULL;
	DECLARE @cl_u TFLOAT_NULL;
	DECLARE @lcl_u TFLOAT_NULL;
	DECLARE @ucl_u TFLOAT_NULL;
	DECLARE @fit_test INT32_NULL;
	DECLARE @hist_capability_sigma INT32_NULL;
	DECLARE @filter_by_ent_id LOGICAL = 1;
	DECLARE @filter_by_item_id LOGICAL = 1;
	DECLARE @filter_by_wo_id LOGICAL = 0;
	DECLARE @filter_by_oper_id LOGICAL = 0;
	DECLARE @filter_by_process_id LOGICAL = 0;
	DECLARE @filter_by_segment_req_id LOGICAL = 0;
	DECLARE @filter_by_segment_resp_id LOGICAL = 0;
	DECLARE @filter_by_spare1 LOGICAL = 0;
	DECLARE @filter_by_spare2 LOGICAL = 0;
	DECLARE @filter_by_spare3 LOGICAL = 0;
	DECLARE @filter_by_spare4 LOGICAL = 0;

	-- Since the same Parameter List / Variant can be used in different Test Methods. So to differentiate, concatenate each characteristic with test method and variant name.  Ex 'Red value(Color test/Lovibond)'.
	-- Because of size constraint, we will keep char_desc as concatenated value, and char_name is the passed parameter name. 
	-- char_name = @Parameter
	-- char_desc = @Parameter + '(' + @TestMethod + '/' + @Variant + ')'
	-- to be verified the concatenated text should not be more than 80 characters
	IF (LEN(@Parameter + @TestMethod + '|' + @Variant) > 80)
	BEGIN
		SET @concatenated_char_desc = @Parameter + '|' + LEFT(@TestMethod, 80 - (LEN(@Parameter) + 1));
		SET @concatenated_char_desc = @concatenated_char_desc + '|' + LEFT(@Variant, 80 - (LEN(@concatenated_char_desc) + 1));
		--SET @concatenated_char_desc = CASE 
		--		WHEN LEN(@concatenated_char_desc) < 80
		--			THEN @concatenated_char_desc + ')'
		--		ELSE @concatenated_char_desc
		--		END;
		SET @spare4 = 'characteristic name + test method + variant exceeds 80 chrs.';
	END;
	ELSE
	BEGIN
		SET @concatenated_char_desc = @Parameter + '|' + @TestMethod + '|' + @Variant;
			--SET @concatenated_char_desc = @Parameter + '(' + @TestMethod + '/' + @Variant + ')';
	END;

	IF (LTRIM(RTRIM(@Units)) = '')
	BEGIN
		SET @units = ' ';
	END;

	-- call sp to insert uom in case if not exist in uom table
	IF NOT EXISTS (
			SELECT 1
			FROM uom WITH (NOLOCK)
			WHERE abbreviation = @units
				OR description = @units
			)
	BEGIN
		EXEC sp_I_uom @description = @units
			,@abbreviation = @units
			,@last_edit_comment = 'inserted through script'
			,@last_edit_at = @last_edit_at OUTPUT
			,@uom_id = @uom_id OUTPUT;
	END;
	ELSE
	BEGIN
		SELECT @uom_id = uom_id
		FROM uom WITH (NOLOCK)
		WHERE abbreviation = @units
			OR description = @units;
	END;

	SELECT @char_name = @Parameter
		,@char_desc = @concatenated_char_desc
		,@normal_sample_size = 1;

	-- call standard SP to create characteristic
	IF EXISTS (
			SELECT 1
			FROM characteristic WITH (NOLOCK)
			WHERE spare1 = @char_name -- v00.04 changed to spare1 as that will have the clear parameter name from char_name
				AND char_desc = @char_desc
			)
	BEGIN
		-- update and return with char_id for the given char_name and char_desc
		SELECT @char_id = char_id
		FROM characteristic WITH (NOLOCK)
		WHERE spare1 = @char_name
			AND char_desc = @char_desc;

		-- v00.04 Update the @char_name now
		SELECT @char_name = c.char_name
		FROM characteristic c WITH (NOLOCK)
		WHERE c.char_id = @char_id


		-- v00.04 removed the update as it is not needed here.


		------ update the existing characteristic and return
		----EXEC sp_U_Characteristic 
		----	@char_id = @char_id
		----	,@char_name = @char_name
		----	,@char_desc = @char_desc
		----	,@default_chart = @default_chart
		----	,@uom_id = @uom_id
		----	,@time_interval = NULL
		----	,@time_int_unit = NULL
		----	,@normal_sample_size = 1
		----	,@num_defect_opp = NULL
		----	,@maximum_sample_size = NULL
		----	,@mov_avg_span = NULL
		----	,@sigma_est = NULL
		----	,@std_avg = NULL
		----	,@std_deviation = NULL
		----	,@cl_xbar = NULL
		----	,@lcl_xbar = NULL
		----	,@ucl_xbar = NULL
		----	,@cl_range = NULL
		----	,@lcl_range = NULL
		----	,@ucl_range = NULL
		----	,@cl_sigma = NULL
		----	,@lcl_sigma = NULL
		----	,@ucl_sigma = NULL
		----	,@cl_ix = NULL
		----	,@lcl_ix = NULL
		----	,@ucl_ix = NULL
		----	,@cl_imr = NULL
		----	,@lcl_imr = NULL
		----	,@ucl_imr = NULL
		----	,@cl_ma = NULL
		----	,@lcl_ma = NULL
		----	,@ucl_ma = NULL
		----	,@cl_mr = NULL
		----	,@lcl_mr = NULL
		----	,@ucl_mr = NULL
		----	,@cl_ms = NULL
		----	,@lcl_ms = NULL
		----	,@ucl_ms = NULL
		----	,@cl_p = NULL
		----	,@lcl_p = NULL
		----	,@ucl_p = NULL
		----	,@cl_np = NULL
		----	,@lcl_np = NULL
		----	,@ucl_np = NULL
		----	,@cl_c = NULL
		----	,@lcl_c = NULL
		----	,@ucl_c = NULL
		----	,@cl_u = NULL
		----	,@lcl_u = NULL
		----	,@ucl_u = NULL
		----	,@fit_test = NULL
		----	,@hist_capability_sigma = NULL
		----	,@num_decimals=@num_decimals
		----	,@spare1 = @spare1
		----	,@spare2 = @spare2
		----	,@spare3 = @spare3
		----	,@spare4 = @spare4
		----	,@last_edit_comment = 'updated through script'
		----	,@last_edit_at = NULL ;

		RETURN;
	END;

	-- check whether char name exist or not, if not exist, need to create with same name
	IF NOT EXISTS (
			SELECT 1
			FROM characteristic WITH (NOLOCK)
			WHERE char_name = @char_name
			)
	BEGIN
		SET @char_name = @char_name;
	END;
			-- check whether char name exist with other desc or not, if not exist, need to create with same name + numeric suffix 
	ELSE IF NOT EXISTS (
			SELECT 1
			FROM characteristic WITH (NOLOCK)
			WHERE char_name = @char_name
				AND char_desc != @char_desc
			)
	BEGIN
		SET @flag = 1;
	END;
			-- check whether char desc exist with different char name or not, if not need to create
	ELSE IF NOT EXISTS (
			SELECT 1
			FROM characteristic WITH (NOLOCK)
			WHERE char_name != @char_name
				AND char_desc = @char_desc
			)
	BEGIN
		SET @flag = 1;
	END;
			-- check whether char name exist but desc is diff. in this case need to create one
	ELSE IF EXISTS (
			SELECT 1
			FROM characteristic WITH (NOLOCK)
			WHERE char_name = @char_name
			)
	BEGIN
		SET @flag = 1;
	END;

	IF (@flag = 1)
	BEGIN
		SELECT TOP 1 @temp_char_name = char_name
		FROM characteristic WITH (NOLOCK)
		WHERE char_name LIKE @char_name + '\_%' ESCAPE '\'
			AND char_Desc = @char_desc
		ORDER BY char_name DESC;

		-- there is no such char name with given desc
		IF (@temp_char_name IS NULL)
		BEGIN
			-- select char name exist like the given one to create a unique char_name
			SELECT TOP 1 @temp_char_name = char_name
			FROM characteristic WITH (NOLOCK)
			WHERE char_name LIKE @char_name + '\_%' ESCAPE '\'
			ORDER BY char_name DESC;

			SELECT @val_part = [2]
			FROM ufn_ofi_SplitStringAsTableColumns(@temp_char_name, '_');

			IF (@val_part IS NULL)
				SET @val_part = '000';
			SET @val_part = CONVERT(INT, @val_part) + 1;

			SELECT @val_part = FORMAT(CONVERT(INT, @val_part), '000');

			SET @char_name = @char_name + '_' + @val_part;
		END;
		ELSE
		BEGIN
			SET @char_name = @temp_char_name;
		END;
	END;

	IF NOT EXISTS (
			SELECT 1
			FROM characteristic WITH (NOLOCK)
			WHERE char_name = @char_name
			)
	BEGIN
		EXEC sp_I_Characteristic @char_name = @char_name
			,@char_desc = @char_desc
			,@type = @type
			,@uom_id = @uom_id
			,@default_chart = @default_chart
			,@time_interval = NULL
			,@time_int_unit = NULL
			,@normal_sample_size = 1
			,@num_defect_opp = NULL
			,@maximum_sample_size = NULL
			,@mov_avg_span = NULL
			,@sigma_est = NULL
			,@std_avg = NULL
			,@std_deviation = NULL
			,@cl_xbar = NULL
			,@lcl_xbar = NULL
			,@ucl_xbar = NULL
			,@cl_range = NULL
			,@lcl_range = NULL
			,@ucl_range = NULL
			,@cl_sigma = NULL
			,@lcl_sigma = NULL
			,@ucl_sigma = NULL
			,@cl_ix = NULL
			,@lcl_ix = NULL
			,@ucl_ix = NULL
			,@cl_imr = NULL
			,@lcl_imr = NULL
			,@ucl_imr = NULL
			,@cl_ma = NULL
			,@lcl_ma = NULL
			,@ucl_ma = NULL
			,@cl_mr = NULL
			,@lcl_mr = NULL
			,@ucl_mr = NULL
			,@cl_ms = NULL
			,@lcl_ms = NULL
			,@ucl_ms = NULL
			,@cl_p = NULL
			,@lcl_p = NULL
			,@ucl_p = NULL
			,@cl_np = NULL
			,@lcl_np = NULL
			,@ucl_np = NULL
			,@cl_c = NULL
			,@lcl_c = NULL
			,@ucl_c = NULL
			,@cl_u = NULL
			,@lcl_u = NULL
			,@ucl_u = NULL
			,@fit_test = NULL
			,@hist_capability_sigma = NULL
			,@num_decimals=@num_decimals
			,@spare1 = @spare1
			,@spare2 = @spare2
			,@spare3 = @spare3
			,@spare4 = @spare4
			,@last_edit_comment = 'inserted through script'
			,@last_edit_at = @last_edit_at OUTPUT
			,@char_id = @char_id OUTPUT;
	END;

	-- return the char_id as output param
	SELECT @char_id = char_id
	FROM characteristic WITH (NOLOCK)
	WHERE char_name = @char_name
		AND char_desc = @char_desc;
END

-- *************************************************************************************************************************************************************************************
-- Name				: sp_I_ofi_EI_qmspec
-- Description		: To create sample plan, and link with sample frequency.
--
-- Author			: Unnikrishnan Nair P G (GDC)
-- Creation date	: 2024-02-12
--
-- Usage			: Using IN LIMS interface EI location MES_LIMS_SamplePlan_IN
--	EXEC sp_I_ofi_EI_qmspec 'GNLNL0043',  'item01', '1011325', 'Full', 'PhysChem', 'TIME_12_H', 'Color Test', 'Color', 'Lovibond', 'Blue Value', 'numeric', '', '10', '15', '12', '1', 6, 16 ; 
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Version			Authour				Date (yyyy-MM-dd)		Change Description
-- 00.01			PG					2024-02-12				Initial draft
-- 01.00			JSC					2025-09-30				CakeBlender Fix! Set Severity to 0 when MESWait is zero or null
-- 01.01			JSC					2026-03-31				Packing Fix! Ignore the limits when MESWait is zero or null.
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************************************************************************
CREATE   PROCEDURE [dbo].[sp_I_ofi_EI_qmspec] (
	@SamplePlanID NVARCHAR(40) -- LIMS plan id/name
	,@ProductID NVARCHAR(40)
	,@ent_id INT
	,@Customer NVARCHAR(40)
	,@Level NVARCHAR(20)
	,@Stage NVARCHAR(20)
	,@SourceLabel NVARCHAR(80)
	,@TestMethod NVARCHAR(40)
	,@ParameterListID NVARCHAR(40)
	,@Variant NVARCHAR(40)
	,@Parameter NVARCHAR(40)
	,@DataType NVARCHAR(20)
	,@Units NVARCHAR(40)
	,@LowerLimit NVARCHAR(80)
	,@UpperLimit NVARCHAR(80)
	,@TargetValue NVARCHAR(80)
	,@MESWait NVARCHAR(1)
	,@mes_plan_id INT32
	,@char_id INT32
	)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	SET NOCOUNT ON;

	-- 01. create qm spec using the std SP: sp_I_Qm_Spec
	-- 02. create qm spec and char link using the std SP: sp_I_Qm_Spec_Char_Link
	DECLARE @segment_ent_id int ;
	DECLARE @lower_val FLOAT;
	DECLARE @upper_val FLOAT;
	DECLARE @target_val FLOAT;	
	DECLARE @qm_spec_name STRING40;
	DECLARE @qm_spec_desc STRING80_NULL;
	DECLARE @edit_level INT32 = 1;
	DECLARE @ver_id STRING40 = '1.0';
	DECLARE @start_eff_local DATETIME;
	DECLARE @end_eff_local DATETIME;
	DECLARE @start_eff_utc DATETIME = NULL;
	DECLARE @end_eff_utc DATETIME = NULL;
	DECLARE @item_id STRING40_NULL = @ProductID;
	DECLARE @item_category_id INT32_NULL;
	DECLARE @process_id STRING40_NULL;
	DECLARE @oper_id STRING40_NULL;
	DECLARE @category_id INT32 = 0;
	DECLARE @plan_id INT32 = @mes_plan_id;
	DECLARE @num_pts_per_page INT32 = NULL;
	DECLARE @display_seq INT32 = 1;
	DECLARE @spare1 STRING80_NULL = @Customer;
	DECLARE @spare2 STRING80_NULL;
	DECLARE @spare3 STRING80_NULL;
	DECLARE @spare4 STRING80_NULL;
	DECLARE @last_edit_comment STRING254_NULL = 'inserted through script';
	DECLARE @last_edit_at TDATETIME;
	DECLARE @qm_spec_id INT32;
	DECLARE @target TFLOAT;--= @TargetValue;
	DECLARE @lsv TFLOAT_NULL;-- = @LowerLimit;
	DECLARE @usv TFLOAT_NULL;-- = @UpperLimit;
	DECLARE @lsv_is_offset LOGICAL = 0;
	DECLARE @usv_is_offset LOGICAL = 0;
	DECLARE @lsv_offset_is_pct LOGICAL = 0;
	DECLARE @usv_offset_is_pct LOGICAL = 0;
	DECLARE @lrv TFLOAT_NULL;-- = @LowerLimit;
	DECLARE @urv TFLOAT_NULL;-- = @UpperLimit;
	DECLARE @lrv_is_mult LOGICAL = 0;
	DECLARE @urv_is_mult LOGICAL = 0;
	DECLARE @severity_cd INT32_NULL = 2;-- severity code = non-key (set as default). MOD: v1.00
	DECLARE @sample_size_source INT32_NULL = NULL;
	DECLARE @normal_sample_size INT32_NULL = NULL;
	DECLARE @minimum_sample_size INT32_NULL = NULL;
	DECLARE @maximum_sample_size INT32_NULL = NULL;
	DECLARE @cl_source INT32_NULL = NULL;
	DECLARE @samples_for_cl INT32_NULL = NULL;
	DECLARE @samples_before_cl INT32_NULL = NULL;
	DECLARE @std_avg TFLOAT_NULL = NULL;
	DECLARE @std_avg_is_target INT32_NULL = NULL;
	DECLARE @std_deviation TFLOAT_NULL = NULL;
	DECLARE @cl_xbar TFLOAT_NULL = NULL;
	DECLARE @lcl_xbar TFLOAT_NULL = NULL;
	DECLARE @ucl_xbar TFLOAT_NULL = NULL;
	DECLARE @cl_range TFLOAT_NULL = NULL;
	DECLARE @lcl_range TFLOAT_NULL = NULL;
	DECLARE @ucl_range TFLOAT_NULL = NULL;
	DECLARE @cl_sigma TFLOAT_NULL = NULL;
	DECLARE @lcl_sigma TFLOAT_NULL = NULL;
	DECLARE @ucl_sigma TFLOAT_NULL = NULL;
	DECLARE @cl_ix TFLOAT_NULL = NULL;
	DECLARE @lcl_ix TFLOAT_NULL = NULL;
	DECLARE @ucl_ix TFLOAT_NULL = NULL;
	DECLARE @cl_imr TFLOAT_NULL = NULL;
	DECLARE @lcl_imr TFLOAT_NULL = NULL;
	DECLARE @ucl_imr TFLOAT_NULL = NULL;
	DECLARE @cl_ma TFLOAT_NULL = NULL;
	DECLARE @lcl_ma TFLOAT_NULL = NULL;
	DECLARE @ucl_ma TFLOAT_NULL = NULL;
	DECLARE @cl_mr TFLOAT_NULL = NULL;
	DECLARE @lcl_mr TFLOAT_NULL = NULL;
	DECLARE @ucl_mr TFLOAT_NULL = NULL;
	DECLARE @cl_ms TFLOAT_NULL = NULL;
	DECLARE @lcl_ms TFLOAT_NULL = NULL;
	DECLARE @ucl_ms TFLOAT_NULL = NULL;
	DECLARE @cl_p TFLOAT_NULL = NULL;
	DECLARE @lcl_p TFLOAT_NULL = NULL;
	DECLARE @ucl_p TFLOAT_NULL = NULL;
	DECLARE @cl_np TFLOAT_NULL = NULL;
	DECLARE @lcl_np TFLOAT_NULL = NULL;
	DECLARE @ucl_np TFLOAT_NULL = NULL;
	DECLARE @cl_c TFLOAT_NULL = NULL;
	DECLARE @lcl_c TFLOAT_NULL = NULL;
	DECLARE @ucl_c TFLOAT_NULL = NULL;
	DECLARE @cl_u TFLOAT_NULL = NULL;
	DECLARE @lcl_u TFLOAT_NULL = NULL;
	DECLARE @ucl_u TFLOAT_NULL = NULL;
	DECLARE @default_chart INT32_NULL = NULL;
	DECLARE @automated_coll INT32 = 2;
	DECLARE @time_interval INT32_NULL = NULL;
	DECLARE @time_int_unit INT32_NULL = NULL;
	DECLARE @mes_plan_name NVARCHAR(40);

	DECLARE @can_capture_qm_data LOGICAL;
	DECLARE @can_capture_util LOGICAL;

	SET @DataType = LTRIM(RTRIM(ISNULL(@DataType, '')));

	IF (UPPER(@DataType) != 'NUMERIC')
	BEGIN
		EXEC sp_I_ofi_EI_convertcharvalues @Parameter
			,@DataType
			,@LowerLimit
			,@UpperLimit
			,@TargetValue
			,@lower_val OUTPUT
			,@upper_val OUTPUT
			,@target_val OUTPUT;
	END;
	ELSE
	BEGIN
		SELECT @target_val = CONVERT(FLOAT, ISNULL(@TargetValue, 0))
			,@lower_val = CASE 
				WHEN @LowerLimit IS NULL
					THEN NULL
				ELSE CONVERT(FLOAT, ISNULL(@LowerLimit, 0))
				END
			,@upper_val = CASE 
				WHEN @UpperLimit IS NULL
					THEN NULL
				ELSE CONVERT(FLOAT, ISNULL(@UpperLimit, 0))
				END;
	END;

	-- 01. create qm spec using the std SP: sp_I_Qm_Spec
	SELECT @mes_plan_name = plan_name
	FROM sample_plan WITH (NOLOCK)
	WHERE plan_id = @mes_plan_id;

	SELECT @Parameter = char_name
	FROM characteristic WITH (NOLOCK)
	WHERE char_id = @char_id;

	IF (@ent_id IS NOT NULL) BEGIN
		SELECT @segment_ent_id = ent_id 
		FROM  ent WITH (NOLOCK)
		WHERE PARENT_ent_id = @ent_id;

		--Retrieve the can_capture_* properties for utilization and qm_data. It should configure against segment entity. 
		SELECT @can_capture_util = can_capture_util, @can_capture_qm_data = can_capture_qm_data
		FROM ent WITH (NOLOCK)
		WHERE ent_id = @segment_ent_id;

		--Verify whether the supplied entity can capture QM data, if not set it.
		IF (@can_capture_qm_data = 0) BEGIN
			UPDATE ent
			SET can_capture_qm_data = 1
			WHERE ent_id = @segment_ent_id;
		END;
	END ;

	-- check whether the same qm_spec exist or not; if not exist, create it
	IF NOT EXISTS (
			SELECT 1
			FROM qm_spec WITH (NOLOCK)
			WHERE qm_spec_name = @mes_plan_name
			)
	BEGIN
		EXEC sp_I_Qm_Spec @qm_spec_name = @mes_plan_name
			,@qm_spec_desc = @mes_plan_name
			,@edit_level = @edit_level
			,@ver_id = @ver_id
			,@start_eff_local = @start_eff_local
			,@end_eff_local = @end_eff_local
			,@start_eff_utc = @start_eff_utc
			,@end_eff_utc = @end_eff_utc
			,@ent_id = @segment_ent_id	-- @ent_id
			,@item_id = @item_id
			,@item_category_id = @item_category_id
			,@process_id = @process_id
			,@oper_id = @oper_id
			,@category_id = @category_id
			,@plan_id = @plan_id
			,@num_pts_per_page = @num_pts_per_page
			,@display_seq = @display_seq
			,@spare1 = @spare1
			,@spare2 = @spare2
			,@spare3 = @spare3
			,@spare4 = @spare4
			,@last_edit_comment = @last_edit_comment
			,@last_edit_at = @last_edit_at OUTPUT
			,@qm_spec_id = @qm_spec_id OUTPUT;
	END;

	SELECT @qm_spec_id = qm_spec_id
	FROM qm_spec WITH (NOLOCK)
	WHERE qm_spec_name = @mes_plan_name;


	-- v1.01 Moved here: 
	IF (@MESWait != '1')
	BEGIN
		SET @severity_cd = 1; --v1.01: set to 1 Not monitored as MES needs this-- v1.0 Set to zero =  Unused -- severity code = non-key
		-- v1.01; Added this so we don't create nor update limits if they are not needed in MES.
		SET @target_val = 0
		SET @lower_val = NULL
		SET @upper_val = NULL
	END

	-- 02. create qm spec and char link using the std SP: sp_I_Qm_Spec_Char_Link
	-- check whether the given qm_spec and char is already linked or not; if not yet linked, link it
	IF NOT EXISTS (
			SELECT 1
			FROM qm_spec_char_link WITH (NOLOCK)
			WHERE qm_spec_id = @qm_spec_id
				AND char_id = @char_id
			)
	BEGIN
		SELECT @display_seq = MAX(display_seq)
		FROM qm_spec_char_link WITH (NOLOCK)
		WHERE qm_spec_id = @qm_spec_id;

		SET @display_seq = (ISNULL(@display_seq, 0)) + 1;

		-- v1.01 removed from here
		--IF (@MESWait != '1')
		--	SET @severity_cd = 0; -- v1.0 Set to zero =  Unused -- severity code = non-key

		EXEC sp_I_Qm_Spec_Char_Link @qm_spec_id = @qm_spec_id
			,@char_id = @char_id
			,@target = @target_val --@TargetValue
			,@lsv = @lower_val --@LowerLimit
			,@usv = @upper_val --@UpperLimit
			,@lsv_is_offset = @lsv_is_offset
			,@usv_is_offset = @usv_is_offset
			,@lsv_offset_is_pct = @lsv_offset_is_pct
			,@usv_offset_is_pct = @usv_offset_is_pct
			,@lrv = @lower_val --@LowerLimit
			,@urv = @upper_val --@UpperLimit
