-- Procedure definition
CREATE PROCEDURE [dbo].[sp_I_Item_File]
(
	@item_id nvarchar(40) ,
	@file_path nvarchar(254) ,
	@file_desc nvarchar(40) ,
	@last_modified datetime ,
	@file_size int ,
	@author nvarchar(80) ,
	-- Added 07/31/2007 AML
	@spare1 nvarchar(80),
	@spare2 nvarchar(80),
	@spare3 nvarchar(80),
	@spare4 nvarchar(80),
	--
	@last_edit_comment nvarchar(254),
	@time_zone_bias_value INT32 = 0,
	@mod_id varchar(30) OUT
)

AS
-- ***********************************************************************************************************************
-- Module Name				-
-- Description				-
-- Author					-
-- Date Created				- 10/21/2002
-- Version					- 1.6.0.0
--
-- Copyright (c) 2018 AVEVA Group plc and its subsidiaries. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By     Ver		Changes
-- 12/04/2002		Raghu			1.5.0	Mod Id Changes (Datetime to Money type)
-- 06/06/2003		Sheetal Jain    1.6.0	Oracle migration changes - SET @<variable> = (SELECT ...)
-- 10/11/2005		Raghu			3.1.0	HD# 5678, Part of DB Changes
-- 01/18/2007		KRF				3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 07/31/2007		AML				3.3.0	DB Changes
-- 10/24/2007		AML				3.3.4	HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--											dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 10/01/2018	Raghu		6.1	UserStory:1084805 - As Terry, I want the upgrade to modify the document / file stored procedures so that my existing configuration is still valid (Part 1)
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @last_edit_by	NVARCHAR(40)
	,	@last_edit_at	DATETIME
	,@ftle		DATETIME
	,@file_type	NVARCHAR(254)

	SET @file_type = dbo.fn_GetFileExtn(@file_path)
	EXEC sp_I_File_Type @file_ext=@file_type, @file_desc=@file_desc, @edit_level=NULL, @view_level=NULL, @print_level=NULL
		, @edit_args=NULL, @view_args=NULL, @print_args=NULL, @ignore_if_exists=1
		, @last_edit_comment=NULL, @last_edit_at=@ftle OUTPUT

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)
IF @last_modified IS NOT NULL SET @last_modified = DATEADD(mi, -@time_zone_bias_value, @last_modified)

INSERT INTO item_file
(
	item_id,
	file_path,
	file_desc,
	file_type,
	last_modified,
	file_size,
	author,
	spare1,
	spare2,
	spare3,
	spare4,
	last_edit_comment,
	last_edit_by,
	last_edit_at
)
VALUES
(
	@item_id,
	@file_path,
	@file_desc,
	@file_type,
	@last_modified,
	@file_size,
	@author,
	@spare1,
	@spare2,
	@spare3,
	@spare4,
	@last_edit_comment,
	@last_edit_by,
	@last_edit_at
)

-- Return timestamp
--SET @mod_id = (select CONVERT(varchar(30), CONVERT(DATETIME, mod_id), 13)
select @mod_id = CONVERT(varchar(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id)))
from item_file WITH (NOLOCK)
WHERE (item_id = @item_id AND
file_path = @file_path)

--===========================================================================================
-- Name:    [sp_U_ofi_SULowSignal]
-- Description:Storage Unit Low Level Signal Update
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  AJEET       2022-09-14         Intial Version
-- 0.01.01  YG          2024-02-09         Update Script Body Comment and Missing No Lock
-- 0.02.00  YG          2024-03-12         Added Good Consumption (Item Reason), Validation for non running job, Ensure qty_left has value for empty inventory  
-- 0.03.00  YG          2024-03-21         Update logic how to get latest consumption and disable scrap logic
-- 0.04.00  YG          2024-05-10         Major Update
-- 0.05.00  MC          2025-07-25         Adding fg_lot/sublot to item consumted because of low level in silo
-- 0.06.00  MC          2025-10-20         Adding removing zero-invenotry as only after low level signal invenotry can by removed from the silo
-- 0.07.00  MH          2025-11-20         [CR 00223357] Implement force scrapping for butter silos if ForceScrapOnLowLevel is set
--
-- Exec sp_U_ofi_SULowSignal '500BN003'
-- =============================================
CREATE PROCEDURE [dbo].[sp_U_ofi_SULowSignal] @SU_Name NVARCHAR(40)
AS
BEGIN
    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET nocount ON;

    -- Declare variable
    DECLARE
        @storage_ent_id INT,
        @cons_lot_no NVARCHAR(40) = NULL,
        @cons_sublot_no NVARCHAR(40) = NULL,
        @cons_qty FLOAT = 0,
        @avl_qty FLOAT = 0,
        @consumed_qty FLOAT = 0,
        @job_pos INT = 0,
        @bom_pos INT = 0,
        @date_time_UTC DATETIME = GETUTCDATE(),
        @return_value INT,
        @row_id INT32,
        @minID INT,
        @typeOfCons NVARCHAR(20) = 'FIFO',
        @process_id NVARCHAR(30),
        @process_type NVARCHAR(30),
        @prod_info NVARCHAR(4000),
        @prod_item_id NVARCHAR(40),
        @prod_date_time_UTC DATETIME,
        @user_id NVARCHAR(40) = NULL,
        @wo_state INT,
        @ent_id INT,
        @qty_left FLOAT,
        @su_level_threshold INT,
        @plant_level_threshold INT,
        @final_threshold INT,
        @wo_id NVARCHAR(40),
        @Out INT,
        @inv_item_id NVARCHAR(40),
        @item_id NVARCHAR(40),
        @target_sched_ent_id INT,
        @cons_ent_id INT,
        @oper_id NVARCHAR(40),
        @seq_no INT,
        @Counter INT,
        @iterate INT = 1,
        @last_consumed_date DATETIME,
        @lot_no NVARCHAR(40) = NULL,
        @sublot_no NVARCHAR(40) = NULL,
        @job_state INT,
        @grade_cd INT,
        @status_cd INT,
        @uom_desc NVARCHAR(40),
        @isOrderClosed INT = 0

    -- Declare Audit Trail
    DECLARE
        @auditTrailParameters ofi_AUDITTRAILPARAMETERS,
        @iRowId int,
        @audit_trail INT = 1,
        @grade_desc NVARCHAR(100),
        @state_desc NVARCHAR(100),
        @user_name NVARCHAR(100),
        @strModuleName nvarchar(80) = 'INV_LowLevelAdjustment',
        @strFunctionName nvarchar(80) = 'UI',
        @strActivityMsg nvarchar(200) = 'ADD',
        @strCommentMsg nvarchar(200)

    DECLARE @TempInv TABLE (
        id         INT IDENTITY (1, 1) PRIMARY KEY,
        ent_id     INT,
        item_id    NVARCHAR(40),
        lot_no     NVARCHAR(40),
        sub_lot_no NVARCHAR(40),
        qty        FLOAT,
        row_id     INT
    )

    DECLARE
        @defaultUoMDesc NVARCHAR(20) = 'KG',
        @defaultUoMId   INT

    --00.05.00
    DECLARE @fg_sublot_no nvarchar(40)
    DECLARE @fg_lot_no nvarchar(40)

    -- Get User Id
    EXEC Sp_s_db_status_getaudtrailusr @user_id output, NULL
    SET @user_name = @user_id

    -- Get Ent Id from SP Parameter
    SELECT @ent_id = ent_id
    FROM ent (nolock)
    WHERE ent_name = @SU_Name

    -- Get Default UoM Desc
    SELECT @defaultUoMDesc = attr_value
    FROM ent_attr WITH (NOLOCK)
    WHERE ent_id = @ent_id
        AND attr_id = (SELECT attr_id FROM attr WITH (NOLOCK) WHERE attr_desc = 'DefaultStorageUoM' AND attr_grp = 2)

    SET @defaultUoMDesc = Isnull(@defaultUoMDesc, 'KG')

    -- v0.02.00 Get Good Consumption (Item Reason)
    DECLARE
        @strGoodConsReas NVARCHAR(40) = 'Good Consumption',
        @intGoodConsReas INT = NULL

    SELECT @intGoodConsReas = ISNULL(reas_cd, 1)
    FROM item_reas WITH (NOLOCK)
    WHERE reas_desc = @strGoodConsReas

    -- Get Default UoM Id
    SELECT @defaultUoMId = uom_id
    FROM uom WITH (NOLOCK)
    WHERE description = @defaultUoMDesc

    -- Get Current Qty on the Silo
    SELECT
        @qty_left = SUM(qty_left),
        @inv_item_id = MAX(item_id)
    FROM item_inv (NOLOCK)
    WHERE ent_id = @ent_id

    -- PRINT @qty_left

    -- Get Plant or Storage threshold
    SELECT @su_level_threshold = CONVERT(INT, REPLACE(ea.attr_value, ',', ''))
    FROM ent_attr (NOLOCK) ea
        -- v0.02.00 refine the logic when taking value from nvarchar attr value
        JOIN attr (NOLOCK) a
            ON ea.attr_id = a.attr_id
    WHERE ea.ent_id = @ent_id
        AND a.attr_desc = 'StorageUnitThreshold'

    -- PRINT @su_level_threshold

    SELECT @plant_level_threshold = CONVERT(INT, REPLACE(ea.attr_value, ',', ''))
    FROM ent_attr (NOLOCK) ea -- v0.02.00 refine the logic when taking value from nvarchar attr value
        JOIN attr (NOLOCK) a
            ON ea.attr_id = a.attr_id
    WHERE ea.ent_id = (SELECT TOP 1 ent_id FROM ent (NOLOCK) WHERE parent_ent_id IS NULL ORDER BY ent_id)
        AND a.attr_desc = 'StorageUnitThreshold'

    -- Convert Qty into Default UoM
    SELECT @qty_left = dbo.[Fn_ofi_convertqtybyitemidanduom](
        @inv_item_id, @qty_left, uom_id, @defaultUoMId, NULL, NULL, NULL, NULL)
    FROM item WITH (NOLOCK)
    WHERE item_id = @inv_item_id

    -- If the Silo level threshold is missing then take the plan level threshold
    IF ( @su_level_threshold = 0 )
    BEGIN
        SET @final_threshold = @plant_level_threshold
    END
    ELSE
    BEGIN
        SET @final_threshold = @su_level_threshold
    END

    -- v0.02.00 Ensure qty has value even no inventory
    SET @qty_left = Isnull(@qty_left, 0.00)

    -- if silo qty less than the thresshold
    IF (@qty_left < @final_threshold AND @qty_left > 0) -- v0.02.00 Add validation qty must more than 0
    BEGIN        
        -- Get last consumed order
        SELECT TOP 1
            @item_id = iv.item_id,
            @lot_no = iv.lot_no,
            @sublot_no = iv.sublot_no,
            @fg_lot_no = ic_max.fg_lot_no,       --00.05.00 select fg_lot/sublot_no from last consumed order
            @fg_sublot_no = ic_max.fg_sublot_no, --00.05.00
            @last_consumed_date = ic_max.max_id,
            @wo_id = ic_max.wo_id,
            @oper_id = ic_max.oper_id,
            @seq_no = ic_max.seq_no,
            @job_state = j.state_cd,
            @target_sched_ent_id = j.target_sched_ent_id,
            @job_pos = je.job_pos,
            @bom_pos = jb.bom_pos
        FROM item_inv iv WITH (NOLOCK)
            LEFT JOIN (
                SELECT
                    item_id,
                    lot_no,
                    sublot_no,
                    fg_lot_no,    --00.05.00
                    fg_sublot_no, --00.05.00
                    from_ent_id,
                    wo_id,
                    oper_id,
                    seq_no,
                    MAX(last_edit_at) AS max_id
                FROM item_cons WITH (NOLOCK)
                GROUP BY
                    item_id,
                    lot_no,
                    sublot_no,
                    fg_lot_no,    --00.05.00
                    fg_sublot_no, --00.05.00
                    from_ent_id,
                    wo_id,
                    oper_id,
                    seq_no
            ) AS ic_max
                ON iv.item_id = ic_max.item_id
                AND iv.lot_no = ic_max.lot_no
                AND iv.sublot_no = ic_max.sublot_no
                AND iv.ent_id= ic_max.from_ent_id
            LEFT JOIN job_exec je WITH (NOLOCK)
                ON ic_max.wo_id = je.cur_wo_id
                AND ic_max.oper_id = je.cur_oper_id
                AND ic_max.seq_no = je.cur_seq_no
            LEFT JOIN job j WITH (NOLOCK)
                ON ic_max.wo_id = j.wo_id
                AND ic_max.oper_id = j.oper_id
                AND ic_max.seq_no = j.seq_no
            LEFT JOIN job_bom jb WITH (NOLOCK)
                ON ic_max.wo_id = jb.wo_id
                AND ic_max.oper_id = jb.oper_id
                AND ic_max.seq_no = jb.seq_no
                AND iv.item_id = jb.item_id
                AND jb.bom_pos > 0
        WHERE iv.ent_id = @ent_id
        ORDER BY max_id DESC

        -- Ensure order selected is not closed
        SELECT @wo_state = state_cd
        FROM   wo WITH (nolock)
        WHERE  wo_id = @wo_id

        IF ( @wo_state = 3 ) -- 3 = Closed
        BEGIN
            SET @isOrderClosed = 1
        END
		
        -- [0.07.00]
        -- Force scrap if the silo has the ForceScrapOnLowLevel attribute set
        DECLARE @ForceScrapOnLowLevelId AS int;
        SELECT @ForceScrapOnLowLevelId = attr_id
        FROM attr
        WHERE attr_desc = 'ForceScrapOnLowLevel'
            AND attr_grp = 2 -- Entity
            
        DECLARE @ForceScrapOnLowLevel AS bit;
        SELECT @ForceScrapOnLowLevel = IIF(attr_value = '1', 1, 0)
        FROM ent_attr
        WHERE ent_id = @ent_id
            AND attr_id = @ForceScrapOnLowLevelId;
        
        IF (@ForceScrapOnLowLevel = 1)
        BEGIN
            PRINT 'Force scrap due to ForceScrapOnLowLevel attribute'

            INSERT INTO @TempInv (
                ent_id,
                item_id,
                lot_no,
                sub_lot_no,
                qty,
                row_id
            )
            SELECT
                iv.ent_id,
                iv.item_id,
                iv.lot_no,
                iv.sublot_no,
                qty_left,
                row_id
            FROM item_inv (NOLOCK) iv
            WHERE ent_id = @ent_id

            IF EXISTS (SELECT 1 FROM @TempInv)
            BEGIN
                SET @Counter = (SELECT Count(1) FROM @TempInv)

                WHILE (@iterate <= @Counter)
                BEGIN
                    SELECT
                        @cons_lot_no = at.lot_no,
                        @cons_sublot_no = at.sub_lot_no,
                        @qty_left = at.qty,
                        @item_id = at.item_id,
                        @grade_cd = iv.grade_cd,
                        @status_cd = iv.status_cd,
                        @uom_desc = u.abbreviation
                    FROM @TempInv at
                        LEFT JOIN item_inv iv WITH (NOLOCK)
                            ON at.row_id = iv.row_id
                        LEFT JOIN uom u WITH (NOLOCK)
                            ON iv.uom_id = u.uom_id
                    WHERE id = @iterate

                    EXEC @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
                        @from_ent_id = @ent_id,
                        @item_id = @item_id,
                        @lot_no = @cons_lot_no,
                        @sublot_no = @cons_sublot_no,
                        @qty_cons = @qty_left,
                        @reas_cd = @intGoodConsReas,
                        @grade_cd = @grade_cd,
                        @status_cd = @status_cd,
                        @user_id = @user_id,
                        @wo_id = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @oper_id = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @seq_no = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @shift_start_local = NULL,
                        @fg_lot_no = @fg_lot_no, --0.05.00
                        @fg_sublot_no = @fg_sublot_no, --0.05.00
                        @item_scrapped = 1,
                        @ent_id = @target_sched_ent_id, --0.05.00
                        @shift_id = NULL,
                        @qty_cons_erp = NULL,
                        @ext_ref = NULL,
                        @transaction_type = NULL,
                        @genealogy_id = NULL,
                        @upstream_event_id = NULL,
                        @segment_requirement_id = NULL,
                        @segment_response_id = NULL,
                        @comments = 'Trigger with Low Signal, Scrap due to ForceScrapOnLowLevel attribute',
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @shift_start_utc = NULL,
                        @time_zone_bias_value = NULL,
                        @row_id = @row_id OUTPUT

                    --00.06.00
                    DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                    IF (@audit_trail = 1)
                    BEGIN
                        DELETE @auditTrailParameters;
                        SET @strCommentMsg = 'Scrap due to ForceScrapOnLowLevel attribute - Silo Name :' + @SU_Name
                            + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                        INSERT INTO @auditTrailParameters
                            (row_id, field_name, field_value)
                        VALUES
                            (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                            (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                            (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                            (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                            (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                            (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                            (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                        EXEC sp_I_ofi_AuditTrail
                             @module_id = @strModuleName,
                             @function_id = @strFunctionName,
                             @auditTrailParameters = @auditTrailParameters,
                             @user_id = @user_name,
                             @activity = @strActivityMsg,
                             @audit_category = 'Info',
                             @comments = @strCommentMsg
                    END

                    SET @iterate = @iterate + 1
                END
            END

            SET @Out = 0

            SELECT
                @Out AS [Out],
                @ent_id AS EntId,
                @wo_id AS WoId
            RETURN
        END
        -- [/0.07.00]

        -- check the running job on silo and assign qty_left to it
        IF (@wo_id IS NOT NULL AND @job_state = 3 AND @isOrderClosed = 0)
            BEGIN
                PRINT 'WoId is running'
                -- Get bom pos from selected order
                SELECT TOP 1 @bom_pos = jb.bom_pos
                FROM job_bom (NOLOCK) jb
                WHERE jb.wo_id = @wo_id
                    AND jb.oper_id = @oper_id
                    AND jb.seq_no = @seq_no
                    AND jb.item_id = @item_id;

                INSERT INTO @TempInv (
                    ent_id,
                    item_id,
                    lot_no,
                    sub_lot_no,
                    qty,
                    row_id
                )
                SELECT
                    iv.ent_id,
                    iv.item_id,
                    iv.lot_no,
                    iv.sublot_no,
                    qty_left,
                    row_id
                FROM item_inv (NOLOCK) iv
                WHERE ent_id = @ent_id
                    AND iv.item_id IN (
                        SELECT item_id
                        FROM job_bom (NOLOCK) jb
                        WHERE jb.wo_id = @wo_id AND jb.oper_id = @oper_id AND jb.seq_no = @seq_no
                    )

                SET @Counter = (SELECT Count(1) FROM @TempInv)

                IF EXISTS (SELECT 1 FROM @TempInv)
                BEGIN
                    WHILE (@iterate <= @Counter)
                    BEGIN
                        SELECT 
                            @cons_lot_no = at.lot_no,
                            @cons_sublot_no = at.sub_lot_no,
                            @qty_left = at.qty,
                            @item_id = at.item_id,
                            @grade_cd = iv.grade_cd,
                            @status_cd = iv.status_cd,
                            @uom_desc = u.abbreviation
                        FROM @TempInv at
                            LEFT JOIN item_inv iv WITH (NOLOCK)
                                ON at.row_id = iv.row_id
                            LEFT JOIN uom u WITH (NOLOCK)
                                ON iv.uom_id = u.uom_id
                        WHERE id = @iterate

                        EXEC @return_value = [dbo].[Sp_i_item_cons_addcons]
                            @session_id = NULL,
                            @event_time_local = NULL,
                            @user_id = @user_id,
                            @ent_id = @target_sched_ent_id,
                            @job_pos = @job_pos,
                            @bom_pos = @bom_pos,
                            @qty_cons = @qty_left,
                            @reas_cd = @intGoodConsReas,
                            @lot_no = @cons_lot_no,
                            @fg_lot_no = @fg_lot_no, --00.05.00
                            @sublot_no = @cons_sublot_no,
                            @fg_sublot_no = @fg_sublot_no, --00.05.00
                            @from_ent_id = @ent_id,
                            @item_id = @item_id,
                            @ext_ref = NULL,
                            @apply_scaling_factor = NULL,
                            @genealogy_id = NULL,
                            @upstream_event_id = NULL,
                            @segment_requirement_id = NULL,
                            @segment_response_id = NULL,
                            @comments ='Trigger with Low Signal-Consumed on running Job',
                            @spare1 = NULL,
                            @spare2 = NULL,
                            @spare3 = NULL,
                            @spare4 = NULL,
                            @created_at_utc = @date_time_UTC,
                            @row_id = @row_id OUTPUT

                        --00.06.00
                        DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                        IF (@audit_trail = 1)
                        BEGIN
                            print 'Audit'
                            DELETE @auditTrailParameters;
                            SET @strCommentMsg = 'Consumed on running Job - Order No : ' + @wo_id
                                + ', Operation : ' + @oper_id
                                + ', Seq No : ' + CAST(@seq_no AS varchar)
                                + ', Silo Name :' + @SU_Name
                                + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                            INSERT INTO @auditTrailParameters
                                (row_id, field_name, field_value)
                            VALUES
                                (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                                (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                                (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                                (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                                (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                                (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                                (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                            EXEC sp_I_ofi_AuditTrail
                                 @module_id = @strModuleName,
                                 @function_id = @strFunctionName,
                                 @auditTrailParameters = @auditTrailParameters,
                                 @user_id = @user_name,
                                 @activity = @strActivityMsg,
                                 @audit_category = 'Info',
                                 @comments = @strCommentMsg
                        END

                        SET @iterate = @iterate + 1
                    END
                END

                DELETE FROM @TempInv

                SET @Out = 0

                SELECT
                    @Out AS [Out],
                    @ent_id AS EntId,
                    @wo_id  AS WoId
                RETURN
            END

        IF (@wo_id IS NOT NULL AND @job_state IN (4,5) AND @isOrderClosed = 0)
        BEGIN
            PRINT 'WoId is stopped/completed'

            INSERT INTO @TempInv (
                ent_id,
                item_id,
                lot_no,
                sub_lot_no,
                qty,
                row_id
            )
            SELECT
                iv.ent_id,
                iv.item_id,
                iv.lot_no,
                iv.sublot_no,
                qty_left,
                row_id
            FROM item_inv (NOLOCK) iv
            WHERE ent_id = @ent_id
                AND iv.item_id IN (
                    SELECT item_id
                    FROM job_bom (NOLOCK) jb
                    WHERE jb.wo_id = @wo_id AND jb.oper_id = @oper_id AND jb.seq_no = @seq_no
                )

            SET @Counter = (SELECT Count(1) FROM @TempInv)

            IF EXISTS (SELECT 1 FROM @TempInv)
            BEGIN
                WHILE (@iterate <= @Counter)
                BEGIN
                    SELECT
                        @cons_lot_no = at.lot_no,
                        @cons_sublot_no = at.sub_lot_no,
                        @qty_left = at.qty,
                        @item_id = at.item_id,
                        @grade_cd = iv.grade_cd,
                        @status_cd = iv.status_cd,
                        @uom_desc = u.abbreviation
                    FROM @TempInv at
                        LEFT JOIN item_inv iv WITH (NOLOCK)
                            ON at.row_id = iv.row_id
                        LEFT JOIN uom u WITH (NOLOCK)
                            ON iv.uom_id = u.uom_id
                    WHERE id = @iterate

                    EXEC @return_value = [dbo].[Sp_i_item_cons_addconspostexec]
                        @session_id = NULL,
                        @user_id = @user_id,
                        @ent_id = @target_sched_ent_id,
                        @bom_pos = @bom_pos,
                        @qty_cons = @qty_left,
                        @wo_id = @wo_id,
                        @oper_id = @oper_id,
                        @seq_no = @seq_no,
                        @shift_start_local = NULL,
                        @shift_id = NULL,
                        @item_id = @item_id,
                        @reas_cd = @intGoodConsReas,
                        @lot_no = @cons_lot_no,
                        @fg_lot_no = @fg_lot_no,    --00.05.00
                        @sublot_no = @cons_sublot_no,
                        @fg_sublot_no = @fg_sublot_no,    --00.05.00
                        @from_ent_id = @ent_id,
                        @ext_ref = NULL,
                        @genealogy_id = NULL,
                        @upstream_event_id = NULL,
                        @segment_requirement_id = NULL,
                        @segment_response_id = NULL,
                        @comments = 'Trigger with Low Signal-Consumed with last consumed job ',
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @created_at_utc = @date_time_UTC,
                        @row_id = @row_id output,
                        @time_zone_bias_value = NULL

                    --00.06.00
                    DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                    IF (@audit_trail = 1)
                    BEGIN
                        DELETE @auditTrailParameters;
                        SET @strCommentMsg = 'Consumed with last consumed job - Order No : ' + @wo_id
                            + ', Operation : ' + @oper_id
                            + ', Seq No : ' + CAST(@seq_no AS varchar)
                            + ', Silo Name :' + @SU_Name
                            + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                        INSERT INTO @auditTrailParameters
                            (row_id, field_name, field_value)
                        VALUES
                            (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                            (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                            (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                            (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                            (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                            (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                            (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                        EXEC sp_I_ofi_AuditTrail
                             @module_id = @strModuleName,
                             @function_id = @strFunctionName,
                             @auditTrailParameters = @auditTrailParameters,
                             @user_id = @user_name,
                             @activity = @strActivityMsg,
                             @audit_category = 'Info',
                             @comments = @strCommentMsg
                    END

                    SET @iterate = @iterate + 1
                END
            END

            DELETE FROM @TempInv

            SET @Out = 0

            SELECT
                @Out AS [Out],
                @ent_id AS EntId,
                @wo_id  AS WoId
            RETURN
        END

        IF (@wo_id IS NULL OR @isOrderClosed = 1)
        BEGIN
            PRINT 'No order is founded / order closed'

            INSERT INTO @TempInv (
                ent_id,
                item_id,
                lot_no,
                sub_lot_no,
                qty,
                row_id
            )
            SELECT
                iv.ent_id,
                iv.item_id,
                iv.lot_no,
                iv.sublot_no,
                qty_left,
                row_id
            FROM item_inv (NOLOCK) iv
            WHERE ent_id = @ent_id

            IF EXISTS (SELECT 1 FROM @TempInv)
            BEGIN
                SET @Counter = (SELECT Count(1) FROM @TempInv)

                WHILE (@iterate <= @Counter)
                BEGIN
                    SELECT
                        @cons_lot_no = at.lot_no,
                        @cons_sublot_no = at.sub_lot_no,
                        @qty_left = at.qty,
                        @item_id = at.item_id,
                        @grade_cd = iv.grade_cd,
                        @status_cd = iv.status_cd,
                        @uom_desc = u.abbreviation
                    FROM @TempInv at
                        LEFT JOIN item_inv iv WITH (NOLOCK)
                            ON at.row_id = iv.row_id
                        LEFT JOIN uom u WITH (NOLOCK)
                            ON iv.uom_id = u.uom_id
                    WHERE id = @iterate

                    EXEC @return_value = [dbo].[sp_I_Item_Cons_AddConsDirect]
                        @from_ent_id = @ent_id,
                        @item_id = @item_id,
                        @lot_no = @cons_lot_no,
                        @sublot_no = @cons_sublot_no,
                        @qty_cons = @qty_left,
                        @reas_cd = @intGoodConsReas,
                        @grade_cd = @grade_cd,
                        @status_cd = @status_cd,
                        @user_id = @user_id,
                        @wo_id = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @oper_id = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @seq_no = NULL, --0.05.00 - to be implemented after CR00186839 implementing
                        @shift_start_local = NULL,
                        @fg_lot_no = @fg_lot_no, --0.05.00
                        @fg_sublot_no = @fg_sublot_no, --0.05.00
                        @item_scrapped = 1,
                        @ent_id = @target_sched_ent_id, --0.05.00
                        @shift_id = NULL,
                        @qty_cons_erp = NULL,
                        @ext_ref = NULL,
                        @transaction_type = NULL,
                        @genealogy_id = NULL,
                        @upstream_event_id = NULL,
                        @segment_requirement_id = NULL,
                        @segment_response_id = NULL,
                        @comments = 'Trigger with Low Signal, Scrap because of no order is founded Or order closed',
                        @spare1 = NULL,
                        @spare2 = NULL,
                        @spare3 = NULL,
                        @spare4 = NULL,
                        @shift_start_utc = NULL,
                        @time_zone_bias_value = NULL,
                        @row_id = @row_id OUTPUT

                    --00.06.00
                    DELETE FROM item_inv where ent_id = @ent_id AND qty_left <= 0

                    IF (@audit_trail = 1)
                    BEGIN
                        DELETE @auditTrailParameters;
                        SET @strCommentMsg = 'Scrap because of no order is founded Or order closed - Silo Name :' + @SU_Name
                            + ', Reduced Qty :' + CAST(@qty_left AS varchar) + ' ' + @uom_desc

                        INSERT INTO @auditTrailParameters
                            (row_id, field_name, field_value)
                        VALUES
                            (@row_id, '@EntId', CONVERT(NVARCHAR(80), @ent_id)),
                            (@row_id, '@ItemId', CONVERT(NVARCHAR(80), @item_id)),
                            (@row_id, '@LotNo', CONVERT(NVARCHAR(80), @cons_lot_no)),
                            (@row_id, '@SublotNo', CONVERT(NVARCHAR(80), @cons_sublot_no)),
                            (@row_id, '@ReducedQty', CONVERT(NVARCHAR(80), @qty_left)),
                            (@row_id, '@GradeCd', CONVERT(NVARCHAR(80), @grade_cd)),
                            (@row_id, '@StateCd', CONVERT(NVARCHAR(80), @status_cd))

                        EXEC sp_I_ofi_AuditTrail
                             @module_id = @strModuleName,
                             @function_id = @strFunctionName,
                             @auditTrailParameters = @auditTrailParameters,
                             @user_id = @user_name,
                             @activity = @strActivityMsg,
                             @audit_category = 'Info',
                             @comments = @strCommentMsg
                    END

                    SET @iterate = @iterate + 1
                END
            END

            SET @Out = 0

            SELECT
                @Out AS [Out],
                @ent_id AS EntId,
                @wo_id  AS WoId
            RETURN
        END

        SET @Out = 0
    END
    ELSE IF (@qty_left = 0.00) --v0.02.00 Add checking if qty is 0
    BEGIN
        --00.06.00
        DELETE FROM item_inv WHERE ent_id = @ent_id AND qty_left <= 0
        PRINT 'Qty is Zero'
        SET @Out = 3
        PRINT @Out
    END
    ELSE
    BEGIN
        PRINT 'Qty More Than Threshold'
        SET @Out = 1
        PRINT @Out
    END

    SELECT @Out    AS [Out],
           @ent_id AS EntId,
           @wo_id  AS WoId
END

CREATE   PROCEDURE [dbo].[sp_I_Item_Inv]
(
	@ent_id int ,
	@item_id nvarchar(40) ,
	@lot_no nvarchar(40) ,
	@sublot_no nvarchar(40) ,
	@grade_cd int ,
	@status_cd int ,
	@qty_left float ,
	@qty_left_erp float ,
	@uom_id int,
	--@date_in datetime ,
	@date_in_local datetime ,	-- Added 07/20/2007 AML
	@date_in_tz INT32 = NULL ,
	--@date_out datetime ,
	@date_out_local datetime ,	-- Added 07/20/2007 AML
	@date_out_tz INT32 = NULL ,
	@expiry_date datetime ,
	@wo_id nvarchar(40) ,
	@oper_id nvarchar(40) ,
	@seq_no int ,
	@spare1 nvarchar(80) ,
	@spare2 nvarchar(80) ,
	@spare3 nvarchar(80) ,
	@spare4 nvarchar(80) ,
	@spare5 nvarchar(80) ,
	@spare6 nvarchar(80) ,
	@last_edit_comment nvarchar(254) ,
	@time_zone_bias_value INT32 = NULL ,
	@last_edit_at datetime OUTPUT ,
	@row_id int OUTPUT
)

AS
-- ***********************************************************************************************************************
-- Module Name			-
-- Description			-
-- Author				-
-- Date Created			- 10/21/2002
-- Version				- 1.5.0.0
--
-- Copyright (c) 2018 AVEVA Group Plc. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Version		Changes
-- 02/09/2005		Raghu			2.1.13		HD# 5258, Added new parameter for the time_zone bias value. Defaults to local time zone
-- 09/09/2005		Raghu			2.1.28		HD# 6370, Row id column should not be included in the insert statement.
-- 09/21/2005		Raghu			3.1.0		Part of DB Changes
-- 01/09/2007		KRF			3.2.1		HD# 8314, part of DB changes - added @sublot_no argument
-- 01/18/2007		KRF			3.2.1		HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 07/30/2007		AML			3.3.0		DB Changes
-- 10/24/2007		AML			3.3.4		HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--												dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
--01/17/2008		Raghu			3.4	L00073985; Inventory Window-Error receiving Items with lots.
-- 11/11/2009		Eswar			4.0	HF 1432 - datetime changes.
-- 02/22/2012		Ashish			4.0 SP1		Modified for Backlog CRL00106055
--10/03/2012		Saiteja		4.6		Added changes for CR L00122604
--05/12/2016		Mallesh		5.03    US#634680 : MOL: As Schneider Electric, I want to fix CR L00140287
--                                      (incorrect update of lot record when adding multiple different sublot records in the item_inv table)
-- 06/27/2018		Varun		6.0		US#1047933: Merge CR L00149493(HF CR L00148823) Modified sp_I_Item_Inv to call sp_I_Item_Inv_Add
-- 02/17/2020	Raghu		6.2	UserStory:1187825-As Bruce, I want a Web API to process ItemInv records so I can interact with inventory
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @last_edit_by	NVARCHAR(40)
	,	@date_in_utc	TDATETIME_NULL
	,	@date_out_utc	TDATETIME_NULL
	,	@tz_temp		INT
	,	@dbg_resp		INT32
BEGIN

    SET @date_in_tz = dbo.fn_TZ_ValidateOffset(@date_in_tz)
	SET @date_in_local = dbo.fn_TZ_ValidateLocalDate(@date_in_local, @date_in_tz)

    SET @date_out_tz = dbo.fn_TZ_ValidateOffset(@date_out_tz)
	SET @date_out_local = dbo.fn_TZ_ValidateLocalDate(@date_out_local, @date_out_tz)

    SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

	-- TRACE
	EXEC @dbg_resp = sp_DBG_LogTrace @src_sp='SP_I_ITEM_INV', @src_key='post_validate', @date_val1 = @date_in_local, @numeric_val1 = @date_in_tz,
					@date_val2 = @date_out_local, @numeric_val2 = @date_out_tz

	EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
	SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

	IF @qty_left_erp IS null SET  @qty_left_erp = 0

	IF ( @date_in_local IS NULL ) SET @date_in_local = dbo.fn_TZ_GetLocalDate(NULL) -- Modified for Backlog CRL00106055

	SET @tz_temp = -@date_in_tz
	EXEC sp_S_GetUtcDate @date_in_local, @tz_temp, @date_in_utc OUTPUT
	SET @tz_temp = -@date_out_tz
	EXEC sp_S_GetUtcDate @date_out_local, @tz_temp, @date_out_utc OUTPUT

	EXEC SP_I_ITEM_INV_ADDLOTSUBLOT @item_id, @lot_no, @sublot_no, @grade_cd, @status_cd

	-- Merge L00149493(HF L00148823): Call sp_I_Item_Inv_Add as this will validate business rules
	EXEC sp_I_Item_Inv_Add
		@ent_id = @ent_id,
		@item_id = @item_id,
		@lot_no = @lot_no,
		@sublot_no = @sublot_no,
		@grade_cd = @grade_cd,
		@status_cd = @status_cd,
		@add_qty = @qty_left,
		@add_qty_erp = @qty_left_erp,
		@date_in_local = @date_in_local,
		@date_in_tz = @date_in_tz,
		@expiry_date = @expiry_date,
		@wo_id = @wo_id,
		@oper_id = @oper_id,
		@seq_no = @seq_no,
		@from_ent_id = NULL,
		@uom_id = @uom_id,
		@spare1 = @spare1,
		@spare2 = @spare2,
		@spare3 = @spare3,
		@spare4 = @spare4,
		@spare5 = @spare5,
		@spare6 = @spare6,
		@goods_received = NULL,
		@checkGradeStatus = NULL,
		@transfer_comments = @last_edit_comment,
		@log_transfer = NULL,
		@time_zone_bias_value = @time_zone_bias_value,
		@date_in_utc = NULL,
		@expiry_date_utc = NULL,
		@row_id = @row_id OUTPUT
END

