	DECLARE @ent_id INT = -1,
            @storage_loc VARCHAR(100) = NULL,
            @item_id NVARCHAR(40),
            @item_group NVARCHAR(40),
            @lot_no NVARCHAR(40),
            @wo_id NVARCHAR(40),
            @sendable_qty DECIMAL(18,3),
			@sent_qty_total DECIMAL(18,3) = 0,
            @created_at_local DATETIME,
            @item_id_sap NVARCHAR(40) = NULL,
            @uom_description NVARCHAR(40) = NULL,
            @row_id INT,
            @qty_cons DECIMAL(18,3),
            @qty_cons_erp DECIMAL(18,3),
            @to_consume DECIMAL(18,3),
            @cutoff_date DATETIME,
            @error_msg NVARCHAR(MAX),
            @error_severity INT,
            @error_state INT,
			@attr_item_group INT,
			@attr_skip_consumption INT,
			@attr_not_consume_to_sap INT,
			@attr_sap_location INT,
			@attr_sap_item_id INT,
			@attr_not_produce_to_sap INT

	DECLARE @delay_hours INT = 0,
			-- 0.02.10
			@frequency_hours INT = 6,	--  report data every X hours for each batch
			@interface NVARCHAR(40) = 'CONS_DETAILS', --ei interface name
			@interface_row_id INT --ofi_ei_interface_last_execution table row id

    -- === Error handling block ===
    BEGIN TRY
		
        -- Calculate cutoff date for eligible records
        SET @cutoff_date = DATEADD(HOUR, DATEDIFF(HOUR, 0, DATEADD(HOUR, -@delay_hours, GETUTCDATE())), 0);

        -- Temporary table for consumption records
        DECLARE @consumption TABLE (
            wo_id NVARCHAR(40),
            lot_no NVARCHAR(40),
            from_ent_id INT,
            item_id NVARCHAR(40),
			sap_item_id NVARCHAR(40),
            item_group NVARCHAR(40),
            total_cons_to_send DECIMAL(18,3),
			total_cons_sent DECIMAL(18,3),
			total_prod_sent DECIMAL(18,3),
            created_at_local DATETIME
        );

        -- Step 1: Load eligible consumption lots

		SELECT @attr_item_group = attr_id FROM attr WHERE attr_desc = 'ItemGroup';
		SELECT @attr_skip_consumption = attr_id FROM attr WHERE attr_desc = 'SkipConsumptionReporting';
		SELECT @attr_not_consume_to_sap = attr_id FROM attr WHERE attr_desc = 'NotConsumeToSAP';
		SELECT @attr_sap_location = attr_id FROM attr WHERE attr_desc = 'SAPLocation';
		SELECT @attr_sap_item_id = attr_id FROM attr WHERE attr_desc = 'sap_item_id';
		SELECT @attr_not_produce_to_sap = attr_id FROM attr WHERE attr_desc = 'NotProduceToSAP';

		-- Insert data to @consumption with aggregation
		INSERT INTO @consumption (
			wo_id, lot_no, from_ent_id, item_id, item_group,
			total_cons_to_send, total_cons_sent, total_prod_sent, created_at_local
		)
		SELECT
			c.wo_id,
			c.lot_no,
			c.from_ent_id,
			c.item_id,
			ia.attr_value AS item_group,
			SUM(c.qty_cons - c.qty_cons_erp) AS total_cons_to_send,
			ic.total_cons_sent AS total_cons_sent,
			ISNULL(p.total_prod_sent, 0) AS total_prod_sent,
			MIN(c.created_at_local) AS created_at_local
		FROM item_cons c WITH(NOLOCK)
		INNER JOIN item i WITH(NOLOCK)
			ON i.item_id = c.item_id
			AND i.item_class_id NOT IN (UPPER('PACK'), UPPER('WIP'), UPPER('INTERMEDIATE'))
		INNER JOIN item_attr ia WITH(NOLOCK)
			ON ia.item_id = i.item_id
			AND ia.attr_id = @attr_item_group
			AND ia.attr_value NOT LIKE '%BEANS'
			AND ia.attr_value <> 'NIBS'
			AND c.oper_id NOT LIKE '%blend'
		INNER JOIN (
			SELECT lot_no, item_id, SUM(qty_cons_erp) as total_cons_sent
			FROM item_cons WITH(NOLOCK)
			GROUP BY lot_no, item_id
		) ic ON ic.item_id=c.item_id and ic.lot_no=c.lot_no
		LEFT JOIN wo w -- 0.02.11
			ON c.wo_id=w.wo_id
		LEFT JOIN item_attr ia1 WITH(NOLOCK)
			ON ia1.item_id = i.item_id
			AND ia1.attr_id = @attr_skip_consumption
		LEFT JOIN ofi_wo_item_ext ie WITH(NOLOCK)
			ON ie.item_id = i.item_id AND ie.wo_id = c.wo_id
		LEFT JOIN oper_attr oa WITH(NOLOCK)
			ON oa.oper_id = c.oper_id
			AND oa.attr_id = @attr_not_consume_to_sap
		LEFT JOIN (
			SELECT lot_no, oper_id, ia2.attr_value  AS item_group, SUM(qty_prod_erp) AS total_prod_sent
			FROM item_prod ip WITH(NOLOCK)
			JOIN item i ON i.item_id = ip.item_id
			JOIN item_attr ia2 ON ia2.item_id=i.item_id AND ia2.attr_id=@attr_item_group
			WHERE i.item_class_id NOT IN (UPPER('WIP'), UPPER('INTERMEDIATE'))
			GROUP BY lot_no, oper_id, ia2.attr_value 
		) p ON p.lot_no = c.lot_no AND p.item_group = ia.attr_value
		LEFT JOIN oper_attr oa2 WITH(NOLOCK)
			ON oa2.oper_id = p.oper_id
			AND oa2.attr_id = @attr_not_produce_to_sap
		LEFT JOIN ofi_ei_interface_last_execution ile ON ile.wo_id=c.wo_id AND ile.lot_no=c.lot_no AND ile.item_id=c.item_id AND ile.interface=@interface -- -- 0.02.10 join with execution history table
		WHERE ISNULL(ie.backflush, 0) <> 1
			AND c.from_ent_id IS NOT NULL
			AND (ia1.attr_value IS NULL OR ia1.attr_value <> '1')
			AND (oa.attr_value IS NULL OR oa.attr_value <> '1')
			AND c.created_at_utc < @cutoff_date
			AND (ile.last_sent_at IS NULL OR ile.last_sent_at < DATEADD(hour,-@frequency_hours,GETDATE())) -- -- 0.02.10 exclude batches sent in the last time window
			AND ISNULL(w.spare1,'0') = '1' -- 0.02.11 take only SAP wo
		GROUP BY c.wo_id, c.lot_no, c.from_ent_id, c.item_id, ia.attr_value, ia1.attr_value, ic.total_cons_sent, p.total_prod_sent, oa2.attr_value
		HAVING
		CAST(SUM(c.qty_cons - c.qty_cons_erp) AS DECIMAL(18,3)) > 0 AND -- there is something to send
		(
		CAST(ISNULL(p.total_prod_sent, 0) AS DECIMAL(18,3)) > CAST(SUM(c.qty_cons_erp) AS DECIMAL(18,3)) -- only batches with production more than consumption sent to ERP	
		OR EXISTS ( -- or pallet (spare2 in intem_inv contains pallet_id) as pallets don't have appropriate production but should be reported
			SELECT 1
			FROM item_cons ii
			WHERE ii.lot_no = c.lot_no
			  AND ii.spare4 IS NOT NULL
		)
		OR ISNULL(oa2.attr_value,'0') = '1' -- or production report is not needed for this consumption
		)

		--select the oldest batch to be reported
        ;WITH cte AS (
		SELECT *,
				CASE WHEN total_prod_sent >= total_cons_to_send + total_cons_sent OR total_prod_sent = 0 THEN total_cons_to_send
				ELSE total_prod_sent - total_cons_sent
				END
				AS sendable_qty
		FROM @consumption
		)
		SELECT TOP 1
		@wo_id = wo_id,
		@lot_no = lot_no,
		@item_id = item_id,
		@sendable_qty = sendable_qty,
		@ent_id = from_ent_id,
		@created_at_local = created_at_local
		FROM cte
		WHERE sendable_qty > 0
		ORDER BY created_at_local;

        -- Step 3: If a valid batch is found, prepare output and update records
        IF @ent_id <> -1 AND @ent_id IS NOT NULL
        BEGIN
			SELECT @storage_loc = attr_value
            FROM ent_attr WITH(NOLOCK)
            WHERE ent_id = @ent_id AND attr_id = @attr_sap_location;

            IF @storage_loc IS NULL
                SELECT @storage_loc = ent_name FROM ent WITH(NOLOCK) WHERE ent_id = @ent_id;

            SELECT @item_id_sap = attr_value
            FROM item_attr WITH(NOLOCK)
            WHERE item_id = @item_id AND attr_id = @attr_sap_item_id;

            SELECT @uom_description = description
            FROM item i
            JOIN uom u ON u.uom_id = i.uom_id
            WHERE i.item_id = @item_id;
			
			-- Step 4: Update item_cons records sequentially
			BEGIN TRANSACTION

			DECLARE cur CURSOR FOR
            SELECT row_id, qty_cons, qty_cons_erp
            FROM item_cons
            WHERE wo_id = @wo_id
                AND lot_no = @lot_no
                AND item_id = @item_id
                AND from_ent_id = @ent_id
                AND qty_cons_erp < qty_cons
				AND created_at_utc < @cutoff_date
            ORDER BY row_id;

			OPEN cur;
            FETCH NEXT FROM cur INTO @row_id, @qty_cons, @qty_cons_erp;

			WHILE @@FETCH_STATUS = 0 AND @sendable_qty > 0
            BEGIN
				SET @to_consume = @qty_cons - @qty_cons_erp;

                IF @sendable_qty >= @to_consume
                BEGIN
                    UPDATE item_cons
                    SET qty_cons_erp = @qty_cons
                    WHERE row_id = @row_id;

                    SET @sendable_qty   = @sendable_qty - @to_consume;
                    SET @sent_qty_total = @sent_qty_total + @to_consume;
                END
                ELSE
                BEGIN
                    UPDATE item_cons
                    SET qty_cons_erp = @qty_cons_erp + @sendable_qty
                    WHERE row_id = @row_id;

                    SET @sent_qty_total = @sent_qty_total + @sendable_qty;
                    SET @sendable_qty   = 0;
                END

                FETCH NEXT FROM cur INTO @row_id, @qty_cons, @qty_cons_erp;
            END

			-- 0.02.10 update history execution table
			SELECT @interface_row_id=id from ofi_ei_interface_last_execution WHERE interface = @interface AND wo_id=@wo_id AND lot_no=@lot_no AND item_id=@item_id

			IF @interface_row_id IS NOT NULL --if already exist update timestamp
				UPDATE dbo.ofi_ei_interface_last_execution
				SET last_sent_at = GETDATE()
				WHERE id = @interface_row_id;
			ELSE -- else create new record
				INSERT INTO ofi_ei_interface_last_execution (wo_id, lot_no, item_id, interface, last_sent_at)
				VALUES (@wo_id, @lot_no, @item_id, @interface, GETDATE())

            CLOSE cur;
            DEALLOCATE cur;
			COMMIT TRANSACTION;

			-- Step 5: Output data to be sent to ERP
            SELECT
            @wo_id AS Order_Number,
            [dbo].[fn_S_ofi_PlantCode]() AS Plant,
            @lot_no AS Batch_Number,
            COALESCE(@item_id_sap, @item_id) AS Material,
            @sent_qty_total AS Quantity,
            @uom_description AS UOM,
            '261' AS Movement_Type,
            FORMAT(@created_at_local, 'yyyyMMdd') AS Posting_Date,
            FORMAT(GETDATE(), 'yyyyMMdd') AS File_GenerationDate,
            FORMAT(GETDATE(), 'HHmmss') AS File_GenerationTime,
            @storage_loc AS Storage_Location,
            '' AS Document_Number,
            '' AS Message,
            '' AS Message;
        END
    END TRY

    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        SELECT @error_msg = ERROR_MESSAGE(),
               @error_severity = ERROR_SEVERITY(),
               @error_state = ERROR_STATE();

        RAISERROR(@error_msg, @error_severity, @error_state);
    END CATCH
END

-- *******************************************************************************************************************************************************************************************************************************
-- Name				: sp_I_ofi_EI_convertcharvalues
-- Description		: To create characteristc data in characteristic table if not exist.
--
-- Author			: Unnikrishnan Nair P G (GDC)
-- Creation date	: 2024-02-12
--
-- Usage			: Using IN LIMS interface EI location MES_LIMS_SamplePlan_IN
--	DECLARE @lower_val float, @upper_val float, @target_val float ; EXEC sp_I_ofi_EI_convertcharvalues 'Text', 'Negative', NULL, NULL, @lower_val OUTPUT, @upper_val OUTPUT, @target_val OUTPUT ; SELECT @lower_val, @upper_val, @target_val ;
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- Version			Authour				Date (yyyy-MM-dd)		Change Description
-- 00.01			PG					2024-02-12				Initial draft
----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
-- *******************************************************************************************************************************************************************************************************************************
CREATE PROCEDURE [dbo].[sp_I_ofi_EI_convertcharvalues] (
	@char_name nvarchar(40)
	,@DataType NVARCHAR(20)
	,@LowerLimit NVARCHAR(80)
	,@UpperLimit NVARCHAR(80)
	,@TargetValue NVARCHAR(80)
	,@lower_val float OUTPUT
	,@upper_val float OUTPUT
	,@target_val float OUTPUT
	)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	SET NOCOUNT ON;

	DECLARE @next_num_value int = 0 ;
	DECLARE @last_edit_comment nvarchar(254) = 'inserted through script.' ;

	/*
	--	LabVantage (LV) system has different data types and may not valid in AVEVA prpducts.  The LV datatypes will be converted into the below types from LV before sending to AVEVA system.
	--
	Text - when LV DataType is:-
		Text
		Text (Calc)
		SDC
		Reference
		Validated Reference
		Any

	Numeric: when LV DataType is
		Numeric
		Numeric (Calc)

	Date: when LV DataType is
		Date
		Date (Calc)
		Date Only
		Date Only (Calc)
	*/

	SELECT @TargetValue = ISNULL(@TargetValue, ''), @LowerLimit = ISNULL(@LowerLimit, ''), @UpperLimit = ISNULL(@UpperLimit, '') ;

	IF (UPPER(@DataType) = 'TEXT') BEGIN
		-- check whether the given text exist in the custom table or not.  if exist, get the corresponding numeric value.
		IF (@TargetValue != '') BEGIN
			IF EXISTS(SELECT 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @TargetValue AND data_type = @DataType AND char_name = @char_name) BEGIN
				SELECT @target_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @TargetValue  AND data_type = @DataType  AND char_name = @char_name;
			END ;
			ELSE BEGIN
				SELECT @next_num_value = ISNULL(MAX(val_numeric), 0) + 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) ;

				INSERT INTO ofi_numeric_converted_charvalues(val_desc, val_numeric, last_edit_comment, char_name) 
				VALUES(@TargetValue, @next_num_value, @last_edit_comment, @char_name);

				SELECT @target_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @TargetValue  AND data_type = @DataType  AND char_name = @char_name;
			END ;
		END ;

		IF (@LowerLimit != '') BEGIN
			IF EXISTS(SELECT 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @LowerLimit  AND data_type = @DataType AND char_name = @char_name) BEGIN
				SELECT @lower_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @LowerLimit  AND data_type = @DataType AND char_name = @char_name;
			END ;
			ELSE BEGIN
				SELECT @next_num_value = ISNULL(MAX(val_numeric), 0) + 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) ;

				INSERT INTO ofi_numeric_converted_charvalues(val_desc, val_numeric, last_edit_comment, char_name) 
				VALUES(@LowerLimit, @next_num_value, @last_edit_comment, @char_name);

				SELECT @lower_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @LowerLimit  AND data_type = @DataType AND char_name = @char_name;
			END ;
		END ;

		IF (@UpperLimit != '') BEGIN
			IF EXISTS(SELECT 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @UpperLimit  AND data_type = @DataType AND char_name = @char_name) BEGIN
				SELECT @upper_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @UpperLimit  AND data_type = @DataType AND char_name = @char_name;
			END ;
			ELSE BEGIN
				SELECT @next_num_value = ISNULL(MAX(val_numeric), 0) + 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) ;

				INSERT INTO ofi_numeric_converted_charvalues(val_desc, val_numeric, last_edit_comment, char_name) 
				VALUES(@UpperLimit, @next_num_value, @last_edit_comment, @char_name);

				SELECT @upper_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE val_desc = @UpperLimit  AND data_type = @DataType AND char_name = @char_name;
			END ;
		END ;
	END ;

	ELSE IF (UPPER(@DataType) = 'DATE') BEGIN
		-- date value will be always diff. so if any date type record exist, take its numeric value, no need to create separate records (anyway AVEVA system will not support types except float).
		IF EXISTS(SELECT 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE data_type = @DataType AND char_name = @char_name) BEGIN
			SELECT @target_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE data_type = @DataType  AND char_name = @char_name;
		END ;
		ELSE BEGIN
				SELECT @next_num_value = ISNULL(MAX(val_numeric), 0) + 1 FROM ofi_numeric_converted_charvalues WITH (NOLOCK) ;

				INSERT INTO ofi_numeric_converted_charvalues(val_desc, val_numeric, data_type, last_edit_comment, char_name) 
				VALUES(@TargetValue, @next_num_value, @DataType, @last_edit_comment, @char_name);

				SELECT @target_val = val_numeric FROM ofi_numeric_converted_charvalues WITH (NOLOCK) WHERE data_type = @DataType  AND char_name = @char_name;
			END ;

		-- for date type, set lowe and upper spec value as null
		SELECT @lower_val = NULL, @upper_val = NULL ;
	END ;
END

