--===========================================================================================
-- Name:		sp_U_ofi_UpdateRecipe
-- Description:	The stored procedure used to simplify other sp to update preferred and active recipe
--	
-- Usage:		sp_I_ofi_AddMasterRecipe, sp_U_ofi_EditMasterRecipe, sp_I_ofi_CloneMasterRecipe, sp_D_ofi_DeleteMasterRecipe
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	YG				2022-07-04			Initial version.
-- ===========================================================================================

CREATE Procedure [dbo].[sp_U_ofi_UpdateRecipe] 
		@item_id NVARCHAR(40),
		@ent_id INT,
		@recipe_name NVARCHAR(80),
		@recipe_preferred NVARCHAR(1),
		@recipe_active NVARCHAR(1),
		@audit_comments NVARCHAR(250),
		@user_name NVARCHAR(80)
AS
BEGIN
	DECLARE @strPreferred NVARCHAR(1),
			@strActive NVARCHAR(1),
			@iRowId INT,
			@auditTrailParameters ofi_AUDITTRAILPARAMETERS,
			@strModuleName NVARCHAR(80) = 'MRM_MasterRecipe',
			@strFunctionName NVARCHAR(80) = 'UI',
			@strActivityMsg NVARCHAR(200) = 'update'

	IF (@recipe_name IS NULL OR @item_id IS NULL OR @ent_id IS NULL)
	BEGIN
		-- Set Error Message 'Parameters is not completed'
		RAISERROR ('Parameters is not completed', -- Message text.  
               16, -- Severity.  
               1 -- State.  
               );
			   
		RETURN -1
	END

	-- Retrieve master recipe data from the current state
	SELECT @strPreferred = preferred,
		@strActive = is_active,
		@iRowId	= row_id
	FROM ofi_master_recipe WITH (NOLOCK)
	WHERE item_id = @item_id 
		AND recipe_name = @recipe_name
		AND ent_id = @ent_id

	-- Update the master recipe
	UPDATE ofi_master_recipe
	SET is_active = ISNULL(@recipe_active,@strActive),
		preferred = ISNULL(@recipe_preferred,@strPreferred),
		last_edit_at_local = GETDATE(),
		last_edit_at_utc = GETUTCDATE(),
		last_edit_by = @user_name
	WHERE row_id = @iRowId

	-- Insert entry in Audit Trial starts
	DELETE @auditTrailParameters;
	INSERT INTO @auditTrailParameters
	(
		row_id, 
		field_name, 
		field_value
	) 
	VALUES 
	(
		@iRowId,
		'@Preferred',
		ISNULL(@recipe_preferred,@strPreferred)
	),
	(
		@iRowId,
		'@Active',
		ISNULL(@recipe_active,@strActive)
	)

	-- Add audit trail
	EXEC sp_I_ofi_AuditTrail 
		@module_id = @strModuleName,
		@function_id = @strFunctionName,
		@auditTrailParameters = @auditTrailParameters,
		@user_id = @user_name,
		@activity = @strActivityMsg,
		@audit_category = 'Info',
		@comments = @audit_comments
END

