-- Change Date	Change By	Ver.	Changes
-- 05/05/2005	Raghu     	2.1.21	HD# 4385, Special handling of production quantities for piece parts.
-- 01/10/2007	KRF        	3.2.1	HD# 8314, 8876, et al. - part of DB changes - added sublot_no & last_edit_comment
--									arguments, removed @last_edit_at as an argument, initialized last_edit_by,
--									last_edit_at, & created_at, return last_edit_at & row_id (which is moved from first
--									to last in the argument list)
-- 05/17/2005   AML			3.2.10  Added parameters related to V3.2 DB.
-- 07/26/2007	AML			3.3.0	DB Changes; Removed @shift_start parameter, added @shift_start_local parameter.  Added
--									shift_start_local, shift_start_utc, created_at_local, and created_at_utc to insert.
--									Added @time_zone_bias_value parameter.
-- 08/22/2009	Raghu		4.0		DB Changes
-- 13/3/2012    siddu       4.0Sp2  OEE Changes are included from 3.5patch2
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE  @num_decimals		INT32

-- Following added 1/10/07 KRF
DECLARE @last_edit_by		NVARCHAR(40)
	-- Added 07/26/2007 AML
	,	@created_at_local	DATETIME
	,	@created_at_utc		DATETIME
	,	@shift_start_utc	DATETIME
    ,   @hour_start_utc     DATETIME---Added 13/3/2012 sid(OEE Changes from 3.5patch2 )
	--
	,	@use_gmt			INT32

SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)

EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

EXEC sp_SA_System_Attr_UseGMT @use_gmt OUTPUT
SET @use_gmt = ISNULL(@use_gmt, 0)
-- End 1/10/07 addition
---Added 13/3/2012 sid(OEE Changes from 3.5patch2 )
--If the input parameter is null, use the top of the hour of the created_at or shift_start times for hour_start as defaults.
IF @hour_start_local IS NULL
 BEGIN
   IF (@created_at_local >= @shift_start_local)
      BEGIN
        SET @hour_start_local = Convert( datetime,convert(varchar(13), @created_at_local, 120) + ':00:00.000', 120)
      END
   ELSE
      BEGIN
        SET @hour_start_local = Convert( datetime,convert(varchar(13), @shift_start_local, 120) + ':00:00.000', 120)
      END
 END
----end OEE Changes---


SELECT	@created_at_local = dbo.fn_StripMilliSecsFromDateTime( dbo.fn_TZ_GetLocalDate(NULL) )
	,	@created_at_utc = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )
	,	@good_prod = ISNULL(@good_prod, 1)
	,	@qty_prod_erp = ISNULL(@qty_prod_erp, 0)
	,	@processed_flag = ISNULL(@processed_flag, 0)
	,	@byproduct = ISNULL(@byproduct, 0)
	,	@shift_start_utc = DATEADD( mi, -@time_zone_bias_value, @shift_start_local )
     ,  @hour_start_utc=DATEADD( mi, -@time_zone_bias_value, @hour_start_local )---Added 13/3/2012 sid(OEE Changes from 3.5patch2 )
SELECT	@shift_start_local = dbo.fn_StripMilliSecsFromDateTime( @shift_start_local )
	,	@shift_start_utc = dbo.fn_StripMilliSecsFromDateTime( @shift_start_utc )



SELECT @num_decimals = num_decimals FROM item WHERE item_id = @item_id

IF ((ISNULL(@num_decimals, 0) = 0) AND (@good_prod = 1))
	SELECT @num_decimals = CASE WHEN ISNUMERIC(attr_value) = 1 THEN CONVERT(INT, attr_value) ELSE 0 END
	FROM system_attr WHERE attr_id = 326

SET @num_decimals = ISNULL(@num_decimals, 0)
SET @qty_prod = ROUND(@qty_prod, @num_decimals)

