CREATE PROCEDURE [dbo].[sp_I_Sample]
  (@sample_id int OUT ,
   @sample_name nvarchar(254) ,
   @ent_id int,
   @item_id nvarchar(80) ,
   @wo_id nvarchar(80) ,
   @oper_id nvarchar(80) ,
   @seq_no int,
   @context_ent_id int,
   @context_item_id nvarchar(80),
   @item_category_id int,
   @process_id nvarchar(80),
   @context_oper_id nvarchar(80),
   @freq_id int,
   @plan_id int = NULL,
   @segment_requirement_id nvarchar(254) ,
   @segment_response_id nvarchar(254) ,
   @lot_no nvarchar(80) ,
   @sublot_no nvarchar(80) ,
   @requested_time_local datetime,
   @requested_time_tz INT32 = NULL,
   @expiry_time_local datetime,
   @expiry_time_tz INT32 = NULL,
   @warning_time_local datetime,
   @warning_time_tz INT32 = NULL,
   @pulled_by nvarchar(80),
   @pulled_time_local datetime,
   @pulled_time_tz INT32 = NULL,
   @final bit,
   @finalized_by nvarchar(80),
   @finalized_at_local datetime,
   @finalized_at_tz INT32 = NULL,
   @verified_by nvarchar(80),
   @sample_status int,
   @sample_result int,
   @spare1 nvarchar(80) ,
   @spare2 nvarchar(80) ,
   @spare3 nvarchar(80) ,
   @spare4 nvarchar(80) ,
   @priority int=NULL,
   @last_edit_comment nvarchar(254) ,
   @time_zone_bias_value   INT32 = NULL,
   @last_edit_at datetime OUT)
AS
-- ***********************************************************************************************************************
-- Module Name       - SP_I_Sample
-- Description       - insert a sample record
-- Author         - Sara Reynolds
-- Date Created         -  02/01/2011
-- Version        -
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Change Date Change By   Ver.  Changes
----------------------------------------------------------------------------------------------------------------------------
-- 6/7/2011       Johnny Agsalog    Added priority column
-- 01/04/2012     Johnny Agsalog    Added plan_id, ability to generate sample name from a plan_id template
-- *************************************************************************************************************************
BEGIN

   SET NOCOUNT ON

   DECLARE  @last_edit_by  NVARCHAR(40),
          @requested_time_utc TDATETIME,
          @expiry_time_utc TDATETIME,
          @pulled_time_utc TDATETIME,
          @finalized_at_utc TDATETIME,
          @warning_time_utc TDATETIME,
          @tz_temp    INT32


   EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
   SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

   SET @requested_time_tz = dbo.fn_TZ_ValidateOffset(@requested_time_tz)
   SET @requested_time_local = dbo.fn_TZ_ValidateLocalDate(@requested_time_local, @requested_time_tz)

   SET @expiry_time_tz = dbo.fn_TZ_ValidateOffset(@expiry_time_tz)
   SET @expiry_time_local = dbo.fn_TZ_ValidateLocalDate(@expiry_time_local, @expiry_time_tz)

   SET @warning_time_tz = dbo.fn_TZ_ValidateOffset(@warning_time_tz)
   SET @warning_time_local = dbo.fn_TZ_ValidateLocalDate(@warning_time_local, @warning_time_tz)

   SET @pulled_time_tz = dbo.fn_TZ_ValidateOffset(@pulled_time_tz)
   SET @pulled_time_local = dbo.fn_TZ_ValidateLocalDate(@pulled_time_local, @pulled_time_tz)

   SET @finalized_at_tz = dbo.fn_TZ_ValidateOffset(@finalized_at_tz)
   SET @finalized_at_local = dbo.fn_TZ_ValidateLocalDate(@finalized_at_local, @finalized_at_tz)

   SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

   SET @tz_temp = -@requested_time_tz
   EXEC sp_S_GetUtcDate @requested_time_local, @tz_temp, @requested_time_utc OUTPUT

   SET @tz_temp = -@expiry_time_tz
   EXEC sp_S_GetUtcDate @expiry_time_local, @tz_temp, @expiry_time_utc OUTPUT

   SET @tz_temp = -@warning_time_tz
   EXEC sp_S_GetUtcDate @warning_time_local, @tz_temp, @warning_time_utc OUTPUT

   SET @tz_temp = -@pulled_time_tz
   EXEC sp_S_GetUtcDate @pulled_time_local, @tz_temp, @pulled_time_utc OUTPUT

   SET @tz_temp = -@finalized_at_tz
   EXEC sp_S_GetUtcDate @finalized_at_local, @tz_temp, @finalized_at_utc OUTPUT


   IF @final IS NULL SET @final = 0

   INSERT INTO sample
    (ent_id,
     sample_name,
     item_id,
     wo_id,
     oper_id,
     seq_no,
      context_ent_id,
      context_item_id,
      item_category_id,
      process_id,
      context_oper_id,
      freq_id,
      plan_id,
     segment_requirement_id,
     segment_response_id,
     lot_no,
     sublot_no,
     requested_time_utc,
     requested_time_local,
     expiry_time_utc,
     expiry_time_local,
      warning_time_utc,
      warning_time_local,
     pulled_by,
     pulled_time_utc,
     pulled_time_local,
     final,
     finalized_by,
     finalized_at_utc,
     finalized_at_local,
     verified_by,
     sample_status,
     sample_result,
     spare1,
     spare2,
     spare3,
     spare4,
     priority,
     last_edit_comment,
     last_edit_by,
     last_edit_at)
   VALUES
     (@ent_id,
      @sample_name,
      @item_id,
      @wo_id,
      @oper_id,
      @seq_no,
       @context_ent_id,
       @context_item_id,
       @item_category_id,
       @process_id,
       @context_oper_id,
       @freq_id,
       @plan_id,
      @segment_requirement_id,
      @segment_response_id,
      @lot_no,
      @sublot_no,
      @requested_time_utc,
      @requested_time_local,
      @expiry_time_utc,
      @expiry_time_local,
       @warning_time_utc,
       @warning_time_local,
      @pulled_by,
      @pulled_time_utc,
      @pulled_time_local,
      @final,
      @finalized_by,
      @finalized_at_utc,
      @finalized_at_local,
      @verified_by,
      @sample_status,
      @sample_result,
      @spare1,
      @spare2,
      @spare3,
      @spare4,
      @priority,
      @last_edit_comment,
      @last_edit_by,
      @last_edit_at)

   -- Auto Identifer table - return the id of the record created
   SELECT @sample_id = SCOPE_IDENTITY()
END

