CREATE PROCEDURE [dbo].[sp_U_Job]
(
	@wo_id nvarchar(40) ,
	@oper_id nvarchar(40) ,
	@seq_no int ,
	--@segment_requirement_id nvarchar(80) = null, -- Added 07/16/2009 RWB -- Removed 08/20/2009 SLR
	--@segment_response_id nvarchar(80) = null, -- Added 07/16/2009 RWB -- Removed 08/20/2009 SLR
	@job_desc nvarchar(80) ,
	@item_id nvarchar(40) ,
	@state_cd int ,
	@job_priority int ,
	--@req_finish_time datetime , -- 07/25/2007 AML
	@req_finish_time_local datetime , -- Added 07/25/2007 AML
	@req_finish_time_tz INT32 = NULL ,
	@init_sched_ent_id int ,
	@target_sched_ent_id int ,
	@run_ent_id int ,
	@qty_reqd float ,
	@qty_prod float ,
	@qty_prod_erp float ,
	@qty_rejected float ,
	@qty_rejected_erp float ,
	@qty_at_start float ,
	@deviation_above float ,
	@deviation_below float ,
	@batch_size float ,
	@sched_pinned bit ,
	@check_inv bit ,
	@est_fixed_lab float ,
	@est_lab_rate float ,
	@est_setup_time float ,
	@est_teardown_time float ,
	@est_prod_rate float ,
	@prod_uom	int,
	@est_transfer_time float ,
	--@sched_start_time datetime ,		-- 07/26/2007 AML
	@sched_start_time_local datetime,	-- Added 07/26/2007 AML
	@sched_start_time_tz INT32 = NULL,
	--@latest_start_time datetime ,		-- 07/26/2007 AML
	@latest_start_time_local datetime,	-- Added 07/26/2007 AML
	@latest_start_time_tz INT32 = NULL,
	--@sched_finish_time datetime ,		-- 07/26/2007 AML
	@sched_finish_time_local datetime,	-- Added 07/26/2007 AML
	@sched_finish_time_tz INT32 = NULL,
	--@act_start_time datetime ,		-- 07/26/2007 AML
	@act_start_time_local datetime,		-- Added 07/26/2007 AML
	@act_start_time_tz INT32 = NULL,
	--@act_finish_time datetime ,		-- 07/26/2007 AML
	@act_finish_time_local datetime,	-- Added 07/26/2007 AML
	@act_finish_time_tz INT32 = NULL,
	@concurrent_link int ,
	@job_cost float ,
	@parent_contingent_job bit ,
	@child_contingent_job bit ,
	@notes NOTES ,
	@assoc_file nvarchar(254) ,
	@assoc_file_type nvarchar(254) ,
	@status_notes nvarchar(2000) ,
	@display_seq int ,
	@folder_ver_id nvarchar(40) ,
	@rework bit,
	@rework_cd nvarchar(40),			-- Added 07/26/2007 AML
    @rework_process_id nvarchar(40),    -- Added 08/16/2009 SLR
	@spare1 nvarchar(80),
	@spare2 nvarchar(80),
	@spare3 nvarchar(80),
	@spare4 nvarchar(80),
	@last_edit_comment nvarchar(254),
	@edit_time datetime ,
	@edit_time_tz INT32 = NULL,
	@time_zone_bias_value INT32 =NULL ,
	@create_job_bom LOGICAL = 1
)

AS
-- ***********************************************************************************************************************
-- Module Name	  -
-- Description	  -
-- Author	      -
-- Date Created	  -	10/21/2002
-- Version	      - 6.2.0
--
-- Copyright (c) 2020 AVEVA Group plc - All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified	Modified_By		Version		Changes
-- 01/09/2003		Rohit			1.5.2		Added string Id reference to err messages.
-- 02/13/2003		VijayRaj		1.5.2		HD 2392: Enforces that all the jobs with same oper_id share same display_seq
-- 07/08/2003		KRF				1.6.13		HD 2913: If job is running, disallow changes to item_id, assoc_file, and
--           	     							folder_ver_id if not originally null
-- 07/16/2003		KRF             1.6.15		HD 2913: ERB decided a change to assoc_file is OK since can't be downloaded
-- 08/13/2003		Sheetal Jain 	1.6.19		(HD #3309) Create job bom 0 record based off the flag
-- 06/16/2004		Raghu			2.1.0		Adjust current_subst, est_time, last_edit_comment fields in the sp_U_Job_Bom call list
-- 09/15/2005		Raghu			3.1.0		Part of DB Changes
-- 02/13/2007		Raghu			3.2.0		Part of DB Changes
-- 01/21/2008		Raghu			3.4			L00073299; Entry of Production Rates is cumbersome,...
-- 11/12/2009		Ajay			4.0.0		HD#1432, Part of Date/TimeZone changes
-- 01/04/2019		Raghu		 	6.1		    UserStory: 1106881 - As AVEVA, I want to fix CR L00150344 so that a job cannot be updated to an entity not on a line when the WO is on a line.
-- 02/05/2020       Jim O'Hearn     6.2.0       Removed ntext type in favor of NOTES; see US 1232760
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
--VRB This is to validate for First Job and Final Job. If a given Work Order has only one Job
-- then it can be both the start job and final job. But if there are more than one job, it is not true
DECLARE
	@orig_item_id nvarchar(40),
	@orig_folder_ver_id nvarchar(40),
	@orig_state_cd int,
	@reqd_grade_cd INT32_NULL,
	@instruction STRING2000_NULL,
	@max_qty_per_parent_item TFLOAT_NULL,
	@min_qty_per_parent_item TFLOAT_NULL,
	@reqd_start_val TFLOAT_NULL,
	@update_inv LOGICAL,
	@backflush LOGICAL,
	@def_reas_cd INT32_NULL,
	@def_lot_no STRING40_NULL,
	@def_storage_ent_id INT32_NULL,
	@def_reject_ent_id INT32,
	@scaling_factor TFLOAT_NULL,
	@must_consume_from_inv LOGICAL,
	@may_choose_alt_inv_loc LOGICAL,
	@may_create_new_lots LOGICAL,
	@must_consume_before_prod LOGICAL,
	@mod_id VARCHAR(30),
	@dbg_resp INT,
	@num_decimals INT32, -- Added for CR L00108888 - RWN 11/19/2010
	@upstream_ent_name	NVARCHAR(80),
	@downstream_ent_name	NVARCHAR(80),
	@err_msg		NVARCHAR(MAX),
	@line_name		NVARCHAR(80)

BEGIN

	SET @req_finish_time_tz			= dbo.fn_TZ_ValidateOffset(@req_finish_time_tz)
	SET @req_finish_time_local		= dbo.fn_TZ_ValidateLocalDate(@req_finish_time_local, @req_finish_time_tz)
	SET @sched_start_time_tz		= dbo.fn_TZ_ValidateOffset(@sched_start_time_tz)
	SET @sched_start_time_local		= dbo.fn_TZ_ValidateLocalDate(@sched_start_time_local, @sched_start_time_tz)
	SET @latest_start_time_tz		= dbo.fn_TZ_ValidateOffset(@latest_start_time_tz)
	SET @latest_start_time_local	= dbo.fn_TZ_ValidateLocalDate(@latest_start_time_local, @latest_start_time_tz)
	SET @sched_finish_time_tz		= dbo.fn_TZ_ValidateOffset(@sched_finish_time_tz)
	SET @sched_finish_time_local	= dbo.fn_TZ_ValidateLocalDate(@sched_finish_time_local, @sched_finish_time_tz)
	SET @act_start_time_tz			= dbo.fn_TZ_ValidateOffset(@act_start_time_tz)
	SET @act_start_time_local		= dbo.fn_TZ_ValidateLocalDate(@act_start_time_local, @act_start_time_tz)
	SET @act_finish_time_tz			= dbo.fn_TZ_ValidateOffset(@act_finish_time_tz)
	SET @act_finish_time_local		= dbo.fn_TZ_ValidateLocalDate(@act_finish_time_local, @act_finish_time_tz)
	SET @time_zone_bias_value		= dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

   -- TRACE
   exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_U_Job', @src_key='sp_U_Job',
					@date_val1 = @req_finish_time_local, @numeric_val1 = @req_finish_time_tz,
					@date_val2 = @sched_start_time_local, @numeric_val2 = @sched_start_time_tz,
					@date_val3 = @latest_start_time_local, @numeric_val3 = @latest_start_time_tz,
					@date_val4 = @sched_finish_time_local, @numeric_val4 = @sched_finish_time_tz,
					@date_val5 = @act_start_time_local, @numeric_val5 = @act_start_time_tz,
					@date_val6 = @act_finish_time_local, @numeric_val6 = @act_finish_time_tz


 --VRB
  --KRF 7/8/03 as modified 7/16/03 by removal of assoc_file references
  SELECT @orig_item_id = item_id, @orig_folder_ver_id = folder_ver_id,
	 @orig_state_cd = state_cd FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no
  IF @orig_state_cd = 3 AND (@orig_item_id <> @item_id OR
	(@orig_folder_ver_id IS NOT NULL AND @orig_folder_ver_id <> @folder_ver_id))
  BEGIN
    RAISERROR('Cannot change item or folder of a running job{3989}', 16, 1)
    RETURN -1
  END

	IF NOT EXISTS (SELECT TOP 1 1 FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND edit_time = @edit_time)
		RETURN

  -- Added for CR L00108888 - RWN 11/19/2010
  SELECT @num_decimals = num_decimals FROM item WITH (NOLOCK) WHERE item_id = @item_id
  SET @num_decimals = ISNULL(@num_decimals, 0)
  SET @qty_reqd = ROUND(@qty_reqd, @num_decimals)
  SET @qty_prod = ROUND(@qty_prod, @num_decimals)
  SET @qty_prod_erp = ROUND(@qty_prod_erp, @num_decimals)
  SET @qty_rejected = ROUND(@qty_rejected, @num_decimals)
  SET @qty_rejected_erp = ROUND(@qty_rejected_erp, @num_decimals)
  SET @qty_at_start = ROUND(@qty_at_start, @num_decimals)
  -- End of additions for CR L00108888 - RWN 11/19/2010
  -- KRF 7/8/03

  UPDATE job
  SET	--segment_requirement_id = @segment_requirement_id, -- Added 07/16/2009 RWB -- Removed 08/20/2009 SLR
		--segment_response_id = @segment_response_id, -- Added 07/16/2009 RWB -- Removed 08/20/2009 SLR
		job_desc = @job_desc,
		item_id = @item_id,
		state_cd = @state_cd,
		job_priority = @job_priority,
		--req_finish_time = DATEADD(mi, -@time_zone_bias_value, @req_finish_time), 07/25/2007 AML
		req_finish_time_utc = DATEADD( mi, - @req_finish_time_tz, @req_finish_time_local ),
		req_finish_time_local = @req_finish_time_local,
		init_sched_ent_id = @init_sched_ent_id,
		target_sched_ent_id = @target_sched_ent_id,
		run_ent_id = @run_ent_id,
		qty_reqd = @qty_reqd,
		qty_prod = @qty_prod,
		qty_prod_erp = @qty_prod_erp,
		qty_rejected = @qty_rejected,
		qty_rejected_erp = @qty_rejected_erp,
		qty_at_start = @qty_at_start,
		deviation_above = @deviation_above,
		deviation_below = @deviation_below,
		batch_size = @batch_size,
		sched_pinned = @sched_pinned,
		check_inv = @check_inv,
		est_fixed_lab = @est_fixed_lab,
		est_lab_rate = @est_lab_rate,
		est_setup_time = @est_setup_time,
		est_teardown_time = @est_teardown_time,
		est_prod_rate = @est_prod_rate,
		prod_uom = @prod_uom,
		est_transfer_time = @est_transfer_time,
		--sched_start_time = DATEADD(mi, -@time_zone_bias_value, @sched_start_time),
		sched_start_time_utc = DATEADD( mi, - @sched_start_time_tz, @sched_start_time_local ), -- Added 07/25/2007
		sched_start_time_local = @sched_start_time_local, -- Added 07/25/2007
		--latest_start_time = DATEADD(mi, -@time_zone_bias_value, @latest_start_time) ,
		latest_start_time_utc = DATEADD( mi, - @latest_start_time_tz, @latest_start_time_local ), -- Added 07/25/2007
		latest_start_time_local = @latest_start_time_local, -- Added 07/25/2007
		--sched_finish_time = DATEADD(mi, -@time_zone_bias_value, @sched_finish_time),
		sched_finish_time_utc = DATEADD( mi, - @sched_finish_time_tz, @sched_finish_time_local ), -- Added 07/25/2007
		sched_finish_time_local = @sched_finish_time_local, -- Added 07/25/2007
		--act_start_time = DATEADD(mi, -@time_zone_bias_value, @act_start_time) ,
		act_finish_time_utc = DATEADD( mi, - @act_finish_time_tz, @act_finish_time_local ), -- Added 07/25/2007
		act_finish_time_local = @act_finish_time_local,
		concurrent_link = @concurrent_link,
		job_cost = @job_cost,
		parent_contingent_job = @parent_contingent_job,
		child_contingent_job = @child_contingent_job,
		notes = @notes,
		assoc_file = @assoc_file,
		assoc_file_type = @assoc_file_type,
		status_notes = @status_notes,
		display_seq = @display_seq,
		folder_ver_id = @folder_ver_id,
		rework_cd = @rework_cd,	-- Added 07/25/2007
		rework = @rework,
        rework_process_id = @rework_process_id, -- Added 08/19/2009
		spare1 = @spare1,
		spare2 = @spare2,
		spare3 = @spare3,
		spare4 = @spare4,
		last_edit_comment = @last_edit_comment
  WHERE (wo_id = @wo_id AND
        oper_id = @oper_id AND
        seq_no = @seq_no AND
        edit_time = @edit_time)

  UPDATE job set display_seq = @display_seq where wo_id = @wo_id and oper_id = @oper_id --VRB

  --If item being produced changed and flag is true
  IF @create_job_bom = 1 AND @orig_item_id <> @item_id
  BEGIN
    RAISERROR('Cannot change item or folder of a running job{3989}', 16, 1)
    RETURN -1
    --Get the item data from the preferred bom version
    SELECT @reqd_grade_cd = i.reqd_grade_cd, @instruction = i.instruction, @max_qty_per_parent_item = i.max_qty_per_parent_item,
           @min_qty_per_parent_item = i.min_qty_per_parent_item, @update_inv = i.update_inv, @backflush = i.backflush,
           @def_reas_cd = i.def_reas_cd, @def_lot_no = i.def_lot_no, @def_storage_ent_id = i.def_storage_ent_id,
           @def_reject_ent_id = i.def_reject_ent_id, @scaling_factor = i.scaling_factor, @must_consume_from_inv = i.must_consume_from_inv,
           @may_choose_alt_inv_loc = i.may_choose_alt_inv_loc, @may_create_new_lots = i.may_create_new_lots,
           @must_consume_before_prod = i.must_consume_before_prod
      FROM bom_item i WITH (NOLOCK)
      INNER JOIN bom_ver v WITH (NOLOCK) ON i.parent_item_id = v.parent_item_id AND i.ver_id = v.ver_id
        WHERE i.parent_item_id = @item_id AND v.preferred_ver = 1

    --Get the reqd start val from system attr as percent
    SELECT @reqd_start_val = attr_value/100.0 FROM system_attr WITH (NOLOCK) WHERE attr_id = 203
    --Get the mod id for bom pos 0
    SELECT @mod_id = CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id))) FROM job_bom WITH (NOLOCK)
      WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no AND bom_pos = 0
    --Update job bom
    EXECUTE sp_U_Job_Bom @wo_id, @oper_id, @seq_no, 0, @item_id, @reqd_grade_cd, @instruction, 1, @max_qty_per_parent_item,
                         @min_qty_per_parent_item, @reqd_start_val, 1, @update_inv, @backflush, @def_reas_cd, @def_lot_no,NULL,
                         @def_storage_ent_id, @def_reject_ent_id, @scaling_factor, @must_consume_from_inv, @may_choose_alt_inv_loc,
                         @may_create_new_lots, 1, @must_consume_before_prod, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,@last_edit_comment, @mod_id

  END -- End of @create_job_bom = 1 AND @orig_item_id <> @item_id


	EXEC sp_U_Wo_ValJobRteWithLineRte @wo_id = @wo_id, @upstream_ent_name = @upstream_ent_name OUTPUT, @downstream_ent_name	= @downstream_ent_name OUTPUT

	IF (@upstream_ent_name IS NOT NULL OR @downstream_ent_name IS NOT NULL) BEGIN
		SELECT @line_name = l.line_name
		FROM line l WITH (NOLOCK)
		INNER JOIN wo wo WITH (NOLOCK) ON l.line_id = wo.target_sched_line_id
		WHERE wo.wo_id = @wo_id

		SET @err_msg = 'The work order: %1 is currently assigned to line: %2. The job cannot be updated, because the sequence of entities (upstream entity: %3, downstream entity: %4) in the job route do not match with the sequence of entities in the line route.{7920},' + @wo_id + ',' + @line_name + ',' + COALESCE(@upstream_ent_name, '') + ',' + COALESCE(@downstream_ent_name, '')
		RAISERROR(@err_msg, 16, 1)
		RETURN
	END

END

--===========================================================================================
-- Name:    sp_s_ei_hu_stock_receipt_child
-- Description:  used by middleware for insert/update Stored procedure
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  Karthik     2022-12-07		   Initial version.
-- ===========================================================================================

CREATE   PROCEDURE [dbo].[sp_s_ei_hu_stock_receipt_child] @order_number varchar(100),@qty float,@uom varchar(10),
@pallet_id varchar(100),@sender_plant varchar(50),@receiving_plant varchar(50),@receiving_storage_locn varchar(50),
@sender_storage_locn varchar(50),@nestdChild_HU varchar(50),@material_no_child_HU varchar(50),@batch_no_child_HU varchar(50),
@qty_child_HU varchar(50),@usage_decsn_child_HU varchar(10),@blend_ratio float
as
begin
	Declare
	@ent_id int , -- sender storage location
	@item_id nvarchar(40),
	@lot_no nvarchar(40) , --- Batch_no_child Hu
	@sublot_no nvarchar(40) , --- generated using new sp
	@grade_cd int , --- item_grade state code 0
	@status_cd int , --- item_state normal state code
	@qty_left float ,@qty_left_erp float ,-- qty_left
	@uom_id int,@date_in_local datetime,@date_out_local datetime,@expiry_date datetime,	@last_edit_at datetime,	@row_id int

	DECLARE @error_msg  NVARCHAR(MAX),@error_severity INT,@error_state INT

    SET NOCOUNT ON


	SELECT 1 from item_inv WITH (NOLOCK) where  spare2 = @pallet_id and spare3 = @nestdChild_HU
end

--===========================================================================================
-- Name:    SP_S_ofi_GenerateHUNumber_New
-- Description:  generate hu number based on automation requested handshake
--
-- Usage:  Always gets called from the ArchestrA scripts under $AUT_Interfaces instances
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  AML, XPM      2025-01-13        Created a new version for GenerateHUNo
-- ===========================================================================================
CREATE  PROCEDURE [dbo].[SP_S_ofi_GenerateHUNumber_New] (
    @HU_Type INT = NULL,
    @wo_id VARCHAR(100),
    @oper_id VARCHAR(100),
    @seq_no VARCHAR(40)
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Single call to GETDATE(). Calling GETDATE() multiple times can cause inconsistencies (we can execute it at 23:59:59 and the date can change)

    DECLARE @CurrentDT DATETIME = GETDATE();
    
    DECLARE @plant_code INT, @line_no VARCHAR(10), @parenthu_no VARCHAR(10);
    DECLARE @parent_ent_id INT;
    DECLARE @serial_no INT, @new_serialno_str VARCHAR(3);
    DECLARE @year_2d VARCHAR(2), @year_1d VARCHAR(1), @month VARCHAR(2), @day VARCHAR(2);
    DECLARE @SAPNumber NVARCHAR(20), @DCSNumber NVARCHAR(20), @hunumber_f VARCHAR(20) = NULL;
    DECLARE @attr_serial_id INT, @target_attr_id INT;
    DECLARE @result INT = 0;
    
    -- Variable to control if we actually need a new serial number
    DECLARE @MustGenerateSerial BIT = 1; 

    -- Date Formatting (without calling GETDATE)
    SET @year_2d = RIGHT(YEAR(@CurrentDT), 2);
    SET @year_1d = RIGHT(YEAR(@CurrentDT), 1);
    SET @month   = FORMAT(@CurrentDT, 'MM');
    SET @day     = FORMAT(@CurrentDT, 'dd');

    -- Get Attribute IDs
    SELECT @attr_serial_id = attr_id FROM attr WITH (NOLOCK) WHERE attr_desc = 'HUSerialNo';
    SELECT @plant_code = attr_value FROM system_attr WITH (NOLOCK) WHERE attr_desc = 'HUPlantCode';

    -- Get Parent Entity ID based on Work Order 
    SELECT @parent_ent_id = e.parent_ent_id
    FROM ent e WITH (NOLOCK)
    INNER JOIN job j WITH (NOLOCK) ON j.run_ent_id = e.ent_id
    WHERE j.wo_id = @wo_id AND j.oper_id = @oper_id AND j.seq_no = @seq_no;

    -- Get Line Code
    SELECT @line_no = ea.attr_value 
    FROM ent_attr ea WITH(NOLOCK) 
    JOIN attr a WITH(NOLOCK) ON a.attr_id = ea.attr_id 
    WHERE a.attr_desc = 'LineCode' AND ea.ent_id = @parent_ent_id;


    --Check if NestedHU exists BEFORE generating a serial number. Use JOIN instead of IN (SELECT).

    IF @HU_Type = 3
    BEGIN
        -- Get Parent HU Group code
        SELECT @parenthu_no = ea.attr_value 
        FROM ent_attr ea WITH(NOLOCK) 
        JOIN attr a WITH(NOLOCK) ON a.attr_id = ea.attr_id 
        WHERE a.attr_desc = 'ParentHUGroup' AND ea.ent_id = @parent_ent_id;

        DECLARE @nested_hu_attr_id INT;
        SELECT @nested_hu_attr_id = attr_id FROM attr WITH(NOLOCK) WHERE attr_desc = 'NestedHU' AND attr_grp = 2;

        -- Check if it already exists
        SELECT @hunumber_f = ea_nested.attr_value
        FROM ent_attr ea_group WITH (NOLOCK)
        INNER JOIN attr a_group WITH (NOLOCK) ON a_group.attr_id = ea_group.attr_id
        INNER JOIN ent_attr ea_nested WITH (NOLOCK) ON ea_nested.ent_id = ea_group.ent_id
        WHERE a_group.attr_desc = 'ParentHUGroup'
            AND ea_group.attr_value = @parenthu_no
            AND ea_nested.attr_id = @nested_hu_attr_id;

        IF @hunumber_f IS NOT NULL
        BEGIN
            -- Found existing HU, we do NOT need a new serial
            SET @MustGenerateSerial = 0; 
            SET @result = 1; 
        END
    END
    
    IF @MustGenerateSerial = 1
    BEGIN
        BEGIN TRANSACTION;
            
            DECLARE @last_edit_at DATETIME;
            DECLARE @current_val VARCHAR(255);
            
          
            SELECT 
                @current_val = attr_value, 
                @last_edit_at = last_edit_at
            FROM process_attr
            WHERE attr_id = @attr_serial_id;

           
            IF (CAST(@CurrentDT AS DATE) <> CAST(@last_edit_at AS DATE))
                SET @serial_no = 1;
            ELSE
                SET @serial_no = CAST(@current_val AS INT) + 1;

            EXEC [dbo].[sp_U_ofi_Process_Attr] 
                @attr_id = @attr_serial_id,
                @attr_value = @serial_no;

        COMMIT TRANSACTION;

        SET @new_serialno_str = RIGHT('000' + CAST(@serial_no AS VARCHAR(10)), 3);
    END

    
    -- Type 1 or 2

    IF @HU_Type IN (1, 2)
    BEGIN
        DECLARE @Type INT = @HU_Type;
        DECLARE @AttrName VARCHAR(50) = CASE WHEN @HU_Type=1 THEN 'GoodHU' ELSE 'RejectHU' END;

        SELECT @target_attr_id = attr_id FROM attr WITH (NOLOCK) WHERE attr_desc = @AttrName;

        -- Generate Formats
        SET @DCSNumber = CONCAT(@Type, @year_1d, @month, @day, @new_serialno_str);
        SET @SAPNumber = CONCAT(@plant_code, @line_no, @Type, @year_2d, @month, @day, @new_serialno_str, '0');

        --Reject Flush Number
        IF @HU_Type = 2
            SET @hunumber_f = CONCAT(@plant_code, @line_no, @year_2d, @month, @day, @new_serialno_str, 'F');

        --Update if exists, else Insert 
        
        IF EXISTS (SELECT 1 FROM wo_attr WITH(NOLOCK) WHERE wo_id=@wo_id AND attr_id=@target_attr_id)
        BEGIN
            UPDATE wo_attr SET attr_value = @SAPNumber WHERE wo_id=@wo_id AND attr_id=@target_attr_id;
        END
        ELSE
        BEGIN
            EXEC [dbo].[sp_I_Wo_Attr] @wo_id, @target_attr_id, @SAPNumber, NULL, NULL, NULL;
        END
    END

    -- Type 3
    ELSE IF @HU_Type = 3 AND @MustGenerateSerial = 1
    BEGIN
        -- We only enter here if it didn't exist before
        SET @hunumber_f = CONCAT(@plant_code, @parenthu_no, '2', @year_2d, @month, @day, @new_serialno_str, '0');
            
        EXEC [dbo].[sp_I_Ent_Attr] 
            @ent_id = @parent_ent_id, 
            @attr_id = @nested_hu_attr_id,
            @attr_value = @hunumber_f,
            @notes = NULL, @last_edit_comment = NULL, @last_edit_at = NULL;
    END
    
    -- Errors
    ELSE IF @HU_Type NOT IN (1, 2, 3)
    BEGIN
        SET @result = -1;
    END


    SELECT 
        @SAPNumber AS hunumber,
        @DCSNumber AS dcs_number,
        @hunumber_f AS flush_hunumber,
        @result AS result;

END

