--	0.01	02-Apr-2018				PG						Initial Version
--
--
--	EXEC sp_U_GMES_Helper_ReindexTables
--
-- ===========================================================================================================

CREATE PROCEDURE [dbo].[sp_U_MES_Helper_ReindexTables]
AS
BEGIN
	SET NOCOUNT ON ;

	DECLARE @TableName VARCHAR(255) ;
	DECLARE @tblForIndex Table
	(
		row_id INT IDENTITY(0, 1) NOT NULL,
		table_name nvarchar(80)
	) ;

	DECLARE @row_min int ;
	DECLARE @row_max int ;

	INSERT INTO @tblForIndex (table_name)
		SELECT '['+TABLE_SCHEMA +'].['+TABLE_NAME+']'
		FROM information_schema.tables
		WHERE 
			table_type = 'base table';

	SELECT @row_min = MIN(row_id), @row_max = MAX(row_id) FROM @tblForIndex ;

	WHILE (@row_min <= @row_max) BEGIN
		SELECT @TableName = table_name FROM @tblForIndex WHERE row_id = @row_min ;

		DBCC DBREINDEX(@TableName, '', 80);

		SET @row_min = @row_min + 1 ;
	END ;

	EXEC sp_updatestats ;

END

-- Procedure definition
CREATE PROCEDURE [dbo].[sp_SA_Spc_Rule]
    (
      @rule_desc NVARCHAR(40) ,
      @use_for_ix BIT = 0 ,
      @use_for_mr BIT = 0 ,
      @use_for_xbar BIT = 0 ,
      @use_for_range BIT = 0 ,
      @use_for_sigma BIT = 0 ,
      @use_for_ma BIT = 0 ,
      @use_for_ewmaix BIT = 0 ,
      @use_for_run BIT = 0 ,
      @use_for_attr BIT = 0 ,
      @test1 INT ,
      @test2 INT ,
      @and_not_or BIT ,
      @level1 FLOAT ,
      @level2 FLOAT ,
      @num_points INT ,
      @of_points INT ,
      @priority INT ,
      @obsolete BIT ,
      @last_edit_by NVARCHAR(40) ,
      @created_by NVARCHAR(40) ,
      @last_edit_at DATETIME ,
      @created_at DATETIME ,
      @rule_id INT ,
      @time_zone_bias_value INT32 = 0
    )
AS --- ***********************************************************************************************************************
-- Module Name      - sp_SA_Spc_Rule
-- Description      - Select multiple rows filtered by any included column values
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
-- Notes            -
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified      Modified_By      Changes
--09/26/2005   Raghu    3.1.0 Part of DB Changes
--02/02/2007   Raghu    3.2.0 Part of DB Changes
--12/22/2009   Kishore  4.0      HF1432 - Removed conversion to local time.
--08/29/2011  JA        4.5   MES-QM changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
    SET NOCOUNT ON
    SET XACT_ABORT ON

    BEGIN
        SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)
        IF @created_at IS NOT NULL
            SET @created_at = DATEADD(mi, -@time_zone_bias_value, @created_at)

        SELECT  spc_rule.rule_desc ,
                spc_rule.use_for_ix ,
                spc_rule.use_for_mr ,
                spc_rule.use_for_xbar ,
                spc_rule.use_for_range ,
                spc_rule.use_for_sigma ,
                spc_rule.use_for_ma ,
                spc_rule.use_for_ewmaix ,
                spc_rule.use_for_run ,
                spc_rule.use_for_attr ,
                spc_rule.test1 ,
                spc_rule.test2 ,
                spc_rule.and_not_or ,
                spc_rule.level1 ,
                spc_rule.level2 ,
                spc_rule.num_points ,
                spc_rule.of_points ,
                spc_rule.priority ,
                spc_rule.obsolete ,
                spc_rule.last_edit_comment ,
                spc_rule.last_edit_by ,
                spc_rule.created_by ,
                spc_rule.last_edit_at ,
                spc_rule.created_at AS created_at ,
                spc_rule.rule_id
        FROM    spc_rule spc_rule WITH ( NOLOCK )
        WHERE   ( ( spc_rule.rule_desc = @rule_desc
                    OR @rule_desc IS NULL
                  )
                  AND ( spc_rule.use_for_ix = ABS(@use_for_ix)
                        OR @use_for_ix IS NULL
                      )
                  AND ( spc_rule.use_for_mr = ABS(@use_for_mr)
                        OR @use_for_mr IS NULL
                      )
                  AND ( spc_rule.use_for_xbar = ABS(@use_for_xbar)
                        OR @use_for_xbar IS NULL
                      )
                  AND ( spc_rule.use_for_range = ABS(@use_for_range)
                        OR @use_for_range IS NULL
                      )
                  AND ( spc_rule.use_for_sigma = ABS(@use_for_sigma)
                        OR @use_for_sigma IS NULL
                      )
                  AND ( spc_rule.use_for_ma = ABS(@use_for_ma)
                        OR @use_for_ma IS NULL
                      )
                  AND ( spc_rule.use_for_ewmaix = ABS(@use_for_ewmaix)
                        OR @use_for_ewmaix IS NULL
                      )
                  AND ( spc_rule.use_for_run = ABS(@use_for_run)
                        OR @use_for_run IS NULL
                      )
                  AND ( spc_rule.use_for_attr = ABS(@use_for_attr)
                        OR @use_for_attr IS NULL
                      )
                  AND ( spc_rule.test1 = @test1
                        OR @test1 IS NULL
                      )
                  AND ( spc_rule.test2 = @test2
                        OR @test2 IS NULL
                      )
                  AND ( spc_rule.and_not_or = ABS(@and_not_or)
                        OR @and_not_or IS NULL
                      )
                  AND ( spc_rule.level1 = @level1
                        OR @level1 IS NULL
                      )
                  AND ( spc_rule.level2 = @level2
                        OR @level2 IS NULL
                      )
                  AND ( spc_rule.num_points = @num_points
                        OR @num_points IS NULL
                      )
                  AND ( spc_rule.of_points = @of_points
                        OR @of_points IS NULL
                      )
                  AND ( spc_rule.priority = @priority
                        OR @priority IS NULL
                      )
                  AND ( spc_rule.obsolete = @obsolete
                        OR @obsolete IS NULL
                      )
                  AND ( spc_rule.last_edit_by = @last_edit_by
                        OR @last_edit_by IS NULL
                      )
                  AND ( spc_rule.created_by = @created_by
                        OR @created_by IS NULL
                      )
                  AND ( spc_rule.last_edit_at = @last_edit_at
                        OR @last_edit_at IS NULL
                      )
                  AND ( spc_rule.created_at = @created_at
                        OR @created_at IS NULL
                      )
                  AND ( spc_rule.rule_id = @rule_id
                        OR @rule_id IS NULL
                      )
                )

    END

--===========================================================================================
-- Name:    SP_U_EI_MM_WIP_ITEM
-- Description:  Inserts the WIP item
--
-- Usage:  This will be used by EI
-- ===========================================================================================
-- Version  Author      Date (yyyy-MM-dd)  Change description
-- 0.01.00  KN          2023-01-12      Initial version.
-- 0.01.01  kn			2023-07-20		Update logic to handle WIP items
-- 0.01.02	KN			2023-07-25		Added logic to handle WIP creation for FG items
-- 0.01.03	LK			2024-02-27		Modified the else logic for spare2
-- 0.01.04	LK			2024-03-01		Updated logic to add item attribute
-- 0.01.05	LK			2024-06-19		Updated logic to delete existing attribute, added condition to delete only those which are coming from sap
-- ===========================================================================================


CREATE               PROCEDURE [dbo].[SP_U_EI_MM_WIP_ITEM] (@item_id NVARCHAR(40),@item_class NVARCHAR(80),@item_group NVARCHAR(80)) AS
BEGIN
	DECLARE @item_desc VARCHAR(MAX), @is_wip BIT,@wip_item_id VARCHAR(50), @wip_name VARCHAR(MAX), @spare2 VARCHAR(MAX), @wip_class VARCHAR(MAX), @wip_desc VARCHAR(MAX), 
	@wip_item_grp VARCHAR(MAX), @rc INT, @attr_id INT,@mod_id VARCHAR(40), @uom_id INT, @lifetime INT, @obsolete BIT, @num_decimals INT,
	@error_msg  NVARCHAR(500), @error_severity INT, @error_state    INT,@item_class_id VARCHAR(100),
	@item_classification   NVARCHAR(80),                                           
    @plant_code            NVARCHAR(40),                                           
    @legacy_code           NVARCHAR(40),
    @item_status           NVARCHAR(40),  
	@material_state        NVARCHAR(40),
	@production_supervisor NVARCHAR(40),
	@itemgrpattrid int,
	@prodsuperattrid int,
	@plantcodeattrid int,
	@languagekeyattrid int,
	@legacykeyattrid int,
	@automationidattrid int

	IF EXISTS (SELECT 1 FROM item WHERE item_id = @item_id)
	BEGIN

		--DO THE ENTIRE LOGIC ONLY FOR SFG ITEMS OR FOR ITEMS WITH ITEM GROUP EITHER AS COCOA LIQUOR OR CAKE
		
		IF UPPER(@item_class) = UPPER('Semifinished Goods') OR (UPPER(@item_group) = UPPER('Cocoa Liquor') OR UPPER(@item_group) = UPPER('Cocoa Cake') OR UPPER(@item_group) = UPPER('Cocoa Butter')) -- (KN 25JUL Changed Cake to Cocoa Cake as there is no such material group for just Cake)
		BEGIN		
			SELECT @item_desc = item_desc,@item_class_id = item_class_id FROM item with(nolock) WHERE item_id = @Item_id

			PRINT @item_class

			SET @spare2 = NULL
			SELECT @spare2 = spare2 FROM item_class with(nolock) WHERE item_class_id = @item_class or item_class_desc = @item_class

			SELECT @uom_id = uom_id,@lifetime = lifetime,@obsolete = obsolete,@num_decimals = num_decimals FROM item with(nolock) WHERE item_id = @item_id

			--CREATE A NEW WIP ITEM ID BASED ON THE INCOMING ITEM ID. THE REST OF THE ITEM DETAILS CAN BE REUSED

			IF @spare2 IS NULL
				SET @wip_item_id = CONCAT('50', substring(@Item_id, 3, len(@Item_id)))
			ELSE
				SET @wip_item_id = CONCAT(@spare2, substring(@Item_id, 3, len(@Item_id))) -- 0.01.03

			SELECT @wip_class = item_class_id FROM item_class with(nolock) WHERE item_class_desc = 'Intermediate Materials'
			
			SET @wip_desc = 'WIP '

			DECLARE @attr_desc varchar(100) = NULL

			SELECT @attr_desc = attr_value from item_attr with(nolock) where item_id = @Item_id and attr_id = (Select attr_id from attr where attr_desc = 'ItemGroup')

			/*KN 25Jul23 Added below logic to handle WIP creation for FG process*/

			IF @item_class_id = 'FG'
				BEGIN
					IF @attr_desc LIKE '%liquor%' SET @wip_desc = @wip_desc + '(LIQUOR BLEND) '
					ELSE IF @attr_desc LIKE '%butter%' SET @wip_desc = @wip_desc + '(BUTTER BLEND) '
					--ELSE IF @attr_desc LIKE '%cake%' SET @wip_desc = @wip_desc + '(CAKE BLEND) '
				END
			ELSE IF @attr_desc LIKE '%powder%'
				SET @wip_desc = @wip_desc + '(CAKE) '
			ELSE
				SET @wip_desc = @wip_desc + '(NIBS) '

			SET @wip_desc = @wip_desc +   @item_desc
			SET @wip_name = @wip_desc
			print @wip_desc
			BEGIN TRY
			BEGIN TRANSACTION

			--UPDATE THE NEW WIP ITEM

				EXECUTE @rc = [dbo].[Sp_u_item]
						@item_id = @wip_item_id,
						@item_desc =@wip_desc,
						@item_class_id = @wip_class,
						@uom_id = @uom_id,
						@template = 0,
						@lifetime = @lifetime,
						@unit_cost = NULL,
						@obsolete = @obsolete,
						@purchased = 0,
						@sold = 0,
						@num_decimals = @num_decimals,
						@must_complete_steps = 0,
						@must_prod_reqd_qty = 0,
						@min_grade = NULL,
						@min_state = NULL,
						@min_inv_level = NULL,
						@reorder_amt = NULL,
						@auto_reorder = 0,
						@lot_no_format = NULL,
						@last_lot_no = NULL,
						@max_lot_size = NULL,
						@sublot_no_format = NULL,
						@last_sublot_no = NULL,
						@serial_no_lvl = -1,
						@max_sublot_size = NULL,
						@max_order_size = NULL,
						@min_trace_inv = NULL,
						@inv_unique_by_job = 0,
						@notes = NULL,
						@spare1 = 1,
						@spare2 = NULL,
						@spare3 = NULL,
						@spare4 = NULL,
						@last_edit_comment = N'UPDATED BY EI',
						@last_edit_at = NULL

						--added update if product sp didnt work
						UPDATE item
							  SET    item_desc = @wip_desc,
									 uom_id = @uom_id,
									 item_class_id = @wip_class,
									 lifetime = @lifetime,
									 obsolete = @obsolete
							  WHERE  item_id = @wip_item_id
				-- FOR THE WIP ITEM, UPDATE ITEM GROUP ATTRIBUTE BASED ON WHAT ITEM GROUP IT BELONGS TO

				SELECT @attr_id = attr_id FROM attr WHERE attr_desc= 'ItemGroup' AND attr_grp = 1


				IF @attr_desc LIKE '%powder%'
					SET @wip_item_grp = 'Cake'
				ELSE
					BEGIN
						IF @item_class_id = 'FG' SET @wip_item_grp = 'Liquor' ELSE SET @wip_item_grp = 'NIBS'
					END


				SELECT @mod_id= CONVERT(VARCHAR(30), CONVERT(DECIMAL(19, 4), CONVERT(MONEY, mod_id))) from item_attr where item_id =@wip_item_id and attr_id = @attr_id

				/*EXEC @rc = [dbo].[Sp_u_item_attr]
							@item_id = @wip_item_id,
							@attr_id = @attr_id,
							@attr_value = @wip_item_grp,
							@notes = 'UPDATED BY EI',
							@last_edit_comment = NULL,
							@mod_id = @mod_id*/
							-- 0.01.04
							DECLARE
							  @mainitemattr TABLE 
							  (
							   attr_desc nvarchar(40),
							   attr_value  nvarchar(40)
							  )
							 insert into @mainitemattr
								select a.attr_desc,ia.attr_value from item_attr ia with(nolock) inner join attr a with(nolock)
								on ia.attr_id=a.attr_id
								where item_id=@item_id order by a.attr_desc asc

								select @item_classification=attr_value from @mainitemattr where attr_desc='Classification'
								select @plant_code=attr_value from @mainitemattr where attr_desc='PlantCode'
								select @legacy_code=attr_value from @mainitemattr where attr_desc='LegacyCode'
								select @material_state=attr_value from @mainitemattr where attr_desc='MaterialType'
								select @production_supervisor=attr_value from @mainitemattr where attr_desc='ProductionSupervisor'
								
								select @itemgrpattrid =attr_id from attr with(nolock) where attr_desc='ItemGroup'
								select @languagekeyattrid =attr_id from attr with(nolock) where attr_desc='languagekey'
								select @plantcodeattrid =attr_id from attr with(nolock) where attr_desc='PlantCode'
								select @legacykeyattrid =attr_id from attr with(nolock) where attr_desc='LegacyCode'
								select @automationidattrid =attr_id from attr with(nolock) where attr_desc='AutomationItemId'
								select @prodsuperattrid=attr_id from attr with(nolock) where attr_desc='ProductionSupervisor'
																							
								delete from item_attr where item_id=@wip_item_id and attr_id in(@itemgrpattrid ,@prodsuperattrid,@plantcodeattrid ,@languagekeyattrid ,	@legacykeyattrid ,@automationidattrid )-- 0.01.05

							  Exec [dbo].[SP_I_EI_MM_Attr] 
							  @item_id  = @wip_item_id,
                                           @item_group= @wip_item_grp,
                                           @item_classification =@item_classification,
                                           @language_key='EN',
                                           @plant_code   =@plant_code,
                                           @production_supervisor=@production_supervisor,
                                           @legacy_code  =@legacy_code,
                                           @item_status ='ACTIVE',
										   @material_state  =@material_state,
										   @production_method=null
				COMMIT;
			END TRY
			BEGIN CATCH
				  IF @@TRANCOUNT > 0
					ROLLBACK TRANSACTION;

				  SELECT @error_msg = Error_message(),@error_severity = Error_severity(),@error_state = Error_state();
				  RAISERROR(@error_msg,@error_severity,@error_state)
			END CATCH

		END		
	END
END

CREATE PROCEDURE [dbo].[sp_I_Bom_Item_Subst]
  (@parent_item_id nvarchar(40) ,
   @ver_id nvarchar(40) ,
   @bom_pos int ,
   @alt_no int ,
   @pref int ,
   @subst_level int ,
   @item_id nvarchar(40) ,
   @reqd_grade_cd int ,
   @instruction nvarchar(2000) ,
   @qty_per_parent_item float ,
   @max_qty_per_parent_item float ,
   @min_qty_per_parent_item float ,
   @update_inv bit ,
   @backflush bit ,
   @def_reas_cd int ,
   @def_lot_no nvarchar(40) ,
   @def_sublot_no nvarchar(40) = NULL,
   @def_storage_ent_id int ,
   @def_reject_ent_id int ,
   @scaling_factor float ,
