   @may_choose_alt_inv_loc bit ,
   @may_create_new_lots bit ,
   @must_consume_from_wip bit ,
   @must_consume_before_prod bit ,
   @constant_qty bit ,
   @est_time float ,
   @spare1 nvarchar(1000) ,
   @spare2 nvarchar(1000) ,
   @spare3 nvarchar(1000) ,
   @spare4 nvarchar(1000) ,
   @last_edit_comment nvarchar(254) ,
   @last_edit_at datetime OUT)
AS
--- ***********************************************************************************************************************
-- Module Name      - sp_I_Bom_Item_Subst
-- Description      - Insert a row into the table
-- Date Created     - 10/17/2002
-- Version          - 1.5.0.0
--
-- Copyright (c) 2017 Schneider Electric Software, LLC. All rights reserved.
--
-- THIS CODE AND INFORMATION ARE PROVIDED "AS IS" WITHOUT WARRANTY OF ANY
-- KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE
-- IMPLIED WARRANTIES OF MERCHANTABILITY AND/OR FITNESS FOR A
-- PARTICULAR PURPOSE.
-- Notes            -
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified  Modified_By   Ver	Changes
-- 07/07/2004     Sheetal Jain  20024  	(HD# 4395) Maintain BOM_ver.ver_date automatically
-- 08/04/2004     Raghu		2.1.0	Disallow inserting substitution item if the item is the same as the main bom_item
-- 09/19/2005     Raghu		3.1.0	Part of DB Changes
-- 01/04/2007     KRF           3.2.1   HD# 8314 - Added @def_sublot_no argument
-- 01/18/2007     KRF		3.2.1	HD# 8434 - Make conversion of current datetime back to a datetime type explicit
-- 10/24/2007		AML				3.3.4		HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--												dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET XACT_ABORT ON
SET NOCOUNT ON
DECLARE  @last_edit_by	NVARCHAR(40)
	,@current_time	TDATETIME
	,@use_GMT	INT32

BEGIN

  IF EXISTS (SELECT TOP 1 1 FROM bom_item WHERE parent_item_id = @parent_item_id AND ver_id = @ver_id AND bom_pos = @bom_pos AND item_id = @item_id) BEGIN
	RAISERROR('The substitute bom item cannot be the same item as the bom item{2631}', 16, 1)
	RETURN
  END

  EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL
  SET @last_edit_at = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

 INSERT INTO bom_item_subst
 (parent_item_id,
  ver_id,
  bom_pos,
  alt_no,
  pref,
  subst_level,
  item_id,
  reqd_grade_cd,
  instruction,
  qty_per_parent_item,
  max_qty_per_parent_item,
  min_qty_per_parent_item,
  update_inv,
  backflush,
  def_reas_cd,
  def_lot_no,
  def_sublot_no,
  def_storage_ent_id,
  def_reject_ent_id,
  scaling_factor,
  must_consume_from_inv,
  may_choose_alt_inv_loc,
  may_create_new_lots,
  must_consume_from_wip,
  must_consume_before_prod,
  constant_qty,
  est_time,
  spare1,
  spare2,
  spare3,
  spare4,
  last_edit_comment,
  last_edit_by,
  last_edit_at)
VALUES
  (@parent_item_id,
   @ver_id,
   @bom_pos,
   @alt_no,
   @pref,
   @subst_level,
   @item_id,
   @reqd_grade_cd,
   @instruction,
   @qty_per_parent_item,
   @max_qty_per_parent_item,
   @min_qty_per_parent_item,
   @update_inv,
   @backflush,
   @def_reas_cd,
   @def_lot_no,
   @def_sublot_no,
   @def_storage_ent_id,
   @def_reject_ent_id,
   @scaling_factor,
   @must_consume_from_inv,
   @may_choose_alt_inv_loc,
   @may_create_new_lots,
   @must_consume_from_wip,
   @must_consume_before_prod,
   @constant_qty,
   @est_time,
   @spare1,
   @spare2,
   @spare3,
   @spare4,
   @last_edit_comment,
   @last_edit_by,
   @last_edit_at)

  --Maintain bom version date automatically
	EXEC sp_SA_System_Attr_UseGMT @use_GMT OUTPUT
	IF @use_GMT = 1 SET @current_time = GETUTCDATE() ELSE SET @current_time = dbo.fn_TZ_GetLocalDate(NULL)

  UPDATE bom_ver SET ver_date = @current_time WHERE parent_item_id = @parent_item_id AND ver_id = @ver_id
END

