/*--===========================================================================================
-- Name:		SP_I_OFI_BinProdCons
-- Description:	to cons and prouce bins
-- 
-- Usage:		
-- ===========================================================================================
-- Version	Author			Date (yyyy-MM-dd)	Change description
-- 0.01.00	SSB				2024-04-12		Initial version
-- 0.01.01	SSB/VJ			2024-04-24		Updated for origin line wo orders
--===========================================================================================*/
-- *************************************************************************************************************************
CREATE PROCEDURE [dbo].[SP_I_OFI_BinProdCons]
@ent_id INT,
@wo_id nvarchar(50),
@collectionStartTime nvarchar(50),
@collectionEndTime nvarchar(50),
@item nvarchar(MAX),
@originArea INT,
@qty float=50,
@USERNAME NVARCHAR(100)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
declare --@ent_id nvarchar(50),
@datefrom AS nvarchar(40),
@dateto AS nvarchar(40),
@total float,
@bom_pos int,
@item_id nvarchar(50),
@ent_name NVARCHAR(80),
@scn_oper_id NVARCHAR(MAX),
@scn_seq_no int


declare
  @date_from datetime = CONVERT(datetime, @collectionStartTime),
  @date_to datetime = CONVERT(datetime, @collectionEndTime),
  @attrConsumptionMode nvarchar(50)='BinConsumptionMode',
  @attrConsumptionModeValue nvarchar(50)=0,
  @consumptionMode nvarchar(50)='Manual',
  @itemUom NVARCHAR(50)

  select @attrConsumptionModeValue=ea.attr_value from ent e
inner join ent e1 on e1.ent_id=e.parent_ent_id
	inner join ent_attr ea (nolock) on e1.ent_id=ea.ent_id
	inner join attr a on ea.attr_id=a.attr_id
	where e.ent_id=@ent_id and a.attr_desc=@attrConsumptionMode

IF @attrConsumptionModeValue=1 
BEGIN

SET @consumptionMode='Automated'
select @item=mes_item_id from ufn_ofi_mes_aut_itemid(@item,2)
END

DECLARE @OriginEntities as table (ent_id INT)

--GET MES ITEM ID
select @item_id=item.item_id , @itemUom=uom.description from item 
INNER JOIN uom on item.uom_id=uom.uom_id
where item_id =@item

select * from item 
INNER JOIN uom on item.uom_id=uom.uom_id
where item_id =@item




--considering rework has only one operation Get run_ent_id from WO
select @scn_oper_id=oper_id,@scn_seq_no=seq_no from job where wo_id=@wo_id AND run_ent_id=@ent_id

--get oal ent name
declare @oal_ent_name nvarchar (50)
SELECT @oal_ent_name= ISNULL(description, ent_name) FROM ent WHERE ent_id=@originArea

--GET ENTITY NAME
SELECT @ent_name= ISNULL(description, ent_name) FROM ent WHERE ent_id=@ent_id

--get consumpiton mode
--select @attrConsumptionModeValue=ea.attr_value from ent e
--	inner join ent_attr ea (nolock) on e.ent_id=ea.ent_id
--	inner join attr a on ea.attr_id=a.attr_id
--	where ea.ent_id=@ent_id and a.attr_desc=@attrConsumptionMode



INSERT INTO @OriginEntities select ent.ent_id
		FROM ent_attr ea WITH (NOLOCK)
		INNER JOIN ent WITH (NOLOCK) ON ent.ent_id = ea.ent_id
		INNER JOIN attr WITH (NOLOCK) ON ea.attr_id = attr.attr_id
		WHERE attr_desc = 'EntityType'
		AND ea.attr_value IN ('Segment')
		AND (ent.parent_ent_id=@originArea or ent.parent_ent_id in (select ent_id from ent where parent_ent_id=@originArea))


--select distinct wo_id,qty_prod from item_prod where ent_id=@ent_id and created_at_utc BETWEEN @date_from AND @date_to

--select *,e.ent_name from @OriginEntities oa
--inner join ent e on e.ent_id=oa.ent_id
DECLARE
  @jobprod TABLE 
  (
    id int IDENTITY (1, 1) NOT NULL,
	ent_id int,
    wo_id nvarchar(40),
    oper_id nvarchar(40),
    seq_no int,
    state_cd int,
    item_id nvarchar(40),
    total_qtyprod float,  
	split_qty  DECIMAL(10, 3),
    def_lot_no nvarchar(40),
	sublot_no nvarchar(40),
    shift_start_local datetime,
    hour_start_local datetime,
    created_at_utc datetime
  )



	--INSERT wo, Production for Origin Line /Area for specified time into temp table
;with cte_wo as (select wxt.wo_id from ofi_wo_item_ext wxt
Inner join wo WITH (NOLOCK) on wxt.wo_id=wo.wo_id
where 
wxt.bom_pos < 0 
AND wxt.item_id=@item_id
and wo.state_cd IN (1, 2) -- (Started/Completed)
),
	--INSERT @jobprod
CTE_prod as (SELECT
    ip.ent_id,
			ip.wo_id,
           ip.oper_id,
           ip.seq_no,
           j.state_cd,          
		   j.item_id,             
		   SUM(ip.qty_prod) qty_prod,
           NULL as split_qty,
           MAX(ip.lot_no) as lot_no,
		   MAX(IP.sublot_no) as sublot_no,
           MAX(ip.shift_start_local) shift_start_local,
           MAX(ip.hour_start_local) hour_start_local,
           MAX(ip.created_at_utc) created_at_utc
    FROM item_prod ip WITH (NOLOCK)
    INNER JOIN wo w WITH (NOLOCK)ON ip.wo_id = w.wo_id
    INNER JOIN job j WITH (NOLOCK) ON ip.wo_id = j.wo_id  AND ip.oper_id = j.oper_id   AND ip.seq_no = j.seq_no
	INNER JOIN job_bom JB WITH(NOLOCK) on jb.wo_id=ip.wo_id and ip.oper_id=jb.oper_id and ip.seq_no=jb.seq_no and ip.item_id=jb.item_id 
	INNER JOIN @OriginEntities oe on ip.ent_id=oe.ent_id 
	Inner join cte_wo on ip.wo_id=cte_wo.wo_id
    WHERE	
	 jb.bom_pos=0
	AND w.state_cd IN (1, 2) -- (Started/Completed)    
   AND j.state_cd IN (3, 4, 5)-- (RUNNING/COMPLETED/STOPPED)
	AND ip.created_at_utc BETWEEN @date_from AND @date_to --date from and date to logic not yet added due to testing
    GROUP BY ip.wo_id,
             ip.oper_id,
             ip.seq_no,
             j.item_id,           
             j.state_cd,
			 ip.ent_id
			 )

	INSERT INTO @jobprod select * from CTE_prod

	SELECT @total = SUM(total_qtyprod)  FROM @jobprod

    UPDATE @jobprod
    SET split_qty = ((total_qtyprod * @qty) / @total)


	declare @rwsCount int
	declare @to_ent_id int,
	@row_id int,
	@cur_wo_id nvarchar(50),
	@cur_oper_id nvarchar(max),
	@cur_seq_no int,
	@cur_qty float,
	@cur_shift_start datetime,
	@cur_hour_start datetime,
	@cur_lot_no nvarchar(20),
	@cur_sublot_no nvarchar(20),
	@id int,
	@cur_reas int,
	@errorMessage nvarchar(max),
	@loopCnt INT=1,
	@created_at_utc datetime,
	@oal_ent_id int

	--SET REASON CODE AND TO_ENT_ID
	select @cur_reas=ir.reas_cd from item_reas ir where ir.reas_desc='Good Production'	
	select @to_ent_id=@ent_id from ent where description like'Production Supply Area'
	select @rwsCount=count(*) from @jobprod 
	SELECT @id=FLOOR(RAND() * 1000000) 


	DECLARE
  @sublot_table TABLE 
  (
    sublot_ctr int,
	sublot_no nvarchar(20)
	)
	
	if (@rwsCount <= 0)
	BEGIN
		--SELECT @collectionStartTime =
  --     DATEADD(HOUR, 2, @collectionStartTime) 

	 --  SELECT @collectionEndTime =
  --     DATEADD(HOUR, 2, @collectionEndTime) 

	   DECLARE @CST DATETIME;
		SET @CST = CONVERT(DATETIME, @collectionStartTime, 121);

		SELECT @CST= @CST AT TIME ZONE 'UTC' AT TIME ZONE 'Central European Standard Time' 


		DECLARE @FormattedStartUtcTime NVARCHAR(50);
		SET @FormattedStartUtcTime = CONVERT(NVARCHAR, @CST, 120);

		DECLARE @CET DATETIME;
		SET @CET = CONVERT(DATETIME, @collectionEndTime, 121);

		SELECT @CET= @CET AT TIME ZONE 'UTC' AT TIME ZONE 'Central European Standard Time' 


		DECLARE @FormattedEndUtcTime NVARCHAR(50);
		SET @FormattedEndUtcTime = CONVERT(NVARCHAR, @CET, 120);


		--SET @errorMessage=CONCAT(dbo.fn_s_ofi_getLangString(500013,NULL,NULL),dbo.fn_s_ofi_getLangString(1814,NULL,NULL),': ',@oal_ent_name,', ', dbo.fn_s_ofi_getLangString(7783,NULL,NULL),': ',@item_id, 
		--', ', dbo.fn_s_ofi_getLangString(215,NULL,NULL),': ',@consumptionMode,
		--', ', dbo.fn_s_ofi_getLangString(2568,NULL,NULL),' ',@FormattedStartUtcTime, ', ',dbo.fn_s_ofi_getLangString(2570,NULL,NULL),' ',@FormattedEndUtcTime,', ', dbo.fn_s_ofi_getLangString(625,NULL,NULL),': ',@qty,' ', @itemUom)	
		
		SET @errorMessage='@@BinConsFail@@'
		RAISERROR ( @errorMessage,16,1 
					);
		RETURN -1

	END 
	
		declare @PSAgetEnt int
	--select * from @jobprod
	BEGIN TRANSACTION
	--LOOP THROUGH EACH WO FROM ORIGIN LINES TO LOG PRODUCTION AND CONSUME SAME ON REWORK ORDER
	while @loopCnt <= @rwsCount 
	BEGIN		

		SELECT  @cur_wo_id=jb.wo_id,
				@cur_oper_id=jb.oper_id,
				@cur_seq_no=jb.seq_no,
				@cur_qty=jb.split_qty,
				@cur_shift_start=JB.shift_start_local,
				@cur_hour_start=JB.hour_start_local  ,
				@cur_lot_no=jb.def_lot_no,
				@cur_sublot_no=jb.sublot_no,
				@created_at_utc=created_at_utc,
				@oal_ent_id=ent_id

		from  @jobprod jb		
		WHERE id=@loopCnt	
		
		--set update flag for  job_bom
		update job_bom set update_inv=0 where wo_id=@cur_wo_id and oper_id=@cur_oper_id  and bom_pos <0
		
		-- select sublot no for cur wo 
		--INSERT INTO @sublot_table(sublot_ctr,sublot_no)
		--exec sp_S_ofi_Sublot @wo_id=@cur_wo_id,@oper_id=@cur_oper_id,@seq_no=@cur_seq_no

		--select @cur_sublot_no=sublot_no from @sublot_table -- commented as Same sublot number from main item production for by product production

		

		--RECORD PRODUCTION AGAINST ORIGIN WO
		EXEC	[dbo].[sp_I_Item_Prod_AddProdPostExec]
				@session_id = @id,
				@user_id = @USERNAME,
				@ent_id = @oal_ent_id,--segment id of OAL
				@qty_prod = @cur_qty,
				@wo_id = @cur_wo_id,
				@oper_id = @cur_oper_id,
				@seq_no = @cur_seq_no,
				@created_at_utc = @created_at_utc,
				@shift_start_local = @cur_shift_start,
				@hour_start_local = @cur_hour_start,
				@shift_id = NULL,
				@item_id = @item_id,
