-- Updated PROD Data Proc with correct data types
CREATE        PROCEDURE [dbo].[sp_U_ofi_aut_int_buff_InsertJobOutData]
    @wo_id NVARCHAR(40),
	@oper_id NVARCHAR(40),
    @seq_no INT,
	@ent_id INT,
	@job_command INT = 0,
	@job_pos INT,
	@recorded_timestamp DATETIME = NULL,
	@current_timestamp DATETIME,
    @object_name NVARCHAR(80),              
    @interface_type NVARCHAR(15) = 'JOB_OUT',
	@return_code INT = 0 OUTPUT, 
	@row_id_output INT = -1 OUTPUT
AS
BEGIN

	DECLARE @object_name_local NVARCHAR(80)
		,   @interface_type_local NVARCHAR(15)
		,	@current_timestamp_local DATETIME

	SET @object_name_local = @object_name
	SET @interface_type_local = @interface_type
	SET @current_timestamp_local = ISNULL(@current_timestamp,GETUTCDATE())
	SET @recorded_timestamp = COALESCE(@recorded_timestamp,GETUTCDATE())

    DECLARE @Data_local NVARCHAR(4000) = (
        SELECT
            @wo_id AS wo_id,
            @oper_id AS oper_id,			         
			@seq_no AS seq_no,
			@ent_id AS ent_id,
			@job_command AS job_command,
			@job_pos AS job_pos,			
			@recorded_timestamp AS recorded_timestamp
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    EXEC dbo.sp_I_ofi_aut_int_buff 
        @Data = @Data_local,
        @object_name = @object_name_local,
        @interface_type = @interface_type_local,
        @current_timestamp = @current_timestamp_local,
        @Error = @return_code OUTPUT,
		@id = @row_id_output OUTPUT;


	SET @return_code = COALESCE(@return_code,999999)
	SET @row_id_output = COALESCE(@row_id_output,-1)

    RETURN @return_code
END;

