--									@from_oper_id, and @from_seq_no arguments
-- 07/30/2007	AML			3.3.0	DB Changes
-- 11/13/2009  Kishore   4.0   HF# 1432, Part of Date/Timezone Changes
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
DECLARE @transfer_by			NVARCHAR(40)
	,	@transfer_time_local	TDATETIME
	,	@transfer_time_utc		TDATETIME
	,	@tz_temp				INT
	,	@dbg_resp				INT32

IF ( @transfer_by IS NULL ) EXEC sp_S_DB_Status_GetAudTrailUsr @transfer_by OUTPUT, NULL

IF ( @transfer_time_local IS NULL ) SET @transfer_time_local = dbo.fn_TZ_GetLocalDate(NULL)

SET @expiry_date_tz = dbo.fn_TZ_ValidateOffset(@expiry_date_tz)
SET @expiry_date = dbo.fn_TZ_ValidateLocalDate(@expiry_date, @expiry_date_tz)

SET @from_expiry_date_tz = dbo.fn_TZ_ValidateOffset(@from_expiry_date_tz)
SET @from_expiry_date = dbo.fn_TZ_ValidateLocalDate(@from_expiry_date, @from_expiry_date_tz)


  SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

-- TRACE
 exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Item_Transfer', @src_key='on_entry', @date_val1 = @expiry_date, @numeric_val1 = @expiry_date_tz,
					@date_val2 = @from_expiry_date, @numeric_val2 = @from_expiry_date_tz
--TO DO  (@time_zone_bias_value)
SET @tz_temp = -@time_zone_bias_value
EXEC sp_S_GetUtcDate @transfer_time_local, @tz_temp, @transfer_time_utc OUTPUT

SELECT	@transfer_time_utc = dbo.fn_StripMilliSecsFromDateTime( @transfer_time_utc )
	,	@transfer_time_local = dbo.fn_StripMilliSecsFromDateTime( @transfer_time_local )
