	transfer_list_row_id  ,
	comments ,
	transfer_by ,
	--transfer_time	-- 07/30/2007 AML
	transfer_time_utc,
	transfer_time_local
)
VALUES
(
	@wo_id ,
	@oper_id,
	@seq_no ,
	@bom_pos ,
	@to_ent_id ,
	@item_id  ,
	@lot_no ,
	@sublot_no , -- Added 1/12/07 KRF
	@grade_cd ,
	@status_cd ,
	@qty_txd  ,
	@uom_id ,
	@expiry_date ,
	@to_spare1 ,
	@to_spare2 ,
	@to_spare3 ,
	@to_spare4 ,
	@to_spare5 ,
	@to_spare6 ,
	@from_wo_id, -- Added 1/12/07 KRF
	@from_oper_id, -- Added 1/12/07 KRF
	@from_seq_no, -- Added 1/12/07 KRF
	@from_ent_id ,
	@from_item_id ,
	@from_lot_no ,
	@from_sublot_no , -- Added 1/12/07 KRF
	@from_grade_cd ,
	@from_status_cd ,
	@from_qty_txd ,
	@from_uom_id ,
	@from_expiry_date ,
	@from_spare1 ,
	@from_spare2 ,
	@from_spare3 ,
	@from_spare4 ,
	@from_spare5 ,
	@from_spare6 ,
	@qty_txd_erp ,
	@goods_received ,
	@goods_shipped ,
	@transfer_list_row_id  ,
	@comments ,
	@transfer_by ,
	--@transfer_time	-- 07/30/2007 AML
	@transfer_time_utc,
	@transfer_time_local
)

-- Auto Identifer table - return the id of the record created
SELECT @trans_id = SCOPE_IDENTITY()
-- Return timestamp
