-- PARTICULAR PURPOSE.
----------------------------------------------------------------------------------------------------------------------------
-- Date_Modified  Modified_By   Version		Changes
-- 02/13/2003	  VijayRaj     	1.5.2		HD 2392: Enforces that all the jobs with same oper_id share same display_seq
-- 05/15/2003     Sheetal Jain 	1.6.0.0		(HD #2378) Set first job and final job flags in real time as and when the job route is drawn
-- 08/11/2003	  Raghu			1.6.19		(HD# 3269) Should do the first, final job check only if the job does not exist. If exists should throw pk err.
-- 08/13/2003     Sheetal Jain 	1.6.0.19	(HD #3309) Create job bom 0 record based off the flag
-- 01/13/2004     Sheetal Jain 	1.6.0.41	(HD #4284) Creating a Job (not from process) bom_pos zero not created
-- 10/28/2004     Sheetal Jain  2.1.0.6		HD#4873 Initially force job.qty_at_start >= job.qty_reqd
-- 09/15/2005	  Raghu			3.1.0		Part of DB Changes
-- 07/11/2006 	  Raghu			3.1.19		HD# 8434, Strip the milli-seconds by converting the datetime value to a character type and then convert it back to a datetime datatype
-- 07/11/2006 	  Raghu			3.1.19		HD# 7793, Creates jobs from a standard operation; added default values for *_contingent_job columns
-- 05/18/2007	  AML			3.2.0		HD# 8354, Default job_priority to 1; if a NULL value is supplied.
-- 05/18/2007	  AML			3.2.9		HD# 9740, Create BOM flag in SP_I_JOB
-- 10/24/2007	  AML			3.3.4		HD# 8434, Replacing CONVERT(NVARCHAR(19), [date_time_value], 120) with
--											dbo.fn_StripMilliSecsFromDateTime( [date_time_value] ).
-- 01/21/2008	  Raghu		    3.4		    L00073299; Entry of Production Rates is cumbersome,...
-- 09/22/2008	  AML			3.5			L00082756 - Added a try-catch block around the insert job statement to handle "violation of
--											primary key" errors.
-- 11/06/2008	  Diana		    3.5         L00085825(Cloned from HotFix 1130): Use @rework_cd parameter that was added previously to insert in job table
-- 08/20/2009     Sara          4.0         L00075592 Added rework_process_id field; Removed segment_requirement_id and segment_response_id parameters
-- 11/11/2009	  Kishore		4.1			HF# 1432, Part of Date/Timezone Changes
-- 05/10/2012	  Saiteja		4.2			L00120471(Cloned for CRL00119997) - Included must_consume_from_wip for new job so that it should be carried over from item_bom to job_bom.
-- 10/30/2013     Arun			4.6			Modified SP to throw proper error message while inserting the job with est_prod_rate as 0
-- 07/10/2014	  Raghu		    5.0	        Userstory: 348566 - As Jack, I want to prohibit MES client from making changes to work orders assigned to lines that would make them incompatible with the line to which they were assigned so that I do not create a problem for the Web client (Part 2)
-- 10/01/2018	  Raghu		    6.1	        UserStory:1084805 - As Terry, I want the upgrade to modify the document / file stored procedures so that my existing configuration is still valid (Part 1)
-- 10/25/2018	  RWB			6.1         UserStory:1084807 - added a check for a null assoc_file and only added the file type to the file_type table if the assoc_file is not null
-- 02/04/2020     Jim O'Hearn   6.2.0       Removed ntext type in favor of NOTES; see US 1232760
----------------------------------------------------------------------------------------------------------------------------
-- *************************************************************************************************************************
SET NOCOUNT ON
DECLARE
	@reqd_grade_cd INT32_NULL,
	@instruction STRING2000_NULL,
	@max_qty_per_parent_item TFLOAT_NULL,
	@min_qty_per_parent_item TFLOAT_NULL,
	@reqd_start_val TFLOAT_NULL,
	@update_inv LOGICAL,
	@backflush LOGICAL,
	@def_reas_cd INT32_NULL,
	@def_lot_no STRING40_NULL,
	@def_sublot_no STRING40_NULL, --Added 05/18/2007 AML
	@serial_no_source LOGICAL,
	@def_reject_ent_id INT32,
	@def_storage_ent_id INT32_NULL,
	@scaling_factor TFLOAT_NULL,
	@must_consume_from_inv LOGICAL,
	@may_choose_alt_inv_loc LOGICAL,
	@may_create_new_lots LOGICAL,
	@must_consume_before_prod LOGICAL,
	@edited_by STRING80,
	@mod_id VARCHAR(30),
	@err_str NVARCHAR(2000),	-- Added 05/18/2007 AML
	@bom_pos0 INT32,	-- Added 05/18/2007 AML
	@qty_per_parent_item INT32, -- Added 05/18/2007 AML
	@reqd_start_val_is_pct INT32, -- Added 05/18/2007 AML
	@must_consume_from_wip INT32, -- Added 05/18/2007 AML
	@constant_qty INT32, -- Added 05/18/2007 AML
	-- Added 08/02/2007 AML
	@req_finish_time_utc TDATETIME,
	@sched_start_time_utc TDATETIME,
	@latest_start_time_utc TDATETIME,
	@sched_finish_time_utc TDATETIME,
	@act_start_time_utc TDATETIME,
	@act_finish_time_utc TDATETIME,
	@tz_temp INT32,
	@err NVARCHAR(1000),
	--
	@dbg_resp INT32,
	@num_decimals INT32 -- Added for CR L00108888 - RWN 11/19/2010

	 ,@upstream_ent_name	NVARCHAR(80)
	 ,@downstream_ent_name	NVARCHAR(80)
	 ,@err_msg		NVARCHAR(MAX)
	,@line_name		NVARCHAR(80)
	,@ftle		DATETIME
	,@assoc_file_type	NVARCHAR(254)


	  SET @req_finish_time_tz = dbo.fn_TZ_ValidateOffset(@req_finish_time_tz)
	  SET @req_finish_time_local = dbo.fn_TZ_ValidateLocalDate(@req_finish_time_local, @req_finish_time_tz)

      SET @sched_start_time_tz = dbo.fn_TZ_ValidateOffset(@sched_start_time_tz)
      SET @sched_start_time_local = dbo.fn_TZ_ValidateLocalDate(@sched_start_time_local, @sched_start_time_tz)

      SET @latest_start_time_tz = dbo.fn_TZ_ValidateOffset(@latest_start_time_tz)
      SET @latest_start_time_local = dbo.fn_TZ_ValidateLocalDate(@latest_start_time_local, @latest_start_time_tz)

      SET @sched_finish_time_tz = dbo.fn_TZ_ValidateOffset(@sched_finish_time_tz)
      SET @sched_finish_time_local = dbo.fn_TZ_ValidateLocalDate(@sched_finish_time_local, @sched_finish_time_tz)

      SET @act_start_time_tz = dbo.fn_TZ_ValidateOffset(@act_start_time_tz)
      SET @act_start_time_local = dbo.fn_TZ_ValidateLocalDate(@act_start_time_local, @act_start_time_tz)

      SET @act_finish_time_tz = dbo.fn_TZ_ValidateOffset(@act_finish_time_tz)
      SET @act_finish_time_local = dbo.fn_TZ_ValidateLocalDate(@act_finish_time_local, @act_finish_time_tz)

      SET @time_zone_bias_value = dbo.fn_TZ_ValidateOffset(@time_zone_bias_value)

	 -- TRACE
	 exec @dbg_resp = sp_DBG_LogTrace @src_sp='sp_I_Job_1', @src_key='on_entry', @date_val1 = @req_finish_time_local, @numeric_val1 = @req_finish_time_tz,
					@date_val2 = @sched_start_time_local, @numeric_val2 = @sched_start_time_tz, @date_val3 = @latest_start_time_local, @numeric_val3 = @latest_start_time_tz,
					@date_val4 = @sched_finish_time_local, @numeric_val4 = @sched_finish_time_tz, @date_val5 = @act_start_time_local, @numeric_val5 = @act_start_time_tz,
					@date_val6 = @act_finish_time_local, @numeric_val6 = @act_finish_time_tz
	 if ( @dbg_resp = 1 ) RETURN

	SET @tz_temp = -@req_finish_time_tz
	EXEC sp_S_GetUtcDate @req_finish_time_local, @tz_temp, @req_finish_time_utc OUTPUT

	SET @tz_temp = -@sched_start_time_tz
	EXEC sp_S_GetUtcDate @sched_start_time_local, @tz_temp, @sched_start_time_utc OUTPUT

	SET @tz_temp = -@latest_start_time_tz
	EXEC sp_S_GetUtcDate @latest_start_time_local, @tz_temp, @latest_start_time_utc OUTPUT

	SET @tz_temp = -@sched_finish_time_tz
	EXEC sp_S_GetUtcDate @sched_finish_time_local, @tz_temp, @sched_finish_time_utc OUTPUT

	SET @tz_temp = -@act_start_time_tz
	EXEC sp_S_GetUtcDate @act_start_time_local, @tz_temp, @act_start_time_utc OUTPUT

	SET @tz_temp = -@act_finish_time_tz
	EXEC sp_S_GetUtcDate @act_finish_time_local, @tz_temp, @act_finish_time_utc OUTPUT

   SET @bom_pos0 = 0
   SET @qty_per_parent_item = 1
   SET @reqd_start_val_is_pct = 1
   SET @must_consume_from_wip = 0
   SET @constant_qty = 0

	SET @create_job_bom = coalesce(@create_job_bom,1)

BEGIN

  --Check if start qty is atleast equal to the reqd qty
  IF @qty_reqd > ISNULL(@qty_at_start, 0)
  BEGIN
    RAISERROR('Starting quantity must at least be equal to the required quantity.{4100}', 16, 1)
    RETURN
  END
  SELECT @state_cd = COALESCE(@state_cd, 1), @qty_prod = COALESCE(@qty_prod, 0)
	,@qty_rejected = COALESCE(@qty_rejected, 0), @batch_size = COALESCE(@batch_size, 1), @first_job = COALESCE(@first_job, 0)
	,@final_job = COALESCE(@final_job, 0), @sched_pinned = COALESCE(@sched_pinned, 0), @check_inv = COALESCE(@check_inv, 0)
	,@concurrent_link = COALESCE(@concurrent_link, 0), @rework = COALESCE(@rework, 0), @must_consume_before_prod = COALESCE(@must_consume_before_prod, 0)
	,@parent_contingent_job = COALESCE(@parent_contingent_job, 0), @child_contingent_job = COALESCE(@child_contingent_job, 0)
	,@job_priority = COALESCE(@job_priority, 1) -- Added 05/18/2007 AML
	,@prod_uom = COALESCE(@prod_uom, 0)

/*  SET @time_zone_bias_value = ISNULL(@time_zone_bias_value, 0)
  IF @state_cd IS null SET @state_cd = 1
  IF @qty_prod IS null SET @qty_prod = 0
  IF @qty_rejected IS null SET @qty_rejected = 0  IF @batch_size IS null SET @batch_size = 1
  IF @first_job IS null SET @first_job = 0
  IF @final_job IS null SET @final_job = 0
  IF @sched_pinned IS null SET @sched_pinned = 0
  IF @check_inv IS null SET @check_inv = 0
  IF @concurrent_link IS null SET @concurrent_link = 0
  IF @rework IS null SET @rework = 0
  IF @must_consume_before_prod IS NULL SET @must_consume_before_prod = 0*/

  --VRB This is to validate for First Job and Final Job. If a given Work Order has only one Job
  -- then it can be both the start job and final job. But if there are more than one job, it is not true
  DECLARE @JobCount int

  --Added by Raghu 08/11/2003. The below "IF NOT EXISTS ..." should do the check only if the job does not exist and should throw the error if pkey fails.
  IF NOT EXISTS (SELECT TOP 1 'X' FROM job WITH (NOLOCK) WHERE wo_id = @wo_id AND oper_id = @oper_id AND seq_no = @seq_no)
  BEGIN
    SELECT @JobCount = COUNT(*) FROM job WITH (NOLOCK) WHERE wo_id=@wo_id
    IF @JobCount>0
    BEGIN
      IF @first_job = 1 and  @final_job = 1
      BEGIN
        --RAISERROR('Cannot be First and Final Job when more than one job exists', 16, 1)
        RAISERROR('Cannot be First and Final Job when more than one job exists.{3200}', 16, 1)
	RETURN -1
      END
    END
    SET @first_job = 1
    SET @final_job = 1
  END

  EXEC sp_S_DB_Status_GetAudTrailUsr @edited_by OUTPUT, NULL
  --  IF @edit_time IS NULL
--  SET @edit_time = CONVERT(NVARCHAR(19), GETUTCDATE(), 120)
  SET @edit_time = dbo.fn_StripMilliSecsFromDateTime( GETUTCDATE() )

  IF @deviation_above IS NULL SELECT @deviation_above = attr_value FROM system_attr WITH (NOLOCK) WHERE attr_id = 103
  IF @deviation_below IS NULL SELECT @deviation_below = attr_value FROM system_attr WITH (NOLOCK) WHERE attr_id = 104

  /*
	SELECT	@req_finish_time =  DATEADD(mi, -@time_zone_bias_value, @req_finish_time),
			@sched_start_time =  DATEADD(mi, -@time_zone_bias_value, @sched_start_time),
			@latest_start_time =  DATEADD(mi, -@time_zone_bias_value, @latest_start_time),
			@sched_finish_time =  DATEADD(mi, -@time_zone_bias_value, @sched_finish_time),
			@act_start_time =  DATEADD(mi, -@time_zone_bias_value, @act_start_time),
