END TRY
BEGIN CATCH
	IF ( ERROR_NUMBER() = 2627 OR ERROR_NUMBER() = 3930  /* OR ERROR_NUMBER() = 547 OR ERROR_NUMBER() = 1205*/ ) BEGIN
		SET @err = 'This job failed to create.  Please re-submit.{6015}' + cast(ERROR_NUMBER() as nvarchar(20))
	END ELSE BEGIN
		SET @err = ERROR_MESSAGE() + cast(ERROR_NUMBER() as nvarchar(20))
	END
	RAISERROR( @err, 16, 1 )
END CATCH

EXEC sp_U_Wo_ValJobRteWithLineRte @wo_id = @wo_id, @upstream_ent_name = @upstream_ent_name OUTPUT, @downstream_ent_name	= @downstream_ent_name OUTPUT

IF (@upstream_ent_name IS NOT NULL OR @downstream_ent_name IS NOT NULL) BEGIN
	SELECT @line_name = l.line_name
	FROM line l WITH (NOLOCK)
	INNER JOIN wo wo WITH (NOLOCK) ON l.line_id = wo.target_sched_line_id
	WHERE wo.wo_id = @wo_id

	SET @err_msg = 'The work order: %1 is currently assigned to line: %2. The new job cannot be added, because the sequence of entities (upstream entity: %3, downstream entity: %4) in the job route do not match with the sequence of entities in the line route.{7919},' + @wo_id + ',' + @line_name + ',' + COALESCE(@upstream_ent_name, '') + ',' + COALESCE(@downstream_ent_name, '')
	RAISERROR(@err_msg, 16, 1)
	RETURN
END


  /* Commented Out 05/18/2007 AML
  --Create job bom 0 if flag is true
  IF @create_job_bom = 1
  BEGIN
    --Get the item data from the preferred bom version
    SELECT @reqd_grade_cd = i.reqd_grade_cd, @instruction = i.instruction, @max_qty_per_parent_item = i.max_qty_per_parent_item,
           @min_qty_per_parent_item = i.min_qty_per_parent_item, @update_inv = i.update_inv, @backflush = i.backflush,
           @def_reas_cd = i.def_reas_cd, @def_lot_no = i.def_lot_no, @def_storage_ent_id = i.def_storage_ent_id,
           @def_reject_ent_id = i.def_reject_ent_id, @scaling_factor = i.scaling_factor, @must_consume_from_inv = i.must_consume_from_inv,
           @may_choose_alt_inv_loc = i.may_choose_alt_inv_loc, @may_create_new_lots = i.may_create_new_lots,
           @must_consume_before_prod = i.must_consume_before_prod
      FROM bom_item i
      INNER JOIN bom_ver v ON i.parent_item_id = v.parent_item_id AND i.ver_id = v.ver_id
        WHERE i.parent_item_id = @item_id AND v.preferred_ver = 1

    --Get the reqd start val from system attr as percent
    SELECT @reqd_start_val = attr_value/100.0 FROM system_attr WHERE attr_id = 203
    --Insert into job bom
    EXECUTE sp_I_Job_Bom @wo_id, @oper_id, @seq_no, 0, @item_id, @reqd_grade_cd, @instruction, 1, @max_qty_per_parent_item,
                         @min_qty_per_parent_item, @reqd_start_val, 1, @update_inv, @backflush, @def_reas_cd, @def_lot_no,
                         @def_storage_ent_id, @def_reject_ent_id, @scaling_factor, @must_consume_from_inv, @may_choose_alt_inv_loc,
                         @may_create_new_lots, 1, @must_consume_before_prod, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, @last_edit_comment, @mod_id OUT
  END  --End of @create_job_bom = 1
  */

	--Added 05/18/2007 AML
	--Create job bom 0 if flag is true
    --Get the item data from the preferred bom version
	IF (@create_job_bom = 1) BEGIN
		--Find a preferred version of this bom_item.
		SELECT	@reqd_grade_cd = bi.reqd_grade_cd
			,	@instruction = bi.instruction
			,	@max_qty_per_parent_item = bi.max_qty_per_parent_item
			,	@min_qty_per_parent_item = bi.min_qty_per_parent_item
			,	@update_inv = bi.update_inv
			,	@backflush = bi.backflush
			,	@def_reas_cd = bi.def_reas_cd
			,	@def_lot_no = bi.def_lot_no
			,	@def_sublot_no = bi.def_sublot_no
			,	@serial_no_source = bi.serial_no_source
			,	@def_storage_ent_id = bi.def_storage_ent_id
			,	@def_reject_ent_id = bi.def_reject_ent_id
			,	@scaling_factor = bi.scaling_factor
			,	@must_consume_from_inv = bi.must_consume_from_inv
			,	@must_consume_from_wip = bi.must_consume_from_wip --Added for CR L00120471(Cloned for CRL00119997)
			,	@may_choose_alt_inv_loc = bi.may_choose_alt_inv_loc
			,	@may_create_new_lots = bi.may_create_new_lots
			,	@must_consume_before_prod = bi.must_consume_before_prod
		FROM bom_ver bv WITH (NOLOCK)
			INNER JOIN bom_item bi WITH (NOLOCK) ON bi.parent_item_id = bv.parent_item_id AND bi.ver_id = bv.ver_id
        WHERE bi.parent_item_id = @item_id AND bv.preferred_ver = 1
			AND bi.bom_pos = 0;

		IF (@@ROWCOUNT < 1) BEGIN
			 --Either there is no preferred version for this bom_item; or the bom_item itself does not exist.
             --Verify at least we can identify one version whether preferred or not to default job_bom values.
             SELECT	@reqd_grade_cd = bi.reqd_grade_cd
				,	@instruction = bi.instruction
				,	@max_qty_per_parent_item = bi.max_qty_per_parent_item
				,	@min_qty_per_parent_item = bi.min_qty_per_parent_item
				,	@update_inv = bi.update_inv
				,	@backflush = bi.backflush
				,	@def_reas_cd = bi.def_reas_cd
				,	@def_lot_no = bi.def_lot_no
				,	@def_sublot_no = bi.def_sublot_no
				,	@serial_no_source = bi.serial_no_source
				,	@def_storage_ent_id = bi.def_storage_ent_id
				,	@def_reject_ent_id = bi.def_reject_ent_id
				,	@scaling_factor = bi.scaling_factor
				,	@must_consume_from_inv = bi.must_consume_from_inv
				,	@must_consume_from_wip = bi.must_consume_from_wip --Added for CR L00120471(Cloned for CRL00119997)
				,	@may_choose_alt_inv_loc = bi.may_choose_alt_inv_loc
				,	@may_create_new_lots = bi.may_create_new_lots
				,	@must_consume_before_prod = bi.must_consume_before_prod
             FROM bom_ver bv WITH (NOLOCK)
				INNER JOIN bom_item bi WITH (NOLOCK) ON bi.parent_item_id = bv.parent_item_id AND bi.ver_id = bv.ver_id
             WHERE bi.parent_item_id = @item_id AND bv.preferred_ver = 0
				AND bi.bom_pos = 0;

			IF (@@ROWCOUNT < 1) BEGIN
				--There are no non-preferred versions either; meaning the bom item itself does not exist.
				--Create a new job bom record using job_bom defaults.
				--Get the reqd start val from system attr as percent
				SELECT @reqd_start_val = (attr_value / 100.0) FROM system_attr WITH (NOLOCK) WHERE attr_id = 203

				EXEC sp_I_Job_Bom @wo_id, @oper_id, @seq_no, @bom_pos0, @item_id, NULL, NULL, 1,
                			       NULL, NULL, @reqd_start_val, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 1,  0, 1, 1, 0, 0,
                			       0, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, @last_edit_comment, @mod_id OUTPUT
				RETURN

			END

			IF (@@ROWCOUNT > 1) BEGIN
				--There are a couple of bom versions; but none of them were preferred.
                --raise an error to the caller indicating him to set a preferred version.
				RAISERROR('Not all parent items have preferred BOM versions.{3362}', 16, 1 )
				RETURN -1
			END
		END

		IF (@@ROWCOUNT > 1) BEGIN
			--There are too many preferred versions; and we are not sure which preferred version to pick?
			--raise an error to the caller so that the caller has an option to either fix the bom_version and
			--create the job again; or the caller can uncheck the create_job_bom flag to not to create the job_bom 0 automatically.
			RAISERROR( 'There are more than one preferred version specified for this item: %s.{5462}', 16, 1, @item_id )
			RETURN -1
		END

		--Get the reqd start val from system attr as percent
		SELECT @reqd_start_val = (attr_value / 100.0) FROM system_attr WITH (NOLOCK) WHERE attr_id = 203

		--Create a new job bom record using bom_item defaults
        EXEC sp_I_Job_Bom @wo_id, @oper_id, @seq_no, @bom_pos0, @item_id, @reqd_grade_cd, @instruction, @qty_per_parent_item
						, @max_qty_per_parent_item, @min_qty_per_parent_item, @reqd_start_val, @reqd_start_val_is_pct
						, @update_inv, @backflush, @def_reas_cd, @def_lot_no, @def_sublot_no, @def_storage_ent_id
						, @def_reject_ent_id, @scaling_factor, @must_consume_from_inv, @may_choose_alt_inv_loc
						, @may_create_new_lots, @must_consume_from_wip, @must_consume_before_prod, @constant_qty
						, NULL, NULL, NULL, @serial_no_source, NULL, NULL, NULL, NULL, @last_edit_comment, @mod_id OUT
	END

	UPDATE job WITH (ROWLOCK) set display_seq = @display_seq where wo_id = @wo_id and oper_id = @oper_id --VRB
END

