@value46          nvarchar(80) ,
@value47          nvarchar(80) ,
@value48          nvarchar(80) ,
@tz_temp			INT32,
@err_msg		  STRING254

BEGIN

	SET @time_zone_bias_value = COALESCE(@time_zone_bias_value, 0)
	SET @tz_temp = -@time_zone_bias_value

    --Verify whether an EPA is supplied.
    IF (@extended_attrs IS NULL) BEGIN
		RAISERROR('The %1 must be supplied %2{4677}, extended attributes,to record PEM data.', 16,1)
		RETURN -1
    END

	IF (@event_time_local IS NULL) BEGIN
        --No local time was supplied by the client.  Default to the current date and time.
        SET @event_time_utc = dbo.fn_StripMilliSecsFromDateTime(GETUTCDATE())
        EXEC sp_TZ_GetDateInfo NULL, @event_time_utc OUTPUT, @event_time_local OUTPUT, @time_zone_bias_value OUTPUT

	END
    ELSE
	BEGIN
        --The client has supplied the date and time. Obtain a corresponding UTC time from the supplied local time.
        EXEC sp_TZ_GetDateInfo NULL, @event_time_utc OUTPUT, @event_time_local OUTPUT, @time_zone_bias_value OUTPUT
    END

	--Get the data log group ID using the supplied data log description.
    SET @grp_id = dbo.fn_GetDataLogGroupID(@grp_desc)

    --Verify whether this entity exists in the database or not; if not, raise an error to the caller.
    IF (@grp_id IS NULL) BEGIN
        --raise an error if the entity does not exist in the database.
        RAISERROR('The specified %1 does not exist in the database.{3566}',16,1, @grp_desc)
		RETURN -1
    END
	--Get the shift details related to this transaction.
    SELECT @shift_start_utc = MIN(sh.shift_start_utc), @shift_start_local= MIN(sh.shift_start_local), @shift_id =MIN(sh.shift_id)
		FROM shift_history sh WITH (NOLOCK)
        WHERE sh.ent_id = @ent_id
          --shift start time must be earlier or equal to the the supplied event time
          AND sh.shift_start_utc <= @event_time_utc
          --shift end time must be later than the supplied event time or it could be null; representing the current shift.
          AND (sh.shift_end_utc >= @event_time_utc OR sh.shift_end_utc IS NULL)

	SELECT @shift_start_utc = COALESCE(@shift_start_utc, @event_time_utc)
			, @shift_start_local = COALESCE(@shift_start_local, @event_time_local)
			, @shift_id = COALESCE(@shift_id, 0)

	EXEC sp_S_DB_Status_GetAudTrailUsr @last_edit_by OUTPUT, NULL

	--Log all the attribute data into the corresponding value column in the data_log_48 table.
	EXEC sp_xml_preparedocument @doc_handle OUTPUT, @extended_attrs

	DECLARE @value_index	INT32
	DECLARE pemepa_cursor CURSOR LOCAL FOR
		SELECT	name, value ,data_type,dlv.value_index FROM OPENXML (@doc_handle, '/ea/attribute', 1)
			WITH (	name NVARCHAR(256),
					value NVARCHAR(256),
					data_type NVARCHAR(256))ea RIGHT OUTER JOIN data_log_value dlv
					ON dlv.value_name = ea.name
					WHERE dlv.value_name = ea.name AND (dlv.grp_id = @grp_id OR dlv.value_index IS NULL)

	OPEN pemepa_cursor
	WHILE (1=1) BEGIN
		FETCH NEXT FROM pemepa_cursor INTO @name, @value,@datatype,@value_index
		IF (@@FETCH_STATUS <> 0) BREAK

		IF(@value_index = 1) SET @value1 = @value
		ELSE IF (@value_index = 2) SET @value2 = @value
		ELSE IF (@value_index = 3) SET @value3 = @value
		ELSE IF (@value_index = 4) SET @value4 = @value
		ELSE IF (@value_index = 5) SET @value5 = @value
		ELSE IF (@value_index = 6) SET @value6 = @value
		ELSE IF (@value_index = 7) SET @value7 = @value
		ELSE IF (@value_index = 8) SET @value8 = @value
		ELSE IF (@value_index = 9) SET @value9 = @value
		ELSE IF (@value_index = 10) SET @value10 = @value
		ELSE IF (@value_index = 11) SET @value11 = @value
		ELSE IF (@value_index = 12) SET @value12 = @value
		ELSE IF (@value_index = 13) SET @value13 = @value
		ELSE IF (@value_index = 14) SET @value14 = @value
		ELSE IF (@value_index = 15) SET @value15 = @value
		ELSE IF (@value_index = 16) SET @value16 = @value
		ELSE IF (@value_index = 17) SET @value17 = @value
		ELSE IF (@value_index = 18) SET @value18 = @value
		ELSE IF (@value_index = 19) SET @value19 = @value
		ELSE IF (@value_index = 20) SET @value20 = @value
		ELSE IF (@value_index = 21) SET @value21 = @value
		ELSE IF (@value_index = 22) SET @value22 = @value
		ELSE IF (@value_index = 23) SET @value23 = @value
		ELSE IF (@value_index = 24) SET @value24 = @value
		ELSE IF (@value_index = 25) SET @value25 = @value
		ELSE IF (@value_index = 26) SET @value26 = @value
		ELSE IF (@value_index = 27) SET @value27 = @value
		ELSE IF (@value_index = 28) SET @value28 = @value
		ELSE IF (@value_index = 29) SET @value29 = @value
		ELSE IF (@value_index = 30) SET @value30 = @value
		ELSE IF (@value_index = 31) SET @value31 = @value
		ELSE IF (@value_index = 32) SET @value32 = @value
		ELSE IF (@value_index = 33) SET @value33 = @value
		ELSE IF (@value_index = 34) SET @value34 = @value
		ELSE IF (@value_index = 35) SET @value35 = @value
		ELSE IF (@value_index = 36) SET @value36 = @value
		ELSE IF (@value_index = 37) SET @value37 = @value
		ELSE IF (@value_index = 38) SET @value38 = @value
		ELSE IF (@value_index = 39) SET @value39 = @value
		ELSE IF (@value_index = 40) SET @value40 = @value
		ELSE IF (@value_index = 41) SET @value41 = @value
		ELSE IF (@value_index = 42) SET @value42 = @value
		ELSE IF (@value_index = 43) SET @value43 = @value
		ELSE IF (@value_index = 44) SET @value44 = @value
		ELSE IF (@value_index = 45) SET @value45 = @value
		ELSE IF (@value_index = 46) SET @value46 = @value
		ELSE IF (@value_index = 47) SET @value47 = @value
		ELSE IF (@value_index = 48) SET @value48 = @value
		ELSE BEGIN
			SET @err_msg = 'The specified %1 does not exist in the database.{3566},' + 'EPA Name:' + @name + ' for the data log group:' + @grp_desc
			RAISERROR(@err_msg, 16, 1)
			RETURN
		END
	END
	CLOSE pemepa_cursor
	DEALLOCATE pemepa_cursor
	EXEC sp_xml_removedocument @doc_handle

    INSERT INTO data_log_48 (grp_id, sample_time_utc, sample_time_local, wo_id, oper_id, seq_no,
        step_no, item_id, lot_no, sublot_no,
        shift_start_utc, shift_start_local, shift_id, ent_id,
        genealogy_id, segment_requirement_id, segment_response_id,
        value1, value2, value3, value4, value5,
        value6, value7, value8, value9, value10,
        value11, value12, value13, value14, value15,
        value16, value17, value18, value19, value20,
        value21, value22, value23, value24, value25,
        value26, value27, value28, value29, value30,
        value31, value32, value33, value34, value35,
        value36, value37, value38, value39, value40,
        value41, value42, value43, value44, value45,
        value46, value47, value48,
        last_edit_by, last_edit_at)
	SELECT 	@grp_id, @event_time_utc, @event_time_local,
        @wo_id, @oper_id,@seq_no,
        NULL, @item_id, @lot_no, @sublot_no,
        @shift_start_utc, @shift_start_local, @shift_id, @ent_id,
        @genealogy_id, @segment_requirement_id, @segment_response_id,
        @value1, @value2, @value3, @value4, @value5,
        @value6, @value7, @value8,@value9, @value10,
        @value11, @value12, @value13, @value14, @value15,
        @value16, @value17, @value18, @value19, @value20,
        @value21, @value22, @value23, @value24, @value25,
        @value26, @value27, @value28, @value29, @value30,
        @value31, @value32, @value33, @value34, @value35,
        @value36, @value37, @value38, @value39, @value40,
        @value41, @value42, @value43, @value44, @value45,
        @value46, @value47, @value48,
        @last_edit_by,dbo.fn_StripMilliSecsFromDateTime(GETUTCDATE())

	SET @row_id = SCOPE_IDENTITY()

END

/*
-- ===========================================================================================
-- Name:  [sp_U_ofi_aut_int_buff_MarkTimeout]
-- Description: Used to insert PROD interface data into the buffer table
--
-- Usage: For AUT interface to insert the values from IDE PROD object 
-- ===========================================================================================
-- Version Author  	Date (yyyy-MM-dd) 	Change description
-- 0.01.00 JSC   	2025-04-15   		CR512: Initial version.
-- ===========================================================================================*/
create     PROCEDURE [dbo].[sp_U_ofi_aut_int_buff_MarkTimeout_bck21_8_25]
	@ObjectName NVARCHAR(60),
	@InterfaceType NVARCHAR(15) = 'PROD',
	@NewStatus INT = 13, -- 13 means timeout error
	@rownumber_output INT = -1 OUTPUT -- row ID -1 means not to be marked
AS
BEGIN
	SET NOCOUNT ON;

	UPDATE dbo.ofi_aut_interface_buffer
    SET Comment = ISNULL(Comment,'Processing failed and timeout'),
        Status = @NewStatus,
        StatusTimestamp = GETUTCDATE()
    WHERE ObjectName = @ObjectName
			AND InterfaceType = @InterfaceType
			AND Status =  1
			AND StatusTimestamp < DATEADD(minute,-15,GETUTCDATE());

	SET @rownumber_output = @@ROWCOUNT;

END;
